      transform: scale(1.15);
      border-color: rgba(255,255,255,0.3);
      background: rgba(255,255,255,0.05);
    }

    .input-field {
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: 12px;
      padding: 16px;
