 */
"use client";

import { motion, useInView, useReducedMotion } from "motion/react";
import { Fragment, useRef } from "react";

type BlurTextProps = {
  text: string;
  /** Seconds before the first word starts. */
  delay?: number;
  /** Seconds between one word and the next. */
  stagger?: number;
  /** "up" makes words rise into place, "down" makes them drop in. */
  direction?: "up" | "down";
  /** Play only the first time the text enters the viewport. */
  once?: boolean;
  className?: string;
};

const EASE = [0.22, 1, 0.36, 1] as const;

/** Words that sharpen out of a blur, one after another, when the text scrolls into view. */
export function BlurText({
  text,
  delay = 0,
  stagger = 0.08,
  direction = "up",
  once = true,
  className = "",
}: BlurTextProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once, amount: 0.3 });
  const reduce = useReducedMotion();
  const words = text.split(/\s+/).filter(Boolean);

  const hidden = { opacity: 0, filter: "blur(12px)", y: direction === "up" ? "0.45em" : "-0.45em" };
  const shown = { opacity: 1, filter: "blur(0px)", y: "0em" };

  return (
    <span ref={ref} className={className}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {words.map((word, i) => (
          <Fragment key={i}>
            {i > 0 ? " " : null}
            <motion.span
              className="inline-block will-change-[filter,transform]"
              initial={reduce ? false : hidden}
              animate={reduce || inView ? shown : hidden}
              transition={
                reduce
                  ? { duration: 0 }
                  : inView
                    ? { duration: 0.8, delay: delay + i * stagger, ease: EASE }
                    : { duration: 0.3, ease: EASE }
              }
            >
              {word}
            </motion.span>
          </Fragment>
        ))}
      </span>
    </span>
  );
}

/**
 * Mekai UI · Click Spark
 * MIT License · Copyright (c) 2026 Mekai Games
 * https://ui.mekaigames.com/components/click-spark
 * https://github.com/mekai-ui/mekai-ui
 */
"use client";

import { motion, useReducedMotion } from "motion/react";
import { useRef, useState, type MouseEvent, type ReactNode } from "react";

type ClickSparkProps = {
  children: ReactNode;
  /** Color of the sparks. */
  color?: string;
  /** Number of spark lines in each burst. */
  count?: number;
  /** How far the sparks travel from the click, in pixels. */
  radius?: number;
  /** Length of one burst, in seconds. */
  duration?: number;
  className?: string;
};

type Burst = { id: number; x: number; y: number };

/** A wrapper that throws short spark lines out of every click inside it. */
export function ClickSpark({
  children,
  color = "#ffc24a",
  count = 8,
  radius = 28,
  duration = 0.45,
  className = "",
}: ClickSparkProps) {
  const reduce = useReducedMotion();
  const [bursts, setBursts] = useState<Burst[]>([]);
  const nextId = useRef(0);

  function spark(e: MouseEvent<HTMLDivElement>) {
    const box = e.currentTarget.getBoundingClientRect();
    let x = e.clientX;
    let y = e.clientY;
    // A keyboard press has no pointer position: start from the center of the element it activated.
    if (e.detail === 0 && e.target instanceof Element) {
      const target = e.target.getBoundingClientRect();
      x = target.left + target.width / 2;
      y = target.top + target.height / 2;
    }
    const id = nextId.current++;
    setBursts((list) => [...list.slice(-5), { id, x: x - box.left, y: y - box.top }]);
  }

  function remove(id: number) {
    setBursts((list) => list.filter((b) => b.id !== id));
  }

  return (
    <div className={`relative ${className}`} onClick={spark}>
      {children}
      <div aria-hidden="true" className="pointer-events-none absolute inset-0">
        {bursts.map((b) => (
          <SparkBurst
            key={b.id}
            x={b.x}
            y={b.y}
            color={color}
            count={count}
            radius={radius}
            duration={duration}
            reduce={Boolean(reduce)}
            onDone={() => remove(b.id)}
          />
        ))}
      </div>
    </div>
  );
}

type SparkBurstProps = {
  x: number;
  y: number;
  color: string;
  count: number;
  radius: number;
  duration: number;
  reduce: boolean;
  onDone: () => void;
};

function SparkBurst({ x, y, color, count, radius, duration, reduce, onDone }: SparkBurstProps) {
  if (reduce) {
    // No flying lines: a small dot that fades in place.
    return (
      <motion.span
        className="absolute size-2 rounded-full"
        style={{ left: x - 4, top: y - 4, backgroundColor: color }}
        initial={{ opacity: 0.9 }}
        animate={{ opacity: 0 }}
        transition={{ duration: 0.35 }}
        onAnimationComplete={onDone}
      />
    );
  }

  const lines = Math.max(1, Math.round(count));
  const length = radius * 0.5;

  return (
    <>
      {Array.from({ length: lines }, (_, i) => (
        // The outer span sets the direction; the line then travels along its own x axis.
        <span
          key={i}
          className="absolute size-0"
          style={{ left: x, top: y, transform: `rotate(${(i / lines) * 360}deg)` }}
        >
          <motion.span
            className="absolute left-0 top-[-1px] block h-0.5 origin-left rounded-full"
            style={{ width: length, backgroundColor: color }}
            initial={{ x: radius * 0.1, scaleX: 1, opacity: 1 }}
            animate={{ x: radius, scaleX: 0, opacity: 0.4 }}
            transition={{ duration, ease: [0.16, 0.8, 0.3, 1] }}
            onAnimationComplete={i === 0 ? onDone : undefined}
          />
        </span>
      ))}
    </>
  );
}

/**
 * Mekai UI · Folder
