 * https://ui.mekaigames.com/components/folder
 * https://github.com/mekai-ui/mekai-ui
 */
"use client";

import { motion, useMotionValue, useReducedMotion, useSpring, useTransform, type MotionValue, type Transition } from "motion/react";
import { useState, type PointerEvent, type ReactNode } from "react";

type FolderProps = {
  /** Folder color. The back panel and tab use a darker shade of it. */
  color?: string;
  /** Scale factor. 1 is 120 × 96 pixels. */
  size?: number;
  /** Up to three papers. Keep them non-interactive: they sit inside a button. */
  items?: ReactNode[];
  /** Open state, for controlled use. */
  open?: boolean;
  defaultOpen?: boolean;
  /** Called when the folder is clicked, with the requested state. */
  onOpenChange?: (open: boolean) => void;
  /** Peek inside while the pointer is over the folder. */
  openOnHover?: boolean;
  /** Accessible name of the button. */
  label?: string;
  className?: string;
};

const W = 120;
const H = 96;

/** A folder that opens on hover or click, fanning its papers out; the papers lean toward the pointer. */
export function Folder({
  color = "#ff784f",
  size = 1,
  items,
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  openOnHover = true,
  label = "Folder",
  className = "",
}: FolderProps) {
  const reduce = useReducedMotion() ?? false;
  const [pinned, setPinned] = useState(defaultOpen);
  const [hovered, setHovered] = useState(false);
  // After a click closes the folder, ignore hover until the pointer leaves.
  const [quiet, setQuiet] = useState(false);
  const open = controlled ?? (pinned || (openOnHover && hovered && !quiet));
  const papers = (items ?? [null, null, null]).slice(0, 3);
  const dark = `color-mix(in srgb, ${color} 72%, black)`;

  const px = useMotionValue(0);
  const py = useMotionValue(0);
  const sx = useSpring(px, { stiffness: 220, damping: 18 });
  const sy = useSpring(py, { stiffness: 220, damping: 18 });

  function onClick() {
    const next = !open;
    onOpenChange?.(next);
    if (controlled !== undefined) return;
    setPinned(next);
    if (!next) setQuiet(true);
  }

  function onPointerMove(e: PointerEvent<HTMLButtonElement>) {
    if (reduce || e.pointerType !== "mouse") return;
    const rect = e.currentTarget.getBoundingClientRect();
    px.set(((e.clientX - (rect.left + rect.width / 2)) / (rect.width / 2)) * 7);
    py.set(((e.clientY - (rect.top + rect.height / 2)) / (rect.height / 2)) * 5);
  }

  function onPointerLeave() {
    setHovered(false);
    setQuiet(false);
    px.set(0);
    py.set(0);
  }

  const spring: Transition = reduce ? { duration: 0 } : { type: "spring", stiffness: 320, damping: 22 };

  return (
    <button
      type="button"
      aria-label={label}
      aria-expanded={open}
      onClick={onClick}
      onPointerEnter={(e) => e.pointerType === "mouse" && setHovered(true)}
      onPointerLeave={onPointerLeave}
      onPointerMove={onPointerMove}
      className={`relative inline-block shrink-0 rounded-2xl ${className}`}
      style={{ width: W * size, height: H * size }}
    >
      <span
        aria-hidden="true"
        className="absolute left-0 top-0 block"
        style={{ width: W, height: H, transform: `scale(${size})`, transformOrigin: "0 0", perspective: 600 }}
      >
        {/* Back panel and tab */}
        <span className="absolute left-0 top-0 h-5 w-[46px] rounded-t-[10px]" style={{ backgroundColor: dark }} />
        <span className="absolute inset-x-0 bottom-0 top-3 rounded-[14px] rounded-tl-none" style={{ backgroundColor: dark }} />

        {/* Papers */}
        {papers.map((content, i) => (
          <Paper key={i} index={i} total={papers.length} open={open} spring={spring} sx={sx} sy={sy}>
            {content}
          </Paper>
        ))}

        {/* Front flap */}
        <motion.span
          className="absolute inset-x-0 bottom-0 block h-[78%] rounded-[14px]"
          style={{
            zIndex: 10,
            transformOrigin: "50% 100%",
            backgroundColor: color,
            backgroundImage: "linear-gradient(to bottom, rgb(255 255 255 / 0.18), transparent 45%)",
            boxShadow: "0 -1px 0 rgb(255 255 255 / 0.25) inset",
          }}
          initial={false}
          animate={open ? { rotateX: -42, skewX: -4 } : { rotateX: 0, skewX: 0 }}
          transition={spring}
        />
      </span>
    </button>
  );
}

function Paper({
  index,
  total,
  open,
  spring,
  sx,
  sy,
  children,
}: {
  index: number;
  total: number;
  open: boolean;
  spring: Transition;
  sx: MotionValue<number>;
  sy: MotionValue<number>;
  children: ReactNode;
}) {
  // Spread the papers around the middle: -1, 0, 1 for three.
  const k = index - (total - 1) / 2;
  const depth = 0.6 + index * 0.25;
  const x = useTransform(sx, (v) => v * depth);
  const y = useTransform(sy, (v) => v * depth);
  return (
    <motion.span
      className="absolute bottom-2 left-1/2 block h-16 w-[84px] -translate-x-1/2"
      initial={false}
      animate={open ? { x: k * 26, y: -30 + Math.abs(k) * 7, rotate: k * 11 } : { x: k * 2, y: 0, rotate: 0 }}
      transition={{ ...spring, delay: open ? index * 0.04 : 0 }}
      style={{ zIndex: index }}
    >
      <motion.span
        className="grid size-full place-items-center overflow-hidden rounded-lg bg-bone p-1.5 text-[10px] font-semibold leading-tight text-ink-950 shadow-[0_6px_14px_-6px_rgb(0_0_0/0.6)]"
        style={{ x, y }}
      >
        {children ?? (
          <span className="block w-full space-y-1">
            <span className="block h-1 w-3/4 rounded-full bg-ink-950/20" />
            <span className="block h-1 w-full rounded-full bg-ink-950/15" />
            <span className="block h-1 w-2/3 rounded-full bg-ink-950/15" />
          </span>
        )}
      </motion.span>
    </motion.span>
  );
}

/**
 * Mekai UI · Health Bar
 * MIT License · Copyright (c) 2026 Mekai Games
 * https://ui.mekaigames.com/components/health-bar
 * https://github.com/mekai-ui/mekai-ui
 */
"use client";

import { motion, useAnimate, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

type HealthBarProps = {
  /** Current health. Lower it to deal damage, raise it to heal. */
  value: number;
  max?: number;
  /** Fill color of the health bar. */
  color?: string;
  /** Color of the chip bar that trails behind after damage. */
  chipColor?: string;
  /** Glow and fill color shown while healing. */
  healColor?: string;
  /** Show the current and maximum values next to the label. */
  showNumbers?: boolean;
  label?: string;
  className?: string;
};

type Change = { n: number; kind: "damage" | "heal"; delta: number };

/** HP bar that drops instantly on damage while a lighter chip bar catches up, and glows on heal. */
export function HealthBar({
  value,
  max = 100,
  color = "#ff784f",
  chipColor = "#ffc24a",
  healColor = "#6ee09a",
  showNumbers = true,
  label = "HP",
  className = "",
}: HealthBarProps) {
  const reduce = useReducedMotion();
  const [scope, animate] = useAnimate();
  const top = Math.max(1, max);
  const hp = Math.round(Math.min(top, Math.max(0, value)));
  const pct = (hp / top) * 100;

  // Compare with the previous value during render to know whether this change is a hit or a heal.
  const [prev, setPrev] = useState(hp);
  const [change, setChange] = useState<Change | null>(null);
  if (hp !== prev) {
    setPrev(hp);
    setChange({ n: (change?.n ?? 0) + 1, kind: hp < prev ? "damage" : "heal", delta: hp - prev });
  }

  const damage = change?.kind === "damage";
  const heal = change?.kind === "heal";
  const low = pct <= 25 && hp > 0;

  useEffect(() => {
    if (!change || change.kind !== "damage" || reduce || !scope.current) return;
    animate(scope.current, { x: [0, -5, 5, -3, 3, 0] }, { duration: 0.32, ease: "easeOut" });
  }, [change, reduce, animate, scope]);

  return (
    <div className={`w-full ${className}`}>
      <div className="mb-1.5 flex items-baseline justify-between gap-3">
        <span className="font-pixel text-xs uppercase tracking-wide" style={{ color }}>
          {label}
        </span>
        {showNumbers ? (
          <span className="font-pixel text-xs tabular-nums text-bone">
            {hp === 0 ? <span style={{ color }}>KO</span> : hp}
            <span className="text-bone-dim"> / {top}</span>
          </span>
        ) : null}
      </div>

      <div className="relative">
        <div
          ref={scope}
          className="relative h-4 overflow-hidden rounded-[4px] bg-ink-800 ring-1 ring-inset ring-white/10"
          role="progressbar"
          aria-label={label}
          aria-valuemin={0}
          aria-valuemax={top}
          aria-valuenow={hp}
          aria-valuetext={`${hp} of ${top}`}
        >
          {/* Chip: holds the old value for a beat after a hit, then drains down. */}
          <motion.div
            className="absolute inset-y-0 left-0"
            style={{ backgroundColor: chipColor }}
            initial={false}
            animate={{ width: `${pct}%` }}
            transition={damage ? { duration: 0.55, delay: 0.45, ease: [0.45, 0, 0.2, 1] } : { duration: 0 }}
          />
          {/* Heal preview: jumps to the new value while the main bar fills up to it. */}
          <motion.div
            className="absolute inset-y-0 left-0 opacity-60"
            style={{ backgroundColor: healColor }}
            initial={false}
            animate={{ width: `${pct}%` }}
            transition={{ duration: 0 }}
          />
          <motion.div
            className="absolute inset-y-0 left-0 overflow-hidden"
            style={{ backgroundColor: color }}
            initial={false}
            animate={{ width: `${pct}%` }}
            transition={heal ? { duration: 0.6, delay: 0.15, ease: "easeOut" } : { duration: 0 }}
          >
            <span className="absolute inset-x-0 top-0 h-1/3 bg-white/25" />
            {low && !reduce ? (
              <motion.span
                className="absolute inset-0 bg-white"
                initial={{ opacity: 0 }}
                animate={{ opacity: [0, 0.3, 0] }}
                transition={{ duration: 0.9, repeat: Infinity, ease: "easeInOut" }}
              />
            ) : null}
          </motion.div>
          {/* Segment ticks every tenth of the bar. */}
          <span
            className="pointer-events-none absolute inset-0"
            style={{
              backgroundImage:
                "repeating-linear-gradient(90deg, transparent 0 calc(10% - 2px), rgb(7 6 6 / 0.55) calc(10% - 2px) 10%)",
            }}
          />
          {damage && !reduce ? (
            <motion.span
              key={change.n}
              className="pointer-events-none absolute inset-0 bg-white"
              initial={{ opacity: 0.8 }}
              animate={{ opacity: 0 }}
              transition={{ duration: 0.35, ease: "easeOut" }}
            />
          ) : null}
        </div>

        {heal ? (
          <motion.span
            key={change.n}
            aria-hidden="true"
            className="pointer-events-none absolute -inset-1 rounded-md"
            style={{ boxShadow: `0 0 18px 2px ${healColor}, inset 0 0 0 1px ${healColor}` }}
            initial={{ opacity: 1 }}
            animate={{ opacity: 0 }}
            transition={{ duration: reduce ? 0.2 : 0.9, ease: "easeOut" }}
          />
        ) : null}

        {change && change.delta !== 0 ? (
          <motion.span
            key={`n${change.n}`}
            aria-hidden="true"
            className="pointer-events-none absolute -top-1 font-pixel text-sm tabular-nums"
            style={{ left: `${pct}%`, color: heal ? healColor : color, textShadow: "0 2px 0 #070606" }}
            initial={{ opacity: 0, y: 0, x: "-50%" }}
            animate={{ opacity: [0, 1, 1, 0], y: reduce ? 0 : -22, x: "-50%" }}
            transition={{ duration: 0.9, ease: "easeOut" }}
          >
            {change.delta > 0 ? `+${change.delta}` : change.delta}
          </motion.span>
        ) : null}
      </div>
    </div>
  );
}

/**
 * Mekai UI · Magnetic Button
 * MIT License · Copyright (c) 2026 Mekai Games
 * https://ui.mekaigames.com/components/magnetic-button
 * https://github.com/mekai-ui/mekai-ui
 */
"use client";

import { motion, useMotionValue, useSpring } from "motion/react";
import type { PointerEvent, ReactNode } from "react";

type MagneticButtonProps = {
  children: ReactNode;
  /** How strongly the button follows the pointer, 0 to 1. */
  strength?: number;
  className?: string;
  onClick?: () => void;
};

export function MagneticButton({ children, strength = 0.35, className = "", onClick }: MagneticButtonProps) {
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const sx = useSpring(x, { stiffness: 260, damping: 18, mass: 0.6 });
  const sy = useSpring(y, { stiffness: 260, damping: 18, mass: 0.6 });

  function onMove(e: PointerEvent<HTMLButtonElement>) {
    if (e.pointerType !== "mouse") return;
    const rect = e.currentTarget.getBoundingClientRect();
    x.set((e.clientX - (rect.left + rect.width / 2)) * strength);
    y.set((e.clientY - (rect.top + rect.height / 2)) * strength);
  }

  function reset() {
    x.set(0);
    y.set(0);
  }

  return (
    <motion.button
      type="button"
      onClick={onClick}
      onPointerMove={onMove}
      onPointerLeave={reset}
      style={{ x: sx, y: sy }}
      whileTap={{ scale: 0.95 }}
      className={`rounded-full bg-bone px-7 py-3.5 font-display font-semibold text-black ${className}`}
    >
      <motion.span className="block" style={{ x: sx, y: sy }}>
        {children}
      </motion.span>
    </motion.button>
  );
}

