/**
 * Mekai UI · Split Text
 * MIT License · Copyright (c) 2026 Mekai Games
 * https://ui.mekaigames.com/components/split-text
 * https://github.com/mekai-ui/mekai-ui
 */
"use client";

import { motion, useInView, useReducedMotion } from "motion/react";
import { Fragment, useRef } from "react";

type SplitTextProps = {
  text: string;
  /** Seconds between one letter and the next. */
  stagger?: number;
  /** Where the letters come from. */
  from?: "bottom" | "top";
  /** Play only the first time the text enters the viewport. */
  once?: boolean;
  className?: string;
};

/** Letters that spring into place one by one when the text scrolls into view. */
export function SplitText({ text, stagger = 0.035, from = "bottom", once = true, className = "" }: SplitTextProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once, amount: 0.4 });
  const reduce = useReducedMotion();

  const words = text
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => Array.from(word));
  // Index of each word's first letter, so the stagger runs across the whole line.
  const starts: number[] = [];
  let total = 0;
  for (const letters of words) {
    starts.push(total);
    total += letters.length;
  }

  const sign = from === "bottom" ? 1 : -1;
  const hidden = { opacity: 0, y: `${0.75 * sign}em`, rotate: 14 * sign };
  const shown = { opacity: 1, y: "0em", rotate: 0 };

  return (
    <span ref={ref} className={className}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {words.map((letters, w) => (
          <Fragment key={w}>
            {w > 0 ? " " : null}
            <span className="inline-block whitespace-nowrap">
              {letters.map((char, i) => {
                const d = (starts[w] + i) * stagger;
                return (
                  <motion.span
                    key={i}
                    className="inline-block"
                    style={{ transformOrigin: from === "bottom" ? "0% 100%" : "0% 0%" }}
                    initial={reduce ? false : hidden}
                    animate={reduce || inView ? shown : hidden}
                    transition={
                      reduce
                        ? { duration: 0 }
                        : inView
                          ? {
                              type: "spring",
                              stiffness: 420,
                              damping: 19,
                              mass: 0.8,
                              delay: d,
                              opacity: { duration: 0.25, delay: d },
                            }
                          : { duration: 0.2 }
                    }
                  >
                    {char}
                  </motion.span>
                );
              })}
            </span>
          </Fragment>
        ))}
      </span>
    </span>
  );
}

/**
 * Mekai UI · Tilt Card
 * MIT License · Copyright (c) 2026 Mekai Games
 * https://ui.mekaigames.com/components/tilt-card
 * https://github.com/mekai-ui/mekai-ui
 */
"use client";

import { motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform } from "motion/react";
import type { PointerEvent, ReactNode } from "react";

type TiltCardProps = {
  children: ReactNode;
  /** Largest tilt on each axis, in degrees. */
  maxTilt?: number;
  /** Show a soft highlight that follows the pointer. */
  glare?: boolean;
  /** Color of the highlight. */
  glareColor?: string;
  /** Scale while the pointer is over the card. */
  scale?: number;
  className?: string;
};

const SPRING = { stiffness: 240, damping: 22, mass: 0.6 };

/** A card that tilts in 3D toward the pointer with a moving glare, and springs back when the pointer leaves. */
export function TiltCard({
  children,
  maxTilt = 12,
  glare = true,
  glareColor = "#f4ede3",
  scale = 1.03,
  className = "",
}: TiltCardProps) {
  const reduce = useReducedMotion();
  const tilt = reduce ? 0 : maxTilt;

  // Pointer position over the card, 0 to 1 on each axis. It rests at the center.
  const px = useMotionValue(0.5);
  const py = useMotionValue(0.5);
  const over = useMotionValue(0);
  const sx = useSpring(px, SPRING);
  const sy = useSpring(py, SPRING);
  const sOver = useSpring(over, SPRING);

  // The side under the pointer dips away, so the card turns to face it.
  const rotateX = useTransform(sy, [0, 1], [tilt, -tilt]);
  const rotateY = useTransform(sx, [0, 1], [-tilt, tilt]);
  const lift = useTransform(sOver, [0, 1], [1, reduce ? 1 : scale]);
  const glareOpacity = useTransform(sOver, [0, 1], [0, 0.24]);
  const gx = useTransform(sx, (v) => `${(v * 100).toFixed(1)}%`);
  const gy = useTransform(sy, (v) => `${(v * 100).toFixed(1)}%`);
  const glareBackground = useMotionTemplate`radial-gradient(circle at ${gx} ${gy}, ${glareColor}, transparent 62%)`;

  function track(e: PointerEvent<HTMLDivElement>) {
    const rect = e.currentTarget.getBoundingClientRect();
    px.set(Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width)));
    py.set(Math.min(1, Math.max(0, (e.clientY - rect.top) / rect.height)));
  }

  function enter(e: PointerEvent<HTMLDivElement>) {
    over.set(1);
    track(e);
  }

  function leave() {
    over.set(0);
    px.set(0.5);
