/**
 * Crucible · Anneal
 * MIT License · Copyright (c) 2026 Crucible (crucibleui.com)
 * https://crucibleui.com · https://crucibleui.com/r/anneal.json
 */
"use client";

import { motion, type HTMLMotionProps, type Variants } from "motion/react";
import * as React from "react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cn } from "@/lib/utils";

export interface AnnealProps
  extends Omit<HTMLMotionProps<"span">, "children" | "initial" | "whileInView" | "viewport" | "transition"> {
  /** The text to reveal. */
  children: string;
  /** Split granularity. Words keep natural line-wrapping; chars are more dramatic. */
  by?: "word" | "char";
  /** Seconds before the reveal starts. */
  delay?: number;
  /** Seconds between each segment's reveal. */
  stagger?: number;
  /** Seconds each segment takes to sharpen. */
  duration?: number;
  /** Starting blur radius in px. */
  blur?: number;
  /** Re-trigger every time the text scrolls into view (default: once). */
  repeat?: boolean;
}

/**
 * Anneal — text that resolves from a soft blur into sharp focus, one segment
 * at a time, when it enters the viewport. Like metal normalizing as it cools.
 * Falls back to a simple fade when the user prefers reduced motion.
 */
export function Anneal({
  children,
  by = "word",
  delay = 0,
  stagger = 0.045,
  duration = 0.5,
  blur = 10,
  repeat = false,
  className,
  ...props
}: AnnealProps) {
  const reducedMotion = useReducedMotion();

  // Words keep trailing spaces attached so layout is identical to plain text.
  // In char mode each word's characters are grouped in a nowrap wrapper so the
  // line only ever breaks at spaces, never mid-word.
  const words = React.useMemo(() => children.split(/(?<=\s)/), [children]);

  const variants: Variants = reducedMotion
    ? {
        // Reset filter/y explicitly: useReducedMotion returns false during SSR, so
        // the non-reduced hidden pose (blur + y offset) may already be committed as
        // the initial inline style. Without resetting them here, whileInView drives
        // only opacity and the text freezes blurred/offset. (Same class as surface.)
        hidden: { opacity: 0 },
        visible: { opacity: 1, filter: "blur(0px)", y: "0em", transition: { duration: 0.3 } },
      }
    : {
        hidden: { opacity: 0, filter: `blur(${blur}px)`, y: "0.3em" },
        visible: {
          opacity: 1,
          filter: "blur(0px)",
          y: "0em",
          transition: { duration, ease: [0.25, 0.4, 0.25, 1] },
        },
      };

  return (
    <motion.span
      className={cn("inline-block", className)}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: !repeat, amount: 0.6 }}
      transition={{ staggerChildren: reducedMotion ? 0 : stagger, delayChildren: delay }}
      aria-label={children}
      {...props}
    >
      {by === "char"
        ? words.map((word, wi) => (
            <span key={wi} aria-hidden className="inline-block whitespace-nowrap">
              {[...word].map((ch, ci) => (
                <motion.span
                  key={ci}
                  variants={variants}
                  className="inline-block whitespace-pre will-change-[filter,transform,opacity]"
                >
                  {ch}
                </motion.span>
              ))}
            </span>
          ))
        : words.map((segment, i) => (
            <motion.span
              key={i}
              aria-hidden
              variants={variants}
              className="inline-block whitespace-pre will-change-[filter,transform,opacity]"
            >
              {segment}
            </motion.span>
          ))}
    </motion.span>
  );
}

/**
 * Crucible · Cipher
 * MIT License · Copyright (c) 2026 Crucible (crucibleui.com)
 * https://crucibleui.com · https://crucibleui.com/r/cipher.json
 */
"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface CipherProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /** The text to resolve into. */
  children: string;
  /** What starts the scramble. @default "mount" */
  trigger?: "mount" | "hover" | "view";
  /** Order characters lock into place. @default "random" */
  resolveOrder?: "start" | "end" | "center" | "random";
  /** Glyphs drawn from while a character is still scrambling. @default abstract glyph set */
  charset?: string;
  /** Seconds for the whole string to resolve. @default 1.1 */
  duration?: number;
  /** Seconds to wait before the scramble starts. @default 0 */
  delay?: number;
  /**
   * Re-run every time the element scrolls back into view (`trigger="view"`).
   * The `hover` trigger always re-scrambles on each hover. @default false
   */
  repeat?: boolean;
  /** Color of the still-scrambling glyphs. @default neutral-400 */
  scrambleColor?: string;
  /** Color of the brief flash when a character locks in. @default white */
  flashColor?: string;
}

const DEFAULT_CHARSET = "⟁⟂⟃⟄⏃⏚⌬⌭⎔⋈⋔※᛭ᚨᚱᚲ0123456789#%&";

function computeRanks(n: number, order: NonNullable<CipherProps["resolveOrder"]>): number[] {
  const ranks = new Array<number>(n);
  if (order === "end") {
    for (let i = 0; i < n; i++) ranks[i] = n - 1 - i;
    return ranks;
  }
  if (order === "center") {
    const center = (n - 1) / 2;
    const idx = Array.from({ length: n }, (_, i) => i).sort(
      (a, b) => Math.abs(a - center) - Math.abs(b - center) || a - b
    );
    idx.forEach((charIndex, rank) => {
      ranks[charIndex] = rank;
    });
    return ranks;
  }
  if (order === "random") {
    const idx = Array.from({ length: n }, (_, i) => i);
    for (let i = idx.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const tmp = idx[i]!;
      idx[i] = idx[j]!;
      idx[j] = tmp;
    }
    idx.forEach((charIndex, rank) => {
      ranks[charIndex] = rank;
    });
    return ranks;
  }
  for (let i = 0; i < n; i++) ranks[i] = i;
  return ranks;
}

/**
 * Cipher — characters churn through scrambled glyphs before locking into the
 * final text, one at a time, in the order you choose — each lock-in marked by
 * a brief white flash. Resolves instantly under reduced motion.
 */
export function Cipher({
  children,
  trigger = "mount",
  resolveOrder = "random",
  charset = DEFAULT_CHARSET,
  duration = 1.1,
  delay = 0,
  repeat = false,
  scrambleColor = "#a3a3a3",
  flashColor = "#ffffff",
  className,
  style,
  ...props
}: CipherProps) {
  const reducedMotion = useReducedMotion();
  const chars = React.useMemo(() => Array.from(children), [children]);
  // Runs of non-space chars (words) vs. whitespace, so the render can keep each
  // word on one line while letting the line break at spaces.
  const wordGroups = React.useMemo(() => {
    const groups: { start: number; end: number; isSpace: boolean }[] = [];
    let i = 0;
    while (i < chars.length) {
      const isSpace = /\s/.test(chars[i]!);
      let j = i;
      while (j < chars.length && /\s/.test(chars[j]!) === isSpace) j++;
      groups.push({ start: i, end: j, isSpace });
      i = j;
    }
    return groups;
  }, [chars]);
  const [display, setDisplay] = React.useState<string[]>(chars);
  const [resolvedMask, setResolvedMask] = React.useState<boolean[]>(() => chars.map(() => true));
  const runIdRef = React.useRef(0);
  const wrapperRef = React.useRef<HTMLSpanElement>(null);
  const hasRunRef = React.useRef(false);

  const run = React.useCallback(() => {
    if (reducedMotion) {
      runIdRef.current++; // cancel any scramble already in flight
      setDisplay(chars);
      setResolvedMask(chars.map(() => true));
      return;
    }
    const n = chars.length;
    if (n === 0) return;
    const ranks = computeRanks(n, resolveOrder);
    const runId = ++runIdRef.current;
    const durationMs = Math.max(duration, 0.05) * 1000;
    const delayMs = Math.max(delay, 0) * 1000;
    const startTime = performance.now();

    setResolvedMask(chars.map(() => false));

    const tick = (now: number) => {
      if (runIdRef.current !== runId) return;
      const elapsed = now - startTime - delayMs;
      if (elapsed < 0) {
        requestAnimationFrame(tick);
        return;
      }
      const progress = Math.min(1, elapsed / durationMs);
      const resolvedCount = Math.floor(progress * n);
      const nextDisplay = new Array<string>(n);
      const nextMask = new Array<boolean>(n);
      for (let i = 0; i < n; i++) {
        const original = chars[i]!;
        const isResolved = progress >= 1 || ranks[i]! < resolvedCount || /\s/.test(original);
        nextMask[i] = isResolved;
        nextDisplay[i] = isResolved ? original : (charset[Math.floor(Math.random() * charset.length)] ?? original);
      }
      setDisplay(nextDisplay);
      setResolvedMask(nextMask);
      if (progress < 1) requestAnimationFrame(tick);
    };

    requestAnimationFrame(tick);
  }, [chars, charset, duration, delay, resolveOrder, reducedMotion]);

  // Stop any in-flight scramble loop on unmount.
  React.useEffect(
    () => () => {
      runIdRef.current++;
    },
    []
  );

  // Reset display whenever the target text itself changes.
  React.useEffect(() => {
    runIdRef.current++; // a scramble of the old text must not overwrite the new one
    setDisplay(chars);
    setResolvedMask(chars.map(() => true));
    hasRunRef.current = false;
  }, [chars]);

  React.useEffect(() => {
    if (trigger !== "mount") return;
    run();
  }, [trigger, run]);

  React.useEffect(() => {
    if (trigger !== "view") return;
    const node = wrapperRef.current;
    if (!node || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting && (!hasRunRef.current || repeat)) {
          hasRunRef.current = true;
          run();
        }
      },
      { threshold: 0.6 }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [trigger, repeat, run]);

  const handleMouseEnter = trigger === "hover" ? () => run() : undefined;

  if (reducedMotion) {
    return (
      <span
        ref={wrapperRef}
        aria-label={children}
        className={cn("inline-block", className)}
        style={style}
        {...props}
      >
        <span aria-hidden>{children}</span>
      </span>
    );
  }

  return (
    <span
      ref={wrapperRef}
      aria-label={children}
      onMouseEnter={handleMouseEnter}
      className={cn("inline-block", className)}
      style={
        {
          "--cipher-scramble-color": scrambleColor,
          "--cipher-flash-color": flashColor,
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      <style>{`
        @keyframes crucible-cipher-quench {
          0% { color: var(--cipher-flash-color); text-shadow: 0 0 8px var(--cipher-flash-color); }
          100% { color: inherit; text-shadow: none; }
        }
        @keyframes crucible-cipher-jitter {
          0%, 100% { transform: translateY(0); opacity: 0.9; }
          50% { transform: translateY(-1px); opacity: 1; }
        }
        [data-crucible="cipher"] .cipher-quench {
          animation: crucible-cipher-quench 0.32s ease-out;
        }
        [data-crucible="cipher"] .cipher-scramble {
          color: var(--cipher-scramble-color);
          animation: crucible-cipher-jitter 0.15s steps(2) infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="cipher"] .cipher-scramble { animation: none; }
        }
      `}</style>
      <span data-crucible="cipher" aria-hidden className="inline-block">
        {/* Group per-character spans by word so the line only breaks at spaces —
            bare inline-block chars otherwise wrap mid-word (e.g. 'bet|ter'). The
            global index i is preserved for the scramble animation. */}
        {wordGroups.map((g, gi) =>
          g.isSpace ? (
            <span key={`g-${gi}`} className="whitespace-pre">
              {display.slice(g.start, g.end).join("")}
            </span>
          ) : (
            <span key={`g-${gi}`} className="inline-block whitespace-nowrap">
              {Array.from({ length: g.end - g.start }, (_, k) => {
                const i = g.start + k;
                return (
                  <span
                    key={resolvedMask[i] ? `r-${i}` : `s-${i}`}
                    className={cn("inline-block whitespace-pre", resolvedMask[i] ? "cipher-quench" : "cipher-scramble")}
                  >
                    {display[i]}
                  </span>
                );
              })}
            </span>
          )
        )}
      </span>
    </span>
  );
}

/**
 * Crucible · Flywheel
 * MIT License · Copyright (c) 2026 Crucible (crucibleui.com)
 * https://crucibleui.com · https://crucibleui.com/r/flywheel.json
 */
import * as React from "react";

import { cn } from "@/lib/utils";

export interface FlywheelProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Which spinner to render.
   * - `ring` (default): a machined groove with a white-hot comet head that
   *   cools to a blue-silver tail, spun with heavy inertia and a faint
   *   flicker at speed — the Crucible signature.
   * - `dots-orbit`: a comet of beads orbiting, each breathing on a sine so
   *   the ring has life even at rest.
   * - `segmented`: a spoked wheel of alternating solid/gap segments with a
   *   hot leading spoke.
   * - `dual-ring`: two filament heads counter-rotating at different rates.
   * @default "ring"
   */
  variant?: "ring" | "dots-orbit" | "segmented" | "dual-ring";
  /** Overall size in px. @default 40 */
  size?: number;
  /** Rotation speed multiplier. 1 = default, 2 = twice as fast. @default 1 */
  speed?: number;
  /** Accessible label announced to screen readers. @default "Loading" */
  label?: string;
  /** Accent color for the hot head / active ring. @default "#ffffff" */
  accentColor?: string;
}

// Grain tile — a tiny fractal-noise SVG, tiled at low opacity over the whole
// widget to kill gradient banding and give the glow a shader-grade texture.
// Built once at module scope (pure string ops — SSR-safe, deterministic).
const GRAIN_SVG =
  "<svg xmlns='http://www.w3.org/2000/svg' width='90' height='90'>" +
  "<filter id='fwn'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter>" +
  "<rect width='100%' height='100%' filter='url(#fwn)'/></svg>";
const GRAIN_URI = `url("data:image/svg+xml,${encodeURIComponent(GRAIN_SVG)}")`;

const KEYFRAMES = `
@property --fw-spin {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
@keyframes crucible-flywheel-spin { to { transform: rotate(360deg); } }
@keyframes crucible-flywheel-spin-reverse { to { transform: rotate(-360deg); } }
@keyframes crucible-flywheel-flicker {
  0%, 21%, 23%, 46%, 48%, 100% { opacity: 1; }
  22%, 47% { opacity: 0.62; }
}
/* A sine-ish breath: dots swell and dim, never fully off — idle life. */
@keyframes crucible-flywheel-dot {
  0%, 100% { opacity: 0.18; transform: scale(0.7); }
  50% { opacity: 1; transform: scale(1.15); }
}
/* The head bloom breathes slightly so the tip flares, not just glows flat. */
@keyframes crucible-flywheel-bloom {
  0%, 100% { opacity: 0.85; transform: translate(-50%, -50%) scale(1); }
  50% { opacity: 1; transform: translate(-50%, -50%) scale(1.18); }
}
[data-crucible="flywheel"] .fw-rotor,
[data-crucible="flywheel"] .fw-dot { will-change: transform; }
@media (prefers-reduced-motion: reduce) {
  /* Pin an explicit, legible resting pose — a lit comet, never a blank box
     and never frozen mid-blur. All animated props are committed here. */
  [data-crucible="flywheel"] .fw-rotor {
    animation: none !important;
    transform: rotate(-42deg) !important;
  }
  [data-crucible="flywheel"] .fw-rotor-slow {
    transform: rotate(38deg) !important;
  }
  [data-crucible="flywheel"] .fw-spin-inner { animation: none !important; }
  [data-crucible="flywheel"] .fw-stroke,
  [data-crucible="flywheel"] .fw-head { animation: none !important; opacity: 1 !important; }
  [data-crucible="flywheel"] .fw-bloom {
    animation: none !important;
    opacity: 0.9 !important;
    transform: translate(-50%, -50%) scale(1) !important;
  }
  [data-crucible="flywheel"] .fw-dot {
    animation: none !important;
    opacity: 0.85 !important;
    transform: scale(1) !important;
  }
}
`;

const DOT_COUNT = 8;

// Shared machined groove behind a rotating stroke: a recessed channel with an
// inner shadow, a dark outer rim and a soft top rim-light so it reads as cut
// metal, not a CSS border.
function Groove({ thickness = "var(--fw-thick)", inset = "0" }: { thickness?: string; inset?: string }) {
  return (
    <>
      <span
        aria-hidden
        className="pointer-events-none absolute rounded-full"
        style={{
          inset,
          border: `${thickness} solid transparent`,
          background: `linear-gradient(to bottom, color-mix(in oklab, currentColor 24%, transparent), color-mix(in oklab, currentColor 7%, transparent)) border-box`,
          WebkitMask: "linear-gradient(#000 0 0) padding-box, linear-gradient(#000 0 0)",
          WebkitMaskComposite: "xor",
          mask: "linear-gradient(#000 0 0) padding-box, linear-gradient(#000 0 0)",
          maskComposite: "exclude",
        }}
      />
      <span
        aria-hidden
        className="pointer-events-none absolute rounded-full"
        style={{
          inset,
          boxShadow:
            "inset 0 1px 1.5px rgba(0,0,0,0.65), inset 0 -1px 1px rgba(255,255,255,0.09), inset 0 0 3px rgba(0,0,0,0.5)",
        }}
      />
    </>
  );
}

// The comet head: a blurred bloom flaring behind a sharp white-hot core, both
// pinned to the top-centre point of the ring where the conic head sits.
function Head({ bloom = true }: { bloom?: boolean }) {
  return (
    <>
      {bloom && (
        <span
          aria-hidden
          className="fw-bloom pointer-events-none absolute rounded-full"
          style={{
            top: 0,
            left: "50%",
            width: "calc(var(--fw-thick) * 5)",
            height: "calc(var(--fw-thick) * 5)",
            transform: "translate(-50%, -50%)",
            background: `radial-gradient(circle, var(--fw-accent) 0%, color-mix(in oklab, var(--fw-hot) 70%, transparent) 35%, transparent 70%)`,
            filter: "blur(2.5px) brightness(1.35)",
            animation: "crucible-flywheel-bloom calc(var(--fw-dur) * 2) ease-in-out infinite",
          }}
        />
      )}
      <span
        aria-hidden
        className="fw-head pointer-events-none absolute rounded-full"
        style={{
          top: 0,
          left: "50%",
          width: "calc(var(--fw-thick) * 1.7)",
          height: "calc(var(--fw-thick) * 1.7)",
          transform: "translate(-50%, -50%)",
          background: `radial-gradient(circle, var(--fw-accent) 0%, var(--fw-hot) 55%, transparent 78%)`,
          boxShadow:
            "0 0 4px 1px color-mix(in oklab, var(--fw-accent) 80%, transparent), 0 0 9px 2px color-mix(in oklab, var(--fw-hot) 45%, transparent)",
        }}
      />
    </>
  );
}

// Conic hot filament, masked to the ring band. Head at 12 o'clock (0deg),
// cooling backward into a blue-silver tail that fades to nothing.
const cometConic = `conic-gradient(from 0deg,
  var(--fw-accent) 0%,
  color-mix(in oklab, var(--fw-hot) 55%, transparent) 2.5%,
  transparent 6%,
  transparent 58%,
