import { motion, useAnimate, useReducedMotion } from "motion/react";
import { Fragment, useEffect, useRef, useState, type CSSProperties } from "react";

type TrueFocusProps = {
  text: string;
  /** "auto" moves the focus on a timer, "manual" follows the pointer and keyboard only. */
  mode?: "auto" | "manual";
  /** Milliseconds per word in auto mode. */
  interval?: number;
  /** Blur in pixels for the words out of focus. */
  blur?: number;
  frameColor?: string;
  /** Space in pixels between a word and its frame. */
  padding?: number;
  className?: string;
};

const CORNERS: { className: string; sides: (keyof CSSProperties)[] }[] = [
  { className: "left-0 top-0 rounded-tl-[0.1em]", sides: ["borderTopWidth", "borderLeftWidth"] },
  { className: "right-0 top-0 rounded-tr-[0.1em]", sides: ["borderTopWidth", "borderRightWidth"] },
  { className: "bottom-0 left-0 rounded-bl-[0.1em]", sides: ["borderBottomWidth", "borderLeftWidth"] },
  { className: "bottom-0 right-0 rounded-br-[0.1em]", sides: ["borderBottomWidth", "borderRightWidth"] },
];

/** A sentence where one word at a time is sharp, framed by corner brackets that glide between words. */
export function TrueFocus({
  text,
  mode = "auto",
  interval = 1800,
  blur = 5,
  frameColor = "#ff784f",
  padding = 10,
  className = "",
}: TrueFocusProps) {
  const words = text.split(/\s+/).filter(Boolean);
  const count = words.length;
  const reduce = useReducedMotion();
  const [index, setIndex] = useState(0);
  const [hovering, setHovering] = useState(false);
  const [focused, setFocused] = useState(false);
  const root = useRef<HTMLSpanElement>(null);
  const [frame, animate] = useAnimate<HTMLSpanElement>();
  const placed = useRef(false);
  const currentRef = useRef(0);
  const current = count ? index % count : 0;

  // Auto mode: step through the words, pausing while the reader is pointing or tabbing.
  useEffect(() => {
    if (mode !== "auto" || hovering || focused || reduce || count < 2) return;
    const id = setInterval(() => setIndex((i) => (i + 1) % count), Math.max(400, interval));
    return () => clearInterval(id);
  }, [mode, hovering, focused, reduce, count, interval]);

  useEffect(() => {
    const place = (i: number, instant: boolean) => {
      const word = root.current?.querySelector<HTMLElement>(`[data-word="${i}"]`);
      if (!word || !frame.current) return;
      animate(
        frame.current,
        {
          x: word.offsetLeft - padding,
          y: word.offsetTop - padding,
          width: word.offsetWidth + padding * 2,
          height: word.offsetHeight + padding * 2,
          opacity: 1,
        },
        instant || reduce ? { duration: 0 } : { type: "spring", stiffness: 260, damping: 28 },
      );
    };
    currentRef.current = current;
    place(current, !placed.current);
    placed.current = true;
  }, [current, padding, reduce, animate, frame]);

  // Keep the frame on its word when the text reflows.
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      const word = el.querySelector<HTMLElement>(`[data-word="${currentRef.current}"]`);
      if (!word || !frame.current) return;
      animate(
        frame.current,
        {
          x: word.offsetLeft - padding,
          y: word.offsetTop - padding,
          width: word.offsetWidth + padding * 2,
          height: word.offsetHeight + padding * 2,
        },
        { duration: 0 },
      );
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [padding, animate, frame]);

  const border = "max(2px, 0.045em)";

  return (
    <span
      ref={root}
      className={`relative inline-block ${className}`}
      onPointerEnter={() => setHovering(true)}
      onPointerLeave={() => setHovering(false)}
    >
      {words.map((word, i) => {
        const sharp = reduce || i === current;
        return (
          <Fragment key={i}>
            {i > 0 ? " " : null}
            <motion.span
              data-word={i}
              tabIndex={0}
              className="relative inline-block focus-visible:outline-none"
              onPointerEnter={() => setIndex(i)}
              onFocus={() => {
                setIndex(i);
                setFocused(true);
              }}
              onBlur={() => setFocused(false)}
              initial={false}
              animate={{ filter: sharp ? "blur(0px)" : `blur(${blur}px)`, opacity: sharp ? 1 : 0.55 }}
              transition={{ duration: reduce ? 0 : 0.45, ease: "easeOut" }}
            >
              {word}
            </motion.span>
          </Fragment>
        );
      })}
      <span
        ref={frame}
        aria-hidden="true"
        className="pointer-events-none absolute left-0 top-0"
        style={{ opacity: 0, filter: `drop-shadow(0 0 0.12em ${frameColor}99)` }}
      >
        {CORNERS.map((corner, i) => (
          <span
            key={i}
            className={`absolute size-[0.3em] min-h-2.5 min-w-2.5 border-solid ${corner.className}`}
            style={{
              borderColor: frameColor,
              borderWidth: 0,
              ...Object.fromEntries(corner.sides.map((side) => [side, border])),
            }}
          />
        ))}
      </span>
    </span>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

type TypewriterProps = {
  phrases: string[];
  /** Average milliseconds per typed character. */
  typeSpeed?: number;
  /** Milliseconds per deleted character. */
  deleteSpeed?: number;
  /** Milliseconds a finished phrase stays before it is deleted. */
  pause?: number;
  /** Start again from the first phrase after the last one. */
  loop?: boolean;
  /** Show a blinking caret after the text. */
  caret?: boolean;
  caretColor?: string;
  className?: string;
};

type Step = { index: number; length: number; deleting: boolean };

/** Types a list of phrases one character at a time, deletes them and moves on, with a blinking caret. */
export function Typewriter({
  phrases,
  typeSpeed = 70,
  deleteSpeed = 40,
  pause = 1400,
  loop = true,
  caret = true,
  caretColor = "#ff784f",
  className = "",
}: TypewriterProps) {
  const reduce = useReducedMotion();
  const [step, setStep] = useState<Step>({ index: 0, length: 0, deleting: false });
  const count = phrases.length;
  const index = count ? step.index % count : 0;
  const chars = Array.from(phrases[index] ?? "");
  const full = chars.length;
  const isLast = index === count - 1;
  const typed = !step.deleting && step.length >= full;
  const finished = typed && isLast && !loop;

  useEffect(() => {
    if (reduce || count === 0 || finished) return;
    const { length, deleting } = step;
    let wait: number;
    let next: Step;
    if (!deleting && length < full) {
      // A little jitter makes the typing feel human.
      wait = typeSpeed * (0.6 + Math.random() * 0.8);
      next = { index, length: length + 1, deleting: false };
    } else if (!deleting) {
      wait = pause;
      next = { index, length, deleting: true };
    } else if (length > 0) {
      wait = deleteSpeed;
      next = { index, length: length - 1, deleting: true };
    } else {
      wait = Math.max(220, typeSpeed * 3);
      next = { index: (index + 1) % count, length: 0, deleting: false };
    }
    const id = setTimeout(() => setStep(next), wait);
    return () => clearTimeout(id);
  }, [step, index, full, count, finished, reduce, typeSpeed, deleteSpeed, pause]);

  const shown = reduce ? (loop ? phrases[0] : phrases[count - 1]) ?? "" : chars.slice(0, step.length).join("");
  // Solid while typing or deleting, blinking while it waits.
  const blink = !reduce && (typed || (step.deleting && step.length === 0));

  return (
    <span className={className}>
      <span className="sr-only">{phrases.join(", ")}</span>
      <span aria-hidden="true">
        {shown || "​"}
        {caret ? (
          <motion.span
            className="ml-[0.06em] inline-block h-[0.9em] w-[0.08em] translate-y-[0.1em] rounded-[1px]"
            style={{ backgroundColor: caretColor }}
            animate={blink ? { opacity: [1, 1, 0, 0] } : { opacity: 1 }}
            transition={
              blink ? { duration: 1, times: [0, 0.5, 0.55, 1], ease: "linear", repeat: Infinity } : { duration: 0 }
            }
          />
        ) : null}
      </span>
    </span>
  );
}

