};

const toUnit = ([r, g, b]: Rgb): Vec3 => [r / 255, g / 255, b / 255];

const rotateHue = ([r, g, b]: Rgb, degrees: number): Rgb => {
  const a = (degrees * Math.PI) / 180;
  const c = Math.cos(a);
  const s = Math.sin(a);
  const k = 1 / 3;
  const q = Math.sqrt(k);
  const m0 = c + (1 - c) * k;
  const m1 = k * (1 - c) - q * s;
  const m2 = k * (1 - c) + q * s;
  const clampC = (v: number) => Math.min(255, Math.max(0, v));
  return [
    clampC(r * m0 + g * m1 + b * m2),
    clampC(r * m2 + g * m0 + b * m1),
    clampC(r * m1 + g * m2 + b * m0),
  ];
};

const muteRgb = (rgb: Rgb, amount: number): Rgb => {
  const lum = rgb[0] * 0.2126 + rgb[1] * 0.7152 + rgb[2] * 0.0722;
  return mixRgb(rgb, [lum, lum, lum], amount);
};

const WHITE: Rgb = [255, 255, 255];

interface Palette {
  a: Vec3;
  b: Vec3;
  c: Vec3;
  d: Vec3;
  hi: Vec3;
  cool: Vec3;
  warm: Vec3;
  glow: Vec3;
}

const buildPalette = (from: Rgb, to: Rgb, mute: number): Palette => {
  const a = muteRgb(from, mute);
  const b = muteRgb(to, mute);
  const c = muteRgb(rotateHue(mixRgb(from, to, 0.35), -38), mute);
  const d = muteRgb(rotateHue(mixRgb(from, to, 0.65), 42), mute);
  const mid = mixRgb(a, b, 0.5);
  return {
    a: toUnit(a),
    b: toUnit(b),
    c: toUnit(c),
    d: toUnit(d),
    hi: toUnit(mixRgb(mid, WHITE, 0.82)),
    cool: toUnit(mixRgb(a, WHITE, 0.15)),
    warm: toUnit(mixRgb(d, WHITE, 0.1)),
    glow: toUnit(mid),
  };
};

const VERT = `
attribute vec2 aPos;
void main() {
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;

uniform float uSize;
uniform float uPhase;
uniform float uLevel;
uniform float uWarp;
uniform float uRidge;
uniform float uSharp;
uniform float uZoom;
uniform float uExposure;
uniform float uGlow;
uniform float uRim;
uniform float uHear;
uniform float uFade;
uniform vec3 uColA;
uniform vec3 uColB;
uniform vec3 uColC;
uniform vec3 uColD;
uniform vec3 uHi;
uniform vec3 uCool;
uniform vec3 uWarm;
uniform vec3 uGlowCol;

const float RAD = 0.86;
const float SOFT = 0.005;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * noise(p);
    p = mat2(0.8, 0.6, -0.6, 0.8) * p * 2.03;
    a *= 0.5;
  }
  return s / 0.9375;
}

vec2 band(vec2 q, float drift, float offset, float amp, float mainY, float env, float soft) {
  float y = amp * env * sin(q.x * 1.0 + drift + offset);
  float d = abs(q.y - y);
  float line = 0.018 / (sqrt(d * d + soft * soft) + 0.026);
  float bd = max(0.0, max(q.y - max(mainY, y), min(mainY, y) - q.y));
  float fillB = 0.014 / (bd * bd * 5.0 + 0.06);
  return vec2(line, fillB);
}

vec3 sheet(vec2 p, float t) {
  float scale = 0.74 + uZoom * 0.34;
  vec2 q = p / scale;
  vec2 w = vec2(fbm(q * 1.1 + vec2(0.0, t * 0.09)), fbm(q * 1.1 + vec2(7.7, -t * 0.07))) - 0.5;
  q += uWarp * 0.075 * w;
  float xn = q.x;
  float envB = cos(1.57079633 * min(abs(0.9 * xn), 1.0));
  float env = envB * envB;
  float low = 0.5 + 0.5 * cos(t * 0.37);
  float mid = 0.5 + 0.5 * sin(t * 0.51 + 1.2);
  float high = 0.5 + 0.5 * cos(t * 0.73 + 2.1);
  float drift = t * 2.4;
  float mainAmp = 0.1 + uRidge * 0.17 + low * 0.018;
  float bandAmp = mainAmp + mid * 0.025 + high * 0.018;
  float mainY = mainAmp * env * sin(q.x * 1.1 + drift);
  float sep = 1.85 + uWarp * 0.12 + mid * 0.28;
  float soft = 0.03 / max(uSharp, 0.2) + mid * 0.006;

  vec2 b0 = band(q, drift, -sep, bandAmp, mainY, env, soft);
  vec2 b1 = band(q, drift, -sep * 0.34, bandAmp, mainY, env, soft);
  vec2 b2 = band(q, drift, sep * 0.34, bandAmp, mainY, env, soft);
  vec2 b3 = band(q, drift, sep, bandAmp, mainY, env, soft);
  float w0 = b0.x + b0.y;
  float w1 = b1.x + b1.y;
  float w2 = b2.x + b2.y;
  float w3 = b3.x + b3.y;
  float total = w0 + w1 + w2 + w3;
  float d0 = w0 * w0;
  float d1 = w1 * w1;
  float d2 = w2 * w2;
  float d3 = w3 * w3;
  vec3 spectral = (uColA * d0 + uColC * d1 + uColB * d2 + uColD * d3) / max(d0 + d1 + d2 + d3, 0.0001);
  float energy = (1.0 - exp(-max(total - 0.12, 0.0) * 0.75)) * env;
  float md = abs(q.y - mainY);
  float core = exp(-md * md / (0.0028 / max(uSharp, 0.2))) * env;

  float haze = fbm(q * 1.6 + vec2(t * 0.05, -t * 0.03));
  vec3 atmos = mix(uColD, uColB, smoothstep(-0.7, 0.7, q.y)) * (0.012 + 0.022 * haze);
  atmos += mix(uColA, uColC, haze) * 0.035 * exp(-q.y * q.y * 7.0) * haze;

  vec3 col = atmos + spectral * energy * 1.14;
  col += uHi * core * (0.2 + 0.1 * low);
  col = col / (1.0 + col * 0.18);
  col = mix(col, uHi, 0.06 * smoothstep(0.15, 1.15, dot(p, vec2(-0.32, 0.78))));
  col *= 1.0 - 0.3 * smoothstep(-0.1, 1.2, dot(p, vec2(0.45, -0.62)));
  return col;
}

float profile(float t) {
  float d = clamp(t, 0.0, 1.0);
  return 1.0 - sqrt(max(1.0 - (1.0 - d) * (1.0 - d), 0.0));
}

float lobe(vec2 n, vec2 dir, float cut, float power) {
  return pow(clamp((dot(n, dir) - cut) / max(1.0 - cut, 0.001), 0.0, 1.0), power);
}

vec3 over(vec3 dst, vec3 src, float a) {
  float k = clamp(a, 0.0, 1.0);
  return src * k + dst * (1.0 - k);
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uSize) / uSize;
  float r = length(uv);
  float ang = atan(uv.y, uv.x);
  float t = uPhase;

  float contour = uHear * uLevel * (0.011 * sin(ang * 3.0 + t * 1.9) + 0.006 * sin(ang * 5.0 - t * 1.3 + 1.7));
  float rad = RAD * (1.0 + contour);
  vec3 glowCol = uGlowCol * (0.6 + 0.4 * uHear * uLevel);
  float glowAmt = uGlow * (1.0 + 0.9 * uHear * uLevel);

  if (r > rad * (1.01 + SOFT)) {
    vec3 halo = glowCol * glowAmt * exp(-(r - rad) * 11.0) * (1.0 - smoothstep(rad, 0.995, r));
    halo = clamp(halo, 0.0, 1.0);
    gl_FragColor = vec4(halo, max(halo.r, max(halo.g, halo.b))) * uFade;
    return;
  }

  vec2 p = uv / rad;
  float pd = length(p);
  vec2 n = pd > 0.0001 ? p / pd : vec2(0.0);
  float edge = max(1.0 - pd, 0.0);
  float prof = pow(profile(edge / 0.3), 0.68);
  vec2 rp = p - n * prof * 0.5;

  vec3 fcol;
  if (prof > 0.002) {
    float split = 0.12 * prof;
    fcol = vec3(sheet(rp - n * split, t).r, sheet(rp, t).g, sheet(rp + n * split, t).b);
  } else {
    fcol = sheet(p, t);
  }

  float lum = dot(fcol, vec3(0.213, 0.715, 0.072));
  vec3 col = clamp(vec3(lum) + (fcol - vec3(lum)) * 1.18, 0.0, 1.0);

  float rimReact = uRim * (1.0 + 0.45 * uHear * uLevel);
  float surfW = 0.035 + 0.03 * uHear * uLevel;
  float surf = 1.0 - smoothstep(0.0, surfW, edge);
  float optical = pow(surf, 1.8);
  col = over(col, mix(uColA, uHi, 0.5) * 0.35, optical * 0.1 * rimReact);

  float coolS = lobe(n, normalize(vec2(0.84, 0.54)), 0.05, 1.6);
  float warmS = lobe(n, normalize(vec2(-0.62, -0.78)), 0.05, 1.8);
  float disp = optical * 0.5 * rimReact;
  col = over(col, uCool, disp * coolS);
  col = over(col, uWarm, disp * warmS);

  col *= 1.0 - optical * 0.12 * (0.15 + 0.85 * max(dot(n, vec2(0.45, -0.89)), 0.0));

  float key = optical * lobe(n, normalize(vec2(-0.68, 0.73)), 0.2, 2.8) * 0.6 * rimReact;
  float fillL = optical * lobe(n, normalize(vec2(0.74, -0.67)), 0.4, 3.6) * 0.4 * rimReact;
  col = over(col, mix(uHi, vec3(1.0), 0.35), key);
  col = over(col, mix(uColC, uHi, 0.55), fillL);

  col *= 1.0 - 0.4 * smoothstep(0.95, 1.0, pd);
  col += mix(uColA, uColB, 0.3 + 0.3 * sin(ang + t * 0.6)) * optical * 0.3 * uHear * uLevel;

  float spec = exp(-dot(p - vec2(-0.38, 0.46), p - vec2(-0.38, 0.46)) * 22.0);
  col += uHi * spec * 0.07 * uRim;

  float ballA = 1.0 - smoothstep(0.99 - SOFT, 1.01 + SOFT, pd);
  col = clamp(col * max(uExposure, 0.0), 0.0, 1.0) * ballA;
  float outside = smoothstep(rad - SOFT, rad + SOFT, r);
  col += glowCol * glowAmt * exp(-max(r - rad, 0.0) * 11.0) * (1.0 - smoothstep(rad, 0.995, r)) * outside;
  col = clamp(col, 0.0, 1.0);
  float a = clamp(max(ballA, max(col.r, max(col.g, col.b))), 0.0, 1.0);
  gl_FragColor = vec4(col, a) * uFade;
}
`;

const UNIFORMS = [
  'uSize',
  'uPhase',
  'uLevel',
  'uWarp',
  'uRidge',
  'uSharp',
  'uZoom',
  'uExposure',
  'uGlow',
  'uRim',
  'uHear',
  'uFade',
  'uColA',
  'uColB',
  'uColC',
  'uColD',
  'uHi',
  'uCool',
  'uWarm',
  'uGlowCol',
] as const;

type UniformName = (typeof UNIFORMS)[number];

const SHAKE_TIME = 0.55;

const fallbackLayer = (from: string, to: string, size: number): CSSProperties => ({
  position: 'absolute',
  inset: '7%',
  borderRadius: '50%',
  background: `radial-gradient(ellipse 70% 16% at 50% 50%, color-mix(in oklab, ${from} 45%, white) 0%, ${from} 30%, transparent 72%), radial-gradient(ellipse 85% 34% at 50% 52%, color-mix(in oklab, ${to} 70%, transparent) 0%, transparent 70%), radial-gradient(circle at 34% 28%, rgba(255, 255, 255, 0.18), transparent 38%), radial-gradient(circle at 50% 50%, color-mix(in oklab, ${to} 18%, #07060f) 55%, color-mix(in oklab, ${from} 40%, #07060f) 100%)`,
  boxShadow: `0 0 calc(${Math.round(size * 0.05)}px + var(--orb-level, 0) * ${Math.round(size * 0.14)}px) color-mix(in oklab, ${to} 50%, transparent), inset 0 0 ${Math.round(size * 0.04)}px color-mix(in oklab, ${from} 55%, transparent)`,
  transform: 'scaleY(calc(1 + var(--orb-level, 0) * 0.05))',
  transition: 'opacity 0.4s ease',
});

export const SiriSheet = ({
  state = 'idle',
  size = 168,
  speed = 1,
  colorFrom = '#82f4ff',
  colorTo = '#8e6cff',
  levelRef,
  label = 'Siri Sheet orb',
  className,
  ref,
}: OrbProps) => {
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const colorRef = useRef({ from: colorFrom, to: colorTo });
  const drawRef = useRef<((frame: OrbFrame) => void) | null>(null);
  const motionRef = useRef({ sheet: 1.7, lastPhase: 0, errorAge: SHAKE_TIME, prevState: state });
  const [lost, setLost] = useState(false);
  const support = useWebGLSupport();
  const showCanvas = support === true && !lost;

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      hostRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );


  const onFrame = useCallback((frame: OrbFrame) => {
    const host = hostRef.current;
    const motion = motionRef.current;
    if (frame.state === 'error' && motion.prevState !== 'error') motion.errorAge = 0;
    motion.prevState = frame.state;
    motion.errorAge = Math.min(SHAKE_TIME, motion.errorAge + frame.dt);
    if (host) {
      host.style.setProperty('--orb-level', frame.level.toFixed(3));
      const age = motion.errorAge;
      const shake =
        frame.reduced || age >= SHAKE_TIME
          ? 0
          : Math.sin(age * Math.PI * 2 * 7) * Math.sin((Math.PI * age) / SHAKE_TIME) * 0.022;
      host.style.transform = shake === 0 ? '' : `translateX(${(shake * 100).toFixed(2)}%)`;
    }
    drawRef.current?.(frame);
  }, []);

  const { frameRef } = useOrbAnimator(hostRef, { state, levelRef, speed, onFrame });

  useEffect(() => {
    if (!showCanvas) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const gl = canvas.getContext('webgl', {
      alpha: true,
      antialias: false,
      premultipliedAlpha: true,
      powerPreference: 'low-power',
    });
    if (!gl) {
      setLost(true);
      return;
    }

    const compile = (type: number, source: string): WebGLShader | null => {
      const shader = gl.createShader(type);
      if (!shader) return null;
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
        gl.deleteShader(shader);
        return null;
      }
      return shader;
    };

    const vert = compile(gl.VERTEX_SHADER, VERT);
    const frag = compile(gl.FRAGMENT_SHADER, FRAG);
    const program = gl.createProgram();
    const dropResources = () => {
      if (vert) gl.deleteShader(vert);
      if (frag) gl.deleteShader(frag);
      if (program) gl.deleteProgram(program);
    };
    if (!vert || !frag || !program) {
      dropResources();
      setLost(true);
      return;
    }
    gl.attachShader(program, vert);
    gl.attachShader(program, frag);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      dropResources();
      setLost(true);
      return;
    }
    gl.useProgram(program);

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const px = Math.max(1, Math.round(size * dpr));
    canvas.width = px;
    canvas.height = px;
    gl.viewport(0, 0, px, px);

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const aPos = gl.getAttribLocation(program, 'aPos');
    gl.enableVertexAttribArray(aPos);
    gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

    const loc = {} as Record<UniformName, WebGLUniformLocation | null>;
    for (const name of UNIFORMS) loc[name] = gl.getUniformLocation(program, name);
    gl.uniform1f(loc.uSize, px);

    const errFrom = hexToRgb(ERROR_COLOR_FROM);
    const errTo = hexToRgb(ERROR_COLOR_TO);
    const set3 = (name: UniformName, v: Vec3) => gl.uniform3f(loc[name], v[0], v[1], v[2]);

    drawRef.current = (frame) => {
      const w = frame.weights;
      const p = blendStates(w, STATE_TABLE);
      const level = clamp01(frame.level);
      const motion = motionRef.current;
      const dPhase = Math.max(0, frame.phase - motion.lastPhase);
      motion.lastPhase = frame.phase;
      const voice = p.voice * level;
      motion.sheet += dPhase * p.speed * (1 + 0.7 * voice);

      const baseFrom = hexToRgb(colorRef.current.from);
      const baseTo = hexToRgb(colorRef.current.to);
      const from = mixRgb(baseFrom, errFrom, w.error);
      const to = mixRgb(baseTo, errTo, w.error);
      const pal = buildPalette(from, to, clamp01(p.mute));

      gl.uniform1f(loc.uPhase, motion.sheet);
      gl.uniform1f(loc.uLevel, level);
      gl.uniform1f(loc.uWarp, p.warp * 3.2 + 0.85 * voice);
      gl.uniform1f(loc.uRidge, p.ridge + 0.35 * voice + 0.25 * p.hear * level);
      gl.uniform1f(loc.uSharp, p.sharp * 2.2);
      gl.uniform1f(loc.uZoom, p.zoom);
      gl.uniform1f(loc.uExposure, p.exposure * 1.9 * (1 + 0.12 * voice + 0.1 * p.hear * level));
      gl.uniform1f(loc.uGlow, p.glow * 0.45);
      gl.uniform1f(loc.uRim, p.rim);
      gl.uniform1f(loc.uHear, p.hear);
      gl.uniform1f(loc.uFade, p.fade);
      set3('uColA', pal.a);
      set3('uColB', pal.b);
      set3('uColC', pal.c);
      set3('uColD', pal.d);
      set3('uHi', pal.hi);
      set3('uCool', pal.cool);
      set3('uWarm', pal.warm);
      set3('uGlowCol', pal.glow);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    drawRef.current(frameRef.current);

    const onLost = (event: Event) => {
      event.preventDefault();
      drawRef.current = null;
      setLost(true);
    };
    canvas.addEventListener('webglcontextlost', onLost);

    return () => {
      drawRef.current = null;
      canvas.removeEventListener('webglcontextlost', onLost);
      gl.deleteBuffer(buffer);
      dropResources();
    };
  }, [size, showCanvas, frameRef]);

  useEffect(() => {
    colorRef.current = { from: colorFrom, to: colorTo };
    drawRef.current?.(frameRef.current);
  }, [colorFrom, colorTo, frameRef]);

  const isError = state === 'error';
  const isDisabled = state === 'disabled';
  const fallbackOpacity = state === 'idle' ? 0.82 : state === 'connecting' ? 0.9 : 1;

  return (
    <div
      ref={setRefs}
      role="img"
      aria-label={label}
      data-state={state}
      className={className}
      style={{
        ...orbVars({ size, speed, colorFrom, colorTo }),
        width: size,
        height: size,
        position: 'relative',
        display: 'grid',
        placeItems: 'center',
      }}
    >
      {showCanvas ? (
        <canvas ref={canvasRef} aria-hidden style={{ width: size, height: size }} />
      ) : (
        <div
          aria-hidden
          style={{
            width: '100%',
            height: '100%',
            position: 'relative',
            opacity: isDisabled ? 0.5 : fallbackOpacity,
            filter: isDisabled ? 'grayscale(0.85)' : 'grayscale(0)',
            transition: 'opacity 0.4s ease, filter 0.4s ease',
          }}
        >
          <div style={{ ...fallbackLayer(colorFrom, colorTo, size), opacity: isError ? 0 : 1 }} />
          <div style={{ ...fallbackLayer(ERROR_COLOR_FROM, ERROR_COLOR_TO, size), opacity: isError ? 1 : 0 }} />
        </div>
      )}
    </div>
  );
};

'use client';

import { useCallback, useEffect, useRef } from 'react';
import {
  ERROR_COLOR_FROM,
  ERROR_COLOR_TO,
  approach,
  blendStates,
  clamp01,
  hexToRgb,
  orbVars,
  type OrbProps,
  type OrbState,
} from '@/registry/lib/orb-state';
import { mixRgb, rgba, type Rgb } from '@/registry/lib/orb-color';
import { useOrbAnimator, type OrbFrame } from '@/registry/lib/use-orb-animator';
import { useReducedMotion } from '@/registry/lib/use-reduced-motion';

const CURVES = 4;
const SAMPLES = 120;
const X_RANGE = 2;

interface WaveParams extends Record<string, number> {
  amp: number;
  ampLevel: number;
  freq: number;
  freqLevel: number;
  flow: number;
  spread: number;
  width: number;
  wobble: number;
  jitter: number;
  line: number;
  dim: number;
  fill: number;
  f0: number;
  f1: number;
  f2: number;
  f3: number;
}

const PARAMS: Record<OrbState, WaveParams> = {
  idle: { amp: 0.035, ampLevel: 0, freq: 1.6, freqLevel: 0, flow: 0.7, spread: 0.35, width: 1.5, wobble: 0.35, jitter: 0, line: 0.6, dim: 1, fill: 0.22, f0: 1, f1: 0.7, f2: 0.5, f3: 0.35 },
  connecting: { amp: 0.26, ampLevel: 0.05, freq: 2.6, freqLevel: 0, flow: 1.4, spread: 0, width: 0.5, wobble: 0.1, jitter: 0, line: 0.45, dim: 0.92, fill: 0.28, f0: 1, f1: 0.3, f2: 0.18, f3: 0.1 },
  listening: { amp: 0.06, ampLevel: 0.5, freq: 2.6, freqLevel: 1.6, flow: 2.4, spread: 0.55, width: 1, wobble: 0.3, jitter: 0, line: 0.35, dim: 1, fill: 0.26, f0: 1, f1: 0.8, f2: 0.65, f3: 0.5 },
  thinking: { amp: 0.22, ampLevel: 0.05, freq: 3.4, freqLevel: 0, flow: 2, spread: 0, width: 0.5, wobble: 0.15, jitter: 0, line: 0.4, dim: 1, fill: 0.28, f0: 1, f1: 0.85, f2: 0.7, f3: 0.55 },
  speaking: { amp: 0.06, ampLevel: 0.6, freq: 2.8, freqLevel: 3.2, flow: 3.4, spread: 1, width: 1.05, wobble: 0.3, jitter: 0, line: 0.25, dim: 1, fill: 0.3, f0: 1, f1: 0.9, f2: 0.8, f3: 0.7 },
  error: { amp: 0.13, ampLevel: 0, freq: 7.5, freqLevel: 0, flow: 4, spread: 0.2, width: 0.55, wobble: 0, jitter: 0.8, line: 0.45, dim: 1, fill: 0.3, f0: 1, f1: 0.8, f2: 0.6, f3: 0.45 },
  disabled: { amp: 0.006, ampLevel: 0, freq: 1.2, freqLevel: 0, flow: 0.2, spread: 0.2, width: 1.8, wobble: 0, jitter: 0, line: 0.35, dim: 0.45, fill: 0.15, f0: 1, f1: 0.3, f2: 0.2, f3: 0.1 },
};

const BASE_CENTER = [-0.35, 0.4, 0.05, -0.7];
const FREQ_MUL = [1, 1.3, 0.75, 1.55];
const FLOW_MUL = [1, 1.2, 0.85, 1.4];
const WOBBLE_RATE = [1.3, 1.7, 2.1, 1.1];
const SEED = [0.3, 2.1, 4.2, 5.4];
const BLACK: Rgb = [0, 0, 0];
const WHITE: Rgb = [255, 255, 255];

const readDark = (): boolean => {
  const cl = document.documentElement.classList;
  if (cl.contains('dark')) return true;
  if (cl.contains('light')) return false;
  return window.matchMedia('(prefers-color-scheme: dark)').matches;
};

const desaturate = (c: Rgb, t: number): Rgb => {
  const g = c[0] * 0.2126 + c[1] * 0.7152 + c[2] * 0.0722;
  return mixRgb(c, [g, g, g], t);
};

export const SiriWaveLine = ({
  state = 'idle',
  size = 168,
  speed = 1,
  colorFrom = '#22d3ee',
  colorTo = '#e879f9',
  levelRef,
  label = 'Siri Wave Line orb',
  className,
  ref: externalRef,
}: OrbProps) => {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const colorRef = useRef({ from: colorFrom, to: colorTo });
  const rendererRef = useRef<((frame: OrbFrame, dt: number) => void) | null>(null);
  const reduced = useReducedMotion();

  const onFrame = useCallback((frame: OrbFrame) => rendererRef.current?.(frame, frame.dt), []);
  const { frameRef } = useOrbAnimator(hostRef, { state, levelRef, speed, onFrame });

  const setHostRef = useCallback(
    (node: HTMLDivElement | null) => {
      hostRef.current = node;
      if (typeof externalRef === 'function') externalRef(node);
      else if (externalRef) externalRef.current = node;
    },
    [externalRef],
  );

  useEffect(() => {
    colorRef.current = { from: colorFrom, to: colorTo };
    rendererRef.current?.(frameRef.current, 0);
  }, [colorFrom, colorTo, frameRef]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(size * dpr);
    canvas.height = Math.round(size * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const cy = size / 2;
    const pad = size * 0.04;
    const halfH = size * 0.5;
    const unit = size / 168;
    const xs = new Float32Array(SAMPLES);
    const xn = new Float32Array(SAMPLES);
    const edge = new Float32Array(SAMPLES);
    const ys = new Float32Array(SAMPLES);
    for (let j = 0; j < SAMPLES; j += 1) {
      const u = j / (SAMPLES - 1);
      xs[j] = pad + u * (size - pad * 2);
      xn[j] = (u * 2 - 1) * X_RANGE;
      const e = 1 - (u * 2 - 1) ** 2;
      edge[j] = e * e;
    }

    const ampS = new Float32Array(CURVES);
    const centerS = new Float32Array(CURVES);
    const phs = new Float32Array(CURVES);
    for (let i = 0; i < CURVES; i += 1) {
      centerS[i] = BASE_CENTER[i] * 0.35;
      phs[i] = SEED[i];
    }
    const factors = new Float32Array(CURVES);
    const fillStr: string[] = ['', '', '', ''];
    const glowGrad: (CanvasGradient | null)[] = [null, null, null, null];
    const lineGrad: (CanvasGradient | null)[] = [null, null, null, null];
    let baseGrad: CanvasGradient | null = null;
    let freqS = PARAMS.idle.freq;
    let prevPhase = frameRef.current.phase;
    let dark = readDark();
    let lightMix = dark ? 0 : 1;
    let colorKey = '';
    let first = true;

    const errFrom = hexToRgb(ERROR_COLOR_FROM);
    const errTo = hexToRgb(ERROR_COLOR_TO);

    const edgeGradient = (c: Rgb) => {
      const g = ctx.createLinearGradient(pad, 0, size - pad, 0);
      g.addColorStop(0, rgba(c, 0));
      g.addColorStop(0.18, rgba(c, 0.55));
      g.addColorStop(0.5, rgba(c, 1));
      g.addColorStop(0.82, rgba(c, 0.55));
      g.addColorStop(1, rgba(c, 0));
      return g;
    };

    const ensureColors = (errW: number, disW: number) => {
      const { from, to } = colorRef.current;
      const key = `${from}|${to}|${Math.round(errW * 100)}|${Math.round(disW * 100)}|${Math.round(lightMix * 100)}`;
      if (key === colorKey) return;
      colorKey = key;
      const a = mixRgb(hexToRgb(from), errFrom, errW);
      const b = mixRgb(hexToRgb(to), errTo, errW);
      const palette: Rgb[] = [a, b, mixRgb(a, b, 0.5), mixRgb(mixRgb(a, b, 0.25), WHITE, 0.2)];
      for (let i = 0; i < CURVES; i += 1) {
        const base = mixRgb(desaturate(palette[i], disW * 0.8), BLACK, lightMix * 0.2);
        fillStr[i] = rgba(base, 1);
        glowGrad[i] = edgeGradient(base);
        lineGrad[i] = edgeGradient(mixRgb(base, mixRgb(WHITE, BLACK, lightMix), 0.3 - lightMix * 0.12));
      }
      const mid = mixRgb(desaturate(mixRgb(a, b, 0.5), disW * 0.8), BLACK, lightMix * 0.25);
      baseGrad = edgeGradient(mid);
    };

    const render = (frame: OrbFrame, dt: number) => {
      const w = frame.weights;
      const p = blendStates(w, PARAMS);
      const snap = frame.reduced || first;
      first = false;
      const dPhase = frame.phase - prevPhase;
      prevPhase = frame.phase;
      const level = clamp01(frame.level);

      lightMix = frame.reduced ? (dark ? 0 : 1) : approach(lightMix, dark ? 0 : 1, 6, dt);
      ensureColors(clamp01(w.error), clamp01(w.disabled));

      const targetFreq = p.freq + p.freqLevel * level;
      freqS = snap ? targetFreq : approach(freqS, targetFreq, 6, dt);
      factors[0] = p.f0;
      factors[1] = p.f1;
      factors[2] = p.f2;
      factors[3] = p.f3;
      const baseAmp = p.amp + p.ampLevel * level;
      const thinkT = frame.phase * 1.3;
      const sweep = Math.sin(frame.phase * 0.8) * 1.3;

      for (let i = 0; i < CURVES; i += 1) {
        const target = baseAmp * factors[i];
        const rate = target > ampS[i] ? 12 : 5;
        ampS[i] = snap ? target : approach(ampS[i], target, rate, dt);
        const center =
          p.spread * BASE_CENTER[i] +
          w.thinking * Math.sin(thinkT + i * 1.35) * 1.2 +
          w.connecting * sweep;
        centerS[i] = snap ? center : approach(centerS[i], center, 10, dt);
        phs[i] += dPhase * p.flow * FLOW_MUL[i];
      }

      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
      ctx.clearRect(0, 0, size, size);

      const dim = p.dim;
      if (baseGrad) {
        ctx.globalAlpha = clamp01(p.line * dim * (1 + lightMix * 0.3));
        ctx.fillStyle = baseGrad;
        ctx.fillRect(pad, cy - 0.5 * unit, size - pad * 2, unit);
      }

      for (let pass = 0; pass < 2; pass += 1) {
        const passW = pass === 0 ? 1 - lightMix : lightMix;
        if (passW < 0.004) continue;
        ctx.globalCompositeOperation = pass === 0 ? 'lighter' : 'source-over';
        const fillBoost = pass === 0 ? 1 : 1.25;
        for (let k = CURVES - 1; k >= 0; k -= 1) {
          const wob = 1 - p.wobble * (0.5 + 0.5 * Math.sin(frame.phase * WOBBLE_RATE[k] + SEED[k]));
          const jit =
            1 +
            p.jitter *
              (0.6 * Math.sin(frame.phase * 31 + k * 1.7) + 0.4 * Math.sin(frame.phase * 47 + k * 2.9));
          const amp = ampS[k] * wob * jit * halfH;
          if (amp < 0.05) continue;
          const width = Math.max(0.2, p.width);
          const c = centerS[k];
          const fk = freqS * FREQ_MUL[k];
          const ph = phs[k];
          for (let j = 0; j < SAMPLES; j += 1) {
            const u = (xn[j] - c) / width;
            const u4 = u * u * u * u;
            const env = 2 / (2 + u4);
            ys[j] = amp * env * env * edge[j] * Math.sin(fk * xn[j] - ph);
          }
          ctx.beginPath();
          ctx.moveTo(xs[0], cy - ys[0]);
          for (let j = 1; j < SAMPLES; j += 1) ctx.lineTo(xs[j], cy - ys[j]);
          for (let j = SAMPLES - 1; j >= 0; j -= 1) ctx.lineTo(xs[j], cy + ys[j]);
          ctx.closePath();

          ctx.globalAlpha = clamp01(p.fill * dim * passW * fillBoost);
          ctx.fillStyle = fillStr[k];
          ctx.fill();

          ctx.globalAlpha = clamp01(0.14 * dim * passW);
          ctx.strokeStyle = glowGrad[k] ?? fillStr[k];
          ctx.lineWidth = 4.5 * unit;
          ctx.stroke();

          ctx.globalAlpha = clamp01(0.85 * dim * passW);
          ctx.strokeStyle = lineGrad[k] ?? fillStr[k];
          ctx.lineWidth = 1.1 * unit;
          ctx.stroke();
        }
      }
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
    };

    const redraw = () => render(frameRef.current, 0);
    const syncTheme = () => {
      dark = readDark();
      redraw();
    };
    const observer = new MutationObserver(syncTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
    const scheme = window.matchMedia('(prefers-color-scheme: dark)');
    scheme.addEventListener('change', syncTheme);

    rendererRef.current = render;
    redraw();

    return () => {
      rendererRef.current = null;
      observer.disconnect();
      scheme.removeEventListener('change', syncTheme);
    };
  }, [size, frameRef]);

  useEffect(() => {
    if (state !== 'error' || reduced) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const shake = canvas.animate(
      [
        { transform: 'translateX(0)' },
        { transform: 'translateX(-1.5px)' },
        { transform: 'translateX(3px)' },
        { transform: 'translateX(-2px)' },
        { transform: 'translateX(1px)' },
        { transform: 'translateX(0)' },
      ],
      { duration: 340, easing: 'ease-out' },
    );
    return () => shake.cancel();
  }, [state, reduced]);

  return (
    <div
      ref={setHostRef}
      role="img"
      aria-label={label}
      data-state={state}
      className={className}
      style={{
        ...orbVars({ size, speed, colorFrom, colorTo }),
        width: size,
        height: size,
        display: 'grid',
        placeItems: 'center',
      }}
    >
      <canvas ref={canvasRef} aria-hidden style={{ width: size, height: size }} />
    </div>
  );
};

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  approach,
  blendStates,
  clamp01,
  ERROR_COLOR_FROM,
  ERROR_COLOR_TO,
  hexToRgb,
  orbVars,
  type OrbProps,
  type OrbState,
} from '../../lib/orb-state';
import { mixRgb, rgba, type Rgb } from '../../lib/orb-color';
import { useOrbAnimator, type OrbFrame } from '../../lib/use-orb-animator';
import { useWaveform } from '../../lib/use-waveform';

const TWO_PI = Math.PI * 2;
const SEGMENTS = 160;
const COLOR_BUCKETS = 16;
const ALPHA_BUCKETS = 6;
const BUCKETS = COLOR_BUCKETS * ALPHA_BUCKETS;
const TIME_OFFSET = 4.2;
const LIVE_FADE_RATE = 12;

const ERR_FROM = hexToRgb(ERROR_COLOR_FROM);
const ERR_TO = hexToRgb(ERROR_COLOR_TO);
const ERR_MID = mixRgb(ERR_FROM, ERR_TO, 0.5);

type StateParams = {
  tempo: number;
  amp: number;
  levelAmp: number;
  bias: number;
  breathe: number;
  contract: number;
  echo: number;
  echoRate: number;
  dash: number;
  liveGain: number;
  core: number;
  coreGain: number;
  glowGain: number;
  lineGain: number;
  rest: number;
};

const STATES: Record<OrbState, StateParams> = {
  idle: { tempo: 1, amp: 0.03, levelAmp: 0, bias: 0, breathe: 0.02, contract: 0, echo: 0, echoRate: 1, dash: 0, liveGain: 0.5, core: 0.5, coreGain: 0.2, glowGain: 0.3, lineGain: 0.4, rest: 0 },
  connecting: { tempo: 1, amp: 0.04, levelAmp: 0, bias: 0, breathe: 0.01, contract: 0.5, echo: 0.55, echoRate: 0.5, dash: 1, liveGain: 0.2, core: 0.45, coreGain: 0.2, glowGain: 0.3, lineGain: 0.3, rest: 0.12 },
  listening: { tempo: 1, amp: 0.1, levelAmp: 0.14, bias: 0.85, breathe: 0, contract: 0, echo: 0, echoRate: 1, dash: 0, liveGain: 1, core: 0.35, coreGain: 0.15, glowGain: 1.4, lineGain: 1.2, rest: 0.6 },
  thinking: { tempo: 1, amp: 0.05, levelAmp: 0, bias: 0, breathe: 0, contract: 1, echo: 1, echoRate: 1, dash: 0, liveGain: 0.25, core: 0.5, coreGain: 0.3, glowGain: 0.4, lineGain: 0.4, rest: 0.3 },
  speaking: { tempo: 1, amp: 0.1, levelAmp: 0.12, bias: -0.55, breathe: 0, contract: 0, echo: 0, echoRate: 1, dash: 0, liveGain: 0.6, core: 0.55, coreGain: 0.9, glowGain: 0.5, lineGain: 0.8, rest: 0.6 },
  error: { tempo: 1, amp: 0.11, levelAmp: 0, bias: 0, breathe: 0, contract: 0, echo: 0, echoRate: 1, dash: 0, liveGain: 0.1, core: 0.5, coreGain: 0.2, glowGain: 0.3, lineGain: 0.3, rest: 0.2 },
  disabled: { tempo: 0.04, amp: 0.008, levelAmp: 0, bias: 0, breathe: 0, contract: 0, echo: 0, echoRate: 1, dash: 0, liveGain: 0, core: 0.28, coreGain: 0, glowGain: 0, lineGain: 0, rest: 0 },
};

const SEG_COLOR = new Uint8Array(SEGMENTS);
for (let i = 0; i < SEGMENTS; i += 1) {
  const u = (i + 0.5) / SEGMENTS;
  const g = u < 0.5 ? u * 2 : (1 - u) * 2;
  SEG_COLOR[i] = Math.min(COLOR_BUCKETS - 1, Math.floor(g * COLOR_BUCKETS));
}

const jag = (u: number, t: number) =>
  Math.sign(Math.sin(TWO_PI * 19 * u + t * 1.9)) *
  (0.5 + 0.5 * Math.abs(Math.sin(TWO_PI * 7 * u - t * 2.4)));

const sampleWave = (u: number, data: Uint8Array): number => {
  const m = u < 0.5 ? u * 2 : (1 - u) * 2;
  const pos = m * (data.length - 1);
  const i0 = Math.floor(pos);
  const i1 = Math.min(i0 + 1, data.length - 1);
  const f = pos - i0;
  const v = data[i0] + (data[i1] - data[i0]) * f;
  return Math.max(-1, Math.min(1, ((v - 128) / 128) * 1.6));
};

export const WaveformRing = ({
  state = 'idle',
  size = 168,
  speed = 1,
  colorFrom = '#2dd4bf',
  colorTo = '#38bdf8',
  levelRef,
  label = 'Waveform Ring orb',
  className,
  ref: externalRef,
}: OrbProps) => {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const colorRef = useRef({ from: colorFrom, to: colorTo });
  const drawRef = useRef<((frame: OrbFrame) => void) | null>(null);
  const liveRef = useRef(false);
  const [live, setLive] = useState(false);

  const { samplesRef } = useWaveform(live);

  const setHostRef = useCallback(
    (node: HTMLDivElement | null) => {
      hostRef.current = node;
      if (typeof externalRef === 'function') externalRef(node);
      else if (externalRef) externalRef.current = node;
    },
    [externalRef],
  );

  const onFrame = useCallback((frame: OrbFrame) => {
    if (frame.live !== liveRef.current) {
      liveRef.current = frame.live;
      setLive(frame.live);
    }
    drawRef.current?.(frame);
  }, []);

  const { frameRef } = useOrbAnimator(hostRef, { state, levelRef, speed, onFrame });

  useEffect(() => {
    colorRef.current = { from: colorFrom, to: colorTo };
    drawRef.current?.({ ...frameRef.current, dt: 0 });
  }, [colorFrom, colorTo, frameRef]);

  useEffect(() => {
    const host = hostRef.current;
    const canvas = canvasRef.current;
    if (!host || !canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = size * dpr;
    canvas.height = size * dpr;

    const cx = size / 2;
    const R = size * 0.355;

    const makeCore = (col: Rgb) => {
      const g = ctx.createRadialGradient(cx, cx, 0, cx, cx, R);
      g.addColorStop(0, rgba(col, 0.3));
      g.addColorStop(0.68, rgba(col, 0.1));
      g.addColorStop(1, rgba(col, 0));
      return g;
    };
    const errCoreG = makeCore(ERR_MID);

    let paletteKey = '';
    let colorKey = '';
    let from: Rgb = [255, 255, 255];
    let to: Rgb = [255, 255, 255];
    let mid: Rgb = [255, 255, 255];
    let coreG: CanvasGradient | null = null;
    let echoStyle = '#fff';
    const colorStyles: string[] = new Array<string>(COLOR_BUCKETS).fill('#fff');

    const ensurePalette = (errorW: number) => {
      const key = `${colorRef.current.from}|${colorRef.current.to}`;
      if (key !== paletteKey) {
        paletteKey = key;
        from = hexToRgb(colorRef.current.from);
        to = hexToRgb(colorRef.current.to);
        mid = mixRgb(from, to, 0.5);
        coreG = makeCore(mid);
      }
      const errStep = Math.round(errorW * 64);
      const nextColorKey = `${key}|${errStep}`;
      if (nextColorKey === colorKey) return;
      colorKey = nextColorKey;
      const e = errStep / 64;
      for (let b = 0; b < COLOR_BUCKETS; b += 1) {
        const g = (b + 0.5) / COLOR_BUCKETS;
        const base = mixRgb(from, to, g);
        colorStyles[b] = rgba(e > 0 ? mixRgb(base, mixRgb(ERR_FROM, ERR_TO, g), e) : base, 1);
      }
      echoStyle = rgba(mixRgb(mid, ERR_MID, e), 1);
    };

    const xs = new Float32Array(SEGMENTS + 1);
    const ys = new Float32Array(SEGMENTS + 1);
    const wave = new Float32Array(SEGMENTS + 1);
    const bucketOf = new Uint8Array(SEGMENTS);
    const counts = new Uint16Array(BUCKETS);
    const starts = new Uint16Array(BUCKETS);
    const order = new Uint16Array(SEGMENTS);

    let lastPhase = frameRef.current.phase;
    let lastLevelText = '';
    let clock = 0;
    let echoClock = 0;
    let rot = 0;
    let liveFade = 0;

    const draw = (frame: OrbFrame) => {
      const w = frame.weights;
      const p = blendStates(w, STATES);
      const dPhase = Math.max(0, frame.phase - lastPhase);
      lastPhase = frame.phase;
      const levelText = frame.level.toFixed(3);
      if (levelText !== lastLevelText) {
        lastLevelText = levelText;
        host.style.setProperty('--orb-level', levelText);
      }
      const level = clamp01(frame.reduced ? p.rest : frame.level);

      clock += dPhase * p.tempo;
      echoClock += dPhase * p.tempo * p.echoRate * 0.45;
      rot += dPhase * 2.8 * p.tempo;
      const t = clock + TIME_OFFSET;

      const data = samplesRef.current;
      const hasWave = frame.live && data.length > 0;
      if (hasWave) {
        for (let i = 0; i <= SEGMENTS; i += 1) wave[i] = sampleWave(i / SEGMENTS, data);
      }
      const fadeTarget = hasWave ? 1 : 0;
      liveFade = frame.reduced ? fadeTarget : approach(liveFade, fadeTarget, LIVE_FADE_RATE, frame.dt);
      if (liveFade < 0.001) liveFade = 0;
      const liveMix = clamp01(liveFade * p.liveGain);

      const amp = p.amp + level * p.levelAmp;
      const breathe = 1 + p.breathe * Math.sin(t * 1.1) + level * 0.02;
      const contract = 1 - p.contract * (0.05 + 0.05 * Math.sin((echoClock + TIME_OFFSET) * 5.8));
      const baseR = R * breathe * contract;
      const bias = p.bias;
      const absBias = Math.abs(bias);
      const dashW = clamp01(p.dash);

      for (let i = 0; i <= SEGMENTS; i += 1) {
        const u = i / SEGMENTS;
        const theta = u * TWO_PI - Math.PI / 2;
        let proc = 0;
        if (w.idle > 0) proc += w.idle * Math.sin(TWO_PI * 2 * u + t * 0.9);
        if (w.connecting > 0) proc += w.connecting * Math.sin(TWO_PI * 3 * u - t * 1.2);
        if (w.listening > 0) {
          proc +=
            w.listening *
            (0.62 * Math.sin(TWO_PI * 6 * u + t * 7.2) + 0.38 * Math.sin(TWO_PI * 11 * u - t * 9.6));
        }
        if (w.thinking > 0) proc += w.thinking * Math.sin(TWO_PI * 3 * u + t * 2.1);
        if (w.speaking > 0) {
          proc +=
            w.speaking *
            (0.5 * Math.sin(TWO_PI * 4 * u + t * 5.3) +
              0.32 * Math.sin(TWO_PI * 9 * u + t * 8.9) +
              0.26 * Math.sin(TWO_PI * 15 * u - t * 6.4));
        }
        if (w.error > 0) proc += w.error * jag(u, t);
        const mixed = liveMix > 0 ? proc + (wave[i] - proc) * liveMix : proc;
        const shape = mixed * (1 - absBias) + Math.abs(mixed) * bias;
        const r = baseR + shape * amp * R;
        xs[i] = cx + Math.cos(theta) * r;
        ys[i] = cx + Math.sin(theta) * r;
      }

      counts.fill(0);
      for (let i = 0; i < SEGMENTS; i += 1) {
        const theta = ((i + 0.5) / SEGMENTS) * TWO_PI - Math.PI / 2;
        const dash = dashW > 0.004 ? 0.5 + 0.5 * Math.tanh(Math.sin(theta * 7 - rot) * 5) : 1;
        const alpha = 1 - dashW * (1 - dash);
        const ab = Math.round(alpha * (ALPHA_BUCKETS - 1));
        const b = SEG_COLOR[i] * ALPHA_BUCKETS + ab;
        bucketOf[i] = b;
        counts[b] += 1;
      }
      let acc = 0;
      for (let b = 0; b < BUCKETS; b += 1) {
        starts[b] = acc;
        acc += counts[b];
      }
      for (let i = 0; i < SEGMENTS; i += 1) {
        const b = bucketOf[i];
        order[starts[b]] = i;
        starts[b] += 1;
      }

      ensurePalette(w.error);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
      ctx.clearRect(0, 0, size, size);

      const alphaMul = 1 - 0.45 * w.disabled;
      const coreA = clamp01(p.core + level * p.coreGain) * alphaMul;
      if (coreG && w.error < 0.996) {
        ctx.globalAlpha = coreA * (1 - w.error);
        ctx.fillStyle = coreG;
        ctx.fillRect(0, 0, size, size);
      }
      if (w.error > 0.004) {
        ctx.globalAlpha = coreA * w.error;
        ctx.fillStyle = errCoreG;
        ctx.fillRect(0, 0, size, size);
      }

      if (p.echo > 0.004) {
        ctx.strokeStyle = echoStyle;
        ctx.lineWidth = 1.2;
        for (let k = 0; k < 2; k += 1) {
          const phase = (echoClock + k * 0.5) % 1;
          const ea = p.echo * phase * (1 - phase) * 1.6 * alphaMul;
          if (ea <= 0.004) continue;
          ctx.globalAlpha = clamp01(ea);
          ctx.beginPath();
          ctx.arc(cx, cx, R * (1.02 - phase * 0.72), 0, TWO_PI);
          ctx.stroke();
        }
      }

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      for (let pass = 0; pass < 2; pass += 1) {
        const glowPass = pass === 0;
        ctx.globalCompositeOperation = glowPass ? 'lighter' : 'source-over';
        ctx.lineWidth = glowPass
          ? 5.5 + level * 6 * p.glowGain
          : Math.max(0.7, 1.7 + level * 1.5 * p.lineGain - w.disabled * 0.8);
        const passAlpha = (glowPass ? 0.16 : 0.92) * alphaMul;
        let cursor = 0;
        for (let b = 0; b < BUCKETS; b += 1) {
          const count = counts[b];
          if (count === 0) continue;
          const ab = b % ALPHA_BUCKETS;
          const a = passAlpha * (ab / (ALPHA_BUCKETS - 1));
          if (a > 0.004) {
            ctx.globalAlpha = a;
            ctx.strokeStyle = colorStyles[(b - ab) / ALPHA_BUCKETS];
            ctx.beginPath();
            let prev = -2;
            for (let k = cursor; k < cursor + count; k += 1) {
              const i = order[k];
              if (i !== prev + 1) ctx.moveTo(xs[i], ys[i]);
              ctx.lineTo(xs[i + 1], ys[i + 1]);
              prev = i;
            }
            ctx.stroke();
          }
          cursor += count;
        }
      }
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
    };

    drawRef.current = draw;
    draw({ ...frameRef.current, dt: 0 });

    return () => {
      drawRef.current = null;
    };
  }, [size, samplesRef, frameRef]);

  return (
    <div
      ref={setHostRef}
      role="img"
      aria-label={label}
      data-state={state}
      className={className}
      style={{
        ...orbVars({ size, speed, colorFrom, colorTo }),
        width: size,
        height: size,
        display: 'grid',
        placeItems: 'center',
        opacity: state === 'disabled' ? 0.5 : 1,
        filter: state === 'disabled' ? 'grayscale(0.85)' : 'grayscale(0)',
        transition: 'opacity 0.3s ease, filter 0.3s ease',
      }}
    >
      <canvas ref={canvasRef} aria-hidden style={{ width: size, height: size }} />
    </div>
  );
};

/**
 * Cue Foundations · 3D Book Carousel Reading Mode
 * ────────────────────────────────────────────
 * A perspective-driven CSS 3D shelf of books that morphs spines into covers as you scroll, opening into a two-phase rise-and-swing reading spread.
 *
 * The full AI prompt used to design this lives at:
 *   lib/prompts/3d-book-carousel-reading-mode.md
 *
 * Awwwards-tier premium version → https://cuedesign.space/component/cue074
 *
 * Original Cue ID: cue074
 * Category: 3D & WebGL
 * ────────────────────────────────────────────
 */

/**
 * 3D Book Carousel — Personal Curation with Reading Mode
 *
 * Zero deps. CSS 3D transforms + RAF loop.
 *
 * Usage:
 *   <BookCarousel3D books={books} initialIndex={7} onOpenBook={(i, b) => log(b)} />
 *
 * Font links (add to global head):
 *   <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
 */

import React, { useEffect, useRef, useState } from 'react';

export interface Book {
  title: string;
  color: string;
  textColor: string;
  spineW: number;      // spine width in px
  h: number;           // book height in px
  rotZ?: number;
  img?: string;
  isMain?: boolean;
}

interface BookCarousel3DProps {
  books?: Book[];
  initialIndex?: number;
  onOpenBook?: (index: number, book: Book) => void;
}

const DEFAULT_BOOKS: Book[] = [
  { title: 'DESIGN & ILLUSTRATION', color: '#FFC82C', textColor: '#111', spineW: 50, h: 330, img: 'https://i.pinimg.com/736x/aa/fc/98/aafc9885e670f6473561bdb46b6f78c8.jpg' },
  { title: 'Made in North Korea',   color: '#D661A3', textColor: '#fff', spineW: 25, h: 300, img: 'https://i.pinimg.com/736x/3f/7b/19/3f7b1918ce4af46d415765bedd9a2034.jpg' },
  { title: 'DESIGN BY ACCIDENT',    color: '#2E5296', textColor: '#fff', spineW: 70, h: 370, img: 'https://i.pinimg.com/736x/d2/4b/42/d24b420671770075dbadfc74f14dd64a.jpg' },
  { title: 'The creative act',      color: '#E03F35', textColor: '#fff', spineW: 20, h: 350, rotZ: -2.5, img: 'https://i.pinimg.com/736x/9d/e4/54/9de454a3fe3e35afd3e6449e70178561.jpg' },
  { title: 'S M L XL',              color: '#7C3AED', textColor: '#fff', spineW: 35, h: 360, img: 'https://i.pinimg.com/1200x/80/04/48/800448a167edfba20cd2f87208845428.jpg' },
  { title: 'OPTIC',                 color: '#D97706', textColor: '#fff', spineW: 50, h: 340, img: 'https://i.pinimg.com/736x/05/24/fc/0524fc736181bb269e5398cfff4c3792.jpg' },
  { title: 'DEAD THIRTEEN',         color: '#FFC82C', textColor: '#111', spineW: 25, h: 320, img: 'https://i.pinimg.com/736x/a9/45/9c/a9459c6f5e71d8d69cd44c864e5c7b0e.jpg' },
  { title: 'VISIBLE SIGNS',         color: '#192041', textColor: '#fff', spineW: 45, h: 360, isMain: true, img: 'https://i.pinimg.com/1200x/dc/e3/c2/dce3c2012dcd0eb45649f4adb414843c.jpg' },
  { title: 'THE IDEAL MANUAL OF STYLE', color: '#555555', textColor: '#b0b0b0', spineW: 60, h: 370, img: 'https://i.pinimg.com/736x/52/09/0f/52090ff1b38bbc2d2db6a2de3e24aeb9.jpg' },
  { title: 'DESIGN & ILLUSTRATION', color: '#EE8EBD', textColor: '#111', spineW: 55, h: 380, img: 'https://i.pinimg.com/1200x/45/7d/7f/457d7f2b139558049e8e5782bbdb9a33.jpg' },
  { title: 'DESIGN EMERGENCY',      color: '#227B36', textColor: '#fff', spineW: 25, h: 300, img: 'https://i.pinimg.com/736x/3f/7b/19/3f7b1918ce4af46d415765bedd9a2034.jpg' },
  { title: 'MINIMAL',               color: '#0D9488', textColor: '#fff', spineW: 15, h: 280, img: 'https://i.pinimg.com/736x/aa/fc/98/aafc9885e670f6473561bdb46b6f78c8.jpg' },
  { title: 'PRINTABLE',             color: '#95C6EF', textColor: '#174391', spineW: 45, h: 360, rotZ: -5, img: 'https://i.pinimg.com/1200x/80/04/48/800448a167edfba20cd2f87208845428.jpg' },
];

const OPEN_W = 240;
const GAP = 80;
const smoothstep = (t: number) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

export default function BookCarousel3D({
  books = DEFAULT_BOOKS,
  initialIndex = 7,
  onOpenBook,
}: BookCarousel3DProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const progressRef = useRef<HTMLDivElement>(null);
  const wrapperRefs = useRef<Array<HTMLDivElement | null>>([]);
  const rafRef = useRef<number | null>(null);
  const [activeTitle, setActiveTitle] = useState(books[initialIndex]?.title ?? '');
  const [reading, setReading] = useState(false);

  const state = useRef({
    target: initialIndex,
    current: initialIndex,
    dragging: false,
    startX: 0,
    scrollStart: 0,
    opened: -1,
    openness: new Array(books.length).fill(0),
  });

  useEffect(() => {
    const spineWidths = books.map(b => b.spineW || 40);
    const rotZs = books.map(b => b.rotZ || 0);

    function step() {
      const s = state.current;
      s.current += (s.target - s.current) * 0.08;

      // Compute widths + cumulative left positions
      const positions: number[] = [];
      let left = 0;
      for (let i = 0; i < books.length; i++) {
        positions[i] = left;
        const diff = i - s.current;
        const openness = Math.max(0, 1 - Math.abs(diff));
        const eo = smoothstep(openness);
        const w = spineWidths[i] + eo * (OPEN_W - spineWidths[i]);
        left += w + GAP;
      }

      const getCenter = (i: number, prog: number) => {
        const d = i - prog;
        const openness = Math.max(0, 1 - Math.abs(d));
        const eo = smoothstep(openness);
        const w = spineWidths[i] + eo * (OPEN_W - spineWidths[i]);
        return positions[i] + w / 2;
      };

      const prev = Math.floor(s.current);
      const next = prev + 1;
      const frac = s.current - prev;
      const c1 = getCenter(prev, s.current);
      const c2 = next < books.length ? getCenter(next, s.current) : c1;
      const cameraX = c1 * (1 - frac) + c2 * frac;

      const activeIndex = Math.max(0, Math.min(books.length - 1, Math.round(s.current)));
      setActiveTitle(books[activeIndex].title);

      wrapperRefs.current.forEach((el, i) => {
        if (!el) return;
        const diff = i - s.current;
        const openness = Math.max(0, 1 - Math.abs(diff));
        const eo = smoothstep(openness);

        let x = positions[i] - cameraX + (1 - eo) * (spineWidths[i] / 2);
        let z = eo * 60;
        let y = 0;
        const rotateY = (1 - eo) * 90;
        const zIndex = Math.round(100 - Math.abs(diff) * 10);
        const scale = 1 + eo * 0.05;
        const rotZ = rotZs[i] * (1 - eo);

        // Reading mode
        const target = s.opened === i ? 1 : 0;
        s.openness[i] += (target - s.openness[i]) * 0.06;
        const cOpen = s.openness[i];

        const riseP = Math.min(1, cOpen * 2);
        const swingP = Math.max(0, (cOpen - 0.5) * 2);
        const easeRise = smoothstep(riseP);
        const easeSwing = smoothstep(swingP);

        x += easeSwing * (OPEN_W / 2);
        z += easeRise * 150;
        y += easeRise * -120;

        el.style.zIndex = String(zIndex);
        el.style.transform = `translateX(${x}px) translateY(${y}px) translateZ(${z}px) scale(${scale}) rotateZ(${rotZ}deg)`;

        const inner = el.querySelector<HTMLElement>('.bc-book');
        if (inner) inner.style.transform = `rotateY(${rotateY}deg)`;

        const hinge = el.querySelector<HTMLElement>('.bc-hinge');
        if (hinge) hinge.style.transform = `translateZ(${spineWidths[i] / 2}px) rotateY(${easeSwing * -140}deg)`;

        const spine = el.querySelector<HTMLElement>('.bc-spine');
        if (spine) spine.style.filter = `brightness(${0.6 + eo * 0.4})`;
      });

      if (progressRef.current) {
        progressRef.current.style.width = `${(s.current / (books.length - 1)) * 100}%`;
      }
      rafRef.current = requestAnimationFrame(step);
    }
    rafRef.current = requestAnimationFrame(step);

    // Input handlers
    const clamp = (v: number) => Math.max(0, Math.min(v, books.length - 1));
    const onWheel = (e: WheelEvent) => {
      if (state.current.opened !== -1) return;
      state.current.target = clamp(state.current.target + Math.sign(e.deltaY) * 0.3);
    };
    const onMouseDown = (e: MouseEvent) => {
      if (state.current.opened !== -1) return;
      state.current.dragging = true;
      state.current.startX = e.clientX;
      state.current.scrollStart = state.current.target;
    };
    const onMouseMove = (e: MouseEvent) => {
      if (!state.current.dragging || state.current.opened !== -1) return;
      state.current.target = clamp(state.current.scrollStart + (e.clientX - state.current.startX) * -0.01);
    };
    const onMouseUp = () => (state.current.dragging = false);

    const onTouchStart = (e: TouchEvent) => {
      if (state.current.opened !== -1) return;
      state.current.dragging = true;
      state.current.startX = e.touches[0].clientX;
      state.current.scrollStart = state.current.target;
    };
    const onTouchMove = (e: TouchEvent) => {
      if (!state.current.dragging || state.current.opened !== -1) return;
      state.current.target = clamp(state.current.scrollStart + (e.touches[0].clientX - state.current.startX) * -0.01);
    };
    const onTouchEnd = () => (state.current.dragging = false);

    window.addEventListener('wheel', onWheel, { passive: true });
    window.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('mouseleave', onMouseUp);
    window.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: true });
    window.addEventListener('touchend', onTouchEnd);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      window.removeEventListener('wheel', onWheel);
      window.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('mouseleave', onMouseUp);
      window.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);
    };
  }, [books]);

  function handleClick(i: number) {
    const s = state.current;
    if (Math.round(s.current) === i) {
      const nextOpen = s.opened === i ? -1 : i;
      s.opened = nextOpen;
      setReading(nextOpen !== -1);
      if (nextOpen !== -1) onOpenBook?.(i, books[i]);
    } else {
      s.target = i;
    }
  }

  function closeReading() {
    state.current.opened = -1;
    setReading(false);
  }

  return (
    <>
      <style>{CSS}</style>
      <div className="bc-tl">JZA</div>
      <div className="bc-tr">ABOUT</div>

      <button
        className={`bc-close ${reading ? 'visible' : ''}`}
        onClick={closeReading}
        aria-label="Close book"
      >
        <div className="bc-close-wrap">
          <span className="bc-line bc-line-1" />
          <span className="bc-line bc-line-2" />
        </div>
      </button>

      <div className={`bc-header ${reading ? 'hidden' : ''}`}>
        <h1 className="bc-title">{activeTitle}</h1>
      </div>

      <div className="bc-scene">
        <div ref={trackRef} className="bc-track">
          {books.map((b, i) => {
            const sW = b.spineW || 40;
            return (
              <div
                key={i}
                ref={(el) => (wrapperRefs.current[i] = el)}
                className="bc-wrapper"
                onClick={() => handleClick(i)}
              >
                <div className="bc-book" style={{ height: `${b.h}px` }}>
                  {/* Front hinge (cover + inside) */}
                  <div className="bc-face bc-hinge" style={{ transform: `translateZ(${sW / 2}px)` }}>
                    <div className="bc-face bc-front" style={{ width: OPEN_W, background: b.color }}>
                      <div className="bc-overlay" />
                      {b.img ? (
                        <img src={b.img} alt={b.title} className="bc-cover-img" />
                      ) : (
                        <div className="bc-cover-text" style={{ color: b.textColor }}>
                          {b.title}
                        </div>
                      )}
                    </div>
                    <div className="bc-face bc-inside" style={{ width: OPEN_W }} />
                  </div>

                  {/* Reading page */}
                  <div className="bc-face bc-page" style={{ transform: `translateZ(${sW / 2 - 1}px)` }}>
                    <div className="bc-page-inner">
                      <div className="bc-page-eyebrow">Selected Work</div>
                      <h3 className="bc-page-title">{b.title}</h3>
                      <div className="bc-page-rule" />
                    </div>
                  </div>

                  <div className="bc-face bc-back" style={{ width: OPEN_W, background: b.color, transform: `rotateY(180deg) translateZ(${sW / 2}px)` }} />

                  <div className="bc-face bc-spine" style={{ width: sW, left: -sW / 2, background: b.isMain ? '#121830' : b.color }}>
                    <div className="bc-spine-text" style={{ color: b.textColor }}>{b.title}</div>
                  </div>

                  <div className="bc-face bc-pages bc-pages-right" style={{ width: sW, left: OPEN_W - sW / 2 }} />
                  <div className="bc-face bc-pages bc-pages-top"    style={{ height: sW, top: -sW / 2 }} />
                  <div className="bc-face bc-pages bc-pages-bottom" style={{ height: sW, bottom: -sW / 2 }} />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="bc-progress">
        <div ref={progressRef} className="bc-progress-bar" />
      </div>
    </>
  );
}

