function PunchHoleCamera() {
  return (
    <div
      aria-hidden='true'
      className='pointer-events-none absolute left-1/2 flex -translate-x-1/2 items-center justify-center rounded-full bg-black'
      style={CAMERA_STYLE}
    >
      <span className='rounded-full bg-[hsl(230_18%_8%)]' style={LENS_STYLE} />
    </div>
  );
}

function GestureBar({ toneClass }: { toneClass: string }) {
  return (
    <div
      aria-hidden='true'
      className={cn(
        'pointer-events-none absolute left-1/2 -translate-x-1/2 rounded-full bg-current opacity-80 transition-colors duration-200',
        toneClass
      )}
      style={GESTURE_BAR_STYLE}
    />
  );
}

function ScreenVideo({ src, alt }: { src: string; alt: string }) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isDecorative = alt === '';
  const showsControls = Boolean(shouldReduceMotion);
  const isHidden = isDecorative && !showsControls;

  useEffect(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (shouldReduceMotion) {
      video.pause();
      return;
    }
    const playback = video.play();
    playback.catch(ignoreRefusedPlayback);
  }, [shouldReduceMotion]);

  return (
    <video
      ref={videoRef}
      src={src}
      muted
      loop
      playsInline
      preload='metadata'
      controls={showsControls}
      aria-label={alt || undefined}
      aria-hidden={isHidden || undefined}
      className='size-full object-cover'
    />
  );
}

function ScreenMedia({
  imageSrc,
  videoSrc,
  alt,
}: {
  imageSrc?: string;
  videoSrc?: string;
  alt: string;
}) {
  const mediaKey = videoSrc ?? imageSrc;
  const hasVideo = videoSrc !== undefined;
  const hasImage = imageSrc !== undefined;
  const showsImage = hasImage && !hasVideo;

  return (
    <AnimatePresence initial={false}>
      <motion.div
        key={mediaKey}
        className='absolute inset-0'
        initial={{ opacity: 0 }}
        animate={{ opacity: 1, transition: MEDIA_ENTER }}
        exit={{ opacity: 0, transition: MEDIA_EXIT }}
      >
        {hasVideo && <ScreenVideo src={videoSrc} alt={alt} />}
        {showsImage && (
          // eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist
          <img
            src={imageSrc}
            alt={alt}
            draggable={false}
            className='size-full object-cover'
          />
        )}
      </motion.div>
    </AnimatePresence>
  );
}

export function Android({
  imageSrc,
  videoSrc,
  alt = '',
  finish = 'black',
  statusBar = 'auto',
  time = '9:41',
  safeArea = true,
  label = 'Phone screen',
  className,
  style,
  children,
  ...props
}: AndroidProps) {
  const hasMedia = Boolean(imageSrc || videoSrc);
  const hasChildren = children !== undefined && children !== null;
  const toneClass = STATUS_TONE[statusBar];
  const contentStyle = contentStyleOf(safeArea);

  return (
    <figure
      aria-label={label}
      className={cn('@container relative w-full max-w-[450px]', className)}
      style={{ ...ROOT_STYLE, ...style }}
      {...props}
    >
      <div aria-hidden='true' className='absolute' style={SHADOW_STYLE} />
      <Hardware finish={finish} />
      <div
        className='bg-background text-foreground absolute overflow-hidden'
        style={SCREEN_STYLE}
      >
        {hasMedia && (
          <ScreenMedia imageSrc={imageSrc} videoSrc={videoSrc} alt={alt} />
        )}
        {hasChildren && (
          <div
            className='absolute inset-0 flex [scrollbar-width:none] flex-col overflow-y-auto overscroll-contain [&::-webkit-scrollbar]:hidden'
            style={contentStyle}
          >
            {children}
          </div>
        )}
        <StatusBar time={time} toneClass={toneClass} />
        <PunchHoleCamera />
        <GestureBar toneClass={toneClass} />
      </div>
    </figure>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  AnimatePresence,
  MotionConfig,
  Transition,
  motion,
} from 'motion/react';
import {
  Children,
  cloneElement,
  ReactElement,
  ReactNode,
  useState,
  useId,
} from 'react';

export type AnimatedBackgroundProps = {
  children:
    ReactElement<{ 'data-id': string }>[] | ReactElement<{ 'data-id': string }>;
  defaultValue?: string;
  onValueChange?: (newActiveId: string | null) => void;
  className?: string;
  transition?: Transition;
  enableHover?: boolean;
};

type AnimatedBackgroundChild = ReactElement<
  {
    'data-id': string;
    className?: string;
    children?: ReactNode;
  } & Record<string, unknown>
>;

function ReducedMotionConfig({ children }: { children: ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

function initialOpacityOf(defaultValue?: string) {
  if (defaultValue) {
    return 1;
  }
  return 0;
}

export function AnimatedBackground({
  children,
  defaultValue,
  onValueChange,
  className,
  transition,
  enableHover = false,
}: AnimatedBackgroundProps) {
  const [activeId, setActiveId] = useState<string | null>(defaultValue ?? null);
  const [syncedDefaultValue, setSyncedDefaultValue] = useState(defaultValue);
  const uniqueId = useId();

  const hasNewDefaultValue = defaultValue !== syncedDefaultValue;
  if (hasNewDefaultValue) {
    setSyncedDefaultValue(defaultValue);
    if (defaultValue !== undefined) {
      setActiveId(defaultValue);
    }
  }

  const handleSetActiveId = (id: string | null) => {
    setActiveId(id);

    if (onValueChange) {
      onValueChange(id);
    }
  };

  const interactionPropsOf = (id: string) => {
    if (enableHover) {
      return {
        onMouseEnter: () => handleSetActiveId(id),
        onMouseLeave: () => handleSetActiveId(null),
      };
    }
    return {
      onClick: () => handleSetActiveId(id),
    };
  };

  const initialOpacity = initialOpacityOf(defaultValue);

  return (
    <ReducedMotionConfig>
      {Children.map(children, (child, index) => {
        const element = child as AnimatedBackgroundChild;
        const id = element.props['data-id'];
        const isActive = activeId === id;

        return cloneElement(
          element,
          {
            key: index,
            className: cn('relative inline-flex', element.props.className),
            'data-checked': String(isActive),
            ...interactionPropsOf(id),
          },
          <>
            <AnimatePresence initial={false}>
              {isActive && (
                <motion.div
                  layoutId={`background-${uniqueId}`}
                  className={cn('absolute inset-0', className)}
                  transition={transition}
                  initial={{ opacity: initialOpacity }}
                  animate={{
                    opacity: 1,
                  }}
                  exit={{
                    opacity: 0,
                  }}
                />
              )}
            </AnimatePresence>
            <div className='z-10'>{element.props.children}</div>
          </>
        );
      })}
    </ReducedMotionConfig>
  );
}

'use client';

import { motion, useInView } from 'motion/react';
import { useEffect, useId, useState } from 'react';

import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

type Point = { x: number; y: number };

type BeamGeometry = {
  width: number;
  height: number;
  start: Point;
  end: Point;
  path: string;
};

type ElementRef = React.RefObject<HTMLElement | null>;

type BeamOffsets = {
  start: Point;
  end: Point;
};

const HEAD_LENGTH = 0.35;

const TRAVEL_EASE = [0.77, 0, 0.175, 1] as const;

function centreOf(element: HTMLElement, origin: DOMRect): Point {
  const box = element.getBoundingClientRect();
  const left = box.left - origin.left;
  const top = box.top - origin.top;
  const halfWidth = box.width / 2;
  const halfHeight = box.height / 2;
  return { x: left + halfWidth, y: top + halfHeight };
}

function shiftedOf(point: Point, offset: Point): Point {
  const x = point.x + offset.x;
  const y = point.y + offset.y;
  return { x, y };
}

function curvedPathOf(start: Point, end: Point, curvature: number) {
  const deltaX = end.x - start.x;
  const deltaY = end.y - start.y;
  const distance = Math.hypot(deltaX, deltaY);
  const length = Math.max(distance, 1);
  const normalX = -deltaY / length;
  const normalY = deltaX / length;
  const bendX = normalX * curvature;
  const bendY = normalY * curvature;
  const middleX = (start.x + end.x) / 2;
  const middleY = (start.y + end.y) / 2;
  const controlX = middleX + bendX;
  const controlY = middleY + bendY;
  return `M ${start.x},${start.y} Q ${controlX},${controlY} ${end.x},${end.y}`;
}

function measureBeam(
  container: HTMLElement,
  from: HTMLElement,
  to: HTMLElement,
  curvature: number,
  offsets: BeamOffsets
): BeamGeometry {
  const origin = container.getBoundingClientRect();
  const fromCentre = centreOf(from, origin);
  const toCentre = centreOf(to, origin);
  const start = shiftedOf(fromCentre, offsets.start);
  const end = shiftedOf(toCentre, offsets.end);
  return {
    width: origin.width,
    height: origin.height,
    start,
    end,
    path: curvedPathOf(start, end, curvature),
  };
}

function useBeamGeometry(
  containerRef: ElementRef,
  fromRef: ElementRef,
  toRef: ElementRef,
  curvature: number,
  offsets: BeamOffsets
) {
  const [geometry, setGeometry] = useState<BeamGeometry | null>(null);
  const startX = offsets.start.x;
  const startY = offsets.start.y;
  const endX = offsets.end.x;
  const endY = offsets.end.y;

  useEffect(() => {
    const container = containerRef.current;
    const from = fromRef.current;
    const to = toRef.current;
    const isMissingNode = !from || !to;
    if (!container || isMissingNode) {
      return;
    }
    const measuredOffsets: BeamOffsets = {
      start: { x: startX, y: startY },
      end: { x: endX, y: endY },
    };
    const observer = new ResizeObserver(() => {
      const next = measureBeam(container, from, to, curvature, measuredOffsets);
      setGeometry(next);
    });
    observer.observe(container);
    observer.observe(from);
    observer.observe(to);
    return () => observer.disconnect();
  }, [containerRef, fromRef, toRef, curvature, startX, startY, endX, endY]);

  return geometry;
}

function pointAlong(start: Point, end: Point, progress: number): Point {
  const stepX = (end.x - start.x) * progress;
  const stepY = (end.y - start.y) * progress;
  return { x: start.x + stepX, y: start.y + stepY };
}

function travelOf(start: Point, end: Point) {
  const tailFrom = pointAlong(start, end, -HEAD_LENGTH);
  const tailTo = pointAlong(start, end, 1);
  const headFrom = start;
  const headTo = pointAlong(start, end, 1 + HEAD_LENGTH);
  return {
    x1: [tailFrom.x, tailTo.x],
    y1: [tailFrom.y, tailTo.y],
    x2: [headFrom.x, headTo.x],
    y2: [headFrom.y, headTo.y],
  };
}

function firstFrameOf(travel: ReturnType<typeof travelOf>) {
  return {
    x1: travel.x1[0],
    y1: travel.y1[0],
    x2: travel.x2[0],
    y2: travel.y2[0],
  };
}

function directedEnds(geometry: BeamGeometry, reverse: boolean) {
  if (reverse) {
    return { from: geometry.end, to: geometry.start };
  }
  return { from: geometry.start, to: geometry.end };
}

function safeIdOf(id: string) {
  return id.replace(/[^a-zA-Z0-9_-]/g, '');
}

export type AnimatedBeamProps = {
  containerRef: ElementRef;
  fromRef: ElementRef;
  toRef: ElementRef;
  curvature?: number;
  reverse?: boolean;
  duration?: number;
  delay?: number;
  repeatDelay?: number;
  startXOffset?: number;
  startYOffset?: number;
  endXOffset?: number;
  endYOffset?: number;
  className?: string;
};

export function AnimatedBeam({
  containerRef,
  fromRef,
  toRef,
  curvature = 0,
  reverse = false,
  duration = 3,
  delay = 0,
  repeatDelay = 1,
  startXOffset = 0,
  startYOffset = 0,
  endXOffset = 0,
  endYOffset = 0,
  className,
}: AnimatedBeamProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const isInView = useInView(containerRef);
  const offsets: BeamOffsets = {
    start: { x: startXOffset, y: startYOffset },
    end: { x: endXOffset, y: endYOffset },
  };
  const geometry = useBeamGeometry(
    containerRef,
    fromRef,
    toRef,
    curvature,
    offsets
  );
  const beamId = useId();
  const gradientId = `beam-${safeIdOf(beamId)}`;

  if (!geometry) {
    return null;
  }

  const ends = directedEnds(geometry, reverse);
  const travel = travelOf(ends.from, ends.to);
  const isTravelling = isInView && !prefersReducedMotion;

  return (
    <svg
      aria-hidden='true'
      className={cn(
        'pointer-events-none absolute inset-0 size-full',
        className
      )}
      viewBox={`0 0 ${geometry.width} ${geometry.height}`}
      fill='none'
    >
      <path
        d={geometry.path}
        className='stroke-foreground/12'
        strokeWidth={1.5}
        strokeLinecap='round'
      />
      {isTravelling && (
        <>
          <path
            d={geometry.path}
            stroke={`url(#${gradientId})`}
            strokeWidth={2}
            strokeLinecap='round'
          />
          <defs>
            <motion.linearGradient
              id={gradientId}
              gradientUnits='userSpaceOnUse'
              initial={firstFrameOf(travel)}
              animate={travel}
              transition={{
                duration,
                delay,
                repeatDelay,
                repeat: Infinity,
                ease: TRAVEL_EASE,
              }}
            >
              <stop
                offset='0'
                style={{ stopColor: 'var(--primary)' }}
                stopOpacity={0}
              />
              <stop offset='0.75' style={{ stopColor: 'var(--primary)' }} />
              <stop
                offset='1'
                style={{ stopColor: 'var(--primary)' }}
                stopOpacity={0}
              />
            </motion.linearGradient>
          </defs>
        </>
      )}
    </svg>
  );
}

const NODE_SIZES = {
  sm: 'size-10 rounded-lg [&_svg]:size-4',
