      <div className='bg-foreground/[0.03] relative aspect-[4/3] overflow-hidden'>
        {image && <CardImage image={image} />}
        {meta && <div className={RISING_PANEL}>{meta}</div>}
      </div>
      <CardText title={title} description={description} />
