}

const TILT_DEGREES = 7;

const TILT_PERSPECTIVE = 900;

const TILT_SPRING = { stiffness: 260, damping: 32 };

const EDGE_MASK = {
  mask: 'linear-gradient(black, black) content-box exclude, linear-gradient(black, black)',
  WebkitMask:
    'linear-gradient(black, black) content-box xor, linear-gradient(black, black)',
};

const EDGE_LIGHT = [
  'pointer-events-none absolute inset-0 rounded-[inherit] p-(--hairline) opacity-0',
  'transition-opacity duration-150 group-hover/card:opacity-100 group-hover/card:duration-200',
].join(' ');

function isMouse(event: React.PointerEvent) {
  return event.pointerType === 'mouse';
}

function tiltStyleOf(
  prefersReducedMotion: boolean | null,
  rotateX: MotionValue<number>,
  rotateY: MotionValue<number>
) {
  if (prefersReducedMotion) {
    return undefined;
  }
  return { rotateX, rotateY, transformPerspective: TILT_PERSPECTIVE };
}

function TiltCard({
  title,
  description,
  meta,
  image,
  className,
  onPointerMove,
  onPointerLeave,
  ...props
}: EffectProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const pointerX = useMotionValue(0.5);
  const pointerY = useMotionValue(0.5);
  const smoothX = useSpring(pointerX, TILT_SPRING);
  const smoothY = useSpring(pointerY, TILT_SPRING);
  const rotateY = useTransform(smoothX, [0, 1], [-TILT_DEGREES, TILT_DEGREES]);
  const rotateX = useTransform(smoothY, [0, 1], [TILT_DEGREES, -TILT_DEGREES]);
  const lightX = useTransform(pointerX, [0, 1], [0, 100]);
  const lightY = useTransform(pointerY, [0, 1], [0, 100]);
  const edgeLight = useMotionTemplate`radial-gradient(160px circle at ${lightX}% ${lightY}%, color-mix(in oklab, var(--foreground) 45%, transparent), transparent 70%)`;
  const tiltStyle = tiltStyleOf(prefersReducedMotion, rotateX, rotateY);

  function followPointer(event: React.PointerEvent<HTMLAnchorElement>) {
    onPointerMove?.(event);
    if (!isMouse(event)) {
      return;
    }
    const bounds = event.currentTarget.getBoundingClientRect();
    const offsetX = event.clientX - bounds.left;
    const offsetY = event.clientY - bounds.top;
    const ratioX = offsetX / bounds.width;
    const ratioY = offsetY / bounds.height;
    pointerX.set(ratioX);
    pointerY.set(ratioY);
  }

  function settle(event: React.PointerEvent<HTMLAnchorElement>) {
    onPointerLeave?.(event);
    pointerX.set(0.5);
    pointerY.set(0.5);
  }

  return (
    <a
      className={cn(LINK, className)}
      onPointerMove={followPointer}
      onPointerLeave={settle}
      {...props}
    >
      <motion.div className={cn(SURFACE, 'h-full')} style={tiltStyle}>
        {image && (
          <div className='relative aspect-[3/2] overflow-hidden'>
            <CardImage image={image} />
          </div>
        )}
        <CardText title={title} description={description} meta={meta} />
        <motion.span
          aria-hidden='true'
          className={EDGE_LIGHT}
          style={{ background: edgeLight, ...EDGE_MASK }}
        />
      </motion.div>
    </a>
  );
}

const TRACE_STROKE = 1.5;

const TRACE_PATH = [
  'fill-none stroke-primary [stroke-dasharray:1] [stroke-dashoffset:1]',
  'transition-[stroke-dashoffset] duration-200 ease-(--ease-out-strong)',
  'group-hover/card:[stroke-dashoffset:0] group-hover/card:duration-500 group-hover/card:ease-(--ease-in-out-strong)',
  'group-focus-visible/card:[stroke-dashoffset:0]',
].join(' ');

type Size = { width: number; height: number };

function roundedOutlineOf({ width, height }: Size, radius: number) {
  const inset = TRACE_STROKE / 2;
  const r = radius - inset;
  const right = width - inset;
  const bottom = height - inset;
  const left = inset;
  const top = inset;
  return [
    `M ${left + r} ${top}`,
    `H ${right - r}`,
    `A ${r} ${r} 0 0 1 ${right} ${top + r}`,
    `V ${bottom - r}`,
    `A ${r} ${r} 0 0 1 ${right - r} ${bottom}`,
    `H ${left + r}`,
    `A ${r} ${r} 0 0 1 ${left} ${bottom - r}`,
    `V ${top + r}`,
    `A ${r} ${r} 0 0 1 ${left + r} ${top}`,
    'Z',
  ].join(' ');
}

function useElementSize<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [size, setSize] = useState<Size | null>(null);

  useEffect(() => {
    const element = ref.current;
    if (!element) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      const box = entry.borderBoxSize[0];
      setSize({ width: box.inlineSize, height: box.blockSize });
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  return { ref, size };
}

function TraceCard({
  title,
  description,
  meta,
  image,
  className,
  ...props
}: EffectProps) {
  const { ref, size } = useElementSize<HTMLAnchorElement>();

  return (
    <a ref={ref} className={cn(CARD, className)} {...props}>
      {image && (
        <div className='relative aspect-[3/2] overflow-hidden'>
          <CardImage image={image} />
        </div>
      )}
      <CardText title={title} description={description} meta={meta} />
      {size && (
        <svg
          aria-hidden='true'
          className='pointer-events-none absolute inset-0 size-full'
          viewBox={`0 0 ${size.width} ${size.height}`}
        >
          <path
            d={roundedOutlineOf(size, CARD_RADIUS)}
            pathLength={1}
            strokeWidth={TRACE_STROKE}
            className={TRACE_PATH}
          />
        </svg>
      )}
    </a>
  );
}

export function HoverEffectCard({ effect, ...props }: HoverEffectCardProps) {
  if (effect === 'zoom') {
    return <ZoomCard {...props} />;
  }
  if (effect === 'rise') {
    return <RiseCard {...props} />;
  }
  if (effect === 'tilt') {
    return <TiltCard {...props} />;
  }
  return <TraceCard {...props} />;
}

'use client';
import { useState, type MouseEvent, type PointerEvent } from 'react';
import { cn } from '@/lib/utils';

export type ImageAccordionItem = {
  id: string;
  src: string;
  alt: string;
  title: string;
  description?: string;
  href?: string;
};

export type ImageAccordionOrientation = 'horizontal' | 'vertical';

export type ImageAccordionProps = {
  items: ImageAccordionItem[];
  defaultValue?: string;
  value?: string;
  onValueChange?: (value: string) => void;
  orientation?: ImageAccordionOrientation;
  className?: string;
};

const ORIENTATION_CLASS: Record<ImageAccordionOrientation, string> = {
  horizontal: 'h-[28rem] flex-col sm:h-80 sm:flex-row',
  vertical: 'h-[28rem] flex-col',
};

const IMAGE_CLASS: Record<ImageAccordionOrientation, string> = {
  horizontal:
    'top-1/2 left-0 h-auto min-h-full w-full -translate-y-1/2 sm:top-0 sm:left-1/2 sm:h-full sm:min-h-0 sm:w-auto sm:min-w-full sm:-translate-x-1/2 sm:translate-y-0',
  vertical: 'top-1/2 left-0 h-auto min-h-full w-full -translate-y-1/2',
};

const ITEM_CLASS =
  'min-h-0 min-w-0 basis-0 grow transition-[flex-grow] duration-500 ease-(--ease-out-strong) data-[active=true]:grow-[4]';

const PANEL_CLASS =
  'group/panel bg-foreground/[0.04] focus-visible:ring-ring focus-visible:ring-offset-background relative block size-full cursor-pointer overflow-hidden rounded-xl text-left outline-none focus-visible:ring-2 focus-visible:ring-offset-2';

const CAPTION_CLASS =
  'pointer-events-none absolute bottom-3 left-3 flex w-56 flex-col gap-0.5 rounded-lg bg-card/90 px-3 py-2 text-card-foreground opacity-0 shadow-[0_1px_2px_rgb(0_0_0/0.08)] transition-[opacity,translate] duration-100 ease-(--ease-out-strong) translate-y-1 group-data-[active=true]/panel:translate-y-0 group-data-[active=true]/panel:opacity-100 group-data-[active=true]/panel:delay-150 group-data-[active=true]/panel:duration-200';

function firstIdOf(items: ImageAccordionItem[]) {
  const first = items[0];
  if (!first) {
    return '';
  }
  return first.id;
}

function selectedIdOf(
  controlledValue: string | undefined,
  internalValue: string
) {
  if (controlledValue === undefined) {
    return internalValue;
  }
  return controlledValue;
}

type PanelContentProps = {
  item: ImageAccordionItem;
  orientation: ImageAccordionOrientation;
};

function PanelContent({ item, orientation }: PanelContentProps) {
  return (
    <>
      {/* eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist */}
      <img
        src={item.src}
        alt={item.alt}
        draggable={false}
        decoding='async'
        className={cn(
          'absolute max-w-none object-cover',
          IMAGE_CLASS[orientation]
        )}
      />
      <span className={CAPTION_CLASS}>
        <span className='truncate text-sm font-medium'>{item.title}</span>
        {item.description && (
          <span className='text-muted-foreground line-clamp-2 text-xs'>
            {item.description}
          </span>
        )}
      </span>
    </>
  );
}

function ImageAccordion({
  items,
  defaultValue,
  value: controlledValue,
  onValueChange,
  orientation = 'horizontal',
  className,
}: ImageAccordionProps) {
  const [internalValue, setInternalValue] = useState(
    defaultValue ?? firstIdOf(items)
  );
  const activeId = selectedIdOf(controlledValue, internalValue);

  const activate = (id: string) => {
    if (id === activeId) {
      return;
    }
    setInternalValue(id);
    onValueChange?.(id);
  };

  const activateOnPress = (
    item: ImageAccordionItem,
    event: MouseEvent<HTMLElement>
  ) => {
    const isLink = item.href !== undefined;
    const isClosed = item.id !== activeId;
    const isClosedLink = isLink && isClosed;
    if (isClosedLink) {
      event.preventDefault();
    }
    activate(item.id);
  };

  const activateOnHover = (id: string, event: PointerEvent<HTMLElement>) => {
    const isMouse = event.pointerType === 'mouse';
    if (isMouse) {
      activate(id);
    }
  };

  return (
    <ul className={cn('flex gap-2', ORIENTATION_CLASS[orientation], className)}>
      {items.map((item) => {
        const isActive = item.id === activeId;
        const sharedProps = {
          'data-active': isActive,
          className: PANEL_CLASS,
          onFocus: () => activate(item.id),
          onClick: (event: MouseEvent<HTMLElement>) =>
            activateOnPress(item, event),
          onPointerEnter: (event: PointerEvent<HTMLElement>) =>
            activateOnHover(item.id, event),
        };

        return (
          <li key={item.id} data-active={isActive} className={ITEM_CLASS}>
            {item.href && (
              <a href={item.href} {...sharedProps}>
                <PanelContent item={item} orientation={orientation} />
              </a>
            )}
            {!item.href && (
              <button type='button' aria-expanded={isActive} {...sharedProps}>
                <PanelContent item={item} orientation={orientation} />
              </button>
            )}
          </li>
        );
      })}
    </ul>
  );
}

export { ImageAccordion };

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useState, createContext, useContext } from 'react';
import {
  motion,
  MotionValue,
  SpringOptions,
  useMotionValue,
  useSpring,
  useTransform,
} from 'motion/react';

const ImageComparisonContext = createContext<
  | {
      sliderPosition: number;
      setSliderPosition: (pos: number) => void;
      motionSliderPosition: MotionValue<number>;
    }
  | undefined
>(undefined);

export type ImageComparisonProps = {
  children: React.ReactNode;
  className?: string;
  enableHover?: boolean;
  springOptions?: SpringOptions;
};

const DEFAULT_SPRING_OPTIONS = {
  bounce: 0,
  duration: 0,
};

function followerOf(
  prefersReducedMotion: boolean | null,
  target: MotionValue<number>,
  spring: MotionValue<number>
) {
  if (prefersReducedMotion) {
    return target;
  }
  return spring;
}

function ImageComparison({
  children,
  className,
  enableHover,
  springOptions,
}: ImageComparisonProps) {
  const [isDragging, setIsDragging] = useState(false);
  const motionValue = useMotionValue(50);
  const prefersReducedMotion = usePrefersReducedMotion();
  const springSliderPosition = useSpring(
    motionValue,
    springOptions ?? DEFAULT_SPRING_OPTIONS
  );
  const motionSliderPosition = followerOf(
    prefersReducedMotion,
    motionValue,
    springSliderPosition
  );
  const [sliderPosition, setSliderPosition] = useState(50);

  const handleDrag = (event: React.MouseEvent | React.TouchEvent) => {
    if (!isDragging && !enableHover) return;

    const containerRect = (
      event.currentTarget as HTMLElement
    ).getBoundingClientRect();
    const x =
      'touches' in event
        ? event.touches[0].clientX - containerRect.left
        : (event as React.MouseEvent).clientX - containerRect.left;

    const percentage = Math.min(
      Math.max((x / containerRect.width) * 100, 0),
      100
    );
    motionValue.set(percentage);
    setSliderPosition(percentage);
  };

  return (
    <ImageComparisonContext.Provider
      value={{ sliderPosition, setSliderPosition, motionSliderPosition }}
    >
      <div
        className={cn(
          'relative overflow-hidden select-none',
          enableHover && 'cursor-ew-resize',
          className
        )}
        onMouseMove={handleDrag}
        onMouseDown={() => !enableHover && setIsDragging(true)}
        onMouseUp={() => !enableHover && setIsDragging(false)}
        onMouseLeave={() => !enableHover && setIsDragging(false)}
        onTouchMove={handleDrag}
        onTouchStart={() => !enableHover && setIsDragging(true)}
        onTouchEnd={() => !enableHover && setIsDragging(false)}
      >
        {children}
      </div>
    </ImageComparisonContext.Provider>
  );
}

const ImageComparisonImage = ({
  className,
  alt,
  src,
  position,
}: {
  className?: string;
  alt: string;
  src: string;
  position: 'left' | 'right';
}) => {
  const { motionSliderPosition } = useContext(ImageComparisonContext)!;
  const leftClipPath = useTransform(
    motionSliderPosition,
    (value) => `inset(0 0 0 ${value}%)`
  );
  const rightClipPath = useTransform(
    motionSliderPosition,
    (value) => `inset(0 ${100 - value}% 0 0)`
  );

  return (
    <motion.img
      src={src}
      alt={alt}
      className={cn('absolute inset-0 h-full w-full object-cover', className)}
      style={{
        clipPath: position === 'left' ? leftClipPath : rightClipPath,
      }}
    />
  );
};

const ImageComparisonSlider = ({
  className,
  children,
}: {
  className: string;
  children?: React.ReactNode;
}) => {
  const { motionSliderPosition } = useContext(ImageComparisonContext)!;

  const left = useTransform(motionSliderPosition, (value) => `${value}%`);

  return (
    <motion.div
      className={cn('absolute top-0 bottom-0 w-1 cursor-ew-resize', className)}
      style={{
        left,
      }}
    >
      {children}
    </motion.div>
  );
};

export { ImageComparison, ImageComparisonImage, ImageComparisonSlider };

'use client';
import { motion, useMotionValue, useSpring } from 'motion/react';
import {
  useRef,
  useState,
  type FocusEvent,
  type PointerEvent,
  type ReactNode,
} from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type ImageRevealItem = {
  id: string;
  title: string;
  meta?: ReactNode;
  src: string;
  href?: string;
};

export type ImageRevealProps = {
  items: ImageRevealItem[];
  onSelect?: (item: ImageRevealItem) => void;
  className?: string;
  rowClassName?: string;
  titleClassName?: string;
  imageClassName?: string;
};

type Preview = {
  id: string;
  source: 'pointer' | 'focus';
};

const FOLLOW_SPRING = { stiffness: 320, damping: 32, mass: 0.6 };

const FOCUS_GAP = 16;

const POINTER_GAP = 24;

const FRAME_SHOWN = { opacity: 1, scale: 1 };

const FRAME_HIDDEN = { opacity: 0, scale: 0.96 };

const FRAME_HIDDEN_STILL = { opacity: 0, scale: 1 };

const FRAME_ENTER = { duration: 0.18, ease: [0.23, 1, 0.32, 1] as const };

const FRAME_EXIT = { duration: 0.12, ease: [0.23, 1, 0.32, 1] as const };

const ROW_CLASS =
  'group/row text-foreground focus-visible:ring-ring/25 relative flex w-full items-baseline justify-between gap-6 rounded-lg px-2 py-3 text-left outline-none focus-visible:ring-[3px]';

function isKeyboardFocus(event: FocusEvent<HTMLElement>) {
  return event.currentTarget.matches(':focus-visible');
}

function frameStateOf(
  isVisible: boolean,
  prefersReducedMotion: boolean | null
) {
  if (isVisible) {
    return FRAME_SHOWN;
  }
  if (prefersReducedMotion) {
    return FRAME_HIDDEN_STILL;
  }
  return FRAME_HIDDEN;
}

/** Keeps the image beside the pointer so the hovered title stays readable, and flips it left near the right edge. */
function frameLeftOf(pointerX: number, frameWidth: number, listWidth: number) {
  const rightSide = pointerX + POINTER_GAP;
  const fitsOnTheRight = rightSide + frameWidth <= listWidth;
  if (fitsOnTheRight) {
    return rightSide;
  }
  return pointerX - POINTER_GAP - frameWidth;
}

function frameTransitionOf(isVisible: boolean) {
  if (isVisible) {
    return FRAME_ENTER;
  }
  return FRAME_EXIT;
}

function ImageReveal({
  items,
  onSelect,
  className,
  rowClassName,
  titleClassName,
  imageClassName,
}: ImageRevealProps) {
  const listRef = useRef<HTMLUListElement>(null);
  const frameRef = useRef<HTMLDivElement>(null);
  const [preview, setPreview] = useState<Preview | null>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const targetX = useMotionValue(0);
  const targetY = useMotionValue(0);
  const springX = useSpring(targetX, FOLLOW_SPRING);
  const springY = useSpring(targetY, FOLLOW_SPRING);

  const placeAt = (x: number, y: number, instantly: boolean) => {
    targetX.set(x);
    targetY.set(y);
    const shouldJump = instantly || prefersReducedMotion;
    if (shouldJump) {
      springX.jump(x);
      springY.jump(y);
    }
  };

  const followPointer = (event: PointerEvent<HTMLElement>) => {
    const list = listRef.current;
    const frame = frameRef.current;
    if (!list) {
      return;
    }
    if (!frame) {
      return;
    }
    const bounds = list.getBoundingClientRect();
    const pointerX = event.clientX - bounds.left;
    const x = frameLeftOf(pointerX, frame.offsetWidth, bounds.width);
    const y = event.clientY - bounds.top - frame.offsetHeight / 2;
    const isHidden = preview === null;
    placeAt(x, y, isHidden);
  };

  const showForPointer = (
    item: ImageRevealItem,
    event: PointerEvent<HTMLElement>
  ) => {
    const isMouse = event.pointerType === 'mouse';
    if (!isMouse) {
      return;
    }
    followPointer(event);
    setPreview({ id: item.id, source: 'pointer' });
  };

  const moveWithPointer = (event: PointerEvent<HTMLElement>) => {
    const isFollowing = preview?.source === 'pointer';
    if (isFollowing) {
      followPointer(event);
    }
  };

  const showForFocus = (
    item: ImageRevealItem,
    event: FocusEvent<HTMLElement>
  ) => {
    if (!isKeyboardFocus(event)) {
      return;
    }
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    const row = event.currentTarget;
    const x = row.offsetLeft + row.offsetWidth - frame.offsetWidth - FOCUS_GAP;
    const y = row.offsetTop + row.offsetHeight / 2 - frame.offsetHeight / 2;
    placeAt(x, y, true);
    setPreview({ id: item.id, source: 'focus' });
  };

  const hidePreview = () => {
    setPreview(null);
  };

  const isVisible = preview !== null;

  return (
    <div className={cn('relative', className)}>
      <ul
        ref={listRef}
        onPointerLeave={hidePreview}
        className='relative flex flex-col'
      >
        {items.map((item) => {
          const isPreviewed = preview?.id === item.id;
          const rowProps = {
            'data-previewed': isPreviewed,
            className: cn(ROW_CLASS, rowClassName),
            onPointerEnter: (event: PointerEvent<HTMLElement>) =>
              showForPointer(item, event),
            onPointerMove: moveWithPointer,
            onFocus: (event: FocusEvent<HTMLElement>) =>
              showForFocus(item, event),
            onBlur: hidePreview,
          };

          const content = (
            <>
              <span
                className={cn(
                  'text-2xl font-semibold text-balance sm:text-3xl',
                  titleClassName
                )}
              >
                {item.title}
              </span>
              {item.meta && (
                <span className='text-muted-foreground shrink-0 text-[13px] tabular-nums'>
                  {item.meta}
                </span>
              )}
            </>
          );

          return (
            <li key={item.id}>
              {item.href && (
                <a href={item.href} {...rowProps}>
                  {content}
                </a>
              )}
              {!item.href && (
                <button
                  type='button'
                  onClick={() => onSelect?.(item)}
                  {...rowProps}
                >
                  {content}
                </button>
              )}
            </li>
          );
        })}
      </ul>
      <motion.div
        ref={frameRef}
        aria-hidden
        initial={false}
        animate={frameStateOf(isVisible, prefersReducedMotion)}
        transition={frameTransitionOf(isVisible)}
        style={{ x: springX, y: springY }}
        className={cn(
          'bg-foreground/[0.04] pointer-events-none absolute top-0 left-0 z-10 aspect-[3/2] w-60 overflow-hidden rounded-xl shadow-xl shadow-black/8 [@media(hover:none)]:hidden',
          imageClassName
        )}
      >
        {items.map((item) => {
          const isShown = preview?.id === item.id;

          return (
            // eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist
            <img
              key={item.id}
              src={item.src}
              alt=''
              draggable={false}
              decoding='async'
              data-shown={isShown}
              className='absolute inset-0 size-full object-cover opacity-0 transition-opacity duration-150 data-[shown=true]:opacity-100'
            />
          );
        })}
      </motion.div>
    </div>
  );
}

export { ImageReveal };

'use client';
import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';
import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useState,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type ImageTabsOrientation = 'horizontal' | 'vertical';

export type ImageTabsListVariant = 'list' | 'thumbnails';

export type ImageTabsTransition = 'fade' | 'clip';

type PanelState = 'active' | 'previous' | 'idle';

type PanelSide = 'before' | 'after';

type ImageTabsContextValue = {
  value: string;
  previousValue: string | null;
  orientation: ImageTabsOrientation;
};

type ImageTabsFrameContextValue = {
  values: string[];
  transition: ImageTabsTransition;
};

const ImageTabsContext = createContext<ImageTabsContextValue | undefined>(
  undefined
);

const ImageTabsListContext = createContext<ImageTabsListVariant>('list');

const ImageTabsFrameContext = createContext<
  ImageTabsFrameContextValue | undefined
>(undefined);

function useImageTabs() {
  const context = useContext(ImageTabsContext);
  if (!context) {
    throw new Error('useImageTabs must be used within ImageTabs');
  }
  return context;
}

function useImageTabsFrame() {
  const context = useContext(ImageTabsFrameContext);
  if (!context) {
    throw new Error('ImageTabsPanel must be used within ImageTabsFrame');
  }
  return context;
}

function selectedValueOf(
  controlledValue: string | undefined,
  internal: string
) {
  if (controlledValue === undefined) {
    return internal;
  }
  return controlledValue;
}

export type ImageTabsProps = {
  children: ReactNode;
  className?: string;
  defaultValue: string;
  value?: string;
  onValueChange?: (value: string) => void;
  orientation?: ImageTabsOrientation;
};

function ImageTabs({
  children,
  className,
  defaultValue,
  value: controlledValue,
  onValueChange,
  orientation = 'vertical',
}: ImageTabsProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const value = selectedValueOf(controlledValue, internalValue);
  const [shownValue, setShownValue] = useState(value);
  const [previousValue, setPreviousValue] = useState<string | null>(null);

  const hasNewValue = value !== shownValue;
  if (hasNewValue) {
    setPreviousValue(shownValue);
    setShownValue(value);
  }

  const handleValueChange = (nextValue: unknown) => {
    const next = String(nextValue);
    setInternalValue(next);
    onValueChange?.(next);
  };

  return (
    <ImageTabsContext.Provider value={{ value, previousValue, orientation }}>
      <TabsPrimitive.Root
        value={value}
        onValueChange={handleValueChange}
        orientation={orientation}
        className={cn('grid gap-4', className)}
      >
        {children}
      </TabsPrimitive.Root>
    </ImageTabsContext.Provider>
  );
}

