'use client';
import { useEffect, useRef, type ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type ImageTrailImage = {
  src: string;
};

export type ImageTrailProps = {
  images: ImageTrailImage[];
  children?: ReactNode;
  className?: string;
  imageClassName?: string;
  distance?: number;
  maxVisible?: number;
  lifetime?: number;
  persist?: boolean;
};

type TrailState = {
  lastX: number;
  lastY: number;
  hasStarted: boolean;
  spawnCount: number;
};

const EASE_OUT_STRONG = 'cubic-bezier(0.23, 1, 0.32, 1)';

const ENTER_DURATION = 240;

const EXIT_DURATION = 200;

const ENTER_KEYFRAMES: Keyframe[] = [
  { opacity: 0, transform: 'scale(0.9)' },
  { opacity: 1, transform: 'scale(1)' },
];

const EXIT_KEYFRAMES: Keyframe[] = [{ opacity: 0, transform: 'scale(0.82)' }];

function slotCountOf(maxVisible: number) {
  return maxVisible * 2;
}

function hasMovedFarEnough(
  state: TrailState,
  x: number,
  y: number,
  distance: number
) {
  if (!state.hasStarted) {
    return true;
  }
  const travelled = Math.hypot(x - state.lastX, y - state.lastY);
  return travelled >= distance;
}

function retire(slot: HTMLElement | undefined) {
  if (!slot) {
    return;
  }
  slot.animate(EXIT_KEYFRAMES, {
    duration: EXIT_DURATION,
    easing: EASE_OUT_STRONG,
    fill: 'forwards',
  });
}

function swapSource(picture: HTMLImageElement, src: string) {
  const isSameSource = picture.getAttribute('src') === src;
  if (isSameSource) {
    return;
  }
  picture.src = src;
}

function settle(slot: HTMLElement) {
  slot.getAnimations().forEach((animation) => animation.cancel());
}

function ImageTrail({
  images,
  children,
  className,
  imageClassName,
  distance = 80,
  maxVisible = 5,
  lifetime = 900,
  persist = false,
}: ImageTrailProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const slotsRef = useRef<Array<HTMLDivElement | null>>([]);
  const prefersReducedMotion = usePrefersReducedMotion();
  const slotCount = slotCountOf(maxVisible);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    if (prefersReducedMotion) {
      return;
    }
    const hasImages = images.length > 0;
    if (!hasImages) {
      return;
    }

    const state: TrailState = {
      lastX: 0,
      lastY: 0,
      hasStarted: false,
      spawnCount: 0,
    };
    const timers = new Set<number>();
    const slots = slotsRef.current;

    images.forEach((image) => {
      const preload = new Image();
      preload.src = image.src;
    });

    const slotAt = (spawnIndex: number) => {
      const slotIndex = spawnIndex % slotCount;
      return slots[slotIndex] ?? undefined;
    };

    const scheduleRetire = (slot: HTMLElement, spawnIndex: number) => {
      const timer = window.setTimeout(() => {
        timers.delete(timer);
        const isSameSpawn = slot.dataset.spawn === String(spawnIndex);
        if (isSameSpawn) {
          retire(slot);
        }
      }, lifetime);
      timers.add(timer);
    };

    const spawn = (x: number, y: number) => {
      const spawnIndex = state.spawnCount;
      const slot = slotAt(spawnIndex);
      if (!slot) {
        return;
      }
      const image = images[spawnIndex % images.length];
      const picture = slot.firstElementChild;
      settle(slot);
      if (picture instanceof HTMLImageElement) {
        swapSource(picture, image.src);
      }
      slot.dataset.spawn = String(spawnIndex);
      slot.style.translate = `${x}px ${y}px`;
      slot.style.zIndex = String(spawnIndex + 1);
      slot.animate(ENTER_KEYFRAMES, {
        duration: ENTER_DURATION,
        easing: EASE_OUT_STRONG,
        fill: 'forwards',
      });
      const hasPushedOut = spawnIndex >= maxVisible;
      if (hasPushedOut) {
        const pushedOut = slotAt(spawnIndex - maxVisible);
        retire(pushedOut);
      }
      if (!persist) {
        scheduleRetire(slot, spawnIndex);
      }
      state.spawnCount = spawnIndex + 1;
    };

    const handlePointerMove = (event: PointerEvent) => {
      if (event.pointerType === 'touch') {
        return;
      }
      const bounds = container.getBoundingClientRect();
      const x = event.clientX - bounds.left;
      const y = event.clientY - bounds.top;
      const shouldSpawn = hasMovedFarEnough(state, x, y, distance);
      if (!shouldSpawn) {
        return;
      }
      state.lastX = x;
      state.lastY = y;
      state.hasStarted = true;
      spawn(x, y);
    };

    const handlePointerLeave = () => {
      state.hasStarted = false;
    };

    container.addEventListener('pointermove', handlePointerMove, {
      passive: true,
    });
    container.addEventListener('pointerleave', handlePointerLeave, {
      passive: true,
    });

    return () => {
      container.removeEventListener('pointermove', handlePointerMove);
      container.removeEventListener('pointerleave', handlePointerLeave);
      timers.forEach((timer) => window.clearTimeout(timer));
      slots.forEach((slot) => {
        if (slot) {
          settle(slot);
        }
      });
    };
  }, [
    images,
    distance,
    maxVisible,
    lifetime,
    persist,
    slotCount,
    prefersReducedMotion,
  ]);

  const slotIndexes = Array.from({ length: slotCount }, (_, index) => index);

  return (
    <div
      ref={containerRef}
      className={cn('relative isolate overflow-hidden', className)}
    >
      <div
        aria-hidden
        className='pointer-events-none absolute inset-0 z-0 overflow-hidden'
      >
        {slotIndexes.map((slotIndex) => (
          <div
            key={slotIndex}
            ref={(element) => {
              slotsRef.current[slotIndex] = element;
            }}
            className='absolute top-0 left-0 opacity-0'
          >
            {/* eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist */}
            <img
              alt=''
              draggable={false}
              decoding='async'
              className={cn(
                'h-40 w-32 max-w-none -translate-x-1/2 -translate-y-1/2 rounded-lg object-cover shadow-[0_1px_2px_rgb(0_0_0/0.08)]',
                imageClassName
              )}
            />
          </div>
        ))}
      </div>
      <div className='relative z-10'>{children}</div>
    </div>
  );
}

export { ImageTrail };

'use client';
import { ReactNode, useRef, useState } from 'react';
import {
  MotionConfig,
  useInView,
  Variant,
  Transition,
  UseInViewOptions,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import { motionElementOf } from './motion-elements';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean;
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

function ReducedMotionConfig({ children }: { children: ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

export function InView({
  children,
  variants = defaultVariants,
  transition,
  viewOptions,
  as = 'div',
  once,
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false);

  const MotionComponent = motionElementOf(as) as typeof as;

  return (
    <ReducedMotionConfig>
      <MotionComponent
        ref={ref}
        initial='hidden'
        onAnimationComplete={() => {
          if (once) setIsViewed(true);
        }}
        animate={isInView || isViewed ? 'visible' : 'hidden'}

        variants={variants}
        transition={transition}
      >
        {children}
      </MotionComponent>
    </ReducedMotionConfig>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useMotionValue, animate, motion } from 'motion/react';
import { useState, useEffect } from 'react';
import useMeasure from 'react-use-measure';

export type InfiniteSliderProps = {
  children: React.ReactNode;
  gap?: number;
  speed?: number;
  speedOnHover?: number;
  direction?: 'horizontal' | 'vertical';
  reverse?: boolean;
  className?: string;
};

export function InfiniteSlider({
  children,
  gap = 16,
  speed = 100,
  speedOnHover,
  direction = 'horizontal',
  reverse = false,
  className,
}: InfiniteSliderProps) {
  const [currentSpeed, setCurrentSpeed] = useState(speed);
  const [ref, { width, height }] = useMeasure();
  const translation = useMotionValue(0);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [key, setKey] = useState(0);
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    let controls;
    const size = direction === 'horizontal' ? width : height;
    const contentSize = size + gap;
    const from = reverse ? -contentSize / 2 : 0;
    const to = reverse ? 0 : -contentSize / 2;

    if (prefersReducedMotion) {
      translation.jump(from);
      return;
    }

    const isPaused = currentSpeed <= 0;
    if (isPaused) {
      return;
    }

    const distanceToTravel = Math.abs(to - from);
    const duration = distanceToTravel / currentSpeed;

    if (isTransitioning) {
      const remainingDistance = Math.abs(translation.get() - to);
      const transitionDuration = remainingDistance / currentSpeed;

      controls = animate(translation, [translation.get(), to], {
        ease: 'linear',
        duration: transitionDuration,
        onComplete: () => {
          setIsTransitioning(false);
          setKey((prevKey) => prevKey + 1);
        },
      });
    } else {
      controls = animate(translation, [from, to], {
        ease: 'linear',
        duration: duration,
        repeat: Infinity,
        repeatType: 'loop',
        repeatDelay: 0,
        onRepeat: () => {
          translation.set(from);
        },
      });
    }

    return controls?.stop;
  }, [
    key,
    translation,
    currentSpeed,
    width,
    height,
    gap,
    isTransitioning,
    direction,
    reverse,
    prefersReducedMotion,
  ]);

  function slowDown() {
    if (speedOnHover === undefined) {
      return;
    }
    setIsTransitioning(true);
    setCurrentSpeed(speedOnHover);
  }

  function resume() {
    if (speedOnHover === undefined) {
      return;
    }
    setIsTransitioning(true);
    setCurrentSpeed(speed);
  }

  return (
    <div className={cn('overflow-hidden', className)}>
      <motion.div
        className='flex w-max'
        style={{
          ...(direction === 'horizontal'
            ? { x: translation }
            : { y: translation }),
          gap: `${gap}px`,
          flexDirection: direction === 'horizontal' ? 'row' : 'column',
        }}
        ref={ref}
        onHoverStart={slowDown}
        onHoverEnd={resume}
        onFocus={slowDown}
        onBlur={resume}
      >
        {children}
        {children}
      </motion.div>
    </div>
  );
}

