export type LinearModalProps = {
  features: LinearModalFeature[];
  className?: string;
  closeLabel?: string;
};

export function LinearModal({
  features,
  className,
  closeLabel = 'Close',
}: LinearModalProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const scope = useId();
  const [active, setActive] = useState<LinearModalFeature | null>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const transitions = transitionsOf(prefersReducedMotion);
  const isOpen = active !== null;

  function openFeature(
    feature: LinearModalFeature,
    trigger: HTMLButtonElement
  ) {
    triggerRef.current = trigger;
    setActive(feature);
  }

  function changeOpen(open: boolean) {
    if (open) {
      return;
    }
    setActive(null);
  }

  return (
    <>
      <div className={cn('grid gap-3 sm:grid-cols-2', className)}>
        {features.map((feature) => (
          <FeatureCard
            key={feature.id}
            feature={feature}
            ids={layoutIdsOf(scope, feature)}
            transition={transitions.close}
            onOpen={openFeature}
          />
        ))}
      </div>
      <Dialog.Root open={isOpen} onOpenChange={changeOpen}>
        <AnimatePresence>
          {active && (
            <FeatureModal
              key={active.id}
              feature={active}
              ids={layoutIdsOf(scope, active)}
              transitions={transitions}
              closeLabel={closeLabel}
              finalFocus={triggerRef}
            />
          )}
        </AnimatePresence>
      </Dialog.Root>
    </>
  );
}

'use client';

import {
  animate,
  motion,
  type MotionValue,
  useMotionTemplate,
  useMotionValue,
  useSpring,
} from 'motion/react';
import { useEffect, useRef } from 'react';

import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type MagicCardTint = 'primary' | 'neutral';

const TINT_COLORS = {
  primary: {
    rim: 'color-mix(in oklab, var(--primary) 75%, transparent)',
    wash: 'color-mix(in oklab, var(--primary) 6%, transparent)',
  },
  neutral: {
    rim: 'color-mix(in oklab, var(--foreground) 40%, transparent)',
    wash: 'color-mix(in oklab, var(--foreground) 3%, transparent)',
  },
} satisfies Record<MagicCardTint, { rim: string; wash: string }>;

const ANGLE_SPRING = { stiffness: 320, damping: 40 };

const STRENGTH_SPRING = { stiffness: 260, damping: 36 };

const WASH_RADIUS = 280;

const WASH_IN = { duration: 0.3, ease: [0.23, 1, 0.32, 1] as const };

const WASH_OUT = { duration: 0.15, ease: [0.23, 1, 0.32, 1] as const };

const RIM_SHAPE: React.CSSProperties = {
  inset: 'calc(var(--hairline, 1px) * -1)',
  padding: 1,
  mask: 'linear-gradient(black, black) content-box exclude, linear-gradient(black, black)',
  WebkitMask:
    'linear-gradient(black, black) content-box xor, linear-gradient(black, black)',
};

const CARD = [
  'relative isolate rounded-xl bg-card text-card-foreground',
  'hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
].join(' ');

function clamp(value: number, min: number, max: number) {
  const atLeastMin = Math.max(value, min);
  return Math.min(atLeastMin, max);
}

function distanceOutside(box: DOMRect, x: number, y: number) {
  const beforeLeft = box.left - x;
  const pastRight = x - box.right;
  const aboveTop = box.top - y;
  const belowBottom = y - box.bottom;
  const horizontal = Math.max(beforeLeft, 0, pastRight);
  const vertical = Math.max(aboveTop, 0, belowBottom);
  return Math.hypot(horizontal, vertical);
}

/** Conic gradients start at the top and turn clockwise, so the pointer angle is measured the same way. */
function pointerAngleOf(box: DOMRect, x: number, y: number) {
  const centreX = box.left + box.width / 2;
  const centreY = box.top + box.height / 2;
  const deltaX = x - centreX;
  const deltaY = y - centreY;
  const radians = Math.atan2(deltaY, deltaX);
  const degrees = (radians * 180) / Math.PI;
  return degrees + 90;
}

function continuousAngleOf(target: number, previous: number) {
  const difference = target - previous;
  const turns = Math.round(difference / 360);
  const wrapped = difference - turns * 360;
  return previous + wrapped;
}

function followedOf(
  prefersReducedMotion: boolean | null,
  raw: MotionValue<number>,
  smooth: MotionValue<number>
) {
  if (prefersReducedMotion) {
    return raw;
  }
  return smooth;
}

function washTransitionOf(isInside: boolean) {
  if (isInside) {
    return WASH_IN;
  }
  return WASH_OUT;
}

function washOpacityOf(isInside: boolean) {
  if (isInside) {
    return 1;
  }
  return 0;
}

export type MagicCardProps = React.ComponentProps<'div'> & {
  tint?: MagicCardTint;
  proximity?: number;
  spread?: number;
};

export function MagicCard({
  tint = 'primary',
  proximity = 120,
  spread = 70,
  className,
  children,
  ...props
}: MagicCardProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const rawAngle = useMotionValue(0);
  const rawStrength = useMotionValue(0);
  const smoothAngle = useSpring(rawAngle, ANGLE_SPRING);
  const smoothStrength = useSpring(rawStrength, STRENGTH_SPRING);
  const localX = useMotionValue(0);
  const localY = useMotionValue(0);
  const washOpacity = useMotionValue(0);
  const colors = TINT_COLORS[tint];
  const angle = followedOf(prefersReducedMotion, rawAngle, smoothAngle);
  const strength = followedOf(
    prefersReducedMotion,
    rawStrength,
    smoothStrength
  );
  const spreadEnd = spread * 2;
  const rimLight = useMotionTemplate`conic-gradient(from ${angle}deg at 50% 50%, transparent 0deg, ${colors.rim} ${spread}deg, transparent ${spreadEnd}deg)`;
  const washLight = useMotionTemplate`radial-gradient(${WASH_RADIUS}px circle at ${localX}px ${localY}px, ${colors.wash}, transparent)`;

  useEffect(() => {
    const card = cardRef.current;
    if (!card) {
      return;
    }
    let frame = 0;
    let isNear = false;
    let isInside = false;
    let pointerX = 0;
    let pointerY = 0;

    const setInside = (nextInside: boolean) => {
      if (nextInside === isInside) {
        return;
      }
      isInside = nextInside;
      const opacity = washOpacityOf(nextInside);
      const transition = washTransitionOf(nextInside);
      animate(washOpacity, opacity, transition);
    };

    const update = () => {
      frame = 0;
      const box = card.getBoundingClientRect();
      const distance = distanceOutside(box, pointerX, pointerY);
      const nearness = 1 - distance / proximity;
      const pointerAngle = pointerAngleOf(box, pointerX, pointerY);
      const startAngle = pointerAngle - spread;
      const previousAngle = rawAngle.get();
      const nextAngle = continuousAngleOf(startAngle, previousAngle);
      const wasDark = rawStrength.get() === 0;
      rawAngle.set(nextAngle);
      if (wasDark) {
        smoothAngle.jump(nextAngle);
      }
      const nextStrength = clamp(nearness, 0, 1);
      const cardX = pointerX - box.left;
      const cardY = pointerY - box.top;
      const isPointerInside = distance === 0;
      rawStrength.set(nextStrength);
      localX.set(cardX);
      localY.set(cardY);
      setInside(isPointerInside);
    };

    const track = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') {
        return;
      }
      pointerX = event.clientX;
      pointerY = event.clientY;
      if (frame) {
        return;
      }
      frame = requestAnimationFrame(update);
    };

    const fade = () => {
      rawStrength.set(0);
      setInside(false);
    };

    const startTracking = () => {
      window.addEventListener('pointermove', track, { passive: true });
      document.documentElement.addEventListener('pointerleave', fade);
    };

    const stopTracking = () => {
      window.removeEventListener('pointermove', track);
      document.documentElement.removeEventListener('pointerleave', fade);
      cancelAnimationFrame(frame);
      frame = 0;
    };

    const nearObserver = new IntersectionObserver(
      ([entry]) => {
        const wasNear = isNear;
        isNear = entry.isIntersecting;
        if (isNear === wasNear) {
          return;
        }
        if (isNear) {
          startTracking();
          return;
        }
        stopTracking();
        fade();
      },
      { rootMargin: `${proximity}px` }
    );
    nearObserver.observe(card);

    return () => {
      nearObserver.disconnect();
      stopTracking();
    };
  }, [
    proximity,
    spread,
    rawAngle,
    rawStrength,
    smoothAngle,
    localX,
    localY,
    washOpacity,
  ]);

  return (
    <div ref={cardRef} className={cn(CARD, className)} {...props}>
      <motion.span
        aria-hidden='true'
        className='pointer-events-none absolute inset-0 rounded-[inherit]'
        style={{ background: washLight, opacity: washOpacity }}
      />
      <motion.span
        aria-hidden='true'
        className='pointer-events-none absolute rounded-[inherit]'
        style={{ ...RIM_SHAPE, background: rimLight, opacity: strength }}
      />
      <div className='relative'>{children}</div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import {
  motion,
  useMotionValue,
  useSpring,
  type SpringOptions,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const SPRING_CONFIG = { stiffness: 26.7, damping: 4.1, mass: 0.2 };

export type MagneticProps = {
  children: React.ReactNode;
  intensity?: number;
  range?: number;
  actionArea?: 'self' | 'parent' | 'global';
  springOptions?: SpringOptions;
};

export function Magnetic({
  children,
  intensity = 0.6,
  range = 100,
  actionArea = 'self',
  springOptions = SPRING_CONFIG,
}: MagneticProps) {
  const [isHovered, setIsHovered] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isGlobal = actionArea === 'global';
  const isAttracting = isGlobal || isHovered;
  const canMove = !prefersReducedMotion;

  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const springX = useSpring(x, springOptions);
  const springY = useSpring(y, springOptions);

  useEffect(() => {
    const calculateDistance = (e: MouseEvent) => {
      if (ref.current) {
        const rect = ref.current.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;
        const distanceX = e.clientX - centerX;
        const distanceY = e.clientY - centerY;

        const absoluteDistance = Math.sqrt(distanceX ** 2 + distanceY ** 2);

        const isWithinRange = absoluteDistance <= range;
        const shouldPull = canMove && isAttracting && isWithinRange;
        if (shouldPull) {
          const scale = 1 - absoluteDistance / range;
          x.set(distanceX * intensity * scale);
          y.set(distanceY * intensity * scale);
        } else {
          x.set(0);
          y.set(0);
        }
      }
    };

    document.addEventListener('mousemove', calculateDistance);

    return () => {
      document.removeEventListener('mousemove', calculateDistance);
    };
  }, [ref, isAttracting, canMove, intensity, range, x, y]);

  useEffect(() => {
    if (actionArea === 'parent' && ref.current?.parentElement) {
      const parent = ref.current.parentElement;

      const handleParentEnter = () => setIsHovered(true);
      const handleParentLeave = () => setIsHovered(false);

      parent.addEventListener('mouseenter', handleParentEnter);
      parent.addEventListener('mouseleave', handleParentLeave);

      return () => {
        parent.removeEventListener('mouseenter', handleParentEnter);
        parent.removeEventListener('mouseleave', handleParentLeave);
      };
    }
  }, [actionArea]);

  const handleMouseEnter = () => {
    if (actionArea === 'self') {
      setIsHovered(true);
    }
  };

  const handleMouseLeave = () => {
    if (actionArea === 'self') {
      setIsHovered(false);
      x.set(0);
      y.set(0);
    }
  };

  return (
    <motion.div
      ref={ref}
      onMouseEnter={actionArea === 'self' ? handleMouseEnter : undefined}
      onMouseLeave={actionArea === 'self' ? handleMouseLeave : undefined}
      style={{
        x: springX,
        y: springY,
      }}
    >
      {children}
    </motion.div>
  );
}

'use client';
import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';
import {
  motion,
  useMotionValue,
  useSpring,
  useTransform,
  type MotionValue,
} from 'motion/react';
import {
  Children,
  createContext,
  useContext,
  useEffect,
  useRef,
  type PointerEvent,
  type ReactNode,
  type RefObject,
} from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ImageTabs,
  ImageTabsFrame,
  ImageTabsImage,
  ImageTabsPanel,
  type ImageTabsProps,
} from './image-tabs';

type DockLayout = {
  centers: number[];
  sizes: number[];
};

type DockMetrics = {
  pointerX: number;
  presence: number;
  layout: DockLayout;
  magnification: number;
  distance: number;
};

type DockContextValue = {
  pointer: MotionValue<number>;
  presence: MotionValue<number>;
  layoutRef: RefObject<DockLayout>;
  magnification: number;
  distance: number;
};

const POINTER_SPRING = { stiffness: 520, damping: 46 };

const PRESENCE_SPRING = { stiffness: 320, damping: 36 };

const RESTING_PRESENCE = 0.05;

const DockContext = createContext<DockContextValue | undefined>(undefined);

const DockItemIndexContext = createContext(0);

function useDock() {
  const context = useContext(DockContext);
  if (!context) {
    throw new Error('MagnifiedDocItem must be used within MagnifiedDocDock');
  }
  return context;
}

function measureLayout(list: HTMLElement): DockLayout {
  const items = list.querySelectorAll<HTMLElement>('[data-dock-item]');
  const centers: number[] = [];
  const sizes: number[] = [];
  items.forEach((item) => {
    const center = item.offsetLeft + item.offsetWidth / 2;
    centers.push(center);
    sizes.push(item.offsetWidth);
  });
  return { centers, sizes };
}

function weightOf(offsetFromPointer: number, distance: number) {
  const ratio = Math.abs(offsetFromPointer) / distance;
  if (ratio >= 1) {
    return 0;
  }
  const wave = Math.cos(ratio * Math.PI);
  return (wave + 1) / 2;
}

function growthOf(index: number, metrics: DockMetrics) {
  const center = metrics.layout.centers[index] ?? 0;
  const size = metrics.layout.sizes[index] ?? 0;
  const weight = weightOf(metrics.pointerX - center, metrics.distance);
  const maximumGrowth = (metrics.magnification - 1) * size;
  return weight * metrics.presence * maximumGrowth;
}

function scaleOf(index: number, metrics: DockMetrics) {
  const size = metrics.layout.sizes[index];
  if (!size) {
    return 1;
  }
  const growth = growthOf(index, metrics);
  return 1 + growth / size;
}

/** Translates each item as if its neighbours had grown in width, so the row spreads like a dock without animating layout. */
function shiftOf(index: number, metrics: DockMetrics) {
  let growthBefore = 0;
  let totalGrowth = 0;
  metrics.layout.centers.forEach((_, otherIndex) => {
    const growth = growthOf(otherIndex, metrics);
    totalGrowth += growth;
    if (otherIndex < index) {
      growthBefore += growth;
    }
  });
  const ownGrowth = growthOf(index, metrics);
  return growthBefore + ownGrowth / 2 - totalGrowth / 2;
}

function liftOf(index: number, metrics: DockMetrics) {
  const growth = growthOf(index, metrics);
  return -growth;
}

export type MagnifiedDocProps = Omit<ImageTabsProps, 'orientation'>;

function MagnifiedDoc({ className, ...props }: MagnifiedDocProps) {
  return (
    <ImageTabs
      orientation='horizontal'
      className={cn('relative', className)}
      {...props}
    />
  );
}

export type MagnifiedDocDockProps = {
  children: ReactNode;
  className?: string;
  magnification?: number;
  distance?: number;
  'aria-label'?: string;
};

function MagnifiedDocDock({
  children,
  className,
  magnification = 1.6,
  distance = 120,
  'aria-label': ariaLabel,
}: MagnifiedDocDockProps) {
  const listRef = useRef<HTMLDivElement>(null);
  const layoutRef = useRef<DockLayout>({ centers: [], sizes: [] });
  const pointerTarget = useMotionValue(0);
  const presenceTarget = useMotionValue(0);
  const pointer = useSpring(pointerTarget, POINTER_SPRING);
  const presence = useSpring(presenceTarget, PRESENCE_SPRING);
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    const list = listRef.current;
    if (!list) {
      return;
    }
    const remeasure = () => {
      layoutRef.current = measureLayout(list);
    };
    remeasure();
    const observer = new ResizeObserver(remeasure);
    observer.observe(list);
    return () => observer.disconnect();
  }, []);

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (prefersReducedMotion) {
      return;
    }
    if (event.pointerType === 'touch') {
      return;
    }
    const listLeft = event.currentTarget.getBoundingClientRect().left;
    const pointerX = event.clientX - listLeft;
    const isResting = presence.get() < RESTING_PRESENCE;
    pointerTarget.set(pointerX);
    if (isResting) {
      pointer.jump(pointerX);
    }
    presenceTarget.set(1);
  };

  const handlePointerLeave = () => {
    presenceTarget.set(0);
  };

  const items = Children.toArray(children);

  return (
    <DockContext.Provider
      value={{ pointer, presence, layoutRef, magnification, distance }}
    >
      <TabsPrimitive.List
        ref={listRef}
        activateOnFocus
        aria-label={ariaLabel}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
        className={cn(
          'surface-raised absolute bottom-3 left-1/2 z-10 flex w-fit -translate-x-1/2 items-end gap-2 rounded-2xl px-2 pt-2 pb-1',
          className
        )}
      >
        {items.map((item, index) => (
          <DockItemIndexContext.Provider key={index} value={index}>
            {item}
          </DockItemIndexContext.Provider>
        ))}
      </TabsPrimitive.List>
    </DockContext.Provider>
  );
}

export type MagnifiedDocItemProps = {
  value: string;
  label: string;
  children: ReactNode;
  className?: string;
};

function MagnifiedDocItem({
  value,
  label,
  children,
  className,
}: MagnifiedDocItemProps) {
  const index = useContext(DockItemIndexContext);
  const { pointer, presence, layoutRef, magnification, distance } = useDock();

  const metricsOf = (): DockMetrics => ({
    pointerX: pointer.get(),
    presence: presence.get(),
    layout: layoutRef.current,
    magnification,
    distance,
  });

  const scale = useTransform(() => scaleOf(index, metricsOf()));
  const x = useTransform(() => shiftOf(index, metricsOf()));
  const labelY = useTransform(() => liftOf(index, metricsOf()));

  return (
    <motion.div
      data-dock-item=''
      style={{ x }}
      className='group/dock-item relative flex flex-col items-center gap-1'
    >
      <motion.span
        aria-hidden
        style={{ y: labelY }}
        className='surface-raised pointer-events-none absolute bottom-full left-1/2 mb-2 -translate-x-1/2 rounded-lg px-2 py-0.5 text-xs font-medium whitespace-nowrap opacity-0 transition-opacity duration-150 group-hover/dock-item:opacity-100 group-has-[:focus-visible]/dock-item:opacity-100'
      >
        {label}
      </motion.span>
      <TabsPrimitive.Tab
        value={value}
        aria-label={label}
        render={<motion.button style={{ scale, originY: 1 }} />}
        className={cn(
          'keycap-3d text-foreground focus-visible:ring-ring focus-visible:ring-offset-background grid size-10 cursor-pointer place-items-center overflow-hidden rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-offset-2 [&_svg]:size-5',
          className
        )}
      >
        {children}
      </TabsPrimitive.Tab>
      <span
        aria-hidden
        className='bg-foreground size-1 rounded-full opacity-0 transition-opacity duration-150 group-has-[[data-active]]/dock-item:opacity-100'
      />
    </motion.div>
  );
}

