'use client';
import { cn } from '@/lib/utils';

export type MarqueeDirection = 'horizontal' | 'vertical';

type MarqueeStyle = React.CSSProperties & {
  '--marquee-gap': string;
  '--marquee-duration'?: string;
};

const TRACK_CLASS: Record<MarqueeDirection, string> = {
  horizontal: 'w-max motion-safe:animate-marquee motion-reduce:w-full',
  vertical: 'h-max flex-col motion-safe:animate-marquee-y',
};

const COPY_CLASS: Record<MarqueeDirection, string> = {
  horizontal: 'items-center pr-(--marquee-gap)',
  vertical: 'flex-col pb-(--marquee-gap)',
};

const FIRST_COPY_REDUCED_CLASS: Record<MarqueeDirection, string> = {
  horizontal:
    'motion-reduce:w-full motion-reduce:flex-wrap motion-reduce:justify-center motion-reduce:pr-0',
  vertical: '',
};

const FADE_CLASS: Record<MarqueeDirection, string> = {
  horizontal: 'mask-x-from-85% motion-reduce:mask-none',
  vertical: 'mask-y-from-85%',
};

const PAUSE_CLASS =
  'group-hover/marquee:[animation-play-state:paused] group-focus-within/marquee:[animation-play-state:paused]';

function styleOf(gap: number, duration: number | undefined) {
  const style: MarqueeStyle = { '--marquee-gap': `${gap}px` };
  if (duration !== undefined) {
    style['--marquee-duration'] = `${duration}s`;
  }
  return style;
}

function isRepeatedCopy(index: number) {
  return index > 0;
}

function hiddenFromReadersOf(isRepeated: boolean) {
  if (isRepeated) {
    return true;
  }
  return undefined;
}

export type MarqueeProps = {
  children: React.ReactNode;
  direction?: MarqueeDirection;
  reverse?: boolean;
  pauseOnHover?: boolean;
  gap?: number;
  duration?: number;
  repeat?: number;
  fade?: boolean;
  className?: string;
};

export function Marquee({
  children,
  direction = 'horizontal',
  reverse = false,
  pauseOnHover = true,
  gap = 16,
  duration,
  repeat = 2,
  fade = true,
  className,
}: MarqueeProps) {
  const copyCount = repeat * 2;
  const copies = Array.from({ length: copyCount }, (_, index) => index);
  const isVertical = direction === 'vertical';

  return (
    <div
      style={styleOf(gap, duration)}
      className={cn(
        'group/marquee flex overflow-hidden',
        isVertical && 'flex-col',
        fade && FADE_CLASS[direction],
        className
      )}
    >
      <div
        className={cn(
          'flex',
          TRACK_CLASS[direction],
          reverse && '[animation-direction:reverse]!',
          pauseOnHover && PAUSE_CLASS
        )}
      >
        {copies.map((index) => {
          const isRepeated = isRepeatedCopy(index);

          return (
            <div
              key={index}
              aria-hidden={hiddenFromReadersOf(isRepeated)}
              inert={isRepeated}
              className={cn(
                'flex shrink-0 gap-(--marquee-gap)',
                COPY_CLASS[direction],
                isRepeated && 'motion-reduce:hidden',
                !isRepeated && FIRST_COPY_REDUCED_CLASS[direction]
              )}
            >
              {children}
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';
import { motion, useInView } from 'motion/react';
import {
  Children,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type MasonryGridLayout = 'columns' | 'balanced';

export type MasonryGridProps = {
  children: ReactNode;
  className?: string;
  layout?: MasonryGridLayout;
  columnWidth?: number;
  maxColumns?: number;
  gap?: number;
  revealOnView?: boolean;
};

type Cell = {
  key: string;
  node: ReactNode;
};

type MasonryContextValue = {
  gap: number;
  revealOnView: boolean;
  seenKeys: Set<string>;
  markSeen: (key: string) => void;
};

const MasonryContext = createContext<MasonryContextValue | undefined>(
  undefined
);

const REVEAL_MARGIN = '0px 0px -8% 0px';

const REVEAL_HIDDEN = { opacity: 0, y: 12 };

const REVEAL_SHOWN = { opacity: 1, y: 0 };

const COLUMN_STAGGER = 0.04;

function useMasonry() {
  const context = useContext(MasonryContext);
  if (!context) {
    throw new Error('MasonryCell must be used within MasonryGrid');
  }
  return context;
}

function cellsOf(children: ReactNode) {
  const cells: Cell[] = [];
  Children.toArray(children).forEach((child, index) => {
    let key = String(index);
    if (isValidElement(child) && child.key !== null) {
      key = String(child.key);
    }
    cells.push({ key, node: child });
  });
  return cells;
}

function columnCountOf(
  width: number,
  columnWidth: number,
  gap: number,
  maxColumns: number
) {
  const fitting = Math.floor((width + gap) / (columnWidth + gap));
  const atLeastOne = Math.max(1, fitting);
  return Math.min(maxColumns, atLeastOne);
}

function indexOfShortest(totals: number[]) {
  let shortest = 0;
  totals.forEach((total, index) => {
    if (total < totals[shortest]) {
      shortest = index;
    }
  });
  return shortest;
}

/** Places each item, in reading order, at the bottom of the shortest column. */
function balancedColumnsOf(heights: number[], columnCount: number) {
  const columns: number[][] = Array.from({ length: columnCount }, () => []);
  const totals: number[] = Array.from({ length: columnCount }, () => 0);
  heights.forEach((height, index) => {
    const shortest = indexOfShortest(totals);
    columns[shortest].push(index);
    totals[shortest] += height;
  });
  return columns;
}

function measuredHeightsOf(container: HTMLElement, count: number) {
  const heights: number[] = Array.from({ length: count }, () => 0);
  const cells = container.querySelectorAll<HTMLElement>('[data-masonry-cell]');
  cells.forEach((cell) => {
    const index = Number(cell.dataset.masonryCell);
    heights[index] = cell.offsetHeight;
  });
  return heights;
}

function roundRobinColumnsOf(cellCount: number, columnCount: number) {
  const columns: number[][] = Array.from({ length: columnCount }, () => []);
  for (let index = 0; index < cellCount; index += 1) {
    const columnIndex = index % columnCount;
    columns[columnIndex].push(index);
  }
  return columns;
}

function placedCountOf(columns: number[][]) {
  let placed = 0;
  columns.forEach((column) => {
    placed += column.length;
  });
  return placed;
}

function fitsLayout(
  columns: number[][] | null,
  columnCount: number,
  cellCount: number
) {
  if (!columns) {
    return false;
  }
  const hasSameColumnCount = columns.length === columnCount;
  const placesEveryCell = placedCountOf(columns) === cellCount;
  return hasSameColumnCount && placesEveryCell;
}

function contentWidthOf(container: HTMLElement) {
  const style = window.getComputedStyle(container);
  const paddingLeft = Number.parseFloat(style.paddingLeft);
  const paddingRight = Number.parseFloat(style.paddingRight);
  return container.clientWidth - paddingLeft - paddingRight;
}

function sameColumns(current: number[][] | null, next: number[][]) {
  if (!current) {
    return false;
  }
  return JSON.stringify(current) === JSON.stringify(next);
}

function revealDelayOf(columnIndex: number) {
  return columnIndex * COLUMN_STAGGER;
}

type MasonryCellProps = {
  children: ReactNode;
  cellKey: string;
  index: number;
  columnIndex: number;
};

function StaticCell({ children, index }: MasonryCellProps) {
  const { gap } = useMasonry();

  return (
    <div
      data-masonry-cell={index}
      style={{ marginBottom: gap }}
      className='break-inside-avoid'
    >
      {children}
    </div>
  );
}

function RevealCell({
  children,
  cellKey,
  index,
  columnIndex,
}: MasonryCellProps) {
  const ref = useRef<HTMLDivElement>(null);
  const { gap, markSeen } = useMasonry();
  const isInView = useInView(ref, { once: true, margin: REVEAL_MARGIN });

  useEffect(() => {
    if (isInView) {
      markSeen(cellKey);
    }
  }, [isInView, cellKey, markSeen]);

  return (
    <motion.div
      ref={ref}
      data-masonry-cell={index}
      style={{ marginBottom: gap }}
      initial={REVEAL_HIDDEN}
      animate={isInView && REVEAL_SHOWN}
      transition={{
        duration: 0.32,
        ease: [0.23, 1, 0.32, 1],
        delay: revealDelayOf(columnIndex),
      }}
      className='break-inside-avoid'
    >
      {children}
    </motion.div>
  );
}

/**
 * Whether the cell was new is read once per mount, so marking it as seen does not swap it
 * mid-entrance. The motion preference stays live: it is only known after the page hydrates.
 */
function MasonryCell(props: MasonryCellProps) {
  const { revealOnView, seenKeys } = useMasonry();
  const prefersReducedMotion = usePrefersReducedMotion();
  const [isFirstEntry] = useState(() => !seenKeys.has(props.cellKey));
  const isMotionAllowed = !prefersReducedMotion;
  const wantsReveal = revealOnView && isMotionAllowed;
  const shouldReveal = wantsReveal && isFirstEntry;

  if (shouldReveal) {
    return <RevealCell {...props} />;
  }
  return <StaticCell {...props} />;
}

function MasonryGrid({
  children,
  className,
  layout = 'columns',
  columnWidth = 220,
  maxColumns = 4,
  gap = 16,
  revealOnView = false,
}: MasonryGridProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [columnCount, setColumnCount] = useState(0);
  const [columns, setColumns] = useState<number[][] | null>(null);
  const [seenKeys, setSeenKeys] = useState<Set<string>>(() => new Set());
  const cells = cellsOf(children);
  const cellCount = cells.length;
  const cellSignature = cells.map((cell) => cell.key).join('|');
  const isBalanced = layout === 'balanced';

  const markSeen = useCallback((key: string) => {
    setSeenKeys((current) => {
      if (current.has(key)) {
        return current;
      }
      const next = new Set(current);
      next.add(key);
      return next;
    });
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    if (!isBalanced) {
      return;
    }
    const observer = new ResizeObserver(() => {
      const width = contentWidthOf(container);
      const count = columnCountOf(width, columnWidth, gap, maxColumns);
      setColumnCount(count);
    });
    observer.observe(container);
    return () => observer.disconnect();
  }, [isBalanced, columnWidth, gap, maxColumns]);

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    if (!isBalanced) {
      return;
    }
    const width = contentWidthOf(container);
    const count = columnCountOf(width, columnWidth, gap, maxColumns);
    if (count !== columnCount) {
      setColumnCount(count);
      return;
    }
    const hasFittingColumns = fitsLayout(columns, count, cellCount);
    if (!hasFittingColumns) {
      setColumns(roundRobinColumnsOf(cellCount, count));
      return;
    }
    const heights = measuredHeightsOf(container, cellCount);
    const next = balancedColumnsOf(heights, count);
    if (!sameColumns(columns, next)) {
      setColumns(next);
    }
  }, [
    isBalanced,
    columnCount,
    columns,
    cellCount,
    cellSignature,
    columnWidth,
    gap,
    maxColumns,
  ]);

  const contextValue = { gap, revealOnView, seenKeys, markSeen };
  const hasBalancedColumns = isBalanced && columns !== null;

  if (hasBalancedColumns) {
    return (
      <MasonryContext.Provider value={contextValue}>
        <div
          ref={containerRef}
          style={{ columnGap: gap }}
          className={cn('flex items-start', className)}
          data-layout='balanced'
        >
          {columns.map((column, columnIndex) => (
            <div key={columnIndex} className='flex min-w-0 flex-1 flex-col'>
              {column.map((cellIndex) => {
                const cell = cells[cellIndex];
                if (!cell) {
                  return null;
                }
                return (
                  <MasonryCell
                    key={cell.key}
                    cellKey={cell.key}
                    index={cellIndex}
                    columnIndex={columnIndex}
                  >
                    {cell.node}
                  </MasonryCell>
                );
              })}
            </div>
          ))}
        </div>
      </MasonryContext.Provider>
    );
  }

  return (
    <MasonryContext.Provider value={contextValue}>
      <div
        ref={containerRef}
        style={{ columnWidth, columnCount: maxColumns, columnGap: gap }}
        className={className}
        data-layout='columns'
      >
        {cells.map((cell, index) => (
          <MasonryCell
            key={cell.key}
            cellKey={cell.key}
            index={index}
            columnIndex={0}
          >
            {cell.node}
          </MasonryCell>
        ))}
      </div>
    </MasonryContext.Provider>
  );
}

export { MasonryGrid };

'use client';

import React, {
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react';
import {
  motion,
  AnimatePresence,
  MotionConfig,
  Transition,
  Variant,
} from 'motion/react';
import { createPortal } from 'react-dom';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { XIcon } from '@/registry/ndeko/lib/icons';
import useClickOutside from '@/hooks/useClickOutside';

export type MorphingDialogContextType = {
  isOpen: boolean;
  setIsOpen: React.Dispatch<React.SetStateAction<boolean>>;
  uniqueId: string;
  triggerRef: React.RefObject<HTMLButtonElement | null>;
};

const MorphingDialogContext =
  React.createContext<MorphingDialogContextType | null>(null);

function useMorphingDialog() {
  const context = useContext(MorphingDialogContext);
  if (!context) {
    throw new Error(
      'useMorphingDialog must be used within a MorphingDialogProvider'
    );
  }
  return context;
}

function ReducedMotionConfig({ children }: { children: React.ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

function subscribeToNothing() {
  return () => {};
}

function isOnClient() {
  return true;
}

function isOnServer() {
  return false;
}

export type MorphingDialogProviderProps = {
  children: React.ReactNode;
  transition?: Transition;
};

function MorphingDialogProvider({
  children,
  transition,
}: MorphingDialogProviderProps) {
  const [isOpen, setIsOpen] = useState(false);
  const uniqueId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null!);

  const contextValue = useMemo(
    () => ({
      isOpen,
      setIsOpen,
      uniqueId,
      triggerRef,
    }),
    [isOpen, uniqueId]
  );

  return (
    <MorphingDialogContext.Provider value={contextValue}>
      <ReducedMotionConfig>
        <MotionConfig transition={transition}>{children}</MotionConfig>
      </ReducedMotionConfig>
    </MorphingDialogContext.Provider>
  );
}

export type MorphingDialogProps = {
  children: React.ReactNode;
  transition?: Transition;
};

function MorphingDialog({ children, transition }: MorphingDialogProps) {
  return (
    <MorphingDialogProvider>
      <MotionConfig transition={transition}>{children}</MotionConfig>
    </MorphingDialogProvider>
  );
}

export type MorphingDialogTriggerProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  triggerRef?: React.RefObject<HTMLButtonElement>;
};

function MorphingDialogTrigger({
  children,
  className,
  style,
  triggerRef,
}: MorphingDialogTriggerProps) {
  const { setIsOpen, isOpen, uniqueId } = useMorphingDialog();

  const handleClick = useCallback(() => {
    setIsOpen(!isOpen);
  }, [isOpen, setIsOpen]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        setIsOpen(!isOpen);
      }
    },
    [isOpen, setIsOpen]
  );

  return (
    <motion.button
      ref={triggerRef}
      layoutId={`dialog-${uniqueId}`}
      className={cn('relative cursor-pointer', className)}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      style={style}
      aria-haspopup='dialog'
      aria-expanded={isOpen}
      aria-controls={`motion-ui-morphing-dialog-content-${uniqueId}`}
      aria-label={`Open dialog ${uniqueId}`}
    >
      {children}
    </motion.button>
  );
}

export type MorphingDialogContentProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
};

function MorphingDialogContent({
  children,
  className,
  style,
}: MorphingDialogContentProps) {
  const { setIsOpen, isOpen, uniqueId, triggerRef } = useMorphingDialog();
  const containerRef = useRef<HTMLDivElement>(null!);
  const firstFocusableRef = useRef<HTMLElement | null>(null);
  const lastFocusableRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsOpen(false);
      }
      if (event.key === 'Tab') {
        const firstFocusableElement = firstFocusableRef.current;
        const lastFocusableElement = lastFocusableRef.current;
        if (!firstFocusableElement || !lastFocusableElement) return;

        if (event.shiftKey) {
          if (document.activeElement === firstFocusableElement) {
            event.preventDefault();
            lastFocusableElement.focus();
          }
        } else {
          if (document.activeElement === lastFocusableElement) {
            event.preventDefault();
            firstFocusableElement.focus();
          }
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [setIsOpen]);

  useEffect(() => {
    if (isOpen) {
      document.body.classList.add('overflow-hidden');
      const focusableElements = containerRef.current?.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (focusableElements && focusableElements.length > 0) {
        firstFocusableRef.current = focusableElements[0] as HTMLElement;
        lastFocusableRef.current = focusableElements[
          focusableElements.length - 1
        ] as HTMLElement;
        (focusableElements[0] as HTMLElement).focus();
      }
    } else {
      document.body.classList.remove('overflow-hidden');
      triggerRef.current?.focus();
    }
  }, [isOpen, triggerRef]);

  useClickOutside(containerRef, () => {
    if (isOpen) {
      setIsOpen(false);
    }
  });

  return (
    <motion.div
      ref={containerRef}
      layoutId={`dialog-${uniqueId}`}
      className={cn('overflow-hidden', className)}
      style={style}
      role='dialog'
      aria-modal='true'
      aria-labelledby={`motion-ui-morphing-dialog-title-${uniqueId}`}
      aria-describedby={`motion-ui-morphing-dialog-description-${uniqueId}`}
    >
      {children}
    </motion.div>
  );
}

export type MorphingDialogContainerProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
};

function MorphingDialogContainer({ children }: MorphingDialogContainerProps) {
  const { isOpen, uniqueId } = useMorphingDialog();
  const mounted = useSyncExternalStore(
    subscribeToNothing,
    isOnClient,
    isOnServer
  );

  if (!mounted) return null;

  return createPortal(
    <AnimatePresence initial={false} mode='sync'>
      {isOpen && (
        <>
          <motion.div
            key={`backdrop-${uniqueId}`}
            className='bg-background/40 fixed inset-0 h-full w-full backdrop-blur-xs'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          />
          <div className='fixed inset-0 z-50 flex items-center justify-center'>
            {children}
          </div>
        </>
      )}
    </AnimatePresence>,
    document.body
  );
}

export type MorphingDialogTitleProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
};

function MorphingDialogTitle({
  children,
  className,
  style,
}: MorphingDialogTitleProps) {
  const { uniqueId } = useMorphingDialog();

  return (
    <motion.div
      layoutId={`dialog-title-container-${uniqueId}`}
      className={className}
      style={style}
      layout
    >
      {children}
    </motion.div>
  );
}

export type MorphingDialogSubtitleProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
};

function MorphingDialogSubtitle({
  children,
  className,
  style,
}: MorphingDialogSubtitleProps) {
  const { uniqueId } = useMorphingDialog();

  return (
    <motion.div
      layoutId={`dialog-subtitle-container-${uniqueId}`}
      className={className}
      style={style}
    >
      {children}
    </motion.div>
  );
}

export type MorphingDialogDescriptionProps = {
  children: React.ReactNode;
  className?: string;
  disableLayoutAnimation?: boolean;
  variants?: {
    initial: Variant;
    animate: Variant;
    exit: Variant;
  };
};

function MorphingDialogDescription({
  children,
  className,
  variants,
  disableLayoutAnimation,
}: MorphingDialogDescriptionProps) {
  const { uniqueId } = useMorphingDialog();

  return (
    <motion.div
      key={`dialog-description-${uniqueId}`}
      layoutId={
        disableLayoutAnimation
          ? undefined
          : `dialog-description-content-${uniqueId}`
      }
      variants={variants}
      className={className}
      initial='initial'
      animate='animate'
      exit='exit'
      id={`dialog-description-${uniqueId}`}
    >
      {children}
    </motion.div>
  );
}

export type MorphingDialogImageProps = {
  src: string;
  alt: string;
  className?: string;
  style?: React.CSSProperties;
};

function MorphingDialogImage({
  src,
  alt,
  className,
  style,
}: MorphingDialogImageProps) {
  const { uniqueId } = useMorphingDialog();

  return (
    <motion.img
      src={src}
      alt={alt}
      className={cn(className)}
      layoutId={`dialog-img-${uniqueId}`}
      style={style}
    />
  );
}

export type MorphingDialogCloseProps = {
  children?: React.ReactNode;
  className?: string;
  variants?: {
    initial: Variant;
    animate: Variant;
    exit: Variant;
  };
};

function MorphingDialogClose({
  children,
  className,
  variants,
}: MorphingDialogCloseProps) {
  const { setIsOpen, uniqueId } = useMorphingDialog();

  const handleClose = useCallback(() => {
    setIsOpen(false);
  }, [setIsOpen]);

  return (
    <motion.button
      onClick={handleClose}
      type='button'
      aria-label='Close dialog'
      key={`dialog-close-${uniqueId}`}
      className={cn('absolute top-6 right-6', className)}
      initial='initial'
      animate='animate'
      exit='exit'
      variants={variants}
    >
      {children || <XIcon size={24} />}
    </motion.button>
  );
}

