function dateOf(value: Date | string) {
  if (value instanceof Date) {
    return value;
  }
  return new Date(value);
}

function compactOf(count: number, locale: string) {
  const format = new Intl.NumberFormat(locale, {
    notation: 'compact',
    maximumFractionDigits: 1,
  });
  return format.format(count);
}

function spokenCountOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${plural}`;
}

function spokenViewsOf(views: number) {
  if (views === 1) {
    return 'view';
  }
  return 'views';
}

function timeOf(date: Date, locale: string, timeZone: string) {
  const format = new Intl.DateTimeFormat(locale, {
    hour: 'numeric',
    minute: '2-digit',
    timeZone,
  });
  return format.format(date);
}

function dayOf(date: Date, locale: string, timeZone: string) {
  const format = new Intl.DateTimeFormat(locale, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    timeZone,
  });
  return format.format(date);
}

function PostText({ text }: { text: string }) {
  const parts = text.split(HIGHLIGHT_PATTERN);

  return (
    <p className='mt-3 text-sm leading-relaxed text-pretty whitespace-pre-line'>
      {parts.map((part, index) => {
        const isHighlight = HIGHLIGHT_TEST.test(part);
        if (isHighlight) {
          return (
            <span key={index} className='text-primary-ink'>
              {part}
            </span>
          );
        }
        return <Fragment key={index}>{part}</Fragment>;
      })}
    </p>
  );
}

function PostMediaGrid({ media }: { media: PostMedia[] }) {
  const shown = media.slice(0, MAX_MEDIA);
  const layout = MEDIA_LAYOUTS[shown.length];

  return (
    <div className='mt-3 grid aspect-video grid-cols-2 grid-rows-2 gap-0.5 overflow-hidden rounded-lg'>
      {shown.map((item, index) => (
        // eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist
        <img
          key={item.src}
          src={item.src}
          alt={item.alt}
          loading='lazy'
          className={cn('bg-muted size-full object-cover', layout[index])}
        />
      ))}
    </div>
  );
}

function PostStat({
  stat,
  count,
  locale,
}: {
  stat: StatDefinition;
  count: number;
  locale: string;
}) {
  const StatIcon = stat.icon;

  return (
    <li className='text-muted-foreground flex items-center gap-1.5 text-[13px]'>
      <StatIcon className='size-4' />
      <span aria-hidden='true' className='tabular-nums'>
        {compactOf(count, locale)}
      </span>
      <span className='sr-only'>
        {spokenCountOf(count, stat.singular, stat.plural)}
      </span>
    </li>
  );
}

function hasCount(count: number | undefined): count is number {
  return count !== undefined;
}

export type PostCardProps = Omit<
  React.ComponentProps<'article'>,
  'children'
> & {
  author: PostAuthor;
  text: string;
  date: Date | string;
  media?: PostMedia[];
  counts?: PostCounts;
  href?: string;
  locale?: string;
  timeZone?: string;
};

export function PostCard({
  author,
  text,
  date,
  media = [],
  counts = {},
  href,
  locale = 'en-US',
  timeZone = 'UTC',
  className,
  ...props
}: PostCardProps) {
  const postedAt = dateOf(date);
  const time = timeOf(postedAt, locale, timeZone);
  const day = dayOf(postedAt, locale, timeZone);
  const hasMedia = media.length > 0;
  const views = counts.views;
  const hasViews = hasCount(views);
  const shownStats = STATS.filter((stat) => hasCount(counts[stat.name]));
  const timestamp = (
    <time dateTime={postedAt.toISOString()}>
      {time} · {day}
    </time>
  );

  return (
    <article
      className={cn(
        'bg-card text-card-foreground hairline-ring ring-border w-full max-w-lg rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
      {...props}
    >
      <header className='flex items-center gap-3'>
        <Avatar className='size-10' seed={author.name}>
          {author.avatar && <AvatarImage src={author.avatar} alt='' />}
        </Avatar>
        <div className='flex min-w-0 flex-col'>
          <span className='flex min-w-0 items-center gap-1'>
            <span className='truncate text-sm font-semibold'>
              {author.name}
            </span>
            {author.verified && (
              <>
                <BadgeCheckIcon className='text-primary-ink size-4 shrink-0' />
                <span className='sr-only'>Verified account</span>
              </>
            )}
          </span>
          <span className='text-muted-foreground truncate text-[13px]'>
            @{author.handle}
          </span>
        </div>
      </header>
      <PostText text={text} />
      {hasMedia && <PostMediaGrid media={media} />}
      <footer>
        <p className='text-muted-foreground mt-3 text-[13px]'>
          {href && (
            <a
              href={href}
              className='hover:text-foreground focus-visible:ring-ring/25 rounded-sm underline-offset-4 outline-none hover:underline focus-visible:ring-3'
            >
              {timestamp}
            </a>
          )}
          {!href && timestamp}
          {hasViews && (
            <>
              {' · '}
              <span className='text-foreground font-medium tabular-nums'>
                {compactOf(views, locale)}
              </span>{' '}
              {spokenViewsOf(views)}
            </>
          )}
        </p>
        {shownStats.length > 0 && (
          <ul className='mt-3 flex items-center gap-6'>
            {shownStats.map((stat) => (
              <PostStat
                key={stat.name}
                stat={stat}
                count={counts[stat.name] ?? 0}
                locale={locale}
              />
            ))}
          </ul>
        )}
      </footer>
    </article>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { HTMLMotionProps, motion, MotionConfig } from 'motion/react';

export const GRADIENT_ANGLES = {
  top: 0,
  right: 90,
  bottom: 180,
  left: 270,
};

function ReducedMotionConfig({ children }: { children: React.ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

function maskColorOf(stopIndex: number) {
  const isInsideBand = stopIndex === 1 || stopIndex === 2;
  if (isInsideBand) {
    return 'black';
  }
  return 'transparent';
}

/** Without explicit levels, each layer blurs `index * intensity` pixels, as before. */
function blursOf(
  blurLevels: readonly number[] | undefined,
  blurLayers: number,
  blurIntensity: number
) {
  const hasLevels = blurLevels !== undefined && blurLevels.length > 0;
  if (hasLevels) {
    return [...blurLevels];
  }
  const layerCount = Math.max(blurLayers, 2);
  return Array.from({ length: layerCount }, (_, index) => {
    return index * blurIntensity;
  });
}

export type ProgressiveBlurProps = {
  direction?: keyof typeof GRADIENT_ANGLES;
  blurLayers?: number;
  className?: string;
  blurIntensity?: number;
  blurLevels?: readonly number[];
} & HTMLMotionProps<'div'>;

export function ProgressiveBlur({
  direction = 'bottom',
  blurLayers = 8,
  className,
  blurIntensity = 0.25,
  blurLevels,
  ...props
}: ProgressiveBlurProps) {
  const blurs = blursOf(blurLevels, blurLayers, blurIntensity);
  const bandCount = blurs.length + 1;
  const segmentSize = 1 / bandCount;

  return (
    <ReducedMotionConfig>
      <div aria-hidden='true' className={cn('relative', className)}>
        {blurs.map((blur, index) => {
          const angle = GRADIENT_ANGLES[direction];
          const gradientStops = [
            index * segmentSize,
            (index + 1) * segmentSize,
            (index + 2) * segmentSize,
            (index + 3) * segmentSize,
          ].map((pos, posIndex) => `${maskColorOf(posIndex)} ${pos * 100}%`);

          const gradient = `linear-gradient(${angle}deg, ${gradientStops.join(
            ', '
          )})`;

          return (
            <motion.div
              key={index}
              className='pointer-events-none absolute inset-0 rounded-[inherit]'
              style={{
                maskImage: gradient,
                WebkitMaskImage: gradient,
                backdropFilter: `blur(${blur}px)`,
                WebkitBackdropFilter: `blur(${blur}px)`,
              }}
              {...props}
            />
          );
        })}
      </div>
    </ReducedMotionConfig>
  );
}

'use client';

import { Reorder, type Transition, useDragControls } from 'motion/react';
import { useId, useRef, useState } from 'react';

import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ChevronDownIcon,
  ChevronUpIcon,
  GripVerticalIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

const SETTLE: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const LIFT = { scale: 1.02 };

const ROW = [
  'relative flex items-center gap-1 rounded-xl bg-card p-1.5 text-card-foreground',
  'hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
  'outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring',
].join(' ');

const HANDLE = [
  'grid size-7 shrink-0 cursor-grab touch-none place-items-center rounded-md text-muted-foreground',
  'transition-colors hover:bg-foreground/5 hover:text-foreground active:cursor-grabbing',
].join(' ');

function moveItem<T>(items: T[], from: number, to: number) {
  const next = [...items];
  const [moved] = next.splice(from, 1);
  next.splice(to, 0, moved);
  return next;
}

function settleOf(prefersReducedMotion: boolean | null) {
  if (prefersReducedMotion) {
    return INSTANT;
  }
  return SETTLE;
}

function liftOf(prefersReducedMotion: boolean | null) {
  if (prefersReducedMotion) {
    return undefined;
  }
  return LIFT;
}

function positionMessage(label: string, index: number, count: number) {
  const position = index + 1;
  return `${label} moved to position ${position} of ${count}`;
}

type ReorderRowProps<T> = {
  item: T;
  index: number;
  count: number;
  label: string;
  hintId: string;
  groupRef: React.RefObject<HTMLUListElement | null>;
  onMove: (from: number, to: number) => void;
  onDragStart: () => void;
  onDragEnd: () => void;
  children: React.ReactNode;
};

function ReorderRow<T>({
  item,
  index,
  count,
  label,
  hintId,
  groupRef,
  onMove,
  onDragStart,
  onDragEnd,
  children,
}: ReorderRowProps<T>) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const controls = useDragControls();
  const isFirst = index === 0;
  const lastIndex = count - 1;
  const isLast = index === lastIndex;

  function startDrag(event: React.PointerEvent) {
    onDragStart();
    controls.start(event);
  }

  function moveUp() {
    onMove(index, index - 1);
  }

  function moveDown() {
    onMove(index, index + 1);
  }

  return (
    <Reorder.Item
      value={item}
      dragListener={false}
      dragControls={controls}
      dragConstraints={groupRef}
      dragElastic={0.08}
      onDragEnd={onDragEnd}
      whileDrag={liftOf(prefersReducedMotion)}
      transition={settleOf(prefersReducedMotion)}
      aria-describedby={hintId}
      className={ROW}
    >
      <span aria-hidden='true' className={HANDLE} onPointerDown={startDrag}>
        <GripVerticalIcon className='size-4' />
      </span>
      <div className='min-w-0 flex-1 px-1'>{children}</div>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        className='text-muted-foreground'
        aria-label={`Move ${label} up`}
        disabled={isFirst}
        focusableWhenDisabled
        onClick={moveUp}
      >
        <ChevronUpIcon />
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        className='text-muted-foreground'
        aria-label={`Move ${label} down`}
        disabled={isLast}
        focusableWhenDisabled
        onClick={moveDown}
      >
        <ChevronDownIcon />
      </Button>
    </Reorder.Item>
  );
}

export type ReorderListProps<T> = {
  items: T[];
  onReorder: (items: T[]) => void;
  getKey: (item: T) => string;
  getLabel: (item: T) => string;
  renderItem: (item: T) => React.ReactNode;
  className?: string;
  'aria-label'?: string;
};

export function ReorderList<T>({
  items,
  onReorder,
  getKey,
  getLabel,
  renderItem,
  className,
  'aria-label': ariaLabel,
}: ReorderListProps<T>) {
  const groupRef = useRef<HTMLUListElement>(null);
  const isPointerDragging = useRef(false);
  const draggedItem = useRef<T | null>(null);
  const [announcement, setAnnouncement] = useState('');
  const hintId = useId();
  const count = items.length;

  function announce(item: T, nextItems: T[]) {
    const index = nextItems.indexOf(item);
    const label = getLabel(item);
    const message = positionMessage(label, index, count);
    setAnnouncement(message);
  }

  function reorderFromGroup(nextItems: T[], moved: T) {
    onReorder(nextItems);
    draggedItem.current = moved;
    if (isPointerDragging.current) {
      return;
    }
    announce(moved, nextItems);
  }

  function moveByButton(from: number, to: number) {
    const moved = items[from];
    const nextItems = moveItem(items, from, to);
    onReorder(nextItems);
    announce(moved, nextItems);
  }

  function beginPointerDrag() {
    isPointerDragging.current = true;
    draggedItem.current = null;
  }

  function endPointerDrag() {
    isPointerDragging.current = false;
    const moved = draggedItem.current;
    if (moved === null) {
      return;
    }
    announce(moved, items);
  }

  return (
    <>
      <Reorder.Group
        ref={groupRef}
        axis='y'
        values={items}
        onReorder={reorderFromGroup}
        aria-label={ariaLabel}
        className={cn('flex flex-col gap-2', className)}
      >
        {items.map((item, index) => (
          <ReorderRow
            key={getKey(item)}
            item={item}
            index={index}
            count={count}
            label={getLabel(item)}
            hintId={hintId}
            groupRef={groupRef}
            onMove={moveByButton}
            onDragStart={beginPointerDrag}
            onDragEnd={endPointerDrag}
          >
            {renderItem(item)}
          </ReorderRow>
        ))}
      </Reorder.Group>
      <p id={hintId} className='sr-only'>
        Drag the handle, use the move buttons, or press Space to pick up the
        row, the arrow keys to move it and Space to drop it.
      </p>
      <p aria-live='polite' className='sr-only'>
        {announcement}
      </p>
    </>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef, type ComponentProps, type ReactNode } from 'react';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  CopyIcon,
  PadlockIcon,
  PanelLeftIcon,
  PlusIcon,
  RefreshCwIcon,
  ShareBoxIcon,
} from '@/registry/ndeko/lib/icons';

export type SafariMode = 'simple' | 'full';

export type SafariProps = Omit<ComponentProps<'figure'>, 'children'> & {
  url?: string;
  imageSrc?: string;
  videoSrc?: string;
  alt?: string;
  mode?: SafariMode;
  aspectRatio?: number;
  label?: string;
  children?: ReactNode;
};

const DEFAULT_URL = 'example.com';

const DEFAULT_ASPECT_RATIO = 16 / 10;

const PROTOCOL_PATTERN = /^[a-z][a-z0-9+.-]*:\/\//i;

const TRAILING_SLASH_PATTERN = /\/$/;

const TRAFFIC_LIGHTS = [
  { name: 'close', color: 'hsl(3 100% 67%)' },
  { name: 'minimize', color: 'hsl(41 99% 59%)' },
  { name: 'zoom', color: 'hsl(129 67% 47%)' },
];

const MEDIA_FADE_SECONDS = 0.24;

const MEDIA_ENTER = {
  duration: MEDIA_FADE_SECONDS,
  ease: [0.23, 1, 0.32, 1],
} as const;

const MEDIA_EXIT = { duration: 0, delay: MEDIA_FADE_SECONDS } as const;

const TOOLBAR_HEIGHT: Record<SafariMode, string> = {
  simple: 'h-11',
  full: 'h-[52px]',
};

function displayUrlOf(url: string) {
  const withoutProtocol = url.replace(PROTOCOL_PATTERN, '');
  return withoutProtocol.replace(TRAILING_SLASH_PATTERN, '');
}

function contentRatioOf(
  aspectRatio: number | undefined,
  hasMedia: boolean,
  hasChildren: boolean
) {
  if (aspectRatio !== undefined) {
    return aspectRatio;
  }
  if (hasMedia) {
    return DEFAULT_ASPECT_RATIO;
  }
  if (hasChildren) {
    return undefined;
  }
  return DEFAULT_ASPECT_RATIO;
}

function ignoreRefusedPlayback() {
  return undefined;
}

function TrafficLights() {
  return (
    <span className='flex shrink-0 items-center gap-2'>
      {TRAFFIC_LIGHTS.map((light) => (
        <span
          key={light.name}
          className='size-3 rounded-full shadow-[inset_0_0_0_0.5px_rgb(0_0_0/0.14)]'
          style={{ backgroundColor: light.color }}
        />
      ))}
    </span>
  );
}

function ToolbarGlyph({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <span
      className={cn(
        'flex size-7 shrink-0 items-center justify-center [&_svg]:size-4',
        className
      )}
    >
      {children}
    </span>
  );
}

function AddressField({ url }: { url: string }) {
  return (
    <span className='bg-foreground/[0.05] dark:bg-foreground/[0.08] flex h-[30px] min-w-0 items-center gap-1.5 rounded-lg px-2.5'>
      {/* Balances the reload glyph so the address sits in the middle of the field, as Safari centres it. */}
      <span className='size-3.5 shrink-0' />
      <span className='flex min-w-0 flex-1 items-center justify-center gap-1'>
        <PadlockIcon className='text-muted-foreground size-3 shrink-0' />
        <span className='text-foreground truncate text-[13px] leading-none'>
          {url}
        </span>
      </span>
      <RefreshCwIcon className='text-muted-foreground size-3.5 shrink-0' />
    </span>
  );
}

function Toolbar({ url, mode }: { url: string; mode: SafariMode }) {
  const isFull = mode === 'full';

  return (
    <div
      aria-hidden='true'
      className={cn(
        'hairline-b border-border bg-foreground/[0.03] dark:bg-foreground/[0.05] grid grid-cols-[minmax(max-content,1fr)_minmax(0,30rem)_minmax(max-content,1fr)] items-center gap-3 pr-3 pl-5 select-none dark:shadow-[inset_0_1px_0_rgb(255_255_255/0.06)]',
        TOOLBAR_HEIGHT[mode]
      )}
    >
      <span className='text-muted-foreground flex items-center gap-5'>
        <TrafficLights />
        {isFull && (
          <span className='flex items-center'>
            <ToolbarGlyph className='mr-2 @max-xl:hidden'>
              <PanelLeftIcon />
            </ToolbarGlyph>
            <ToolbarGlyph>
              <ChevronLeftIcon />
            </ToolbarGlyph>
            <ToolbarGlyph className='opacity-40 @max-md:hidden'>
              <ChevronRightIcon />
            </ToolbarGlyph>
          </span>
        )}
      </span>
      <AddressField url={url} />
      <span className='text-muted-foreground flex items-center justify-end'>
        {isFull && (
          <>
            <ToolbarGlyph className='@max-xl:hidden'>
              <ShareBoxIcon />
            </ToolbarGlyph>
            <ToolbarGlyph className='@max-md:hidden'>
              <PlusIcon />
            </ToolbarGlyph>
            <ToolbarGlyph className='@max-md:hidden'>
              <CopyIcon />
            </ToolbarGlyph>
          </>
        )}
      </span>
    </div>
  );
}

function WindowVideo({ src, alt }: { src: string; alt: string }) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isDecorative = alt === '';
  const showsControls = Boolean(shouldReduceMotion);
  const isHidden = isDecorative && !showsControls;

  useEffect(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (shouldReduceMotion) {
      video.pause();
      return;
    }
    const playback = video.play();
    playback.catch(ignoreRefusedPlayback);
  }, [shouldReduceMotion]);

  return (
    <video
      ref={videoRef}
      src={src}
      muted
      loop
      playsInline
      preload='metadata'
      controls={showsControls}
      aria-label={alt || undefined}
      aria-hidden={isHidden || undefined}
      className='size-full object-cover object-top'
    />
  );
}

function WindowMedia({
  imageSrc,
  videoSrc,
  alt,
}: {
  imageSrc?: string;
  videoSrc?: string;
  alt: string;
}) {
  const mediaKey = videoSrc ?? imageSrc;
  const hasVideo = videoSrc !== undefined;
  const hasImage = imageSrc !== undefined;
  const showsImage = hasImage && !hasVideo;

  return (
    <AnimatePresence initial={false}>
      <motion.div
        key={mediaKey}
        className='absolute inset-0'
        initial={{ opacity: 0 }}
        animate={{ opacity: 1, transition: MEDIA_ENTER }}
        exit={{ opacity: 0, transition: MEDIA_EXIT }}
      >
        {hasVideo && <WindowVideo src={videoSrc} alt={alt} />}
        {showsImage && (
          // eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist
          <img
            src={imageSrc}
            alt={alt}
            draggable={false}
            className='size-full object-cover object-top'
          />
        )}
      </motion.div>
    </AnimatePresence>
  );
}

export function Safari({
  url = DEFAULT_URL,
  imageSrc,
  videoSrc,
  alt = '',
  mode = 'full',
  aspectRatio,
  label,
  className,
  children,
  ...props
}: SafariProps) {
  const displayUrl = displayUrlOf(url);
  const figureLabel = label ?? `Browser window at ${displayUrl}`;
  const hasMedia = Boolean(imageSrc || videoSrc);
  const hasChildren = children !== undefined && children !== null;
  const contentRatio = contentRatioOf(aspectRatio, hasMedia, hasChildren);
  const hasFixedHeight = contentRatio !== undefined;

  return (
    <figure
      aria-label={figureLabel}
      className={cn(
        'bg-card text-card-foreground hairline-ring ring-foreground/10 @container relative w-full overflow-hidden rounded-xl shadow-xl shadow-black/8',
        className
      )}
      {...props}
    >
      <Toolbar url={displayUrl} mode={mode} />
      <div
        className='bg-background text-foreground relative'
        style={{ aspectRatio: contentRatio }}
      >
        {hasMedia && (
          <WindowMedia imageSrc={imageSrc} videoSrc={videoSrc} alt={alt} />
        )}
        {hasChildren && (
          <div
            className={cn(
              'relative',
              hasFixedHeight &&
                'absolute inset-0 [scrollbar-width:thin] overflow-y-auto overscroll-contain'
            )}
          >
            {children}
          </div>
        )}
      </div>
    </figure>
  );
}

'use client';
import {
  motion,
  type MotionValue,
  type Transition,
  useInView,
  useScroll,
  useTransform,
  type Variants,
} from 'motion/react';
import { type ReactNode, type RefObject, useRef } from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const EASE_OUT_STRONG = [0.23, 1, 0.32, 1] as const;

export type ScrollAnimationPreset = 'fade-up' | 'scale-in' | 'clip-reveal';

type Preset = {
  variants: Variants;
  duration: number;
};

const PRESETS: Record<ScrollAnimationPreset, Preset> = {
  'fade-up': {
    variants: {
      hidden: { opacity: 0, y: 16 },
      visible: { opacity: 1, y: 0 },
    },
    duration: 0.5,
  },
  'scale-in': {
    variants: {
      hidden: { opacity: 0, scale: 0.96 },
      visible: { opacity: 1, scale: 1 },
    },
    duration: 0.5,
  },
  'clip-reveal': {
    variants: {
      hidden: { clipPath: 'inset(100% 0% 0% 0%)' },
      visible: { clipPath: 'inset(0% 0% 0% 0%)' },
    },
    duration: 0.7,
  },
};

function revealStateOf(isRevealed: boolean) {
  if (isRevealed) {
    return 'visible';
  }
  return 'hidden';
}

// Under reduced motion both states are the final one, so the element is written in place on
// mount instead of keeping the hidden styles rendered on the server.
function variantsOf(
  preset: ScrollAnimationPreset,
  prefersReducedMotion: boolean | null
): Variants {
  const { variants } = PRESETS[preset];
  if (prefersReducedMotion) {
    return { hidden: variants.visible, visible: variants.visible };
  }
  return variants;
}

export type ScrollAnimationProps = {
  children: ReactNode;
  preset?: ScrollAnimationPreset;
  delay?: number;
  amount?: number;
  className?: string;
  containerRef?: RefObject<HTMLElement | null>;
};

export function ScrollAnimation({
  children,
  preset = 'fade-up',
  delay = 0,
  amount = 0.3,
  className,
  containerRef,
}: ScrollAnimationProps) {
  const ref = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isInView = useInView(ref, { root: containerRef, once: true, amount });
  const revealState = revealStateOf(isInView);
  const variants = variantsOf(preset, prefersReducedMotion);
  const transition: Transition = {
    duration: PRESETS[preset].duration,
    ease: EASE_OUT_STRONG,
    delay,
  };

  return (
    <motion.div
      ref={ref}
      initial='hidden'
      animate={revealState}
      variants={variants}
      transition={transition}
      className={className}
    >
      {children}
    </motion.div>
  );
}

function layerOffsetOf(
  prefersReducedMotion: boolean | null,
  offset: MotionValue<number>
) {
  if (prefersReducedMotion) {
    return 0;
  }
  return offset;
}

export type ScrollParallaxProps = {
  children: ReactNode;
  strength?: number;
  className?: string;
  layerClassName?: string;
  containerRef?: RefObject<HTMLElement | null>;
};

export function ScrollParallax({
  children,
  strength = 40,
  className,
  layerClassName,
  containerRef,
}: ScrollParallaxProps) {
  const frameRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const { scrollYProgress } = useScroll({
    target: frameRef,
    container: containerRef,
    offset: ['start end', 'end start'],
  });
  const offset = useTransform(scrollYProgress, [0, 1], [-strength, strength]);
  const reach = Math.abs(strength);
  const bleed = -reach;
  const layerOffset = layerOffsetOf(prefersReducedMotion, offset);

  return (
    <div ref={frameRef} className={cn('relative overflow-clip', className)}>
      <motion.div
        style={{
          y: layerOffset,
          top: bleed,
          bottom: bleed,
        }}
        className={cn('absolute inset-x-0', layerClassName)}
      >
        {children}
      </motion.div>
    </div>
  );
}

'use client';

import {
  motion,
  MotionValue,
  SpringOptions,
  useScroll,
  useSpring,
} from 'motion/react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { RefObject } from 'react';

export type ScrollProgressProps = {
  className?: string;
  springOptions?: SpringOptions;
  containerRef?: RefObject<HTMLDivElement | null>;
};

const DEFAULT_SPRING_OPTIONS: SpringOptions = {
  stiffness: 200,
  damping: 50,
  restDelta: 0.001,
};

function followerOf(
  prefersReducedMotion: boolean | null,
  target: MotionValue<number>,
  spring: MotionValue<number>
) {
  if (prefersReducedMotion) {
    return target;
  }
  return spring;
}

export function ScrollProgress({
  className,
  springOptions,
  containerRef,
}: ScrollProgressProps) {
  const { scrollYProgress } = useScroll({
    container: containerRef,
  });

  const prefersReducedMotion = usePrefersReducedMotion();

  const springScaleX = useSpring(scrollYProgress, {
    ...DEFAULT_SPRING_OPTIONS,
    ...(springOptions ?? {}),
  });
  const scaleX = followerOf(
    prefersReducedMotion,
    scrollYProgress,
    springScaleX
  );

  return (
    <motion.div
      className={cn('inset-x-0 top-0 h-1 origin-left', className)}
      style={{
        scaleX,
      }}
    />
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  motion,
  useAnimationFrame,
  useInView,
  useMotionValue,
  useScroll,
  useSpring,
  useTransform,
  useVelocity,
  wrap,
  type MotionValue,
} from 'motion/react';
import { useRef, type RefObject } from 'react';
import useMeasure from 'react-use-measure';

export type ScrollTextMarqueeDirection = 'left' | 'right';

type DirectionSign = 1 | -1;

type MeasureRef = ReturnType<typeof useMeasure>[0];

const VELOCITY_SPRING = { damping: 50, stiffness: 400 };

/** At 1000px of scroll per second, the text runs this many times faster than at rest. */
const BOOST_PER_1000_PX = 4;

function signOf(direction: ScrollTextMarqueeDirection): DirectionSign {
  if (direction === 'right') {
    return 1;
  }
  return -1;
}

function oppositeOf(sign: DirectionSign): DirectionSign {
  if (sign === 1) {
    return -1;
  }
  return 1;
}

function translateOf(offset: number, copyWidth: number) {
  if (copyWidth === 0) {
    return 'translateX(0px)';
  }
  const wrappedOffset = wrap(-copyWidth, 0, offset);
  return `translateX(${wrappedOffset}px)`;
}

function hiddenFromReadersOf(index: number) {
  if (index > 0) {
    return true;
  }
  return undefined;
}

function measuredRefOf(index: number, measureRef: MeasureRef) {
  if (index === 0) {
    return measureRef;
  }
  return undefined;
}

type MarqueeDriverProps = {
  offset: MotionValue<number>;
  boost: MotionValue<number>;
  speed: number;
  baseSign: DirectionSign;
  bidirectional: boolean;
  signRef: RefObject<DirectionSign>;
};

/**
 * The frame loop of the animation library runs for as long as one `useAnimationFrame` is mounted,
 * even when its callback does nothing, and each of those frames costs the whole page. So the loop
 * lives in this leaf, which is mounted only while the text moves.
 */
function MarqueeDriver({
  offset,
  boost,
  speed,
  baseSign,
  bidirectional,
  signRef,
}: MarqueeDriverProps) {
  useAnimationFrame((_, delta) => {
    const currentBoost = boost.get();
    const isScrollingUp = currentBoost < 0;
    const isScrollingDown = currentBoost > 0;
    if (!bidirectional) {
      signRef.current = baseSign;
    }
    const followsScrollUp = bidirectional && isScrollingUp;
    const followsScrollDown = bidirectional && isScrollingDown;
    if (followsScrollUp) {
      signRef.current = oppositeOf(baseSign);
    }
    if (followsScrollDown) {
      signRef.current = baseSign;
    }
    const seconds = delta / 1000;
    const distanceAtRest = speed * seconds;
    const boostSize = Math.abs(currentBoost);
    const multiplier = 1 + boostSize;
    const distance = distanceAtRest * multiplier;
    const step = signRef.current * distance;
    const nextOffset = offset.get() + step;
    offset.set(nextOffset);
  });

  return null;
}

export type ScrollTextMarqueeProps = {
  children: React.ReactNode;
  speed?: number;
  direction?: ScrollTextMarqueeDirection;
  bidirectional?: boolean;
  repeat?: number;
  containerRef?: RefObject<HTMLElement | null>;
  className?: string;
};

export function ScrollTextMarquee({
  children,
  speed = 60,
  direction = 'left',
  bidirectional = false,
  repeat = 4,
  containerRef,
  className,
}: ScrollTextMarqueeProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [copyRef, { width: copyWidth }] = useMeasure();
  const shouldReduceMotion = usePrefersReducedMotion();
  const isInView = useInView(rootRef);
  const baseSign = signOf(direction);
  const signRef = useRef<DirectionSign>(baseSign);
  const offset = useMotionValue(0);
  const { scrollY } = useScroll({ container: containerRef });
  const scrollVelocity = useVelocity(scrollY);
  const smoothVelocity = useSpring(scrollVelocity, VELOCITY_SPRING);
  const boost = useTransform(
    smoothVelocity,
    [0, 1000],
    [0, BOOST_PER_1000_PX],
    { clamp: false }
  );
  const transform = useTransform(offset, (latest) =>
    translateOf(latest, copyWidth)
  );
  const copies = Array.from({ length: repeat }, (_, index) => index);
  const isStill = shouldReduceMotion || !isInView;
  const isMoving = !isStill;

  return (
    <div
      ref={rootRef}
      className={cn(
        'flex overflow-hidden text-5xl leading-tight font-semibold whitespace-nowrap sm:text-7xl',
        className
      )}
    >
      {isMoving && (
        <MarqueeDriver
          offset={offset}
          boost={boost}
          speed={speed}
          baseSign={baseSign}
          bidirectional={bidirectional}
          signRef={signRef}
        />
      )}
      <motion.div className='flex w-max' style={{ transform }}>
        {copies.map((index) => (
          <span
            key={index}
            ref={measuredRefOf(index, copyRef)}
            aria-hidden={hiddenFromReadersOf(index)}
            className='shrink-0 pr-[0.4em]'
          >
            {children}
          </span>
        ))}
      </motion.div>
    </div>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  motion,
  useScroll,
  useTransform,
  type MotionValue,
  type UseScrollOptions,
} from 'motion/react';
import { useRef, type RefObject } from 'react';
import { motionElementOf } from './motion-elements';

export type ScrollTextMode = 'word' | 'character' | 'highlight';

export type ScrollTextTag =
  'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'blockquote' | 'div' | 'span';

type ScrollOffset = UseScrollOptions['offset'];

type Range = [number, number];

type Word = {
  text: string;
  trailingSpace: string;
  characters: string[];
  firstCharacter: number;
};

const DEFAULT_OFFSET: ScrollOffset = ['start 0.85', 'end 0.5'];

const DIMMED_OPACITY = 0.18;

const SPACE_AFTER_WORD = /^(\S+)(\s*)$/;

function graphemesOf(text: string) {
  const canSegment = typeof Intl.Segmenter === 'function';
  if (!canSegment) {
    return Array.from(text);
  }
  const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  const segments = Array.from(segmenter.segment(text));
  return segments.map((segment) => segment.segment);
}

function wordsOf(text: string) {
  const tokens = text.match(/\S+\s*/g) ?? [];
  const words: Word[] = [];
  let characterCount = 0;

  for (const token of tokens) {
    const match = SPACE_AFTER_WORD.exec(token);
    const wordText = match?.[1] ?? token;
    const trailingSpace = match?.[2] ?? '';
    const characters = graphemesOf(wordText);
    words.push({
      text: wordText,
      trailingSpace,
      characters,
      firstCharacter: characterCount,
    });
    characterCount += characters.length;
  }

  return { words, characterCount };
}

function rangeOf(index: number, total: number): Range {
  const nextIndex = index + 1;
  const start = index / total;
  const end = nextIndex / total;
  return [start, end];
}

function revealStyleOf(isStatic: boolean | null, opacity: MotionValue<number>) {
  if (isStatic) {
    return undefined;
  }
  return { opacity };
}

function fillStyleOf(isStatic: boolean | null, scaleX: MotionValue<number>) {
  if (isStatic) {
    return undefined;
  }
  return { scaleX };
}

function RevealSpan({
  progress,
  range,
  isStatic,
  children,
}: {
  progress: MotionValue<number>;
  range: Range;
  isStatic: boolean | null;
  children: React.ReactNode;
}) {
  const opacity = useTransform(progress, range, [DIMMED_OPACITY, 1]);

  return (
    <motion.span style={revealStyleOf(isStatic, opacity)}>
      {children}
    </motion.span>
  );
}

function HighlightSpan({
  progress,
  range,
  isStatic,
  children,
}: {
  progress: MotionValue<number>;
  range: Range;
  isStatic: boolean | null;
  children: React.ReactNode;
}) {
  const scaleX = useTransform(progress, range, [0, 1]);

  return (
    <span className='relative'>
      <motion.span
        className='bg-primary/15 absolute inset-x-0 inset-y-[0.1em] -z-10 origin-left'
        style={fillStyleOf(isStatic, scaleX)}
      />
      {children}
    </span>
  );
}

export type ScrollTextProps = {
  children: string;
  mode?: ScrollTextMode;
  as?: ScrollTextTag;
  offset?: ScrollOffset;
  containerRef?: RefObject<HTMLElement | null>;
  className?: string;
};

export function ScrollText({
  children,
  mode = 'word',
  as = 'p',
  offset = DEFAULT_OFFSET,
  containerRef,
  className,
}: ScrollTextProps) {
  const ref = useRef<HTMLParagraphElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const { scrollYProgress } = useScroll({
    target: ref,
    container: containerRef,
    offset,
  });
  const MotionComponent = motionElementOf(as) as typeof motion.p;
  const { words, characterCount } = wordsOf(children);
  const wordCount = words.length;

  function renderWord(word: Word, wordIndex: number) {
    const key = `${wordIndex}-${word.text}`;

    if (mode === 'highlight') {
      return (
        <HighlightSpan
          key={key}
          progress={scrollYProgress}
          range={rangeOf(wordIndex, wordCount)}
          isStatic={shouldReduceMotion}
        >
          {word.text}
          {word.trailingSpace}
        </HighlightSpan>
      );
    }

    if (mode === 'character') {
      return (
        <span key={key}>
          {word.characters.map((character, characterIndex) => {
            const globalIndex = word.firstCharacter + characterIndex;
            return (
              <RevealSpan
                key={characterIndex}
                progress={scrollYProgress}
                range={rangeOf(globalIndex, characterCount)}
                isStatic={shouldReduceMotion}
              >
                {character}
              </RevealSpan>
            );
          })}
          {word.trailingSpace}
        </span>
      );
    }

    return (
      <RevealSpan
        key={key}
        progress={scrollYProgress}
        range={rangeOf(wordIndex, wordCount)}
        isStatic={shouldReduceMotion}
      >
        {word.text}
        {word.trailingSpace}
      </RevealSpan>
    );
  }

  return (
    <MotionComponent ref={ref} className={cn('isolate', className)}>
      <span className='sr-only'>{children}</span>
      <span aria-hidden='true'>{words.map(renderWord)}</span>
    </MotionComponent>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  motion,
  useAnimationFrame,
  useInView,
  useMotionValue,
  useScroll,
  useSpring,
  useTransform,
  useVelocity,
  wrap,
  type MotionValue,
} from 'motion/react';
import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from 'react';

export type ScrollVelocityDirection = 'left' | 'right';

type DirectionSign = 1 | -1;

type ScrollVelocityContextValue = {
  boost: MotionValue<number>;
  isRunning: boolean;
  reverseOnScrollUp: boolean;
  lean: boolean;
};

const VELOCITY_SPRING = { damping: 50, stiffness: 400 };

/** At 1000px of scroll per second, the rows run this many times faster than at rest. */
const BOOST_PER_1000_PX = 4;

const LEAN_PER_BOOST = 2;

const MAX_LEAN = 6;

/** A long first frame (a tab coming back) would throw the rows forward, so a frame never counts for more than this. */
const MAX_FRAME_SECONDS = 0.1;

const MAX_COPIES = 24;

/** The copy that screen readers and keyboards reach; the others are visual repeats. */
const READABLE_COPY = 1;

const ScrollVelocityContext = createContext<ScrollVelocityContextValue | null>(
  null
);

function useScrollVelocityContext() {
  const context = useContext(ScrollVelocityContext);
  if (!context) {
    throw new Error('ScrollVelocityRow must be used inside ScrollVelocity');
  }
  return context;
}

function signOf(direction: ScrollVelocityDirection): DirectionSign {
  if (direction === 'right') {
    return 1;
  }
  return -1;
}

function oppositeOf(sign: DirectionSign): DirectionSign {
  if (sign === 1) {
    return -1;
  }
  return 1;
}

function signForBoost(
  boost: number,
  baseSign: DirectionSign,
  current: DirectionSign
) {
  if (boost < 0) {
    return oppositeOf(baseSign);
  }
  if (boost > 0) {
    return baseSign;
  }
  return current;
}

/** Enough copies to cover the row twice over the width of one copy, so neither edge ever shows a gap. */
function copyCountOf(rowWidth: number, copyWidth: number) {
  if (copyWidth <= 0) {
    return 3;
  }
  const covering = rowWidth / copyWidth;
  const rounded = Math.ceil(covering);
  const withSpares = rounded + 2;
  return Math.min(withSpares, MAX_COPIES);
}

function leanOf(boost: number, sign: DirectionSign) {
  const size = Math.abs(boost);
  const raw = size * LEAN_PER_BOOST;
  const clamped = Math.min(raw, MAX_LEAN);
  const against = -sign;
  return clamped * against;
}

/** The track starts one copy to the left, so the readable copy sits at the left edge at rest. */
function trackTransformOf(offset: number, copyWidth: number, lean: number) {
  const shifted = offset - copyWidth;
  return `translateX(${shifted}px) skewX(${lean}deg)`;
}

function isRepeatedCopy(index: number) {
  return index !== READABLE_COPY;
}

function hiddenFromReadersOf(isRepeated: boolean) {
  if (isRepeated) {
    return true;
  }
  return undefined;
}

function copyRefOf(index: number, copyRef: RefObject<HTMLDivElement | null>) {
  if (index === READABLE_COPY) {
    return copyRef;
  }
  return undefined;
}

function frameSecondsOf(delta: number) {
  const seconds = delta / 1000;
  return Math.min(seconds, MAX_FRAME_SECONDS);
}

export type ScrollVelocityProps = {
  children: ReactNode;
  containerRef?: RefObject<HTMLElement | null>;
  reverseOnScrollUp?: boolean;
  lean?: boolean;
  fade?: boolean;
  className?: string;
};

export function ScrollVelocity({
  children,
  containerRef,
  reverseOnScrollUp = true,
  lean = true,
  fade = true,
  className,
}: ScrollVelocityProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const isInView = useInView(rootRef);
  const shouldReduceMotion = usePrefersReducedMotion();
  const { scrollY } = useScroll({ container: containerRef });
  const scrollVelocity = useVelocity(scrollY);
  const smoothVelocity = useSpring(scrollVelocity, VELOCITY_SPRING);
  const boost = useTransform(
    smoothVelocity,
    [0, 1000],
    [0, BOOST_PER_1000_PX],
    { clamp: false }
  );
  const isRunning = isInView && !shouldReduceMotion;
  const value = useMemo(
    () => ({ boost, isRunning, reverseOnScrollUp, lean }),
    [boost, isRunning, reverseOnScrollUp, lean]
  );

  return (
    <div
      ref={rootRef}
      className={cn(
        'flex flex-col overflow-hidden',
        fade && 'mask-x-from-85%',
        className
      )}
    >
      <ScrollVelocityContext.Provider value={value}>
        {children}
      </ScrollVelocityContext.Provider>
    </div>
  );
}

type RowDriverProps = {
  offset: MotionValue<number>;
  copyWidth: MotionValue<number>;
  tilt: MotionValue<number>;
  boost: MotionValue<number>;
  speed: number;
  baseSign: DirectionSign;
  signRef: RefObject<DirectionSign>;
  reverseOnScrollUp: boolean;
  lean: boolean;
};

/**
 * The frame loop of the animation library runs for as long as one `useAnimationFrame` is mounted,
 * even when its callback does nothing, and each of those frames costs the whole page. So the loop
 * lives in this leaf, which is mounted only while the row runs.
 */
function RowDriver({
  offset,
  copyWidth,
  tilt,
  boost,
  speed,
  baseSign,
  signRef,
  reverseOnScrollUp,
  lean,
}: RowDriverProps) {
  useAnimationFrame((_, delta) => {
    const currentBoost = boost.get();
    if (reverseOnScrollUp) {
      signRef.current = signForBoost(currentBoost, baseSign, signRef.current);
    }
    if (!reverseOnScrollUp) {
      signRef.current = baseSign;
    }
    const seconds = frameSecondsOf(delta);
    const boostSize = Math.abs(currentBoost);
    const multiplier = 1 + boostSize;
    const distanceAtRest = speed * seconds;
    const distance = distanceAtRest * multiplier;
    const step = signRef.current * distance;
    const width = copyWidth.get();
    if (width <= 0) {
      return;
    }
    const currentOffset = offset.get();
    const travelled = currentOffset + step;
    const wrapped = wrap(-width, 0, travelled);
    offset.set(wrapped);
    if (lean) {
      const nextTilt = leanOf(currentBoost, signRef.current);
      tilt.set(nextTilt);
    }
  });

  return null;
}

export type ScrollVelocityRowProps = {
  children: ReactNode;
  speed?: number;
  direction?: ScrollVelocityDirection;
  gap?: number;
  className?: string;
};

export function ScrollVelocityRow({
  children,
  speed = 40,
  direction = 'left',
  gap = 32,
  className,
}: ScrollVelocityRowProps) {
  const { boost, isRunning, reverseOnScrollUp, lean } =
    useScrollVelocityContext();
  const rowRef = useRef<HTMLDivElement>(null);
  const copyRef = useRef<HTMLDivElement>(null);
  const [copyCount, setCopyCount] = useState(3);
  const baseSign = signOf(direction);
  const signRef = useRef<DirectionSign>(baseSign);
  const offset = useMotionValue(0);
  const copyWidth = useMotionValue(0);
  const tilt = useMotionValue(0);
  const transform = useTransform<number, string>(
    [offset, copyWidth, tilt],
    ([latestOffset, latestCopyWidth, latestTilt]) =>
      trackTransformOf(latestOffset, latestCopyWidth, latestTilt)
  );
  const copies = Array.from({ length: copyCount }, (_, index) => index);

  useEffect(() => {
    const row = rowRef.current;
    const copy = copyRef.current;
    if (!row) {
      return;
    }
    if (!copy) {
      return;
    }
    const measure = () => {
      const rowWidth = row.getBoundingClientRect().width;
      const measuredCopyWidth = copy.getBoundingClientRect().width;
      const nextCopyCount = copyCountOf(rowWidth, measuredCopyWidth);
      copyWidth.set(measuredCopyWidth);
      setCopyCount(nextCopyCount);
    };
    const observer = new ResizeObserver(measure);
    observer.observe(row);
    observer.observe(copy);
    return () => observer.disconnect();
  }, [copyWidth]);

  return (
    <div ref={rowRef} className={cn('flex overflow-hidden', className)}>
      {isRunning && (
        <RowDriver
          offset={offset}
          copyWidth={copyWidth}
          tilt={tilt}
          boost={boost}
          speed={speed}
          baseSign={baseSign}
          signRef={signRef}
          reverseOnScrollUp={reverseOnScrollUp}
          lean={lean}
        />
      )}
      <motion.div
        className='flex w-max shrink-0 whitespace-nowrap'
        style={{ transform }}
      >
        {copies.map((index) => {
          const isRepeated = isRepeatedCopy(index);

          return (
            <div
              key={index}
              ref={copyRefOf(index, copyRef)}
              aria-hidden={hiddenFromReadersOf(isRepeated)}
              inert={isRepeated}
              className='flex shrink-0 items-center'
              style={{ paddingInlineEnd: gap }}
            >
              {children}
            </div>
          );
        })}
      </motion.div>
    </div>
  );
}

'use client';

import { useEffect, useRef } from 'react';

import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type ShineTrigger = 'loop' | 'hover';

const SWEEP_EASE = 'cubic-bezier(0.77, 0, 0.175, 1)';

const BEFORE_FRAME = 'translateX(-100%)';

const AFTER_FRAME = 'translateX(250%)';

function frameShapeOf(width: number): React.CSSProperties {
  return {
    inset: 'calc(var(--hairline, 1px) * -1)',
    padding: width,
    mask: 'linear-gradient(black, black) content-box exclude, linear-gradient(black, black)',
    WebkitMask:
      'linear-gradient(black, black) content-box xor, linear-gradient(black, black)',
  };
}

function loopSweep(band: HTMLElement, sweepMs: number, restMs: number) {
  const cycleMs = sweepMs + restMs;
  const sweepShare = sweepMs / cycleMs;
  return band.animate(
    [
      { transform: BEFORE_FRAME, offset: 0, easing: SWEEP_EASE },
      { transform: AFTER_FRAME, offset: sweepShare },
      { transform: AFTER_FRAME, offset: 1 },
    ],
    { duration: cycleMs, iterations: Infinity }
  );
}

function singleSweep(band: HTMLElement, sweepMs: number) {
  return band.animate(
    [{ transform: BEFORE_FRAME }, { transform: AFTER_FRAME }],
    {
      duration: sweepMs,
      easing: SWEEP_EASE,
    }
  );
}

function isRunning(animation: Animation | null) {
  if (!animation) {
    return false;
  }
  return animation.playState === 'running';
}

function isKeyboardFocus(event: FocusEvent) {
  const target = event.target;
  if (!(target instanceof Element)) {
    return false;
  }
  return target.matches(':focus-visible');
}

export type ShineBorderProps = {
  trigger?: ShineTrigger;
  duration?: number;
  interval?: number;
  width?: number;
  className?: string;
};

export function ShineBorder({
  trigger = 'loop',
  duration = 1.4,
  interval = 4,
  width = 1,
  className,
}: ShineBorderProps) {
  const frameRef = useRef<HTMLSpanElement>(null);
  const bandRef = useRef<HTMLSpanElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const sweepMs = duration * 1000;
  const restMs = interval * 1000;

  useEffect(() => {
    const band = bandRef.current;
    const isLooping = trigger === 'loop';
    if (!band || !isLooping) {
      return;
    }
    if (prefersReducedMotion) {
      return;
    }
    const animation = loopSweep(band, sweepMs, restMs);
    return () => animation.cancel();
  }, [trigger, sweepMs, restMs, prefersReducedMotion]);

  useEffect(() => {
    const band = bandRef.current;
    const owner = frameRef.current?.parentElement;
    const isHover = trigger === 'hover';
    if (!band || !owner || !isHover) {
      return;
    }
    if (prefersReducedMotion) {
      return;
    }
    let current: Animation | null = null;
    const sweep = () => {
      if (isRunning(current)) {
        return;
      }
      current = singleSweep(band, sweepMs);
    };
    const sweepForMouse = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') {
        return;
      }
      sweep();
    };
    const sweepForKeyboard = (event: FocusEvent) => {
      if (!isKeyboardFocus(event)) {
        return;
      }
      sweep();
    };
    owner.addEventListener('pointerenter', sweepForMouse);
    owner.addEventListener('focusin', sweepForKeyboard);
    return () => {
      owner.removeEventListener('pointerenter', sweepForMouse);
      owner.removeEventListener('focusin', sweepForKeyboard);
      current?.cancel();
    };
  }, [trigger, sweepMs, prefersReducedMotion]);

  return (
    <span
      ref={frameRef}
      aria-hidden='true'
      style={frameShapeOf(width)}
      className={cn(
        'text-primary pointer-events-none absolute overflow-hidden rounded-[inherit]',
        className
      )}
    >
      <span
        ref={bandRef}
        style={{ transform: BEFORE_FRAME }}
        className='absolute inset-y-0 left-0 w-2/5 bg-[linear-gradient(110deg,transparent_25%,currentColor_50%,transparent_75%)]'
      />
    </span>
  );
}

'use client';
import { useEffect, useId } from 'react';
import {
  MotionValue,
  motion,
  useSpring,
  useTransform,
  motionValue,
  MotionConfig,
} from 'motion/react';
import useMeasure from 'react-use-measure';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const TRANSITION = {
  type: 'spring' as const,
  stiffness: 280,
  damping: 18,
  mass: 0.3,
};

function ReducedMotionConfig({ children }: { children: React.ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

function Digit({ value, place }: { value: number; place: number }) {
  const valueRoundedToPlace = Math.floor(value / place) % 10;
  const initial = motionValue(valueRoundedToPlace);
  const animatedValue = useSpring(initial, TRANSITION);
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    if (prefersReducedMotion) {
      animatedValue.jump(valueRoundedToPlace);
      return;
    }
    animatedValue.set(valueRoundedToPlace);
  }, [animatedValue, valueRoundedToPlace, prefersReducedMotion]);

  return (
    <div className='relative inline-block w-[1ch] overflow-x-visible overflow-y-clip leading-none tabular-nums'>
      <div className='invisible'>0</div>
      {Array.from({ length: 10 }, (_, i) => (
        <Number key={i} mv={animatedValue} number={i} />
      ))}
    </div>
  );
}

function Number({ mv, number }: { mv: MotionValue<number>; number: number }) {
  const uniqueId = useId();
  const [ref, bounds] = useMeasure();

  const y = useTransform(mv, (latest) => {
    if (!bounds.height) return 0;
    const placeValue = latest % 10;
    const offset = (10 + number - placeValue) % 10;
    let memo = offset * bounds.height;

    if (offset > 5) {
      memo -= 10 * bounds.height;
    }

    return memo;
  });

  // don't render the animated number until we know the height
  if (!bounds.height) {
    return (
      <span ref={ref} className='invisible absolute'>
        {number}
      </span>
    );
  }

  return (
    <motion.span
      style={{ y }}
      layoutId={`${uniqueId}-${number}`}
      className='absolute inset-0 flex items-center justify-center'
      transition={TRANSITION}
      ref={ref}
    >
      {number}
    </motion.span>
  );
}

type SlidingNumberProps = {
  value: number;
  padStart?: boolean;
  decimalSeparator?: string;
};

export function SlidingNumber({
  value,
  padStart = false,
  decimalSeparator = '.',
}: SlidingNumberProps) {
  const absValue = Math.abs(value);
  const [integerPart, decimalPart] = absValue.toString().split('.');
  const integerValue = parseInt(integerPart, 10);
  const paddedInteger =
    padStart && integerValue < 10 ? `0${integerPart}` : integerPart;
  const integerDigits = paddedInteger.split('');
  const integerPlaces = integerDigits.map((_, i) =>
    Math.pow(10, integerDigits.length - i - 1)
  );

  return (
    <ReducedMotionConfig>
      <div className='flex items-center'>
        {value < 0 && '-'}
        {integerDigits.map((_, index) => (
          <Digit
            key={`pos-${integerPlaces[index]}`}
            value={integerValue}
            place={integerPlaces[index]}
          />
        ))}
        {decimalPart && (
          <>
            <span>{decimalSeparator}</span>
            {decimalPart.split('').map((_, index) => (
              <Digit
                key={`decimal-${index}`}
                value={parseInt(decimalPart, 10)}
                place={Math.pow(10, decimalPart.length - index - 1)}
              />
            ))}
          </>
        )}
      </div>
    </ReducedMotionConfig>
  );
}

'use client';
import { type ReactNode, type RefObject, useEffect, useRef } from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const DEFAULT_LERP = 0.12;
const MIN_LERP = 0.01;
const LINE_HEIGHT = 100 / 3;
const REFERENCE_FRAME_MS = 1000 / 60;
const SETTLED_DISTANCE = 0.5;
const OWN_WRITE_TOLERANCE = 1.5;
const IGNORE_ATTRIBUTE = 'data-smooth-scroll-ignore';

type Scroller = {
  eventTarget: HTMLElement | Window;
  boundary: HTMLElement;
  read: () => number;
  max: () => number;
  pageHeight: () => number;
  isLocked: () => boolean;
  write: (top: number) => void;
};

function hidesOverflow(element: Element) {
  const overflowY = getComputedStyle(element).overflowY;
  const isHidden = overflowY === 'hidden';
  const isClipped = overflowY === 'clip';
  return isHidden || isClipped;
}

function windowScroller(): Scroller {
  const root = document.documentElement;

  return {
    eventTarget: window,
    boundary: root,
    read: () => window.scrollY,
    max: () => root.scrollHeight - root.clientHeight,
    pageHeight: () => root.clientHeight,
    isLocked: () => {
      const isRootLocked = hidesOverflow(root);
      const isBodyLocked = hidesOverflow(document.body);
      return isRootLocked || isBodyLocked;
    },
    write: (top) => window.scrollTo({ top, behavior: 'instant' }),
  };
}

function elementScroller(element: HTMLElement): Scroller {
  return {
    eventTarget: element,
    boundary: element,
    read: () => element.scrollTop,
    max: () => element.scrollHeight - element.clientHeight,
    pageHeight: () => element.clientHeight,
    isLocked: () => hidesOverflow(element),
    write: (top) => element.scrollTo({ top, behavior: 'instant' }),
  };
}

function scrollerOf(container?: RefObject<HTMLElement | null>) {
  if (!container) {
    return windowScroller();
  }
  const element = container.current;
  if (!element) {
    return null;
  }
  return elementScroller(element);
}

function clamp(value: number, min: number, max: number) {
  const atLeastMin = Math.max(min, value);
  return Math.min(max, atLeastMin);
}

function pixelDeltaOf(event: WheelEvent, scroller: Scroller) {
  if (event.deltaMode === WheelEvent.DOM_DELTA_LINE) {
    return event.deltaY * LINE_HEIGHT;
  }
  if (event.deltaMode === WheelEvent.DOM_DELTA_PAGE) {
    return event.deltaY * scroller.pageHeight();
  }
  return event.deltaY;
}

function ownsWheel(element: Element, delta: number) {
  if (element.hasAttribute(IGNORE_ATTRIBUTE)) {
    return true;
  }
  const style = getComputedStyle(element);
  const isAuto = style.overflowY === 'auto';
  const isScroll = style.overflowY === 'scroll';
  const room = element.scrollHeight - element.clientHeight;
  const isScrollable = isAuto || isScroll;
  if (!isScrollable || room <= 0) {
    return false;
  }
  if (delta < 0) {
    return element.scrollTop > 0;
  }
  const lastPosition = room - 1;
  return element.scrollTop < lastPosition;
}

function isInsideOwnScroller(
  start: EventTarget | null,
  boundary: HTMLElement,
  delta: number
) {
  let node: Element | null = null;
  if (start instanceof Element) {
    node = start;
  }
  while (node && node !== boundary) {
    if (ownsWheel(node, delta)) {
      return true;
    }
    node = node.parentElement;
  }
  return false;
}

function isGestureForBrowser(event: WheelEvent) {
  const sidewaysAmount = Math.abs(event.deltaX);
  const downwardAmount = Math.abs(event.deltaY);
  const isHorizontal = sidewaysAmount > downwardAmount;
  const isPinchZoom = event.ctrlKey;
  const isSideways = event.shiftKey;
  const isEmpty = event.deltaY === 0;
  const isHandled = event.defaultPrevented;
  return isHorizontal || isPinchZoom || isSideways || isEmpty || isHandled;
}

function attachSmoothScroll(scroller: Scroller, lerp: number) {
  const easing = clamp(lerp, MIN_LERP, 1);
  const keptPerFrame = 1 - easing;
  let current = scroller.read();
  let target = current;
  let lastWritten = current;
  let lastTime = 0;
  let frameId = 0;

  const stop = () => {
    cancelAnimationFrame(frameId);
    frameId = 0;
  };

  const step = (time: number) => {
    let elapsed = REFERENCE_FRAME_MS;
    if (lastTime > 0) {
      elapsed = time - lastTime;
    }
    lastTime = time;

    const frames = elapsed / REFERENCE_FRAME_MS;
    const kept = Math.pow(keptPerFrame, frames);
    const factor = 1 - kept;
    const max = scroller.max();
    target = clamp(target, 0, max);
    const gap = target - current;
    current += gap * factor;

    const remainingGap = target - current;
    const remaining = Math.abs(remainingGap);
    const isSettled = remaining < SETTLED_DISTANCE;
    if (isSettled) {
      current = target;
    }
    lastWritten = current;
    scroller.write(current);

    if (isSettled) {
      frameId = 0;
      return;
    }
    frameId = requestAnimationFrame(step);
  };

  const onWheel = (event: WheelEvent) => {
    if (isGestureForBrowser(event)) {
      return;
    }
    if (scroller.isLocked()) {
      return;
    }
    const delta = pixelDeltaOf(event, scroller);
    if (isInsideOwnScroller(event.target, scroller.boundary, delta)) {
      return;
    }

    const isAnimating = frameId !== 0;
    if (!isAnimating) {
      current = scroller.read();
      target = current;
    }

    // At an edge with nothing left to finish, the wheel goes back to the browser: it chains to
    // the page around a scrolling area, and keeps the overscroll bounce of the page.
    const max = scroller.max();
    const pushesPastTop = delta < 0 && target <= 0;
    const pushesPastBottom = delta > 0 && target >= max;
    const pushesPastEdge = pushesPastTop || pushesPastBottom;
    if (pushesPastEdge && !isAnimating) {
      return;
    }

    event.preventDefault();
    const nextTarget = target + delta;
    target = clamp(nextTarget, 0, max);
    if (!isAnimating) {
      lastTime = 0;
      frameId = requestAnimationFrame(step);
    }
  };

  // Keyboard, scrollbar, anchors, focus and find in page scroll natively: when the position
  // moves without us, the smoothing stops and starts again from there.
  const onScroll = () => {
    const position = scroller.read();
    const offset = position - lastWritten;
    const drift = Math.abs(offset);
    if (drift <= OWN_WRITE_TOLERANCE) {
      return;
    }
    stop();
    current = position;
    target = position;
    lastWritten = position;
  };

  const onWheelEvent = (event: Event) => {
    if (event instanceof WheelEvent) {
      onWheel(event);
    }
  };

  // The wheel listener cannot be passive: taking over the wheel means cancelling its default.
  scroller.eventTarget.addEventListener('wheel', onWheelEvent, {
    passive: false,
  });
  scroller.eventTarget.addEventListener('scroll', onScroll, { passive: true });

  return () => {
    stop();
    scroller.eventTarget.removeEventListener('wheel', onWheelEvent);
    scroller.eventTarget.removeEventListener('scroll', onScroll);
  };
}

export type UseSmoothScrollOptions = {
  container?: RefObject<HTMLElement | null>;
  lerp?: number;
  enabled?: boolean;
};

export function useSmoothScroll({
  container,
  lerp = DEFAULT_LERP,
  enabled = true,
}: UseSmoothScrollOptions = {}) {
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    if (!enabled) {
      return;
    }
    if (prefersReducedMotion) {
      return;
    }
    const scroller = scrollerOf(container);
    if (!scroller) {
      return;
    }
    return attachSmoothScroll(scroller, lerp);
  }, [container, lerp, enabled, prefersReducedMotion]);
}

function areaClassOf(root: boolean) {
  if (root) {
    return '';
  }
  return 'relative overflow-y-auto';
}

export type SmoothScrollProps = {
  children: ReactNode;
  root?: boolean;
  lerp?: number;
  enabled?: boolean;
  className?: string;
};

export function SmoothScroll({
  children,
  root = false,
  lerp,
  enabled = true,
  className,
}: SmoothScrollProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const smoothsWindow = root && enabled;
  const smoothsArea = !root && enabled;
  useSmoothScroll({ lerp, enabled: smoothsWindow });
  useSmoothScroll({ container: containerRef, lerp, enabled: smoothsArea });

  return (
    <div ref={containerRef} className={cn(areaClassOf(root), className)}>
      {children}
    </div>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { motion, MotionConfig, Transition, Variants } from 'motion/react';
import React, { CSSProperties } from 'react';

export type SpinningTextProps = {
  children: string | readonly string[];
  style?: CSSProperties;
  duration?: number;
  className?: string;
  reverse?: boolean;
  fontSize?: number;
  radius?: number;
  transition?: Transition;
  variants?: {
    container?: Variants;
    item?: Variants;
  };
};

const BASE_TRANSITION: Transition = {
  repeat: Infinity,
  ease: 'linear',
};

const BASE_ITEM_VARIANTS = {
  hidden: {
    opacity: 1,
  },
  visible: {
    opacity: 1,
  },
};

/** Text with an expression in JSX (`{count} left`) arrives as several strings. */
function textOf(children: string | readonly string[]) {
  if (typeof children === 'string') {
    return children;
  }
  return children.join('');
}

function ReducedMotionConfig({ children }: { children: React.ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

export function SpinningText({
  children,
  duration = 10,
  style,
  className,
  reverse = false,
  fontSize = 1,
  radius = 5,
  transition,
  variants,
}: SpinningTextProps) {
  const text = textOf(children);
  const letters = Array.from(text);
  const totalLetters = letters.length;

  const finalTransition = {
    ...BASE_TRANSITION,
    ...transition,
    duration: (transition as { duration?: number })?.duration ?? duration,
  };

  const containerVariants = {
    visible: { rotate: reverse ? -360 : 360 },
    ...variants?.container,
  };

  const itemVariants = {
    ...BASE_ITEM_VARIANTS,
    ...variants?.item,
  };

  return (
    <ReducedMotionConfig>
      <motion.div
        className={cn('relative', className)}
        style={{
          ...style,
        }}
        initial='hidden'
        animate='visible'
        variants={containerVariants}
        transition={finalTransition}
      >
        {letters.map((letter, index) => (
          <motion.span
            aria-hidden='true'
            key={`${index}-${letter}`}
            variants={itemVariants}
            className='absolute top-1/2 left-1/2 inline-block'
            style={
              {
                '--index': index,
                '--total': totalLetters,
                '--font-size': fontSize,
                '--radius': radius,
                fontSize: `calc(var(--font-size, 2) * 1rem)`,
                transform: `
                  translate(-50%, -50%)
                  rotate(calc(360deg / var(--total) * var(--index)))
                  translateY(calc(var(--radius, 5) * -1ch))
                `,
                transformOrigin: 'center',
              } as React.CSSProperties
            }
          >
            {letter}
          </motion.span>
        ))}
        <span className='sr-only'>{text}</span>
      </motion.div>
    </ReducedMotionConfig>
  );
}

'use client';

import {
  motion,
  type MotionValue,
  useMotionTemplate,
  useMotionValue,
  useSpring,
  useTransform,
} from 'motion/react';
import { createContext, useContext, useRef, useState } from 'react';

import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type SpotlightTint = 'neutral' | 'primary';

type SpotlightContextValue = {
  pointerX: MotionValue<number>;
  pointerY: MotionValue<number>;
  tint: SpotlightTint;
};

const SpotlightContext = createContext<SpotlightContextValue | null>(null);

function useSpotlight() {
  const context = useContext(SpotlightContext);
  if (!context) {
    throw new Error('SpotlightCard must be used inside SpotlightCards');
  }
  return context;
}

const FOLLOW_SPRING = { stiffness: 600, damping: 50 };

const EDGE_RADIUS = 220;

const FILL_RADIUS = 320;

const TINT_COLORS = {
  neutral: {
    edge: 'color-mix(in oklab, var(--foreground) 32%, transparent)',
    fill: 'color-mix(in oklab, var(--foreground) 3%, transparent)',
  },
  primary: {
    edge: 'color-mix(in oklab, var(--primary) 60%, transparent)',
    fill: 'color-mix(in oklab, var(--primary) 5%, transparent)',
  },
} satisfies Record<SpotlightTint, { edge: string; fill: string }>;

function isMouse(event: React.PointerEvent) {
  return event.pointerType === 'mouse';
}

type PointerValues = {
  x: MotionValue<number>;
  y: MotionValue<number>;
};

function followedPointerOf(
  prefersReducedMotion: boolean | null,
  raw: PointerValues,
  smooth: PointerValues
) {
  if (prefersReducedMotion) {
    return raw;
  }
  return smooth;
}

export type SpotlightCardsProps = React.ComponentProps<'div'> & {
  tint?: SpotlightTint;
};

export function SpotlightCards({
  tint = 'primary',
  className,
  children,
  onPointerMove,
  onPointerLeave,
  ...props
}: SpotlightCardsProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const [isLit, setIsLit] = useState(false);
  const rawX = useMotionValue(0);
  const rawY = useMotionValue(0);
  const smoothX = useSpring(rawX, FOLLOW_SPRING);
  const smoothY = useSpring(rawY, FOLLOW_SPRING);
  const followed = followedPointerOf(
    prefersReducedMotion,
    { x: rawX, y: rawY },
    { x: smoothX, y: smoothY }
  );

  function follow(event: React.PointerEvent<HTMLDivElement>) {
    onPointerMove?.(event);
    if (!isMouse(event)) {
      return;
    }
    rawX.set(event.clientX);
    rawY.set(event.clientY);
    if (isLit) {
      return;
    }
    smoothX.jump(event.clientX);
    smoothY.jump(event.clientY);
    setIsLit(true);
  }

  function dim(event: React.PointerEvent<HTMLDivElement>) {
    onPointerLeave?.(event);
    setIsLit(false);
  }

  return (
    <SpotlightContext.Provider
      value={{ pointerX: followed.x, pointerY: followed.y, tint }}
    >
      <div
        data-lit={isLit}
        className={cn('group/spotlight grid gap-3', className)}
        onPointerMove={follow}
        onPointerLeave={dim}
        {...props}
      >
        {children}
      </div>
    </SpotlightContext.Provider>
  );
}

function leftOf(element: HTMLElement | null) {
  if (!element) {
    return 0;
  }
  return element.getBoundingClientRect().left;
}

function topOf(element: HTMLElement | null) {
  if (!element) {
    return 0;
  }
  return element.getBoundingClientRect().top;
}

const LIGHT_LAYER = [
  'pointer-events-none absolute rounded-[inherit] opacity-0',
  'transition-opacity duration-150 ease-(--ease-out-strong)',
  'group-data-[lit=true]/spotlight:opacity-100 group-data-[lit=true]/spotlight:duration-300',
].join(' ');

const EDGE_SHAPE = {
  inset: 'calc(var(--hairline) * -1)',
  padding: 'var(--hairline)',
  mask: 'linear-gradient(black, black) content-box exclude, linear-gradient(black, black)',
  WebkitMask:
    'linear-gradient(black, black) content-box xor, linear-gradient(black, black)',
};

const CARD = [
  'group/card relative isolate block rounded-xl bg-card text-card-foreground',
  'hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
  'cursor-pointer outline-none transition-[scale] duration-150 ease-(--ease-out-strong) active:scale-[0.97]',
  'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring',
].join(' ');

export type SpotlightCardProps = React.ComponentProps<'a'>;

export function SpotlightCard({
  className,
  children,
  ...props
}: SpotlightCardProps) {
  const { pointerX, pointerY, tint } = useSpotlight();
  const cardRef = useRef<HTMLAnchorElement>(null);
  const localX = useTransform(() => {
    const pointer = pointerX.get();
    const left = leftOf(cardRef.current);
    return pointer - left;
  });
  const localY = useTransform(() => {
    const pointer = pointerY.get();
    const top = topOf(cardRef.current);
    return pointer - top;
  });
  const colors = TINT_COLORS[tint];
  const edgeLight = useMotionTemplate`radial-gradient(${EDGE_RADIUS}px circle at ${localX}px ${localY}px, ${colors.edge}, transparent)`;
  const fillLight = useMotionTemplate`radial-gradient(${FILL_RADIUS}px circle at ${localX}px ${localY}px, ${colors.fill}, transparent)`;

  return (
    <a ref={cardRef} className={cn(CARD, className)} {...props}>
      <motion.span
        aria-hidden='true'
        className={cn(LIGHT_LAYER, 'inset-0')}
        style={{ background: fillLight }}
      />
      <motion.span
        aria-hidden='true'
        className={LIGHT_LAYER}
        style={{ background: edgeLight, ...EDGE_SHAPE }}
      />
      <div className='relative flex h-full flex-col'>{children}</div>
    </a>
  );
}

'use client';
import React, { useRef, useState, useCallback, useEffect } from 'react';
import { motion, useSpring, useTransform, SpringOptions } from 'motion/react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type SpotlightProps = {
  className?: string;
  size?: number;
  springOptions?: SpringOptions;
};

function visibilityOf(isHovered: boolean) {
  if (isHovered) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

export function Spotlight({
  className,
  size = 200,
  springOptions = { bounce: 0 },
}: SpotlightProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isHovered, setIsHovered] = useState(false);
  const [parentElement, setParentElement] = useState<HTMLElement | null>(null);
  const prefersReducedMotion = usePrefersReducedMotion();

  const mouseX = useSpring(0, springOptions);
  const mouseY = useSpring(0, springOptions);

  const spotlightLeft = useTransform(mouseX, (x) => `${x - size / 2}px`);
  const spotlightTop = useTransform(mouseY, (y) => `${y - size / 2}px`);

  useEffect(() => {
    if (containerRef.current) {
      const parent = containerRef.current.parentElement;
      if (parent) {
        parent.style.position = 'relative';
        parent.style.overflow = 'hidden';
        setParentElement(parent);
      }
    }
  }, []);

  const handleMouseMove = useCallback(
    (event: MouseEvent) => {
      if (!parentElement) return;
      const { left, top } = parentElement.getBoundingClientRect();
      const pointerX = event.clientX - left;
      const pointerY = event.clientY - top;
      if (prefersReducedMotion) {
        mouseX.jump(pointerX);
        mouseY.jump(pointerY);
        return;
      }
      mouseX.set(pointerX);
      mouseY.set(pointerY);
    },
    [mouseX, mouseY, parentElement, prefersReducedMotion]
  );

  useEffect(() => {
    if (!parentElement) return;

    const abortController = new AbortController();

    parentElement.addEventListener('mousemove', handleMouseMove, {
      signal: abortController.signal,
    });
    parentElement.addEventListener('mouseenter', () => setIsHovered(true), {
      signal: abortController.signal,
    });
    parentElement.addEventListener('mouseleave', () => setIsHovered(false), {
      signal: abortController.signal,
    });

    return () => {
      abortController.abort();
    };
  }, [parentElement, handleMouseMove]);

  return (
    <motion.div
      ref={containerRef}
      className={cn(
        'pointer-events-none absolute rounded-full bg-[radial-gradient(circle_at_center,var(--tw-gradient-stops),transparent_80%)] blur-xl transition-opacity duration-200',
        'from-foreground/20 via-foreground/10 to-foreground/5',
        visibilityOf(isHovered),
        className
      )}
      style={{
        width: size,
        height: size,
        left: spotlightLeft,
        top: spotlightTop,
      }}
    />
  );
}

'use client';
import {
  motion,
  type MotionValue,
  useScroll,
  useTransform,
} from 'motion/react';
import {
  Children,
  createContext,
  type CSSProperties,
  type ReactNode,
  type RefObject,
  useContext,
  useRef,
} from 'react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const DEEPEST_SCALE = 0.9;
const MAX_SCALE_STEP = 0.04;
const DIM_STEP = 0.12;
const MAX_DIM = 0.48;

type StackingCardsContextValue = {
  progress: MotionValue<number>;
  count: number;
  peek: number;
  frameClassName?: string;
};

const StackingCardsContext = createContext<StackingCardsContextValue | null>(
  null
);
const StackingCardIndexContext = createContext(0);

function useStackingCards() {
  const context = useContext(StackingCardsContext);
  if (!context) {
    throw new Error('StackingCard must be used inside StackingCards');
  }
  return context;
}

function scaleStepOf(count: number) {
  if (count < 2) {
    return 0;
  }
  const scaleRange = 1 - DEEPEST_SCALE;
  const gaps = count - 1;
  const evenStep = scaleRange / gaps;
  return Math.min(MAX_SCALE_STEP, evenStep);
}

function rangeStartOf(index: number, lastIndex: number) {
  if (lastIndex === 0) {
    return 0;
  }
  return index / lastIndex;
}

function scaleOf(
  prefersReducedMotion: boolean | null,
  scale: MotionValue<number>
) {
  if (prefersReducedMotion) {
    return 1;
  }
  return scale;
}

function dimOf(prefersReducedMotion: boolean | null, dim: MotionValue<number>) {
  if (prefersReducedMotion) {
    return 0;
  }
  return dim;
}

export type StackingCardsProps = {
  children: ReactNode;
  className?: string;
  frameClassName?: string;
  containerRef?: RefObject<HTMLElement | null>;
  peek?: number;
};

export function StackingCards({
  children,
  className,
  frameClassName,
  containerRef,
  peek = 16,
}: StackingCardsProps) {
  const stackRef = useRef<HTMLDivElement>(null);
  const cards = Children.toArray(children);
  const count = cards.length;

  const { scrollYProgress } = useScroll({
    target: stackRef,
    container: containerRef,
    offset: ['start start', 'end end'],
  });

  const value = { progress: scrollYProgress, count, peek, frameClassName };

  return (
    <StackingCardsContext value={value}>
      <div ref={stackRef} className={cn('relative', className)}>
        {cards.map((card, index) => (
          <StackingCardIndexContext key={index} value={index}>
            {card}
          </StackingCardIndexContext>
        ))}
      </div>
    </StackingCardsContext>
  );
}

export type StackingCardProps = {
  children: ReactNode;
  className?: string;
};

export function StackingCard({ children, className }: StackingCardProps) {
  const { progress, count, peek, frameClassName } = useStackingCards();
  const index = useContext(StackingCardIndexContext);
  const prefersReducedMotion = usePrefersReducedMotion();

  const lastIndex = count - 1;
  const depth = lastIndex - index;
  const scaleStep = scaleStepOf(count);
  const targetScale = 1 - depth * scaleStep;
  const depthDim = depth * DIM_STEP;
  const targetDim = Math.min(MAX_DIM, depthDim);
  const rangeStart = rangeStartOf(index, lastIndex);
  const stackOffset = index * peek;

  const scale = useTransform(progress, [rangeStart, 1], [1, targetScale]);
  const dim = useTransform(progress, [rangeStart, 1], [0, targetDim]);
  const cardScale = scaleOf(prefersReducedMotion, scale);
  const cardDim = dimOf(prefersReducedMotion, dim);
  const offsetStyle = {
    '--stack-offset': `${stackOffset}px`,
  } as CSSProperties;

  return (
    <div
      style={offsetStyle}
      className={cn(
        'sticky top-0 flex h-svh items-center justify-center',
        'motion-reduce:static motion-reduce:h-auto motion-reduce:py-2',
        frameClassName
      )}
    >
      <motion.div
        style={{ scale: cardScale }}
        className={cn(
          'relative top-(--stack-offset) w-full origin-top overflow-clip motion-reduce:top-0',
          className
        )}
      >
        {children}
        <motion.div
          aria-hidden='true'
          style={{ opacity: cardDim }}
          className='bg-background pointer-events-none absolute inset-0'
        />
      </motion.div>
    </div>
  );
}

'use client';
import {
  type ComponentProps,
  type ReactNode,
  type RefObject,
  useEffect,
  useRef,
  useState,
} from 'react';
import { cn } from '@/lib/utils';

// A one percent band across the middle of the scrolling area: the step that crosses it is active.
const MIDDLE_BAND = '-50% 0px -49% 0px';

export type StickyScrollStep = {
  id: string;
  title: ReactNode;
  description: ReactNode;
  media: ReactNode;
};

export type StickyScrollProps = {
  steps: StickyScrollStep[];
  containerRef?: RefObject<HTMLElement | null>;
  mediaSide?: 'start' | 'end';
  className?: string;
  frameClassName?: string;
  stepClassName?: string;
};

function stateOf(isActive: boolean) {
  if (isActive) {
    return 'active';
  }
  return 'inactive';
}

function panelOrderOf(mediaSide: 'start' | 'end') {
  if (mediaSide === 'start') {
    return '@xl:order-first';
  }
  return '';
}

function useActiveStep(
  listRef: RefObject<HTMLOListElement | null>,
  containerRef: RefObject<HTMLElement | null> | undefined,
  stepCount: number
) {
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    const list = listRef.current;
    if (!list) {
      return;
    }

    const root = containerRef?.current ?? null;
    const activateCrossingStep = (entries: IntersectionObserverEntry[]) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) {
          continue;
        }
        const indexAttribute = entry.target.getAttribute('data-step-index');
        const index = Number(indexAttribute);
        setActiveIndex(index);
      }
    };
    const observer = new IntersectionObserver(activateCrossingStep, {
      root,
      rootMargin: MIDDLE_BAND,
    });

    for (const step of Array.from(list.children)) {
      observer.observe(step);
    }
    return () => observer.disconnect();
  }, [listRef, containerRef, stepCount]);

  return activeIndex;
}

export function StickyScroll({
  steps,
  containerRef,
  mediaSide = 'end',
  className,
  frameClassName,
  stepClassName,
}: StickyScrollProps) {
  const listRef = useRef<HTMLOListElement>(null);
  const activeIndex = useActiveStep(listRef, containerRef, steps.length);
  const panelOrder = panelOrderOf(mediaSide);

  return (
    <div className={cn('@container', className)}>
      <div className='grid gap-x-12 @xl:grid-cols-2'>
        <ol ref={listRef} className='flex flex-col'>
          {steps.map((step, index) => {
            const isActive = index === activeIndex;

            return (
              <li
                key={step.id}
                data-step-index={index}
                data-state={stateOf(isActive)}
                className={cn(
                  'group/step flex min-h-[70svh] flex-col justify-center gap-4 py-10',
                  stepClassName
                )}
              >
                <div className='@xl:hidden'>{step.media}</div>
                <div className='flex flex-col gap-2'>
                  <h3 className='text-muted-foreground group-data-[state=active]/step:text-foreground text-lg font-semibold text-balance transition-colors duration-200'>
                    {step.title}
                  </h3>
                  <div className='text-muted-foreground text-sm'>
                    {step.description}
                  </div>
                </div>
              </li>
            );
          })}
        </ol>
        <div
          aria-hidden='true'
          className={cn(
            'sticky top-0 hidden h-svh items-center self-start @xl:flex',
            panelOrder,
            frameClassName
          )}
        >
          <div className='grid w-full'>
            {steps.map((step, index) => {
              const isActive = index === activeIndex;

              // The outgoing media stays opaque under the incoming one until its fade ends,
              // so the panel never shows the page through a half-faded pair.
              return (
                <div
                  key={step.id}
                  data-state={stateOf(isActive)}
                  className='col-start-1 row-start-1 opacity-0 transition-opacity delay-200 duration-0 data-[state=active]:z-10 data-[state=active]:opacity-100 data-[state=active]:delay-0 data-[state=active]:duration-200 data-[state=active]:ease-(--ease-out-strong)'
                >
                  {step.media}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

export function StickySections({ className, ...props }: ComponentProps<'div'>) {
  return <div className={cn('relative', className)} {...props} />;
}

export function StickySection({
  className,
  ...props
}: ComponentProps<'section'>) {
  return (
    <section
      className={cn('sticky top-0 flex h-svh flex-col', className)}
      {...props}
    />
  );
}

'use client';

import {
  animate,
  motion,
  type MotionValue,
  type Transition,
  useMotionValue,
} from 'motion/react';
import { useCallback, useId, useLayoutEffect, useRef, useState } from 'react';

import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type SwapGridItem = {
  id: string;
  label: string;
  content: React.ReactNode;
};

export type SwapGridSlots = (string | null)[];

type TileHandle = {
  element: HTMLElement;
  x: MotionValue<number>;
  y: MotionValue<number>;
};

type FlipStart = {
  left: number;
  top: number;
  velocityX: number;
  velocityY: number;
};

type DragSession = {
  id: string;
  pointerId: number;
  startX: number;
  startY: number;
  originX: number;
  originY: number;
  originSlot: number;
  isActive: boolean;
};

type Grab = {
  id: string;
  originSlots: SwapGridSlots;
};

type Step = { rows: number; columns: number };

const SETTLE: Transition = { type: 'spring', bounce: 0, duration: 0.4 };

const DRAG_THRESHOLD = 4;

const STEPS: Record<string, Step> = {
  ArrowUp: { rows: -1, columns: 0 },
  ArrowDown: { rows: 1, columns: 0 },
  ArrowLeft: { rows: 0, columns: -1 },
  ArrowRight: { rows: 0, columns: 1 },
};

const CONTROLS = 'button, a, input, select, textarea, [contenteditable="true"]';

function placementOf(index: number, columns: number): React.CSSProperties {
  const column = index % columns;
  const row = Math.floor(index / columns);
  return { gridColumn: column + 1, gridRow: row + 1 };
}

function positionOf(index: number, columns: number) {
  const column = index % columns;
  const row = Math.floor(index / columns);
  return `row ${row + 1}, column ${column + 1}`;
}

function neighbourOf(
  index: number,
  step: Step,
  columns: number,
  slotCount: number
) {
  const column = index % columns;
  const row = Math.floor(index / columns);
  const nextColumn = column + step.columns;
  const nextRow = row + step.rows;
  const isInsideRow = nextColumn >= 0 && nextColumn < columns;
  const rowStart = nextRow * columns;
  const nextIndex = rowStart + nextColumn;
  const isInsideGrid = nextRow >= 0 && nextIndex < slotCount;
  if (!isInsideRow) {
    return null;
  }
  if (!isInsideGrid) {
    return null;
  }
  return nextIndex;
}

function swappedSlots(slots: SwapGridSlots, from: number, to: number) {
  const next = [...slots];
  const moving = next[from];
  next[from] = next[to];
  next[to] = moving;
  return next;
}

function presentIds(ids: (string | null)[]) {
  return ids.filter((id): id is string => id !== null);
}

function changedIds(before: SwapGridSlots, after: SwapGridSlots) {
  const moved = after.filter((id, index) => id !== before[index]);
  return presentIds(moved);
}

function startsOnControl(event: React.PointerEvent<HTMLElement>) {
  const target = event.target as HTMLElement;
  const control = target.closest(CONTROLS);
  if (!control) {
    return false;
  }
  return event.currentTarget.contains(control);
}

function isPrimaryPress(event: React.PointerEvent) {
  return event.button === 0;
}

function isActivationKey(event: React.KeyboardEvent) {
  return event.key === 'Enter' || event.key === ' ';
}

function initialSlotsOf(
  items: SwapGridItem[],
  defaultSlots: SwapGridSlots | undefined
) {
  if (defaultSlots) {
    return defaultSlots;
  }
  return items.map((item) => item.id);
}

export type SwapGridProps = {
  items: SwapGridItem[];
  columns?: number;
  defaultSlots?: SwapGridSlots;
  onSlotsChange?: (slots: SwapGridSlots) => void;
  className?: string;
  itemClassName?: string;
  'aria-label'?: string;
};

export function SwapGrid({
  items,
  columns = 3,
  defaultSlots,
  onSlotsChange,
  className,
  itemClassName,
  'aria-label': ariaLabel,
}: SwapGridProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const [slots, setSlots] = useState(() => initialSlotsOf(items, defaultSlots));
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [targetSlot, setTargetSlot] = useState<number | null>(null);
  const [grab, setGrab] = useState<Grab | null>(null);
  const [announcement, setAnnouncement] = useState('');
  const tiles = useRef(new Map<string, TileHandle>());
  const slotElements = useRef(new Map<number, HTMLElement>());
  const flipStarts = useRef<Map<string, FlipStart> | null>(null);
  const drag = useRef<DragSession | null>(null);
  const hintId = useId();
  const labels = new Map(items.map((item) => [item.id, item.label]));
  const contents = new Map(items.map((item) => [item.id, item.content]));

  useLayoutEffect(() => {
    const starts = flipStarts.current;
    flipStarts.current = null;
    if (!starts) {
      return;
    }
    starts.forEach((start, id) => {
      const tile = tiles.current.get(id);
      if (!tile) {
        return;
      }
      if (prefersReducedMotion) {
        tile.x.jump(0);
        tile.y.jump(0);
        return;
      }
      const deltaX = start.left - tile.element.offsetLeft;
      const deltaY = start.top - tile.element.offsetTop;
      tile.x.jump(deltaX);
      tile.y.jump(deltaY);
      animate(tile.x, 0, { ...SETTLE, velocity: start.velocityX });
      animate(tile.y, 0, { ...SETTLE, velocity: start.velocityY });
    });
  }, [slots, prefersReducedMotion]);

  const registerTile = useCallback((id: string, handle: TileHandle) => {
    tiles.current.set(id, handle);
    return () => {
      tiles.current.delete(id);
    };
  }, []);

  function registerSlot(index: number, element: HTMLElement | null) {
    if (!element) {
      slotElements.current.delete(index);
      return;
    }
    slotElements.current.set(index, element);
  }

  function labelOf(id: string | null) {
    if (id === null) {
      return '';
    }
    return labels.get(id) ?? id;
  }

  function rememberPositions(ids: string[]) {
    const starts = new Map<string, FlipStart>();
    for (const id of ids) {
      const tile = tiles.current.get(id);
      if (!tile) {
        continue;
      }
      const left = tile.element.offsetLeft + tile.x.get();
      const top = tile.element.offsetTop + tile.y.get();
      const velocityX = tile.x.getVelocity();
      const velocityY = tile.y.getVelocity();
      starts.set(id, { left, top, velocityX, velocityY });
    }
    return starts;
  }

  function commitSlots(next: SwapGridSlots) {
    const moved = changedIds(slots, next);
    flipStarts.current = rememberPositions(moved);
    setSlots(next);
    onSlotsChange?.(next);
  }

  function swapMessage(id: string, from: number, to: number) {
    const label = labelOf(id);
    const position = positionOf(to, columns);
    const displaced = slots[to];
    if (displaced === null) {
      return `${label} moved to ${position}`;
    }
    const displacedLabel = labelOf(displaced);
    const displacedPosition = positionOf(from, columns);
    return `${label} swapped with ${displacedLabel}. ${label} is in ${position}, ${displacedLabel} in ${displacedPosition}`;
  }

  function swap(id: string, from: number, to: number) {
    const message = swapMessage(id, from, to);
    const next = swappedSlots(slots, from, to);
    setAnnouncement(message);
    commitSlots(next);
  }

  function slotAt(clientX: number, clientY: number) {
    for (const [index, element] of slotElements.current) {
      const box = element.getBoundingClientRect();
      const isInsideX = clientX >= box.left && clientX <= box.right;
      const isInsideY = clientY >= box.top && clientY <= box.bottom;
      if (isInsideX && isInsideY) {
        return index;
      }
    }
    return null;
  }

  function returnHome(id: string) {
    const tile = tiles.current.get(id);
    if (!tile) {
      return;
    }
    if (prefersReducedMotion) {
      tile.x.jump(0);
      tile.y.jump(0);
      return;
    }
    animate(tile.x, 0, SETTLE);
    animate(tile.y, 0, SETTLE);
  }

  function pressTile(id: string, event: React.PointerEvent<HTMLElement>) {
    if (drag.current) {
      return;
    }
    if (!isPrimaryPress(event)) {
      return;
    }
    if (startsOnControl(event)) {
      return;
    }
    const tile = tiles.current.get(id);
    if (!tile) {
      return;
    }
    drag.current = {
      id,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      originX: tile.x.get(),
      originY: tile.y.get(),
      originSlot: slots.indexOf(id),
      isActive: false,
    };
  }

  function activateDrag(
    session: DragSession,
    tile: TileHandle,
    event: React.PointerEvent<HTMLElement>
  ) {
    session.isActive = true;
    event.currentTarget.setPointerCapture(event.pointerId);
    tile.x.stop();
    tile.y.stop();
    window.getSelection()?.removeAllRanges();
    setDraggingId(session.id);
  }

  function moveTile(event: React.PointerEvent<HTMLElement>) {
    const session = drag.current;
    if (!session) {
      return;
    }
    if (event.pointerId !== session.pointerId) {
      return;
    }
    const tile = tiles.current.get(session.id);
    if (!tile) {
      return;
    }
    const deltaX = event.clientX - session.startX;
    const deltaY = event.clientY - session.startY;
    const distance = Math.hypot(deltaX, deltaY);
    const isStillAPress = !session.isActive && distance < DRAG_THRESHOLD;
    if (isStillAPress) {
      return;
    }
    if (!session.isActive) {
      activateDrag(session, tile, event);
    }
    tile.x.set(session.originX + deltaX);
    tile.y.set(session.originY + deltaY);
    const target = slotAt(event.clientX, event.clientY);
    setTargetSlot(target);
  }

  function endDrag(event: React.PointerEvent<HTMLElement>, canDrop: boolean) {
    const session = drag.current;
    if (!session) {
      return;
    }
    if (event.pointerId !== session.pointerId) {
      return;
    }
    drag.current = null;
    if (!session.isActive) {
      return;
    }
    setDraggingId(null);
    setTargetSlot(null);
    const target = slotAt(event.clientX, event.clientY);
    const isOtherSlot = target !== session.originSlot;
    const isDrop = canDrop && isOtherSlot;
    if (target === null || !isDrop) {
      returnHome(session.id);
      return;
    }
    swap(session.id, session.originSlot, target);
  }

  function releaseTile(event: React.PointerEvent<HTMLElement>) {
    endDrag(event, true);
  }

  function cancelDrag(event: React.PointerEvent<HTMLElement>) {
    endDrag(event, false);
  }

  function pickUp(id: string) {
    const slot = slots.indexOf(id);
    const position = positionOf(slot, columns);
    const label = labelOf(id);
    setGrab({ id, originSlots: slots });
    setAnnouncement(
      `${label} picked up in ${position}. Use the arrow keys to move it, Enter to drop it, Escape to cancel`
    );
  }

  function drop(id: string) {
    const slot = slots.indexOf(id);
    const position = positionOf(slot, columns);
    const label = labelOf(id);
    setGrab(null);
    setAnnouncement(`${label} dropped in ${position}`);
  }

  function cancelGrab(current: Grab) {
    const slot = current.originSlots.indexOf(current.id);
    const position = positionOf(slot, columns);
    const label = labelOf(current.id);
    setGrab(null);
    setAnnouncement(`Move cancelled. ${label} is back in ${position}`);
    commitSlots(current.originSlots);
  }

  function moveGrabbed(id: string, step: Step) {
    const from = slots.indexOf(id);
    const to = neighbourOf(from, step, columns, slots.length);
    if (to === null) {
      return;
    }
    swap(id, from, to);
  }

  function handleKeyDown(id: string, event: React.KeyboardEvent<HTMLElement>) {
    if (event.target !== event.currentTarget) {
      return;
    }
    const isGrabbed = grab?.id === id;
    if (isActivationKey(event)) {
      event.preventDefault();
      if (event.repeat) {
        return;
      }
      if (isGrabbed) {
        drop(id);
        return;
      }
      pickUp(id);
      return;
    }
    if (!grab) {
      return;
    }
    if (!isGrabbed) {
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      cancelGrab(grab);
      return;
    }
    const step = STEPS[event.key];
    if (!step) {
      return;
    }
    event.preventDefault();
    moveGrabbed(id, step);
  }

  function handleBlur(id: string) {
    if (grab?.id !== id) {
      return;
    }
    drop(id);
  }

  function isDropTargetOf(id: string, index: number) {
    if (draggingId === null) {
      return false;
    }
    if (draggingId === id) {
      return false;
    }
    return targetSlot === index;
  }

  const gridStyle = {
    gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
  };

  return (
    <>
      <div
        role='group'
        aria-label={ariaLabel}
        className={cn('relative grid gap-3', className)}
        style={gridStyle}
      >
        {slots.map((id, index) => (
          <SwapSlot
            key={`slot-${index}`}
            index={index}
            columns={columns}
            isEmpty={id === null}
            isTarget={targetSlot === index}
            register={registerSlot}
          />
        ))}
        {slots.map((id, index) => {
          if (id === null) {
            return null;
          }
          return (
            <SwapTile
              key={id}
              id={id}
              label={labelOf(id)}
              slotIndex={index}
              columns={columns}
              hintId={hintId}
              isDragging={draggingId === id}
              isDropTarget={isDropTargetOf(id, index)}
              isGrabbed={grab?.id === id}
              className={itemClassName}
              register={registerTile}
              onPress={pressTile}
              onMove={moveTile}
              onRelease={releaseTile}
              onCancel={cancelDrag}
              onKeyDown={handleKeyDown}
              onBlur={handleBlur}
            >
              {contents.get(id)}
            </SwapTile>
          );
        })}
      </div>
      <p id={hintId} className='sr-only'>
        Press Enter or Space to pick up an item, the arrow keys to swap it with
        its neighbour, Enter to drop it and Escape to cancel.
      </p>
      <p aria-live='polite' className='sr-only'>
        {announcement}
      </p>
    </>
  );
}

const SLOT = [
  'hairline-border rounded-xl border-dashed border-transparent',
  'transition-colors duration-150 ease-(--ease-out-strong)',
  'data-[empty=true]:border-foreground/15',
  'data-[target=true]:border-primary/50 data-[target=true]:bg-primary/[0.06]',
].join(' ');

type SwapSlotProps = {
  index: number;
  columns: number;
  isEmpty: boolean;
  isTarget: boolean;
  register: (index: number, element: HTMLElement | null) => void;
};

function SwapSlot({
  index,
  columns,
  isEmpty,
  isTarget,
  register,
}: SwapSlotProps) {
  function attach(element: HTMLDivElement | null) {
    register(index, element);
  }

  return (
    <div
      ref={attach}
      aria-hidden='true'
      data-empty={isEmpty}
      data-target={isTarget}
      className={SLOT}
      style={placementOf(index, columns)}
    />
  );
}

const TILE = [
  'group/tile relative z-10 cursor-grab touch-none rounded-xl outline-none select-none',
  'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring',
  'data-[dragging=true]:z-30 data-[dragging=true]:cursor-grabbing',
  'data-[grabbed=true]:z-20',
].join(' ');

const TILE_SURFACE = [
  'size-full rounded-xl bg-card text-card-foreground',
  'hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
  'transition-[scale,box-shadow] duration-150 ease-(--ease-out-strong)',
  'motion-safe:group-data-[dragging=true]/tile:scale-[1.03] motion-safe:group-data-[grabbed=true]/tile:scale-[1.03]',
  'group-data-[dragging=true]/tile:shadow-[0_12px_32px_-8px_rgb(0_0_0/0.18)]',
  'group-data-[grabbed=true]/tile:ring-primary/60 group-data-[target=true]/tile:ring-primary/60',
].join(' ');

type SwapTileProps = {
  id: string;
  label: string;
  slotIndex: number;
  columns: number;
  hintId: string;
  isDragging: boolean;
  isDropTarget: boolean;
  isGrabbed: boolean;
  className?: string;
  register: (id: string, handle: TileHandle) => () => void;
  onPress: (id: string, event: React.PointerEvent<HTMLElement>) => void;
  onMove: (event: React.PointerEvent<HTMLElement>) => void;
  onRelease: (event: React.PointerEvent<HTMLElement>) => void;
  onCancel: (event: React.PointerEvent<HTMLElement>) => void;
  onKeyDown: (id: string, event: React.KeyboardEvent<HTMLElement>) => void;
  onBlur: (id: string) => void;
  children: React.ReactNode;
};

function SwapTile({
  id,
  label,
  slotIndex,
  columns,
  hintId,
  isDragging,
  isDropTarget,
  isGrabbed,
  className,
  register,
  onPress,
  onMove,
  onRelease,
  onCancel,
  onKeyDown,
  onBlur,
  children,
}: SwapTileProps) {
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const attach = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) {
        return;
      }
      return register(id, { element, x, y });
    },
    [id, register, x, y]
  );

  function press(event: React.PointerEvent<HTMLDivElement>) {
    onPress(id, event);
  }

  function keyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    onKeyDown(id, event);
  }

  function blur() {
    onBlur(id);
  }

  return (
    <motion.div
      ref={attach}
      role='button'
      tabIndex={0}
      aria-roledescription='swappable item'
      aria-label={`${label}, ${positionOf(slotIndex, columns)}`}
      aria-describedby={hintId}
      aria-pressed={isGrabbed}
      data-dragging={isDragging}
      data-grabbed={isGrabbed}
      data-target={isDropTarget}
      className={TILE}
      style={{ ...placementOf(slotIndex, columns), x, y }}
      onPointerDown={press}
      onPointerMove={onMove}
      onPointerUp={onRelease}
      onPointerCancel={onCancel}
      onKeyDown={keyDown}
      onBlur={blur}
    >
      <div className={cn(TILE_SURFACE, className)}>{children}</div>
    </motion.div>
  );
}

'use client';
import { cn } from '@/lib/utils';
import {
  AnimatePresence,
  animate,
  motion,
  useInView,
  useMotionValue,
  useTransform,
  type MotionValue,
  type Transition,
} from 'motion/react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { CheckIcon, CopyIcon, RotateCcwIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

export type TerminalTone =
  'default' | 'muted' | 'success' | 'warning' | 'error';

export type TerminalLine =
  | { kind: 'command'; text: string }
  | { kind: 'output'; text: string; tone?: TerminalTone; delay?: number };

type LineStatus = 'done' | 'active' | 'pending';

const TONE_CLASS: Record<TerminalTone, string> = {
  default: 'text-foreground',
  muted: 'text-muted-foreground',
  success: 'text-success-foreground',
  warning: 'text-warning-foreground',
  error: 'text-destructive-ink',
};

const PAUSE_AFTER_COMMAND_MS = 400;

const COPIED_DURATION_MS = 1600;

const BLINK: Transition = {
  duration: 1.06,
  times: [0, 0.5, 0.5, 1],
  repeat: Infinity,
  ease: 'linear',
};

const STEADY: Transition = { duration: 0 };

const SWAP_TRANSITION = { duration: 0.15, ease: [0.2, 0, 0, 1] } as const;

function statusOf(index: number, cursor: number): LineStatus {
  if (index < cursor) {
    return 'done';
  }
  if (index === cursor) {
    return 'active';
  }
  return 'pending';
}

function cursorOf(
  shouldReduceMotion: boolean | null,
  activeLine: number,
  lineCount: number
) {
  if (shouldReduceMotion) {
    return lineCount;
  }
  return activeLine;
}

function typedClipOf(typed: number) {
  const visibleCharacters = Math.round(typed);
  return `inset(0 calc(100% - ${visibleCharacters}ch) 0 0)`;
}

function caretOffsetOf(typed: number) {
  const visibleCharacters = Math.round(typed);
  return `translateX(${visibleCharacters}ch)`;
}

function caretMotionOf(shouldBlink: boolean) {
  if (shouldBlink) {
    return { animate: { opacity: [1, 1, 0, 0] }, transition: BLINK };
  }
  return { animate: { opacity: 1 }, transition: STEADY };
}

function swapMotionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return {
      initial: { opacity: 0 },
      animate: { opacity: 1 },
      exit: { opacity: 0 },
    };
  }
  return {
    initial: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
    animate: { opacity: 1, scale: 1, filter: 'blur(0px)' },
    exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  };
}

function Caret({
  isBlinking,
  shouldReduceMotion,
  style,
}: {
  isBlinking: boolean;
  shouldReduceMotion: boolean | null;
  style?: { transform: MotionValue<string> };
}) {
  const shouldBlink = isBlinking && !shouldReduceMotion;
  const caretMotion = caretMotionOf(shouldBlink);

  return (
    <motion.span
      aria-hidden='true'
      className='bg-foreground/70 absolute inset-y-[0.2em] left-0 w-[1ch]'
      style={style}
      {...caretMotion}
    />
  );
}

function Prompt({ prompt }: { prompt: string }) {
  return (
    <span
      aria-hidden='true'
      className='text-muted-foreground shrink-0 pr-[1ch] select-none'
    >
      {prompt}
    </span>
  );
}

function TypedCommand({
  text,
  prompt,
  isPlaying,
  typingSpeed,
  shouldReduceMotion,
  onTyped,
}: {
  text: string;
  prompt: string;
  isPlaying: boolean;
  typingSpeed: number;
  shouldReduceMotion: boolean | null;
  onTyped: () => void;
}) {
  const typed = useMotionValue(0);
  const clipPath = useTransform(typed, typedClipOf);
  const caretOffset = useTransform(typed, caretOffsetOf);

  useEffect(() => {
    if (!isPlaying) {
      return;
    }
    let isCancelled = false;
    let pauseTimer: ReturnType<typeof setTimeout> | undefined;
    const typingMs = text.length * typingSpeed;
    const typingSeconds = typingMs / 1000;
    const controls = animate(typed, text.length, {
      duration: typingSeconds,
      ease: 'linear',
    });
    controls.then(() => {
      if (isCancelled) {
        return;
      }
      pauseTimer = setTimeout(onTyped, PAUSE_AFTER_COMMAND_MS);
    });
    return () => {
      isCancelled = true;
      controls.stop();
      clearTimeout(pauseTimer);
    };
  }, [isPlaying, text, typingSpeed, typed, onTyped]);

  return (
    <div className='flex'>
      <Prompt prompt={prompt} />
      <span className='relative shrink-0'>
        <motion.span className='block' style={{ clipPath }}>
          {text}
        </motion.span>
        <Caret
          isBlinking={!isPlaying}
          shouldReduceMotion={shouldReduceMotion}
          style={{ transform: caretOffset }}
        />
      </span>
    </div>
  );
}

function StaticLine({
  line,
  prompt,
  isHidden,
}: {
  line: TerminalLine;
  prompt: string;
  isHidden: boolean;
}) {
  if (line.kind === 'command') {
    return (
      <div className={cn('flex', isHidden && 'opacity-0')}>
        <Prompt prompt={prompt} />
        <span className='shrink-0'>{line.text}</span>
      </div>
    );
  }
  const tone = line.tone ?? 'default';

  return (
    <div className={cn('shrink-0', TONE_CLASS[tone], isHidden && 'opacity-0')}>
      {line.text}
    </div>
  );
}

function TerminalSession({
  lines,
  prompt,
  typingSpeed,
  outputDelay,
}: {
  lines: TerminalLine[];
  prompt: string;
  typingSpeed: number;
  outputDelay: number;
}) {
  const sessionRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isInView = useInView(sessionRef, { once: true, amount: 0.5 });
  const [activeLine, setActiveLine] = useState(0);
  const cursor = cursorOf(shouldReduceMotion, activeLine, lines.length);
  const isPlaying = isInView && !shouldReduceMotion;
  const isFinished = cursor >= lines.length;

  const advance = useCallback(() => {
    setActiveLine((current) => current + 1);
  }, []);

  useEffect(() => {
    if (!isPlaying) {
      return;
    }
    const line = lines[activeLine];
    const isOutput = line?.kind === 'output';
    if (!isOutput) {
      return;
    }
    const delay = line.delay ?? outputDelay;
    const timer = setTimeout(advance, delay);
    return () => clearTimeout(timer);
  }, [activeLine, isPlaying, lines, outputDelay, advance]);

  return (
    <div ref={sessionRef} className='overflow-x-auto px-4 pb-4 whitespace-pre'>
      {lines.map((line, index) => {
        const key = `${index}-${line.text}`;
        const status = statusOf(index, cursor);
        const isTyping = status === 'active' && line.kind === 'command';

        if (isTyping) {
          return (
            <TypedCommand
              key={key}
              text={line.text}
              prompt={prompt}
              isPlaying={isPlaying}
              typingSpeed={typingSpeed}
              shouldReduceMotion={shouldReduceMotion}
              onTyped={advance}
            />
          );
        }
        return (
          <StaticLine
            key={key}
            line={line}
            prompt={prompt}
            isHidden={status === 'pending'}
          />
        );
      })}
      <div
        aria-hidden='true'
        className={cn('flex', !isFinished && 'opacity-0')}
      >
        <Prompt prompt={prompt} />
        <span className='relative'>
          <span className='invisible'> </span>
          <Caret isBlinking shouldReduceMotion={shouldReduceMotion} />
        </span>
      </div>
    </div>
  );
}

function CopyCommandsButton({ commands }: { commands: string }) {
  const [hasCopied, setHasCopied] = useState(false);
  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const swap = swapMotionOf(shouldReduceMotion);

  useEffect(() => {
    return () => {
      if (resetTimer.current) {
        clearTimeout(resetTimer.current);
      }
    };
  }, []);

  async function copy() {
    try {
      await navigator.clipboard.writeText(commands);
    } catch {
      return;
    }
    setHasCopied(true);
    if (resetTimer.current) {
      clearTimeout(resetTimer.current);
    }
    resetTimer.current = setTimeout(() => {
      setHasCopied(false);
    }, COPIED_DURATION_MS);
  }

  return (
    <Button
      variant='ghost'
      size='icon-sm'
      className='text-muted-foreground'
      aria-label='Copy commands'
      onClick={copy}
    >
      <AnimatePresence mode='popLayout' initial={false}>
        {hasCopied && (
          <motion.span
            key='copied'
            className='flex'
            transition={SWAP_TRANSITION}
            {...swap}
          >
            <CheckIcon />
          </motion.span>
        )}
        {!hasCopied && (
          <motion.span
            key='copy'
            className='flex'
            transition={SWAP_TRANSITION}
            {...swap}
          >
            <CopyIcon />
          </motion.span>
        )}
      </AnimatePresence>
      <span className='sr-only' aria-live='polite'>
        {hasCopied && 'Copied'}
      </span>
    </Button>
  );
}

export type TerminalProps = {
  lines: TerminalLine[];
  title?: string;
  prompt?: string;
  typingSpeed?: number;
  outputDelay?: number;
  className?: string;
};

export function Terminal({
  lines,
  title = 'Terminal',
  prompt = '$',
  typingSpeed = 32,
  outputDelay = 120,
  className,
}: TerminalProps) {
  const [run, setRun] = useState(0);
  const shouldReduceMotion = usePrefersReducedMotion();
  const commandLines = lines.filter((line) => line.kind === 'command');
  const commandTexts = commandLines.map((line) => line.text);
  const commands = commandTexts.join('\n');
  const hasCommands = commandLines.length > 0;
  const canReplay = !shouldReduceMotion;

  function replay() {
    setRun((current) => current + 1);
  }

  return (
    <div
      className={cn(
        'bg-card hairline-ring ring-border w-full overflow-hidden rounded-xl font-mono text-[13px] leading-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <div className='flex h-10 items-center justify-between gap-2 pr-1.5 pl-4'>
        <span className='text-muted-foreground font-sans text-xs'>{title}</span>
        <div className='flex items-center gap-0.5'>
          {canReplay && (
            <Button
              variant='ghost'
              size='icon-sm'
              className='text-muted-foreground'
              aria-label='Replay'
              onClick={replay}
            >
              <RotateCcwIcon />
            </Button>
          )}
          {hasCommands && <CopyCommandsButton commands={commands} />}
        </div>
      </div>
      <TerminalSession
        key={run}
        lines={lines}
        prompt={prompt}
        typingSpeed={typingSpeed}
        outputDelay={outputDelay}
      />
    </div>
  );
}

'use client';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  Fragment,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ElementType,
  type RefObject,
} from 'react';

export type Text3DFlipDirection = 'up' | 'down' | 'left' | 'right';

export type Text3DFlipStaggerFrom =
  'first' | 'last' | 'center' | 'random' | number;

type Turn = {
  front: string;
  back: string;
  origin: string;
};

type Letter = {
  character: string;
  index: number;
};

type Word = {
  letters: Letter[];
};

type FaceStyles = {
  front: CSSProperties;
  back: CSSProperties;
};

type Timing = {
  duration: number;
  delay: number;
};

/**
 * Each letter is the front of a small cube: the axis sits half a line (or half a letter) behind
 * the text, so the face that leaves and the face that arrives turn together like one block.
 */
const VERTICAL_ORIGIN = '50% 50% -0.5lh';

const HORIZONTAL_ORIGIN = '50% 50% -0.3em';

const TURNS: Record<Text3DFlipDirection, Turn> = {
  up: {
    front: 'rotateX(90deg)',
    back: 'rotateX(-90deg)',
    origin: VERTICAL_ORIGIN,
  },
  down: {
    front: 'rotateX(-90deg)',
    back: 'rotateX(90deg)',
    origin: VERTICAL_ORIGIN,
  },
  left: {
    front: 'rotateY(-90deg)',
    back: 'rotateY(90deg)',
    origin: HORIZONTAL_ORIGIN,
  },
  right: {
    front: 'rotateY(90deg)',
    back: 'rotateY(-90deg)',
    origin: HORIZONTAL_ORIGIN,
  },
};

const RESTING = 'none';

const EASE_OUT_STRONG = 'cubic-bezier(0.23, 1, 0.32, 1)';

const RETURN_SPEED = 0.7;

const RETURN_STAGGER = 0.6;

const FADE_MS = 150;

const INTERACTIVE_ANCESTOR = [
  'a[href]',
  'button',
  'summary',
  'label',
  '[role="button"]',
  '[role="link"]',
  '[role="tab"]',
  '[role="menuitem"]',
  '[role="option"]',
].join(', ');

function wordsOf(text: string): Word[] {
  const words: Word[] = [];
  let index = 0;
  for (const part of text.split(' ')) {
    const letters: Letter[] = [];
    for (const character of Array.from(part)) {
      letters.push({ character, index });
      index += 1;
    }
    words.push({ letters });
  }
  return words;
}

function letterCountOf(words: readonly Word[]) {
  let count = 0;
  for (const word of words) {
    count += word.letters.length;
  }
  return count;
}

/** A fixed shuffle, so the server and the browser agree on the order. */
function shuffledRankOf(index: number, count: number) {
  const position = index + 1;
  const angle = position * 12.9898;
  const sine = Math.sin(angle);
  const wave = sine * 43758.5453;
  const whole = Math.floor(wave);
  const fraction = wave - whole;
  const lastIndex = count - 1;
  const spread = Math.max(lastIndex, 0);
  return fraction * spread;
}

function rankOf(index: number, count: number, from: Text3DFlipStaggerFrom) {
  const lastIndex = count - 1;
  if (typeof from === 'number') {
    return Math.abs(index - from);
  }
  if (from === 'last') {
    return lastIndex - index;
  }
  if (from === 'center') {
    const middle = lastIndex / 2;
    return Math.abs(index - middle);
  }
  if (from === 'random') {
    return shuffledRankOf(index, count);
  }
  return index;
}

function timingOf(
  rank: number,
  isFlipped: boolean,
  duration: number,
  stagger: number
): Timing {
  if (isFlipped) {
    const delay = rank * stagger;
    return { duration, delay };
  }
  const returnDuration = duration * RETURN_SPEED;
  const returnStagger = stagger * RETURN_STAGGER;
  const returnDelay = rank * returnStagger;
  return { duration: returnDuration, delay: returnDelay };
}

function millisecondsOf(seconds: number) {
  const milliseconds = seconds * 1000;
  return Math.round(milliseconds);
}

function transitionOf(property: string, timing: Timing) {
  const durationMs = millisecondsOf(timing.duration);
  const delayMs = millisecondsOf(timing.delay);
  return `${property} ${durationMs}ms ${EASE_OUT_STRONG} ${delayMs}ms`;
}

function frontTransformOf(turn: Turn, isFlipped: boolean) {
  if (isFlipped) {
    return turn.front;
  }
  return RESTING;
}

function backTransformOf(turn: Turn, isFlipped: boolean) {
  if (isFlipped) {
    return RESTING;
  }
  return turn.back;
}

function turningStylesOf(
  turn: Turn,
  isFlipped: boolean,
  timing: Timing
): FaceStyles {
  const transition = transitionOf('transform', timing);
  return {
    front: {
      transform: frontTransformOf(turn, isFlipped),
      transformOrigin: turn.origin,
      transition,
    },
    back: {
      transform: backTransformOf(turn, isFlipped),
      transformOrigin: turn.origin,
      transition,
    },
  };
}

function frontOpacityOf(isFlipped: boolean) {
  if (isFlipped) {
    return 0;
  }
  return 1;
}

function backOpacityOf(isFlipped: boolean) {
  if (isFlipped) {
    return 1;
  }
  return 0;
}

function fadingStylesOf(isFlipped: boolean): FaceStyles {
  const transition = `opacity ${FADE_MS}ms ${EASE_OUT_STRONG}`;
  return {
    front: { opacity: frontOpacityOf(isFlipped), transition },
    back: { opacity: backOpacityOf(isFlipped), transition },
  };
}

function isTouchPointer(event: PointerEvent) {
  return event.pointerType === 'touch';
}

function isKeyboardFocus(event: FocusEvent) {
  const target = event.target;
  if (!(target instanceof Element)) {
    return false;
  }
  return target.matches(':focus-visible');
}

/**
 * Hover and keyboard focus of the link or button the text sits in. Text outside a link or a
 * button never reacts to the pointer: plain text that moves on hover reads as something to click.
 */
function useAncestorActivity(
  rootRef: RefObject<HTMLElement | null>,
  isListening: boolean
) {
  const [isHovered, setIsHovered] = useState(false);
  const [isFocused, setIsFocused] = useState(false);

  useEffect(() => {
    const root = rootRef.current;
    if (!isListening) {
      return;
    }
    if (!root) {
      return;
    }
    const trigger = root.closest<HTMLElement>(INTERACTIVE_ANCESTOR);
    if (!trigger) {
      return;
    }
    const handlePointerEnter = (event: PointerEvent) => {
      if (isTouchPointer(event)) {
        return;
      }
      setIsHovered(true);
    };
    const handlePointerLeave = () => {
      setIsHovered(false);
    };
    const handleFocusIn = (event: FocusEvent) => {
      const isFromKeyboard = isKeyboardFocus(event);
      setIsFocused(isFromKeyboard);
    };
    const handleFocusOut = () => {
      setIsFocused(false);
    };
    trigger.addEventListener('pointerenter', handlePointerEnter);
    trigger.addEventListener('pointerleave', handlePointerLeave);
    trigger.addEventListener('focusin', handleFocusIn);
    trigger.addEventListener('focusout', handleFocusOut);
    return () => {
      trigger.removeEventListener('pointerenter', handlePointerEnter);
      trigger.removeEventListener('pointerleave', handlePointerLeave);
      trigger.removeEventListener('focusin', handleFocusIn);
      trigger.removeEventListener('focusout', handleFocusOut);
    };
  }, [rootRef, isListening]);

  return isHovered || isFocused;
}

type FlipLetterProps = {
  character: string;
  styles: FaceStyles;
  textClassName?: string;
  backClassName?: string;
};

function FlipLetter({
  character,
  styles,
  textClassName,
  backClassName,
}: FlipLetterProps) {
  return (
    <span className='inline-grid [perspective:4em]'>
      <span
        className={cn('col-start-1 row-start-1 backface-hidden', textClassName)}
        style={styles.front}
      >
        {character}
      </span>
      <span
        className={cn('col-start-1 row-start-1 backface-hidden', backClassName)}
        style={styles.back}
