                    initial={{ height: 0 }}
                    animate={{ height: heightContent || 0 }}
                    exit={{ height: 0 }}
                    style={{
                      width: maxWidth,
                    }}
                  >
                    <div ref={contentRef} className='p-2'>
                      {ITEMS.map((item) => {
                        const isSelected = active === item.id;

                        return (
                          <motion.div
                            key={item.id}
                            initial={{ opacity: 0 }}
                            animate={{ opacity: panelOpacityOf(isSelected) }}
                            exit={{ opacity: 0 }}
                          >
                            <div
                              className={cn(
                                'px-2 pt-2 text-[13px]',
                                panelDisplayOf(isSelected)
                              )}
                            >
                              {item.content}
                            </div>
                          </motion.div>
                        );
                      })}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
            <div className='flex space-x-2 p-2' ref={menuRef}>
              {ITEMS.map((item) => (
                <button
                  key={item.id}
                  aria-label={item.label}
                  className={cn(TOOL_BUTTON, toolStateOf(active === item.id))}
                  type='button'
                  onClick={() => {
                    if (!isOpen) setIsOpen(true);
                    if (active === item.id) {
                      setIsOpen(false);
                      setActive(null);
                      return;
                    }

                    setActive(item.id);
                  }}
                >
                  {item.title}
                </button>
              ))}
            </div>
          </div>
        </div>
      </MotionConfig>
    </ReducedMotionConfig>
  );
}

'use client';
import {
  AnimatePresence,
  Transition,
  Variant,
  motion,
  MotionConfig,
  MotionProps,
} from 'motion/react';
import { cn } from '@/lib/utils';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type TransitionPanelProps = {
  children: React.ReactNode[];
  className?: string;
  transition?: Transition;
  activeIndex: number;
  variants?: { enter: Variant; center: Variant; exit: Variant };
} & MotionProps;

function ReducedMotionConfig({ children }: { children: React.ReactNode }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

export function TransitionPanel({
  children,
  className,
  transition,
  variants,
  activeIndex,
  ...motionProps
}: TransitionPanelProps) {
  return (
    <ReducedMotionConfig>
      <div className={cn('relative', className)}>
        <AnimatePresence
          initial={false}
          mode='popLayout'
          custom={motionProps.custom}
        >
          <motion.div
            key={activeIndex}
            variants={variants}
            transition={transition}
            initial='enter'
            animate='center'
            exit='exit'
            {...motionProps}
          >
            {children[activeIndex]}
          </motion.div>
        </AnimatePresence>
      </div>
    </ReducedMotionConfig>
  );
}

'use client';
import { cn } from '@/lib/utils';
import {
  AnimatePresence,
  LayoutGroup,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState, type ReactNode } from 'react';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

export type WordRollDirection = 'up' | 'down';

/**
 * A word is a string, or a node with a stable key: the node keeps its place while its own content
 * changes (a `MotionNumber` inside a phrase), and rolls only when its key changes.
 */
export type WordRollWord =
  | string
  | {
      key: string;
      text: string;
      node: ReactNode;
    };

type RollItem = {
  key: string;
  text: string;
  node: ReactNode;
};

type SlotChange = {
  index: number;
  item: RollItem | null;
  exits: boolean;
  enters: boolean;
};

type SlotPlan = {
  index: number;
  item: RollItem | null;
  enterDelay: number;
  exitDelay: number;
};

type WordMotion = {
  direction: WordRollDirection;
  delay: number;
};

const ENTER_DURATION = 0.28;

const EXIT_DURATION = 0.2;

const ENTER_STAGGER = 0.07;

const EXIT_STAGGER = 0.05;

const ENTER_EASE: [number, number, number, number] = [0.22, 1, 0.36, 1];

const BLURRED = 'blur(4px)';

const SHARP = 'blur(0px)';

const RESTING = 'translateY(0%)';

const BELOW = 'translateY(110%)';

const ABOVE = 'translateY(-110%)';

/** Same spring as `AnimatedSize`, so the last word and the clipping edge move together. */
const SLIDE: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const FADE_IN: Transition = { duration: 0.15, ease: [0.23, 1, 0.32, 1] };

const FADE_OUT: Transition = { duration: 0.1, ease: [0.23, 1, 0.32, 1] };

function enteringOffsetOf(direction: WordRollDirection) {
  if (direction === 'down') {
    return ABOVE;
  }
  return BELOW;
}

function leavingOffsetOf(direction: WordRollDirection) {
  if (direction === 'down') {
    return BELOW;
  }
  return ABOVE;
}

const ROLL_VARIANTS: Variants = {
  hidden: (wordMotion: WordMotion) => ({
    transform: enteringOffsetOf(wordMotion.direction),
    filter: BLURRED,
  }),
  shown: (wordMotion: WordMotion) => ({
    transform: RESTING,
    filter: SHARP,
    transition: {
      duration: ENTER_DURATION,
      ease: ENTER_EASE,
      delay: wordMotion.delay,
    },
  }),
  gone: (wordMotion: WordMotion) => ({
    transform: leavingOffsetOf(wordMotion.direction),
    filter: BLURRED,
    transition: {
      duration: EXIT_DURATION,
      ease: 'easeIn',
      delay: wordMotion.delay,
    },
  }),
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1, transition: FADE_IN },
  gone: { opacity: 0, transition: FADE_OUT },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ROLL_VARIANTS;
}

function slideOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return SLIDE;
}

function itemOf(word: WordRollWord): RollItem {
  if (typeof word === 'string') {
    return { key: `word:${word}`, text: word, node: word };
  }
  return { key: `node:${word.key}`, text: word.text, node: word.node };
}

function wordsOfText(text: string) {
  const trimmed = text.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(/\s+/);
}

function itemsOf(
  text: string | undefined,
  words: readonly WordRollWord[] | undefined
) {
  if (words) {
    return words.map(itemOf);
  }
  const textWords = wordsOfText(text ?? '');
  return textWords.map(itemOf);
}

function haveSameKeys(first: readonly string[], second: readonly string[]) {
  if (first.length !== second.length) {
    return false;
  }
  return first.every((key, index) => key === second[index]);
}

function trendOf(
  previous: number | undefined,
  next: number | undefined,
  current: WordRollDirection
): WordRollDirection {
  if (previous === undefined) {
    return current;
  }
  if (next === undefined) {
    return current;
  }
  if (next < previous) {
    return 'down';
  }
  return 'up';
}

function keyOf(item: RollItem | null) {
  if (!item) {
    return null;
  }
  return item.key;
}

function changeAt(
  index: number,
  previousKeys: readonly string[],
  items: readonly RollItem[]
): SlotChange {
  const previousKey = previousKeys[index] ?? null;
  const item = items[index] ?? null;
  const key = keyOf(item);
  const isChanged = previousKey !== key;
  const hadWord = previousKey !== null;
  const hasWord = key !== null;
  const exits = isChanged && hadWord;
  const enters = isChanged && hasWord;
  return { index, item, exits, enters };
}

/** How long the leaving words take as a line, so the new words rise once they are all gone. */
function exitPhaseOf(exitCount: number) {
  if (exitCount === 0) {
    return 0;
  }
  const staggered = (exitCount - 1) * EXIT_STAGGER;
  return EXIT_DURATION + staggered;
}

/**
 * Only the words that changed roll, staggered among themselves. A slot whose word leaves mounts
 * its new word when the old one is gone, so its enter delay is counted from that moment.
 */
function planSlots(
  previousKeys: readonly string[],
  items: readonly RollItem[],
  slotCount: number
) {
  const indexes = Array.from({ length: slotCount }, (_, index) => index);
  const changes = indexes.map((index) => changeAt(index, previousKeys, items));
  const exiting = changes.filter((change) => change.exits);
  const exitPhase = exitPhaseOf(exiting.length);
  const plans: SlotPlan[] = [];
  let exitRank = 0;
  let enterRank = 0;

  for (const change of changes) {
    let exitDelay = 0;
    let exitEnd = 0;
    let enterDelay = 0;
    if (change.exits) {
      exitDelay = exitRank * EXIT_STAGGER;
      exitEnd = exitDelay + EXIT_DURATION;
      exitRank += 1;
    }
    if (change.enters) {
      const enterOffset = enterRank * ENTER_STAGGER;
      const enterStart = exitPhase + enterOffset;
      enterDelay = enterStart - exitEnd;
      enterRank += 1;
    }
    plans.push({
      index: change.index,
      item: change.item,
      enterDelay,
      exitDelay,
    });
  }

  return plans;
}

function leadingSpaceOf(index: number) {
  if (index === 0) {
    return null;
  }
  return ' ';
}

type WordSlotProps = {
  plan: SlotPlan;
  direction: WordRollDirection;
  variants: Variants;
  slide: Transition;
  initialSlotCount: number;
  /** The words in order: the slots are only measured again when it changes, not on every render. */
  layoutKey: string;
};

function WordSlot({
  plan,
  direction,
  variants,
  slide,
  initialSlotCount,
  layoutKey,
}: WordSlotProps) {
  const isAddedLater = plan.index >= initialSlotCount;
  const leadingSpace = leadingSpaceOf(plan.index);
  const enterMotion: WordMotion = { direction, delay: plan.enterDelay };
  const exitMotion: WordMotion = { direction, delay: plan.exitDelay };

  return (
    <motion.span
      layout='position'
      layoutDependency={layoutKey}
      transition={slide}
      className='flex overflow-y-clip'
    >
      <AnimatePresence mode='wait' initial={isAddedLater} custom={exitMotion}>
        {plan.item && (
          <motion.span
            key={plan.item.key}
            custom={enterMotion}
            variants={variants}
            initial='hidden'
            animate='shown'
            exit='gone'
            className='block whitespace-pre'
          >
            {leadingSpace}
            {plan.item.node}
          </motion.span>
        )}
      </AnimatePresence>
    </motion.span>
  );
}

type RollFrameProps = {
  labels: readonly string[] | undefined;
  children: ReactNode;
};

function RollFrame({ labels, children }: RollFrameProps) {
  const hasLabels = labels !== undefined && labels.length > 0;

  if (hasLabels) {
    return (
      <span aria-hidden='true' className='inline-grid'>
        {labels.map((label, index) => (
          <span
            key={`${index}-${label}`}
            className='invisible col-start-1 row-start-1 whitespace-pre'
          >
            {label}
          </span>
        ))}
        <span className='col-start-1 row-start-1 flex items-baseline'>
          {children}
        </span>
      </span>
    );
  }

  return (
    <AnimatedSize
      as='span'
      axis='width'
      contentClassName='flex items-baseline'
      aria-hidden='true'
    >
      {children}
    </AnimatedSize>
  );
}

type WordRollContent =
  | {
      text: string;
      words?: never;
    }
  | {
      words: readonly WordRollWord[];
      text?: never;
    };

export type WordRollProps = WordRollContent & {
  labels?: readonly string[];
  direction?: WordRollDirection;
  value?: number;
  accessibleText?: string;
  className?: string;
};

export function WordRoll({
  text,
  words,
  labels,
  direction,
  value,
  accessibleText,
  className,
}: WordRollProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const items = itemsOf(text, words);
  const keys = items.map((item) => item.key);
  const [initialSlotCount] = useState(keys.length);
  const [slotCount, setSlotCount] = useState(keys.length);
  const [currentKeys, setCurrentKeys] = useState<readonly string[]>(keys);
  const [previousKeys, setPreviousKeys] = useState<readonly string[]>(keys);
  const [previousValue, setPreviousValue] = useState(value);
  const [trend, setTrend] = useState<WordRollDirection>('up');

  const hasNewWords = !haveSameKeys(keys, currentKeys);
  if (hasNewWords) {
    setPreviousKeys(currentKeys);
    setCurrentKeys(keys);
  }

  const needsMoreSlots = keys.length > slotCount;
  if (needsMoreSlots) {
    setSlotCount(keys.length);
  }

  const hasNewValue = !Object.is(value, previousValue);
  if (hasNewValue) {
    const nextTrend = trendOf(previousValue, value, trend);
    setPreviousValue(value);
    setTrend(nextTrend);
  }

  const rollDirection = direction ?? trend;
  const renderedSlotCount = Math.max(slotCount, keys.length);
  const plans = planSlots(previousKeys, items, renderedSlotCount);
  const variants = variantsOf(shouldReduceMotion);
  const slide = slideOf(shouldReduceMotion);
  const spokenWords = items.map((item) => item.text);
  const spokenText = accessibleText ?? spokenWords.join(' ');
  const layoutKey = keys.join('\n');

  return (
    <span
      className={cn('inline-flex items-baseline whitespace-nowrap', className)}
    >
      <span className='sr-only'>{spokenText}</span>
      <RollFrame labels={labels}>
        <LayoutGroup inherit={false}>
          {plans.map((plan) => (
            <WordSlot
              key={plan.index}
              plan={plan}
              direction={rollDirection}
              variants={variants}
              slide={slide}
              initialSlotCount={initialSlotCount}
              layoutKey={layoutKey}
            />
          ))}
        </LayoutGroup>
      </RollFrame>
    </span>
  );
}

'use client';
import { cn } from '@/lib/utils';
import {
  AnimatePresence,
  motion,
  useInView,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useEffectEvent, useRef, useState } from 'react';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

export type WordRotateDirection = 'up' | 'down';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const TURN_IN: Transition = { duration: 0.5, ease: EASE_OUT_STRONG };

const TURN_OUT: Transition = {
  duration: 0.35,
  ease: EASE_OUT_STRONG,
  opacity: { duration: 0.2, ease: EASE_OUT_STRONG },
};

const FADE_IN: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const FADE_OUT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const FACING = 'translateY(0%) rotateX(0deg)';

const LOWER_SIDE = 'translateY(55%) rotateX(-70deg)';

const UPPER_SIDE = 'translateY(-55%) rotateX(70deg)';

const BLURRED = 'blur(4px)';

const SHARP = 'blur(0px)';

function arrivingSideOf(direction: WordRotateDirection) {
  if (direction === 'down') {
    return UPPER_SIDE;
  }
  return LOWER_SIDE;
}

function leavingSideOf(direction: WordRotateDirection) {
  if (direction === 'down') {
    return LOWER_SIDE;
  }
  return UPPER_SIDE;
}

/** The phrases sit on a drum: the next one turns in from one side while the last one turns away. */
const DRUM_VARIANTS: Variants = {
  hidden: (direction: WordRotateDirection) => ({
    transform: arrivingSideOf(direction),
    filter: BLURRED,
    opacity: 0,
  }),
  shown: {
    transform: FACING,
    filter: SHARP,
    opacity: 1,
    transition: TURN_IN,
  },
  gone: (direction: WordRotateDirection) => ({
    transform: leavingSideOf(direction),
    filter: BLURRED,
    opacity: 0,
    transition: TURN_OUT,
  }),
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1, transition: FADE_IN },
  gone: { opacity: 0, transition: FADE_OUT },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return DRUM_VARIANTS;
}

function useDocumentVisible() {
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    const handleVisibilityChange = () => {
      setIsVisible(document.visibilityState === 'visible');
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  return isVisible;
}

function spokenTextOf(
  words: readonly string[],
  accessibleText: string | undefined
) {
  if (accessibleText !== undefined) {
    return accessibleText;
  }
  return words.join(', ');
}

export type WordRotateProps = {
  words: readonly string[];
  interval?: number;
  direction?: WordRotateDirection;
  paused?: boolean;
  pauseOnHover?: boolean;
  onIndexChange?: (index: number) => void;
  accessibleText?: string;
  className?: string;
};

export function WordRotate({
  words,
  interval = 2.5,
  direction = 'up',
  paused = false,
  pauseOnHover = true,
  onIndexChange,
  accessibleText,
  className,
}: WordRotateProps) {
  const rootRef = useRef<HTMLSpanElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isInView = useInView(rootRef);
  const isDocumentVisible = useDocumentVisible();
  const [index, setIndex] = useState(0);
  const [isHovered, setIsHovered] = useState(false);
  const count = words.length;
  const slotCount = Math.max(count, 1);
  const currentIndex = index % slotCount;
  const hasSeveralWords = count > 1;
  const isHeldByPointer = pauseOnHover && isHovered;
  const isOnScreen = isInView && isDocumentVisible;
  const isHeld = paused || isHeldByPointer;
  const isTurning = hasSeveralWords && isOnScreen && !isHeld;

  const turnToNext = useEffectEvent(() => {
    const following = currentIndex + 1;
    const next = following % count;
    setIndex(next);
    onIndexChange?.(next);
  });

  useEffect(() => {
    if (!isTurning) {
      return;
    }
    const intervalMs = interval * 1000;
    const timer = window.setInterval(() => {
      turnToNext();
    }, intervalMs);
    return () => window.clearInterval(timer);
  }, [isTurning, interval]);

  if (count === 0) {
    return null;
  }

  return (
    <span
      ref={rootRef}
      onPointerEnter={() => setIsHovered(true)}
      onPointerLeave={() => setIsHovered(false)}
      className={cn('inline-flex items-baseline', className)}
    >
      <span className='sr-only'>{spokenTextOf(words, accessibleText)}</span>
      <AnimatedSize
        as='span'
        axis='width'
        aria-hidden='true'
        contentClassName='relative [perspective:4em]'
      >
        <AnimatePresence mode='popLayout' initial={false} custom={direction}>
          <motion.span
            key={currentIndex}
            custom={direction}
            variants={variantsOf(shouldReduceMotion)}
            initial='hidden'
            animate='shown'
            exit='gone'
            className='block whitespace-nowrap'
          >
            {words[currentIndex]}
          </motion.span>
        </AnimatePresence>
      </AnimatedSize>
    </span>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

/** Imperative verbs exposed through the `ref` prop. */
export interface ArcHandle {
  /**
   * Call a charged strike down to `(x, y)` — fractions of the element, `0,0`
   * top-left. Defaults to a seeded random ground point. Calls stack: up to 3
   * charges queue up and fire in turn, each still honoring the 1.25s strike
   * cooldown. No-op while paused or under reduced motion.
   */
  strike: (x?: number, y?: number) => void;
}

export interface ArcProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Imperative handle — see {@link ArcHandle}. */
  ref?: React.Ref<ArcHandle>;
  /**
   * Ambient strikes per second. Clamped 0–0.8; on top of that a hard 1.25s
   * minimum gap between strike starts is always enforced (see the
   * photosensitivity note on the component). 0 = no ambient strikes
   * (click-only when `interactive`). @default 0.3
   */
  frequency?: number;
  /** How eagerly bolts fork into side branches, 0 (bare channel) – 1 (heavily forked). @default 0.55 */
  branchiness?: number;
  /** Jaggedness of the bolt path — midpoint-displacement amplitude multiplier, 0–2. @default 1 */
  jag?: number;
  /** Width of the outer glow stroke in CSS px. @default 26 */
  glowRadius?: number;
  /**
   * `[core, haze, background]`. Core is the white-hot channel, haze the
   * colored glow/sky wash, background the storm-sky bed.
   * @default ["#dbeafe", "#3b82f6", "#05070d"]
   */
  colors?: string[];
  /** Click/tap calls a strike down to the cursor (with a charge-up shimmer). @default true */
  interactive?: boolean;
  /** Flicker/decay tempo and ambient-cadence multiplier. Safety clamps below are absolute and unaffected. @default 1 */
  speed?: number;
  /** Overall brightness of strokes, impact glow and sky wash, 0–2. @default 1 */
  intensity?: number;
  /**
   * Photosensitivity clamp: the maximum opacity of the full-frame sky-wash
   * flash. Hard-clamped to ≤0.25 internally — no prop value can produce a
   * large-area luminance jump. @default 0.14
   */
  flashCap?: number;
  /** Freeze at the static poster frame (one forked bolt at full brightness). @default false */
  paused?: boolean;
  /**
   * Deterministic seed for bolt geometry and the strike schedule. Give each
   * instance on a page a different seed to desynchronize their storms.
   * @default 1
   */
  seed?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /**
   * Idle autoplay: after ~1.5s with no real pointer, a seeded ghost "clicks"
   * every few seconds — a charge shimmer drifting on a slow Lissajous path,
   * then a strike to it — so the click interaction shows itself in thumbnails
   * and heroes. Ghost strikes share the cooldown and pulse clamps above. Only
   * when `interactive`; never under reduced motion. @default true
   */
  idle?: boolean;
}

const DEFAULT_COLORS = ["#dbeafe", "#3b82f6", "#05070d"];

/**
 * Hard minimum gap (real seconds) between any two strike starts — ambient and
 * click strikes share it. With ≤3 brightness peaks per strike, all inside the
 * first ~0.42s, this guarantees any sliding one-second window contains at most
 * 3 peaks. Never relax this.
 */
const MIN_STRIKE_GAP = 1.25;
/** Peaks per strike never exceed 3 and are never closer than this (real seconds). */
const MIN_PEAK_SPACING = 0.13;
/** Absolute ceiling on the flashCap prop. */
const FLASH_CAP_MAX = 0.25;
/** Most charged strikes that may queue up from stacked clicks / handle calls. */
const MAX_CHARGES = 3;
/** Ghost takes over this long (ms) after the last real pointer activity. */
const GHOST_DELAY_MS = 1500;

/** Per-line-depth width and brightness falloff: main channel, branch, sub-branch. */
const LEVEL_W = [1, 0.55, 0.35];
const LEVEL_B = [1, 0.55, 0.35];

/** Module-scope mount counter → deterministic schedule desync between instances. */
let instanceCounter = 0;

/** Deterministic mulberry32 PRNG — same seed always produces the same storm. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

/** Normalize any CSS color string to [r,g,b] using a throwaway 1×1 read. */
function colorToRgb(ctx: CanvasRenderingContext2D, color: string): [number, number, number] {
  ctx.clearRect(0, 0, 1, 1);
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 1, 1);
  const d = ctx.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}

/** Fast attack (~30ms) then exponential decay — one flicker peak of a strike. */
function pulseShape(u: number, tau: number): number {
  if (u <= 0) return 0;
  const rise = 0.03;
  if (u < rise) return u / rise;
  return Math.exp(-(u - rise) / tau);
}

interface Pulse {
  t: number; // seconds after strike start
  amp: number;
}

interface Polyline {
  pts: number[]; // [x0,y0,x1,y1,...] device px
  level: number; // 0 main channel, 1 branch, 2 sub-branch
}

interface Strike {
  lines: Polyline[];
  pulses: Pulse[];
  start: number;
  end: number;
  originX: number;
  targetX: number;
  targetY: number;
}

interface Charge {
  x: number;
  y: number;
  start: number;
  fireAt: number;
  /** Queued by the idle ghost — dropped the moment a real click arrives. */
  ghost?: boolean;
}

interface Knobs {
  speed: number;
  intensity: number;
  frequency: number;
  jag: number;
  branchiness: number;
  glowRadius: number;
  flashCap: number;
}

interface Internals {
  ctx: CanvasRenderingContext2D;
  w: number;
  h: number;
  scale: number;
  seed: number;
  bed: HTMLCanvasElement; // storm sky: bg + cloud glow, the fade target
  wash: HTMLCanvasElement; // big soft haze sprite for the sky flash
  spark: HTMLCanvasElement; // hot core sprite for impact / charge shimmer
  coreStyle: string;
  hazeStyle: string;
  strikes: Strike[];
  /** Pending charged strikes, oldest first (stacked clicks queue up). */
  charges: Charge[];
  rand: () => number;
  /** Separate seeded stream for the ghost so it never perturbs the storm. */
  ghostRand: () => number;
  nextGhost: number;
  nextStrike: number;
  lastStrikeStart: number;
  fadeUntil: number; // afterimage still decaying until this time
  last: number;
  now: number;
}

/** Recursive midpoint displacement: jagged polyline from (x1,y1) to (x2,y2). */
function displacedPath(
  rand: () => number,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  jag: number
): number[] {
  const pts: number[] = [x1, y1];
  const len = Math.hypot(x2 - x1, y2 - y1) || 1;
  const gens = clamp(Math.round(Math.log2(len / 10)), 3, 7);
  const sub = (ax: number, ay: number, bx: number, by: number, disp: number, gen: number) => {
    if (gen === 0) {
      pts.push(bx, by);
      return;
    }
    const dx = bx - ax;
    const dy = by - ay;
    const l = Math.hypot(dx, dy) || 1;
    const off = (rand() * 2 - 1) * disp;
    const mx = (ax + bx) / 2 + (-dy / l) * off;
    const my = (ay + by) / 2 + (dx / l) * off;
    sub(ax, ay, mx, my, disp * 0.52, gen - 1);
    sub(mx, my, bx, by, disp * 0.52, gen - 1);
  };
  sub(x1, y1, x2, y2, len * 0.16 * jag, gens);
  return pts;
}

/** Grow branches off a parent polyline (recursing at most to sub-branches). */
function addBranches(
  rand: () => number,
  parent: number[],
  level: number,
  jag: number,
  branchiness: number,
  groundY: number,
  scale: number,
  lines: Polyline[]
): void {
  if (level > 2 || branchiness <= 0) return;
  const n = parent.length / 2;
  if (n < 6) return;
  const maxB = level === 1 ? Math.round(1 + branchiness * 5) : 1;
  const lo = Math.max(1, Math.floor(n * 0.15));
  const hi = Math.min(n - 2, Math.floor(n * 0.85));
  let made = 0;
  for (let i = lo; i < hi && made < maxB; i += 2) {
    if (rand() > branchiness * 0.3) continue;
    const bx = parent[i * 2];
    const by = parent[i * 2 + 1];
    // Local travel direction, rotated off to a side.
    const dx = parent[(i + 1) * 2] - parent[(i - 1) * 2];
    const dy = parent[(i + 1) * 2 + 1] - parent[(i - 1) * 2 + 1];
    const dl = Math.hypot(dx, dy) || 1;
    const angle = (rand() < 0.5 ? -1 : 1) * (0.35 + rand() * 0.55);
    const ca = Math.cos(angle);
    const sa = Math.sin(angle);
    const ux = (dx * ca - dy * sa) / dl;
    const uy = (dx * sa + dy * ca) / dl;
    const room = Math.max(groundY - by, 40 * scale);
    const len = Math.max(30 * scale, room * (0.2 + rand() * 0.28) * (level === 1 ? 1 : 0.55));
    const path = displacedPath(rand, bx, by, bx + ux * len, by + uy * len, jag * 1.15);
    lines.push({ pts: path, level });
    addBranches(rand, path, level + 1, jag, branchiness, groundY, scale, lines);
    made++;
  }
}

function buildBoltLines(
  rand: () => number,
  ox: number,
  oy: number,
  tx: number,
  ty: number,
  jag: number,
  branchiness: number,
  groundY: number,
  scale: number
): Polyline[] {
  const lines: Polyline[] = [];
  const main = displacedPath(rand, ox, oy, tx, ty, jag);
  lines.push({ pts: main, level: 0 });
  addBranches(rand, main, 1, jag, branchiness, groundY, scale, lines);
  return lines;
}

/**
 * 1–3 flicker peaks. Spacing is hard-floored at MIN_PEAK_SPACING in *real*
 * seconds (never scaled by speed) and the last peak lands ≤ ~0.42s in.
 */
function buildPulses(rand: () => number): Pulse[] {
  const pulses: Pulse[] = [{ t: 0, amp: 1 }];
  if (rand() < 0.85) {
    pulses.push({ t: MIN_PEAK_SPACING + rand() * 0.07, amp: 0.5 + rand() * 0.15 });
    if (rand() < 0.5) {
      pulses.push({
        t: pulses[1].t + MIN_PEAK_SPACING + rand() * 0.09,
        amp: 0.28 + rand() * 0.12,
      });
    }
  }
  return pulses;
}

function spawnStrike(
  it: Internals,
  k: Knobs,
  ox: number,
  tx: number,
  ty: number,
  now: number
): void {
  const lines = buildBoltLines(
    it.rand,
    ox,
    -8 * it.scale,
    tx,
    ty,
    clamp(k.jag, 0, 2),
    clamp(k.branchiness, 0, 1),
    it.h,
    it.scale
  );
  const pulses = buildPulses(it.rand);
  const end = now + pulses[pulses.length - 1].t + 0.55;
  it.strikes.push({ lines, pulses, start: now, end, originX: ox, targetX: tx, targetY: ty });
  it.lastStrikeStart = now;
  it.fadeUntil = Math.max(it.fadeUntil, end + 1.6);
}

function scheduleNext(it: Internals, k: Knobs, now: number): void {
  const f = clamp(k.frequency, 0, 0.8) * clamp(k.speed, 0.25, 3);
  if (f <= 0.001) {
    it.nextStrike = Infinity;
    return;
  }
  const interval = (1 / f) * (0.6 + it.rand() * 0.9);
  it.nextStrike = now + Math.max(MIN_STRIKE_GAP, interval);
}

/** Soft radial sprite: `core` = hot center profile, otherwise a wide haze. */
function makeSprite(rgb: [number, number, number], core: boolean): HTMLCanvasElement {
  const D = 128;
  const c = document.createElement("canvas");
  c.width = D;
  c.height = D;
  const g = c.getContext("2d")!;
  const [r, gg, b] = rgb;
  const grad = g.createRadialGradient(D / 2, D / 2, 0, D / 2, D / 2, D / 2);
  if (core) {
    grad.addColorStop(0, `rgba(${r},${gg},${b},1)`);
    grad.addColorStop(0.25, `rgba(${r},${gg},${b},0.5)`);
    grad.addColorStop(1, `rgba(${r},${gg},${b},0)`);
  } else {
    grad.addColorStop(0, `rgba(${r},${gg},${b},0.55)`);
    grad.addColorStop(0.5, `rgba(${r},${gg},${b},0.16)`);
    grad.addColorStop(1, `rgba(${r},${gg},${b},0)`);
  }
  g.fillStyle = grad;
  g.fillRect(0, 0, D, D);
  return c;
}

/** Storm-sky bed: near-black bg + faint uneven cloud glow along the top edge. */
function makeBed(
  w: number,
  h: number,
  bg: [number, number, number],
  haze: [number, number, number],
  seed: number
): HTMLCanvasElement {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const g = c.getContext("2d")!;
  g.fillStyle = `rgb(${bg[0]},${bg[1]},${bg[2]})`;
  g.fillRect(0, 0, w, h);
  const [hr, hg, hb] = haze;
  const band = g.createLinearGradient(0, 0, 0, h * 0.32);
  band.addColorStop(0, `rgba(${hr},${hg},${hb},0.08)`);
  band.addColorStop(1, `rgba(${hr},${hg},${hb},0)`);
  g.fillStyle = band;
  g.fillRect(0, 0, w, h * 0.32);
  // Two seeded cloud blobs so the glow reads as weather, not a gradient.
  const rand = mulberry32(seed ^ 0xc1a0d5ed);
  for (let i = 0; i < 2; i++) {
    const cx = w * (0.15 + rand() * 0.7);
    const R = w * (0.16 + rand() * 0.14);
    const blob = g.createRadialGradient(cx, 0, 0, cx, 0, R);
    blob.addColorStop(0, `rgba(${hr},${hg},${hb},0.06)`);
    blob.addColorStop(1, `rgba(${hr},${hg},${hb},0)`);
    g.fillStyle = blob;
    g.fillRect(cx - R, 0, R * 2, R);
  }
  return c;
}

function tracePath(ctx: CanvasRenderingContext2D, pts: number[]): void {
  ctx.beginPath();
  ctx.moveTo(pts[0], pts[1]);
  for (let i = 2; i < pts.length; i += 2) ctx.lineTo(pts[i], pts[i + 1]);
}

/**
 * Draw one bolt: sky wash (flashCap-clamped) + impact glow + layered strokes
 * (wide low-alpha glow → medium haze → thin white-hot core), all additive.
 */
function drawBolt(
  it: Internals,
  k: Knobs,
  lines: Polyline[],
  eMain: number,
  eBranch: number,
  originX: number,
  targetX: number,
  targetY: number
): void {
  const { ctx } = it;
  const intensity = clamp(k.intensity, 0, 2);
  const flashCap = clamp(k.flashCap, 0, FLASH_CAP_MAX);
  ctx.globalCompositeOperation = "lighter";

  // Full-frame component of the flash — the ONLY large-area luminance change,
  // hard-clamped by flashCap.
  const washA = Math.min(eMain * 0.5 * intensity, flashCap);
  if (washA > 0.003) {
    const W = it.w * 1.15;
    ctx.globalAlpha = washA;
    ctx.drawImage(it.wash, originX - W / 2, -W * 0.62, W, W);
  }

  // Small impact glow where the bolt meets the ground point.
  const impactA = Math.min(1, eMain * 0.55 * intensity);
  if (impactA > 0.01) {
    const S = 90 * it.scale;
    ctx.globalAlpha = impactA;
    ctx.drawImage(it.spark, targetX - S / 2, targetY - S / 2, S, S);
  }

  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const glowW = Math.max(2, k.glowRadius) * it.scale;
  const passes: { color: string; width: number; alpha: number }[] = [
    { color: it.hazeStyle, width: glowW, alpha: 0.1 },
    { color: it.hazeStyle, width: 3.2 * it.scale, alpha: 0.35 },
    { color: it.coreStyle, width: Math.max(1, 1.15 * it.scale), alpha: 0.95 },
  ];
  for (const line of lines) {
    const e = line.level === 0 ? eMain : eBranch * LEVEL_B[line.level];
    if (e < 0.01) continue;
    tracePath(ctx, line.pts);
    for (const p of passes) {
      ctx.globalAlpha = Math.min(1, p.alpha * e * intensity);
      ctx.strokeStyle = p.color;
      ctx.lineWidth = p.width * LEVEL_W[line.level];
      ctx.stroke();
    }
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
}

/**
 * Poster frame for reduced motion / paused: the sky bed plus one seeded,
 * well-forked bolt frozen at full brightness with its glow — no flashing.
 */
function drawStatic(it: Internals, k: Knobs): void {
  const { ctx } = it;
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
  ctx.drawImage(it.bed, 0, 0);
  const rand = mulberry32(it.seed ^ 0x51ab7e11);
  const ox = it.w * (0.3 + rand() * 0.4);
  const tx = clamp(ox + (rand() - 0.5) * it.w * 0.36, it.w * 0.08, it.w * 0.92);
  const lines = buildBoltLines(
    rand,
    ox,
    -8 * it.scale,
    tx,
    it.h * 0.97,
    clamp(k.jag, 0, 2),
    Math.max(0.6, clamp(k.branchiness, 0, 1)), // poster is always visibly forked
    it.h,
    it.scale
  );
  drawBolt(it, k, lines, 1, 0.9, ox, tx, it.h * 0.97);
}

/** One animated frame. Idle-silent: early-exits without touching the canvas between strikes. */
function stepFrame(it: Internals, k: Knobs, now: number, dt: number, ghost: boolean): void {
  // Idle ghost: a seeded "click" on a slow Lissajous path, queued exactly
  // like a real one so it inherits every photosensitivity clamp.
  if (ghost && it.charges.length === 0 && now >= it.nextGhost) {
    const fx = 0.5 + 0.36 * Math.sin(now * 0.23) * Math.cos(now * 0.071);
    const fy = 0.66 + 0.2 * Math.sin(now * 0.17 + 1.3);
    queueCharge(it, fx * it.w, fy * it.h, true);
    it.nextGhost = now + 4.2 + it.ghostRand() * 3;
  }
  // Ambient schedule (a pending click charge takes priority over ambient).
  if (it.charges.length === 0 && now >= it.nextStrike && now - it.lastStrikeStart >= MIN_STRIKE_GAP) {
    const tx = it.w * (0.08 + it.rand() * 0.84);
    const ty = it.h * (0.86 + it.rand() * 0.14);
    const ox = clamp(tx + (it.rand() - 0.5) * it.w * 0.5, it.w * 0.04, it.w * 0.96);
    spawnStrike(it, k, ox, tx, ty, now);
    scheduleNext(it, k, now);
  }
  // Fire a charged click strike once its cooldown-respecting moment arrives.
  const head = it.charges[0];
  if (head && now >= head.fireAt && now - it.lastStrikeStart >= MIN_STRIKE_GAP) {
    const c = head;
    it.charges.shift();
    const ox = clamp(c.x + (it.rand() - 0.5) * it.w * 0.4, it.w * 0.04, it.w * 0.96);
    spawnStrike(it, k, ox, c.x, c.y, now);
    it.nextStrike = Math.max(it.nextStrike, now + MIN_STRIKE_GAP);
  }
  if (it.strikes.length) it.strikes = it.strikes.filter(s => now < s.end);

  const busy = it.strikes.length > 0 || it.charges.length > 0 || now < it.fadeUntil;
  if (!busy) return; // idle-silent between strikes

  // Afterimage persistence: fade toward the storm bed instead of clearing.
  const { ctx } = it;
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1 - Math.exp(-dt / 0.22);
  ctx.drawImage(it.bed, 0, 0);
  ctx.globalAlpha = 1;

  const tau = 0.08 / clamp(k.speed, 0.4, 2.5);
  for (const s of it.strikes) {
    const t = now - s.start;
    let eMain = 0;
    for (const p of s.pulses) eMain = Math.max(eMain, p.amp * pulseShape(t - p.t, tau));
    // Branches light up on the first stroke only (like real return strokes).
    const eBranch = pulseShape(t, tau);
    if (eMain < 0.004) continue;
    drawBolt(it, k, s.lines, eMain, eBranch, s.originX, s.targetX, s.targetY);
  }

  // Charge-up shimmer at each pending click target: a small, smooth ~2.4Hz swell.
  for (const c of it.charges) {
    const cs = Math.max(0, now - c.start);
    const ramp = Math.min(1, cs / 0.12);
    const pulse = 0.72 + 0.28 * Math.sin(cs * Math.PI * 2 * 2.4);
    const a = Math.min(1, 0.5 * ramp * pulse * clamp(k.intensity, 0, 2));
    const S = (30 + 6 * Math.sin(cs * Math.PI * 2 * 1.1)) * it.scale;
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = a;
    ctx.drawImage(it.spark, c.x - S / 2, c.y - S / 2, S, S);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
  }
}

/**
 * Queue a charged strike at device-px `(x, y)`. Stacked calls line up behind
 * each other, each a full cooldown after the previous one — so stacking can
 * never beat the strike-gap clamp. Capped at MAX_CHARGES.
 */
function queueCharge(it: Internals, x: number, y: number, ghost = false): void {
  if (it.charges.length >= MAX_CHARGES) return;
  const prev = it.charges[it.charges.length - 1];
  const fireAt = Math.max(
    it.now + 0.28,
    it.lastStrikeStart + MIN_STRIKE_GAP,
    prev ? prev.fireAt + MIN_STRIKE_GAP : -Infinity
  );
  it.charges.push({ x, y, start: it.now, fireAt, ghost });
  it.fadeUntil = Math.max(it.fadeUntil, fireAt + 2);
}

/**
 * Arc — an electric-storm background. Seeded midpoint-displacement lightning
 * bolts fork down from a faint cloud glow toward random ground points, drawn
 * as layered strokes (wide low-alpha glow → colored haze → 1px white-hot core)
 * with flicker re-strikes and afterimage persistence via destination fade.
 * Click/tap calls a strike to the cursor after a charge-up shimmer.
 *
 * **Photosensitivity-safe by design** (unlike the strobing effects this genre
 * is known for): each strike is a shaped pulse train of at most 3 brightness
 * peaks spaced ≥130ms apart, strike starts are hard-clamped ≥1.25s apart
 * (ambient and click strikes share the cooldown) so any one-second window
 * contains at most 3 peaks — within WCAG 2.3.1's three-flashes threshold —
 * and the only full-frame luminance component (the sky wash) is opacity-capped
 * by `flashCap` (hard ceiling 0.25). `speed` and `frequency` cannot defeat
 * these clamps. Reduced motion shows a static poster bolt with no flashing.
 *
 * Canvas 2D; idle-silent between strikes (frames early-exit without drawing);
 * pauses offscreen and on hidden tabs; fully seeded (deterministic, SSR-safe);
 * tears down observers and listeners on unmount.
 */
export function Arc({
  frequency = 0.3,
  branchiness = 0.55,
  jag = 1,
  glowRadius = 26,
  colors = DEFAULT_COLORS,
  interactive = true,
  speed = 1,
  intensity = 1,
  flashCap = 0.14,
  paused = false,
  seed = 1,
  dpr = 2,
  idle = true,
  ref,
  className,
  style,
  ...props
}: ArcProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();
  const frozen = paused || reducedMotion;
  const colorsKey = colors.join(",");

  const knobsRef = React.useRef<Knobs>({
    speed,
    intensity,
    frequency,
    jag,
    branchiness,
    glowRadius,
    flashCap,
  });
  knobsRef.current = { speed, intensity, frequency, jag, branchiness, glowRadius, flashCap };
  // Ghost clicks demo the click interaction, so they only run when it exists.
  const ghostOnRef = React.useRef(idle && interactive);
  ghostOnRef.current = idle && interactive;
  // performance.now() of the last real pointer activity; -Infinity = never.
  const lastRealPointerRef = React.useRef(-Infinity);
  // A parked cursor still counts as present — the ghost never clicks under it.
  const insideRef = React.useRef(false);

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it) return;
    // Re-seat if the loop clock ever restarts below our last sample.
    if (elapsed < it.last) it.last = elapsed;
    const dt = Math.min(elapsed - it.last, 0.05);
    it.last = elapsed;
    it.now = elapsed;
    if (dt <= 0) return;
    const ghost =
      ghostOnRef.current &&
      !insideRef.current &&
      performance.now() - lastRealPointerRef.current > GHOST_DELAY_MS;
    stepFrame(it, knobsRef.current, elapsed, dt, ghost);
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: frozen });

  // Mount-once canvas setup; rebuild bed/sprites on size / palette / seed change.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;

    const scale = clamp(
      Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, dpr),
      1,
      2
    );
    const palette = colors.length >= 2 ? colors : DEFAULT_COLORS;
    const coreRgb = colorToRgb(ctx, palette[0] ?? DEFAULT_COLORS[0]);
    const hazeRgb = colorToRgb(ctx, palette[1] ?? DEFAULT_COLORS[1]);
    const bgRgb = colorToRgb(ctx, palette[2] ?? DEFAULT_COLORS[2]);
    const wash = makeSprite(hazeRgb, false);
    const spark = makeSprite(coreRgb, true);
    const inst = instanceCounter++;

    const build = () => {
      const w = Math.max(1, Math.round(container.clientWidth * scale));
      const h = Math.max(1, Math.round(container.clientHeight * scale));
      canvas.width = w;
      canvas.height = h;
      const prev = internalsRef.current;
      const rand = mulberry32(seed);
      const it: Internals = {
        ctx,
        w,
        h,
        scale,
        seed,
        bed: makeBed(w, h, bgRgb, hazeRgb, seed),
        wash,
        spark,
        coreStyle: `rgb(${coreRgb[0]},${coreRgb[1]},${coreRgb[2]})`,
        hazeStyle: `rgb(${hazeRgb[0]},${hazeRgb[1]},${hazeRgb[2]})`,
        strikes: [],
        charges: [],
        rand,
        ghostRand: prev?.ghostRand ?? mulberry32(seed ^ 0x9e3779b9),
        // First ghost click lands soon so thumbnails show the interaction.
        nextGhost: prev?.nextGhost ?? 2.2 + (inst % 3) * 0.7,
        // Carry the clock/schedule across resizes; stagger fresh instances so
        // multiple storms on one page desynchronize deterministically.
        nextStrike: prev
          ? Math.max(prev.nextStrike, prev.now + 0.4)
          : 0.35 + rand() * 0.9 + (inst % 4) * 0.6,
        lastStrikeStart: prev?.lastStrikeStart ?? -MIN_STRIKE_GAP,
        fadeUntil: prev?.fadeUntil ?? 0,
        last: prev?.last ?? 0,
        now: prev?.now ?? 0,
      };
      internalsRef.current = it;
      // Paint immediately so mount/resize never flashes empty.
      if (frozen) drawStatic(it, knobsRef.current);
      else {
        ctx.globalAlpha = 1;
        ctx.drawImage(it.bed, 0, 0);
      }
    };

    const ro = new ResizeObserver(build);
    ro.observe(container);
    build();

    return () => {
      ro.disconnect();
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seed, colorsKey, dpr]);

  // Freeze/unfreeze: draw the poster when frozen (and on poster-affecting prop
  // tweaks); on unfreeze let the poster decay like an afterimage.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it) return;
    if (frozen) drawStatic(it, knobsRef.current);
    else it.fadeUntil = Math.max(it.fadeUntil, it.now + 2);
  }, [frozen, jag, branchiness, glowRadius, intensity, flashCap]);

  // Click/tap → charge shimmer → strike to the cursor.
  React.useEffect(() => {
    const el = containerRef.current;
    if (!el || !interactive || frozen) return;
    const onPointerDown = (e: PointerEvent) => {
      const it = internalsRef.current;
      if (!it) return;
      lastRealPointerRef.current = performance.now();
      const rect = el.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / Math.max(rect.width, 1)) * it.w;
      const y = ((e.clientY - rect.top) / Math.max(rect.height, 1)) * it.h;
      // The real pointer takes over: drop any pending ghost charge. Clicks
      // stack: each queues behind the last, the shimmer stretching to honor
      // the global strike cooldown.
      it.charges = it.charges.filter((c) => !c.ghost);
      queueCharge(it, x, y);
    };
    // Any real pointer presence holds the ghost off.
    const onPointerMove = () => {
      insideRef.current = true;
      lastRealPointerRef.current = performance.now();
    };
    const onPointerLeave = () => {
      insideRef.current = false;
      lastRealPointerRef.current = performance.now();
    };
    el.addEventListener("pointerdown", onPointerDown);
    el.addEventListener("pointermove", onPointerMove);
    el.addEventListener("pointerleave", onPointerLeave);
    return () => {
      el.removeEventListener("pointerdown", onPointerDown);
      el.removeEventListener("pointermove", onPointerMove);
      el.removeEventListener("pointerleave", onPointerLeave);
    };
  }, [interactive, frozen, containerRef]);

  React.useImperativeHandle(
    ref,
    () => ({
      strike: (x?: number, y?: number) => {
        const it = internalsRef.current;
        if (!it || frozen) return;
        const fx = x ?? 0.12 + it.ghostRand() * 0.76;
        const fy = y ?? 0.86 + it.ghostRand() * 0.12;
        queueCharge(it, clamp(fx, 0, 1) * it.w, clamp(fy, 0, 1) * it.h);
      },
    }),
    [frozen]
  );

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="arc"
      className={cn("absolute inset-0 -z-10 overflow-hidden", className)}
      style={style}
      {...props}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface ArcadeProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Star / grid / sprite palette, brightest → deepest. Index `0` is the near
   * (foreground) star + sprite tint, `1` the mid layer + floor grid, `2` the
   * far layer. Extra entries recolor the drifting sprites. Defaults to a cool
   * cyan-to-indigo starfield on near-black — pass warm tones for a synthwave
   * cabinet or all-white for classic mono.
   * @default ["#eaf6ff", "#7fdfff", "#4aa6ff"]
   */
  colors?: string[];
  /** Drift / flap / floor-scroll speed multiplier. 1 = default. @default 1 */
  speed?: number;
  /** Overall star brightness and grid/sprite opacity, 0–2. @default 1 */
  intensity?: number;
  /** Star-count multiplier across all layers, 0.2–3. @default 1 */
  density?: number;
  /** Chunk size of one "pixel" in CSS px — the whole scene snaps to it. Clamped 2–8. @default 3 */
  pixelSize?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /** Freeze the scene at a static, populated attract-mode frame. @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: string[] = ["#eaf6ff", "#7fdfff", "#4aa6ff"];

/** Deterministic mulberry32 — seeded so the field is identical SSR intent ↔ CSR. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SEED = 0x51ed270b;

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [234, 246, 255];
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

/**
 * 8-bit sprite bitmaps — two flap frames each. `#` = a filled pixel-block.
 * Clean-room classic space-shooter silhouettes (crab + octopus invaders).
 */
const SPRITES: { w: number; h: number; frames: string[][] }[] = [
  {
    w: 11,
    h: 8,
    frames: [
      [
        "..#.....#..",
        "...#...#...",
        "..#######..",
        ".##.###.##.",
        "###########",
        "#.#######.#",
        "#.#.....#.#",
        "...##.##...",
      ],
      [
        "..#.....#..",
        "#..#...#..#",
        "#.#######.#",
        "###.###.###",
        "###########",
        ".#########.",
        "..#.....#..",
        ".#.......#.",
      ],
    ],
  },
  {
    w: 12,
    h: 8,
    frames: [
      [
        "....####....",
        ".##########.",
        "############",
        "###..##..###",
        "############",
        "...##..##...",
        "..##.##.##..",
        "##........##",
      ],
      [
        "....####....",
        ".##########.",
        "############",
        "###..##..###",
        "############",
        "..###..###..",
        ".##..##..##.",
        "..##....##..",
      ],
    ],
  },
];

const NLINES = 16; // floor rows
const NVERT = 18; // floor verticals

interface Star {
  x: number; // CSS px
  y: number;
  layer: 0 | 1 | 2; // 0 near, 1 mid, 2 far
  vy: number; // CSS px/s drift
  baseAlpha: number;
  colorIdx: number;
  twPhase: number;
  twFreq: number;
}

interface Sprite {
  x: number; // CSS px (top-left)
  y: number;
  dir: 1 | -1;
  vx: number; // CSS px/s
  type: number; // SPRITES index
  colorIdx: number;
  flapPhase: number;
  flapRate: number; // toggles/sec
}

interface Internals {
  ctx: CanvasRenderingContext2D;
  width: number;
  height: number;
  P: number; // pixel-block size, CSS px
  palette: [number, number, number][];
  stars: Star[];
  sprites: Sprite[];
  gridOffset: number;
  intensity: number;
  speed: number;
  rng: () => number;
  bg: string;
}

function buildStars(w: number, h: number, P: number, density: number): Star[] {
  const rng = mulberry32(SEED ^ 0x1b56c4e9);
  const area = w * h;
  const farCount = Math.min(360, Math.max(12, Math.round((area / 2600) * density)));
  const midCount = Math.round(farCount * 0.5);
  const nearCount = Math.round(farCount * 0.16);
  const stars: Star[] = [];

  const push = (layer: 0 | 1 | 2, n: number) => {
    for (let i = 0; i < n; i++) {
      const near = layer === 0;
      const mid = layer === 1;
      stars.push({
        x: rng() * w,
        y: rng() * h,
        layer,
        vy: (near ? 34 : mid ? 18 : 8) * (0.75 + rng() * 0.5),
        baseAlpha: near ? 0.85 : mid ? 0.6 : 0.32,
        colorIdx: layer, // near→0, mid→1, far→2
        twPhase: rng() * Math.PI * 2,
        twFreq: near ? 2.2 + rng() * 2.4 : mid ? 1.2 + rng() * 1.6 : 0,
      });
    }
  };
  push(2, farCount);
  push(1, midCount);
  push(0, nearCount);
  return stars;
}

function buildSprites(w: number, h: number, paletteLen: number): Sprite[] {
  const rng = mulberry32(SEED ^ 0x27d4eb2f);
  const out: Sprite[] = [];
  const band = Math.max(h * 0.12, 40);
  for (let i = 0; i < 3; i++) {
    const dir: 1 | -1 = rng() < 0.5 ? 1 : -1;
    out.push({
      // Seeded across the frame so the static / first frame already shows craft.
      x: rng() * w,
      y: band + rng() * (h * 0.42),
      dir,
      vx: (22 + rng() * 20) * (0.85 + rng() * 0.4),
      type: (rng() * SPRITES.length) | 0,
      colorIdx: (rng() * paletteLen) | 0,
      flapPhase: rng() * 10,
      flapRate: 1.4 + rng() * 0.9,
    });
  }
  return out;
}

function recycleSprite(s: Sprite, it: Internals) {
  const rng = it.rng;
  const spr = SPRITES[s.type];
  const wpx = spr.w * it.P * 2;
  s.dir = rng() < 0.5 ? 1 : -1;
  s.type = (rng() * SPRITES.length) | 0;
  s.colorIdx = (rng() * it.palette.length) | 0;
  s.vx = (22 + rng() * 20) * (0.85 + rng() * 0.4);
  s.y = Math.max(it.height * 0.12, 40) + rng() * (it.height * 0.42);
  s.flapRate = 1.4 + rng() * 0.9;
  // Enter from the side it travels toward, with a seeded gap so appearances
  // are occasional rather than a constant conveyor.
  const gap = wpx + rng() * (it.width * 0.9 + wpx);
  s.x = s.dir === 1 ? -gap : it.width + gap;
}

function drawBlock(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  size: number,
  rgb: [number, number, number],
  alpha: number
) {
  if (alpha <= 0.01) return;
  ctx.fillStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha < 1 ? alpha : 1})`;
  ctx.fillRect(Math.round(x), Math.round(y), size, size);
}

/** Perspective pixel-grid floor: rows compress toward a horizon, verticals fan from a vanishing point. */
function drawGrid(it: Internals, offset: number) {
  const { ctx, width, height, P } = it;
  const hY = Math.round(height * 0.66);
  const H = height - hY;
  if (H <= 4) return;
  const cx = width / 2;
  const rgb = it.palette[Math.min(1, it.palette.length - 1)];
  const thick = Math.max(1, Math.round(P * 0.6));
  const dot = P;
  const gAmt = Math.min(Math.max(it.intensity, 0), 2);

  for (let k = 0; k < NLINES; k++) {
    let p = ((k + offset) % NLINES) / NLINES;
    if (p < 0) p += 1;
    const persp = p * p; // near horizon → 0, bottom → 1
    const sy = hY + H * persp;
    const fade = (0.12 + 0.88 * p) * gAmt;
    // Floor row — a thin chunky full-width scan line.
    ctx.fillStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.06 * fade})`;
    ctx.fillRect(0, Math.round(sy), width, thick);
    // Vertical intersections — dots converging on the vanishing point.
    for (let v = 0; v <= NVERT; v++) {
      const bx = (v / NVERT) * width * 2 - width * 0.5;
      const x = cx + (bx - cx) * persp;
      if (x < -dot || x > width + dot) continue;
      drawBlock(ctx, x, sy, dot, rgb, 0.16 * fade);
    }
  }
}

function drawSprite(it: Internals, s: Sprite, frame: number) {
  const spr = SPRITES[s.type];
  const rows = spr.frames[frame % spr.frames.length];
  const block = it.P * 2;
  const rgb = it.palette[s.colorIdx % it.palette.length];
  const alpha = Math.min(0.85 * it.intensity, 1);
  const x0 = Math.round(s.x / it.P) * it.P;
  const y0 = Math.round(s.y / it.P) * it.P;
  it.ctx.fillStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    for (let c = 0; c < row.length; c++) {
      if (row[c] === "#") {
        it.ctx.fillRect(x0 + c * block, y0 + r * block, block, block);
      }
    }
  }
}

/** One frame. `t` is elapsed seconds (phases); `useStatic` freezes drift, flap and scroll. */
function draw(it: Internals, dt: number, t: number, useStatic: boolean) {
  const { ctx, width, height, P } = it;

  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = it.bg;
  ctx.fillRect(0, 0, width, height);

  // ------------------------------------------------------------------ floor --
  if (!useStatic) it.gridOffset += dt * it.speed * 1.1;
  drawGrid(it, useStatic ? 0 : it.gridOffset);

  // ------------------------------------------------------------------ stars --
  for (let i = 0; i < it.stars.length; i++) {
    const s = it.stars[i];
    if (!useStatic) {
      s.y += s.vy * it.speed * dt;
      if (s.y > height + P) s.y -= height + P * 2;
    }
    const rgb = it.palette[s.colorIdx % it.palette.length];
    const tw =
      s.twFreq && !useStatic ? 0.55 + 0.45 * Math.sin(s.twPhase + t * s.twFreq) : 0.9;
    const alpha = Math.min(s.baseAlpha * tw * it.intensity, 1);
    const x = Math.round(s.x / P) * P;
    const y = Math.round(s.y / P) * P;
    if (s.layer === 0) {
      // Near stars are a bright pixel-cross (classic twinkle sprite).
      drawBlock(ctx, x, y, P, rgb, alpha);
      drawBlock(ctx, x - P, y, P, rgb, alpha * 0.7);
      drawBlock(ctx, x + P, y, P, rgb, alpha * 0.7);
      drawBlock(ctx, x, y - P, P, rgb, alpha * 0.7);
      drawBlock(ctx, x, y + P, P, rgb, alpha * 0.7);
    } else {
      drawBlock(ctx, x, y, P, rgb, alpha);
    }
  }

  // ---------------------------------------------------------------- sprites --
  for (let i = 0; i < it.sprites.length; i++) {
    const s = it.sprites[i];
    const spr = SPRITES[s.type];
    if (!useStatic) {
      s.x += s.vx * s.dir * it.speed * dt;
      const wpx = spr.w * it.P * 2;
      if (s.dir === 1 && s.x > width + wpx) recycleSprite(s, it);
      else if (s.dir === -1 && s.x < -wpx) recycleSprite(s, it);
    }
    const frame = useStatic ? 0 : Math.floor(s.flapPhase + t * s.flapRate) % 2;
    drawSprite(it, s, frame);
  }
}

/** Cool near-black bed derived from the far-star hue — never flat #000. */
function baseFill(far: [number, number, number]): string {
  return `rgb(${(4 + far[0] * 0.01) | 0}, ${(6 + far[1] * 0.012) | 0}, ${(10 + far[2] * 0.018) | 0})`;
}

/**
 * Arcade — an 8-bit attract-mode background. A chunky pixel starfield drifts on
 * three parallax depth layers (bright near cross-stars, mid and far dots),
 * seeded space-shooter sprites glide across on a two-frame flap, and a faint
 * pixel grid recedes to a horizon like a cabinet's demo screen. Crisp,
 * unsmoothed pixels snapped to a block grid. Canvas 2D: seeded and SSR-safe,
 * paused offscreen and on hidden tabs, reduced-motion-safe (a static, fully
 * populated frame — no drift). Drop it inside any `relative` container.
 */
export function Arcade({
  colors = DEFAULT_COLORS,
  speed = 1,
  intensity = 1,
  density = 1,
  pixelSize = 3,
  dpr = 2,
  paused = false,
  className,
  ...props
}: ArcadeProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();
  const staticFrame = paused || reducedMotion;
  const staticFrameRef = React.useRef(staticFrame);
  staticFrameRef.current = staticFrame;
  const lastElapsedRef = React.useRef(0);

  const P = Math.round(Math.min(Math.max(pixelSize, 2), 8));
  const dens = Math.min(Math.max(density, 0.2), 3);
  const colorsKey = colors.join(",");

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it) return;
    let dt = elapsed - lastElapsedRef.current;
    lastElapsedRef.current = elapsed;
    if (dt > 0.1) dt = 0.1; // clamp tab-restore jumps
    if (dt < 0) dt = 0;
    draw(it, dt, elapsed, staticFrameRef.current);
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: staticFrame });

  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;
    ctx.imageSmoothingEnabled = false;

    const effectiveDpr = Math.min(
      typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1,
      Math.min(Math.max(dpr, 1), 2)
    );

    const source = colors.length ? colors : DEFAULT_COLORS;
    const palette = source.map(hexToRgb);
    while (palette.length < 3) palette.push(palette[palette.length - 1]);

    const it: Internals = {
      ctx,
      width: 0,
      height: 0,
      P,
      palette,
      stars: [],
      sprites: [],
      gridOffset: 0,
      intensity,
      speed,
      rng: mulberry32(SEED ^ 0x85ebca6b),
      bg: baseFill(palette[Math.min(2, palette.length - 1)]),
    };
    internalsRef.current = it;

    const onContextLost = (e: Event) => e.preventDefault();
    canvas.addEventListener("contextlost", onContextLost);

    const resize = () => {
      const w = Math.max(container.clientWidth, 1);
      const h = Math.max(container.clientHeight, 1);
      canvas.width = Math.round(w * effectiveDpr);
      canvas.height = Math.round(h * effectiveDpr);
      canvas.style.width = "100%";
      canvas.style.height = "100%";
      ctx.setTransform(effectiveDpr, 0, 0, effectiveDpr, 0, 0);
      ctx.imageSmoothingEnabled = false;

      it.width = w;
      it.height = h;
      it.stars = buildStars(w, h, P, dens);
      it.sprites = buildSprites(w, h, palette.length);
      it.gridOffset = 0;

      // Never flash empty — paint one frame immediately.
      draw(it, 0, 0, staticFrameRef.current);
    };

    const ro = new ResizeObserver(resize);
    ro.observe(container);
    resize();

    return () => {
      ro.disconnect();
      canvas.removeEventListener("contextlost", onContextLost);
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dpr, P, dens, colorsKey]);

  // Live-sync speed / intensity without rebuilding (and resetting) the field.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it) return;
    it.speed = speed;
    it.intensity = intensity;
    if (staticFrameRef.current) draw(it, 0, 0, true);
  }, [speed, intensity]);

  // Re-render the frozen frame in place when paused / reduced-motion toggles.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !staticFrame) return;
    draw(it, 0, 0, true);
  }, [staticFrame]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="arcade"
      className={cn("absolute inset-0 -z-10 overflow-hidden bg-neutral-950", className)}
      {...props}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
      {/* CRT scanlines + faint vignette — sink the cabinet into the frame. */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          backgroundImage:
            "repeating-linear-gradient(0deg, rgba(0,0,0,0.32) 0px, rgba(0,0,0,0.32) 1px, transparent 1px, transparent 3px)",
          opacity: 0.5,
        }}
      />
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 120% at 50% 40%, transparent 58%, rgba(0,0,0,0.6) 100%)",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

export interface ArmatureProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Content pinned in the fixed center slot — logo, icon, avatar. */
  center?: React.ReactNode;
  /** One or more `<ArmatureRing>` elements. */
  children: React.ReactNode;
  /** Pause every ring (and its counter-rotating icons) while hovered. @default true */
  pauseOnHover?: boolean;
  /** Color of the soft light cast behind the center slot. @default "#ffffff" */
  emberColor?: string;
}

export interface ArmatureRingProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Ring radius in px. */
  radius: number;
  /** Seconds per revolution. @default 20 */
  speed?: number;
  /** Spin direction. @default "cw" */
  direction?: "cw" | "ccw";
  /** Draw a hairline guide circle with a rotating brightened arc. @default true */
  showPath?: boolean;
  /** Icons/elements distributed evenly around the ring. */
  children: React.ReactNode;
  /** Squash factor (0–1) for a slightly elliptical, off-axis orbit. @default 0 */
  eccentricity?: number;
  /** Color of the guide circle / trailing arc. @default "#ffffff" */
  color?: string;
}

const KEYFRAMES = `
@keyframes crucible-armature-spin-cw { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes crucible-armature-spin-ccw { from { transform: rotate(360deg); } to { transform: rotate(0deg); } }
@keyframes crucible-armature-counter-cw { from { transform: rotate(0deg); } to { transform: rotate(-360deg); } }
@keyframes crucible-armature-counter-ccw { from { transform: rotate(-360deg); } to { transform: rotate(0deg); } }
@keyframes crucible-armature-ember {
  0%, 100% { opacity: 0.55; transform: translate(-50%, -50%) scale(1); }
  50% { opacity: 0.85; transform: translate(-50%, -50%) scale(1.12); }
}
[data-crucible="armature"][data-paused="true"] .armature-spin {
  /* !important: the spin animation is set as an inline style whose shorthand
     implies animation-play-state:running, and inline wins over a plain rule. */
  animation-play-state: paused !important;
}
@media (prefers-reduced-motion: reduce) {
  [data-crucible="armature"] .armature-spin,
  [data-crucible="armature"] .armature-ember {
    animation: none !important;
  }
}
`;

/**
 * Armature — orbiting icon rings around a fixed center slot. Compose with
 * `<ArmatureRing>` for a multi-radius orbital system: each ring sets its own
 * radius, speed, and direction, and icons stay upright via a counter-rotation
 * so only their position orbits, not their orientation.
 *
 * Crucible signature: rings render as neutral hairline guide circles with a
 * rotating arc that brightens to white just behind the icons, a soft white
 * glow behind the center slot, and support for one ring set deliberately
 * eccentric (`eccentricity`) for a slightly elliptical orbit. Pure CSS —
 * pauses on hover and freezes orbits (and the center glow's breathing) to a
 * static, correctly-centered frame under reduced motion.
 */
export function Armature({
  center,
  children,
  pauseOnHover = true,
  emberColor = "#ffffff",
  className,
  onMouseEnter,
  onMouseLeave,
  ...props
}: ArmatureProps) {
  const [paused, setPaused] = React.useState(false);

  return (
    <div
      data-crucible="armature"
      data-paused={pauseOnHover && paused}
      className={cn("relative flex items-center justify-center", className)}
      onMouseEnter={(e) => {
        onMouseEnter?.(e);
        if (pauseOnHover) setPaused(true);
      }}
      onMouseLeave={(e) => {
        onMouseLeave?.(e);
        if (pauseOnHover) setPaused(false);
      }}
      {...props}
    >
      <style>{KEYFRAMES}</style>
      <span
        aria-hidden
        className="armature-ember pointer-events-none absolute top-1/2 left-1/2 h-24 w-24 rounded-full blur-2xl"
        style={{
          background: `radial-gradient(circle, ${emberColor}66, transparent 70%)`,
          // Resting pose (centered, mid-glow) for when the breath is disabled
          // under reduced motion; the running animation overrides both.
          transform: "translate(-50%, -50%)",
          opacity: 0.7,
          animation: "crucible-armature-ember 4s ease-in-out infinite",
        }}
      />
      {center && <div className="relative z-10 flex items-center justify-center">{center}</div>}
      {children}
    </div>
  );
}

/**
 * ArmatureRing — one orbit within an `<Armature>`. Must be a descendant of
 * `Armature` (it positions itself absolutely against the nearest positioned
 * ancestor, i.e. Armature's root).
 */
export function ArmatureRing({
  radius,
  speed = 20,
  direction = "cw",
  showPath = true,
  eccentricity = 0,
  color = "#ffffff",
  children,
  className,
  style,
  ...props
}: ArmatureRingProps) {
  const icons = React.Children.toArray(children);
  const size = radius * 2;
  const squash = 1 - Math.min(1, Math.max(0, eccentricity)) * 0.16;
  const tilt = Math.min(1, Math.max(0, eccentricity)) * 5;
  const spinAnimation = `crucible-armature-spin-${direction} ${speed}s linear infinite`;
  const counterAnimation = `crucible-armature-counter-${direction} ${speed}s linear infinite`;

  return (
    <div
      data-crucible="armature-ring"
      className={cn("pointer-events-none absolute top-1/2 left-1/2", className)}
      style={{
        width: size,
        height: size,
        transform: `translate(-50%, -50%) scale(1, ${squash}) rotate(${tilt}deg)`,
        ...style,
      }}
      {...props}
    >
      {showPath && (
        <div
          aria-hidden
          className="absolute inset-0 rounded-full"
          style={{ border: `1px solid ${color}`, opacity: 0.25 }}
        />
      )}
      {showPath && (
        <div
          aria-hidden
          className="armature-spin absolute inset-0 rounded-full"
          style={{
            background: `conic-gradient(from 0deg, transparent 0deg, transparent 290deg, ${color} 330deg, transparent 358deg)`,
            WebkitMask: "radial-gradient(farthest-side, transparent calc(100% - 2px), #000 calc(100% - 2px))",
            mask: "radial-gradient(farthest-side, transparent calc(100% - 2px), #000 calc(100% - 2px))",
            animation: spinAnimation,
          }}
        />
      )}
      <div className="armature-spin absolute inset-0" style={{ animation: spinAnimation }}>
        {icons.map((icon, i) => {
          const angle = (360 / icons.length) * i;
          return (
            <div
              key={i}
              className="absolute top-1/2 left-1/2"
              style={{ transform: `translate(-50%, -50%) rotate(${angle}deg) translate(${radius}px) rotate(-${angle}deg)` }}
            >
              <div className="armature-spin pointer-events-auto" style={{ animation: counterAnimation }}>
                {icon}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/** Built-in gas presets, or any CSS color string. */
export type ArgonGas = "neon" | "argon" | "mercury" | (string & {});

export interface ArgonHandle {
  /** Switch every tube off and run the ignition intro again. */
  replay(): void;
  /** Destabilise one glyph (by index among visible glyphs), or a seeded random one. */
  flicker(index?: number): void;
}

export interface ArgonProps extends Omit<React.HTMLAttributes<HTMLElement>, "children"> {
  /** The lettering. Use "\n" for a stacked multi-line sign. @default "Open late" */
  text?: string;
  /** Gas fill: "neon" (red-orange), "argon" (ice blue), "mercury" (cold white), or any CSS color. @default "argon" */
  gas?: ArgonGas;
  /** Element the (visually hidden) real text is rendered as, so it stays a heading. @default "h2" */
  as?: "h1" | "h2" | "h3" | "p";
  /** Glyph size in px at natural size; the sign scales down to fit its container. @default 96 */
  fontSize?: number;
  /** Lit tube stroke width in px at natural size. @default 2.4 */
  strokeWidth?: number;
  /** Render mounting clips beneath each glyph and a back-wire behind every line. @default true */
  clips?: boolean;
  /** Wait until the sign scrolls into view before igniting (otherwise ignite on mount). @default true */
  igniteOnView?: boolean;
  /** Glow strength: bloom size/opacity and interior gas fill. 0–2. @default 1 */
  intensity?: number;
  /** When no pointer has been present for ~1.5s, glyphs occasionally destabilise on their own. @default true */
  idle?: boolean;
  /** Hold the sign fully lit and steady — no intro, hum, or flicker. @default false */
  paused?: boolean;
  /** Imperative handle: `replay()` and `flicker(index?)`. */
  ref?: React.Ref<ArgonHandle>;
}

const GAS_PRESETS: Record<string, string> = {
  neon: "#ff5a3c",
  argon: "#7cc4ff",
  mercury: "#e8f1ff",
};

/** Stagger between glyph ignitions (ms). */
const STAGGER = 70;
/** Time for the ignition to travel the dash window (ms). */
const DRAW_MS = 1400;
/** Dash window, in em — longer than any glyph's outline. */
const DASH_EM = 10;
/** Photosensitivity budget: max opacity dips from hover/idle flicker in any 1s window. */
const MAX_DIPS_PER_SECOND = 3;
const FLICKER_DIPS = 2;

interface Glyph {
  char: string;
  line: number;
  /** Start x relative to the line's left edge. */
  x: number;
  /** Advance width. */
  w: number;
}

interface Layout {
  glyphs: Glyph[];
  lineWidths: number[];
  measured: boolean;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashString(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/** Deterministic pre-measure layout (SSR + first client render; hidden until measured). */
function estimateLayout(lines: string[], fontSize: number): Layout {
  const glyphs: Glyph[] = [];
  const lineWidths: number[] = [];
  const adv = fontSize * 0.6;
  lines.forEach((line, li) => {
    const chars = Array.from(line);
    chars.forEach((char, ci) => {
      if (!/\s/.test(char)) glyphs.push({ char, line: li, x: ci * adv, w: adv });
    });
    lineWidths.push(chars.length * adv);
  });
  return { glyphs, lineWidths, measured: false };
}

/** Seeded strike: 2–3 uneven partial dips inside the first ~200ms of a glyph lighting. */
function strikeKeyframes(rng: () => number): Keyframe[] {
  const dips = rng() < 0.5 ? 2 : 3;
  const total = 240;
  const frames: Keyframe[] = [{ opacity: 0, offset: 0 }];
  let t = 18 + rng() * 14;
  frames.push({ opacity: 0.85 + rng() * 0.15, offset: t / total });
  for (let d = 0; d < dips; d++) {
    t += 22 + rng() * 22;
    frames.push({ opacity: 0.2 + rng() * 0.25, offset: Math.min(t, 200) / total });
    t += 18 + rng() * 22;
    frames.push({ opacity: 0.8 + rng() * 0.2, offset: Math.min(t, 210) / total });
  }
  frames.push({ opacity: 1, offset: 1 });
  return frames;
}

/** Seeded ~400ms destabilise: exactly two partial dips, then a wobble back to steady. */
function flickerKeyframes(rng: () => number): Keyframe[] {
  return [
    { opacity: 1, offset: 0 },
    { opacity: 0.28 + rng() * 0.14, offset: 0.08 + rng() * 0.04 },
    { opacity: 0.88 + rng() * 0.1, offset: 0.2 },
    { opacity: 0.72 + rng() * 0.1, offset: 0.34 },
    { opacity: 0.38 + rng() * 0.14, offset: 0.46 + rng() * 0.04 },
    { opacity: 1, offset: 0.62 },
    { opacity: 0.9 + rng() * 0.06, offset: 0.8 },
    { opacity: 1, offset: 1 },
  ];
}

/**
 * Argon — a headline rendered as bent gas-discharge glass tubes. Each glyph
 * is an SVG text outline in three layers: a dim unlit tube, a bright lit core
 * with a white-hot center, and a blurred bloom. On view, ignition travels
 * along each tube glyph-by-glyph with an uneven strike flicker, then holds
 * with a near-imperceptible mains hum. The glyph nearest the pointer
 * destabilises briefly. Flicker is photosensitivity-budgeted (≤3 dips/s);
 * reduced motion renders the sign fully lit and steady.
 */
export function Argon({
  text = "Open late",
  gas = "argon",
  as = "h2",
  fontSize = 96,
  strokeWidth = 2.4,
  clips = true,
  igniteOnView = true,
  intensity = 1,
  idle = true,
  paused = false,
  ref,
  className,
  style,
  ...props
}: ArgonProps) {
  const reducedMotion = useReducedMotion();
  const staticMode = reducedMotion || paused;
  const Tag = as;
  const uid = React.useId().replace(/:/g, "");
  const filterId = `argon-bloom-${uid}`;
  const maskId = `argon-mask-${uid}`;

  const lines = React.useMemo(() => text.split("\n"), [text]);
  const seed = React.useMemo(() => hashString(text), [text]);
  const color = GAS_PRESETS[gas] ?? gas;
  const hot = `color-mix(in srgb, ${color} 42%, #ffffff)`;
  const k = Math.max(0, Math.min(2, intensity));

  const [layout, setLayout] = React.useState<Layout>(() => estimateLayout(lines, fontSize));
  const [igniteKey, setIgniteKey] = React.useState(0);
  const [lit, setLit] = React.useState(false);
  const [inView, setInView] = React.useState(false);
  const [docVisible, setDocVisible] = React.useState(true);

  const svgRef = React.useRef<SVGSVGElement>(null);
  const measureRefs = React.useRef<(SVGTextElement | null)[]>([]);
  const dashRefs = React.useRef<(SVGTextElement | null)[][]>([]);
  const glowRefs = React.useRef<(SVGGElement | null)[]>([]);
  const bloomRefs = React.useRef<(SVGTextElement | null)[]>([]);
  const fillRefs = React.useRef<(SVGTextElement | null)[]>([]);
  const playedKeyRef = React.useRef(0);
  const activeFlickers = React.useRef(new Map<number, Animation>());
  const dipTimes = React.useRef<number[]>([]);
  const flickerCount = React.useRef(0);
  const lastPointer = React.useRef(-Infinity);
  const hoverIndex = React.useRef(-1);

  // ---- geometry -----------------------------------------------------------
  const pad = Math.max(strokeWidth * 6, fontSize * 0.2);
  const lineHeight = fontSize * 1.18;
  const ascent = fontSize * 0.8;
  const clipSpace = clips ? fontSize * 0.2 : 0;
  const maxLineWidth = Math.max(1, ...layout.lineWidths);
  const vbW = maxLineWidth + pad * 2;
  const vbH = pad * 2 + ascent + (lines.length - 1) * lineHeight + fontSize * 0.22 + clipSpace;
  const baselineOf = (line: number) => pad + ascent + line * lineHeight;
  const lineOffset = (line: number) => pad + (maxLineWidth - (layout.lineWidths[line] ?? 0)) / 2;
  const dashLen = fontSize * DASH_EM;

  // ---- measure real glyph advances (kerning + letter-spacing included) -----
  const measure = React.useCallback(() => {
    const glyphs: Glyph[] = [];
    const lineWidths: number[] = [];
    lines.forEach((line, li) => {
      const el = measureRefs.current[li];
      if (!el) {
        lineWidths.push(0);
        return;
      }
      let width = 0;
      try {
        width = el.getComputedTextLength();
      } catch {
        width = 0;
      }
      lineWidths.push(width);
      let unit = 0;
      for (const char of Array.from(line)) {
        if (!/\s/.test(char)) {
          try {
            const start = el.getStartPositionOfChar(unit).x;
            const end = el.getEndPositionOfChar(unit + char.length - 1).x;
            glyphs.push({ char, line: li, x: start, w: Math.max(0, end - start) });
          } catch {
            /* unaddressable character — skip */
          }
        }
        unit += char.length;
      }
    });
    setLayout({ glyphs, lineWidths, measured: true });
  }, [lines]);

  React.useLayoutEffect(() => {
    measure();
    const fonts = typeof document !== "undefined" ? document.fonts : undefined;
    if (!fonts) return;
    let alive = true;
    const onLoad = () => alive && measure();
    fonts.ready.then(onLoad).catch(() => {});
    fonts.addEventListener?.("loadingdone", onLoad);
    return () => {
      alive = false;
      fonts.removeEventListener?.("loadingdone", onLoad);
    };
  }, [measure, fontSize]);

  // ---- visibility (in view + tab visible) ---------------------------------
  React.useEffect(() => {
    const node = svgRef.current;
    if (!node) return;
    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(([entry]) => setInView(!!entry?.isIntersecting), {
      threshold: 0.35,
    });
    io.observe(node);
    return () => io.disconnect();
  }, []);

  React.useEffect(() => {
    const onVis = () => setDocVisible(document.visibilityState !== "hidden");
    onVis();
    document.addEventListener("visibilitychange", onVis);
    return () => document.removeEventListener("visibilitychange", onVis);
  }, []);

  // ---- ignition trigger ---------------------------------------------------
  React.useEffect(() => {
    if (igniteKey !== 0) return;
    if (!igniteOnView || inView) setIgniteKey(1);
  }, [igniteOnView, inView, igniteKey]);

  // Static mode (reduced motion / paused): everything lit, nothing animating.
  React.useEffect(() => {
    if (!staticMode) return;
    playedKeyRef.current = Math.max(playedKeyRef.current, igniteKey);
    activeFlickers.current.forEach((a) => a.cancel());
    activeFlickers.current.clear();
    setLit(true);
  }, [staticMode, igniteKey]);

  const glyphCount = layout.glyphs.length;
  const measured = layout.measured;

  React.useLayoutEffect(() => {
    if (staticMode || !measured || igniteKey === 0 || playedKeyRef.current === igniteKey) return;
    playedKeyRef.current = igniteKey;
    setLit(false);
    activeFlickers.current.forEach((a) => a.cancel());
    activeFlickers.current.clear();

    const anims: Animation[] = [];
    const len = fontSize * DASH_EM;
    for (let i = 0; i < glyphCount; i++) {
      const delay = i * STAGGER;
      const rng = mulberry32(seed ^ Math.imul(i + 1, 0x9e3779b1) ^ Math.imul(igniteKey, 0x85ebca6b));
      for (const el of dashRefs.current[i] ?? []) {
        if (!el?.animate) continue;
        anims.push(
          el.animate([{ strokeDashoffset: len }, { strokeDashoffset: 0 }], {
            duration: DRAW_MS,
            delay,
            easing: "cubic-bezier(0.3, 0.15, 0.55, 1)",
            fill: "both",
          })
        );
      }
      const strike = strikeKeyframes(rng);
      const g = glowRefs.current[i];
      const b = bloomRefs.current[i];
      if (g?.animate) anims.push(g.animate(strike, { duration: 240, delay, fill: "both" }));
      if (b?.animate) anims.push(b.animate(strike, { duration: 240, delay, fill: "both" }));
      const f = fillRefs.current[i];
      if (f?.animate) {
        anims.push(
          f.animate([{ opacity: 0 }, { opacity: 1 }], {
            duration: 520,
            delay: delay + DRAW_MS * 0.3,
            easing: "ease-out",
            fill: "both",
          })
        );
      }
    }
    let cancelled = false;
    Promise.all(anims.map((a) => a.finished))
      .then(() => {
        if (cancelled) return;
        setLit(true);
        // Committed state now matches the end frames — release the animations.
        anims.forEach((a) => a.cancel());
      })
      .catch(() => {});
    return () => {
      cancelled = true;
      anims.forEach((a) => a.cancel());
    };
  }, [igniteKey, staticMode, measured, glyphCount, seed, fontSize]);

  // ---- flicker (hover / idle / handle) ------------------------------------
  const flicker = React.useCallback(
    (index?: number) => {
      if (staticMode || !lit || glyphCount === 0) return;
      const n = flickerCount.current++;
      const rng = mulberry32(seed ^ Math.imul(n + 17, 0x27d4eb2f));
      const i =
        index === undefined ? Math.floor(rng() * glyphCount) : Math.max(0, Math.min(glyphCount - 1, index));
      if (activeFlickers.current.has(i)) return;
      const now = performance.now();
      dipTimes.current = dipTimes.current.filter((t) => now - t < 1000);
      if (dipTimes.current.length + FLICKER_DIPS > MAX_DIPS_PER_SECOND) return;
      const frames = flickerKeyframes(rng);
      const opts: KeyframeAnimationOptions = { duration: 400, easing: "linear" };
      const g = glowRefs.current[i];
      const b = bloomRefs.current[i];
      const f = fillRefs.current[i];
      if (!g?.animate) return;
      dipTimes.current.push(now, now + 180);
      const a = g.animate(frames, opts);
      b?.animate?.(frames, opts);
      f?.animate?.(frames, opts);
      activeFlickers.current.set(i, a);
      const done = () => {
        if (activeFlickers.current.get(i) === a) activeFlickers.current.delete(i);
      };
      a.finished.then(done, done);
    },
    [staticMode, lit, glyphCount, seed]
  );

  React.useImperativeHandle(
    ref,
    () => ({
      replay: () => {
        if (staticMode) return;
        setIgniteKey((key) => key + 1);
      },
      flicker,
    }),
    [flicker, staticMode]
  );

  // Idle ghost: the sign occasionally destabilises on its own when nobody's pointing.
  const running = lit && !staticMode && inView && docVisible;
  React.useEffect(() => {
    if (!running || !idle) return;
    const rng = mulberry32(seed ^ 0x51ed27);
    let timer: ReturnType<typeof setTimeout>;
    const schedule = () => {
      timer = setTimeout(
        () => {
          if (performance.now() - lastPointer.current > 1500) flicker();
          schedule();
        },
        2600 + rng() * 3200
      );
    };
    schedule();
    return () => clearTimeout(timer);
  }, [running, idle, seed, flicker]);

  React.useEffect(() => {
    const flickers = activeFlickers.current;
    return () => {
      flickers.forEach((a) => a.cancel());
      flickers.clear();
    };
  }, []);

  const nearestGlyph = (clientX: number, clientY: number) => {
    const svg = svgRef.current;
    const ctm = svg?.getScreenCTM();
    if (!svg || !ctm) return -1;
    const p = new DOMPoint(clientX, clientY).matrixTransform(ctm.inverse());
    let best = -1;
    let bestD = fontSize * 0.9;
    layout.glyphs.forEach((g, i) => {
      const cx = lineOffset(g.line) + g.x + g.w / 2;
      const cy = baselineOf(g.line) - fontSize * 0.36;
      const d = Math.hypot((p.x - cx) * 1.15, p.y - cy);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    return best;
  };

  const onPointerMove = (e: React.PointerEvent<SVGSVGElement>) => {
    lastPointer.current = performance.now();
    const i = nearestGlyph(e.clientX, e.clientY);
    if (i !== hoverIndex.current) {
      hoverIndex.current = i;
      if (i >= 0) flicker(i);
    }
  };
  const onPointerDown = (e: React.PointerEvent<SVGSVGElement>) => {
    lastPointer.current = performance.now();
    const i = nearestGlyph(e.clientX, e.clientY);
    if (i >= 0) flicker(i);
  };
  const onPointerLeave = () => {
    lastPointer.current = performance.now();
    hoverIndex.current = -1;
  };

  // ---- render -------------------------------------------------------------
  const restOffset = staticMode || lit ? 0 : dashLen;
  const restFill = staticMode || lit ? 1 : 0;
  const humming = lit && !staticMode;
  const bloomBlur = strokeWidth * (0.9 + 1.4 * k);
  const tubeTransition = "stroke 450ms ease, fill 450ms ease";

  const textProps = (g: Glyph) => ({
    x: lineOffset(g.line) + g.x,
    y: baselineOf(g.line),
  });

  return (
    <Tag
      data-crucible="argon"
      className={cn("relative inline-block max-w-full font-semibold", className)}
      style={style}
      {...props}
    >
      <span className="sr-only">{text}</span>
      <style>{`
        @keyframes crucible-argon-hum {
          0%, 100% { opacity: 1; }
          23% { opacity: 0.997; }
          41% { opacity: 1; }
          67% { opacity: 0.9975; }
          84% { opacity: 0.999; }
        }
        @keyframes crucible-argon-hum-bloom {
          0%, 100% { opacity: 1; }
          31% { opacity: 0.99; }
          58% { opacity: 1; }
          79% { opacity: 0.992; }
        }
        [data-crucible="argon"] [data-hum] {
          animation: crucible-argon-hum 2.3s ease-in-out infinite;
          animation-play-state: var(--argon-play, running);
        }
        [data-crucible="argon"] [data-hum="bloom"] {
          animation-name: crucible-argon-hum-bloom;
          animation-duration: 3.1s;
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="argon"] [data-hum] { animation: none; }
        }
      `}</style>
      <svg
        ref={svgRef}
        aria-hidden
        focusable="false"
        width={vbW}
        viewBox={`0 0 ${vbW} ${vbH}`}
        className="block h-auto max-w-full select-none overflow-visible"
        style={
          {
            visibility: layout.measured ? "visible" : "hidden",
            "--argon-play": running ? "running" : "paused",
          } as React.CSSProperties
        }
        onPointerMove={onPointerMove}
        onPointerDown={onPointerDown}
        onPointerLeave={onPointerLeave}
      >
        <defs>
          <filter id={filterId} x="-30%" y="-40%" width="160%" height="180%" colorInterpolationFilters="sRGB">
            <feGaussianBlur in="SourceGraphic" stdDeviation={bloomBlur} result="near" />
            <feGaussianBlur in="SourceGraphic" stdDeviation={bloomBlur * 3.4} result="far" />
            <feMerge>
              <feMergeNode in="far" />
              <feMergeNode in="near" />
            </feMerge>
          </filter>
          {/* Hides the inner half of every outline stroke — tubes read as clean
              rims, and overlapping contours in variable fonts never show. */}
          <mask id={maskId} maskUnits="userSpaceOnUse" x={0} y={0} width={vbW} height={vbH}>
            <rect x={0} y={0} width={vbW} height={vbH} fill="#fff" />
            <g style={{ fontSize }} fontFamily="inherit" fontWeight="inherit" fill="#000" stroke="none">
              {layout.glyphs.map((g, i) => (
                <text key={i} {...textProps(g)}>
                  {g.char}
                </text>
              ))}
            </g>
          </mask>
        </defs>

        <g style={{ fontSize }} fontFamily="inherit" fontWeight="inherit" strokeLinejoin="round" strokeLinecap="round">
          {/* measuring copies — never painted */}
          <g visibility="hidden">
            {lines.map((line, li) => (
              <text
                key={li}
                ref={(el) => {
                  measureRefs.current[li] = el;
                }}
                x={0}
                y={baselineOf(li)}
                style={{ whiteSpace: "pre" }}
              >
                {line}
              </text>
            ))}
          </g>

          {/* back-wire + mounting clips */}
          {clips && (
            <g>
              {lines.map((_, li) => {
                const lineGlyphs = layout.glyphs.filter((g) => g.line === li);
                if (lineGlyphs.length === 0) return null;
                const first = lineGlyphs[0]!;
                const last = lineGlyphs[lineGlyphs.length - 1]!;
                const off = lineOffset(li);
                const wy = baselineOf(li) + fontSize * 0.15;
                return (
                  <line
                    key={li}
                    x1={off + first.x - fontSize * 0.08}
                    x2={off + last.x + last.w + fontSize * 0.08}
                    y1={wy}
                    y2={wy}
                    stroke="rgba(255,255,255,0.09)"
                    strokeWidth={Math.max(1, fontSize * 0.012)}
                  />
                );
              })}
              {layout.glyphs.map((g, i) => {
                const cx = lineOffset(g.line) + g.x + g.w / 2;
                const by = baselineOf(g.line);
                const cw = fontSize * 0.085;
                const ch = fontSize * 0.06;
                return (
                  <g key={i}>
                    <line
                      x1={cx}
                      x2={cx}
                      y1={by + ch * 0.6}
                      y2={by + fontSize * 0.15}
                      stroke="rgba(255,255,255,0.12)"
                      strokeWidth={Math.max(1, fontSize * 0.01)}
                    />
                    <rect
                      x={cx - cw / 2}
                      y={by - ch * 0.35}
                      width={cw}
                      height={ch}
                      rx={ch * 0.3}
                      style={{
                        fill: `color-mix(in srgb, ${color} ${restFill ? 14 : 4}%, #2b2b30)`,
                        stroke: "rgba(255,255,255,0.2)",
                        transition: "fill 600ms ease",
                      }}
                      strokeWidth={Math.max(0.75, fontSize * 0.006)}
                    />
                  </g>
                );
              })}
            </g>
          )}

          {/* unlit glass tubes */}
          {layout.glyphs.map((g, i) => (
            <text key={i} {...textProps(g)} fill="rgba(255,255,255,0.03)" stroke="none">
              {g.char}
            </text>
          ))}
          <g mask={`url(#${maskId})`}>
            {layout.glyphs.map((g, i) => (
              <text
                key={i}
                {...textProps(g)}
                fill="none"
                stroke="rgba(226,232,240,0.2)"
                strokeWidth={strokeWidth * 1.5}
              >
                {g.char}
              </text>
            ))}
          </g>

          {/* bloom */}
          <g filter={`url(#${filterId})`} opacity={Math.min(1, 0.6 * k)} data-hum={humming ? "bloom" : undefined}>
            {layout.glyphs.map((g, i) => (
              <text
                key={i}
                ref={(el) => {
                  bloomRefs.current[i] = el;
                  (dashRefs.current[i] ??= [])[0] = el;
                }}
                {...textProps(g)}
                fill="none"
                strokeWidth={strokeWidth * (2.2 + k)}
                strokeDasharray={`${dashLen} ${dashLen}`}
                style={{ stroke: color, strokeDashoffset: restOffset, transition: tubeTransition }}
              >
                {g.char}
              </text>
            ))}
          </g>

          {/* gas glowing inside the glass */}
          <g data-hum={humming ? "core" : undefined}>
            {layout.glyphs.map((g, i) => (
              <text
                key={i}
                ref={(el) => {
                  fillRefs.current[i] = el;
                }}
                {...textProps(g)}
                stroke="none"
                style={{
                  fill: color,
                  fillOpacity: 0.08 * k,
                  opacity: restFill,
                  transition: tubeTransition,
                }}
              >
                {g.char}
              </text>
            ))}
          </g>

          {/* lit tubes: core rim + white-hot inner edge (outer half only, via mask) */}
          <g data-hum={humming ? "core" : undefined} mask={`url(#${maskId})`}>
            {layout.glyphs.map((g, i) => (
              <g
                key={i}
                ref={(el) => {
                  glowRefs.current[i] = el;
                }}
              >
                <text
                  ref={(el) => {
                    (dashRefs.current[i] ??= [])[1] = el;
                  }}
                  {...textProps(g)}
                  fill="none"
                  strokeWidth={strokeWidth * 2}
                  strokeDasharray={`${dashLen} ${dashLen}`}
                  style={{
                    stroke: color,
                    strokeOpacity: Math.min(1, 0.65 + 0.35 * k),
                    strokeDashoffset: restOffset,
                    transition: tubeTransition,
                  }}
                >
                  {g.char}
                </text>
                <text
                  ref={(el) => {
                    (dashRefs.current[i] ??= [])[2] = el;
                  }}
                  {...textProps(g)}
                  fill="none"
                  strokeWidth={strokeWidth * 0.9}
                  strokeDasharray={`${dashLen} ${dashLen}`}
                  style={{ stroke: hot, strokeDashoffset: restOffset, transition: tubeTransition }}
                >
                  {g.char}
                </text>
              </g>
            ))}
          </g>
        </g>
      </svg>
    </Tag>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface BevelProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Card content. */
  children: React.ReactNode;
  /** Maximum tilt, in degrees, on either axis at the card's edge. Subtle by design. @default 6 */
  tilt?: number;
  /** Color of the caustic light on the bevel edges and the internal refracted highlight. @default glacial cyan */
  causticColor?: string;
  /** Backdrop blur in px — how strongly the glass frosts whatever sits behind it. @default 16 */
  blur?: number;
  /**
   * Idle autoplay: after 1.5s with no pointer on the card, a slow ghost
   * light drifts across it — a gentle tilt and sliding caustic at reduced
   * strength — so the glass never reads as dead. A real pointer takes over
   * instantly. Off under reduced motion; sleeps offscreen. @default true
   */
  idle?: boolean;
}

const IDLE_MS = 1500;
/** Ghost strength relative to a real pointer — deliberate, never a full hover. */
const GHOST_GAIN = 0.55;

/** Stable per-instance phase from React's id, so sibling cards never ghost in lockstep. */
function idPhase(id: string): number {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  return ((h >>> 0) / 4294967296) * Math.PI * 2;
}

/**
 * Bevel — a glass-refraction surface card. A glassmorphic panel (backdrop
 * blur + saturation over whatever sits behind it) with a multi-layer edge:
 * an outer hairline, a soft white inner bevel, and a slow glacial-cyan
 * caustic that drifts along the top edge. On hover the panel tilts gently in
 * perspective and a refracted offset highlight — plus a thin caustic line on
 * the lower-inside bevel — slides with the pointer, like light cast through
 * thick glass. Tilt eases via registered custom-property transitions (pure
 * CSS, no animation library) and disables for touch input. Reduced motion:
 * static caustics at a handsome phase, no tilt, no drift. Untouched, a ghost
 * light idles across the pane (`idle`), handing over to the real pointer.
 */
export function Bevel({
  children,
  tilt = 6,
  causticColor = "#7dd3fc",
  blur = 16,
  idle = true,
  className,
  style,
  ...props
}: BevelProps) {
  const reducedMotion = useReducedMotion();
  const hoverRef = React.useRef(false);
  const lastPointerRef = React.useRef(0);
  const ghostRef = React.useRef({ presence: 0, last: 0, on: false });
  const phase = idPhase(React.useId());

  // Ghost driver: a slow Lissajous light path, eased in so it never snaps.
  // The observed element, mirrored for the rAF tick (set after commit).
  const elRef = React.useRef<HTMLElement | null>(null);
  const nodeRef = useVisibilityPause<HTMLDivElement>(
    (elapsed) => {
      const node = elRef.current;
      const g = ghostRef.current;
      if (!node) return;
      if (elapsed < g.last) g.last = elapsed;
      const dt = Math.min(elapsed - g.last, 0.05);
      g.last = elapsed;
      if (hoverRef.current) {
        g.presence = 0;
        g.on = false;
        return;
      }
      const want = performance.now() - lastPointerRef.current > IDLE_MS ? 1 : 0;
      g.presence += (want - g.presence) * Math.min(1, dt * 1.6);
      if (g.presence < 0.01 && !want) {
        if (g.on) {
          g.on = false;
          node.setAttribute("data-hover", "false");
        }
        return;
      }
      if (!g.on) {
        g.on = true;
        node.setAttribute("data-hover", "ghost");
      }
      const px = 0.5 + 0.34 * Math.sin(elapsed * 0.41 + phase + 0.7);
      const py = 0.45 + 0.3 * Math.sin(elapsed * 0.29 + 2.1 + phase * 1.7);
      const k = g.presence * GHOST_GAIN;
      node.style.setProperty("--bevel-rx", `${(-(py - 0.5) * 2 * tilt * k).toFixed(3)}deg`);
      node.style.setProperty("--bevel-ry", `${((px - 0.5) * 2 * tilt * k).toFixed(3)}deg`);
      node.style.setProperty("--bevel-px", `${((0.5 + (px - 0.5) * g.presence) * 100).toFixed(2)}%`);
      node.style.setProperty("--bevel-py", `${((0.4 + (py - 0.4) * g.presence) * 100).toFixed(2)}%`);
    },
    { paused: !idle || reducedMotion }
  );

  React.useEffect(() => {
    elRef.current = nodeRef.current;
  });

  // Arm the idle clock at mount (the ghost waits 1.5s before its first pass).
  React.useEffect(() => {
    lastPointerRef.current = performance.now();
  }, []);

  const handlePointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (reducedMotion || event.pointerType === "touch") return;
      const node = nodeRef.current;
      if (!node) return;
      hoverRef.current = true;
      lastPointerRef.current = performance.now();
      if (node.getAttribute("data-hover") !== "true") node.setAttribute("data-hover", "true");
      const rect = node.getBoundingClientRect();
      const px = (event.clientX - rect.left) / rect.width;
      const py = (event.clientY - rect.top) / rect.height;
      node.style.setProperty("--bevel-rx", `${(-(py - 0.5) * 2 * tilt).toFixed(3)}deg`);
      node.style.setProperty("--bevel-ry", `${((px - 0.5) * 2 * tilt).toFixed(3)}deg`);
      node.style.setProperty("--bevel-px", `${(px * 100).toFixed(2)}%`);
      node.style.setProperty("--bevel-py", `${(py * 100).toFixed(2)}%`);
    },
    [reducedMotion, tilt, nodeRef]
  );

  const handlePointerEnter = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (reducedMotion || event.pointerType === "touch") return;
      hoverRef.current = true;
      lastPointerRef.current = performance.now();
      ghostRef.current.presence = 0;
      ghostRef.current.on = false;
      nodeRef.current?.setAttribute("data-hover", "true");
    },
    [reducedMotion, nodeRef]
  );

  const handlePointerLeave = React.useCallback(() => {
    hoverRef.current = false;
    lastPointerRef.current = performance.now();
    const node = nodeRef.current;
    if (!node) return;
    node.setAttribute("data-hover", "false");
    node.style.setProperty("--bevel-rx", "0deg");
    node.style.setProperty("--bevel-ry", "0deg");
    node.style.setProperty("--bevel-px", "50%");
    node.style.setProperty("--bevel-py", "40%");
  }, [nodeRef]);

  return (
    <div
      ref={nodeRef}
      data-crucible="bevel"
      data-hover="false"
      data-reduced-motion={reducedMotion}
      onPointerMove={handlePointerMove}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      className={cn(
        "relative overflow-hidden rounded-2xl border border-white/10",
        "focus-within:border-white/25",
        className
      )}
      style={{
        ["--bevel-rx" as string]: "0deg",
        ["--bevel-ry" as string]: "0deg",
        ["--bevel-px" as string]: "50%",
        ["--bevel-py" as string]: "40%",
        ["--bevel-caustic" as string]: causticColor,
        backgroundColor: "rgba(18, 21, 27, 0.32)",
        backdropFilter: `blur(${blur}px) saturate(150%)`,
        WebkitBackdropFilter: `blur(${blur}px) saturate(150%)`,
        ...style,
      }}
      {...props}
    >
      <style>{`
        @property --bevel-rx {
          syntax: "<angle>";
          inherits: true;
          initial-value: 0deg;
        }
        @property --bevel-ry {
          syntax: "<angle>";
          inherits: true;
          initial-value: 0deg;
        }
        @property --bevel-px {
          syntax: "<percentage>";
          inherits: true;
          initial-value: 50%;
        }
        @property --bevel-py {
          syntax: "<percentage>";
          inherits: true;
          initial-value: 40%;
        }
        [data-crucible="bevel"] {
          isolation: isolate;
          transform: perspective(1100px) rotateX(var(--bevel-rx)) rotateY(var(--bevel-ry));
          /* Registered custom properties interpolate, so the tilt and the
             refracted light trail the pointer with a heavy, glassy lag
             instead of snapping. Unregistered fallback follows instantly. */
          transition:
            --bevel-rx 260ms cubic-bezier(0.22, 1, 0.36, 1),
            --bevel-ry 260ms cubic-bezier(0.22, 1, 0.36, 1),
            --bevel-px 260ms cubic-bezier(0.22, 1, 0.36, 1),
            --bevel-py 260ms cubic-bezier(0.22, 1, 0.36, 1);
        }
        [data-crucible="bevel"] .bevel-layer {
          position: absolute;
          inset: 0;
          border-radius: inherit;
          pointer-events: none;
        }
        /* Inner bevel: soft white top edge, faint bottom return, hairline
           inner ring — the three-line stack that reads as ground glass. */
        [data-crucible="bevel"] .bevel-edge {
          box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, 0.22),
            inset 0 2px 6px -2px rgba(255, 255, 255, 0.1),
            inset 0 -1px 0 rgba(255, 255, 255, 0.05),
            inset 0 0 0 1px rgba(255, 255, 255, 0.04);
        }
        /* Caustic sheen drifting along the top bevel. */
        [data-crucible="bevel"] .bevel-caustic-top {
          inset: 0 0 auto 0;
          height: 2px;
          border-radius: 0;
          background: linear-gradient(
            90deg,
            transparent,
            color-mix(in oklab, var(--bevel-caustic) 55%, white) 45%,
            color-mix(in oklab, var(--bevel-caustic) 85%, transparent) 55%,
            transparent
          );
          background-size: 55% 100%;
          background-repeat: no-repeat;
          background-position: 35% 0;
          filter: drop-shadow(0 0 6px color-mix(in oklab, var(--bevel-caustic) 60%, transparent));
          opacity: 0.7;
          animation: bevel-drift 9s ease-in-out infinite alternate;
          transition: opacity 400ms ease;
        }
        [data-crucible="bevel"][data-hover="true"] .bevel-caustic-top {
          opacity: 1;
        }
        [data-crucible="bevel"][data-hover="ghost"] .bevel-caustic-top {
          opacity: 0.85;
        }
        /* The refracted line on the lower-inside bevel — slides with the
           pointer, like a caustic cast through the pane onto its far edge. */
        [data-crucible="bevel"] .bevel-caustic-low {
          inset: auto 0 0 0;
          height: 1.5px;
          border-radius: 0;
          background: linear-gradient(
            90deg,
            transparent,
            color-mix(in oklab, var(--bevel-caustic) 70%, transparent),
            transparent
          );
          background-size: 45% 100%;
          background-repeat: no-repeat;
          background-position: var(--bevel-px) 0;
          opacity: 0;
          transition: opacity 400ms ease;
        }
        [data-crucible="bevel"][data-hover="true"] .bevel-caustic-low {
          opacity: 0.8;
        }
        [data-crucible="bevel"][data-hover="ghost"] .bevel-caustic-low {
          opacity: 0.5;
        }
        /* Internal refracted highlight: offset from the pointer (light bends
           through the glass, so it never sits directly under the cursor). */
        [data-crucible="bevel"] .bevel-refract {
          background: radial-gradient(
            130% 90% at calc(var(--bevel-px) + 14%) calc(var(--bevel-py) - 22%),
            color-mix(in oklab, var(--bevel-caustic) 12%, transparent),
            color-mix(in oklab, var(--bevel-caustic) 5%, transparent) 40%,
            transparent 68%
          );
          mix-blend-mode: screen;
          opacity: 0.55;
          transition: opacity 400ms ease;
        }
        [data-crucible="bevel"][data-hover="true"] .bevel-refract {
          opacity: 0.95;
        }
        [data-crucible="bevel"][data-hover="ghost"] .bevel-refract {
          opacity: 0.75;
        }
        @keyframes bevel-drift {
          from {
            background-position: -12% 0;
          }
          to {
            background-position: 112% 0;
          }
        }
        [data-crucible="bevel"][data-reduced-motion="true"] {
          transform: none;
          transition: none;
        }
        [data-crucible="bevel"][data-reduced-motion="true"] .bevel-caustic-top {
          animation: none;
          background-position: 35% 0;
          opacity: 0.7;
        }
        [data-crucible="bevel"][data-reduced-motion="true"] .bevel-caustic-low {
          opacity: 0.5;
        }
        [data-crucible="bevel"][data-reduced-motion="true"] .bevel-refract {
          opacity: 0.45;
          transition: none;
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="bevel"] .bevel-caustic-top {
            animation: none;
          }
        }
      `}</style>
      <div className="relative z-10">{children}</div>
      <div className="bevel-layer bevel-refract" aria-hidden />
      <div className="bevel-layer bevel-edge" aria-hidden />
      <div className="bevel-layer bevel-caustic-top" aria-hidden />
      <div className="bevel-layer bevel-caustic-low" aria-hidden />
    </div>
  );
}

import * as React from "react";

import { cn } from "@/lib/utils";

export interface BilletProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Which content-shaped placeholder to forge.
   * - `card` (default): an avatar + heading rows, a media rect, and a
   *   paragraph — a full content card blank.
   * - `text`: a stack of text-line bars, the last one short.
   * - `circle`: a single avatar disc.
   * - `rect`: a single media/thumbnail block.
   * Compose several to prefigure any layout.
   * @default "card"
   */
  shape?: "card" | "text" | "circle" | "rect";
  /** Number of text-line bars for `text` (and the card paragraph). @default 3 */
  lines?: number;
  /** Width of the final, short line — any CSS length/percentage. @default "62%" */
  lastLineWidth?: string;
  /** Diameter in px of the `circle` avatar disc. @default 48 */
  size?: number;
  /** Sweep-cycle speed multiplier. 1 = default, 2 = twice as fast. @default 1 */
  speed?: number;
  /** Direction the light pass travels. @default "right" */
  direction?: "left" | "right";
  /** Tilt of the light band in degrees (0 = vertical bar). @default 12 */
  angle?: number;
  /** Corner radius in px for blocks and the card panel. @default 8 */
  radius?: number;
  /**
   * `sweep` (default): a single cool-white light pass with matte graphite
   * between passes. `pulse`: a gentle opacity breathe, no pass.
   * @default "sweep"
   */
  mode?: "sweep" | "pulse";
  /** Matte base tone of the placeholder blocks. Any CSS color. @default "#1c1e24" */
  baseColor?: string;
  /** Peak tone of the light pass. Any CSS color. @default "#e6ecf7" */
  highlightColor?: string;
  /** Freeze the animation on a designed lit frame. @default false */
  paused?: boolean;
  /** Accessible label announced while content loads. @default "Loading" */
  label?: string;
}

// @property makes --billet-pos a real animatable <number>, so the custom
// property INTERPOLATES between keyframes (unregistered custom properties
// snap, they don't tween) — that smooth tween is the whole light pass. The
// keyframes dwell off-screen (matte) then fire a single eased pass: a heat
// pass, not a constant conveyor. Reduced motion swaps to a slow opacity
// breathe — a living resting frame, never a dead grey box. All pure CSS:
// browsers already throttle CSS animations offscreen and on hidden tabs, so
// no JS observer is needed to pause.
const STYLE = `
@property --billet-pos {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}
@keyframes crucible-billet-sweep {
  0%, 44%  { --billet-pos: var(--billet-from); }
  44%      { --billet-pos: var(--billet-from); animation-timing-function: cubic-bezier(0.45, 0, 0.15, 1); }
  80%      { --billet-pos: var(--billet-to); }
  100%     { --billet-pos: var(--billet-to); }
}
@keyframes crucible-billet-pulse {
  0%, 100% { opacity: 0.5; }
  50%      { opacity: 1; }
}
[data-crucible="billet"] .billet-block {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  background-color: var(--billet-base);
  border-radius: var(--billet-radius);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035), inset 0 0 0 1px rgba(255, 255, 255, 0.02);
}
[data-crucible="billet"] .billet-shine {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(
    var(--billet-grad-angle),
    transparent 34%,
    color-mix(in oklab, var(--billet-highlight) 85%, transparent) 50%,
    transparent 66%
  );
  transform: translateX(calc(var(--billet-pos) * 1%));
  mix-blend-mode: screen;
  opacity: 0.7;
  will-change: transform;
}
[data-crucible="billet"][data-mode="sweep"]:not([data-paused="true"]) .billet-shine {
  animation: crucible-billet-sweep var(--billet-dur) linear infinite;
}
[data-crucible="billet"][data-mode="pulse"] .billet-shine {
  display: none;
}
[data-crucible="billet"][data-mode="pulse"]:not([data-paused="true"]) .billet-block {
  animation: crucible-billet-pulse var(--billet-dur) ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) {
  [data-crucible="billet"] .billet-shine {
    display: none !important;
  }
  [data-crucible="billet"]:not([data-paused="true"]) .billet-block {
    animation: crucible-billet-pulse calc(var(--billet-dur) * 1.5) ease-in-out infinite !important;
  }
}
`;

// A single matte placeholder block with its own light-pass overlay.
function Block({ style }: { style?: React.CSSProperties }) {
  return (
    <div className="billet-block" style={style} aria-hidden>
      <span className="billet-shine" />
    </div>
  );
}

function TextLines({ lines, lastLineWidth, lineRadius }: { lines: number; lastLineWidth: string; lineRadius: number }) {
  return (
    <div className="flex w-full flex-col" style={{ gap: "0.62rem" }}>
      {Array.from({ length: lines }, (_, i) => (
        <Block
          key={i}
          style={{
            height: "0.85rem",
            width: i === lines - 1 && lines > 1 ? lastLineWidth : "100%",
            borderRadius: lineRadius,
          }}
        />
      ))}
    </div>
  );
}

/**
 * Billet — a content-shaped skeleton placeholder: matte graphite blocks (an
 * "unforged billet") crossed by a single cool-white light pass. The pass is a
 * heat pass, not a treadmill — it dwells off the block, then fires once and
 * rests, driven by an @property-registered custom property so the shine tweens
 * smoothly with zero JavaScript. Presets cover the common blanks (card / text
 * / circle / rect) and compose to prefigure any layout. Colors, radius, sweep
 * speed/direction/angle, line count, and a pulse mode are all themeable; the
 * region carries `role="status"` + `aria-busy`, and under reduced motion the
 * sweep becomes a gentle opacity breathe — a living resting frame, never a
 * dead grey box.
 */
export function Billet({
  shape = "card",
  lines = 3,
  lastLineWidth = "62%",
  size = 48,
  speed = 1,
  direction = "right",
  angle = 12,
  radius = 8,
  mode = "sweep",
  baseColor = "#1c1e24",
  highlightColor = "#e6ecf7",
  paused = false,
  label = "Loading",
  className,
  style,
  ...rest
}: BilletProps) {
  const lineCount = Math.max(1, Math.min(Math.round(lines), 12));
  const lineRadius = Math.min(radius, 6);

  const vars = {
    "--billet-base": baseColor,
    "--billet-highlight": highlightColor,
    "--billet-radius": `${radius}px`,
    "--billet-grad-angle": `${90 + angle}deg`,
    "--billet-dur": `${(2.8 / Math.max(speed, 0.05)).toFixed(3)}s`,
    // Percentages the light band translates between (its own width is the
    // block width, so ±120% clears fully off either side).
    "--billet-from": direction === "left" ? "120" : "-120",
    "--billet-to": direction === "left" ? "-120" : "120",
    ...style,
  } as React.CSSProperties;

  const panel: React.CSSProperties = {
    padding: "1rem",
    border: "1px solid rgba(255,255,255,0.06)",
    borderRadius: `calc(var(--billet-radius) + 6px)`,
    background: "rgba(255,255,255,0.015)",
  };

  return (
    <div
      {...rest}
      data-crucible="billet"
      data-mode={mode}
      data-paused={paused ? "true" : undefined}
      role="status"
      aria-busy="true"
      aria-label={label}
      className={cn("relative block w-full", className)}
      style={vars}
    >
      <style>{STYLE}</style>

      {shape === "circle" && (
        <Block style={{ width: size, height: size, borderRadius: 9999 }} />
      )}

      {shape === "rect" && <Block style={{ width: "100%", height: "9rem" }} />}

      {shape === "text" && (
        <TextLines lines={lineCount} lastLineWidth={lastLineWidth} lineRadius={lineRadius} />
      )}

      {shape === "card" && (
        <div className="billet-card w-full" style={panel}>
          <div className="flex items-center" style={{ gap: "0.85rem" }}>
            <Block style={{ width: 44, height: 44, borderRadius: 9999, flex: "0 0 auto" }} />
            <div className="flex min-w-0 flex-1 flex-col" style={{ gap: "0.5rem" }}>
              <Block style={{ height: "0.95rem", width: "55%", borderRadius: lineRadius }} />
              <Block style={{ height: "0.75rem", width: "32%", borderRadius: lineRadius }} />
            </div>
          </div>
          <Block
            style={{ height: "8.5rem", width: "100%", borderRadius: "var(--billet-radius)", marginTop: "1rem" }}
          />
          <div className="flex flex-col" style={{ gap: "0.6rem", marginTop: "1rem" }}>
            {Array.from({ length: lineCount }, (_, i) => (
              <Block
                key={i}
                style={{
                  height: "0.8rem",
                  width: i === lineCount - 1 && lineCount > 1 ? lastLineWidth : "100%",
                  borderRadius: lineRadius,
                }}
              />
            ))}
          </div>
        </div>
      )}

      <span className="sr-only">{label}</span>
    </div>
  );
}

