/* ---------------------------------------------------------------- types */

/** The four change kinds, in the order groups render. */
export type AnnalsKind = "new" | "improved" | "fixed" | "deprecated";

/** One line in a release. */
export interface AnnalsItem {
  /** Which group (and chip color) the change belongs to. */
  kind: AnnalsKind;
  /** The change itself, one sentence. Search matches and highlights within it. */
  text: string;
}

/** Optional screenshot plate for a release. */
export interface AnnalsMedia {
  /** Image URL. Omit for a procedural gradient "screenshot" placeholder seeded from the version. */
  src?: string;
  /** Accessible description of the image. @default "<title> preview" */
  alt?: string;
  /** Small caption under the plate. */
  caption?: string;
}

/** One release in the changelog. Pass entries newest first. */
export interface AnnalsEntry {
  /** Version label, e.g. `"v3.8.0"`. Also the stable key unless `id` is set. */
  version: string;
  /** Release date — ISO `YYYY-MM-DD` is formatted ("Oct 8, 2026"); anything else renders as-is. */
  date: string;
  /** Release headline. */
  title: string;
  /** Optional one-line summary under the headline. */
  summary?: string;
  /** The changes. Rendered grouped by kind: New, Improved, Fixed, Deprecated. */
  items: AnnalsItem[];
  /** Screenshot plate. `true` renders the procedural placeholder. */
  media?: AnnalsMedia | true;
  /** Stable identity. @default version */
  id?: string;
}

/** Imperative verbs exposed through the `ref` prop. */
export interface AnnalsHandle {
  /** Replay the designed intro (header rise, spine draw, entry cascade, Latest pulse). */
  replay: () => void;
  /** Clear the kind filters and the search query. */
  clearFilters: () => void;
  /** Focus the search field. */
  focusSearch: () => void;
}

export interface AnnalsProps extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title"> {
  /** Releases, newest first. The first entry carries the "Latest" badge. Defaults to a seeded sample changelog. */
  entries?: AnnalsEntry[];
  /** Section headline (`<h2>`). @default "What's new" */
  title?: React.ReactNode;
  /** Small label above the headline. @default "Changelog" */
  eyebrow?: React.ReactNode;
  /** Supporting copy under the headline. */
  description?: React.ReactNode;
  /**
   * Called with the email from the inline subscribe field. Return a Promise to
   * hold the pending state — resolve shows "Subscribed", reject shows the
   * rejection message (or a generic one) inline.
   */
  onSubscribe?: (email: string) => void | Promise<unknown>;
  /** Href of the RSS ghost link; `false` hides it. @default "/changelog/rss.xml" */
  rssHref?: string | false;
  /** Items shown per release before "Show N more changes" (ignored while searching). @default 4 */
  collapseAfter?: number;
  /** Render media plates (real or procedural). @default true */
  showMedia?: boolean;
  /** Show the search field in the toolbar. @default true */
  searchable?: boolean;
  /**
   * Scroll container that drives the spine's progress beam. Auto-detects the
   * nearest scrollable ancestor (or the window) when omitted; pass a ref to
