   */
  scroller?: React.RefObject<HTMLElement | null>;
  /** Backdrop painted behind the sticky toolbar so entries scroll beneath it cleanly. Match your surface. @default "rgb(10 10 10 / 0.86)" */
  stickyBackground?: string;
  /** Accent hex: "New" chips, the spine beam, Latest badge, subscribe button, marks and focus rings. @default "#bef264" */
