/** Procedural "screenshot": a seeded faux app window on a soft accent-lit gradient. */
function MediaPlate({ seedKey, label }: { seedKey: string; label: string }) {
  const art = React.useMemo(() => {
    const rand = mulberry32(hashString(seedKey));
    const variant = Math.floor(rand() * 3);
    const gx = 15 + Math.round(rand() * 70);
    const gy = 10 + Math.round(rand() * 40);
    const hue = Math.round(180 + rand() * 120);
    const bars = Array.from({ length: 5 }, () => 40 + Math.round(rand() * 50));
    const points = Array.from({ length: 9 }, (_, i) => {
      const y = 70 - i * 5 - rand() * 22;
      return `${(i / 8) * 100},${Math.max(8, Math.min(92, y))}`;
    });
    const rows = Array.from({ length: 5 }, () => [30 + rand() * 40, 15 + rand() * 25, 10 + rand() * 15]);
    return { variant, gx, gy, hue, bars, points, rows, active: Math.floor(rand() * 3) };
  }, [seedKey]);

  return (
    <div
      role="img"
      aria-label={label}
      className="relative aspect-[16/9] w-full overflow-hidden rounded-xl border border-white/[0.08] bg-[#0d0d10]"
      style={{
        backgroundImage: `radial-gradient(70% 90% at ${art.gx}% ${art.gy}%, color-mix(in oklab, var(--annals-accent) 22%, transparent), transparent 70%), radial-gradient(60% 70% at ${100 - art.gx}% 100%, hsl(${art.hue} 70% 55% / 0.16), transparent 70%)`,
      }}
    >
      {/* faux window */}
      <div className="absolute inset-x-[7%] top-[12%] bottom-0 overflow-hidden rounded-t-lg border border-b-0 border-white/[0.1] bg-[#0b0b0d]/90 shadow-[0_-12px_40px_-12px_rgba(0,0,0,0.6)]">
        <div className="flex h-[9%] min-h-[14px] items-center gap-[3px] border-b border-white/[0.06] px-[2.5%]">
          {[0, 1, 2].map((i) => (
            <span key={i} className="aspect-square h-[34%] rounded-full bg-white/15" />
          ))}
          <span className="mx-auto h-[38%] w-[28%] rounded-full bg-white/[0.06]" />
        </div>
        <div className="flex h-[91%]">
          <div className="flex w-[20%] flex-col gap-[7%] border-r border-white/[0.06] p-[3%] pt-[5%]">
            {art.bars.map((w, i) => (
              <span
                key={i}
                className="h-[5px] rounded-full"
                style={{
                  width: `${w}%`,
                  backgroundColor: i === 1 ? "color-mix(in oklab, var(--annals-accent) 70%, transparent)" : "rgb(255 255 255 / 0.1)",
                }}
              />
            ))}
          </div>
          <div className="flex flex-1 flex-col gap-[5%] p-[3.5%]">
            <div className="flex items-center justify-between">
              <span className="h-[7px] w-[30%] rounded-full bg-white/20" />
              <span className="h-[10px] w-[14%] rounded-full" style={{ backgroundColor: "var(--annals-accent)", opacity: 0.85 }} />
            </div>
            {art.variant === 0 && (
              <div className="grid flex-1 grid-cols-3 gap-[4%]">
                {[0, 1, 2].map((i) => (
                  <div
                    key={i}
                    className="rounded-md border bg-white/[0.025] p-[8%]"
                    style={{
                      borderColor:
                        i === art.active ? "color-mix(in oklab, var(--annals-accent) 55%, transparent)" : "rgb(255 255 255 / 0.07)",
                    }}
                  >
                    <span className="block h-[5px] w-3/5 rounded-full bg-white/20" />
                    <span className="mt-[14%] block h-[4px] w-full rounded-full bg-white/[0.08]" />
                    <span className="mt-[8%] block h-[4px] w-4/5 rounded-full bg-white/[0.08]" />
                  </div>
                ))}
              </div>
            )}
            {art.variant === 1 && (
              <div className="flex-1 rounded-md border border-white/[0.07] bg-white/[0.02] p-[3%]">
                <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-full w-full overflow-visible">
                  <polyline
                    points={art.points.join(" ")}
                    fill="none"
                    stroke="var(--annals-accent)"
                    strokeWidth="1.6"
                    vectorEffect="non-scaling-stroke"
                    strokeLinejoin="round"
                  />
                  <polyline
                    points={`0,100 ${art.points.join(" ")} 100,100`}
                    fill="var(--annals-accent)"
                    opacity="0.08"
                    stroke="none"
                  />
                </svg>
              </div>
            )}
            {art.variant === 2 && (
              <div className="flex flex-1 flex-col justify-between rounded-md border border-white/[0.07] bg-white/[0.02] p-[3%]">
                {art.rows.map((r, i) => (
                  <div key={i} className="flex items-center gap-[4%]">
                    <span
                      className="size-[6px] shrink-0 rounded-full"
                      style={{ backgroundColor: i === art.active ? "var(--annals-accent)" : "rgb(255 255 255 / 0.18)" }}
                    />
                    <span className="h-[4px] rounded-full bg-white/[0.14]" style={{ width: `${r[0]}%` }} />
                    <span className="h-[4px] rounded-full bg-white/[0.07]" style={{ width: `${r[1]}%` }} />
                    <span className="ml-auto h-[4px] rounded-full bg-white/[0.07]" style={{ width: `${r[2]}%` }} />
                  </div>
                ))}
              </div>
            )}
          </div>
