const INTRO_STAGGER = 0.35; // s between cursors fading in
const INTRO_FADE = 0.45; // s
const RESUME_DELAY = 1.5; // s after the real pointer leaves
const CLICK_MS = 320;
const PILL_SPRING = { stiffness: 170, damping: 22, mass: 0.9 };

// Underdamped spring step response (ζ≈0.68 → ~5% overshoot), normalized to s∈[0,1].
const ZETA = 0.68;
const OMEGA = 10;
const OMEGA_D = OMEGA * Math.sqrt(1 - ZETA * ZETA);
function springEase(s: number) {
  if (s >= 1) return 1;
  const e = Math.exp(-ZETA * OMEGA * s);
  return 1 - e * (Math.cos(OMEGA_D * s) + ((ZETA * OMEGA) / OMEGA_D) * Math.sin(OMEGA_D * s));
}
const easeInOut = (s: number) => (s < 0.5 ? 2 * s * s : 1 - Math.pow(-2 * s + 2, 2) / 2);
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** Pill text color: white on dark hex fills, near-black otherwise (non-hex colors keep the dark default). */
function inkOn(color: string) {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
  if (!m) return "#0a0a0a";
  const h = m[1].length === 3 ? [...m[1]].map((c) => c + c).join("") : m[1];
  const [r, g, b] = [0, 2, 4].map((i) => {
    const c = parseInt(h.slice(i, i + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  // Contrast vs white (1.05/(L+0.05)) beats contrast vs near-black ((L+0.05)/0.05) below L≈0.18.
  return lum < 0.18 ? "#ffffff" : "#0a0a0a";
}

function hashString(str: string) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

type Vec = { x: number; y: number };
type Box = { x: number; y: number; w: number; h: number };

// Internal ops: `select` expands to a move to the top-left + a drag.
type Op =
  | { k: "move"; to: CohortTarget; anchor: CohortPoint; dur?: number }
  | { k: "drag"; target: string | CohortRect; dur: number }
  | { k: "click" }
  | { k: "type"; text: string; dur: number; hold: number }
  | { k: "react"; emoji: string }
  | { k: "wait"; dur: number };

function compile(script: CohortStep[]): Op[] {
  const ops: Op[] = [];
  for (const s of script) {
    switch (s.type) {
      case "move":
        ops.push({ k: "move", to: s.to, anchor: s.anchor ?? [0.5, 0.5], dur: s.duration });
        break;
      case "select":
        ops.push({ k: "move", to: s.target, anchor: [0, 0] });
        ops.push({ k: "drag", target: s.target, dur: s.duration ?? 700 });
        break;
      case "click":
        ops.push({ k: "click" });
        break;
      case "type":
        ops.push({ k: "type", text: s.text, dur: s.duration ?? s.text.length * 55, hold: s.hold ?? 900 });
        break;
      case "react":
        ops.push({ k: "react", emoji: s.emoji });
        break;
      case "wait":
        ops.push({ k: "wait", dur: s.duration ?? 900 });
        break;
    }
  }
  return ops;
}

interface Runtime {
  x: MotionValue<number>;
  y: MotionValue<number>;
  scale: MotionValue<number>;
  opacity: MotionValue<number>;
  selX: MotionValue<number>;
  selY: MotionValue<number>;
  selW: MotionValue<number>;
  selH: MotionValue<number>;
  selO: MotionValue<number>;
  bubbleO: MotionValue<number>;
  text: MotionValue<string>;
  pillX?: MotionValue<number>;
  pillY?: MotionValue<number>;
  ops: Op[];
  seed: number;
  rng: () => number;
  phase: "intro" | "run" | "done";
  i: number;
  /** Current step has finished; waiting for permission to start the next. */
  pending: boolean;
  stepStart: number;
  base: Vec;
  from: Vec;
  to: Vec;
  ctrl: Vec;
  dur: number;
  selTarget: number;
  bubbleTarget: number;
  drift: number;
  driftPhase: number;
  gen: number;
  /** Last resolved destination spec, re-resolved on resize. */
  rest: { to: CohortTarget; anchor: CohortPoint } | null;
  selSpec: string | CohortRect | null;
}

interface Fx {
  id: number;
  kind: "ripple" | "react";
  x: number;
  y: number;
  color: string;
  emoji?: string;
}

function isRect(t: CohortTarget): t is CohortRect {
  return typeof t !== "string" && t.length === 4;
}

/**
 * Cohort — fake live collaboration for marketing heroes. A handful of named
 * pointers (arrow + name pill in their color) act out looping scripts over
 * the children: gliding along curved, slightly overshooting paths, clicking
 * with ripples, dragging translucent selections, typing comment bubbles and
 * floating emoji reactions. Scripts run concurrently; pointer positions are
 * driven by motion values (no per-frame React renders) and the name pill
 * trails on a softer spring. Targets resolve from percent coordinates or
 * `[data-cohort]` elements inside the children, measured relative to the
 * container and re-measured on resize. When the visitor's pointer enters,
 * cursors finish their current step and idle with a subtle drift, resuming
 * 1.5s after it leaves. The overlay is `aria-hidden` and pointer-transparent;
 * playback pauses offscreen and on hidden tabs. Under reduced motion the
 * cursors park at their first targets with their name pills — no motion.
 */
export function Cohort({
  children,
  className,
  cursors = DEFAULT_CURSORS,
  loop = true,
  speedScale = 1,
  pauseOnPointer = true,
  paused = false,
  ref,
  onPointerEnter,
  onPointerLeave,
  ...props
}: CohortProps) {
  const reducedMotion = useReducedMotion();
  const [fx, setFx] = React.useState<Fx[]>([]);
  const fxId = React.useRef(0);

  // Scripts are plain data: key on their content so inline literals don't reset playback.
  const cursorsKey = JSON.stringify(cursors);
  const scriptHash = hashString(cursorsKey);
  const runtimes = React.useMemo<Runtime[]>(
    () =>
      cursors.map((c, idx) => {
        const seed = hashString(`${c.name}:${idx}`);
        const rng = mulberry32(seed);
        return {
          x: motionValue(0),
          y: motionValue(0),
          scale: motionValue(1),
          opacity: motionValue(0),
          selX: motionValue(0),
          selY: motionValue(0),
          selW: motionValue(0),
          selH: motionValue(0),
          selO: motionValue(0),
          bubbleO: motionValue(0),
          text: motionValue(""),
          ops: compile(c.script),
          seed,
          rng,
          phase: "intro",
          i: 0,
          pending: true,
          stepStart: 0,
          base: { x: 0, y: 0 },
          from: { x: 0, y: 0 },
          to: { x: 0, y: 0 },
          ctrl: { x: 0, y: 0 },
          dur: 0,
          selTarget: 0,
          bubbleTarget: 0,
          drift: 1,
          driftPhase: rng() * Math.PI * 2,
          gen: 0,
          rest: null,
          selSpec: null,
        };
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [cursorsKey]
  );

  const live = React.useRef({
    clock: 0,
    real: 0,
    last: -1,
    inside: false,
    leftAt: -Infinity,
    size: { w: 0, h: 0 },
    gen: 0,
  });
  const opts = React.useRef({ loop, speedScale, pauseOnPointer, cursors, reducedMotion });
  opts.current = { loop, speedScale, pauseOnPointer, cursors, reducedMotion };

  const containerRef = useVisibilityPause<HTMLDivElement>((elapsed) => tick(elapsed), {
    paused: reducedMotion || paused,
  });

  // --- target resolution (container-relative px) -----------------------------
  const resolveBox = React.useCallback((t: CohortTarget): Box => {
    const { w, h } = live.current.size;
    if (typeof t !== "string") {
      if (isRect(t)) return { x: (t[0] / 100) * w, y: (t[1] / 100) * h, w: (t[2] / 100) * w, h: (t[3] / 100) * h };
      return { x: (t[0] / 100) * w, y: (t[1] / 100) * h, w: 0, h: 0 };
    }
    const root = containerRef.current;
    let el: Element | null = null;
    if (root) {
      const sel = /^[\w-]+$/.test(t) ? `[data-cohort="${t}"]` : t;
      try {
        el = root.querySelector(sel);
      } catch {
        el = null;
      }
    }
    if (!root || !el) return { x: w / 2, y: h / 2, w: 0, h: 0 };
    const rr = root.getBoundingClientRect();
    const er = el.getBoundingClientRect();
    return { x: er.left - rr.left, y: er.top - rr.top, w: er.width, h: er.height };
  }, [containerRef]);

  const resolvePoint = React.useCallback(
    (t: CohortTarget, anchor: CohortPoint): Vec => {
      const b = resolveBox(t);
      return { x: b.x + b.w * anchor[0], y: b.y + b.h * anchor[1] };
    },
    [resolveBox]
  );

  const spawn = React.useCallback((f: Omit<Fx, "id">) => {
    const id = ++fxId.current;
    setFx((prev) => [...prev.slice(-11), { ...f, id }]);
  }, []);

  const teleport = (r: Runtime, p: Vec) => {
    r.base = { ...p };
    r.x.jump(p.x);
    r.y.jump(p.y);
    r.pillX?.jump(p.x);
    r.pillY?.jump(p.y);
  };

  const clearMarks = (r: Runtime, hard: boolean) => {
    r.selTarget = 0;
    r.bubbleTarget = 0;
    if (hard) {
      r.selO.set(0);
      r.bubbleO.set(0);
      r.text.set("");
    }
  };

  const firstTarget = (r: Runtime) => {
    const first = r.ops.find((o) => o.k === "move") as Extract<Op, { k: "move" }> | undefined;
    return first ? { to: first.to, anchor: first.anchor } : null;
  };

  const measure = () => {
    const el = containerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    live.current.size = { w: rect.width, h: rect.height };
  };

  /** Park every cursor at its first target, fully visible (reduced motion / paused-from-start frame). */
  const placeStatic = () => {
    measure();
    for (const r of runtimes) {
      const t = firstTarget(r);
      const p = t ? resolvePoint(t.to, t.anchor) : { x: live.current.size.w / 2, y: live.current.size.h / 2 };
      teleport(r, p);
      r.rest = t;
      r.opacity.set(1);
      r.scale.set(1);
      clearMarks(r, true);
      r.phase = "run";
      r.i = 0;
      r.pending = true;
      r.drift = 1;
    }
  };

  /** Fresh start: cursors wait offstage-adjacent, then fade in staggered and run. */
  const reset = () => {
    measure();
    const L = live.current;
    L.clock = 0;
    L.last = -1;
    for (const r of runtimes) {
      r.rng = mulberry32(r.seed);
      const t = firstTarget(r);
      const p = t ? resolvePoint(t.to, t.anchor) : { x: L.size.w / 2, y: L.size.h / 2 };
      const ang = r.rng() * Math.PI * 2;
      const dist = 60 + r.rng() * 70;
      teleport(r, {
        x: clamp(p.x + Math.cos(ang) * dist, 12, Math.max(12, L.size.w - 60)),
        y: clamp(p.y + Math.sin(ang) * dist, 12, Math.max(12, L.size.h - 40)),
      });
      r.rest = null;
      r.selSpec = null;
      r.opacity.set(0);
      r.scale.set(1);
      clearMarks(r, true);
      r.phase = "intro";
      r.i = 0;
      r.pending = true;
      r.drift = 1;
      r.gen = L.gen;
    }
    setFx([]);
  };

  const beginStep = (r: Runtime, now: number) => {
    const o = opts.current;
    if (r.i >= r.ops.length) {
      if (!o.loop || r.ops.length === 0) {
        r.phase = "done";
        return;
      }
      r.i = 0;
      clearMarks(r, false);
    }
    const op = r.ops[r.i];
    r.pending = false;
    r.stepStart = now;
    const color = o.cursors[runtimes.indexOf(r)]?.color ?? "#fff";
    switch (op.k) {
      case "move": {
        clearMarks(r, false);
        r.from = { ...r.base };
        r.to = resolvePoint(op.to, op.anchor);
        r.rest = { to: op.to, anchor: op.anchor };
        const dx = r.to.x - r.from.x;
        const dy = r.to.y - r.from.y;
        const dist = Math.hypot(dx, dy);
        const bend = dist * (0.12 + r.rng() * 0.16) * (r.rng() < 0.5 ? -1 : 1);
        const nx = dist > 0 ? -dy / dist : 0;
        const ny = dist > 0 ? dx / dist : 0;
        r.ctrl = { x: (r.from.x + r.to.x) / 2 + nx * bend, y: (r.from.y + r.to.y) / 2 + ny * bend };
        r.dur = op.dur ?? clamp(520 + dist * 0.9, 500, 1500);
        if (dist < 3) r.dur = Math.min(r.dur, 200);
        break;
      }
      case "drag": {
        const b = resolveBox(op.target);
        r.from = { x: b.x, y: b.y };
        r.to = { x: b.x + b.w, y: b.y + b.h };
        r.selSpec = op.target;
        r.rest = { to: op.target, anchor: [1, 1] };
        r.dur = op.dur;
        r.selX.set(b.x);
        r.selY.set(b.y);
        r.selW.set(0);
        r.selH.set(0);
        r.selO.set(0);
        r.selTarget = 1;
        break;
      }
      case "click":
        r.dur = CLICK_MS;
        spawn({ kind: "ripple", x: r.base.x, y: r.base.y, color });
        break;
      case "type":
        r.text.set("");
        r.bubbleTarget = 1;
        r.dur = op.dur + op.hold;
        break;
      case "react":
        r.dur = 520;
        spawn({ kind: "react", x: r.base.x, y: r.base.y, color, emoji: op.emoji });
        break;
      case "wait":
        r.dur = op.dur;
        break;
    }
  };

  function tick(elapsed: number) {
    const L = live.current;
    const o = opts.current;
    const dt = L.last < 0 ? 0 : clamp(elapsed - L.last, 0, 0.1);
    L.last = elapsed;
    L.real += dt;
    L.clock += dt * Math.max(0, o.speedScale);
    const now = L.clock;
    const smooth = 1 - Math.exp(-dt * 9);
    const canAdvance = !o.pauseOnPointer || (!L.inside && L.real - L.leftAt >= RESUME_DELAY);

    runtimes.forEach((r, idx) => {
      // Re-measure after a resize: snap parked cursors / retarget the live move.
      if (r.gen !== L.gen) {
        r.gen = L.gen;
        const op = r.ops[r.i];
        if (!r.pending && op?.k === "move") {
          r.to = resolvePoint(op.to, op.anchor);
        } else if (r.rest && !(op?.k === "drag" && !r.pending)) {
          r.base = resolvePoint(r.rest.to, r.rest.anchor);
        }
        if (r.selSpec && r.selTarget > 0 && !(op?.k === "drag" && !r.pending)) {
          const b = resolveBox(r.selSpec);
          r.selX.set(b.x);
          r.selY.set(b.y);
          r.selW.set(b.w);
          r.selH.set(b.h);
        }
      }

      if (r.phase === "intro") {
        const t = now - idx * INTRO_STAGGER;
        r.opacity.set(clamp(t / INTRO_FADE, 0, 1));
        if (t >= INTRO_FADE) r.phase = "run";
      }

      let moving = false;
      if (r.phase === "run") {
        if (r.pending && canAdvance) beginStep(r, now);
        const op = r.ops[r.i];
        if (r.phase === "run" && !r.pending && op) {
          const ms = (now - r.stepStart) * 1000;
          const s = r.dur > 0 ? ms / r.dur : 1;
          switch (op.k) {
            case "move": {
              moving = true;
              const p = springEase(Math.min(s, 1));
              const q = 1 - p;
              r.base =
                s >= 1
                  ? { ...r.to }
                  : {
                      x: q * q * r.from.x + 2 * q * p * r.ctrl.x + p * p * r.to.x,
                      y: q * q * r.from.y + 2 * q * p * r.ctrl.y + p * p * r.to.y,
                    };
              break;
            }
            case "drag": {
              moving = true;
              const e = easeInOut(clamp(s, 0, 1));
              r.base = { x: r.from.x + (r.to.x - r.from.x) * e, y: r.from.y + (r.to.y - r.from.y) * e };
              r.selW.set(Math.max(0, r.base.x - r.from.x));
              r.selH.set(Math.max(0, r.base.y - r.from.y));
              break;
            }
            case "click":
              r.scale.set(1 - 0.18 * Math.sin(Math.PI * clamp(s, 0, 1)));
              break;
            case "type": {
              const n = Math.floor(op.text.length * clamp(op.dur > 0 ? ms / op.dur : 1, 0, 1));
              if (r.text.get().length !== n) r.text.set(op.text.slice(0, n));
              break;
            }
            default:
              break;
          }
          if (s >= 1) {
            if (op.k === "click") r.scale.set(1);
            r.i += 1;
            r.pending = true;
            if (canAdvance) beginStep(r, now);
          }
        }
      }

      // Subtle human drift whenever the pointer isn't travelling.
      r.drift += ((moving ? 0 : 1) - r.drift) * (1 - Math.exp(-dt * 3));
      const ph = r.driftPhase;
      const dx = Math.sin(L.real * 0.9 + ph) * 3.2 * r.drift;
      const dy = Math.sin(L.real * 1.3 + ph * 1.7) * 2.4 * r.drift;
      r.x.set(r.base.x + dx);
      r.y.set(r.base.y + dy);

      r.selO.set(r.selO.get() + (r.selTarget - r.selO.get()) * smooth);
      const bo = r.bubbleO.get() + (r.bubbleTarget - r.bubbleO.get()) * smooth;
      r.bubbleO.set(bo);
      if (r.bubbleTarget === 0 && bo < 0.02 && r.text.get() !== "") r.text.set("");
    });
  }

  // Mount / script change / motion preference: lay out the opening frame.
  React.useLayoutEffect(() => {
    if (reducedMotion) placeStatic();
    else if (paused && live.current.clock === 0) placeStatic();
    else if (live.current.clock === 0) reset();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runtimes, reducedMotion]);

  React.useEffect(() => {
    if (paused && !reducedMotion && live.current.clock === 0) placeStatic();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [paused]);

  // Container-relative measurement: re-measure on resize; ticks re-resolve targets.
  React.useEffect(() => {
    const el = containerRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(() => {
      measure();
      live.current.gen += 1;
      if (opts.current.reducedMotion) placeStatic();
    });
    ro.observe(el);
    return () => ro.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runtimes]);

  React.useImperativeHandle(
    ref,
    () => ({
      restart: () => {
        if (opts.current.reducedMotion) placeStatic();
        else reset();
      },
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [runtimes]
  );

  const removeFx = React.useCallback((id: number) => {
    setFx((prev) => prev.filter((f) => f.id !== id));
  }, []);

  return (
    <div
      ref={containerRef}
      data-crucible="cohort"
      className={cn("relative isolate", className)}
      onPointerEnter={(e) => {
        live.current.inside = true;
        onPointerEnter?.(e);
      }}
      onPointerLeave={(e) => {
        live.current.inside = false;
        live.current.leftAt = live.current.real;
        onPointerLeave?.(e);
      }}
      {...props}
    >
      {children}
      <div aria-hidden className="pointer-events-none absolute inset-0 z-30 select-none">
        {runtimes.map((r, i) => {
          const c = cursors[i];
          if (!c) return null;
          return (
            <motion.div
              key={`sel-${i}`}
              className="absolute left-0 top-0 rounded-[3px]"
              style={{
                x: r.selX,
                y: r.selY,
                width: r.selW,
                height: r.selH,
                opacity: r.selO,
                backgroundColor: `color-mix(in srgb, ${c.color} 16%, transparent)`,
                boxShadow: `inset 0 0 0 1px color-mix(in srgb, ${c.color} 55%, transparent)`,
              }}
            />
          );
        })}
        {fx.map((f) =>
          f.kind === "ripple" ? (
            <motion.span
              key={f.id}
              className="absolute block size-9 rounded-full"
              style={{ left: f.x - 18, top: f.y - 18, boxShadow: `0 0 0 1.5px ${f.color}` }}
              initial={{ scale: 0.2, opacity: 0.9 }}
              animate={{ scale: 1.1, opacity: 0 }}
              transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
              onAnimationComplete={() => removeFx(f.id)}
            />
          ) : (
            <motion.span
              key={f.id}
              className="absolute block text-xl leading-none"
              style={{ left: f.x + 6, top: f.y - 22 }}
              initial={{ y: 0, opacity: 0, scale: 0.6 }}
              animate={{ y: -58, opacity: [0, 1, 1, 0], scale: [0.6, 1.15, 1, 0.95] }}
              transition={{ duration: 1.5, ease: "easeOut", times: [0, 0.18, 0.7, 1] }}
              onAnimationComplete={() => removeFx(f.id)}
            >
              {f.emoji}
            </motion.span>
          )
        )}
        {runtimes.map((r, i) => {
          const c = cursors[i];
          if (!c) return null;
          return <CohortPointer key={`ptr-${scriptHash}-${i}`} runtime={r} cursor={c} still={reducedMotion} />;
        })}
      </div>
    </div>
  );
}

function CohortPointer({ runtime: r, cursor, still }: { runtime: Runtime; cursor: CohortCursor; still: boolean }) {
  const springX = useSpring(r.x, PILL_SPRING);
  const springY = useSpring(r.y, PILL_SPRING);
  React.useLayoutEffect(() => {
    r.pillX = springX;
    r.pillY = springY;
    springX.jump(r.x.get());
    springY.jump(r.y.get());
    return () => {
      r.pillX = undefined;
      r.pillY = undefined;
    };
  }, [r, springX, springY]);

  const pillX = still ? r.x : springX;
  const pillY = still ? r.y : springY;

  return (
    <>
      <motion.div
        className="absolute left-0 top-0"
        style={{ x: pillX, y: pillY, opacity: r.opacity }}
      >
        <div className="absolute left-[13px] top-[19px] flex flex-col items-start gap-1">
          <span
            className="whitespace-nowrap rounded-full px-2 py-[3px] text-[11px] font-medium leading-none shadow-[0_2px_8px_rgba(0,0,0,0.35)]"
            style={{ backgroundColor: cursor.color, color: inkOn(cursor.color) }}
          >
            {cursor.name}
          </span>
          <motion.div
            className="w-max max-w-[190px] rounded-xl rounded-tl-sm border border-white/10 bg-neutral-900/95 px-2.5 py-1.5 text-xs leading-snug text-neutral-100 shadow-[0_6px_20px_rgba(0,0,0,0.45)]"
            style={{ opacity: r.bubbleO }}
          >
            <motion.span>{r.text}</motion.span>
            <span
              className="ml-px inline-block h-[0.9em] w-px translate-y-[0.12em] animate-pulse"
              style={{ backgroundColor: cursor.color }}
            />
          </motion.div>
        </div>
      </motion.div>
      <motion.div
        className="absolute left-0 top-0"
        style={{ x: r.x, y: r.y, scale: r.scale, opacity: r.opacity, transformOrigin: "0px 0px" }}
      >
        <svg
          width="20"
          height="22"
          viewBox="0 0 20 22"
          className="-ml-[2px] -mt-[2px] block drop-shadow-[0_2px_4px_rgba(0,0,0,0.45)]"
        >
          <path
            d="M2 2 L2 18.5 L6.4 14.6 L9.3 21 L12.1 19.8 L9.3 13.5 L15.2 13.2 Z"
            fill={cursor.color}
            stroke="rgba(10,10,10,0.85)"
            strokeWidth="1.1"
            strokeLinejoin="round"
          />
        </svg>
      </motion.div>
    </>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface ContourProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Two tones `[line, accent]`. `line` colors the thin minor contour lines;
   * `accent` colors the bolder index line (every fifth contour) and tints the
   * soft elevation bands toward the peaks. Defaults to a cool cartographic
   * slate-on-ice. Pass warm tones for a topographic-heat look.
   * @default ["#64788f", "#dbe9fb"]
   */
  colors?: [string, string];
  /** Morph-speed multiplier — how fast the terrain evolves. 1 = default. @default 1 */
  speed?: number;
  /** Line brightness / opacity, 0–2. @default 1 */
  intensity?: number;
  /**
   * Spacing between contour lines in CSS px — the elevation interval. Smaller =
   * denser lines (steep terrain read), larger = sparse. Clamped 12–80.
   * @default 28
   */
  lineGap?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /** Freeze the map at a static, fully-drawn topographic frame. @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: [string, string] = ["#64788f", "#dbe9fb"];

/** Cool near-black valley floor the map sits on — never flat #000. */
const BG_RGB: [number, number, number] = [6, 9, 14];

/** Spatial size of one terrain "hill" in CSS px — sets feature scale. */
const FEATURE_PX = 300;
/** Target grid cell size in CSS px — finer = smoother contours, more cost. */
const CELL_PX = 14;
/** fBm octaves — 3 gives ridged terrain without going heavy. */
const OCTAVES = 3;
/** How fast the noise field morphs through its third (time) dimension. */
const Z_RATE = 0.12;
/** A slow horizontal drift so the map also creeps, not only morphs. */
const DRIFT_RATE = 0.015;
/** Frozen z-slice for the reduced-motion / paused frame (a handsome terrain). */
const Z_STATIC = 3.7;
/** Every Nth contour is promoted to a bold accent index line. */
const INDEX_EVERY = 5;

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [100, 120, 143];
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

/** Integer hash → [0,1), stable across SSR intent and client. */
function hash3(ix: number, iy: number, iz: number, seed: number): number {
  let h = seed >>> 0;
  h = Math.imul(h ^ (ix | 0), 0x27d4eb2f);
  h = Math.imul(h ^ (iy | 0), 0x85ebca6b);
  h = Math.imul(h ^ (iz | 0), 0xc2b2ae35);
  h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}

function fade(t: number): number {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Trilinear value noise in 3D — smooth, seeded, morphs along z. */
function vnoise3(x: number, y: number, z: number, seed: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const iz = Math.floor(z);
  const ux = fade(x - ix);
  const uy = fade(y - iy);
  const uz = fade(z - iz);

  const c000 = hash3(ix, iy, iz, seed);
  const c100 = hash3(ix + 1, iy, iz, seed);
  const c010 = hash3(ix, iy + 1, iz, seed);
  const c110 = hash3(ix + 1, iy + 1, iz, seed);
  const c001 = hash3(ix, iy, iz + 1, seed);
  const c101 = hash3(ix + 1, iy, iz + 1, seed);
  const c011 = hash3(ix, iy + 1, iz + 1, seed);
  const c111 = hash3(ix + 1, iy + 1, iz + 1, seed);

  const x00 = lerp(c000, c100, ux);
  const x10 = lerp(c010, c110, ux);
  const x01 = lerp(c001, c101, ux);
  const x11 = lerp(c011, c111, ux);
  const y0 = lerp(x00, x10, uy);
  const y1 = lerp(x01, x11, uy);
  return lerp(y0, y1, uz);
}

/** Fractal value noise, normalized to ~[0,1]. */
function fbm(x: number, y: number, z: number, seed: number): number {
  let amp = 0.5;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let o = 0; o < OCTAVES; o++) {
    sum += amp * vnoise3(x * freq, y * freq, z * freq + o * 13.7, seed + o * 101);
    norm += amp;
    amp *= 0.5;
    freq *= 2;
  }
  return sum / norm;
}

interface Internals {
  ctx: CanvasRenderingContext2D;
  width: number;
  height: number;
  gx: number;
  gy: number;
  cw: number;
  ch: number;
  stepX: number;
  stepY: number;
  field: Float32Array;
  cellMin: Float32Array;
  cellMax: Float32Array;
  fieldCanvas: HTMLCanvasElement;
  fieldCtx: CanvasRenderingContext2D;
  imgData: ImageData;
  levels: number[];
  lineRgb: [number, number, number];
  accentRgb: [number, number, number];
  peakRgb: [number, number, number];
  intensity: number;
  speed: number;
  seed: number;
  /** Speed-scaled terrain clock, accumulated per frame so speed changes never jump. */
  phase: number;
  lastElapsed: number;
}

/** Elevation range the contour levels span (trims dead edges of the field). */
const LO = 0.08;
const HI = 0.92;

function buildLevels(lineGap: number): number[] {
  // px spacing → contour count. 28px → ~13 lines; larger gap → fewer.
  const count = Math.min(48, Math.max(5, Math.round(360 / lineGap)));
  const span = HI - LO;
  const out: number[] = [];
  for (let k = 0; k < count; k++) out.push(LO + ((k + 0.5) / count) * span);
  return out;
}

/** Recompute the scalar terrain field for the whole grid at time-slice z. */
function computeField(it: Internals, z: number, driftX: number) {
  const { field, gx, gy, stepX, stepY, seed } = it;
  const cols = gx + 1;
  for (let j = 0; j <= gy; j++) {
    const wy = j * stepY;
    const row = j * cols;
    for (let i = 0; i <= gx; i++) {
      field[row + i] = fbm(i * stepX + driftX, wy, z, seed);
    }
  }
  // Per-cell min/max so the contour pass can cheaply skip cells no level crosses.
  const { cellMin, cellMax } = it;
  for (let j = 0; j < gy; j++) {
    const r0 = j * cols;
    const r1 = r0 + cols;
    for (let i = 0; i < gx; i++) {
      const a = field[r0 + i];
      const b = field[r0 + i + 1];
      const c = field[r1 + i + 1];
      const d = field[r1 + i];
      let mn = a;
      let mx = a;
      if (b < mn) mn = b;
      else if (b > mx) mx = b;
      if (c < mn) mn = c;
      else if (c > mx) mx = c;
      if (d < mn) mn = d;
      else if (d > mx) mx = d;
      const ci = j * gx + i;
      cellMin[ci] = mn;
      cellMax[ci] = mx;
    }
  }
}

/** Paint the soft, posterized elevation bands beneath the lines. */
function paintBands(it: Internals) {
  const { field, gx, gy, imgData, peakRgb } = it;
  const cols = gx + 1;
  const data = imgData.data;
  const span = HI - LO;
  // Band edges land on every ~3rd contour, so plateaus read as "filled bands".
  const bands = Math.max(3, Math.round(it.levels.length / 3));
  const [pr, pg, pb] = peakRgb;
  const [br, bg, bb] = BG_RGB;
  for (let j = 0; j <= gy; j++) {
    const row = j * cols;
    for (let i = 0; i <= gx; i++) {
      const v = field[row + i];
      // Normalize into the drawn elevation range, posterize into bands.
      let t = (v - LO) / span;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      const shade = Math.floor(t * bands) / bands;
      const p = (row + i) * 4;
      data[p] = br + (pr - br) * shade;
      data[p + 1] = bg + (pg - bg) * shade;
      data[p + 2] = bb + (pb - bb) * shade;
      data[p + 3] = 255;
    }
  }
  it.fieldCtx.putImageData(imgData, 0, 0);
  it.ctx.imageSmoothingEnabled = true;
  it.ctx.drawImage(it.fieldCanvas, 0, 0, it.width, it.height);
}

/** Add the marching-squares segment(s) for one cell at one level to the path. */
function addCellSegments(
  path: Path2D,
  L: number,
  x0: number,
  y0: number,
  cw: number,
  ch: number,
  vtl: number,
  vtr: number,
  vbr: number,
  vbl: number
) {
  const x1 = x0 + cw;
  const y1 = y0 + ch;
  // Edge crossing helpers (only the ones a case needs are evaluated).
  const top = () => {
    const d = vtr - vtl;
    return x0 + cw * (Math.abs(d) < 1e-6 ? 0.5 : (L - vtl) / d);
  };
  const bottom = () => {
    const d = vbr - vbl;
    return x0 + cw * (Math.abs(d) < 1e-6 ? 0.5 : (L - vbl) / d);
  };
  const left = () => {
    const d = vbl - vtl;
    return y0 + ch * (Math.abs(d) < 1e-6 ? 0.5 : (L - vtl) / d);
  };
  const right = () => {
    const d = vbr - vtr;
    return y0 + ch * (Math.abs(d) < 1e-6 ? 0.5 : (L - vtr) / d);
  };

  const code =
    (vtl > L ? 8 : 0) | (vtr > L ? 4 : 0) | (vbr > L ? 2 : 0) | (vbl > L ? 1 : 0);

  switch (code) {
    case 1: // BL
    case 14: // ~BL
      path.moveTo(x0, left());
      path.lineTo(bottom(), y1);
      break;
    case 2: // BR
    case 13: // ~BR
      path.moveTo(bottom(), y1);
      path.lineTo(x1, right());
      break;
    case 3: // BL+BR
    case 12: // TL+TR
      path.moveTo(x0, left());
      path.lineTo(x1, right());
      break;
    case 4: // TR
    case 11: // ~TR
      path.moveTo(top(), y0);
      path.lineTo(x1, right());
      break;
    case 6: // TR+BR
    case 9: // TL+BL
      path.moveTo(top(), y0);
      path.lineTo(bottom(), y1);
      break;
    case 7: // ~TL
    case 8: // TL
      path.moveTo(top(), y0);
      path.lineTo(x0, left());
      break;
    case 5: // TR+BL saddle
      path.moveTo(top(), y0);
      path.lineTo(x0, left());
      path.moveTo(bottom(), y1);
      path.lineTo(x1, right());
      break;
    case 10: // TL+BR saddle
      path.moveTo(top(), y0);
      path.lineTo(x1, right());
      path.moveTo(x0, left());
      path.lineTo(bottom(), y1);
      break;
    default: // 0 or 15 — no crossing
      break;
  }
}

/** One frame. `useStatic` renders the frozen z-slice with no drift. */
function draw(it: Internals, useStatic: boolean) {
  const z = useStatic ? Z_STATIC : it.phase * Z_RATE;
  const driftX = useStatic ? 0 : it.phase * DRIFT_RATE;

  computeField(it, z, driftX);

  // Elevation bands first (opaque base), then the crisp lines on top.
  paintBands(it);

  const { ctx, field, gx, gy, cw, ch, cellMin, cellMax, levels } = it;
  const cols = gx + 1;
  const gInt = Math.min(Math.max(it.intensity, 0), 2);
  ctx.imageSmoothingEnabled = true;
  ctx.lineJoin = "round";
  ctx.lineCap = "round";

  for (let li = 0; li < levels.length; li++) {
    const L = levels[li];
    const isIndex = li % INDEX_EVERY === Math.floor(INDEX_EVERY / 2);
    const rgb = isIndex ? it.accentRgb : it.lineRgb;
    const alpha = Math.min((isIndex ? 0.92 : 0.5) * gInt, 1);
    if (alpha < 0.01) continue;

    const path = new Path2D();
    for (let j = 0; j < gy; j++) {
      const r0 = j * cols;
      const r1 = r0 + cols;
      const y0 = j * ch;
      for (let i = 0; i < gx; i++) {
        const ci = j * gx + i;
        if (L < cellMin[ci] || L > cellMax[ci]) continue;
        addCellSegments(
          path,
          L,
          i * cw,
          y0,
          cw,
          ch,
          field[r0 + i],
          field[r0 + i + 1],
          field[r1 + i + 1],
          field[r1 + i]
        );
      }
    }
    ctx.strokeStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;
    ctx.lineWidth = isIndex ? 1.5 : 1;
    ctx.stroke(path);
  }
}

/**
 * Contour — a living topographic map. Elevation contour lines traced by
 * marching-squares over an evolving 3D value-noise terrain: thin minor lines
 * with a bolder accent index line every fifth level, laid over soft posterized
 * elevation bands that read as filled plateaus. The whole field slowly morphs
 * and drifts like a survey map redrawing itself. Canvas 2D: seeded and
 * SSR-safe, paused offscreen and on hidden tabs, DPR-clamped, reduced-motion-
 * safe (a static, fully-drawn terrain). Drop it inside any `relative` container.
 */
export function Contour({
  colors = DEFAULT_COLORS,
  speed = 1,
  intensity = 1,
  lineGap = 28,
  dpr = 2,
  paused = false,
  className,
  ...props
}: ContourProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();
  const staticFrame = paused || reducedMotion;
  const staticFrameRef = React.useRef(staticFrame);
  staticFrameRef.current = staticFrame;

  const gap = Math.min(Math.max(lineGap, 12), 80);
  const colorsKey = colors.join(",");

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it) return;
    let dt = elapsed - it.lastElapsed;
    it.lastElapsed = elapsed;
    if (dt > 0.1) dt = 0.1; // clamp tab-restore jumps
    if (dt < 0) dt = 0;
    it.phase += dt * it.speed;
    draw(it, staticFrameRef.current);
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: staticFrame });

  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;

    const effectiveDpr = Math.min(
      typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1,
      Math.min(Math.max(dpr, 1), 2)
    );

    const lineRgb = hexToRgb(colors[0]);
    const accentRgb = hexToRgb(colors[1]);
    // Sunlit-peak tint: a dim wash of the accent hue over the valley floor.
    const peakRgb: [number, number, number] = [
      Math.min(255, (BG_RGB[0] + accentRgb[0] * 0.15) | 0),
      Math.min(255, (BG_RGB[1] + accentRgb[1] * 0.15) | 0),
      Math.min(255, (BG_RGB[2] + accentRgb[2] * 0.15) | 0),
    ];

    const fieldCanvas = document.createElement("canvas");
    const fieldCtx = fieldCanvas.getContext("2d", { alpha: false });
    if (!fieldCtx) return;

    const it: Internals = {
      ctx,
      width: 0,
      height: 0,
      gx: 0,
      gy: 0,
      cw: 0,
      ch: 0,
      stepX: 0,
      stepY: 0,
      field: new Float32Array(0),
      cellMin: new Float32Array(0),
      cellMax: new Float32Array(0),
      fieldCanvas,
      fieldCtx,
      imgData: fieldCtx.createImageData(1, 1),
      levels: buildLevels(gap),
      lineRgb,
      accentRgb,
      peakRgb,
      intensity,
      speed,
      seed: 0x1234,
      phase: internalsRef.current?.phase ?? 0,
      lastElapsed: internalsRef.current?.lastElapsed ?? 0,
    };
    internalsRef.current = it;

    const onContextLost = (e: Event) => e.preventDefault();
    canvas.addEventListener("contextlost", onContextLost);

    const resize = () => {
      const w = Math.max(container.clientWidth, 1);
      const h = Math.max(container.clientHeight, 1);
      canvas.width = Math.round(w * effectiveDpr);
      canvas.height = Math.round(h * effectiveDpr);
      canvas.style.width = "100%";
      canvas.style.height = "100%";
      ctx.setTransform(effectiveDpr, 0, 0, effectiveDpr, 0, 0);

      const gx = Math.min(200, Math.max(8, Math.round(w / CELL_PX)));
      const gy = Math.min(200, Math.max(8, Math.round(h / CELL_PX)));
      it.width = w;
      it.height = h;
      it.gx = gx;
      it.gy = gy;
      it.cw = w / gx;
      it.ch = h / gy;
      // Isotropic feature scale regardless of grid resolution.
      it.stepX = (w / FEATURE_PX) / gx;
      it.stepY = (h / FEATURE_PX) / gy;
      it.field = new Float32Array((gx + 1) * (gy + 1));
      it.cellMin = new Float32Array(gx * gy);
      it.cellMax = new Float32Array(gx * gy);
      fieldCanvas.width = gx + 1;
      fieldCanvas.height = gy + 1;
      it.imgData = fieldCtx.createImageData(gx + 1, gy + 1);

      // Never flash empty — paint one frame immediately.
      draw(it, staticFrameRef.current);
    };

    const ro = new ResizeObserver(resize);
    ro.observe(container);
    resize();

    return () => {
      ro.disconnect();
      canvas.removeEventListener("contextlost", onContextLost);
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dpr, gap, colorsKey]);

  // Live-sync speed / intensity without rebuilding the map.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it) return;
    it.speed = speed;
    it.intensity = intensity;
    if (staticFrameRef.current) draw(it, true);
  }, [speed, intensity]);

  // Re-render the frozen frame in place when paused / reduced-motion toggles.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !staticFrame) return;
    draw(it, true);
  }, [staticFrame]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="contour"
      className={cn("absolute inset-0 -z-10 overflow-hidden bg-neutral-950", className)}
      {...props}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
      {/* Soft vignette so the map sinks into the frame edges. */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 120% at 50% 42%, transparent 58%, rgba(0,0,0,0.5) 100%)",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface CoalesceProps {
  /** Number of drifting cores, clamped 1–10. The pointer adds one more. Default 5. */
  count?: number;
  /**
   * Chrome pair `[shadow, highlight]`: the dark reflection tone and the
   * bright sky tone the surface mirrors. Any hex strings. Defaults to
   * mercury — silvery monochrome.
   */
  colors?: [string, string];
  /** Drift speed multiplier. 1 = default. */
  speed?: number;
  /** Base core radius as a fraction of the container's height. Default 0.16. */
  size?: number;
  /** Overall brightness of the surface shading. 1 = default. */
  intensity?: number;
  /** Freeze the animation, holding the current frame. */
  paused?: boolean;
  /**
   * Idle autoplay: after ~1.5s with no pointer present, a seeded ghost drifts
   * slowly across the field and carries the extra pointer core, so thumbnails
   * and heroes never look still; a real pointer takes over instantly. Never runs
   * under reduced motion. Default true.
   */
  idle?: boolean;
  /** Extra classes for the wrapper. Positioned `absolute inset-0 -z-10`. */
  className?: string;
}

const DEFAULT_COLORS: [string, string] = [
  "#262a31", // mercury shadow
  "#e9edf3", // mercury highlight
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.9, 0.92, 0.95];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Metaball fragment shader. Classic sum-of-inverse-square fields thresholded
 * with smoothstep into one liquid silhouette; the analytic field gradient
 * doubles as a height-field normal for mirror-chrome shading (sharp fake
 * horizon, circling key light, rim on the blend edge). The pointer carries
 * one extra core. GLSL ES 1.00, constant loop bounds, grain-dithered.
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive;

uniform vec3 uColorA; // shadow tone
uniform vec3 uColorB; // highlight tone
uniform float uCount;
uniform float uSpeed;
uniform float uSize;
uniform float uIntensity;

const int MAX_N = 10;

float hash11(float n) {
  return fract(sin(n * 127.1 + 311.7) * 43758.5453);
}

float hash21(vec2 p) {
  p = fract(p * vec2(217.13, 373.41));
  p += dot(p, p + 31.73);
  return fract(p.x * p.y);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2((vUv.x - 0.5) * aspect, vUv.y - 0.5);
  float t = uTime * uSpeed;
  float size = max(uSize, 0.02);
  int count = int(clamp(uCount, 1.0, float(MAX_N)));

  float f = 0.0;
  vec2 grad = vec2(0.0);

  // Sum of inverse-square fields, accumulating the analytic gradient
  // alongside for shading. Constant loop bound with an early break.
  for (int i = 0; i < MAX_N; i++) {
    if (i >= count) break;
    float fi = float(i);
    float h1 = hash11(fi + 1.0);
    float h2 = hash11(fi + 17.0);
    float h3 = hash11(fi + 43.0);
    float h4 = hash11(fi + 71.0);

    // Each core drifts a slow seeded lissajous orbit around its anchor.
    vec2 anchor = vec2((h1 - 0.5) * 0.8 * max(aspect, 1.0), (h2 - 0.5) * 0.5);
    vec2 amp = vec2(0.14 + 0.22 * h4, 0.10 + 0.18 * h3);
    vec2 c = anchor + amp * vec2(
      sin(t * (0.28 + 0.5 * h3) + h1 * 6.2832),
      cos(t * (0.22 + 0.45 * h4) + h2 * 6.2832)
    );

    float r = size * (0.55 + 0.7 * h3);
    vec2 d = p - c;
    float d2 = dot(d, d) + 1e-5;
    float r2 = r * r;
    f += r2 / d2;
    grad -= 2.0 * r2 * d / (d2 * d2);
  }

  // The pointer carries one extra core; the harness lerps uPointer, so it
  // trails with liquid lag and merges into the ambient field.
  vec2 pc = vec2((uPointer.x - 0.5) * aspect, uPointer.y - 0.5);
  vec2 pd = p - pc;
  // Shrinks away when the pointer leaves instead of parking at center.
  float pr = size * 0.8 * uPointerActive;
  float pd2 = dot(pd, pd) + 1e-5;
  f += pr * pr / pd2;
  grad -= 2.0 * pr * pr * pd / (pd2 * pd2);

  // Iso-surface: a crisp silhouette with a soft anti-aliased shoulder.
  float mask = smoothstep(1.0, 1.16, f);

  // Height-field normal: dividing the gradient by f^2 flattens the domes
  // over the cores and keeps the tilt strongest at the blend edge. At fusion
  // necks the raw slope spikes and, run through the sharp horizon term below,
  // used to trace hard sawtooth contours across the interior. Soft-limiting the
  // slope magnitude compresses those extreme neck values while leaving gentle
  // dome slopes untouched, so the mirror reads as smooth liquid, not terraced.
  vec2 gh = grad / (f * f);
  float ghLen = length(gh);
  gh /= 1.0 + ghLen * 0.6;
  vec3 n = normalize(vec3(-gh * size * 0.85, 1.0));

  // Mirror-chrome environment: bright sky above a soft dark horizon (a slightly
  // wider band than a razor edge — enough to read as a horizon, gentle enough
  // that rapid normal swings never quantize into hard steps).
  float envY = n.y + 0.28 * n.x;
  vec3 col = mix(uColorA, uColorB, smoothstep(-0.45, 0.6, envY));
  float horizon = exp(-abs(envY - 0.02) * 5.5);
  col = mix(col, uColorA * 0.45, horizon * 0.5);

  // One slowly circling key light for the moving specular glint.
  vec3 l = normalize(vec3(cos(t * 0.25) * 0.55, 0.7, 0.5));
  float spec = pow(max(dot(n, l), 0.0), 48.0);
  col += vec3(0.95, 0.97, 1.0) * spec * 0.9;

  // Silvery rim hugging the blend edge, where necks form and snap.
  float rim = smoothstep(1.0, 1.45, f) * (1.0 - smoothstep(1.45, 2.4, f));
  col += uColorB * rim * 0.28;

  col *= uIntensity;

  // Film-grain dithering kills banding in both color and the alpha edge.
  float grain = hash21(gl_FragCoord.xy + fract(t) * 61.0) - 0.5;
  col += grain * (2.0 / 255.0);
  float alpha = clamp(mask + grain * (1.5 / 255.0) * mask, 0.0, 1.0);

  gl_FragColor = vec4(max(col, 0.0), alpha);
}
`;

/**
 * Coalesce — a metaball field. Several blobby cores drift on slow seeded
 * orbits and fuse where they meet, rendered as one mercury-chrome liquid: a
 * mirror environment with a sharp horizon, a circling specular glint, and a
 * silvery rim on the blend edge. The pointer carries one extra core with
 * liquid lag. Transparent outside the surface, so it layers over any stage.
 * Built on the `ogl-canvas` harness: GPU-light, offscreen-paused,
 * reduced-motion-safe. Drop it inside any `relative` container; it fills
 * and sits behind content.
 */
export function Coalesce({
  count = 5,
  colors = DEFAULT_COLORS,
  speed = 1,
  size = 0.16,
  intensity = 1,
  paused = false,
  idle = true,
  className,
}: CoalesceProps) {
  const uniforms = React.useMemo(
    () => ({
      uColorA: { value: hexToRgb(colors[0]) },
      uColorB: { value: hexToRgb(colors[1]) },
      uCount: { value: count },
      uSpeed: { value: speed },
      uSize: { value: size },
      uIntensity: { value: intensity },
    }),
    [colors, count, speed, size, intensity]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="coalesce"
      className={cn("absolute inset-0 -z-10", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      reducedMotionTime={8}
      paused={paused}
      ghost={idle}
    />
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface DraftProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Blob colors, any hex color. Defaults to a soft slate / indigo / violet palette. */
  colors?: [string, string, string, string];
  /** Animation speed multiplier. 1 = default, 2 = twice as fast. */
  speed?: number;
  /** Freeze the animation at its current frame. */
  paused?: boolean;
  /**
   * Idle autoplay: after ~1.5s with no pointer present, a seeded ghost drifts
   * slowly across the field and leans the mesh, so thumbnails and heroes never
   * look still; a real pointer takes over instantly. Never runs under reduced
   * motion. Default true.
   */
  idle?: boolean;
  /**
   * Softness of the color fields. Kept in the same px scale as the original
   * CSS version for API compatibility (90 = default); internally it maps to a
   * shader smoothness uniform — lower values sharpen the mesh edges, higher
   * values melt them further together.
   */
  blur?: number;
}

const DEFAULT_COLORS: [string, string, string, string] = [
  "#64748b", // slate — the calm body of the mesh
  "#6366f1", // indigo — cool current
  "#1a1a2b", // deep — the base field everything floats on
  "#8b5cf6", // violet — soft bloom
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.39, 0.45, 0.55];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Original domain-warped fbm "fluid gradient mesh" fragment shader.
 * Three chained warp layers (q warps p, r warps p+q, f samples p+r) produce
 * slowly swirling, cloud-soft color fields rather than discrete blobs. Each
 * palette entry keys off a different warp field so the hues drift through one
 * another. Soft exponential tone curve so nothing clips, film-grain dithering
 * to defeat 8-bit banding. GLSL ES 1.00 (WebGL1/2 compatible).
 *
 * No fract() on spatial coordinates (only inside the hash), so there are no
 * wrap seams anywhere in the field.
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive; // eased 0-1 pointer/ghost presence

uniform vec3 uColor1; // slate — mesh body
uniform vec3 uColor2; // indigo — cool current
uniform vec3 uColor3; // deep — base field
uniform vec3 uColor4; // violet — bloom
uniform float uSpeed;
uniform float uSoftness; // 1 = default, from the blur prop

// --- compact value noise + fbm (original) ---
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  // Rotated lacunarity kills the axis-aligned look of raw value noise.
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) {
    v += amp * vnoise(p);
    p = m * p;
    amp *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  // Slow by design: the whole field should read as a lava-lamp drift.
  float t = uTime * uSpeed * 0.05;

  // Centered, aspect-corrected field coordinate.
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 1.35;

  // Gentle pointer influence: the field leans toward the cursor, strongest
  // nearby and fading out smoothly — a lean, never a spotlight.
  vec2 pd = vec2((uv.x - uPointer.x) * aspect, uv.y - uPointer.y);
  float pfall = exp(-dot(pd, pd) * 3.5) * uPointerActive;
  p -= (uPointer - 0.5) * 0.22 * pfall;

  // --- three-layer domain warp ---
  // q: first warp field, two decorrelated fbm channels drifting on their own
  // clocks so the motion never settles into a loop.
  vec2 q = vec2(
    fbm(p + t * vec2(0.9, 0.6)),
    fbm(p + vec2(5.2, 1.3) - t * vec2(0.5, 0.8))
  );

  // r: second warp, sampled through q — this is what turns soft gradients
  // into swirling currents.
  vec2 r = vec2(
    fbm(p + 1.7 * q + vec2(1.7, 9.2) + t * vec2(0.25, 0.4)),
    fbm(p + 1.7 * q + vec2(8.3, 2.8) - t * vec2(0.35, 0.15))
  );

  // f: the final field, warped through both layers.
  float f = fbm(p + 1.9 * r);

  // Softness maps the blur prop onto the smoothstep transition width: wide
  // windows melt the hues together, narrow ones cut cleaner shapes.
  float w = clamp(0.3 * uSoftness, 0.06, 0.85);

  // Each hue keys off a DIFFERENT warp field so the colors drift through one
  // another instead of moving in lockstep. smoothstep clamps — no clipping.
  vec3 col = uColor3;
  col = mix(col, uColor1, smoothstep(0.38 - w, 0.38 + w, f));
  col = mix(col, uColor2, 0.85 * smoothstep(0.52 - w, 0.52 + w, q.y));
  col = mix(col, uColor4, 0.75 * smoothstep(0.58 - w, 0.58 + w, r.x));

  // Cloud shading: valleys of the field sit deeper, crests lift — gives the
  // mesh volume without hard edges.
  col *= mix(0.72, 1.12, smoothstep(0.18, 0.82, f));

  // Luminous crest bloom where the field peaks, tinted along a second field
  // so the highlight color itself wanders.
  float glow = smoothstep(0.62, 0.94, f);
  col += mix(uColor2, uColor4, r.y) * glow * glow * 0.35;

  // Soft exponential tone curve: compresses highlights asymptotically below
  // 1.0 so the bloom can never clip to a flat patch.
  col = 1.0 - exp(-col * 1.7);

  // Faint vignette to seat the field behind content.
  vec2 vg = (uv - 0.5) * vec2(aspect, 1.0);
  col *= 1.0 - 0.3 * dot(vg, vg);

  // Film-grain dithering to defeat 8-bit banding in the slow gradients.
  float grain = hash21(gl_FragCoord.xy + fract(t) * 137.0) - 0.5;
  col += grain * (1.8 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

/**
 * Draft — a soft fluid gradient mesh. A domain-warped fbm fragment shader
 * swirls slate, indigo, and violet fields through each other in a slow,
 * cloud-soft drift, with a gentle lean toward the pointer. Built on the
 * `ogl-canvas` harness: GPU-light, offscreen-paused, reduced-motion-safe.
 * Position it inside any `relative` container; it fills and sits behind
 * content.
 */
export function Draft({
  colors = DEFAULT_COLORS,
  speed = 1,
  paused = false,
  idle = true,
  blur = 90,
  className,
  ...props
}: DraftProps) {
  const uniforms = React.useMemo(
    () => ({
      uColor1: { value: hexToRgb(colors[0]) },
      uColor2: { value: hexToRgb(colors[1]) },
      uColor3: { value: hexToRgb(colors[2]) },
      uColor4: { value: hexToRgb(colors[3]) },
      uSpeed: { value: Math.max(speed, 0) },
      // 90px (the CSS-era default) maps to softness 1.
      uSoftness: { value: Math.min(Math.max(blur / 90, 0.1), 3) },
    }),
    [colors, speed, blur]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="draft"
      {...props}
      className={cn("absolute inset-0 -z-10", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      paused={paused}
      ghost={idle}
      reducedMotionTime={8}
    />
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface EclipseProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Three tones: `[core, streamer, glint]`. `core` is the white-hot inner
   * corona hugging the limb, `streamer` is the cooler outer corona the rays
   * fade into, `glint` is the warm diamond-ring bead. Any hex string.
   * @default ["#f4f6ff", "#a8c2ec", "#ffcf8a"]
   */
  colors?: [string, string, string];
  /**
   * Animation speed multiplier: scales the corona's writhe and the diamond
   * glint's travel around the ring. 1 = default, 2 = twice as fast.
   * @default 1
   */
  speed?: number;
  /**
   * Corona brightness 0–2: scales the glow, streamers, limb ring, and diamond
   * glint together. The starfield stays fixed so raising it never blows out
   * the sky. @default 1
   */
  intensity?: number;
  /** Freeze the animation at its current frame. @default false */
  paused?: boolean;
  /**
   * Idle autoplay: after ~1.5s with no pointer present, a seeded ghost drifts
   * slowly across the field and shifts the parallax, so thumbnails and heroes
   * never look still; a real pointer takes over instantly. Never runs under
   * reduced motion. Default true.
   */
  idle?: boolean;
}

const DEFAULT_COLORS: [string, string, string] = [
  "#f4f6ff", // core — white-hot inner corona
  "#a8c2ec", // streamer — cool ice-blue outer corona
  "#ffcf8a", // glint — warm diamond-ring bead
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.96, 0.96, 1.0];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Original total-solar-eclipse fragment shader. A black moon disk occludes a
 * sun dead-center, ringed by a white-hot corona: broad angular lobes and fine
 * rays are built from seamless direction-space fbm (sampled on the unit circle
 * so the rays are perfectly radial with no atan seam), each streamer reaching
 * farther the brighter it is, so the corona fades outward with a dithered
 * exponential falloff instead of banding. A razor limb ring sits at the moon's
 * edge, and one intense diamond-ring bead — a hot core, soft bloom, and a
 * subtle cross-flare, warm against the neutral corona — travels very slowly
 * around the rim. A seeded starfield sits behind, washed out under the corona
 * and occluded by the disk. Filmic highlight rolloff keeps the bloom clean;
 * grain dithering defeats 8-bit banding. GLSL ES 1.00 (WebGL1/2 compatible).
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive; // eased 0-1 pointer/ghost presence

uniform vec3 uCore;      // inner corona
uniform vec3 uStreamer;  // outer corona
uniform vec3 uGlint;     // diamond bead
uniform float uSpeed;
uniform float uIntensity;

// Sun/moon radius in vertical-half units (uv.y spans 1.0 across the frame).
const float RIM = 0.15;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// 4-octave fbm. Rotated lacunarity kills the axis-aligned look.
float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 4; i++) {
    v += amp * vnoise(p);
    p = m * p;
    amp *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float resY = max(uResolution.y, 1.0);
  float t = uTime * uSpeed;

  // Subtle parallax: the disk shifts a hair more than the stars with the
  // pointer, giving the void depth. At rest (pointer centered) it's dead center.
  // Presence-scaled so the disk recenters when nobody is there.
  vec2 ptr = mix(vec2(0.5), uPointer, uPointerActive);
  vec2 center = vec2(0.5) + (ptr - 0.5) * 0.025;

  vec2 p = (uv - center) * vec2(aspect, 1.0);
  float rr = length(p);
  vec2 dir = p / max(rr, 1e-4);

  // Distance outside the limb, in sun-radii.
  float x = max(rr - RIM, 0.0) / RIM;

  // ------------------------------------------------------------- corona --
  // Seamless angular fields: sampling fbm on the unit circle makes the value
  // continuous around the ring (period 2pi, no seam) and constant along a
  // radius — i.e. perfectly radial streamers. Slow drift = the writhe.
  float lobes = fbm(dir * 2.4 + t * vec2(0.05, -0.035));
  float rays  = fbm(dir * 6.5 + vec2(9.3, 2.1) - t * vec2(0.045, 0.06));
  float streak = clamp(lobes * 0.62 + rays * 0.48, 0.0, 1.0);
  streak = pow(streak, 1.7);
  // Faint radial breakup so rays are filaments, not perfect spokes.
  streak *= 0.72 + 0.28 * fbm(dir * 9.5 + vec2(0.0, rr * 6.0) - t * 0.05);

  // Brighter streamers reach farther out.
  float reach = mix(0.55, 1.9, streak);
  float streamer = exp(-x / reach) * streak;
  float baseGlow = exp(-x * 1.7) * 0.42;      // smooth halo filling the gaps
  float breathe = 0.94 + 0.06 * sin(t * 0.3);
  float corAmt = (baseGlow + streamer * 1.15) * breathe;

  // Razor limb ring + a soft collar hugging the moon's edge.
  float ringD = (rr - RIM) / RIM;
  float ring = exp(-ringD * ringD * 320.0);
  float collar = exp(-x * 7.0);

  // ------------------------------------------------------- diamond ring --
  float phi = t * 0.06 + 0.4;                 // travels slowly around the rim
  vec2 gdir = vec2(cos(phi), sin(phi));
  float nearG = smoothstep(0.4, 1.0, dot(dir, gdir)); // limb glows near the bead
  vec2 gpos = gdir * (RIM * 1.02);            // just outside the limb
  vec2 gp = p - gpos;
  float gdist = length(gp);
  float gcore = exp(-gdist * gdist * 2200.0);
  float gbloom = exp(-gdist * 20.0);
  float fH = exp(-gp.y * gp.y * 2600.0) * exp(-abs(gp.x) * 9.0);
  float fV = exp(-gp.x * gp.x * 2600.0) * exp(-abs(gp.y) * 9.0);
  float glint = gcore * 3.5 + gbloom * 0.55 + (fH + fV) * 0.45;

  // --------------------------------------------------------------- sky --
  vec3 col = vec3(0.0015, 0.002, 0.005); // faint deep-space cast, never dead #000

  // Seeded starfield, washed out under the corona, parallaxed a touch.
  vec2 sPar = (ptr - 0.5) * 0.008;
  vec2 sc = (uv - sPar) * vec2(aspect, 1.0) * 92.0;
  vec2 sid = floor(sc);
  float pick = hash21(sid);
  float starW = 1.0 - clamp(corAmt * 2.2, 0.0, 1.0);
  if (pick > 0.985) {
    vec2 sp = vec2(hash21(sid + 3.1), hash21(sid + 7.7));
    float dst = length(fract(sc) - sp);
    float b = pow(max(0.0, 1.0 - dst * 3.2), 5.0);
    float tw = 0.55 + 0.45 * sin(t * 1.1 + pick * 54.0);
    col += vec3(0.7, 0.78, 1.0) * b * tw * (0.35 + 0.65 * hash21(sid + 1.7)) * starW;
  }

  // ------------------------------------------------------------ light --
  // Corona hue drifts from white-hot core at the limb to cool streamer far out.
  vec3 cCol = mix(uCore, uStreamer, clamp(x * 0.6, 0.0, 1.0));

  vec3 light = vec3(0.0);
  light += cCol * corAmt * (1.0 + 0.6 * nearG);
  light += mix(uCore, vec3(1.0), 0.5) * ring * (0.9 + 1.4 * nearG);
  light += uCore * collar * (0.35 + 0.5 * nearG);
  light += uGlint * glint;
  col += light * uIntensity;

  // The moon occludes everything: stars behind it, the inner half of the ring.
  float aa = 1.5 / resY;
  float disk = smoothstep(RIM - aa, RIM + aa, rr);
  col *= disk;

  // ---------------------------------------------------------- surface --
  vec2 vg = (uv - 0.5) * vec2(aspect, 1.0);
  col *= 1.0 - 0.4 * dot(vg, vg); // sink the frame edges into black

  // Filmic highlight rolloff: only the hottest points bloom to white.
  col = 1.0 - exp(-col * 1.5);

  // Grain dithering to defeat 8-bit banding across the falloff.
  float grain = hash21(gl_FragCoord.xy + fract(t) * 137.0) - 0.5;
  col += grain * (2.0 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

/**
 * Eclipse — a total solar eclipse in GL. A black moon disk occludes a
 * dead-center sun ringed by a white-hot corona: radial streamers writhe and
 * fade outward with a dithered falloff, a razor limb ring burns at the edge,
 * and one warm diamond-ring bead travels slowly around the rim over a seeded
 * starfield. Built on the `ogl-canvas` harness: GPU-light, offscreen-paused,
 * reduced-motion-safe. Position it inside any `relative` container; it fills
 * and sits behind content.
 */
export function Eclipse({
  colors = DEFAULT_COLORS,
  speed = 1,
  intensity = 1,
  paused = false,
  idle = true,
  className,
  ...props
}: EclipseProps) {
  const uniforms = React.useMemo(
    () => ({
      uCore: { value: hexToRgb(colors[0]) },
      uStreamer: { value: hexToRgb(colors[1]) },
      uGlint: { value: hexToRgb(colors[2]) },
      uSpeed: { value: Math.max(speed, 0) },
      uIntensity: { value: Math.min(Math.max(intensity, 0), 2) },
    }),
    [colors, speed, intensity]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="eclipse"
      {...props}
      className={cn("absolute inset-0 -z-10 bg-neutral-950", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      paused={paused}
      ghost={idle}
      dpr={1.75}
      reducedMotionTime={13.5}
    />
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import * as React from "react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cn } from "@/lib/utils";

export interface DetentItem {
  /** Unique, URL-safe-ish value identifying this tab. */
  value: string;
  /** Tab label. */
  label: React.ReactNode;
  /** Panel content shown when this tab is active. */
  content: React.ReactNode;
  /** Disable this tab — it's skipped by pointer and keyboard navigation. */
  disabled?: boolean;
}

export interface DetentProps extends Omit<React.ComponentPropsWithoutRef<"div">, "onChange"> {
  /** Tabs to render, in order. */
  items: DetentItem[];
  /** Controlled active tab value. */
  value?: string;
  /** Initial active tab value when uncontrolled. @default first enabled item */
  defaultValue?: string;
  /** Fires whenever the active tab changes, controlled or not. */
  onValueChange?: (value: string) => void;
  /** Tab list orientation. @default "horizontal" */
  orientation?: "horizontal" | "vertical";
  /** Accessible name for the tablist (e.g. "Filter by team"). Props on the root don't reach the tablist itself. */
  label?: string;
  /** Extra classes for the tablist track — e.g. `max-w-full overflow-x-auto` to let many tabs scroll. */
  listClassName?: string;
  /** Extra classes for every tab panel (replaces nothing; merged after the focus-ring defaults). */
  panelClassName?: string;
}

/**
 * Detent — animated tabs with a shared-layout sliding pill indicator that
 * flashes white as it lands and rests as a neutral pill with a subtle top
 * hairline. Full roving-tabindex keyboard support: Arrow keys move and
 * activate, Home/End jump to the ends, disabled tabs are skipped. Indicator
 * motion collapses to an instant snap under `prefers-reduced-motion`.
 */
export function Detent({
  items,
  value,
  defaultValue,
  onValueChange,
  orientation = "horizontal",
  label,
  listClassName,
  panelClassName,
  className,
  ...props
}: DetentProps) {
  const reducedMotion = useReducedMotion();
  const baseId = React.useId();
  const tabRefs = React.useRef<Array<HTMLButtonElement | null>>([]);
  // Bumped each time the sliding pill finishes settling into a tab; retriggers
  // the white bloom pulse — the detent "landing". Stays 0 on first paint so the
  // component mounts at rest, without a flash.
  const [landCount, setLandCount] = React.useState(0);

  const firstEnabled = items.find((item) => !item.disabled)?.value ?? items[0]?.value;
  const [internalValue, setInternalValue] = React.useState(defaultValue ?? firstEnabled);
  const activeValue = value ?? internalValue;

  const selectTab = React.useCallback(
    (next: string) => {
      if (value === undefined) setInternalValue(next);
      onValueChange?.(next);
    },
    [value, onValueChange]
  );

  const nextEnabledIndex = React.useCallback(
    (from: number, direction: 1 | -1) => {
      const count = items.length;
      let index = from;
      for (let step = 0; step < count; step++) {
        index = (index + direction + count) % count;
        if (!items[index]?.disabled) return index;
      }
      return from;
    },
    [items]
  );

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      const currentIndex = items.findIndex((item) => item.value === activeValue);
      const forwardKey = orientation === "vertical" ? "ArrowDown" : "ArrowRight";
      const backwardKey = orientation === "vertical" ? "ArrowUp" : "ArrowLeft";

      let nextIndex: number | null = null;
      if (event.key === forwardKey) nextIndex = nextEnabledIndex(currentIndex, 1);
      else if (event.key === backwardKey) nextIndex = nextEnabledIndex(currentIndex, -1);
      else if (event.key === "Home") nextIndex = nextEnabledIndex(-1, 1);
      else if (event.key === "End") nextIndex = nextEnabledIndex(0, -1);

      if (nextIndex === null) return;
      event.preventDefault();
      const nextItem = items[nextIndex];
      if (!nextItem) return;
      selectTab(nextItem.value);
      tabRefs.current[nextIndex]?.focus();
    },
    [items, activeValue, orientation, nextEnabledIndex, selectTab]
  );

  return (
    <div data-crucible="detent" className={cn("flex flex-col gap-4", className)} {...props}>
      <style>{`
        @keyframes crucible-detent-sheen {
          0% { background-position: 150% 0; }
          22% { background-position: -50% 0; }
          100% { background-position: -50% 0; }
        }
        [data-crucible="detent"] .detent-sheen {
          position: absolute;
          inset: 0;
          border-radius: inherit;
          background-image: linear-gradient(105deg, transparent 42%, rgba(255,255,255,0.16) 50%, transparent 58%);
          background-size: 220% 100%;
          background-repeat: no-repeat;
          background-position: -50% 0;
          animation: crucible-detent-sheen 6s ease-in-out infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="detent"] .detent-sheen { animation: none; }
        }
      `}</style>
      <div
        role="tablist"
        aria-label={label}
        aria-orientation={orientation}
        onKeyDown={handleKeyDown}
        className={cn(
          "relative inline-flex items-center gap-1 self-start rounded-full border border-white/10 p-1",
          orientation === "vertical" && "flex-col items-stretch self-stretch",
          listClassName
        )}
        style={{
          // Machined groove: the track is a shaded well the pills sit down into.
          backgroundImage: "linear-gradient(180deg, #171719 0%, #0f0f11 100%)",
          boxShadow:
            "inset 0 1px 2px rgba(0,0,0,0.65), inset 0 -1px 0 rgba(255,255,255,0.03)",
        }}
      >
        {items.map((item, index) => {
          const selected = item.value === activeValue;
          return (
            <button
              key={item.value}
              ref={(el) => {
                tabRefs.current[index] = el;
              }}
              role="tab"
              type="button"
              id={`${baseId}-tab-${item.value}`}
              aria-selected={selected}
              aria-controls={`${baseId}-panel-${item.value}`}
              tabIndex={selected ? 0 : -1}
              disabled={item.disabled}
              onClick={() => !item.disabled && selectTab(item.value)}
              className={cn(
                "relative z-10 rounded-full px-4 py-1.5 text-sm font-medium whitespace-nowrap text-white/55 transition-colors duration-200",
                "hover:text-white/85",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
                "disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:text-white/55",
                selected && "text-white"
              )}
            >
              {selected && (
                <motion.span
                  layoutId={`${baseId}-detent-indicator`}
                  aria-hidden
                  className="absolute inset-0 -z-10 rounded-full"
                  style={{
                    // Machined pill: lit from above (lighter top → darker base),
                    // a bright top hairline, a soft drop shadow so it rides ABOVE
                    // the groove, a hairline rim, and a faint neutral underglow.
                    backgroundImage:
                      "linear-gradient(180deg, #3b3b3f 0%, #2a2a2d 55%, #232326 100%)",
                    boxShadow: [
                      "inset 0 1px 0 rgba(255,255,255,0.22)",
                      "inset 0 -1px 0 rgba(0,0,0,0.45)",
                      "0 1px 1px rgba(0,0,0,0.5)",
                      "0 2px 6px -1px rgba(0,0,0,0.55)",
                      "0 0 0 1px rgba(255,255,255,0.08)",
                      "0 0 18px -6px rgba(255,255,255,0.2)",
                    ].join(", "),
                  }}
                  transition={
                    reducedMotion
                      ? { duration: 0 }
                      : { type: "spring", stiffness: 480, damping: 26, mass: 0.9 }
                  }
                  onLayoutAnimationComplete={() => {
                    if (!reducedMotion) setLandCount((c) => c + 1);
                  }}
                >
                  {/* Idle life: a slow, faint sheen glints across the resting
                      pill every few seconds. Pure CSS; frozen under reduced motion. */}
                  {!reducedMotion && <span className="detent-sheen" />}
                  {/* Detent landing: a white brightness + bloom pulse fired the
                      instant the pill settles. Gated on landCount>0 so mount is calm. */}
                  <AnimatePresence>
                    {landCount > 0 && (
                      <motion.span
                        key={landCount}
                        className="pointer-events-none absolute inset-0 rounded-full bg-white"
                        style={{ boxShadow: "0 0 22px 2px rgba(255,255,255,0.45)" }}
                        initial={{ opacity: 0.5 }}
                        animate={{ opacity: 0 }}
                        exit={{ opacity: 0 }}
                        transition={{ duration: 0.42, ease: "easeOut" }}
                      />
                    )}
                  </AnimatePresence>
                </motion.span>
              )}
              <span className="relative">{item.label}</span>
            </button>
          );
        })}
      </div>
      {items.map((item) => (
        <div
          key={item.value}
          role="tabpanel"
          id={`${baseId}-panel-${item.value}`}
          aria-labelledby={`${baseId}-tab-${item.value}`}
          hidden={item.value !== activeValue}
          tabIndex={0}
          className={cn(
            "rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40 focus-visible:ring-offset-4 focus-visible:ring-offset-neutral-950",
            panelClassName
          )}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface EmberProps {
  /**
   * Two forge tones for the ember color ramp: `[base, tip]`. `base` is the
   * color at the bottom where embers are born (ember red); `tip` is the color
   * they carry as they rise (molten amber). Any hex string.
   */
  colors?: [string, string];
  /**
   * Wind vector `[x, y]`. `x` drifts rising embers sideways (positive =
   * rightward), roughly −1…1; positive `y` quickens their rise (0 or
   * negative leaves the base rise speed — embers never sink).
   * Default `[0.25, 0]` — a soft rightward draft.
   */
  wind?: [number, number];
  /** Rise-speed multiplier. 1 = default. Default 1. */
  speed?: number;
  /** Ember count / field density, clamped 8–64. Default 44. */
  density?: number;
  /** Overall glow / bloom of the embers. 1 = default. Default 1. */
  intensity?: number;
  /** Freeze the animation, holding the current frame. */
  paused?: boolean;
  /**
   * Idle autoplay: after ~1.5s with no pointer present, a seeded ghost drifts
   * slowly across the field and raises the updraft, so thumbnails and heroes
   * never look still; a real pointer takes over instantly. Never runs under
   * reduced motion. Default true.
   */
  idle?: boolean;
  /** Extra classes for the wrapper. Positioned `absolute inset-0 -z-10`. */
  className?: string;
}

const DEFAULT_COLORS: [string, string] = [
  "#c1121f", // ember red — base
  "#ff6b35", // molten amber — tip
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [1, 0.42, 0.21];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Original ember fragment shader. A field of point-sprite embers, each seeded
 * by an inline hash, rising from the bottom edge with a per-particle phase,
 * convection wobble, and a caller-supplied horizontal wind. Color ramps from
 * base (ember red) at birth to tip (molten amber) as it climbs; brightness
 * flickers per particle; glow accumulates additively over a dark coal bed.
 * The pointer raises a gentle updraft in the embers nearest it. GLSL ES 1.00.
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive; // eased 0-1 pointer/ghost presence

uniform vec3 uColorBase; // ember red (birth)
uniform vec3 uColorTip;  // molten amber (rising)
uniform vec2 uWind;      // horizontal drift + rise bias
uniform float uSpeed;
uniform float uDensity;
uniform float uIntensity;

const int MAX_EMBERS = 64;

// --- inline hashes (original) ---
float hash11(float n) {
  return fract(sin(n * 127.1) * 43758.5453);
}
vec2 hash21(float n) {
  return fract(sin(vec2(n * 127.1, n * 311.7)) * 43758.5453);
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = uTime * uSpeed;

  int count = int(clamp(uDensity, 8.0, float(MAX_EMBERS)));

  // Dark field with a faint warm coal glow banked along the bottom edge.
  vec3 col = vec3(0.015, 0.010, 0.020);
  col += uColorBase * 0.10 * pow(1.0 - uv.y, 5.0);

  for (int i = 0; i < MAX_EMBERS; i++) {
    if (i >= count) break;
    float fi = float(i);

    vec2 rnd = hash21(fi + 1.37);
    float speed = 0.10 + rnd.x * 0.22 + max(uWind.y, 0.0) * 0.15;
    float phase = rnd.y;

    // life: 0 at the bottom edge, 1 at the top, looping.
    float life = fract(t * speed + phase);

    // Horizontal home + convection wobble, then wind carries it with height.
    float bx = hash11(fi * 3.17 + 5.0);
    float wob = sin(t * (0.8 + rnd.x * 2.0) + fi * 2.3) * 0.03;
    float x = bx + wob + uWind.x * life * 0.45;
    x = fract(x);

    float y = life;

    // Pointer updraft: embers horizontally near the pointer and below it get
    // lifted and jostled — a gentle convection column, never repulsion.
    float dxp = (x - uPointer.x) * aspect;
    float prox = exp(-dxp * dxp * 6.0);
    float below = smoothstep(uPointer.y + 0.20, uPointer.y - 0.30, y);
    float updraft = prox * below * uPointerActive;
    y += updraft * 0.05;
    x += updraft * sin(t * 5.0 + fi) * 0.008;

    // Point-sprite: gaussian falloff, shrinking as the ember rises.
    float size = (0.006 + rnd.x * 0.011) * (1.0 - 0.45 * life);
    size *= 1.0 + updraft * 0.30;
    vec2 d = vec2((uv.x - x) * aspect, uv.y - y);
    float g = exp(-dot(d, d) / (size * size));

    // Per-particle flicker + fade-in at birth, fade-out near the top.
    float flick = 0.65 + 0.35 * sin(t * (6.0 + rnd.y * 8.0) + fi * 4.0);
    float fade = smoothstep(0.0, 0.07, life) * (1.0 - smoothstep(0.72, 1.0, life));

    // Color ramp base → tip along the rise.
    vec3 ec = mix(uColorBase, uColorTip, smoothstep(0.0, 0.85, life));

    col += ec * g * flick * fade * uIntensity;
  }

  // Soft tone curve so stacked glows bloom instead of clipping.
  col = col / (col + vec3(0.85));

  // Film-grain dithering to defeat 8-bit banding.
  float grain = hash11(dot(gl_FragCoord.xy, vec2(12.9898, 78.233)) + fract(t) * 137.0) - 0.5;
  col += grain * (1.6 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

/**
 * Ember — a field of glowing embers rising from below in molten forge tones.
 * Each ember carries its own phase, convection wobble, flicker and color ramp
 * (ember red → molten amber), with a caller-supplied wind drift and a gentle
 * cursor updraft. Built on the `ogl-canvas` harness: GPU-light, offscreen-
 * paused, reduced-motion-safe. Drop it inside any `relative` container; it
 * fills and sits behind content.
 */
export function Ember({
  colors = DEFAULT_COLORS,
  wind = [0.25, 0],
  speed = 1,
  density = 44,
  intensity = 1,
  paused = false,
  idle = true,
  className,
}: EmberProps) {
  const uniforms = React.useMemo(
    () => ({
      uColorBase: { value: hexToRgb(colors[0]) },
      uColorTip: { value: hexToRgb(colors[1]) },
      uWind: { value: [wind[0], wind[1]] as [number, number] },
      uSpeed: { value: speed },
      uDensity: { value: density },
      uIntensity: { value: intensity },
    }),
    [colors, wind, speed, density, intensity]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="ember"
      className={cn("absolute inset-0 -z-10", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      paused={paused}
      ghost={idle}
      dpr={1.75}
      reducedMotionTime={2.5}
    />
  );
}

"use client";

import * as React from "react";
import { AnimatePresence, motion } from "motion/react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface EscapementProps
  extends Omit<React.ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> {
  /** Controlled value. */
  value?: number;
  /** Initial value when uncontrolled. @default 0 (clamped into range) */
  defaultValue?: number;
  /** Fires with the next value on every step, controlled or not. */
  onChange?: (value: number) => void;
  /** Lower bound. @default 0 */
  min?: number;
  /** Upper bound. @default 100 */
  max?: number;
  /** Amount per step. @default 1 */
  step?: number;
  /** Accent for the pawl and focus ring. @default "#d4a95c" (brass) */
  accentColor?: string;
  /** Accessible name for the spinbutton. @default "Value" */
  label?: string;
}

function DigitColumn({
  char,
  direction,
  reducedMotion,
}: {
  char: string;
  direction: number;
  reducedMotion: boolean;
}) {
  return (
    <span className="relative inline-block h-[1.3em] w-[0.62em] overflow-hidden">
      <AnimatePresence initial={false} custom={direction}>
        <motion.span
          key={char}
          custom={direction}
          variants={{
            enter: (d: number) => ({ y: d > 0 ? "105%" : "-105%", opacity: 0.3 }),
            center: { y: "0%", opacity: 1 },
            exit: (d: number) => ({ y: d > 0 ? "-105%" : "105%", opacity: 0 }),
          }}
          initial="enter"
          animate="center"
          exit="exit"
          transition={
            reducedMotion
              ? { duration: 0 }
              : { type: "spring", stiffness: 620, damping: 24, mass: 0.6 }
          }
          className="absolute inset-0 flex items-center justify-center"
        >
          {char}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

/**
 * Escapement — a numeric stepper with a mechanical ratchet feel. Each step
 * rolls the digit column with an overshoot-click settle (new digits spring in
 * from the direction of travel and catch), while a small brass pawl beneath the
 * dial flicks and re-seats like a gear tooth engaging. Hold either button and
 * the cadence accelerates like a wound mechanism. Neutral capsule, one brass
 * accent.
 *
 * Accessibility: proper `role="spinbutton"` semantics with Arrow keys,
 * PageUp/PageDown, and Home/End on the focusable value; the +/- buttons stay
 * out of the tab order per the APG pattern; value changes are announced via a
 * polite live region. Honors prefers-reduced-motion: digits swap instantly
 * with no springs or pawl flicks.
 */
export function Escapement({
  value,
  defaultValue,
  onChange,
  min = 0,
  max = 100,
  step = 1,
  accentColor = "#d4a95c",
  label = "Value",
  className,
  style,
  ...props
}: EscapementProps) {
  const reducedMotion = useReducedMotion();

  const clamp = React.useCallback(
    (v: number) => Math.min(max, Math.max(min, v)),
    [min, max]
  );

  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = React.useState(() =>
    clamp(defaultValue ?? 0)
  );
  const current = clamp(isControlled ? value : internalValue);

  // Direction of the last change — drives the roll direction and pawl flick.
  const prevRef = React.useRef(current);
  const direction = current >= prevRef.current ? 1 : -1;
  React.useEffect(() => {
    prevRef.current = current;
  }, [current]);

  const [hasStepped, setHasStepped] = React.useState(false);

  const valueRef = React.useRef(current);
  valueRef.current = current;

  const commit = React.useCallback(
    (next: number) => {
      setHasStepped(true);
      if (!isControlled) setInternalValue(next);
      onChange?.(next);
    },
    [isControlled, onChange]
  );

  /** Steps by `d` steps. Returns false when pinned at a bound. */
  const stepBy = React.useCallback(
    (d: number) => {
      // Round to the step's precision so fractional steps (0.1) never surface
      // float noise like 0.30000000000000004 in the digit columns.
      const decimals = (String(step).split(".")[1] ?? "").length;
      const next = clamp(Number((valueRef.current + d * step).toFixed(decimals)));
      if (next === valueRef.current) return false;
      commit(next);
      return true;
    },
    [clamp, step, commit]
  );

  // Hold-to-repeat with accelerating cadence.
  const holdTimerRef = React.useRef(0);
  const stopHold = React.useCallback(() => {
    window.clearTimeout(holdTimerRef.current);
  }, []);
  React.useEffect(() => stopHold, [stopHold]);

  const startHold = React.useCallback(
    (d: number) => {
      stopHold();
      if (!stepBy(d)) return;
      let delay = 340;
      const run = () => {
        if (!stepBy(d)) return;
        delay = Math.max(60, delay * 0.82);
        holdTimerRef.current = window.setTimeout(run, delay);
      };
      holdTimerRef.current = window.setTimeout(run, delay);
    },
    [stepBy, stopHold]
  );

  const handleSpinKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      let handled = true;
      if (event.key === "ArrowUp" || event.key === "ArrowRight") stepBy(1);
      else if (event.key === "ArrowDown" || event.key === "ArrowLeft") stepBy(-1);
      else if (event.key === "PageUp") stepBy(10);
      else if (event.key === "PageDown") stepBy(-10);
      else if (event.key === "Home") {
        if (valueRef.current !== min) commit(min);
      } else if (event.key === "End") {
        if (valueRef.current !== max) commit(max);
      } else handled = false;
      if (handled) event.preventDefault();
    },
    [stepBy, commit, min, max]
  );

  const buttonClass = cn(
    "flex size-9 items-center justify-center rounded-full text-neutral-300 transition-colors",
    "hover:bg-white/5 hover:text-white active:bg-white/10",
    "disabled:cursor-not-allowed disabled:opacity-30 disabled:hover:bg-transparent",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--esc-accent)"
  );

  const holdButtonProps = (d: number) => ({
    tabIndex: -1,
    disabled: d > 0 ? current >= max : current <= min,
    onPointerDown: (event: React.PointerEvent) => {
      if (event.pointerType === "mouse" && event.button !== 0) return;
      startHold(d);
    },
    onPointerUp: stopHold,
    onPointerLeave: stopHold,
    onPointerCancel: stopHold,
    onKeyDown: (event: React.KeyboardEvent) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        stepBy(d);
      }
    },
  });

  const chars = String(current).split("");

  return (
    <div
      data-crucible="escapement"
      className={cn("inline-flex flex-col items-center gap-1.5", className)}
      style={{ ["--esc-accent" as string]: accentColor, ...style }}
      {...props}
    >
      <div className="inline-flex items-center gap-0.5 rounded-full border border-white/10 bg-neutral-900 p-1.5 shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_14px_30px_-16px_rgba(0,0,0,0.8)]">
        <button
          type="button"
          aria-label="Decrease"
          className={buttonClass}
          {...holdButtonProps(-1)}
        >
          <svg
            aria-hidden
            viewBox="0 0 24 24"
            className="size-4"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
          >
            <path d="M5 12h14" />
          </svg>
        </button>

        <div
          role="spinbutton"
          aria-valuenow={current}
          aria-valuemin={min}
          aria-valuemax={max}
          aria-valuetext={String(current)}
          aria-label={label}
          tabIndex={0}
          onKeyDown={handleSpinKeyDown}
          className="relative flex min-w-[3.5ch] items-center justify-center rounded-full px-2 py-1 text-2xl font-semibold tabular-nums text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--esc-accent)"
        >
          {chars.map((char, i) => (
            <DigitColumn
              // Keyed by distance from the units place so existing columns
              // persist (and roll) when the digit count grows, odometer-style.
              key={chars.length - i}
              char={char}
              direction={direction}
              reducedMotion={reducedMotion}
            />
          ))}
        </div>

        <button
          type="button"
          aria-label="Increase"
          className={buttonClass}
          {...holdButtonProps(1)}
        >
          <svg
            aria-hidden
            viewBox="0 0 24 24"
            className="size-4"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
          >
            <path d="M12 5v14M5 12h14" />
          </svg>
        </button>
      </div>

      {/* The pawl — flicks and re-seats on every step, like a gear tooth engaging. */}
      <motion.svg
        key={current}
        aria-hidden
        viewBox="0 0 12 8"
        className="h-2 w-3 text-(--esc-accent)"
        initial={
          hasStepped && !reducedMotion
            ? { rotate: direction * 26, y: 1.5 }
            : false
        }
        animate={{ rotate: 0, y: 0 }}
        transition={
          reducedMotion
            ? { duration: 0 }
            : { type: "spring", stiffness: 700, damping: 18, mass: 0.5 }
        }
      >
        <path d="M6 0 11.5 8H0.5L6 0Z" fill="currentColor" />
      </motion.svg>

      {/* Announces value changes made via the +/- buttons (focus stays off the spinbutton). */}
      <span aria-live="polite" className="sr-only">
        {current}
      </span>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, type Transition } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/** Built-in empty-state presets, plus `"custom"` (bring your own illustration + copy). */
export type FallowKind = "no-results" | "first-run" | "error" | "offline" | "inbox-zero" | "custom";

/** Overall scale of the block. */
export type FallowSize = "sm" | "md" | "lg";

/** A primary or secondary call to action. */
export interface FallowAction {
  /** Visible label. */
  label: React.ReactNode;
  /** Click handler (rendered as a `<button>`). */
  onClick?: (event: React.MouseEvent<HTMLElement>) => void;
  /** Render as a link (`<a href>`) instead of a button. */
  href?: string;
}

/** Imperative verbs exposed through the `ref` prop. */
export interface FallowHandle {
  /** Replay the intro and the illustration's idle loop, and clear any retry state. */
  replay: () => void;
}

export interface FallowProps extends Omit<React.ComponentPropsWithoutRef<"div">, "title" | "children"> {
  /**
   * Which preset to render. Each preset brings its own line illustration and
   * default copy/actions; `"custom"` renders only what you pass.
   * @default "no-results"
   */
  kind?: FallowKind;
  /** Headline. Defaults to the preset's copy. */
  title?: React.ReactNode;
  /** Supporting sentence under the headline. Defaults to the preset's copy. */
  description?: React.ReactNode;
  /**
   * Primary action (accent-filled button). Defaults to the preset's action;
   * pass `null` to hide it. In retry mode (`onRetry` set) its label becomes the
   * retry button's idle label.
   */
  action?: FallowAction | null;
  /** Secondary text link. Defaults to the preset's link; pass `null` to hide it. */
  secondaryAction?: FallowAction | null;
  /**
   * Suggestion chips shown under the copy ("Try 'deploy'"). Defaults to three
   * sample queries for `no-results`, none otherwise; pass `[]` to hide.
   */
  suggestions?: string[];
  /** Fires with the chip's text when a suggestion is chosen. */
  onSuggestion?: (suggestion: string) => void;
  /**
   * Retry mode (meant for `error` / `offline`). When set, the primary button
   * calls this; return a Promise to show a pending spinner, then a success
   * check on resolve, or an inline "still failing" note on reject.
   */
  onRetry?: () => void | Promise<unknown>;
  /** Overall scale: illustration size, type ramp and button height. @default "md" */
  size?: FallowSize;
  /** Wrap the block in a dashed-border panel instead of rendering bare. @default false */
  framed?: boolean;
  /** Replace the preset illustration (decorative; rendered `aria-hidden`). */
  illustration?: React.ReactNode;
  /** Heading element for the title. @default "h3" */
  titleAs?: "h2" | "h3" | "h4" | "p";
  /** Stop the illustration's idle loop (it already stops by itself after 3 cycles). @default false */
  paused?: boolean;
  /** The single accent: illustration detail, primary fill, focus rings. @default "#a3c9a8" (sage) */
  accentColor?: string;
  /** Imperative handle (`replay()`). React 19 ref-as-prop. */
  ref?: React.Ref<FallowHandle>;
  /** Extra classes for the root. */
  className?: string;
}

const DEFAULT_ACCENT = "#a3c9a8";
const EASE: [number, number, number, number] = [0.22, 1, 0.36, 1];
const INSTANT: Transition = { duration: 0 };
const CYCLES = 3;

interface PresetCopy {
  title: string;
  description: string;
  action?: string;
  secondary?: string;
  suggestions?: string[];
  pending: string;
  success: string;
  failure: string;
}

