const INK_SOFT = "rgba(255,255,255,0.2)";
const SW = 1.5;

/** Idle loop: CYCLES repeats, each cycle starting and ending at the rest pose. */
const loop = (play: boolean, duration: number, extra?: Partial<Transition>): Transition =>
  play
    ? { duration, ease: "easeInOut", repeat: CYCLES - 1, delay: 0.75, ...extra }
    : INSTANT;

