/** Wi-fi arcs fading bar by bar, outermost first. */
function OfflineArt({ accent, play }: ArtProps) {
  const cx = 60;
  const cy = 84;
  const arc = (r: number) => {
    const d = r * Math.SQRT1_2;
    return `M${cx - d} ${cy - d}A${r} ${r} 0 0 1 ${cx + d} ${cy - d}`;
  };
  // Rest opacities read as "weak signal"; index 0 = innermost.
  const rest = [0.7, 0.3, 0.14];
  return (
    <>
      <path d="M30 98H90" stroke={INK_SOFT} strokeWidth={SW} strokeLinecap="round" strokeDasharray="2 5" />
      {[13, 26, 39].map((r, i) => {
        // Outer arcs fade first, inner last.
        const order = 2 - i;
        const start = 0.18 + order * 0.16;
        return (
          <motion.path
            key={r}
            d={arc(r)}
            stroke={INK}
            strokeWidth={SW}
            strokeLinecap="round"
            initial={false}
            animate={play ? { opacity: [rest[i], 1, 1, rest[i], rest[i]] } : { opacity: rest[i] }}
            transition={
              play
                ? {
                    duration: 3,
                    times: [0, 0.12, start, start + 0.16, 1],
                    ease: "easeInOut",
                    repeat: CYCLES - 1,
                    delay: 0.75,
                  }
                : INSTANT
            }
          />
        );
      })}
      <circle cx={cx} cy={cy} r="3.5" fill={accent} />
      <circle cx={cx} cy={cy} r="7.5" stroke={accent} strokeOpacity="0.35" strokeWidth={SW} />
