const ART: Partial<Record<FallowKind, React.ComponentType<ArtProps>>> = {
  "no-results": NoResultsArt,
  "first-run": FirstRunArt,
  error: ErrorArt,
  offline: OfflineArt,
  "inbox-zero": InboxZeroArt,
};

/* ---------------------------------------------------------------- main */

type RetryPhase = "idle" | "pending" | "success" | "failed";

/**
 * Fallow — an empty-state block with five presets (`no-results`, `first-run`,
 * `error`, `offline`, `inbox-zero`) and a custom mode. Each preset carries an
 * original 1.5px line illustration with a single accent detail and a gentle
 * idle loop that plays three cycles once in view, then rests: a magnifier
 * sweeping empty rows, a seedling in a dashed planter, a twitching unplugged
 * cable, Wi-fi arcs fading bar by bar, a paper plane gliding off a tray.
 * Headline, description, an accent primary action and a secondary link, an
 * optional suggestion-chip row, and a retry mode whose button runs an async
 * `onRetry` through pending → success (or an inline "still failing" note).
 * The copy sits in a `role="status"` region so swaps and retry results are
 * announced. Reduced motion renders the rest pose with crossfades only.
 */
export function Fallow({
  kind = "no-results",
  title,
  description,
  action,
  secondaryAction,
  suggestions,
  onSuggestion,
  onRetry,
  size = "md",
  framed = false,
  illustration,
  titleAs = "h3",
  paused = false,
  accentColor = DEFAULT_ACCENT,
  ref,
  className,
  style,
  ...props
}: FallowProps) {
  const reducedMotion = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [seen, setSeen] = React.useState(false);
  const [run, setRun] = React.useState(0);
  // Retry state is tagged with the preset it belongs to, so switching `kind`
  // starts with a clean button (and late results from the old preset are ignored).
  const [retryState, setRetryState] = React.useState<{ kind: FallowKind; phase: RetryPhase }>({
    kind,
    phase: "idle",
  });
  const retry: RetryPhase = retryState.kind === kind ? retryState.phase : "idle";
  const setRetry = React.useCallback((phase: RetryPhase, forKind: FallowKind) => setRetryState({ kind: forKind, phase }), []);
  const retryToken = React.useRef(0);

  const preset = PRESETS[kind];
  const sz = SIZES[size];
  const ink = readableOn(accentColor);
  const Title = titleAs;

  // Designed intro: plays the first time the block scrolls into view.
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );
    observer.observe(el);
    // Belt and braces: if already on screen at mount, don't wait on the observer.
    const raf = window.requestAnimationFrame(() => {
      const r = el.getBoundingClientRect();
      if (r.width > 0 && r.bottom > 0 && r.top < window.innerHeight) {
        setSeen(true);
        observer.disconnect();
      }
    });
    return () => {
      window.cancelAnimationFrame(raf);
      observer.disconnect();
    };
  }, []);

  const replay = React.useCallback(() => {
    retryToken.current++;
    setRetry("idle", kind);
    setRun((r) => r + 1);
  }, [kind, setRetry]);
  React.useImperativeHandle(ref, () => ({ replay }), [replay]);

  const shown = reducedMotion || seen;
  // On replay() the subtree remounts (key={run}) and starts from the hidden pose.
  const replaying = run > 0 && !reducedMotion;
  const reveal = (delay: number) => ({
    initial: replaying ? { opacity: 0, y: 10 } : (false as const),
    animate: { opacity: shown ? 1 : 0, y: shown ? 0 : 10 },
    transition: reducedMotion ? INSTANT : { duration: 0.5, ease: EASE, delay },
  });

  const primary: FallowAction | null =
    action === null ? null : action ?? (preset.action ? { label: preset.action } : null);
  const secondary: FallowAction | null =
    secondaryAction === null ? null : secondaryAction ?? (preset.secondary ? { label: preset.secondary } : null);
  const chips = suggestions ?? preset.suggestions ?? [];
  const retryMode = Boolean(onRetry);
  const showPrimary = retryMode || primary !== null;
  const titleText = title ?? preset.title;
  const descText = description ?? preset.description;

  const handleRetry = async () => {
    if (!onRetry || retry === "pending" || retry === "success") return;
    const token = ++retryToken.current;
    const forKind = kind;
    setRetry("pending", forKind);
    try {
      await onRetry();
      if (token === retryToken.current) setRetry("success", forKind);
    } catch {
      if (token === retryToken.current) setRetry("failed", forKind);
    }
  };

  const Art = ART[kind];
  const art = illustration ?? (Art ? (
    <svg viewBox="0 0 120 120" fill="none" className="size-full overflow-visible">
      <circle cx="60" cy="62" r="54" fill="rgba(255,255,255,0.018)" />
      <circle cx="60" cy="62" r="54" stroke="rgba(255,255,255,0.06)" strokeWidth="1" strokeDasharray="1.5 5" />
      <Art accent={accentColor} play={shown && !reducedMotion && !paused} animateIn={!reducedMotion} entered={shown} />
    </svg>
  ) : null);

  const focusRing =
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--fallow-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950";

  const primaryLabel: React.ReactNode =
    retry === "pending" ? preset.pending : retry === "success" ? preset.success : primary?.label ?? preset.action ?? "Try again";

  const primaryClass = cn(
    "inline-flex shrink-0 items-center justify-center gap-1.5 rounded-lg font-medium whitespace-nowrap",
    "shadow-[inset_0_1px_0_rgba(255,255,255,0.25),0_1px_2px_rgba(0,0,0,0.4)] transition-[filter,transform] hover:brightness-110 active:scale-[0.98]",
    sz.btn,
    focusRing
  );

  const announce =
    retry === "pending"
      ? `${preset.pending}…`
      : retry === "success"
        ? `${preset.success}.`
        : retry === "failed"
          ? preset.failure
          : "";

  return (
    <div
      ref={rootRef}
      data-crucible="fallow"
      className={cn("@container relative w-full text-white", className)}
      style={{ ["--fallow-accent" as string]: accentColor, ...style }}
      {...props}
    >
      <div
        key={run}
        className={cn(
          "flex flex-col items-center text-center",
          sz.pad,
          framed && "rounded-2xl border border-dashed border-white/[0.12] bg-white/[0.015]"
        )}
      >
        {art ? (
          <motion.div
            aria-hidden
            className={cn("relative isolate shrink-0", sz.gapArt)}
            style={{ width: sz.art, height: sz.art }}
            initial={replaying ? { opacity: 0, scale: 0.94 } : false}
            animate={{ opacity: shown ? 1 : 0, scale: shown ? 1 : 0.94 }}
            transition={reducedMotion ? INSTANT : { duration: 0.55, ease: EASE }}
          >
            <div
              className="pointer-events-none absolute inset-[-20%] -z-10 rounded-full opacity-60 blur-2xl"
              style={{ background: `radial-gradient(closest-side, color-mix(in srgb, ${accentColor} 14%, transparent), transparent)` }}
            />
            {art}
          </motion.div>
        ) : null}

        <div role="status" aria-live="polite" className="flex flex-col items-center">
          <motion.div {...reveal(0.08)}>
            <Title className={cn("text-balance text-white", sz.title)}>{titleText}</Title>
          </motion.div>
          {descText ? (
            <motion.p className={cn("text-pretty text-white/55", sz.desc)} {...reveal(0.14)}>
              {descText}
            </motion.p>
          ) : null}
          <span className="sr-only">{announce}</span>
        </div>

        {chips.length > 0 ? (
          <motion.div className={cn("flex flex-wrap items-center justify-center gap-1.5", sz.chips)} {...reveal(0.2)}>
            <span className={cn("mr-0.5 text-white/40", size === "sm" ? "text-[11px]" : "text-xs")}>Try</span>
            {chips.map((chip) => (
              <button
                key={chip}
                type="button"
                onClick={() => onSuggestion?.(chip)}
                className={cn(
                  "inline-flex items-center rounded-full border border-white/[0.09] bg-white/[0.03] font-medium text-white/70 transition-colors",
                  "hover:border-[color:var(--fallow-accent)]/50 hover:bg-white/[0.06] hover:text-white",
                  sz.chip,
                  focusRing
                )}
              >
                <span className="text-white/35">&lsquo;</span>
                {chip}
                <span className="text-white/35">&rsquo;</span>
              </button>
            ))}
          </motion.div>
        ) : null}

        {showPrimary || secondary ? (
          <motion.div
            className={cn("flex w-full flex-col items-center justify-center gap-2.5 @xs:w-auto @xs:flex-row @xs:gap-4", sz.actions)}
            {...reveal(0.26)}
          >
            {showPrimary ? (
              retryMode ? (
                <motion.button
                  type="button"
                  layout={!reducedMotion}
                  transition={{ layout: reducedMotion ? INSTANT : { type: "spring", stiffness: 420, damping: 34 } }}
                  onClick={handleRetry}
                  aria-busy={retry === "pending" || undefined}
                  aria-disabled={retry === "pending" || retry === "success" || undefined}
                  className={cn(primaryClass, "w-full @xs:w-auto", retry === "success" && "cursor-default hover:brightness-100 active:scale-100")}
                  style={{ backgroundColor: accentColor, color: ink }}
                >
                  <AnimatePresence mode="popLayout" initial={false}>
                    <motion.span
                      key={retry === "failed" ? "idle" : retry}
                      className="inline-flex items-center gap-1.5"
                      initial={{ opacity: 0, y: reducedMotion ? 0 : 6 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: reducedMotion ? 0 : -6 }}
                      transition={reducedMotion ? { duration: 0.12 } : { duration: 0.2, ease: "easeOut" }}
                    >
                      {retry === "pending" ? <Spinner /> : retry === "success" ? <CheckGlyph /> : null}
                      {primaryLabel}
                    </motion.span>
                  </AnimatePresence>
                </motion.button>
              ) : primary?.href ? (
                <a
                  href={primary.href}
                  onClick={primary.onClick}
                  className={cn(primaryClass, "w-full @xs:w-auto")}
                  style={{ backgroundColor: accentColor, color: ink }}
                >
                  {primary.label}
                </a>
              ) : (
                <button
                  type="button"
                  onClick={primary?.onClick}
                  className={cn(primaryClass, "w-full @xs:w-auto")}
                  style={{ backgroundColor: accentColor, color: ink }}
                >
                  {primary?.label}
                </button>
              )
            ) : null}
            {secondary ? (
              secondary.href ? (
                <a
                  href={secondary.href}
                  onClick={secondary.onClick}
                  className={cn("group inline-flex items-center gap-1 whitespace-nowrap rounded font-medium text-white/60 transition-colors hover:text-white", sz.link, focusRing)}
                >
                  {secondary.label}
                  <ArrowGlyph />
                </a>
              ) : (
                <button
                  type="button"
                  onClick={secondary.onClick}
                  className={cn("group inline-flex items-center gap-1 whitespace-nowrap rounded font-medium text-white/60 transition-colors hover:text-white", sz.link, focusRing)}
                >
                  {secondary.label}
                  <ArrowGlyph />
                </button>
              )
            ) : null}
          </motion.div>
        ) : null}

        <AnimatePresence initial={false}>
          {retry === "failed" ? (
            <motion.p
              key="failed"
              className={cn("mt-3 text-white/50", size === "sm" ? "text-[11px]" : "text-xs")}
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={reducedMotion ? { duration: 0.12 } : { duration: 0.25, ease: EASE }}
              aria-hidden
            >
              <span className="mr-1.5 inline-block size-1.5 -translate-y-px rounded-full bg-amber-300/80 align-middle" />
              {preset.failure}
            </motion.p>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { motion, useMotionValue, useSpring, type HTMLMotionProps } from "motion/react";
import * as React from "react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";
import { cn } from "@/lib/utils";

export interface FacetProps extends Omit<HTMLMotionProps<"div">, "children" | "ref"> {
  /** Content to render on the tilting surface. */
  children: React.ReactNode;
  /** Maximum rotation, in degrees, on either axis at the card's edge. @default 14 */
  maxTilt?: number;
  /** Container perspective distance in px — lower feels more extreme. @default 900 */
  perspective?: number;
  /** Peak opacity of the glare streak while hovered. @default 0.7 */
  glareOpacity?: number;
  /** Scale applied while hovered/tilting. @default 1.02 */
  hoverScale?: number;
  /**
   * Idle autoplay: after 1.5s with no pointer on the card, a ghost light
   * slowly rocks it through a shallow tilt with a dimmed glare, so the metal
   * never reads as dead. A real pointer takes over instantly. Off under
   * reduced motion; sleeps offscreen. @default true
   */
  idle?: boolean;
}

const SPRING = { stiffness: 300, damping: 28, mass: 1 };
const IDLE_MS = 1500;
/** Ghost tilt relative to a real pointer — deliberate, never a full hover. */
const GHOST_GAIN = 0.45;

/** Stable per-instance phase from React's id, so sibling cards never ghost in lockstep. */
function idPhase(id: string): number {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  return ((h >>> 0) / 4294967296) * Math.PI * 2;
}

/**
 * Facet — a card that tilts in 3D toward the pointer with spring-damped
 * rotation, while a hard-edged white-silver anisotropic glare streak sweeps
 * the surface like light across brushed metal. Disables tilt for touch input, and under
 * `prefers-reduced-motion` falls back to a flat card with a static, subtle
 * glare instead of disappearing. Untouched, a ghost light idles the tilt
 * (`idle`) and hands over to the real pointer the moment it arrives.
 */
export function Facet({
  children,
  className,
  style,
  maxTilt = 14,
  perspective = 900,
  glareOpacity = 0.7,
  hoverScale = 1.02,
  idle = true,
  ...props
}: FacetProps) {
  const reducedMotion = useReducedMotion();
  const [hovering, setHovering] = React.useState(false);
  const [ghosting, setGhosting] = React.useState(false);
  const hoverRef = React.useRef(false);
  const lastPointerRef = React.useRef(0);
  const ghostRef = React.useRef({ presence: 0, last: 0, on: false });
  const phase = idPhase(React.useId());

  const rawRotateX = useMotionValue(0);
  const rawRotateY = useMotionValue(0);
  const rotateX = useSpring(rawRotateX, SPRING);
  const rotateY = useSpring(rawRotateY, SPRING);
  const scale = useSpring(1, SPRING);

  // Ghost driver: a slow Lissajous light path at reduced strength.
  // The observed element, mirrored for the rAF tick (set after commit).
  const elRef = React.useRef<HTMLElement | null>(null);
  const cardRef = useVisibilityPause<HTMLDivElement>(
    (elapsed) => {
      const node = elRef.current;
      const g = ghostRef.current;
      if (!node) return;
      if (elapsed < g.last) g.last = elapsed;
      const dt = Math.min(elapsed - g.last, 0.05);
      g.last = elapsed;
      if (hoverRef.current) {
        g.presence = 0;
        if (g.on) {
          g.on = false;
          setGhosting(false);
        }
        return;
      }
      const want = performance.now() - lastPointerRef.current > IDLE_MS ? 1 : 0;
      g.presence += (want - g.presence) * Math.min(1, dt * 1.6);
      if (!want && g.presence < 0.01) {
        if (g.on) {
          g.on = false;
          setGhosting(false);
        }
        return;
      }
      if (!g.on) {
        g.on = true;
        setGhosting(true);
      }
      const px = 0.5 + 0.36 * Math.sin(elapsed * 0.43 + phase + 0.4);
      const py = 0.45 + 0.32 * Math.sin(elapsed * 0.31 + 1.9 + phase * 1.7);
      const k = g.presence * GHOST_GAIN;
      rawRotateX.set(-(py - 0.5) * 2 * maxTilt * k);
      rawRotateY.set((px - 0.5) * 2 * maxTilt * k);
      node.style.setProperty("--facet-gx", `${(px * 100).toFixed(2)}%`);
      node.style.setProperty("--facet-gy", `${(py * 100).toFixed(2)}%`);
    },
    { paused: !idle || reducedMotion }
  );

  React.useEffect(() => {
    elRef.current = cardRef.current;
  });

  // Arm the idle clock at mount (the ghost waits 1.5s before its first pass).
  React.useEffect(() => {
    lastPointerRef.current = performance.now();
  }, []);

  const handlePointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (reducedMotion || event.pointerType === "touch") return;
      const node = cardRef.current;
      if (!node) return;
      lastPointerRef.current = performance.now();
      if (!hoverRef.current) {
        // Pointer started inside the card (no enter event): take over now.
        hoverRef.current = true;
        setHovering(true);
        scale.set(hoverScale);
      }

      const rect = node.getBoundingClientRect();
      const px = (event.clientX - rect.left) / rect.width;
      const py = (event.clientY - rect.top) / rect.height;
      const cx = px - 0.5;
      const cy = py - 0.5;

      rawRotateX.set(-cy * 2 * maxTilt);
      rawRotateY.set(cx * 2 * maxTilt);
      node.style.setProperty("--facet-gx", `${(px * 100).toFixed(2)}%`);
      node.style.setProperty("--facet-gy", `${(py * 100).toFixed(2)}%`);
    },
    [reducedMotion, maxTilt, rawRotateX, rawRotateY, cardRef, scale, hoverScale]
  );

  const handlePointerEnter = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (reducedMotion || event.pointerType === "touch") return;
      hoverRef.current = true;
      lastPointerRef.current = performance.now();
      setHovering(true);
      scale.set(hoverScale);
    },
    [reducedMotion, hoverScale, scale]
  );

  const handlePointerLeave = React.useCallback(() => {
    hoverRef.current = false;
    lastPointerRef.current = performance.now();
    setHovering(false);
    rawRotateX.set(0);
    rawRotateY.set(0);
    scale.set(1);
  }, [rawRotateX, rawRotateY, scale]);

  return (
    <motion.div
      ref={cardRef}
      data-crucible="facet"
      onPointerMove={handlePointerMove}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      className={cn(
        "relative isolate overflow-hidden rounded-2xl border border-white/10 bg-neutral-900",
        className
      )}
      style={{
        transformStyle: "preserve-3d",
        // `transformPerspective` bakes perspective() into this element's own
        // transform. The CSS `perspective` property only affects descendants, so
        // it never foreshortened the card's own rotateX/rotateY (the tilt read flat).
        transformPerspective: reducedMotion ? undefined : perspective,
        rotateX: reducedMotion ? 0 : rotateX,
        rotateY: reducedMotion ? 0 : rotateY,
        scale: reducedMotion ? 1 : scale,
        ["--facet-gx" as string]: "50%",
        ["--facet-gy" as string]: "30%",
        ...style,
      }}
      {...props}
    >
      <div className="relative z-10">{children}</div>
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] transition-opacity duration-300"
        style={{
          opacity: reducedMotion ? 0.12 : hovering ? glareOpacity : ghosting ? glareOpacity * 0.55 : 0,
          mixBlendMode: "screen",
          background: [
            "radial-gradient(360px circle at var(--facet-gx) var(--facet-gy), rgba(255,255,255,0.35), transparent 40%)",
            "linear-gradient(115deg, transparent 40%, rgba(255,255,255,0.5) 47%, rgba(196,204,215,0.38) 50%, rgba(148,158,172,0.34) 53%, transparent 60%)",
          ].join(", "),
          backgroundSize: "auto, 220% 220%",
          backgroundPosition: "var(--facet-gx) var(--facet-gy)",
        }}
      />
    </motion.div>
  );
}

import * as React from "react";

import { cn } from "@/lib/utils";

export interface FilamentProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Card content. */
  children: React.ReactNode;
  /**
   * Four stops for the traveling filament: `[head, hot, cool, trace]` — a
   * white-hot leading point, the bright silver it cools through, the cool
   * blue-gray it desaturates to, and a faint slate trace before it fades.
   */
  colors?: [string, string, string, string];
  /** Border radius in px. */
  radius?: number;
  /** Ring thickness in px. */
  thickness?: number;
  /** Seconds for one full lap. */
  duration?: number;
  /** Freeze the animation, holding the current frame. */
  paused?: boolean;
}

/**
 * Filament — an animated conic-gradient border, a filament of light
 * orbiting the card: a white-hot head trailing a silver-to-blue tail that
 * cools and desaturates, leaving a faint slate trace before it fades.
 * Pure CSS via `@property`-animated conic gradient — zero JS, zero
 * dependencies. Honors prefers-reduced-motion by freezing the wire in place.
 */
export function Filament({
  children,
  colors = ["#ffffff", "#dbe4f0", "#93a8c4", "#5f7896"],
  radius = 16,
  thickness = 1.5,
  duration = 6,
  paused = false,
  className,
  style,
  ...rest
}: FilamentProps) {
  return (
    <div
      data-crucible="filament"
      className={cn("relative isolate overflow-hidden bg-neutral-900", className)}
      style={
        {
          "--filament-head": colors[0],
          "--filament-hot": colors[1],
          "--filament-cool": colors[2],
          "--filament-trace": colors[3],
          "--filament-thickness": `${thickness}px`,
          "--filament-duration": `${duration}s`,
          "--filament-play": paused ? "paused" : "running",
          "--filament-angle": "0deg",
          borderRadius: radius,
          ...style,
        } as React.CSSProperties
      }
      {...rest}
    >
      <style>{`
        @property --filament-angle {
          syntax: '<angle>';
          inherits: false;
          initial-value: 0deg;
        }
        @keyframes crucible-filament-spin {
          to { --filament-angle: 360deg; }
        }
        [data-crucible="filament"] .filament-ring {
          position: absolute;
          inset: 0;
          border-radius: inherit;
          padding: var(--filament-thickness);
          background: conic-gradient(
            from var(--filament-angle),
            var(--filament-head) 0%,
            var(--filament-hot) 3%,
            var(--filament-cool) 9%,
            color-mix(in oklab, var(--filament-cool) 25%, transparent) 15%,
            transparent 20%,
            color-mix(in oklab, var(--filament-trace) 35%, transparent) 30%,
            transparent 38%,
            transparent 100%
          );
          -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          -webkit-mask-composite: xor;
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask-composite: exclude;
          animation: crucible-filament-spin var(--filament-duration) linear infinite;
          animation-play-state: var(--filament-play);
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="filament"] .filament-ring {
            animation: none;
            --filament-angle: 20deg;
          }
        }
      `}</style>

      <span aria-hidden className="filament-ring pointer-events-none" />

      <div className="relative z-10">{children}</div>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface FilingsProps {
  /**
   * Two tones: `[cool, warm]`. `cool` is the resting silver of aligned
   * filings; `warm` is the brighter white they glow near the cursor.
   * Any hex string.
   */
  colors?: [string, string];
  /** Grid density (square cells stacked across the container height), clamped 8–40. Default 22. */
  density?: number;
  /** Idle-field animation speed multiplier. 1 = default. Default 1. */
  speed?: number;
  /** Stroke brightness / glow. 1 = default. Default 1. */
  intensity?: number;
  /** Freeze the animation, holding the current frame. */
  paused?: boolean;
  /**
   * Idle autoplay: after ~1.5s with no pointer present, a seeded ghost drifts
   * slowly across the field and bends the filings, so thumbnails and heroes
   * never look still; a real pointer takes over instantly. Never runs under
   * reduced motion. Default true.
   */
  idle?: boolean;
  /** Extra classes for the wrapper. Positioned `absolute inset-0 -z-10`. */
  className?: string;
}

const DEFAULT_COLORS: [string, string] = [
  "#a1a1aa", // silver — resting
  "#fafafa", // white — alignment glow
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.63, 0.63, 0.67];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Original iron-filings fragment shader. The plane is tiled into a grid; each
 * cell draws one short line segment (an SDF capsule) whose orientation tracks a
 * slowly-rotating magnetic-dipole field when idle and bends radially toward the
 * pointer near it. Alignment strength doubles as brightness — cells near the
 * cursor glow from resting silver to bright white, with a radial
 * magnetization wave rippling out from the pointer. One draw call, no
 * derivatives. GLSL ES 1.00.
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive;

uniform vec3 uColorCool; // resting silver
uniform vec3 uColorWarm; // alignment-glow white
uniform float uDensity;
uniform float uSpeed;
uniform float uIntensity;

// Distance from p to the segment a—b.
float segDist(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// Ideal magnetic-dipole field at p from a dipole at pos with moment m.
// Direction (~1/r^3 magnitude, unused here) gives the field-line tangent.
vec2 dipoleField(vec2 p, vec2 pos, vec2 m) {
  vec2 r = p - pos;
  float d2 = dot(r, r) + 0.0009;
  float d = sqrt(d2);
  vec2 rh = r / d;
  return (3.0 * dot(m, rh) * rh - m) / (d2 * d);
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = uTime * uSpeed;
  vec2 asp = vec2(aspect, 1.0);

  float dens = clamp(uDensity, 8.0, 40.0);

  // Aspect-corrected grid space (one grid unit is square on screen).
  vec2 q = uv * asp;
  vec2 gp = q * dens;
  vec2 cid = floor(gp);
  vec2 f = fract(gp) - 0.5;            // local coords within the cell
  vec2 cCenter = (cid + 0.5) / dens;   // cell center in q-space

  // Slowly-rotating, gently-drifting dipole for the idle field pattern.
  float a = t * 0.15;
  vec2 m = vec2(cos(a), sin(a));
  vec2 dpos = vec2(0.5 * aspect, 0.5) + 0.12 * vec2(cos(t * 0.10), sin(t * 0.13));
  vec2 fieldDir = normalize(dipoleField(cCenter, dpos, m));

  // Pointer influence, aspect-corrected.
  vec2 pw = uPointer * asp;
  vec2 toP = pw - cCenter;
  float pd = length(toP);
  // Released when the pointer leaves, so the idle frame is the pure dipole field.
  float cursorInf = exp(-pd * pd * 5.0) * uPointerActive;
  vec2 cDir = toP / (pd + 1e-4);

  // Blend idle field with the radial cursor pull.
  vec2 dir = normalize(mix(fieldDir, cDir, cursorInf));

  // One short segment centered in the cell, oriented along dir.
  float hl = 0.34;
  vec2 e = dir * hl;
  float dist = segDist(f, -e, e);
  float th = 0.075;
  float seg = smoothstep(th, th * 0.35, dist);

  // Alignment/brightness: a magnetization wave rides out from the pointer.
  float wave = 0.6 + 0.4 * sin(pd * 12.0 - t * 2.5);
  float warmth = clamp(cursorInf * wave, 0.0, 1.0);

  vec3 stroke = mix(uColorCool, uColorWarm, warmth);

  // Near-black plate with a faint cool lift toward the bottom.
  vec3 col = mix(vec3(0.018, 0.016, 0.030), uColorCool * 0.05, pow(1.0 - uv.y, 1.6));

  col += stroke * seg * uIntensity;
  // Soft glow halo pooling under the cursor.
  col += uColorWarm * cursorInf * cursorInf * 0.06;

  // Film-grain dithering to defeat banding.
  float grain = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233)) + fract(t) * 43.0) * 43758.5453) - 0.5;
  col += grain * (1.6 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

/**
 * Filings — an iron-filing field. A grid of short line segments aligns to a
 * slowly-rotating magnetic-dipole field when idle and bends toward the cursor
 * like filings around a magnet, brightening from resting silver to white
 * where the field is strongest. Built on the `ogl-canvas` harness: one draw
 * call, offscreen-paused, reduced-motion-safe. Drop it inside any `relative`
 * container; it fills and sits behind content.
 */
export function Filings({
  colors = DEFAULT_COLORS,
  density = 22,
  speed = 1,
  intensity = 1,
  paused = false,
  idle = true,
  className,
}: FilingsProps) {
  const uniforms = React.useMemo(
    () => ({
      uColorCool: { value: hexToRgb(colors[0]) },
      uColorWarm: { value: hexToRgb(colors[1]) },
      uDensity: { value: density },
      uSpeed: { value: speed },
      uIntensity: { value: intensity },
    }),
    [colors, density, speed, intensity]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="filings"
      className={cn("absolute inset-0 -z-10", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      paused={paused}
      ghost={idle}
      reducedMotionTime={3}
    />
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface FirefliesProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * How many fireflies drift in the field. Clamped 8–160. Near ones are large,
   * bright and roam widely; far ones are tiny, dim pinpricks — real depth.
   * @default 46
   */
  count?: number;
  /**
   * Glow palette, hottest → coolest, mapped across the depth field (nearest
   * fireflies take the first color). Defaults to a warm bioluminescent glow:
   * soft gold melting into a gentle leaf-green. Pass your own for a different
   * night — cool `["#dbeafe", "#a5f3fc", "#818cf8"]` reads as winter starlight.
   * @default ["#fff1c1", "#ffd166", "#b5e48c"]
   */
  colors?: string[];
  /** Drift / breathing-speed multiplier. 1 = default, 2 = twice as lively. @default 1 */
  speed?: number;
  /** Overall glow brightness and bloom, 0–2. @default 1 */
  intensity?: number;
  /** Deterministic seed for the wander layout — same seed, same night. @default 1 */
  seed?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /** Freeze the field at a static, aesthetic frame of glowing points. @default false */
  paused?: boolean;
}

const DEFAULT_COLORS = ["#fff1c1", "#ffd166", "#b5e48c"];
// Deep midnight bed — cool blue-black so the warm fireflies read as light.
const BG: [number, number, number] = [7, 9, 16];
// Per-frame fade toward the bed: leaves each firefly a short, soft trail.
const TRAIL_FADE = 0.14;

/** Deterministic mulberry32 PRNG — same seed always produces the same field. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Normalize any CSS color to [r,g,b] via a throwaway 1×1 draw. */
function colorToRgb(ctx: CanvasRenderingContext2D, color: string): [number, number, number] {
  ctx.clearRect(0, 0, 1, 1);
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 1, 1);
  const d = ctx.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}

/**
 * Pre-render one soft radial-glow sprite per palette color: a near-white hot
 * core fading through the color into a transparent halo. Built once, then
 * blitted additively per firefly so overlaps bloom — no per-frame gradients.
 */
function makeSprite(rgb: [number, number, number], scale: number): HTMLCanvasElement {
  const D = Math.max(24, Math.round(80 * scale));
  const c = document.createElement("canvas");
  c.width = D;
  c.height = D;
  const g = c.getContext("2d")!;
  const cx = D / 2;
  const [r, gg, b] = rgb;
  // Hot core mixes heavily toward white so each point reads incandescent.
  const cr = Math.round(r * 0.3 + 255 * 0.7);
  const cg = Math.round(gg * 0.3 + 255 * 0.7);
  const cb = Math.round(b * 0.3 + 255 * 0.7);
  const grad = g.createRadialGradient(cx, cx, 0, cx, cx, cx);
  grad.addColorStop(0, `rgba(${cr},${cg},${cb},1)`);
  grad.addColorStop(0.12, `rgba(${r},${gg},${b},0.9)`);
  grad.addColorStop(0.34, `rgba(${r},${gg},${b},0.28)`);
  grad.addColorStop(1, `rgba(${r},${gg},${b},0)`);
  g.fillStyle = grad;
  g.fillRect(0, 0, D, D);
  return c;
}

interface Firefly {
  /** Home anchor in device px — the wander orbits this point. */
  hx: number;
  hy: number;
  /** Depth 0 (far) → 1 (near): drives size, brightness, wander amplitude. */
  z: number;
  /** Glow sprite draw size, device px. */
  size: number;
  spriteIndex: number;
  brightness: number;
  // Two-frequency Lissajous wander per axis → organic, non-obviously-looping.
  ampX: number;
  ampY: number;
  fx1: number;
  fx2: number;
  fy1: number;
  fy2: number;
  phx1: number;
  phx2: number;
  phy1: number;
  phy2: number;
  // Breathing pulse.
  pulseFreq: number;
  pulsePhase: number;
}

function makeFirefly(
  rand: () => number,
  w: number,
  h: number,
  scale: number,
  paletteLen: number
): Firefly {
  // Skew depth toward "far" so a few near fireflies float over a dim deep field.
  const z = rand() * rand();
  const size = (11 + z * 34) * scale;
  return {
    hx: rand() * w,
    hy: rand() * h,
    z,
    size,
    spriteIndex: Math.min(paletteLen - 1, Math.floor((1 - z) * paletteLen)),
    brightness: 0.32 + z * 0.55,
    ampX: (10 + z * 46) * scale,
    ampY: (8 + z * 38) * scale,
    fx1: 0.12 + rand() * 0.22,
    fx2: 0.05 + rand() * 0.12,
    fy1: 0.1 + rand() * 0.2,
    fy2: 0.04 + rand() * 0.11,
    phx1: rand() * Math.PI * 2,
    phx2: rand() * Math.PI * 2,
    phy1: rand() * Math.PI * 2,
    phy2: rand() * Math.PI * 2,
    pulseFreq: 0.5 + rand() * 1.6,
    pulsePhase: rand() * Math.PI * 2,
  };
}

function buildField(
  count: number,
  seed: number,
  w: number,
  h: number,
  scale: number,
  paletteLen: number
): Firefly[] {
  const n = Math.min(160, Math.max(8, Math.round(count)));
  const rand = mulberry32(seed);
  const out: Firefly[] = [];
  for (let i = 0; i < n; i++) out.push(makeFirefly(rand, w, h, scale, paletteLen));
  return out;
}

interface Internals {
  ctx: CanvasRenderingContext2D;
  w: number;
  h: number;
  scale: number;
  sprites: HTMLCanvasElement[];
  flies: Firefly[];
  intensity: number;
}

/** Position of a firefly at effective time `t` (seconds, speed already applied). */
function posX(f: Firefly, t: number): number {
  return f.hx + f.ampX * (Math.sin(t * f.fx1 + f.phx1) * 0.7 + Math.sin(t * f.fx2 + f.phx2) * 0.3);
}
function posY(f: Firefly, t: number): number {
  return f.hy + f.ampY * (Math.sin(t * f.fy1 + f.phy1) * 0.7 + Math.sin(t * f.fy2 + f.phy2) * 0.3);
}

/** Draw one firefly's additive glow. `pulse` in [0,1] scales alpha (breathing). */
function drawFly(it: Internals, f: Firefly, x: number, y: number, pulse: number) {
  const alpha = Math.max(0, Math.min(1, f.brightness * pulse * it.intensity));
  if (alpha <= 0.004) return;
  const { ctx } = it;
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = alpha;
  const s = f.size;
  ctx.drawImage(it.sprites[f.spriteIndex], x - s / 2, y - s / 2, s, s);
}

function paintBackground(it: Internals) {
  it.ctx.globalCompositeOperation = "source-over";
  it.ctx.globalAlpha = 1;
  it.ctx.fillStyle = `rgb(${BG[0]},${BG[1]},${BG[2]})`;
  it.ctx.fillRect(0, 0, it.w, it.h);
}

/** One live frame: fade toward the bed (soft trails), then wander + breathe. */
function tickFrame(it: Internals, t: number) {
  it.ctx.globalCompositeOperation = "source-over";
  it.ctx.globalAlpha = 1;
  it.ctx.fillStyle = `rgba(${BG[0]},${BG[1]},${BG[2]},${TRAIL_FADE})`;
  it.ctx.fillRect(0, 0, it.w, it.h);

  for (const f of it.flies) {
    const pulse = 0.42 + 0.58 * (0.5 + 0.5 * Math.sin(t * f.pulseFreq + f.pulsePhase));
    drawFly(it, f, posX(f, t), posY(f, t), pulse);
  }
  it.ctx.globalCompositeOperation = "source-over";
  it.ctx.globalAlpha = 1;
}

/** Static frame for paused / reduced-motion: a still field of glowing points. */
function drawStatic(it: Internals) {
  paintBackground(it);
  for (const f of it.flies) {
    // Vary brightness by phase so the frozen field reads as scattered lights,
    // not a uniform grid — never blank, never flat.
    const pulse = 0.55 + 0.45 * (0.5 + 0.5 * Math.sin(f.pulsePhase));
    drawFly(it, f, posX(f, 0), posY(f, 0), pulse);
  }
  it.ctx.globalCompositeOperation = "source-over";
  it.ctx.globalAlpha = 1;
}

/**
 * Fireflies — a calm, magical night. Warm glowing points drift along gentle,
 * seeded wandering paths in the dark, each softly breathing (pulsing brightness)
 * inside an additive-glow halo and trailing a short, fading wake. Near fireflies
 * are large, bright and roam widely; far ones are dim pinpricks — a real depth
 * parallax, not a uniform sprinkle. 2D canvas with additive blending; seeded
 * PRNG for a deterministic, SSR-safe layout, pauses offscreen and on hidden
 * tabs, and honors prefers-reduced-motion with a still field of glowing points.
 * Drop it inside any `relative` container.
 */
export function Fireflies({
  count = 46,
  colors = DEFAULT_COLORS,
  speed = 1,
  intensity = 1,
  seed = 1,
  dpr = 2,
  paused = false,
  className,
  style,
  ...props
}: FirefliesProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();

  const frozen = paused || reducedMotion;
  const frozenRef = React.useRef(frozen);
  frozenRef.current = frozen;
  const speedFactor = Math.max(speed, 0);
  const colorsKey = colors.join(",");

  // Speed-scaled clock, accumulated per frame so speed changes never jump the swarm.
  const phaseRef = React.useRef(0);
  const lastElapsedRef = React.useRef(0);
  const tick = React.useCallback(
    (elapsed: number) => {
      const it = internalsRef.current;
      let dt = elapsed - lastElapsedRef.current;
      lastElapsedRef.current = elapsed;
      if (dt > 0.1) dt = 0.1; // clamp tab-restore jumps
      if (dt < 0) dt = 0;
      phaseRef.current += dt * speedFactor;
      if (!it) return;
      tickFrame(it, phaseRef.current);
    },
    [speedFactor]
  );

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: frozen });

  // Set up canvas, sprites and the field; rebuild on size / palette / seed / count.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;

    const scale = Math.min(
      typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1,
      Math.min(Math.max(dpr, 1), 2)
    );
    const palette = colors.length ? colors : DEFAULT_COLORS;
    const sprites = palette.map((c) => makeSprite(colorToRgb(ctx, c), scale));

    const onContextLost = (e: Event) => e.preventDefault();
    canvas.addEventListener("contextlost", onContextLost);

    const build = () => {
      const w = Math.max(1, Math.round(container.clientWidth * scale));
      const h = Math.max(1, Math.round(container.clientHeight * scale));
      canvas.width = w;
      canvas.height = h;
      canvas.style.width = "100%";
      canvas.style.height = "100%";
      const it: Internals = {
        ctx,
        w,
        h,
        scale,
        sprites,
        flies: buildField(count, seed, w, h, scale, sprites.length),
        intensity: Math.max(intensity, 0),
      };
      internalsRef.current = it;
      // Paint one frame immediately so mount / resize never flashes empty.
      if (frozenRef.current) drawStatic(it);
      else {
        paintBackground(it);
        for (const f of it.flies) {
          const pulse = 0.42 + 0.58 * (0.5 + 0.5 * Math.sin(f.pulsePhase));
          drawFly(it, f, posX(f, 0), posY(f, 0), pulse);
        }
      }
    };

    const ro = new ResizeObserver(build);
    ro.observe(container);
    build();

    return () => {
      ro.disconnect();
      canvas.removeEventListener("contextlost", onContextLost);
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [count, seed, colorsKey, dpr]);

  // Live-sync intensity without rebuilding the field.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it) return;
    it.intensity = Math.max(intensity, 0);
    if (frozenRef.current) drawStatic(it);
  }, [intensity]);

  // Re-render the static frame in place when paused / reduced-motion toggles on.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !frozen) return;
    drawStatic(it);
  }, [frozen]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="fireflies"
      className={cn("absolute inset-0 -z-10 overflow-hidden", className)}
      style={style}
      {...props}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
      {/* Soft vignette so the swarm sinks into the frame edges. */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 120% at 50% 45%, transparent 52%, rgba(0,0,0,0.55) 100%)",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface FlurryProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Layer tints, nearest → farthest. Index `0` colors the big foreground
   * flakes, `1` the mid layer, `2` the distant dust. Defaults to an icy
   * white-to-blue ramp on a cold near-black bed — pass warm grays for ash,
   * greens for pollen, anything for confetti-weather.
   * @default ["#eff6ff", "#bfdbfe", "#93c5fd"]
   */
  colors?: string[];
  /** Flake-count multiplier across all layers, 0.2–3. @default 1 */
  density?: number;
  /** Fall-speed multiplier (gust strength is set separately by `wind`). 1 = a lazy flurry. @default 1 */
  speed?: number;
  /**
   * Gust strength multiplier, 0–3. Gusts arrive on a seeded schedule and
   * shear every layer proportionally to its depth; `0` disables them.
   * @default 1
   */
  wind?: number;
  /**
   * Constant fall angle in degrees from vertical (positive leans right).
   * Clamped −45…45. @default 6
   */
  drift?: number;
  /** Chunk size of one "pixel" in CSS px — flakes snap to this grid. Clamped 2–8. @default 3 */
  pixelSize?: number;
  /**
   * Let flakes settle on an invisible floor line: each lands, flattens into a
   * 1-block drift for a moment, then fades and recycles. @default true
   */
  settle?: boolean;
  /** Overall flake brightness, 0–2. @default 1 */
  intensity?: number;
  /** Deterministic seed — same seed always renders the same snowfall. @default 1 */
  seed?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /** Freeze the flurry at a static mid-fall scatter. @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: string[] = ["#eff6ff", "#bfdbfe", "#93c5fd"];

/** How strongly gusts shear each layer — near snow catches the wind, far snow barely stirs. */
const GUST_SHEAR: [number, number, number] = [1, 0.55, 0.28];

/** Deterministic mulberry32 — seeded so the field is identical across mounts (SSR-safe). */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [239, 246, 255];
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

/** Cold near-black bed derived from the far-layer tint — never flat #000. */
function baseFill(far: [number, number, number]): string {
  return `rgb(${(4 + far[0] * 0.012) | 0}, ${(6 + far[1] * 0.015) | 0}, ${(10 + far[2] * 0.024) | 0})`;
}

interface Flake {
  x: number; // CSS px (unquantized sim position)
  y: number;
  layer: 0 | 1 | 2; // 0 near, 1 mid, 2 far
  vy: number; // fall speed, CSS px/s (before global speed)
  wanderAmp: number; // horizontal sine sway, CSS px
  wanderFreq: number;
  wanderPhase: number;
  baseAlpha: number;
  cross: boolean; // near flakes only: plus-shaped sparkle variant
  settled: boolean;
  settleT: number; // seconds spent on the floor
  settleDur: number;
}

interface Internals {
  ctx: CanvasRenderingContext2D;
  width: number; // CSS px
  height: number;
  P: number; // pixel-block size, CSS px
  palette: [number, number, number][];
  bg: string;
  flakes: Flake[];
  rng: () => number; // runtime recycling stream
  // Live knobs (mutated in place — no canvas rebuild on change).
  speed: number;
  wind: number;
  driftTan: number;
  intensity: number;
  settle: boolean;
  // Seeded gust schedule.
  gustStart: number;
  gustDur: number;
  gustStrength: number; // signed CSS px/s at envelope peak
}

function makeFlake(rng: () => number, layer: 0 | 1 | 2, w: number, h: number, initial: boolean): Flake {
  const near = layer === 0;
  const mid = layer === 1;
  return {
    x: rng() * w,
    // First build scatters mid-fall across the full height so frame zero (and
    // the reduced-motion still) is already a populated snowfall.
    y: initial ? rng() * h : -4 - rng() * h * 0.15,
    layer,
    vy: (near ? 46 : mid ? 26 : 13) * (0.75 + rng() * 0.5),
    wanderAmp: near ? 8 + rng() * 8 : mid ? 5 + rng() * 5 : 2 + rng() * 3,
    wanderFreq: 0.3 + rng() * 0.6,
    wanderPhase: rng() * Math.PI * 2,
    baseAlpha: near ? 0.95 : mid ? 0.6 : 0.35,
    cross: near && rng() < 0.3,
    settled: false,
    settleT: 0,
    settleDur: 1.2 + rng() * 1.4,
  };
}

function buildField(w: number, h: number, density: number, settle: boolean, seed: number): Flake[] {
  const rng = mulberry32((seed ^ 0x5eed5307) >>> 0);
  const area = w * h;
  const farCount = Math.min(320, Math.max(16, Math.round((area / 3800) * density)));
  const midCount = Math.round(farCount * 0.55);
  const nearCount = Math.max(3, Math.round(farCount * 0.28));
  const flakes: Flake[] = [];
  const push = (layer: 0 | 1 | 2, n: number) => {
    for (let i = 0; i < n; i++) {
      const f = makeFlake(rng, layer, w, h, true);
      // A seeded handful start already settled so the floor detail shows in
      // the static frame and from frame one.
      if (settle && rng() < 0.08) {
        f.settled = true;
        f.settleT = rng() * f.settleDur * 0.7;
      }
      flakes.push(f);
    }
  };
  push(2, farCount);
  push(1, midCount);
  push(0, nearCount);
  return flakes;
}

/** Send a flake back above the top edge with fresh seeded character. */
function respawn(f: Flake, it: Internals) {
  const fresh = makeFlake(it.rng, f.layer, it.width, it.height, false);
  Object.assign(f, fresh);
}

/**
 * Smooth gust envelope from the seeded schedule: 0 between gusts, sin² hump
 * during one. Advancing past a gust schedules the next from the seeded stream,
 * so the whole storm is deterministic.
 */
function gustAt(it: Internals, t: number): number {
  const end = it.gustStart + it.gustDur;
  if (t >= end) {
    it.gustStart = t + 3 + it.rng() * 6;
    it.gustDur = 1.2 + it.rng() * 1.8;
    it.gustStrength = (it.rng() < 0.5 ? -1 : 1) * (34 + it.rng() * 52);
    return 0;
  }
  if (t < it.gustStart) return 0;
  const p = (t - it.gustStart) / it.gustDur;
  const s = Math.sin(Math.PI * p);
  return it.gustStrength * s * s;
}

function fillBlock(it: Internals, qx: number, qy: number, w: number, h: number, rgb: [number, number, number], alpha: number) {
  if (alpha <= 0.01) return;
  it.ctx.fillStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${Math.min(alpha, 1)})`;
  it.ctx.fillRect(qx, qy, w, h);
}

/** Draw one flake, quantized to the pixel grid — integer blocks, zero subpixel churn. */
function drawFlake(it: Internals, f: Flake, t: number) {
  const { P } = it;
  const rgb = it.palette[f.layer];
  const floorY = Math.max(it.height - 2 * P, P);

  if (f.settled) {
    // Landed: a flat 1-block drift, one block wider than the flake, fading out
    // over the back half of its rest.
    const fade = 1 - Math.max(0, (f.settleT / f.settleDur - 0.4) / 0.6);
    const wBlocks = f.layer === 0 ? 3 : 2;
    const qx = Math.round(f.x / P) * P;
    const qy = Math.round(floorY / P) * P;
    fillBlock(it, qx - ((wBlocks / 2) | 0) * P, qy, wBlocks * P, P, rgb, f.baseAlpha * fade * it.intensity);
    return;
  }

  const xd = f.x + Math.sin(f.wanderPhase + t * f.wanderFreq) * f.wanderAmp;
  const qx = Math.round(xd / P) * P;
  const qy = Math.round(f.y / P) * P;
  const a = f.baseAlpha * it.intensity;

  if (f.layer === 0) {
    if (f.cross) {
      // Plus-shaped sparkle flake — pixel-craft variety in the near field.
      fillBlock(it, qx, qy, P, P, rgb, a);
      fillBlock(it, qx - P, qy, P, P, rgb, a * 0.75);
      fillBlock(it, qx + P, qy, P, P, rgb, a * 0.75);
      fillBlock(it, qx, qy - P, P, P, rgb, a * 0.75);
      fillBlock(it, qx, qy + P, P, P, rgb, a * 0.75);
    } else {
      fillBlock(it, qx, qy, 2 * P, 2 * P, rgb, a);
    }
  } else {
    fillBlock(it, qx, qy, P, P, rgb, a);
  }
}

/** One frame. `animate` false renders the designed static scatter (no advance). */
function draw(it: Internals, dt: number, t: number, animate: boolean) {
  const { ctx, width, height, P } = it;
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = it.bg;
  ctx.fillRect(0, 0, width, height);

  const gust = animate ? gustAt(it, t) * it.wind : 0;
  const floorY = Math.max(height - 2 * P, P);
  const margin = 4 * P;
  const span = width + 2 * margin;

  for (let i = 0; i < it.flakes.length; i++) {
    const f = it.flakes[i];
    if (animate) {
      if (f.settled) {
        f.settleT += dt;
        if (f.settleT >= f.settleDur) respawn(f, it);
      } else {
        const fall = f.vy * it.speed;
        f.y += fall * dt;
        f.x += (fall * it.driftTan + gust * GUST_SHEAR[f.layer]) * dt;
        // Wrap horizontally so drift and gusts never thin the field.
        if (f.x < -margin) f.x += span;
        else if (f.x > width + margin) f.x -= span;
        if (f.y >= floorY) {
          if (it.settle && it.rng() < 0.55) {
            f.settled = true;
            f.settleT = 0;
            f.y = floorY;
          } else {
            respawn(f, it);
          }
        }
      }
    }
    drawFlake(it, f, animate ? t : 0);
  }
}

/**
 * Flurry — quantized pixel snowfall. Chunky flakes locked to a crisp,
 * unsmoothed pixel grid drift down on three parallax depth layers (big bright
 * near chunks, mid blocks, distant dust — each with its own fall speed and
 * ice-blue tint). Every flake wanders on its own horizontal sine; seeded wind
 * gusts sweep through and shear all layers proportionally to depth; flakes
 * settle briefly on an invisible floor line — flattening into a 1-block drift
 * before fading. Canvas 2D: integer block positions (no subpixel churn),
 * seeded PRNG (SSR-safe), paused offscreen and on hidden tabs, reduced-motion
 * renders a static seeded mid-fall scatter. Drop it inside any `relative`
 * container.
 */
export function Flurry({
  colors = DEFAULT_COLORS,
  density = 1,
  speed = 1,
  wind = 1,
  drift = 6,
  pixelSize = 3,
  settle = true,
  intensity = 1,
  seed = 1,
  dpr = 2,
  paused = false,
  className,
  ...props
}: FlurryProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();
  const frozen = paused || reducedMotion;
  const lastElapsedRef = React.useRef(0);

  const P = Math.round(Math.min(Math.max(pixelSize, 2), 8));
  const dens = Math.min(Math.max(density, 0.2), 3);
  const speedF = Math.max(speed, 0.01);
  const windF = Math.min(Math.max(wind, 0), 3);
  const driftTan = Math.tan((Math.min(Math.max(drift, -45), 45) * Math.PI) / 180);
  const intens = Math.min(Math.max(intensity, 0), 2);
  const colorsKey = colors.join(",");

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it) return;
    // useVisibilityPause restarts `elapsed` at 0 whenever its `paused` option
    // flips; re-seat so the first frame after a resume steps by 0, not backwards.
    if (elapsed < lastElapsedRef.current) lastElapsedRef.current = elapsed;
    let dt = elapsed - lastElapsedRef.current;
    lastElapsedRef.current = elapsed;
    if (dt > 0.05) dt = 0.05; // clamp tab-restore jumps
    if (dt < 0) dt = 0;
    // The rAF loop only runs while unfrozen (useVisibilityPause gates it), so
    // ticks always animate; the frozen still is drawn by the effects below.
    draw(it, dt, elapsed, true);
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: frozen });

  // Canvas + field setup; rebuilds only on structural props (size via observer).
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;

    const effectiveDpr = Math.min(
      typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1,
      Math.min(Math.max(dpr, 1), 2)
    );

    const source = colors.length ? colors : DEFAULT_COLORS;
    const palette = source.map(hexToRgb) as [number, number, number][];
    while (palette.length < 3) palette.push(palette[palette.length - 1]);

    const rng = mulberry32((seed ^ 0x9e3779b9) >>> 0);
    const it: Internals = {
      ctx,
      width: 0,
      height: 0,
      P,
      palette,
      bg: baseFill(palette[2]),
      flakes: [],
      rng,
      speed: speedF,
      wind: windF,
      driftTan,
      intensity: intens,
      settle,
      gustStart: 2 + rng() * 4,
      gustDur: 1.2 + rng() * 1.8,
      gustStrength: (rng() < 0.5 ? -1 : 1) * (34 + rng() * 52),
    };
    internalsRef.current = it;

    const resize = () => {
      const w = Math.max(container.clientWidth, 1);
      const h = Math.max(container.clientHeight, 1);
      canvas.width = Math.round(w * effectiveDpr);
      canvas.height = Math.round(h * effectiveDpr);
      canvas.style.width = "100%";
      canvas.style.height = "100%";
      ctx.setTransform(effectiveDpr, 0, 0, effectiveDpr, 0, 0);
      ctx.imageSmoothingEnabled = false;

      it.width = w;
      it.height = h;
      it.flakes = buildField(w, h, dens, it.settle, seed);
      // Never flash empty — paint the seeded scatter immediately.
      draw(it, 0, 0, false);
    };

    const ro = new ResizeObserver(resize);
    ro.observe(container);
    resize();

    return () => {
      ro.disconnect();
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [P, dens, seed, dpr, colorsKey]);

  // Keep behavior knobs live in place (no rebuild), and re-render the frozen
  // frame so prop tweaks show while paused / reduced-motion.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it) return;
    it.speed = speedF;
    it.wind = windF;
    it.driftTan = driftTan;
    it.intensity = intens;
    it.settle = settle;
    if (frozen) draw(it, 0, 0, false);
  }, [speedF, windF, driftTan, intens, settle, frozen]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="flurry"
      className={cn("absolute inset-0 -z-10 overflow-hidden bg-neutral-950", className)}
      {...props}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
    </div>
  );
}

"use client";

import { AnimatePresence, motion, type Transition } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/** A single question/answer pair in a {@link Fold}. */
export interface FoldItem {
  /** The question shown on the disclosure trigger. */
  question: string;
  /** The answer revealed when the row unfolds. Plain text or rich nodes. */
  answer: React.ReactNode;
}

/** Accent tokens for {@link Fold}. Everything defaults to a cool, elegant blue. */
export interface FoldColors {
  /** Hue of the active chevron, focus ring, and the open row's hairline. @default "#93c5fd" */
  accent?: string;
}

export interface FoldProps extends Omit<React.ComponentPropsWithoutRef<"section">, "color"> {
  /** Question/answer pairs, rendered in order. @default five generic FAQs */
  items?: FoldItem[];
  /** Optional heading rendered as an h2 above the stack. Pass `null` to omit. @default "Frequently asked questions" */
  heading?: React.ReactNode;
  /**
   * When true (default), opening a row folds the previously open one shut so
   * only one answer shows at a time. When false, rows open independently.
   * @default true
   */
  singleOpen?: boolean;
  /** Index open on mount (changing it later re-seeds the open row). Pass -1 to start fully folded. @default 0 */
  defaultOpenIndex?: number;
  /** Accent tokens — the single cool hue on the active chevron and ring. @default `{ accent: "#93c5fd" }` */
  colors?: FoldColors;
}

const DEFAULT_ITEMS: FoldItem[] = [
  {
    question: "How does the free plan work?",
    answer:
      "Everything you need to evaluate the product, with no time limit and no card required. Upgrade only when you outgrow the free limits.",
  },
  {
    question: "Can I change plans at any time?",
    answer:
      "Yes. Switch up or down whenever you like — changes take effect immediately and we prorate the difference to the cent.",
  },
  {
    question: "Do you offer refunds?",
    answer:
      "If something isn't right within the first 30 days, reach out and we'll issue a full refund. No forms, no friction.",
  },
  {
    question: "Where is my data stored?",
    answer:
      "In the region you choose, encrypted at rest and in transit. You can export or delete everything at any time.",
  },
  {
    question: "How do I get support?",
    answer:
      "Every plan includes email support with a same-business-day response. Paid plans add priority chat and a shared channel.",
  },
];

const DEFAULT_ACCENT = "#93c5fd";

/**
 * Fold — a neutral-elegant FAQ accordion where each row is a self-contained card
 * in a soft stack. Opening a row lifts it a hair off the stack (a whisper of
 * shadow and scale), spins its chevron to point up in one accent hue, and the
 * answer physically unfolds: the panel measures its own height while the copy
 * hinges down from the top edge like paper opening. Full disclosure semantics —
 * every trigger is a real button with aria-expanded/aria-controls, the panel is a
 * labelled region, Enter/Space toggle, and Up/Down/Home/End roam between
 * questions. Single-open by default; `singleOpen={false}` lets rows open
 * independently. Reduced motion swaps to an instant open/close with the open row
 * resting lifted and the chevron already turned — no height tween, no hinge.
 */
export function Fold({
  items = DEFAULT_ITEMS,
  heading = "Frequently asked questions",
  singleOpen = true,
  defaultOpenIndex = 0,
  colors,
  className,
  ...props
}: FoldProps) {
  const reducedMotion = useReducedMotion();
  const baseId = React.useId();
  const headingId = `${baseId}-heading`;
  const accent = colors?.accent ?? DEFAULT_ACCENT;

  const triggerRefs = React.useRef<Array<HTMLButtonElement | null>>([]);

  const [openIndexes, setOpenIndexes] = React.useState<number[]>(() =>
    defaultOpenIndex >= 0 && defaultOpenIndex < items.length ? [defaultOpenIndex] : []
  );

  // Re-seed the open row when `defaultOpenIndex` itself changes after mount
  // (e.g. a live customizer knob), using the adjust-state-during-render pattern.
  const [seededIndex, setSeededIndex] = React.useState(defaultOpenIndex);
  if (seededIndex !== defaultOpenIndex) {
    setSeededIndex(defaultOpenIndex);
    setOpenIndexes(
      defaultOpenIndex >= 0 && defaultOpenIndex < items.length ? [defaultOpenIndex] : []
    );
  }

  const toggle = React.useCallback(
    (index: number) => {
      setOpenIndexes((current) => {
        const isOpen = current.includes(index);
        if (singleOpen) return isOpen ? [] : [index];
        return isOpen ? current.filter((i) => i !== index) : [...current, index];
      });
    },
    [singleOpen]
  );

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>, index: number) => {
      let next: number | null = null;
      if (event.key === "ArrowDown") next = (index + 1) % items.length;
      else if (event.key === "ArrowUp") next = (index - 1 + items.length) % items.length;
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = items.length - 1;
      if (next === null) return;
      event.preventDefault();
      triggerRefs.current[next]?.focus();
    },
    [items.length]
  );

  // Height/hinge tween for the panel; snaps instantly under reduced motion.
  const panelTransition: Transition = reducedMotion
    ? { duration: 0 }
    : {
        height: { duration: 0.36, ease: [0.16, 1, 0.3, 1] },
        opacity: { duration: 0.26, ease: "easeOut" },
      };

  const liftTransition: Transition = reducedMotion
    ? { duration: 0 }
    : { type: "spring", stiffness: 420, damping: 34, mass: 0.7 };

  const chevronTransition: Transition = reducedMotion
    ? { duration: 0 }
    : { type: "spring", stiffness: 460, damping: 30 };

  return (
    <section
      aria-labelledby={heading == null ? undefined : headingId}
      style={{ ["--fold-accent" as string]: accent }}
      className={cn("w-full", className)}
      {...props}
    >
      {heading != null ? (
        <h2
          id={headingId}
          className="text-balance text-2xl font-semibold tracking-tight text-white sm:text-3xl"
        >
          {heading}
        </h2>
      ) : null}

      <div className={cn("flex flex-col gap-2.5", heading != null && "mt-8")}>
        {items.map((item, index) => {
          const open = openIndexes.includes(index);
          const triggerId = `${baseId}-trigger-${index}`;
          const panelId = `${baseId}-panel-${index}`;

          return (
            <motion.div
              key={index}
              initial={false}
              animate={{
                y: open ? -2 : 0,
                scale: open ? 1.006 : 1,
                borderColor: open ? "rgba(255,255,255,0.16)" : "rgba(255,255,255,0.08)",
                backgroundColor: open ? "rgba(255,255,255,0.05)" : "rgba(255,255,255,0.02)",
                boxShadow: open
                  ? "0 12px 30px -14px rgba(0,0,0,0.7)"
                  : "0 0 0 0 rgba(0,0,0,0)",
              }}
              transition={liftTransition}
              className="relative overflow-hidden rounded-xl border"
            >
              {/* Hairline accent seam down the open row's left edge. */}
              <motion.span
                aria-hidden
                initial={false}
                animate={{ opacity: open ? 1 : 0 }}
                transition={{ duration: reducedMotion ? 0 : 0.4, ease: "easeOut" }}
                className="pointer-events-none absolute inset-y-2.5 left-0 w-px"
                style={{
                  background:
                    "linear-gradient(to bottom, transparent, var(--fold-accent) 28%, var(--fold-accent) 72%, transparent)",
                }}
              />

              <h3 className="m-0">
                <button
                  ref={(el) => {
                    triggerRefs.current[index] = el;
                  }}
                  type="button"
                  id={triggerId}
                  aria-expanded={open}
                  aria-controls={panelId}
                  onClick={() => toggle(index)}
                  onKeyDown={(event) => handleKeyDown(event, index)}
                  className={cn(
                    "flex w-full items-center justify-between gap-4 px-5 py-4 text-left",
                    "text-[15px] font-medium text-white/90 transition-colors hover:text-white",
                    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--fold-accent)] focus-visible:ring-inset"
                  )}
                >
                  <span className="min-w-0">{item.question}</span>

                  <motion.svg
                    viewBox="0 0 16 16"
                    aria-hidden="true"
                    className="h-4 w-4 shrink-0"
                    initial={false}
                    animate={{
                      rotate: open ? 180 : 0,
                      color: open ? "var(--fold-accent)" : "#8a8a8a",
                    }}
                    transition={chevronTransition}
                  >
                    <path
                      d="M4 6l4 4 4-4"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </motion.svg>
                </button>
              </h3>

              <AnimatePresence initial={false}>
                {open ? (
                  <motion.div
                    key="panel"
                    id={panelId}
                    role="region"
                    aria-labelledby={triggerId}
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: "auto", opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={panelTransition}
                    className="overflow-hidden"
                    style={{ perspective: 900 }}
                  >
                    <motion.div
                      initial={reducedMotion ? false : { rotateX: -14, opacity: 0 }}
                      animate={{ rotateX: 0, opacity: 1 }}
                      exit={reducedMotion ? undefined : { rotateX: -8, opacity: 0 }}
                      transition={
                        reducedMotion
                          ? { duration: 0 }
                          : { duration: 0.34, ease: [0.16, 1, 0.3, 1] }
                      }
                      style={{ transformOrigin: "top center" }}
                      className="px-5 pb-4.5 pt-0 text-sm leading-relaxed text-neutral-400"
                    >
                      {item.answer}
                    </motion.div>
                  </motion.div>
                ) : null}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>
    </section>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface FriezeProps extends Omit<React.ComponentPropsWithoutRef<"div">, "children"> {
  /**
   * The marks to display — logos, wordmarks, SVG glyphs, anything. Each direct
   * child becomes one lift-on-hover item. The set is duplicated internally for
   * a seamless loop; only the first copy is exposed to assistive tech.
   */
  children: React.ReactNode;
  /** Loop axis. @default "horizontal" */
  orientation?: "horizontal" | "vertical";
  /** Reverse the travel direction (right / down instead of left / up). @default false */
  reverse?: boolean;
  /**
   * Travel speed in pixels per second — held constant regardless of content
   * length or viewport size (duration is derived from the measured track).
   * @default 40
   */
  speed?: number;
  /** Space between marks, in pixels. @default 48 */
  gap?: number;
  /** Halt the strip while it (or one of its marks) is hovered/focused. @default true */
  pauseOnHover?: boolean;
  /** Width of the gradient edge-fade masks, in pixels, so marks dissolve at the boundary. @default 64 */
  fade?: number;
  /**
   * Copies of the children set laid end to end within one looping half. Bump
   * it when the mark set is too short to fill the viewport. @default 2
   */
  repeat?: number;
  /** Angle the strip in 3D space for a receding logo-wall look. @default false */
  perspective?: boolean;
  /** Tilt angle in degrees when `perspective` is on. @default 18 */
  tilt?: number;
  /** Resting opacity of each mark before it lifts to full on hover. @default 0.55 */
  restOpacity?: number;
  /** Draw the hairline architectural baseline that grounds the strip. @default true */
  baseline?: boolean;
}

const PERSPECTIVE_DISTANCE = 1400;

const STYLES = `
@keyframes crucible-frieze-x { to { transform: translateX(calc(-50% - var(--frieze-gap, 0px) / 2)); } }
@keyframes crucible-frieze-y { to { transform: translateY(calc(-50% - var(--frieze-gap, 0px) / 2)); } }
[data-crucible="frieze"] .frieze-track {
  animation-name: var(--frieze-name);
  animation-duration: var(--frieze-duration, 40s);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-direction: var(--frieze-dir, normal);
}
[data-crucible="frieze"][data-paused="true"] .frieze-track { animation-play-state: paused; }
[data-crucible="frieze"][data-pause-on-hover="true"]:hover .frieze-track,
[data-crucible="frieze"][data-pause-on-hover="true"]:focus-within .frieze-track { animation-play-state: paused; }
[data-crucible="frieze"] .frieze-item {
  opacity: var(--frieze-rest, 0.55);
  transition: opacity 0.4s ease, transform 0.4s ease, filter 0.4s ease;
}
[data-crucible="frieze"] .frieze-item:hover,
[data-crucible="frieze"] .frieze-item:focus-within {
  opacity: 1;
  transform: scale(1.05);
}
@media (prefers-reduced-motion: reduce) {
  [data-crucible="frieze"] .frieze-track { animation: none !important; }
}
`;

/**
 * Frieze — the calm, always-on brand marquee every landing page needs: a
 * logo cloud that loops horizontally or vertically, reversible, with gradient
 * edge-fade masks so marks dissolve at the boundary and a hairline baseline
 * grounding the strip like an architectural frieze.
 *
 * Crucible signature: marks ride at a hushed reduced opacity and an individual
 * item lifts to full presence on hover (never the whole strip), the loop halts
 * on hover/focus so a mark can be caught, and an optional 3D-perspective tilt
 * angles the whole plane in space. Pure CSS transform loop at a constant
 * pixels-per-second velocity — distinct from a velocity-reactive marquee.
 * Pauses offscreen and on hidden tabs; under reduced motion it freezes to a
 * static, fully-legible wrapped row.
 */
export function Frieze({
  children,
  orientation = "horizontal",
  reverse = false,
  speed = 40,
  gap = 48,
  pauseOnHover = true,
  fade = 64,
  repeat = 2,
  perspective = false,
  tilt = 18,
  restOpacity = 0.55,
  baseline = true,
  className,
  style,
  ...props
}: FriezeProps) {
  const reducedMotion = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const trackRef = React.useRef<HTMLUListElement>(null);
  const [duration, setDuration] = React.useState<number | null>(null);
  const [active, setActive] = React.useState(true);

  const isHorizontal = orientation === "horizontal";
  const items = React.Children.toArray(children);
  const safeRepeat = Math.max(1, Math.floor(repeat));

  // Pause the CSS loop when scrolled out of view or the tab is hidden — a
  // paused animation resumes from the same frame, so there is never a jump.
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    let inView = true;
    let tabVisible = !document.hidden;
    const update = () => setActive(inView && tabVisible);
    const io = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { threshold: 0 }
    );
    io.observe(el);
    const onVisibility = () => {
      tabVisible = !document.hidden;
      update();
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  // Derive the loop duration from the measured track so velocity stays constant
  // regardless of how much content is present. Not a rAF loop — the observer is
  // idle until a resize, and tears down on unmount.
  React.useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const measure = () => {
      const total = isHorizontal ? track.scrollWidth : track.scrollHeight;
      // One looping half advances by (total + gap) / 2; time = distance / speed.
      const advance = (total + gap) / 2;
      const next = speed > 0 ? advance / speed : 0;
      setDuration(next > 0 ? next : null);
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(track);
    return () => ro.disconnect();
  }, [isHorizontal, gap, speed, safeRepeat, children]);

  // Static, legible frame for reduced-motion users: a wrapped, full-opacity row.
  if (reducedMotion) {
    return (
      <div
        ref={rootRef}
        data-crucible="frieze"
        className={cn("relative", isHorizontal ? "w-full" : "h-full", className)}
        style={style}
        {...props}
      >
        <style>{STYLES}</style>
        <ul
          className="m-0 flex list-none flex-wrap items-center justify-center p-0"
          style={{ gap: `${gap}px` }}
        >
          {items.map((node, i) => (
            <li key={i} className="flex shrink-0 items-center justify-center">
              {node}
            </li>
          ))}
        </ul>
        {baseline && (
          <div
            aria-hidden
            className="pointer-events-none absolute inset-x-0 bottom-0 h-px"
            style={{
              background:
                "linear-gradient(to right, transparent, rgba(255,255,255,0.18), transparent)",
            }}
          />
        )}
      </div>
    );
  }

  const perHalf = items.length * safeRepeat;
  const all = Array.from({ length: perHalf * 2 }, (_, i) => items[i % items.length]);

  const maskImage = isHorizontal
    ? `linear-gradient(to right, transparent 0, #000 ${fade}px, #000 calc(100% - ${fade}px), transparent 100%)`
    : `linear-gradient(to bottom, transparent 0, #000 ${fade}px, #000 calc(100% - ${fade}px), transparent 100%)`;

  const viewportTransform = perspective
    ? isHorizontal
      ? `rotateY(${tilt}deg)`
      : `rotateX(${tilt}deg)`
    : undefined;

  const trackStyle = {
    "--frieze-name": isHorizontal ? "crucible-frieze-x" : "crucible-frieze-y",
    "--frieze-dir": reverse ? "reverse" : "normal",
    "--frieze-gap": `${gap}px`,
    "--frieze-rest": String(restOpacity),
    ...(duration ? { "--frieze-duration": `${duration}s` } : null),
    gap: `${gap}px`,
  } as React.CSSProperties;

  // The edge-fade mask lives on the static viewport, not the moving track — a
  // mask on the track would travel with it and fade the track's own ends
  // instead of the strip's boundary.
  const viewportStyle: React.CSSProperties = {
    maskImage,
    WebkitMaskImage: maskImage,
    ...(viewportTransform ? { transform: viewportTransform } : null),
  };

  return (
    <div
      ref={rootRef}
      data-crucible="frieze"
      data-paused={!active}
      data-pause-on-hover={pauseOnHover}
      className={cn("relative", isHorizontal ? "w-full" : "h-full", className)}
      style={perspective ? { perspective: `${PERSPECTIVE_DISTANCE}px`, ...style } : style}
      {...props}
    >
      <style>{STYLES}</style>
      <div
        className={cn(
          "relative overflow-hidden",
          isHorizontal ? "w-full" : "h-full"
        )}
        style={viewportStyle}
      >
        <ul
          ref={trackRef}
          className={cn(
            "frieze-track m-0 flex list-none p-0 will-change-transform",
            isHorizontal ? "w-max flex-row items-center" : "h-max flex-col items-center"
          )}
          style={trackStyle}
        >
          {all.map((node, i) => (
            <li
              key={i}
              aria-hidden={i >= items.length || undefined}
              // Loop copies are presentation only: keep any links inside them
              // out of the tab order as well as the accessibility tree.
              inert={i >= items.length || undefined}
              className="frieze-item flex shrink-0 items-center justify-center"
            >
              {node}
            </li>
          ))}
        </ul>
        {baseline && (
          <div
            aria-hidden
            className={cn(
              "pointer-events-none absolute",
              isHorizontal ? "inset-x-0 bottom-0 h-px" : "inset-y-0 left-0 w-px"
            )}
            style={{
              background: isHorizontal
                ? "linear-gradient(to right, transparent, rgba(255,255,255,0.18), transparent)"
                : "linear-gradient(to bottom, transparent, rgba(255,255,255,0.18), transparent)",
            }}
          />
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface FractureColors {
  /** Color of the first channel ghost. @default classic glitch red */
  ember?: string;
  /** Color of the second channel ghost. @default classic glitch cyan */
  violet?: string;
  /** Color of the base (undisplaced) text. @default warm white */
  base?: string;
  /** Color of the spark-fleck particles fired at each shear line. @default white */
  spark?: string;
}

export interface FractureProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /** The text to render and glitch. */
  children: string;
  /** Element tag rendered. @default "span" */
  as?: "span" | "div" | "p" | "h1" | "h2" | "h3";
  /**
   * What fires the glitch. "always" loops continuously (still bursty, not
   * nonstop noise — one burst per `cadence`-second cycle, the burst taking
   * the first ~17% of it); "hover" bursts rapidly while the pointer is over
   * the text; "interval" fires one `burstDuration` burst every `cadence`
   * seconds even without interaction. @default "hover"
   */
  trigger?: "always" | "hover" | "interval";
  /** Channel-split offset and slice strength, 0-1. @default 0.6 */
  intensity?: number;
  /** Seconds between bursts for "always"/"interval" triggers. @default 3.2 */
  cadence?: number;
  /**
   * Seconds per burst cycle for the "hover" and "interval" triggers ("always"
   * derives its burst from `cadence` instead). @default 0.5
   */
  burstDuration?: number;
  /** Ghost-layer, base, and spark colors. */
  colors?: FractureColors;
  /** Freeze the animation. @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: Required<FractureColors> = {
  ember: "#ff2d2d",
  violet: "#31e6ff",
  base: "#fdf1e3",
  spark: "#ffffff",
};

/**
 * Fracture — text shears under stress: classic red and cyan channel ghosts
 * jump apart along clip-path slices, with a white spark-fleck particle
 * firing at each shear line. Reads as structural shear, not a VHS dropout.
 * Freezes static under reduced motion.
 */
export function Fracture({
  children,
  as = "span",
  trigger = "hover",
  intensity = 0.6,
  cadence = 3.2,
  burstDuration = 0.5,
  colors,
  paused = false,
  className,
  style,
  ...props
}: FractureProps) {
  const reducedMotion = useReducedMotion();
  const c = { ...DEFAULT_COLORS, ...colors };
  const Tag = as;
  const [burst, setBurst] = React.useState(false);

  React.useEffect(() => {
    if (reducedMotion || trigger !== "interval" || paused) return;
    const cadenceMs = Math.max(cadence, 0.2) * 1000;
    const burstMs = Math.max(burstDuration, 0.05) * 1000;
    let timeoutId: ReturnType<typeof setTimeout>;
    const intervalId = setInterval(() => {
      setBurst(true);
      timeoutId = setTimeout(() => setBurst(false), burstMs);
    }, cadenceMs);
    return () => {
      clearInterval(intervalId);
      clearTimeout(timeoutId);
    };
  }, [trigger, cadence, burstDuration, reducedMotion, paused]);

  if (reducedMotion) {
    return (
      <Tag className={cn("inline-block", className)} style={{ color: c.base, ...style }} {...props}>
        {children}
      </Tag>
    );
  }

  return (
    <Tag
      data-crucible="fracture"
      data-trigger={trigger}
      data-burst={burst ? "" : undefined}
      aria-label={children}
      className={cn("relative isolate inline-block", className)}
      style={
        {
          "--fracture-intensity": intensity,
          "--fracture-cadence": `${cadence}s`,
          "--fracture-burst-duration": `${burstDuration}s`,
          ...(paused ? { "--fracture-play": "paused" } : {}),
          color: c.base,
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      <style>{`
