/* ---------------------------------------------------------------- helpers */

/** FNV-1a string hash → 32-bit seed. */
function hashString(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Seeded PRNG — deterministic on server and client. */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Soft gradient-blob portrait background, seeded from the person's name. */
function portraitBackground(name: string): string {
  const rand = mulberry32(hashString(name));
  const h = Math.floor(rand() * 360);
  const blob = (dh: number, l: number) => {
    const x = Math.round(10 + rand() * 80);
    const y = Math.round(10 + rand() * 80);
    const r = Math.round(38 + rand() * 30);
    const hue = (h + dh + 360) % 360;
    return `radial-gradient(circle at ${x}% ${y}%, hsl(${hue} 62% ${l}% / 0.95) 0%, hsl(${hue} 62% ${l}% / 0) ${r}%)`;
  };
  const angle = Math.floor(rand() * 360);
  return [
    blob(0, 72),
    blob(28 + Math.floor(rand() * 30), 60),
    blob(-30 - Math.floor(rand() * 30), 52),
    `linear-gradient(${angle}deg, hsl(${(h + 330) % 360} 35% 18%), hsl(${(h + 20) % 360} 38% 30%))`,
  ].join(", ");
}

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  const first = parts[0]?.[0] ?? "";
  const last = parts.length > 1 ? (parts[parts.length - 1]?.[0] ?? "") : "";
  return (first + last).toUpperCase();
}

function slug(s: string): string {
  return (
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "") || "team"
  );
}

