interface CardProps {
  person: GuildPerson;
  layoutId: string;
  panelId: string;
  open: boolean;
  /** Entry stagger index (intro) or -1 for "already on screen, no entry". */
  entryIndex: number;
  inView: boolean;
  intro: boolean;
  reducedMotion: boolean;
  onToggle: (open: boolean) => void;
}

const cardVariants: Variants = {
  hidden: { opacity: 0, y: 16, scale: 0.98 },
  shown: (delay: number) => ({
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { ...SPRING, delay },
  }),
};

function PersonCard({ person, layoutId, panelId, open, entryIndex, inView, intro, reducedMotion, onToggle }: CardProps) {
  const [hovered, setHovered] = React.useState(false);
  const toggleRef = React.useRef<HTMLButtonElement>(null);
  const visible = open || hovered;
  const background = React.useMemo(() => portraitBackground(person.name), [person.name]);
  const initials = initialsOf(person.name);
  const hasPanel = Boolean(person.bio || person.links?.length);
  const delay = intro ? Math.min(Math.max(entryIndex, 0), 11) * 0.045 : 0;

  return (
    <motion.li
      layoutId={layoutId}
      layout={!reducedMotion}
      custom={delay}
      variants={cardVariants}
      initial={entryIndex < 0 || reducedMotion ? false : "hidden"}
      animate={inView ? "shown" : "hidden"}
      transition={reducedMotion ? INSTANT : SPRING}
      data-open={visible || undefined}
      className="group/card relative flex min-w-0 flex-col"
      onPointerEnter={(e) => {
        if (e.pointerType === "mouse") setHovered(true);
      }}
      onPointerLeave={(e) => {
        if (e.pointerType === "mouse") setHovered(false);
      }}
      onKeyDown={(e) => {
        if (e.key === "Escape" && visible) {
          e.stopPropagation();
          setHovered(false);
          if (open) onToggle(false);
          toggleRef.current?.focus();
        }
      }}
    >
      <div className="@container/portrait relative aspect-[4/5] w-full overflow-hidden rounded-2xl border border-white/[0.08] bg-neutral-900">
        {/* Portrait art: rests as an accent duotone, warms to full color. */}
        <div
          aria-hidden
          className={cn(
            "absolute inset-0 grayscale-[1] contrast-[1.05] transition-[filter,transform] duration-700 ease-out",
            "group-focus-within/card:grayscale-0 group-data-[open]/card:grayscale-0",
            !reducedMotion && "group-data-[open]/card:scale-[1.04]"
          )}
          style={{ backgroundImage: background }}
        >
          {person.image ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={person.image} alt="" className="absolute inset-0 size-full object-cover" loading="lazy" />
          ) : (
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold tracking-[-0.04em] text-white/85 mix-blend-soft-light select-none"
              style={{ fontSize: "28cqw" }}
            >
              {initials}
            </span>
          )}
        </div>
        <div
          aria-hidden
          className="absolute inset-0 mix-blend-color transition-opacity duration-700 ease-out group-focus-within/card:opacity-0 group-data-[open]/card:opacity-0"
          style={{ backgroundColor: "var(--guild-accent)" }}
        />
        <div
          aria-hidden
          className="absolute inset-0 bg-[radial-gradient(120%_90%_at_50%_20%,transparent_30%,rgba(10,10,10,0.55))] mix-blend-multiply transition-opacity duration-700 ease-out group-focus-within/card:opacity-40 group-data-[open]/card:opacity-40"
        />
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/45 via-transparent to-transparent"
        />
        {/* Hairline sheen along the top edge. */}
        <div aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/25 to-transparent" />

        <button
          ref={toggleRef}
          type="button"
          aria-expanded={hasPanel ? open : undefined}
          aria-controls={hasPanel ? panelId : undefined}
          aria-label={`${person.name}, ${person.role}${hasPanel ? (open ? " — hide bio" : " — show bio") : ""}`}
          onClick={() => {
            if (!hasPanel) return;
            const next = !visible;
            if (!next) setHovered(false);
            onToggle(next);
          }}
          className="absolute inset-0 z-10 cursor-pointer rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[var(--guild-accent)]"
        />

        {hasPanel ? (
          <motion.div
            id={panelId}
            inert={!visible}
            aria-hidden={!visible}
            initial={false}
            animate={
              reducedMotion
                ? { opacity: visible ? 1 : 0, y: 0 }
                : { opacity: visible ? 1 : 0, y: visible ? "0%" : "calc(100% + 12px)" }
            }
            transition={reducedMotion ? { duration: 0.15 } : { type: "spring", stiffness: 380, damping: 34 }}
            className="absolute inset-x-1.5 bottom-1.5 z-20 rounded-xl border border-white/10 bg-neutral-950/80 p-2.5 shadow-[0_8px_24px_-8px_rgba(0,0,0,0.6)] backdrop-blur-md @[13rem]/portrait:inset-x-2 @[13rem]/portrait:bottom-2 @[13rem]/portrait:p-3"
          >
            {person.bio ? (
              <p className="line-clamp-4 text-pretty text-[11px] leading-snug text-white/75 @[13rem]/portrait:text-xs">
                {person.bio}
              </p>
            ) : null}
            {person.links?.length ? (
              <ul className={cn("flex flex-wrap gap-1", person.bio && "mt-2")}>
                {person.links.map((link) => {
                  const mail = link.href.startsWith("mailto:");
                  return (
                    <li key={link.label + link.href}>
                      <a
                        href={link.href}
                        {...(!mail && /^https?:/.test(link.href) ? { target: "_blank", rel: "noreferrer" } : {})}
                        className="inline-flex items-center gap-1 rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[11px] font-medium text-white/80 transition-colors hover:border-white/25 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--guild-accent)]"
                      >
                        {mail ? <MailGlyph className="size-3" /> : null}
                        {link.label}
                        {!mail ? <ArrowGlyph className="size-3 opacity-60" /> : null}
                        {!mail && /^https?:/.test(link.href) ? <span className="sr-only"> (opens in a new tab)</span> : null}
                      </a>
                    </li>
                  );
                })}
              </ul>
            ) : null}
          </motion.div>
        ) : null}
      </div>
      <div className="mt-3 min-w-0 px-0.5">
        <p className="truncate text-sm font-medium text-white">{person.name}</p>
        <p className="mt-0.5 truncate text-xs text-white/50">{person.role}</p>
      </div>
    </motion.li>
  );
}

/* ------------------------------------------------------------------- main */

/**
 * Guild — an about & team section block in three optional parts. (1) A
 * mission statement with an oversized stat row whose numbers roll in on
 * Tally digit drums. (2) A team grid of seeded generative portraits — soft
 * gradient blobs and initials — resting as an accent duotone that warms to
 * full color on hover or focus, with a reveal panel that slides up over the
 * portrait carrying a one-line bio and links (Enter/Space or tap pins it,
 * Escape closes). A Detent department filter re-flows the grid with shared
 * layout springs. (3) A numbered values list whose rule lines draw in.
 * Reduced motion shows the final layout with crossfades only.
 */
export function Guild({
  eyebrow = "About us",
  mission = DEFAULT_MISSION,
  missionBody = DEFAULT_MISSION_BODY,
  stats = DEFAULT_STATS,
  teamTitle = "The people behind the work",
  teamDescription = "A few of the people who design, build and run the product — spread across eleven countries and one shared calendar.",
  people = DEFAULT_PEOPLE,
  showFilter = true,
  allLabel = "Everyone",
  filter,
  defaultFilter = null,
  onFilterChange,
  onPersonToggle,
  valuesTitle = "What we hold to",
  values = DEFAULT_VALUES,
  accentColor = DEFAULT_ACCENT,
  ref,
  className,
  style,
  ...props
}: GuildProps) {
  const reducedMotion = useReducedMotion();
  const [replayKey, setReplayKey] = React.useState(0);
  const [innerFilter, setInnerFilter] = React.useState<string | null>(defaultFilter);
  const activeFilter = filter !== undefined ? filter : innerFilter;
  const [pinned, setPinned] = React.useState<string | null>(null);
  const [announcement, setAnnouncement] = React.useState("");

  const uid = React.useId().replace(/[:]/g, "");
  const headingId = `${uid}-heading`;

  const teams = React.useMemo(() => {
    const seen: string[] = [];
    for (const p of people) if (!seen.includes(p.team)) seen.push(p.team);
    return seen;
  }, [people]);

  const setFilter = React.useCallback(
    (team: string | null) => {
      if (filter === undefined) setInnerFilter(team);
      onFilterChange?.(team);
      setPinned(null);
      const count = team ? people.filter((p) => p.team === team).length : people.length;
      setAnnouncement(`Showing ${count} ${count === 1 ? "person" : "people"}${team ? ` in ${team}` : ""}.`);
    },
    [filter, onFilterChange, people]
  );

  React.useImperativeHandle(
    ref,
    () => ({
      replay: () => {
        setPinned(null);
        setReplayKey((k) => k + 1);
      },
      setFilter,
    }),
    [setFilter]
  );

  const showMission = mission !== null && mission !== undefined && mission !== false;
  const showStats = stats.length > 0;
  const showTeam = people.length > 0;
  const showValues = values.length > 0;
  const filterOn = showFilter && teams.length > 1;

  return (
    <section
      data-crucible="guild"
      aria-labelledby={showMission ? headingId : undefined}
      aria-label={showMission ? undefined : "About"}
      className={cn("@container relative isolate w-full overflow-hidden bg-neutral-950 text-white", className)}
      style={{ ["--guild-accent" as string]: accentColor, ...style }}
      {...props}
    >
      {/* Faint accent bloom + top hairline. */}
      <div aria-hidden className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-[28rem]">
        <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/12 to-transparent" />
        <div
          className="absolute inset-0"
          style={{
            background: `radial-gradient(60% 70% at 20% 0%, color-mix(in srgb, ${accentColor} 10%, transparent), transparent 70%)`,
          }}
        />
      </div>

      <GuildBody
        key={replayKey}
        uid={uid}
        headingId={headingId}
        reducedMotion={reducedMotion}
        eyebrow={eyebrow}
        mission={showMission ? mission : null}
        missionBody={missionBody}
        stats={showStats ? stats : []}
        teamTitle={teamTitle}
        teamDescription={teamDescription}
        people={showTeam ? people : []}
        teams={teams}
        filterOn={filterOn}
        allLabel={allLabel}
        activeFilter={activeFilter}
        setFilter={setFilter}
        pinned={pinned}
        setPinned={(name, open) => {
          setPinned(open ? name : null);
          const person = people.find((p) => p.name === name);
          if (person) onPersonToggle?.(person, open);
        }}
        valuesTitle={valuesTitle}
        values={showValues ? values : []}
      />

      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </section>
  );
}

interface BodyProps {
  uid: string;
  headingId: string;
  reducedMotion: boolean;
  eyebrow: React.ReactNode;
  mission: React.ReactNode;
  missionBody: React.ReactNode;
  stats: GuildStat[];
  teamTitle: React.ReactNode;
  teamDescription: React.ReactNode;
  people: GuildPerson[];
  teams: string[];
  filterOn: boolean;
  allLabel: string;
  activeFilter: string | null;
  setFilter: (team: string | null) => void;
  pinned: string | null;
  setPinned: (name: string, open: boolean) => void;
  valuesTitle: React.ReactNode;
  values: GuildValue[];
}

function GuildBody({
  uid,
  headingId,
  reducedMotion,
  eyebrow,
  mission,
  missionBody,
  stats,
  teamTitle,
  teamDescription,
  people,
  teams,
  filterOn,
  allLabel,
  activeFilter,
  setFilter,
  pinned,
  setPinned,
  valuesTitle,
  values,
}: BodyProps) {
  const missionRef = React.useRef<HTMLDivElement>(null);
  const teamRef = React.useRef<HTMLDivElement>(null);
  const valuesRef = React.useRef<HTMLOListElement>(null);
  const missionInView = useInView(missionRef, { once: true, amount: 0.3 });
  const teamInView = useInView(teamRef, { once: true, amount: 0.15 });
  const valuesInView = useInView(valuesRef, { once: true, amount: 0.3 });
  const mShow = reducedMotion || missionInView;
  const tShow = reducedMotion || teamInView;
  const vShow = reducedMotion || valuesInView;

  // Intro window for the grid's staggered plate-in; filter changes after it
  // only fade newly-entering cards in place.
  const [gridIntro, setGridIntro] = React.useState(true);
  React.useEffect(() => {
    if (!teamInView) return;
    const t = window.setTimeout(() => setGridIntro(false), 900);
    return () => window.clearTimeout(t);
  }, [teamInView]);

  const visiblePeople = React.useMemo(
    () =>
      people
        .map((p, i) => ({ p, i }))
        .filter(({ p }) => !filterOn || activeFilter === null || p.team === activeFilter),
    [people, filterOn, activeFilter]
  );

  // Cards already on screen keep their identity (shared layout); only new ones fade in.
  // Tracked as state (previous-render pattern) so render stays pure.
  const [filterHistory, setFilterHistory] = React.useState<{ current: string | null; previous?: string | null }>({
    current: activeFilter,
  });
  if (filterHistory.current !== activeFilter) {
    setFilterHistory({ current: activeFilter, previous: filterHistory.current });
  }
  const previously = React.useMemo(() => {
    if (filterHistory.previous === undefined) return null;
    const prev = filterHistory.previous;
    const set = new Set<number>();
    people.forEach((p, i) => {
      if (!filterOn || prev === null || p.team === prev) set.add(i);
    });
    return set;
  }, [filterHistory.previous, people, filterOn]);

  const rise = (delay: number) =>
    reducedMotion
      ? // Keep the same `initial` as the motion branch and animate straight to
        // the resting pose with a plain fade: SSR commits the hidden pose before
        // the reduced-motion query resolves, and swapping `initial` to `false`
        // after mount leaves it stuck there.
        {
          initial: { opacity: 0, y: 14, filter: "blur(4px)" },
          animate: { opacity: 1, y: 0, filter: "blur(0px)" },
          transition: { duration: 0.2, ease: "linear" as const },
        }
      : {
          initial: { opacity: 0, y: 14, filter: "blur(4px)" },
          animate: mShow ? { opacity: 1, y: 0, filter: "blur(0px)" } : undefined,
          transition: { duration: 0.6, ease: EASE, delay },
        };

  const grid = (
    <ul
      aria-label={activeFilter ? `${activeFilter} team` : "Team"}
      className="grid grid-cols-2 gap-x-3 gap-y-6 @lg:gap-x-4 @xl:grid-cols-3 @3xl:grid-cols-4 @4xl:gap-x-5"
    >
      {visiblePeople.map(({ p, i }, order) => (
        <PersonCard
          key={i}
          person={p}
          layoutId={`${uid}-person-${i}`}
          panelId={`${uid}-bio-${i}`}
          open={pinned === p.name}
          entryIndex={previously && previously.has(i) ? -1 : order}
          inView={tShow}
          intro={gridIntro && !reducedMotion}
          reducedMotion={reducedMotion}
          onToggle={(open) => setPinned(p.name, open)}
        />
      ))}
    </ul>
  );

  const filterValue = activeFilter === null ? ALL : slug(activeFilter);
  const tabLabel = (label: string, count: number) => (
    <span className="inline-flex items-center gap-1.5">
      {label}
      <span className="text-[11px] tabular-nums text-white/35">{count}</span>
    </span>
  );

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-col gap-16 px-5 py-14 @xl:px-8 @3xl:gap-24 @3xl:py-20">
      {mission !== null || stats.length > 0 ? (
        <div ref={missionRef} className="flex flex-col gap-10 @3xl:gap-14">
          {mission !== null ? (
            <div className="grid gap-5 @4xl:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)] @4xl:items-end @4xl:gap-16">
