                    <span aria-hidden className="size-1.5 rounded-full" style={{ backgroundColor: "var(--guild-accent)" }} />
                    {eyebrow}
                  </motion.p>
                ) : null}
                <motion.h2
                  id={headingId}
                  {...rise(0.06)}
                  className="text-balance text-[1.75rem] leading-[1.12] font-semibold tracking-[-0.025em] text-white @xl:text-4xl @4xl:text-5xl"
