              {missionBody !== null && missionBody !== undefined ? (
                <motion.p {...rise(0.14)} className="max-w-md text-pretty text-sm leading-relaxed text-white/55 @xl:text-base">
                  {missionBody}
                </motion.p>
              ) : null}
            </div>
          ) : null}

          {stats.length > 0 ? (
            <dl
              className="grid border-t border-white/[0.08]"
              style={{ gridTemplateColumns: "repeat(auto-fit, minmax(min(8rem, 100%), 1fr))" }}
            >
              {stats.map((stat, i) => (
                <motion.div
                  key={i}
                  {...rise(0.18 + i * 0.06)}
                  className="relative flex flex-col-reverse gap-1.5 border-b border-white/[0.08] py-5 pr-4 @xl:py-7"
                >
                  <dt className="text-xs text-white/50 @xl:text-sm">{stat.label}</dt>
                  <dd className="flex items-baseline text-4xl font-semibold tracking-[-0.03em] text-white tabular-nums @3xl:text-5xl @5xl:text-6xl">
