                    <Tally
                      value={stat.value}
                      start={stat.start ?? 0}
                      decimals={stat.decimals ?? 0}
                      formatOptions={stat.formatOptions}
                      duration={1.2}
                      delay={0.2 + i * 0.08}
                      glow={false}
                    />
                    {stat.suffix ? (
                      <span className="ml-0.5" style={{ color: "var(--guild-accent)" }}>
                        {stat.suffix}
                      </span>
                    ) : null}
                  </dd>
                </motion.div>
              ))}
            </dl>
          ) : null}
        </div>
      ) : null}

      {people.length > 0 ? (
        <div ref={teamRef} className="flex flex-col gap-7">
          <div className="flex max-w-2xl flex-col gap-2">
            <h3 className="text-xl font-semibold tracking-[-0.015em] text-white @xl:text-2xl">{teamTitle}</h3>
            {teamDescription !== null && teamDescription !== undefined ? (
              <p className="text-pretty text-sm leading-relaxed text-white/55">{teamDescription}</p>
            ) : null}
