  /** Fires when the detail sheet opens (`id`) or closes (`null`). */
  onOpenChange?: (id: string | null) => void;
  /** Href for the empty-state "Request an integration" link. @default "#" */
  requestHref?: string;
  /** Click handler for the "Request an integration" link (receives the current query). */
  onRequest?: (query: string) => void;
  /** Signature accent (hex) for glows, focus rings, the beam and the Connect button. @default "#f472b6" */
  accentColor?: string;
  /** Imperative handle (`replay()`, `open(id)`, `close()`). React 19 ref-as-prop. */
  ref?: React.Ref<ManifoldHandle>;
  /** Extra classes for the `<section>` root. */
  className?: string;
}

