/**
 * Pantograph — a horizontal nav where hovering a trigger opens a single shared
 * flyout that *morphs* to the next trigger instead of closing and reopening:
 * the panel slides along the bar and resizes to fit each trigger's content
 * while the caret tracks the active trigger and the content crossfades in from
 * the direction of travel. The signature is an *anticipation stretch* — the
 * panel's leading edge extends toward the new trigger a beat before the body
 * follows and the trailing edge snaps in, so it reads as one window panning
 * over a continuous surface. Hover-intent grace prevents flicker on diagonal
 * travel. Full disclosure semantics: focus opens, Escape closes, arrow keys
 * move between triggers, `aria-expanded` reflects state. On coarse pointers it
 * opens on tap; under `prefers-reduced-motion` the panel repositions instantly
 * and the content simply crossfades.
 */
export function Pantograph({
  items = DEFAULT_ITEMS,
  openOn = "hover",
  caret = true,
  closeDelay = 150,
  contentTransition = "directional",
  spring,
  minWidth = 200,
  maxWidth = 560,
  value,
  defaultValue = null,
  onValueChange,
  className,
  ...props
}: PantographProps) {
  const reducedMotion = useReducedMotion();
  const baseId = React.useId();
  const panelId = `${baseId}-panel`;

  const rootRef = React.useRef<HTMLDivElement>(null);
  const barRef = React.useRef<HTMLDivElement>(null);
  const triggerRefs = React.useRef<Map<string, HTMLElement>>(new Map());
  const measureRefs = React.useRef<Map<string, HTMLDivElement>>(new Map());
  const closeTimer = React.useRef<number | null>(null);

  const springCfg = { ...DEFAULT_SPRING, ...spring };

  // ---- open / active state (controlled or not) -----------------------------
  const [internalValue, setInternalValue] = React.useState<string | null>(
    defaultValue
  );
  const activeValue = value !== undefined ? value : internalValue;
  const [direction, setDirection] = React.useState(1);
  const [focusValue, setFocusValue] = React.useState<string>(
    items[0]?.value ?? ""
  );
  const [finePointer, setFinePointer] = React.useState(true);

  const activeItem = items.find(
    (i) => i.value === activeValue && i.content != null
  );
  const open = activeItem != null;

  const setActive = React.useCallback(
    (next: string | null) => {
      if (next && activeValue && next !== activeValue) {
        const a = triggerCentersRef.current[activeValue];
        const b = triggerCentersRef.current[next];
        if (a != null && b != null) setDirection(b > a ? 1 : -1);
      }
      if (value === undefined) setInternalValue(next);
      onValueChange?.(next);
    },
    [activeValue, value, onValueChange]
  );

  // ---- layout measurement --------------------------------------------------
  const [navWidth, setNavWidth] = React.useState(0);
  const [dims, setDims] = React.useState<
    Record<string, { w: number; h: number }>
  >({});
  const triggerCentersRef = React.useRef<Record<string, number>>({});

  const measureTriggers = React.useCallback(() => {
    const bar = barRef.current;
    if (!bar) return;
    const barRect = bar.getBoundingClientRect();
    setNavWidth(barRect.width);
    const centers: Record<string, number> = {};
    for (const item of items) {
      const el = triggerRefs.current.get(item.value);
      if (el) {
        const r = el.getBoundingClientRect();
        centers[item.value] = r.left - barRect.left + r.width / 2;
      }
    }
    triggerCentersRef.current = centers;
  }, [items]);

  React.useLayoutEffect(() => {
    measureTriggers();
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(() => measureTriggers());
    if (barRef.current) ro.observe(barRef.current);
    return () => ro.disconnect();
  }, [measureTriggers]);

  // Measure each trigger's natural content size (padding included).
  React.useLayoutEffect(() => {
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver((entries) => {
      setDims((prev) => {
        let changed = false;
        const next = { ...prev };
        for (const entry of entries) {
          const key = entry.target.getAttribute("data-measure-key");
          if (!key) continue;
          const el = entry.target as HTMLElement;
          const w = el.offsetWidth;
          const h = el.offsetHeight;
          if (!next[key] || next[key].w !== w || next[key].h !== h) {
            next[key] = { w, h };
            changed = true;
          }
        }
        return changed ? next : prev;
      });
    });
    for (const el of measureRefs.current.values()) ro.observe(el);
    return () => ro.disconnect();
  }, [items]);

  // ---- morph motion values -------------------------------------------------
  const leftMV = useMotionValue(0);
  const rightMV = useMotionValue(0);
  const heightMV = useMotionValue(0);
  const caretCenterMV = useMotionValue(0);
  const widthMV = useTransform([leftMV, rightMV], (latest: number[]) =>
    Math.max(0, latest[1] - latest[0])
  );
  const caretX = useTransform(
    [caretCenterMV, leftMV, rightMV],
    (latest: number[]) => {
      const [c, l, r] = latest;
      return clamp(c - l, CARET_PAD, Math.max(CARET_PAD, r - l - CARET_PAD));
    }
  );

  const wasOpenRef = React.useRef(false);

  React.useEffect(() => {
    if (!open || !activeValue) {
      wasOpenRef.current = false;
      return;
    }
    const dim = dims[activeValue];
    const center = triggerCentersRef.current[activeValue];
    if (!dim || center == null || !navWidth) return;

    const w = clamp(dim.w, minWidth, maxWidth);
    const h = dim.h;
    let targetLeft: number;
    if (w >= navWidth) targetLeft = (navWidth - w) / 2;
    else targetLeft = clamp(center - w / 2, 0, navWidth - w);
    const targetRight = targetLeft + w;

    if (!wasOpenRef.current || reducedMotion) {
      // Fresh open or reduced motion: seat the panel with no morph theatrics.
      leftMV.set(targetLeft);
      rightMV.set(targetRight);
      heightMV.set(h);
      caretCenterMV.set(center);
    } else {
      // Anticipation stretch: the leading edge (toward the new trigger) springs
      // fast and arrives first; the trailing edge follows a beat behind, so the
      // panel visibly stretches before it settles.
      const movingRight = targetLeft > leftMV.get();
      const lead = {
        type: "spring" as const,
        stiffness: springCfg.stiffness * 1.7,
        damping: springCfg.damping * 1.05,
        mass: springCfg.mass * 0.85,
      };
      const trail = {
        type: "spring" as const,
        stiffness: springCfg.stiffness * 0.85,
        damping: springCfg.damping,
        mass: springCfg.mass,
        delay: 0.05,
      };
      if (movingRight) {
        animate(rightMV, targetRight, lead);
        animate(leftMV, targetLeft, trail);
      } else {
        animate(leftMV, targetLeft, lead);
        animate(rightMV, targetRight, trail);
      }
      animate(heightMV, h, {
        type: "spring",
        stiffness: springCfg.stiffness,
        damping: springCfg.damping,
        mass: springCfg.mass,
      });
      animate(caretCenterMV, center, {
        type: "spring",
        stiffness: 700,
        damping: 44,
      });
    }
    wasOpenRef.current = true;
    // springCfg is derived each render; deps below cover its inputs via `spring`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, activeValue, dims, navWidth, reducedMotion, minWidth, maxWidth]);

  // ---- pointer / focus intent ---------------------------------------------
  React.useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mql = window.matchMedia("(pointer: fine)");
    const sync = () => setFinePointer(mql.matches);
    sync();
    mql.addEventListener("change", sync);
    return () => mql.removeEventListener("change", sync);
  }, []);

  React.useEffect(
    () => () => {
      if (closeTimer.current != null) window.clearTimeout(closeTimer.current);
    },
    []
  );

  const cancelClose = React.useCallback(() => {
    if (closeTimer.current != null) {
      window.clearTimeout(closeTimer.current);
      closeTimer.current = null;
    }
  }, []);

  const scheduleClose = React.useCallback(() => {
    cancelClose();
    closeTimer.current = window.setTimeout(() => setActive(null), closeDelay);
  }, [cancelClose, closeDelay, setActive]);

  const hoverMode = openOn === "hover" && finePointer;

  const handleTriggerEnter = (item: PantographItem) => {
    if (!hoverMode) return;
    cancelClose();
    if (item.content != null) setActive(item.value);
    else setActive(null);
  };

  const handleTriggerClick = (item: PantographItem) => {
    if (item.content == null) return; // let the link/button do its thing
    if (openOn === "click" || !finePointer) {
      setActive(activeValue === item.value ? null : item.value);
    }
  };

  // Click-away for click / touch open.
  React.useEffect(() => {
    if (!open || hoverMode) return;
    const onDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setActive(null);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [open, hoverMode, setActive]);

  // ---- keyboard: roving focus across triggers ------------------------------
  const enabledItems = items;
  const moveFocus = (fromValue: string, dir: 1 | -1 | "home" | "end") => {
    const count = enabledItems.length;
    if (count === 0) return;
    let idx = enabledItems.findIndex((i) => i.value === fromValue);
    if (idx < 0) idx = 0;
    let nextIdx: number;
    if (dir === "home") nextIdx = 0;
    else if (dir === "end") nextIdx = count - 1;
    else nextIdx = (idx + dir + count) % count;
    const next = enabledItems[nextIdx];
    if (!next) return;
    setFocusValue(next.value);
    triggerRefs.current.get(next.value)?.focus();
    if (open) {
      if (next.content != null) setActive(next.value);
      else setActive(null);
    }
  };

  const handleBarKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const from = focusValue || items[0]?.value || "";
    switch (e.key) {
      case "ArrowRight":
        e.preventDefault();
        moveFocus(from, 1);
        break;
      case "ArrowLeft":
        e.preventDefault();
        moveFocus(from, -1);
        break;
      case "Home":
        e.preventDefault();
        moveFocus(from, "home");
        break;
      case "End":
        e.preventDefault();
        moveFocus(from, "end");
        break;
      case "ArrowDown": {
        const item = items.find((i) => i.value === from);
        if (item?.content != null) {
          e.preventDefault();
          setActive(from);
        }
        break;
      }
      case "Escape":
        if (open) {
          e.preventDefault();
          setActive(null);
        }
        break;
      default:
        break;
    }
  };

  const handleRootBlur = (e: React.FocusEvent<HTMLDivElement>) => {
    if (!rootRef.current?.contains(e.relatedTarget as Node)) {
      cancelClose();
      setActive(null);
    }
  };

  const directionalContent = contentTransition === "directional" && !reducedMotion;
  const contentVariants: Variants = {
    enter: (dir: number) =>
      directionalContent
        ? { opacity: 0, x: dir * CONTENT_SHIFT, filter: "blur(5px)" }
        : { opacity: 0 },
    center: { opacity: 1, x: 0, filter: "blur(0px)" },
    exit: (dir: number) =>
      directionalContent
        ? { opacity: 0, x: -dir * CONTENT_SHIFT, filter: "blur(5px)" }
        : { opacity: 0 },
  };

  return (
    <nav
      {...props}
      aria-label={props["aria-label"] ?? "Main"}
      data-crucible="pantograph"
      className={cn("inline-block", className)}
    >
      <div
        ref={rootRef}
        className="relative inline-block"
        onPointerLeave={hoverMode ? scheduleClose : undefined}
        onPointerEnter={hoverMode ? cancelClose : undefined}
        onBlur={handleRootBlur}
      >
        {/* The trigger bar. */}
        <div
          ref={barRef}
          onKeyDown={handleBarKeyDown}
          className="relative flex items-center gap-1 rounded-full border border-white/10 bg-neutral-900/70 p-1.5 backdrop-blur-md"
        >
          {items.map((item) => {
            const isActive = item.value === activeValue && item.content != null;
            const hasPanel = item.content != null;
            const commonProps = {
              ref: (el: HTMLElement | null) => {
                if (el) triggerRefs.current.set(item.value, el);
                else triggerRefs.current.delete(item.value);
              },
              // Disclosure pattern (not an ARIA menu — the panel holds plain
              // links): triggers expose aria-expanded / aria-controls only.
              tabIndex: item.value === (focusValue || items[0]?.value) ? 0 : -1,
              "aria-expanded": hasPanel ? isActive : undefined,
              "aria-controls": hasPanel && isActive ? panelId : undefined,
              onFocus: () => {
                setFocusValue(item.value);
                if (hasPanel) setActive(item.value);
                else setActive(null);
              },
              onPointerEnter: () => handleTriggerEnter(item),
              className: cn(
                "relative rounded-full px-3.5 py-1.5 text-sm font-medium whitespace-nowrap transition-colors",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/50 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
                isActive ? "text-white" : "text-white/60 hover:text-white/90"
              ),
            };

            const inner = (
              <>
                {isActive && (
                  <motion.span
                    layoutId={`${baseId}-trigger-glow`}
                    aria-hidden
                    className="absolute inset-0 -z-10 rounded-full bg-white/[0.07]"
                    transition={
                      reducedMotion
                        ? { duration: 0 }
                        : { type: "spring", stiffness: 620, damping: 34 }
                    }
                  />
                )}
                <span className="relative">{item.label}</span>
              </>
            );

            return item.href ? (
              <a
                key={item.value}
                href={item.href}
                {...commonProps}
                onClick={(e) => {
                  if (hasPanel && (openOn === "click" || !finePointer)) {
                    e.preventDefault();
                    handleTriggerClick(item);
                  }
                }}
              >
                {inner}
              </a>
            ) : (
              <button
                key={item.value}
                type="button"
                {...commonProps}
                onClick={() => handleTriggerClick(item)}
              >
                {inner}
              </button>
            );
          })}
        </div>

        {/* The single shared flyout that morphs between triggers. */}
        <AnimatePresence>
          {open && activeItem && (
            <motion.div
              id={panelId}
              role="region"
              aria-label={
                typeof activeItem.label === "string" ? activeItem.label : undefined
              }
              key="pantograph-panel"
              className="absolute top-full left-0 z-20 mt-3 origin-top"
              style={{ x: leftMV, width: widthMV, height: heightMV }}
              initial={
                reducedMotion
                  ? { opacity: 0 }
                  : { opacity: 0, scale: 0.96, y: -6 }
              }
              animate={
                reducedMotion
                  ? { opacity: 1 }
                  : { opacity: 1, scale: 1, y: 0 }
              }
              exit={
                reducedMotion
                  ? { opacity: 0 }
                  : { opacity: 0, scale: 0.97, y: -6 }
              }
              transition={
                reducedMotion
                  ? { duration: 0.12 }
                  : { type: "spring", stiffness: 500, damping: 40, mass: 0.7 }
              }
              onPointerEnter={hoverMode ? cancelClose : undefined}
              onPointerLeave={hoverMode ? scheduleClose : undefined}
            >
              <div className="relative h-full w-full overflow-hidden rounded-2xl border border-white/10 bg-neutral-900/85 shadow-[0_1px_0_rgba(255,255,255,0.06)_inset,0_24px_60px_-20px_rgba(0,0,0,0.8)] backdrop-blur-xl">
                {/* Top hairline sheen. */}
                <div
                  aria-hidden
                  className="pointer-events-none absolute inset-x-0 top-0 h-px bg-linear-to-r from-transparent via-white/25 to-transparent"
                />
                <AnimatePresence
                  mode="popLayout"
                  initial={false}
                  custom={direction}
                >
                  <motion.div
                    key={activeItem.value}
                    custom={direction}
                    variants={contentVariants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    transition={
                      reducedMotion
                        ? { duration: 0.14 }
                        : {
                            type: "spring",
                            stiffness: 520,
                            damping: 42,
                            mass: 0.7,
                          }
                    }
                    className="absolute inset-0 p-3"
                  >
                    {activeItem.content}
                  </motion.div>
                </AnimatePresence>
              </div>

              {/* Caret — slides to track the active trigger, never teleports. */}
              {caret && (
                <motion.span
                  aria-hidden
                  className="pointer-events-none absolute -top-1.5 z-10 h-3 w-3 -translate-x-1/2 rotate-45 rounded-tl-[3px] border-t border-l border-white/10 bg-neutral-900/85 backdrop-blur-xl"
                  style={{ left: caretX }}
                />
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Hidden measurers — natural content size drives the morph target. */}
      <div
        aria-hidden
        className="pointer-events-none invisible fixed top-0 left-0 -z-50"
        style={{ visibility: "hidden" }}
      >
        {items.map((item) =>
          item.content != null ? (
            <div
              key={item.value}
              data-measure-key={item.value}
              ref={(el) => {
                if (el) measureRefs.current.set(item.value, el);
                else measureRefs.current.delete(item.value);
              }}
              className="absolute w-max p-3"
            >
              {item.content}
            </div>
          ) : null
        )}
      </div>
    </nav>
  );
}

"use client";

import * as React from "react";
import { Mesh, Program, Renderer, Triangle } from "ogl";

import { cn } from "@/lib/utils";
import { clampDpr, useDprCap } from "@/hooks/use-dpr-cap";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

/** A single OGL uniform. Mirrors OGL's `{ value }` convention. */
export interface Uniform<T = unknown> {
  value: T;
}

/** Caller-supplied uniform map, merged over the auto-managed uniforms. */
export type UniformMap = Record<string, Uniform>;

export interface OglCanvasProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * GLSL ES 1.00 fragment shader source. Must declare `precision` and write
   * `gl_FragColor`. Receives the auto-managed uniforms plus anything in
   * `uniforms`, and the `vUv` varying (0–1 across the canvas).
   */
  fragment: string;
  /**
   * Optional vertex shader override. Defaults to a fullscreen-triangle
   * pass-through that forwards `uv` as `vUv`. Rarely needed.
   */
  vertex?: string;
  /**
   * Caller uniforms merged over the built-ins. Values are read on every commit,
   * so passing a fresh object with updated `.value`s live-updates the shader.
   * Reserved names `uTime`, `uResolution`, `uPointer`, `uPointerActive` are managed for you.
   */
  uniforms?: UniformMap;
  /**
   * devicePixelRatio ceiling. The effective DPR is
   * `min(window.devicePixelRatio, dpr)`. Default 2.
   */
  dpr?: number;
  /** Freeze the RAF loop, holding the last rendered frame. */
  paused?: boolean;
  /**
   * Fired once the GL context is live and the FIRST frame has been rendered —
   * use it to fade the canvas in from a placeholder so the shader never pops in
   * suddenly after its chunk loads and initializes.
   */
  onReady?: () => void;
  /**
   * `uTime` (seconds) used for the single static frame rendered when the user
   * prefers reduced motion. Pick a value that looks good frozen. Default 4.
   */
  reducedMotionTime?: number;
  /**
   * Idle autoplay. When truthy, a ghost pointer takes over after ~1.5s with no
   * real pointer, drifting on a slow seeded Lissajous path so pointer-reactive
   * shaders never look dead in thumbnails and heroes; the real pointer takes
   * over instantly. `true` = presence 0.75 (fed to `uPointerActive`), or pass a
   * 0–1 number. Off by default so existing consumers are unchanged.
   */
  ghost?: boolean | number;
}

/** Ghost takes over this long after the last real pointer movement. */
const GHOST_DELAY_MS = 1500;

const DEFAULT_VERTEX = /* glsl */ `
precision highp float;
attribute vec2 position;
attribute vec2 uv;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

interface Internals {
  renderer: Renderer;
  mesh: Mesh;
  program: Program;
  uTime: Uniform<number>;
  uResolution: Uniform<[number, number]>;
  uPointer: Uniform<[number, number]>;
  /** Eased 0–1 presence of a real pointer over the canvas (0 once it leaves). */
  uPointerActive: Uniform<number>;
  /** Un-smoothed target the pointer lerps toward. */
  pointerTarget: [number, number];
  /** Un-smoothed target for `uPointerActive`. */
  pointerActiveTarget: number;
  loseContext: (() => void) | null;
}

/**
 * OGL's Program.setShaders early-returns on a failed link WITHOUT creating
 * `uniformLocations` — rendering such a program throws deep inside OGL. Treat
 * "unlinked" as "skip the frame": the GLSL warning is already in the console.
 */
function programLinked(program: Program): boolean {
  return (program as unknown as { uniformLocations?: unknown }).uniformLocations !== undefined;
}

/** Write caller uniform values into the live program, creating missing keys. */
function syncUniforms(program: Program, uniforms: UniformMap | undefined) {
  if (!uniforms) return;
  for (const key in uniforms) {
    const incoming = uniforms[key];
    const existing = program.uniforms[key];
    if (existing) existing.value = incoming.value;
    else program.uniforms[key] = { value: incoming.value };
  }
}

/**
 * ogl-canvas — a reusable client harness for fullscreen fragment-shader
 * backgrounds. Runs a single fullscreen triangle through your shader, manages
 * `uTime` / `uResolution` / `uPointer` / `uPointerActive` (eased 0–1 pointer presence) uniforms, clamps DPR, pauses offscreen
 * and on hidden tabs, and freezes at one frame under prefers-reduced-motion.
 * Full WebGL teardown on unmount.
 *
 * Build a background on top of it: supply a `fragment` and any `uniforms`.
 */
export function OglCanvas({
  fragment,
  vertex = DEFAULT_VERTEX,
  uniforms,
  dpr = 2,
  paused = false,
  reducedMotionTime = 4,
  ghost = false,
  onReady,
  className,
  ...rest
}: OglCanvasProps) {
  const internalsRef = React.useRef<Internals | null>(null);
  const [ready, setReady] = React.useState(false);
  // Latest onReady, called from the setup effect without re-triggering GL init.
  const onReadyRef = React.useRef(onReady);
  onReadyRef.current = onReady;
  // GL init can fail outright (context cap reached, blocked WebGL) and a live
  // context can be evicted later — both degrade to a static ember wash rather
  // than a crash or a black hole.
  const [failed, setFailed] = React.useState(false);

  const reducedMotion = useReducedMotion();
  const ghostStrength = ghost === true ? 0.75 : typeof ghost === "number" ? Math.max(0, Math.min(1, ghost)) : 0;
  const ghostRef = React.useRef(ghostStrength);
  ghostRef.current = ghostStrength;
  // performance.now() of the last real pointer activity; -Infinity = never.
  const lastRealPointerRef = React.useRef(-Infinity);
  // A real pointer resting over the canvas (even motionless) keeps the ghost away.
  const hoveringRef = React.useRef(false);
  // Latest caller uniforms, read inside the setup effect without re-triggering it.
  const uniformsRef = React.useRef(uniforms);
  uniformsRef.current = uniforms;

  // useVisibilityPause restarts its clock at 0 whenever its `paused` option
  // flips. Fold the time already shown into a base offset on every flip so
  // un-pausing resumes the shader where it froze instead of snapping to t=0.
  const loopPaused = paused || reducedMotion;
  const timeBaseRef = React.useRef(0);
  const lastElapsedRef = React.useRef(0);
  const prevLoopPausedRef = React.useRef(loopPaused);
  if (prevLoopPausedRef.current !== loopPaused) {
    prevLoopPausedRef.current = loopPaused;
    timeBaseRef.current += lastElapsedRef.current;
    lastElapsedRef.current = 0;
  }

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it || !programLinked(it.program)) return;
    lastElapsedRef.current = elapsed;
    const p = it.uPointer.value;
    const t = it.pointerTarget;
    const g = ghostRef.current;
    if (g > 0 && !hoveringRef.current && performance.now() - lastRealPointerRef.current > GHOST_DELAY_MS) {
      // Slow, non-repeating-looking drift that stays clear of the edges.
      const gt = timeBaseRef.current + elapsed;
      t[0] = 0.5 + 0.32 * Math.sin(gt * 0.23) * Math.cos(gt * 0.071);
      t[1] = 0.5 + 0.26 * Math.sin(gt * 0.17 + 1.3);
      it.pointerActiveTarget = g;
    }
    // Organic easing toward the real pointer.
    p[0] += (t[0] - p[0]) * 0.06;
    p[1] += (t[1] - p[1]) * 0.06;
    it.uPointerActive.value += (it.pointerActiveTarget - it.uPointerActive.value) * 0.06;
    it.uTime.value = timeBaseRef.current + elapsed;
    it.renderer.render({ scene: it.mesh });
  }, []);

  // The container is both the RAF gate (IntersectionObserver, via the hook) and
  // the ResizeObserver target. The loop is suppressed while paused or reduced.
  const containerRef = useVisibilityPause<HTMLDivElement>(tick, {
    paused: loopPaused,
  });

  // Host-imposed DPR ceiling (galleries of thumbnails cap fill rate).
  const dprCap = useDprCap();

  // Setup / teardown. Rebuilds only when the shader program or DPR changes.
  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // The canvas is created per mount, never reused: once WEBGL_lose_context
    // has killed a canvas's context (our teardown), that canvas can only ever
    // return the same dead context again — under StrictMode's double-mount a
    // reused JSX canvas would come back permanently black and OGL would crash
    // rendering an unlinked program.
    const canvas = document.createElement("canvas");
    canvas.setAttribute("aria-hidden", "true");
    canvas.className = "absolute inset-0 block h-full w-full";
    container.appendChild(canvas);

    const effectiveDpr = clampDpr(dprCap, dpr);

    let renderer: Renderer;
    let gl: Renderer["gl"];
    try {
      renderer = new Renderer({
        canvas,
        dpr: effectiveDpr,
        alpha: true,
        antialias: false, // fullscreen fragment pass — MSAA buys nothing
        premultipliedAlpha: false,
      });
      gl = renderer.gl;
      gl.clearColor(0, 0, 0, 0);
    } catch (err) {
      console.warn("[crucible] WebGL unavailable — rendering static fallback.", err);
      canvas.remove();
      setFailed(true);
      return;
    }

    const onContextLost = (e: Event) => {
      e.preventDefault();
      setFailed(true);
    };
    canvas.addEventListener("webglcontextlost", onContextLost);

    const uTime: Uniform<number> = { value: 0 };
    const uResolution: Uniform<[number, number]> = {
      value: [gl.drawingBufferWidth || 1, gl.drawingBufferHeight || 1],
    };
    const uPointer: Uniform<[number, number]> = { value: [0.5, 0.5] };
    // Shaders that react to the pointer should scale that reaction by this, so
    // the effect releases when the pointer leaves instead of parking at center.
    const uPointerActive: Uniform<number> = { value: 0 };

    const program = new Program(gl, {
      vertex,
      fragment,
      uniforms: {
        uTime,
        uResolution,
        uPointer,
        uPointerActive,
        ...(uniformsRef.current ?? {}),
      },
    });

    const geometry = new Triangle(gl);
    const mesh = new Mesh(gl, { geometry, program });

    const loseExt = gl.getExtension("WEBGL_lose_context");

    const internals: Internals = {
      renderer,
      mesh,
      program,
      uTime,
      uResolution,
      uPointer,
      uPointerActive,
      pointerTarget: [0.5, 0.5],
      pointerActiveTarget: 0,
      loseContext: loseExt ? () => loseExt.loseContext() : null,
    };
    internalsRef.current = internals;

    const renderStatic = () => {
      if (!programLinked(program)) return;
      uTime.value = reducedMotion ? reducedMotionTime : uTime.value;
      renderer.render({ scene: mesh });
    };

    // setSize reallocates the drawing buffer — skip no-op calls (the observer's
    // initial callback repeats the size the synchronous mount call just set).
    let sizedW = -1;
    let sizedH = -1;
    const resize = () => {
      const { clientWidth: w, clientHeight: h } = container;
      if (w === sizedW && h === sizedH) return;
      sizedW = w;
      sizedH = h;
      renderer.setSize(Math.max(w, 1), Math.max(h, 1));
      uResolution.value[0] = gl.drawingBufferWidth;
      uResolution.value[1] = gl.drawingBufferHeight;
      // Keep the frame correct even while the loop is idle (paused/reduced).
      if (programLinked(program)) renderer.render({ scene: mesh });
    };

    const ro = new ResizeObserver(resize);
    ro.observe(container);
    resize();
    renderStatic();

    const onPointerMove = (e: PointerEvent) => {
      const r = container.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) return;
      internals.pointerTarget[0] = (e.clientX - r.left) / r.width;
      // Flip Y so "up" on screen is 1.
      internals.pointerTarget[1] = 1 - (e.clientY - r.top) / r.height;
      internals.pointerActiveTarget = 1;
      lastRealPointerRef.current = performance.now();
      hoveringRef.current = true;
    };
    const onPointerLeave = () => {
      internals.pointerActiveTarget = 0;
      hoveringRef.current = false;
      // Let the ghost resume after the usual delay rather than snapping in.
      lastRealPointerRef.current = performance.now();
      internals.pointerTarget[0] = 0.5;
      internals.pointerTarget[1] = 0.5;
    };
    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerleave", onPointerLeave);

    setReady(true);
    // The first frame is on screen — let the caller fade the canvas in.
    onReadyRef.current?.();

    return () => {
      setReady(false);
      internalsRef.current = null;
      ro.disconnect();
      canvas.removeEventListener("webglcontextlost", onContextLost);
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
      internals.loseContext?.();
      canvas.remove();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fragment, vertex, dpr, dprCap]);

  // Live-sync caller uniforms every commit; re-render if the loop is idle so
  // static frames reflect prop changes (paused, reduced motion).
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !programLinked(it.program)) return;
    syncUniforms(it.program, uniforms);
    if (paused || reducedMotion) {
      if (reducedMotion) it.uTime.value = reducedMotionTime;
      it.renderer.render({ scene: it.mesh });
    }
  });

  // Render the frozen frame whenever the static conditions change.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !ready || !programLinked(it.program)) return;
    if (paused || reducedMotion) {
      if (reducedMotion) {
        it.uTime.value = reducedMotionTime;
        it.uPointer.value[0] = 0.5;
        it.uPointer.value[1] = 0.5;
      }
      it.renderer.render({ scene: it.mesh });
    }
  }, [paused, reducedMotion, reducedMotionTime, ready]);

  return (
    <div
      ref={containerRef}
      className={cn("relative block h-full w-full overflow-hidden", className)}
      {...rest}
    >
      {failed && (
        <div
          aria-hidden
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(120% 90% at 50% 100%, rgba(255,107,53,0.16), rgba(193,18,31,0.08) 45%, transparent 75%)",
          }}
        />
      )}
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useAnimate, type Transition } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/* ---------------------------------------------------------------- types */

/** Input kind of a form field. */
export type ParleyFieldType = "text" | "email" | "tel" | "number" | "textarea" | "select" | "segmented";

export interface ParleyOption {
  /** Submitted value. */
  value: string;
  /** Visible label. */
  label: string;
}

export interface ParleyField {
  /**
   * Key in the submitted values. Fields that share a `name` across topics
   * keep their value and glide to their new position when the topic changes.
   */
  name: string;
  /** Visible label. */
  label: string;
  /** Input kind. @default "text" */
  type?: ParleyFieldType;
  /** Placeholder text (text-like inputs and textarea). */
  placeholder?: string;
  /** Choices for `select` and `segmented` fields (strings use the same value and label). */
  options?: (ParleyOption | string)[];
  /** Initial value (e.g. the preselected segmented choice). */
  defaultValue?: string;
  /** Must be filled before submit. @default false */
  required?: boolean;
  /** Message shown when a required field is empty. @default "{label} is required." */
  requiredMessage?: string;
  /** Format check applied to non-empty values. */
  pattern?: RegExp;
  /** Message shown when `pattern` fails. @default "Check the format of this field." */
  patternMessage?: string;
  /** Custom validator; return a message to flag the field. Runs after the built-in checks. */
  validate?: (value: string, values: Record<string, string>) => string | undefined | null;
  /** Half width beside its neighbour when the form is wide enough. @default false */
  half?: boolean;
  /** Small helper line under the input. */
  hint?: string;
  /** `autocomplete` attribute for text-like inputs. */
  autoComplete?: string;
  /** Visible rows for a textarea. @default 4 */
  rows?: number;
}

/** Built-in topic glyphs. Pass a node for your own icon. */
export type ParleyTopicGlyph = "sales" | "support" | "press" | "other";

export interface ParleyTopic {
  /** Stable id, passed back to `onSubmit`. */
  id: string;
  /** Chip label. */
  label: string;
  /** Built-in glyph name or your own icon node. @default "other" */
  icon?: ParleyTopicGlyph | React.ReactNode;
  /** Fields shown, in order, while this topic is selected. */
  fields: ParleyField[];
  /** Submit button label. @default "Send message" */
  submitLabel?: string;
  /** Expected-reply line under the form (e.g. "Replies within 2 hours"). */
  replyLine?: string;
  /** Body of the success card. @default "Your message is in. {replyLine}." */
  successMessage?: string;
}

/** Built-in channel glyphs. */
export type ParleyChannelKind = "email" | "chat" | "phone" | "other";

export interface ParleyChannel {
  /** Glyph and default link scheme. @default "other" */
  kind?: ParleyChannelKind;
  /** Card heading (e.g. "Email us"). */
  label: string;
  /** The visible contact value (address, handle, number). */
  value: string;
  /** Muted supporting line (hours, response time). */
  detail?: string;
  /** Link for the value. Email/phone default to `mailto:` / `tel:`. */
  href?: string;
  /** Text written to the clipboard. @default value */
  copyValue?: string;
}

export interface ParleyOffice {
  /** Card heading. @default "Visit the studio" */
  label?: string;
  /** Address lines. */
  lines: string[];
  /** Muted supporting line (opening hours). */
  detail?: string;
  /** Directions link. */
  href?: string;
  /** Text written to the clipboard. @default lines joined with ", " */
  copyValue?: string;
}

/** Imperative verbs exposed through the `ref` prop. */
export interface ParleyHandle {
  /** Clear every field, drop errors and the success card, and return to the default topic. */
  reset: () => void;
  /** Re-run the designed intro. */
  replay: () => void;
  /** Switch topic programmatically. */
  setTopic: (id: string) => void;
  /** Focus the first field of the form. */
  focus: () => void;
}

export interface ParleyProps extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title" | "onSubmit"> {
  /** Small label above the title. @default "Contact" */
  eyebrow?: React.ReactNode;
  /** Section heading. @default "Talk to the right person" */
  title?: React.ReactNode;
  /** Line under the heading. */
  subtitle?: React.ReactNode;
  /** Topic chips and the form each one routes to. Omit for Sales / Support / Press / Other. */
  topics?: ParleyTopic[];
  /** Uncontrolled initial topic id. @default first topic */
  defaultTopic?: string;
  /** Controlled topic id. */
  topic?: string;
  /** Called when the visitor picks a topic. */
  onTopicChange?: (id: string) => void;
  /**
   * Called with the current topic's values. Return a Promise to hold the
   * button in its pending state — resolve shows the success card, reject
   * keeps every value and shows the rejection's message inline.
   */
  onSubmit?: (values: Record<string, string>, topic: string) => void | Promise<unknown>;
  /** Side-column channel cards with copy-to-clipboard. Omit for a sample set; `[]` hides them. */
  channels?: ParleyChannel[];
  /** Office card with an abstract location plate, or `false` to hide it. */
  office?: ParleyOffice | false;
  /** Accent hex for the active chip, submit button, focus rings and pin. @default "#60a5fa" */
  accentColor?: string;
  /** Imperative handle (`reset()`, `replay()`, `setTopic()`, `focus()`). React 19 ref-as-prop. */
  ref?: React.Ref<ParleyHandle>;
  /** Extra classes for the `<section>` root. */
  className?: string;
}

