/* ---------------------------------------------------------------- helpers */

/** Black or white text, whichever reads against the accent fill. */
function readableOn(hex: string): string {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return "#0a0a0a";
  let s = m[1];
  if (s.length === 3) s = s.replace(/./g, (c) => c + c);
  const n = parseInt(s, 16);
  const lum = 0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255);
  return lum > 140 ? "#0a0a0a" : "#ffffff";
}

function normOptions(options: ParleyField["options"]): ParleyOption[] {
  return (options ?? []).map((o) => (typeof o === "string" ? { value: o, label: o } : o));
}

function initialValue(f: ParleyField): string {
  if (f.defaultValue != null) return f.defaultValue;
  if (f.type === "segmented") return normOptions(f.options)[0]?.value ?? "";
  return "";
}

function validateField(f: ParleyField, raw: string | undefined, values: Record<string, string>): string | undefined {
  const value = (raw ?? "").trim();
  if (!value) return f.required ? f.requiredMessage ?? `${f.label} is required.` : undefined;
  if (f.type === "email" && !EMAIL_RE.test(value)) return "That doesn't look like an email address.";
  if (f.pattern && !f.pattern.test(value)) return f.patternMessage ?? "Check the format of this field.";
  return f.validate?.(value, values) ?? undefined;
}

async function writeClipboard(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    /* fall through to the legacy path */
  }
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    ta.remove();
    return ok;
  } catch {
    return false;
  }
}

