/* ---------------------------------------------------------------- auto height */

/** Animates its own height to match its content (field enter/leave, form ↔ success). */
function AutoHeight({ children, instant }: { children: React.ReactNode; instant: boolean }) {
  const innerRef = React.useRef<HTMLDivElement>(null);
  const [height, setHeight] = React.useState<number | "auto">("auto");

  React.useEffect(() => {
    const el = innerRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(() => setHeight(el.offsetHeight));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    <motion.div
      initial={false}
      animate={{ height }}
      transition={instant ? INSTANT : SPRING}
      className="overflow-hidden"
    >
      <div ref={innerRef} className="flow-root">
        {children}
      </div>
    </motion.div>
  );
}

/* ---------------------------------------------------------------- copy button */

function CopyButton({
  text,
  label,
  reducedMotion,
  onCopied,
}: {
  text: string;
  label: string;
  reducedMotion: boolean;
  onCopied: (label: string, ok: boolean) => void;
}) {
  const [copied, setCopied] = React.useState(false);
  const timer = React.useRef<number | undefined>(undefined);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  const swap: Transition = reducedMotion ? { duration: 0.12 } : { duration: 0.22, ease: EASE };

  return (
    <button
      type="button"
      aria-label={copied ? `${label} copied` : `Copy ${label}`}
      title={copied ? "Copied" : "Copy"}
      onClick={async () => {
        const ok = await writeClipboard(text);
        onCopied(label, ok);
        if (!ok) return;
        setCopied(true);
        window.clearTimeout(timer.current);
        timer.current = window.setTimeout(() => setCopied(false), 1800);
      }}
      className={cn(
        "relative grid size-8 shrink-0 place-items-center rounded-lg border transition-colors duration-200",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--parley-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
        copied
          ? "border-[color-mix(in_srgb,var(--parley-accent)_45%,transparent)] bg-[color-mix(in_srgb,var(--parley-accent)_14%,transparent)] text-[var(--parley-accent)]"
          : "border-white/[0.08] bg-white/[0.03] text-white/55 hover:border-white/15 hover:text-white"
      )}
    >
      <AnimatePresence initial={false} mode="popLayout">
        {copied ? (
          <motion.svg
            key="check"
            aria-hidden
            viewBox="0 0 24 24"
            className="size-4"
            {...stroke}
            strokeWidth={2.1}
            initial={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6, rotate: -20 }}
            animate={{ opacity: 1, scale: 1, rotate: 0 }}
            exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            transition={swap}
          >
            <motion.path
              d="M5 12.5l4.5 4.5L19 7.5"
              initial={reducedMotion ? false : { pathLength: 0 }}
              animate={{ pathLength: 1 }}
              transition={reducedMotion ? INSTANT : { duration: 0.32, ease: EASE, delay: 0.05 }}
            />
          </motion.svg>
        ) : (
          <motion.svg
            key="copy"
            aria-hidden
            viewBox="0 0 24 24"
            className="size-4"
            {...stroke}
            initial={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6, rotate: 20 }}
            animate={{ opacity: 1, scale: 1, rotate: 0 }}
            exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            transition={swap}
          >
            <rect x="8.5" y="8.5" width="11" height="11" rx="2.2" />
            <path d="M15.5 8.5V6.2a1.7 1.7 0 0 0-1.7-1.7H6.2a1.7 1.7 0 0 0-1.7 1.7v7.6a1.7 1.7 0 0 0 1.7 1.7h2.3" />
          </motion.svg>
        )}
      </AnimatePresence>
    </button>
  );
}

