/* ---------------------------------------------------------------- field */

interface FieldProps {
  field: ParleyField;
  id: string;
  value: string;
  error?: string;
  shake: number;
  reducedMotion: boolean;
  registerFocus: (name: string, el: HTMLElement | null) => void;
  onChange: (name: string, value: string) => void;
  onBlur: (name: string) => void;
}

const inputBase =
  "w-full rounded-xl border bg-white/[0.03] px-3.5 text-sm text-white placeholder:text-white/30 transition-[border-color,background-color,box-shadow] duration-200 focus:outline-none focus:bg-white/[0.05] focus:border-[var(--parley-accent)] focus:shadow-[0_0_0_3px_color-mix(in_srgb,var(--parley-accent)_18%,transparent)]";

function Field({ field, id, value, error, shake, reducedMotion, registerFocus, onChange, onBlur }: FieldProps) {
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const errorId = `${id}-error`;
  const hintId = `${id}-hint`;
  const type = field.type ?? "text";
  const describedBy = [error ? errorId : null, field.hint ? hintId : null].filter(Boolean).join(" ") || undefined;
  const borderTone = error ? "border-red-400/55" : "border-white/[0.09] hover:border-white/[0.16]";

  React.useEffect(() => {
    if (!shake || reducedMotion || !scope.current) return;
    animate(scope.current, { x: [0, -7, 6, -4, 3, -1, 0] }, { duration: 0.42, ease: "easeOut" });
  }, [shake, reducedMotion, animate, scope]);

  const options = normOptions(field.options);
  const segRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const selectedIndex = Math.max(
    0,
    options.findIndex((o) => o.value === value)
  );

  let control: React.ReactNode;
  if (type === "textarea") {
    control = (
      <textarea
        ref={(el) => registerFocus(field.name, el)}
        id={id}
        name={field.name}
        rows={field.rows ?? 4}
        placeholder={field.placeholder}
        value={value}
        onChange={(e) => onChange(field.name, e.target.value)}
        onBlur={() => onBlur(field.name)}
        aria-invalid={error ? true : undefined}
        aria-required={field.required || undefined}
        aria-describedby={describedBy}
        className={cn(inputBase, borderTone, "block min-h-24 resize-y py-2.5 leading-relaxed")}
      />
    );
  } else if (type === "select") {
    control = (
      <div className="relative">
        <select
          ref={(el) => registerFocus(field.name, el)}
          id={id}
          name={field.name}
          value={value}
          onChange={(e) => onChange(field.name, e.target.value)}
          onBlur={() => onBlur(field.name)}
          aria-invalid={error ? true : undefined}
          aria-required={field.required || undefined}
          aria-describedby={describedBy}
          className={cn(inputBase, borderTone, "h-11 cursor-pointer appearance-none pr-9", !value && "text-white/40")}
        >
          {options.map((o) => (
            <option key={o.value} value={o.value} disabled={o.value === "" && field.required} className="bg-neutral-900 text-white">
              {o.label}
            </option>
          ))}
        </select>
        <svg
          aria-hidden
          viewBox="0 0 24 24"
          className="pointer-events-none absolute top-1/2 right-3 size-4 -translate-y-1/2 text-white/40"
          {...stroke}
        >
          <path d="m7 10 5 5 5-5" />
        </svg>
      </div>
    );
  } else if (type === "segmented") {
    const move = (to: number) => {
      const i = (to + options.length) % options.length;
      onChange(field.name, options[i].value);
      segRefs.current[i]?.focus();
    };
    control = (
      <div
        role="radiogroup"
        aria-labelledby={`${id}-label`}
        aria-describedby={describedBy}
        className="grid gap-1 rounded-xl border border-white/[0.09] bg-white/[0.03] p-1"
        style={{ gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))` }}
      >
        {options.map((o, i) => {
          const checked = i === selectedIndex;
          return (
            <button
              key={o.value}
              ref={(el) => {
                segRefs.current[i] = el;
                if (checked) registerFocus(field.name, el);
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={checked ? 0 : -1}
              onClick={() => onChange(field.name, o.value)}
              onBlur={() => onBlur(field.name)}
              onKeyDown={(e) => {
                if (e.key === "ArrowRight" || e.key === "ArrowDown") {
                  e.preventDefault();
                  move(i + 1);
                } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
                  e.preventDefault();
                  move(i - 1);
                } else if (e.key === "Home") {
                  e.preventDefault();
                  move(0);
                } else if (e.key === "End") {
                  e.preventDefault();
                  move(options.length - 1);
                }
              }}
              className={cn(
                "relative isolate flex h-9 min-w-0 items-center justify-center gap-1.5 rounded-lg px-1 text-[13px] font-medium transition-colors duration-200",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--parley-accent)]",
                checked ? "text-white" : "text-white/50 hover:text-white/80"
              )}
            >
              {checked ? (
                <motion.span
                  layoutId={`${id}-seg`}
                  transition={reducedMotion ? INSTANT : SPRING}
                  className="absolute inset-0 -z-10 rounded-lg border border-white/[0.1] bg-white/[0.08]"
                />
              ) : null}
              {o.value === "urgent" || o.value === "high" ? (
                <span
                  aria-hidden
                  className={cn("size-1.5 shrink-0 rounded-full", o.value === "urgent" ? "bg-rose-400" : "bg-amber-300")}
                />
              ) : null}
              <span className="truncate">{o.label}</span>
            </button>
          );
        })}
      </div>
    );
  } else {
    control = (
      <input
        ref={(el) => registerFocus(field.name, el)}
        id={id}
        name={field.name}
        type={type === "number" ? "text" : type}
        inputMode={type === "number" ? "numeric" : type === "email" ? "email" : type === "tel" ? "tel" : undefined}
        autoComplete={field.autoComplete ?? "off"}
        placeholder={field.placeholder}
        value={value}
        onChange={(e) => onChange(field.name, e.target.value)}
        onBlur={() => onBlur(field.name)}
        aria-invalid={error ? true : undefined}
        aria-required={field.required || undefined}
        aria-describedby={describedBy}
        className={cn(inputBase, borderTone, "h-11", type === "number" && "tabular-nums")}
      />
    );
  }

  return (
    <div ref={scope} className="flex flex-col gap-1.5">
      <div className="flex items-baseline justify-between gap-3">
        {type === "segmented" ? (
          <span id={`${id}-label`} className="text-[13px] font-medium text-white/75">
            {field.label}
          </span>
        ) : (
          <label id={`${id}-label`} htmlFor={id} className="text-[13px] font-medium text-white/75">
            {field.label}
          </label>
        )}
        {!field.required && type !== "segmented" && type !== "select" ? (
          <span className="text-[11px] text-white/30">Optional</span>
        ) : null}
      </div>
      {control}
      <AnimatePresence initial={false}>
        {error ? (
          <motion.p
            key="err"
            id={errorId}
            initial={reducedMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.18 }}
            className="flex items-center gap-1.5 text-xs text-red-300"
          >
            <svg aria-hidden viewBox="0 0 24 24" className="size-3.5 shrink-0" {...stroke} strokeWidth={2}>
              <circle cx="12" cy="12" r="8.5" />
              <path d="M12 7.8v5M12 16.2h.01" />
            </svg>
            {error}
          </motion.p>
        ) : field.hint ? (
          <p id={hintId} className="text-xs text-white/35">
            {field.hint}
          </p>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

/* ---------------------------------------------------------------- main */

type Phase = "idle" | "pending" | "error" | "success";

/**
 * Parley — a contact section that routes before it asks. A radiogroup of
 * topic chips sits atop the form; picking one reshapes it — fields glide in
 * and out with layout animation, values carry across topics by field name,
 * and the submit label and expected-reply line change with the route.
 * Validation runs on blur with a short shake and inline messages; an async
 * `onSubmit` drives pending → success (a drawn check with "Send another") or
 * an inline error that keeps every value. A side column holds channel cards
 * with copy-to-clipboard (the icon morphs to a check) and an office card with
 * an abstract SVG street plate and pulsing pin. Reduced motion: crossfades
 * only, no shake, no pulse.
 */
export function Parley({
  eyebrow = "Contact",
  title = "Talk to the right person",
  subtitle = "Pick a topic and we'll route you straight to the team that can help — no ticket mazes, no bots.",
  topics = DEFAULT_TOPICS,
  defaultTopic,
  topic: topicProp,
  onTopicChange,
  onSubmit,
  channels = DEFAULT_CHANNELS,
  office = DEFAULT_OFFICE,
  accentColor = DEFAULT_ACCENT,
  ref,
  className,
  style,
  ...props
}: ParleyProps) {
  const reducedMotion = useReducedMotion();
  const uid = React.useId().replace(/[:]/g, "");
  const rootRef = React.useRef<HTMLElement>(null);
  const successRef = React.useRef<HTMLHeadingElement>(null);
  const focusMap = React.useRef(new Map<string, HTMLElement>());
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const fallbackTopic = defaultTopic ?? topics[0]?.id ?? "";
  const [innerTopic, setInnerTopic] = React.useState(fallbackTopic);
  const topicId = topicProp ?? innerTopic;
  const current = topics.find((t) => t.id === topicId) ?? topics[0];
  const fields = React.useMemo(() => current?.fields ?? [], [current]);

  const seedValues = React.useCallback(() => {
    const v: Record<string, string> = {};
    for (const t of topics) for (const f of t.fields) if (!(f.name in v)) v[f.name] = initialValue(f);
    return v;
  }, [topics]);

  const [values, setValues] = React.useState<Record<string, string>>(seedValues);
  const [touched, setTouched] = React.useState<Record<string, boolean>>({});
  const [shakes, setShakes] = React.useState<Record<string, number>>({});
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [submitError, setSubmitError] = React.useState<string | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const [sentTopic, setSentTopic] = React.useState<ParleyTopic | null>(null);
  const pendingRef = React.useRef(false);
  const focusAfter = React.useRef<"success" | "first" | null>(null);

  // Designed intro: once, the first time the section is in view.
  const [seen, setSeen] = React.useState(false);
  const [run, setRun] = React.useState(0);
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setSeen(true);
          io.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  const shown = reducedMotion || seen;

  const accentInk = readableOn(accentColor);
  const pending = phase === "pending";

  const errors = React.useMemo(() => {
    const out: Record<string, string | undefined> = {};
    for (const f of fields) if (touched[f.name]) out[f.name] = validateField(f, values[f.name], values);
    return out;
  }, [fields, touched, values]);

  const selectTopic = React.useCallback(
    (id: string) => {
      if (id === topicId) return;
      const next = topics.find((t) => t.id === id);
      if (!next) return;
      if (topicProp == null) setInnerTopic(id);
      onTopicChange?.(id);
      setSubmitError(null);
      if (phase === "error") setPhase("idle");
      const added = next.fields.filter((f) => !fields.some((g) => g.name === f.name)).length;
      setAnnounce(`${next.label} form${added ? `, ${added} new field${added === 1 ? "" : "s"}` : ""}. ${next.replyLine ?? ""}`);
    },
    [topicId, topics, topicProp, onTopicChange, phase, fields]
  );

  const registerFocus = React.useCallback((name: string, el: HTMLElement | null) => {
    if (el) focusMap.current.set(name, el);
  }, []);

  const focusFirst = React.useCallback(() => {
    const first = fields[0];
    if (first) focusMap.current.get(first.name)?.focus({ preventScroll: false });
  }, [fields]);

  const handleChange = React.useCallback((name: string, value: string) => {
    setValues((v) => ({ ...v, [name]: value }));
  }, []);

  const handleBlur = React.useCallback(
    (name: string) => {
      const f = fields.find((x) => x.name === name);
      if (!f) return;
      // Don't flag untouched empty fields just for tabbing through — submit catches those.
      const value = values[name] ?? "";
      if (!touched[name] && !value.trim()) return;
      setTouched((t) => ({ ...t, [name]: true }));
      const err = validateField(f, value, values);
      // Shake when a new problem appears, not on every blur of an already-flagged field.
      if (err && err !== errors[name]) setShakes((s) => ({ ...s, [name]: (s[name] ?? 0) + 1 }));
    },
    [fields, values, touched, errors]
  );

  const reset = React.useCallback(() => {
    pendingRef.current = false;
    setValues(seedValues());
    setTouched({});
    setShakes({});
    setSubmitError(null);
    setPhase("idle");
    setSentTopic(null);
    if (topicProp == null) setInnerTopic(fallbackTopic);
    else if (topicProp !== fallbackTopic) onTopicChange?.(fallbackTopic);
  }, [seedValues, topicProp, fallbackTopic, onTopicChange]);

  const sendAnother = () => {
    // Keep who they are; clear what they said.
    const seeded = seedValues();
    setValues((v) => ({ ...seeded, name: v.name ?? "", email: v.email ?? "" }));
    setTouched({});
    setSubmitError(null);
    setPhase("idle");
    focusAfter.current = "first";
  };

  const replay = React.useCallback(() => {
    setSeen(true);
    setRun((r) => r + 1);
  }, []);

  React.useImperativeHandle(ref, () => ({ reset, replay, setTopic: selectTopic, focus: focusFirst }), [
    reset,
    replay,
    selectTopic,
    focusFirst,
  ]);

  React.useEffect(() => {
    if (focusAfter.current === "success" && phase === "success") {
      successRef.current?.focus({ preventScroll: true });
      focusAfter.current = null;
    }
  }, [phase]);

  // "Send another": the form mounts only after the success card exits, so focus from its ref.
  const formRef = React.useCallback(
    (el: HTMLFormElement | null) => {
      if (!el || focusAfter.current !== "first") return;
      focusAfter.current = null;
      requestAnimationFrame(() => focusFirst());
    },
    [focusFirst]
  );

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (pendingRef.current || !current) return;
    const invalid = fields.filter((f) => validateField(f, values[f.name], values));
    if (invalid.length) {
      setTouched((t) => {
        const next = { ...t };
        for (const f of fields) next[f.name] = true;
        return next;
      });
      setShakes((s) => {
        const next = { ...s };
        for (const f of invalid) next[f.name] = (next[f.name] ?? 0) + 1;
        return next;
      });
      setAnnounce(`${invalid.length} field${invalid.length === 1 ? " needs" : "s need"} attention.`);
      focusMap.current.get(invalid[0].name)?.focus();
      return;
    }
    const payload: Record<string, string> = {};
    for (const f of fields) payload[f.name] = (values[f.name] ?? "").trim();
    pendingRef.current = true;
    setSubmitError(null);
    setPhase("pending");
    setAnnounce("Sending…");
    try {
      await onSubmit?.(payload, current.id);
      pendingRef.current = false;
      setSentTopic(current);
      focusAfter.current = "success";
      setPhase("success");
      setAnnounce(`Message sent. ${current.replyLine ?? ""}`);
    } catch (err) {
      pendingRef.current = false;
      const msg = err instanceof Error && err.message ? err.message : "Something went wrong. Your message is still here — try again.";
      setSubmitError(msg);
      setPhase("error");
      setAnnounce("");
    }
  };

  const onCopied = React.useCallback((label: string, ok: boolean) => {
    setAnnounce(ok ? `${label} copied to clipboard.` : `Couldn't copy ${label}.`);
  }, []);

  /* ---- chip radiogroup keyboard ---- */
  const topicIndex = Math.max(0, topics.findIndex((t) => t.id === current?.id));
  const moveChip = (to: number) => {
    const i = (to + topics.length) % topics.length;
    selectTopic(topics[i].id);
    chipRefs.current[i]?.focus();
  };

  /* ---- intro choreography ---- */
  const enter = (delay: number) =>
    reducedMotion
      ? { initial: false as const, animate: { opacity: 1, y: 0 } }
      : {
          initial: { opacity: 0, y: 14 },
          animate: shown ? { opacity: 1, y: 0 } : { opacity: 0, y: 14 },
          transition: { duration: 0.55, ease: EASE, delay },
        };

  const fieldT: Transition = reducedMotion ? { duration: 0.15 } : SPRING;
  const focusRing =
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--parley-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950";

  const hasSide = channels.length > 0 || office !== false;
  const officeCopy = office ? office.copyValue ?? office.lines.join(", ") : "";
  const firstName = (values.name ?? "").trim().split(/\s+/)[0];

  return (
    <section
      ref={rootRef}
      data-crucible="parley"
      aria-labelledby={`${uid}-title`}
      className={cn("@container relative isolate w-full text-white", className)}
      style={{ ["--parley-accent" as string]: accentColor, ...style }}
      {...props}
    >
      <style>{`@keyframes parley-ping{0%{transform:scale(1);opacity:.55}100%{transform:scale(4.2);opacity:0}}.parley-ping{transform-box:fill-box;transform-origin:center;animation:parley-ping 2.2s cubic-bezier(0,0,.2,1) infinite}`}</style>

      <div key={run} className="mx-auto w-full max-w-6xl px-4 py-10 @xl:px-8 @xl:py-14">
        {/* Header */}
        <motion.header {...enter(0)} className="max-w-xl">
          <p className="inline-flex items-center gap-2 text-xs font-medium tracking-[0.16em] text-[var(--parley-accent)] uppercase">
            <span aria-hidden className="h-px w-5 bg-[var(--parley-accent)] opacity-70" />
            {eyebrow}
          </p>
          <h2 id={`${uid}-title`} className="mt-3 text-3xl font-semibold tracking-tight text-balance text-white @xl:text-4xl">
            {title}
          </h2>
          {subtitle ? <p className="mt-3 max-w-lg text-[15px] leading-relaxed text-pretty text-white/50">{subtitle}</p> : null}
        </motion.header>

        <div className={cn("mt-10 grid gap-5", hasSide && "@3xl:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)] @3xl:gap-6")}>
          {/* Form card */}
          <motion.div
            {...enter(0.08)}
            className="@container/form relative rounded-2xl border border-white/[0.08] bg-white/[0.025] shadow-[0_1px_0_0_rgba(255,255,255,0.04)_inset,0_24px_60px_-30px_rgba(0,0,0,0.8)]"
          >
            {/* top hairline glow */}
            <div
              aria-hidden
              className="pointer-events-none absolute inset-x-8 top-0 h-px"
              style={{ background: `linear-gradient(90deg, transparent, color-mix(in srgb, ${accentColor} 55%, transparent), transparent)` }}
            />
            <AutoHeight instant={reducedMotion}>
              <AnimatePresence initial={false} mode="wait">
                {phase === "success" ? (
                  <motion.div
                    key="success"
                    initial={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0 }}
                    transition={reducedMotion ? { duration: 0.15 } : { duration: 0.35, ease: EASE }}
                    className="flex min-h-[420px] flex-col items-center justify-center px-6 py-14 text-center"
                  >
                    <svg aria-hidden viewBox="0 0 64 64" className="size-16" fill="none">
                      <circle cx="32" cy="32" r="30" fill={accentColor} fillOpacity="0.08" />
                      <motion.circle
                        cx="32"
                        cy="32"
                        r="27"
                        stroke={accentColor}
                        strokeWidth="2"
                        strokeLinecap="round"
                        transform="rotate(-90 32 32)"
                        initial={reducedMotion ? false : { pathLength: 0 }}
                        animate={{ pathLength: 1 }}
                        transition={reducedMotion ? INSTANT : { duration: 0.55, ease: EASE }}
                      />
                      <motion.path
                        d="M21 33l7.5 7.5L44 25"
                        stroke={accentColor}
                        strokeWidth="3"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        initial={reducedMotion ? false : { pathLength: 0 }}
                        animate={{ pathLength: 1 }}
                        transition={reducedMotion ? INSTANT : { duration: 0.35, ease: EASE, delay: 0.38 }}
                      />
                    </svg>
                    <h3
                      ref={successRef}
                      tabIndex={-1}
                      className="mt-6 text-xl font-semibold tracking-tight text-white focus:outline-none"
                    >
                      {firstName ? `Thanks, ${firstName} — message sent` : "Message sent"}
                    </h3>
                    <p className="mt-2 max-w-xs text-sm leading-relaxed text-white/50">
                      {sentTopic?.successMessage ??
                        `It's with our ${sentTopic?.label.toLowerCase() ?? ""} team. ${sentTopic?.replyLine ? `${sentTopic.replyLine}.` : ""}`}
                    </p>
                    {values.email ? (
                      <p className="mt-4 rounded-full border border-white/[0.08] bg-white/[0.03] px-3 py-1 text-xs text-white/55">
                        Reply goes to <span className="text-white/80">{values.email}</span>
                      </p>
                    ) : null}
                    <button
                      type="button"
                      onClick={sendAnother}
                      className={cn(
                        "mt-7 inline-flex items-center gap-1.5 rounded-md text-sm font-medium text-[var(--parley-accent)] underline-offset-4 hover:underline",
                        focusRing
                      )}
                    >
                      Send another
                      <Glyph className="size-3.5">
                        <path d="M5 12h14m-5-5 5 5-5 5" />
                      </Glyph>
                    </button>
                  </motion.div>
                ) : (
                  <motion.form
                    key="form"
                    ref={formRef}
                    noValidate
                    onSubmit={handleSubmit}
                    aria-labelledby={`${uid}-title`}
                    initial={reducedMotion ? { opacity: 0 } : { opacity: 0, y: 8 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    transition={reducedMotion ? { duration: 0.15 } : { duration: 0.3, ease: EASE }}
                    className="p-4 @md:p-6"
                  >
                    {/* Topic chips */}
                    <div id={`${uid}-topic-label`} className="mb-2.5 text-[13px] font-medium text-white/75">
                      What&apos;s this about?
                    </div>
                    <div
                      role="radiogroup"
                      aria-labelledby={`${uid}-topic-label`}
                      className="grid grid-cols-2 gap-1 rounded-xl border border-white/[0.08] bg-black/30 p-1 @sm/form:grid-cols-4"
                      style={topics.length !== 4 ? { gridTemplateColumns: `repeat(${Math.min(topics.length, 4)}, minmax(0, 1fr))` } : undefined}
                    >
                      {topics.map((t, i) => {
                        const checked = i === topicIndex;
                        const icon =
                          t.icon != null && typeof t.icon !== "string" ? (
                            t.icon
                          ) : (
                            <Glyph>{TOPIC_GLYPHS[(t.icon as ParleyTopicGlyph) ?? "other"] ?? TOPIC_GLYPHS.other}</Glyph>
                          );
                        return (
                          <button
                            key={t.id}
                            ref={(el) => {
                              chipRefs.current[i] = el;
                            }}
                            type="button"
                            role="radio"
                            aria-checked={checked}
                            tabIndex={checked ? 0 : -1}
                            disabled={pending}
                            onClick={() => selectTopic(t.id)}
                            onKeyDown={(e) => {
                              if (e.key === "ArrowRight" || e.key === "ArrowDown") {
                                e.preventDefault();
                                moveChip(i + 1);
                              } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
                                e.preventDefault();
                                moveChip(i - 1);
                              } else if (e.key === "Home") {
                                e.preventDefault();
                                moveChip(0);
                              } else if (e.key === "End") {
                                e.preventDefault();
                                moveChip(topics.length - 1);
                              }
                            }}
                            className={cn(
                              "relative isolate flex h-10 min-w-0 items-center justify-center gap-2 rounded-lg px-2 text-sm font-medium transition-colors duration-200 disabled:cursor-not-allowed",
                              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--parley-accent)]",
                              checked ? "" : "text-white/50 hover:bg-white/[0.04] hover:text-white/85"
                            )}
                            style={checked ? { color: accentInk } : undefined}
                          >
                            {checked ? (
                              <motion.span
                                layoutId={`${uid}-chip`}
                                transition={reducedMotion ? INSTANT : SPRING}
                                className="absolute inset-0 -z-10 rounded-lg"
                                style={{
                                  backgroundColor: accentColor,
                                  boxShadow: `0 6px 20px -8px ${accentColor}, inset 0 1px 0 rgba(255,255,255,0.25)`,
                                }}
                              />
                            ) : null}
                            {icon}
                            <span className="truncate">{t.label}</span>
                          </button>
                        );
                      })}
                    </div>

                    {/* Fields */}
                    <fieldset disabled={pending} className="relative mt-6 grid min-w-0 grid-cols-1 gap-x-4 gap-y-5 @sm/form:grid-cols-2">
                      <legend className="sr-only">{current?.label} details</legend>
                      <AnimatePresence initial={false} mode="popLayout">
                        {fields.map((f) => (
                          <motion.div
                            key={f.name}
                            layout={reducedMotion ? false : "position"}
                            initial={reducedMotion ? { opacity: 0 } : { opacity: 0, y: 10, filter: "blur(4px)" }}
                            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                            exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.97, filter: "blur(4px)" }}
                            transition={fieldT}
                            className={cn("min-w-0", f.half ? "@sm/form:col-span-1" : "@sm/form:col-span-2")}
                          >
                            <Field
                              field={f}
                              id={`${uid}-${f.name}`}
                              value={values[f.name] ?? ""}
                              error={errors[f.name]}
                              shake={shakes[f.name] ?? 0}
                              reducedMotion={reducedMotion}
                              registerFocus={registerFocus}
                              onChange={handleChange}
                              onBlur={handleBlur}
                            />
                          </motion.div>
                        ))}
                      </AnimatePresence>
                    </fieldset>

                    {/* Submit error */}
                    <AnimatePresence initial={false}>
                      {phase === "error" && submitError ? (
                        <motion.div
                          key="submit-error"
                          role="alert"
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
                          exit={{ opacity: 0 }}
                          className="mt-5 flex items-start gap-2.5 rounded-xl border border-red-400/25 bg-red-500/[0.07] px-3.5 py-3 text-sm text-red-200"
                        >
                          <Glyph className="mt-0.5 text-red-300">
                            <path d="M12 4 21 19.5H3Z" />
                            <path d="M12 10v4M12 17h.01" />
                          </Glyph>
                          <span>{submitError}</span>
                        </motion.div>
                      ) : null}
                    </AnimatePresence>

                    {/* Footer: reply line + submit */}
                    <div className="mt-6 flex flex-col-reverse gap-4 border-t border-white/[0.07] pt-5 @sm/form:flex-row @sm/form:items-center @sm/form:justify-between">
                      <p className="flex items-center gap-2 text-xs text-white/45">
                        <span aria-hidden className="relative flex size-2">
                          {!reducedMotion ? (
                            <span className="absolute inline-flex size-full animate-ping rounded-full bg-emerald-400 opacity-50 [animation-duration:2.4s]" />
                          ) : null}
                          <span className="relative inline-flex size-2 rounded-full bg-emerald-400" />
                        </span>
                        <AnimatePresence initial={false} mode="popLayout">
                          <motion.span
                            key={current?.replyLine ?? "none"}
                            initial={reducedMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={reducedMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
                            transition={{ duration: 0.25, ease: EASE }}
                            className="tabular-nums"
                          >
                            {current?.replyLine ?? "We read every message"}
                          </motion.span>
                        </AnimatePresence>
                      </p>
                      <motion.button
                        type="submit"
                        layout={reducedMotion ? false : true}
                        transition={reducedMotion ? INSTANT : SPRING}
                        aria-disabled={pending || undefined}
                        aria-busy={pending || undefined}
                        className={cn(
                          "inline-flex h-11 shrink-0 items-center justify-center gap-2 overflow-hidden rounded-xl px-5 text-sm font-semibold whitespace-nowrap transition-[filter] hover:brightness-110 active:brightness-95",
                          focusRing
                        )}
                        style={{
                          backgroundColor: accentColor,
                          color: accentInk,
                          boxShadow: `0 10px 30px -12px ${accentColor}, inset 0 1px 0 rgba(255,255,255,0.3)`,
                        }}
                      >
                        <AnimatePresence initial={false} mode="popLayout">
                          <motion.span
                            key={pending ? "pending" : current?.submitLabel ?? "Send message"}
                            layout={reducedMotion ? false : "position"}
                            initial={reducedMotion ? { opacity: 0 } : { opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={reducedMotion ? { opacity: 0 } : { opacity: 0, y: -10 }}
                            transition={{ duration: 0.22, ease: EASE }}
                            className="inline-flex items-center gap-2"
                          >
                            {pending ? <Spinner /> : null}
                            {pending ? "Sending…" : current?.submitLabel ?? "Send message"}
                            {!pending ? (
                              <Glyph className="size-3.5">
                                <path d="M5 12h14m-5-5 5 5-5 5" />
                              </Glyph>
                            ) : null}
                          </motion.span>
                        </AnimatePresence>
                      </motion.button>
                    </div>
                  </motion.form>
                )}
              </AnimatePresence>
            </AutoHeight>
          </motion.div>

          {/* Side column */}
          {hasSide ? (
            <div className="grid content-start gap-3 @xl:grid-cols-2 @3xl:grid-cols-1">
              {channels.map((c, i) => {
                const kind = c.kind ?? "other";
                const href = c.href ?? (kind === "email" ? `mailto:${c.value}` : kind === "phone" ? `tel:${c.value.replace(/[^\d+]/g, "")}` : undefined);
                return (
                  <motion.div
                    key={`${c.label}-${c.value}`}
                    {...enter(0.16 + i * 0.06)}
                    className="group flex items-center gap-3.5 rounded-2xl @xl:col-start-1 @3xl:col-start-auto border border-white/[0.07] bg-white/[0.02] p-3.5 transition-colors duration-200 hover:border-white/[0.12] hover:bg-white/[0.035]"
                  >
                    <span
                      aria-hidden
                      className="grid size-10 shrink-0 place-items-center rounded-xl border border-white/[0.08] bg-white/[0.03] text-white/70 transition-colors duration-200 group-hover:text-[var(--parley-accent)]"
                    >
                      <Glyph className="size-[18px]">{CHANNEL_GLYPHS[kind]}</Glyph>
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="text-[13px] font-medium text-white/85">{c.label}</p>
                      {href ? (
                        <a
                          href={href}
                          className={cn(
                            "block truncate rounded-sm text-sm text-white/55 tabular-nums transition-colors hover:text-[var(--parley-accent)]",
                            focusRing
                          )}
                        >
                          {c.value}
                        </a>
                      ) : (
                        <p className="truncate text-sm text-white/55 tabular-nums">{c.value}</p>
                      )}
                      {c.detail ? <p className="mt-0.5 text-xs leading-snug text-pretty text-white/30">{c.detail}</p> : null}
                    </div>
                    <CopyButton
                      text={c.copyValue ?? c.value}
                      label={c.label}
                      reducedMotion={reducedMotion}
                      onCopied={onCopied}
                    />
                  </motion.div>
                );
              })}

              {office ? (
                <motion.div
                  {...enter(0.16 + channels.length * 0.06)}
                  className="flex flex-col overflow-hidden rounded-2xl border border-white/[0.07] bg-white/[0.02] @xl:col-start-2 @xl:row-start-1 @xl:row-span-3 @3xl:col-start-auto @3xl:row-start-auto @3xl:row-span-1"
                >
                  <div className="relative h-28 flex-1 border-b border-white/[0.06] @3xl:flex-none">
                    <LocationPlate accent={accentColor} reducedMotion={reducedMotion} shown={shown} />
                  </div>
                  <div className="flex items-start gap-3.5 p-3.5">
                    <div className="min-w-0 flex-1">
                      <p className="text-[13px] font-medium text-white/85">{office.label ?? "Visit the studio"}</p>
                      <address className="mt-0.5 text-sm leading-snug text-white/55 not-italic">
                        {office.lines.map((l) => (
                          <span key={l} className="block">
                            {l}
                          </span>
                        ))}
                      </address>
                      {office.detail ? <p className="mt-1 text-xs text-white/30">{office.detail}</p> : null}
                      {office.href ? (
                        <a
                          href={office.href}
                          className={cn(
                            "mt-2 inline-flex items-center gap-1 rounded-sm text-xs font-medium text-[var(--parley-accent)] underline-offset-4 hover:underline",
                            focusRing
                          )}
                        >
                          Get directions
                          <Glyph className="size-3">
                            <path d="M7 17 17 7M9 7h8v8" />
                          </Glyph>
                        </a>
                      ) : null}
                    </div>
                    <CopyButton
                      text={officeCopy}
                      label={office.label ? `${office.label} address` : "Address"}
                      reducedMotion={reducedMotion}
                      onCopied={onCopied}
                    />
                  </div>
                </motion.div>
              ) : null}
            </div>
          ) : null}
        </div>
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {announce}
      </p>
    </section>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface PasscodeProps {
  /** Controlled value — a string of up to `length` characters. Omit for uncontrolled use. */
  value?: string;
  /** Initial value when uncontrolled. @default "" */
  defaultValue?: string;
  /** Number of single-character cells. @default 6 */
  length?: number;
  /**
   * Accepted characters. `"numeric"` allows 0–9 (mobile number pad, one-time-code
   * autofill); `"alphanumeric"` allows 0–9 and A–Z. @default "numeric"
   */
  mode?: "numeric" | "alphanumeric";
  /** Hide entered characters behind dots (like a PIN). @default false */
  masked?: boolean;
  /** Fires on every change with the concatenated value. */
  onChange?: (value: string) => void;
  /** Fires once every cell is filled, with the complete code. */
  onComplete?: (value: string) => void;
  /**
   * `[accent, success]`. Accent lights the focus ring + caret; success flashes
   * the row when the code completes. @default indigo + emerald
   */
  colors?: [string, string] | string[];
  /** Animation-speed multiplier for the pop, caret blink and success flash. @default 1 */
  speed?: number;
  /** Freeze the caret blink and skip the success flash (still seats instantly). @default false */
  paused?: boolean;
  /** Disable all cells. @default false */
  disabled?: boolean;
  /** Focus the first cell on mount. @default false */
  autoFocus?: boolean;
  /** Submit name — emits a hidden input carrying the concatenated value. */
  name?: string;
  /**
   * Cell scale. `"md"` is the roomy standalone size; `"sm"` is a tighter
   * cell for auth cards, dialogs and narrow containers. @default "md"
   */
  size?: "sm" | "md";
  /** Accessible name for the group of cells. @default "Verification code" */
  "aria-label"?: string;
  className?: string;
}

const SIZES = {
  md: {
    gap: "gap-2 sm:gap-3",
    cell: "h-14 w-11 sm:w-12",
    radius: "rounded-xl",
    glyph: "text-2xl",
    dot: "h-2.5 w-2.5",
    caret: "h-6",
  },
  sm: {
    gap: "gap-1.5 sm:gap-2",
    cell: "h-12 w-10",
    radius: "rounded-[10px]",
    glyph: "text-xl",
    dot: "h-2 w-2",
    caret: "h-5",
  },
} as const;

/** Indigo accent, emerald success — neutral-elegant, cool. */
const DEFAULT_COLORS: [string, string] = ["#818cf8", "#34d399"];

function sanitize(input: string, mode: "numeric" | "alphanumeric"): string {
  return mode === "numeric"
    ? input.replace(/[^0-9]/g, "")
    : input.replace(/[^0-9a-zA-Z]/g, "");
}

/**
 * Passcode — a row of `length` segmented single-character cells backed by real
 * inputs. Typing advances focus and seats each digit with a soft pop; Backspace
 * retreats, arrow/Home/End keys move, and a paste (or SMS one-time-code autofill)
 * distributes across the cells. The focused empty cell shows an animated caret
 * inside an accent focus ring; the moment every cell is filled the row flashes
 * a success hue and `onComplete` fires. Fully keyboard operable, every cell
 * carries its own aria-label, and mobile gets a numeric keypad. Reduced motion
 * drops the pop, caret blink and flash — cells seat instantly and success shows
 * as a static colour change.
 */
export function Passcode({
  value,
  defaultValue = "",
  length = 6,
  mode = "numeric",
  masked = false,
  onChange,
  onComplete,
  colors = DEFAULT_COLORS,
  speed = 1,
  paused = false,
  disabled = false,
  autoFocus = false,
  name,
  size = "md",
  "aria-label": ariaLabel = "Verification code",
  className,
}: PasscodeProps) {
  const sz = SIZES[size] ?? SIZES.md;
  const reducedMotion = useReducedMotion();
  const animate = !reducedMotion && !paused;
  const count = Math.max(1, Math.floor(length));
  const spd = Math.max(0.1, speed);

  const [accent, success] = React.useMemo<[string, string]>(() => {
    const c = colors.length ? colors : DEFAULT_COLORS;
    return [c[0] ?? DEFAULT_COLORS[0], c[1] ?? DEFAULT_COLORS[1]];
  }, [colors]);

  const inputsRef = React.useRef<(HTMLInputElement | null)[]>([]);
  const groupRef = React.useRef<HTMLDivElement>(null);
  const completedRef = React.useRef(false);
  const [focusedIndex, setFocusedIndex] = React.useState<number | null>(null);
  const [pulseKey, setPulseKey] = React.useState(0);

  const isControlled = value !== undefined;
  const [internal, setInternal] = React.useState<string[]>(() =>
    Array.from({ length: count }, (_, i) => defaultValue[i] ?? "")
  );

  // Derive the fixed-length cell array from whichever source of truth is active.
  const chars = React.useMemo<string[]>(() => {
    const source = isControlled ? (value ?? "") : internal.join("");
    return Array.from({ length: count }, (_, i) => source[i] ?? "");
  }, [isControlled, value, internal, count]);

  const complete = chars.every((c) => c !== "");

  const commit = React.useCallback(
    (next: string[]) => {
      if (!isControlled) setInternal(next);
      onChange?.(next.join(""));
    },
    [isControlled, onChange]
  );

  // Fire onComplete once per completion; re-arm when the code is edited back down.
  React.useEffect(() => {
    if (complete && !completedRef.current) {
      completedRef.current = true;
      if (animate) setPulseKey((k) => k + 1);
      onComplete?.(chars.join(""));
    } else if (!complete && completedRef.current) {
      completedRef.current = false;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [complete]);

  const focusCell = React.useCallback(
    (index: number) => {
      const clamped = Math.max(0, Math.min(count - 1, index));
      const el = inputsRef.current[clamped];
      if (el) {
        el.focus();
        el.select();
      }
    },
    [count]
  );

  const setCharAt = React.useCallback(
    (index: number, char: string) => {
      const next = [...chars];
      next[index] = char;
      commit(next);
    },
    [chars, commit]
  );

  const distribute = React.useCallback(
    (start: number, incoming: string) => {
      if (!incoming) return;
      const next = [...chars];
      let idx = start;
      for (const ch of incoming) {
        if (idx >= count) break;
        next[idx] = ch;
        idx += 1;
      }
      commit(next);
      focusCell(Math.min(idx, count - 1));
    },
    [chars, commit, count, focusCell]
  );

  const handleChange = (index: number, event: React.ChangeEvent<HTMLInputElement>) => {
    let incoming = sanitize(event.target.value, mode);
    if (!incoming) {
      setCharAt(index, "");
      return;
    }
    // Typing into an already-filled cell without the text selected (e.g. after
    // a click repositioned the caret) yields old+new — keep only the new char
    // instead of spilling the old one into the next cell.
    const existing = chars[index];
    if (existing && incoming.length === 2) {
      incoming = incoming[0] === existing ? incoming.slice(1) : incoming.slice(0, 1);
    }
    distribute(index, incoming);
  };

  const handleKeyDown = (index: number, event: React.KeyboardEvent<HTMLInputElement>) => {
    switch (event.key) {
      case "Backspace":
        event.preventDefault();
        if (chars[index]) {
          setCharAt(index, "");
        } else if (index > 0) {
          setCharAt(index - 1, "");
          focusCell(index - 1);
        }
        break;
      case "Delete":
        event.preventDefault();
        setCharAt(index, "");
        break;
      case "ArrowLeft":
        event.preventDefault();
        focusCell(index - 1);
        break;
      case "ArrowRight":
        event.preventDefault();
        focusCell(index + 1);
        break;
      case "Home":
        event.preventDefault();
        focusCell(0);
        break;
      case "End":
        event.preventDefault();
        focusCell(count - 1);
        break;
      default:
        break;
    }
  };

  const handlePaste = (index: number, event: React.ClipboardEvent<HTMLInputElement>) => {
    event.preventDefault();
    const text = sanitize(event.clipboardData.getData("text"), mode);
    distribute(index, text);
  };

  const handleBlur = (event: React.FocusEvent<HTMLInputElement>) => {
    if (!groupRef.current?.contains(event.relatedTarget as Node | null)) {
      setFocusedIndex(null);
    }
  };

  const joined = chars.join("");
  // Spring time-scale ∝ 1/sqrt(stiffness): scale stiffness by spd² and damping
  // by spd so `speed` speeds the pop up/down while keeping the same overshoot.
  const popTransition = {
    type: "spring" as const,
    stiffness: 560 * spd * spd,
    damping: 22 * spd,
    mass: 0.6,
  };

  return (
    <div
      ref={groupRef}
      role="group"
      aria-label={ariaLabel}
      data-crucible="passcode"
      className={cn(
        "relative inline-flex items-center",
        sz.gap,
        disabled && "opacity-50",
        className
      )}
    >
      {chars.map((char, i) => {
        const isFocused = focusedIndex === i;
        const showCaret = isFocused && !char && !disabled;
        const cellColor = complete ? success : isFocused ? accent : undefined;

        return (
          <div
            key={i}
            className={cn("relative flex items-center justify-center", sz.cell)}
          >
            {/* Cell frame — neutral at rest, accent on focus, success on complete. */}
            <div
              aria-hidden
              className={cn(
                "pointer-events-none absolute inset-0 border bg-neutral-900/40 transition-colors",
                sz.radius,
                char ? "border-neutral-600" : "border-neutral-800",
                complete && "border-transparent"
              )}
              style={{
                borderColor: cellColor,
                boxShadow: isFocused && !complete ? `0 0 0 3px ${accent}33` : undefined,
                transitionDuration: reducedMotion ? "0ms" : "180ms",
              }}
            />

            {/* Success flash — a one-shot glow when the last cell fills. */}
            {animate && complete && (
              <motion.div
                key={pulseKey}
                aria-hidden
                className={cn("pointer-events-none absolute inset-0", sz.radius)}
                initial={{ opacity: 0.55, boxShadow: `0 0 0 4px ${success}66` }}
                animate={{ opacity: 0, boxShadow: `0 0 0 10px ${success}00` }}
                transition={{ duration: 0.5 / spd, ease: "easeOut" }}
              />
            )}

            {/* Visible glyph / caret. The real input above is transparent, so this
                layer owns every pixel the user sees. Decorative → aria-hidden. */}
            <div
              aria-hidden
              className="pointer-events-none relative z-10 flex h-full w-full items-center justify-center"
            >
              <AnimatePresence mode="popLayout" initial={false}>
                {char ? (
                  <motion.span
                    key={`char-${char}`}
                    className={cn("font-medium tabular-nums", sz.glyph)}
                    style={{ color: complete ? success : "#f5f5f5" }}
                    initial={animate ? { scale: 0.55, opacity: 0, y: 3 } : false}
                    animate={{ scale: 1, opacity: 1, y: 0 }}
                    exit={animate ? { scale: 0.55, opacity: 0 } : { opacity: 0 }}
                    transition={animate ? popTransition : { duration: 0 }}
                  >
                    {masked ? (
                      <span className={cn("inline-block rounded-full bg-current align-middle", sz.dot)} />
                    ) : (
                      char
                    )}
                  </motion.span>
                ) : showCaret ? (
                  <motion.span
                    key="caret"
                    className={cn("block w-[2px] rounded-full", sz.caret)}
                    style={{ backgroundColor: accent }}
                    initial={{ opacity: 1 }}
                    animate={animate ? { opacity: [1, 1, 0, 0] } : { opacity: 1 }}
                    transition={
                      animate
                        ? { duration: 1.06 / spd, repeat: Infinity, ease: "linear" }
                        : { duration: 0 }
                    }
                  />
                ) : null}
              </AnimatePresence>
            </div>

            {/* The real, accessible input — transparent text + caret so the layer
                above renders instead. Holds exactly one character of state. */}
            <input
              ref={(el) => {
                inputsRef.current[i] = el;
              }}
              type="text"
              inputMode={mode === "numeric" ? "numeric" : "text"}
              pattern={mode === "numeric" ? "[0-9]*" : undefined}
              autoComplete={i === 0 ? "one-time-code" : "off"}
              // eslint-disable-next-line jsx-a11y/no-autofocus
              autoFocus={autoFocus && i === 0}
              disabled={disabled}
              value={char}
              aria-label={`${mode === "numeric" ? "Digit" : "Character"} ${i + 1} of ${count}`}
              onChange={(e) => handleChange(i, e)}
              onKeyDown={(e) => handleKeyDown(i, e)}
              onPaste={(e) => handlePaste(i, e)}
              onFocus={(e) => {
                setFocusedIndex(i);
                e.target.select();
              }}
              onBlur={handleBlur}
              className={cn(
                "absolute inset-0 z-20 h-full w-full bg-transparent text-center",
                sz.radius,
                "text-transparent caret-transparent outline-none",
                "selection:bg-transparent selection:text-transparent",
                "disabled:cursor-not-allowed"
              )}
            />
          </div>
        );
      })}

      {name ? <input type="hidden" name={name} value={joined} /> : null}
    </div>
  );
}

"use client";

import { motion } from "motion/react";
import * as React from "react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cn } from "@/lib/utils";

export interface PastelPalette {
  /** Outer soft gradient — top stop. */
  base: string;
  /** Outer soft gradient — bottom stop. */
  baseAlt: string;
  /** Card surface fill. */
  surface: string;
  /** Nested surface (stat, input, chips) fill. */
  surfaceSoft: string;
  /** Primary accent — filled button, active chip, stat figure. */
  primary: string;
  /** Text/icon color that sits on `primary`. */
  onPrimary: string;
  /** Secondary accent — tints the second floating orb. */
  accent: string;
  /** Heading + body text. */
  text: string;
  /** Muted / secondary text. */
  muted: string;
  /** Hairline borders around the card and nested surfaces. */
  border: string;
}

export interface PastelPreset {
  /** Stable id used for controlled selection and React keys. */
  id: string;
  /** Chip label shown in the switcher. */
  label: string;
  /** Token set applied when this preset is active. */
  palette: PastelPalette;
}

