          d="M20 84 L30 62 Q34 55 44 54 L156 54 Q166 55 170 62 L180 84 Q181 90 174 90 L26 90 Q19 90 20 84 Z"
          fill="#170a2b" stroke={line} strokeWidth="1.6" />
