/**
 * Retro Forge — a synthwave DRIVE in GL. A perspective ground plane of glowing
 * magenta grid lines scrolls toward the viewer and melts into a layered violet
 * horizon bloom; an optional slit-scanned cyan sun sits on the line under a
 * faint star field, and a neon rear-view sports car cruises on the grid.
 * Built on the `ogl-canvas` harness: GPU-light, offscreen-paused,
 * reduced-motion-safe. Position it inside any `relative` container; it fills
 * and sits behind content.
 */
export function RetroForge({
  colors = DEFAULT_COLORS,
  speed = 1,
  heat = 1,
  cellSize = 60,
  sun = true,
  car = true,
  paused = false,
  idle = true,
  className,
  ...props
}: RetroForgeProps) {
  const reduced = useReducedMotion();
  const uniforms = React.useMemo(
    () => ({
      uLine: { value: hexToRgb(colors[0]) },
      uGlow: { value: hexToRgb(colors[1]) },
      uSun: { value: hexToRgb(colors[2]) },
      uSpeed: { value: speed },
      uHeat: { value: Math.min(Math.max(heat, 0), 1) },
      uCell: { value: Math.max(cellSize, 8) / 60 },
      uSunOn: { value: sun ? 1 : 0 },
    }),
    [colors, speed, heat, cellSize, sun]
  );

  return (
    <div
      aria-hidden
      className={cn("absolute inset-0 -z-10 overflow-hidden bg-neutral-950", className)}
      {...props}
    >
      <OglCanvas
        data-crucible="retro-forge"
        className="absolute inset-0"
        fragment={FRAGMENT}
        uniforms={uniforms}
        paused={paused}
      ghost={idle}
        reducedMotionTime={5.2}
      />
      {car && (
        <motion.div
          className="pointer-events-none absolute bottom-[6%] left-1/2 w-[32%] max-w-[400px] min-w-[210px]"
          style={{ x: "-50%" }}
          animate={paused || reduced ? undefined : { y: [0, -5, 0] }}
          transition={{ duration: 4.5, repeat: Infinity, ease: "easeInOut" }}
        >
          <OutrunCar line={colors[0]} sun={colors[2]} />
        </motion.div>
      )}
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useAnimationControls, type Transition } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface RecastProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /**
   * The text to display. Whenever it changes, the word re-forms: shared letters
   * slide to their new home while unique letters iris in/out.
   */
  children?: string;
  /**
   * Optional words to auto-cycle through. When provided, the component morphs
   * between them on a timer (pausing offscreen and on hidden tabs) and
   * `children` is ignored.
   */
  words?: string[];
  /** Milliseconds each cycled word holds before re-forming into the next. @default 2600 */
  interval?: number;
  /** Restart from the first word after the last (cycle mode). @default true */
  loop?: boolean;
  /** Freeze cycling on the current word. @default false */
  paused?: boolean;
  /** Seconds the position morph / iris takes. @default 0.6 */
  duration?: number;
  /** Seconds between each entering/leaving letter's start. @default 0.016 */
  stagger?: number;
  /** Fired whenever a new word becomes current (cycle mode). */
  onIndexChange?: (index: number) => void;
}

/** Occurrence-indexed keys so shared letters keep a stable identity across a
 *  morph (the second "n" in "Continue" stays the second "n"), which is what
 *  lets motion's layout engine slide them from their old slot to the new one
 *  instead of cross-fading. Letters with no match iris in/out. */
function keyLetters(text: string): { key: string; char: string }[] {
  const counts = new Map<string, number>();
  const out: { key: string; char: string }[] = [];
  for (const char of Array.from(text)) {
    const n = counts.get(char) ?? 0;
    counts.set(char, n + 1);
    out.push({ key: `${char}�${n}`, char });
  }
  return out;
}

/** Split into runs of word (non-space) vs. whitespace so the line only ever
 *  breaks at spaces — each word is its own nowrap group, never split mid-word. */
function tokenize(text: string): { text: string; isSpace: boolean }[] {
  const chars = Array.from(text);
  const tokens: { text: string; isSpace: boolean }[] = [];
  let i = 0;
  while (i < chars.length) {
    const isSpace = /\s/.test(chars[i]!);
    let j = i;
    while (j < chars.length && /\s/.test(chars[j]!) === isSpace) j++;
    tokens.push({ text: chars.slice(i, j).join(""), isSpace });
    i = j;
  }
  return tokens;
}

/** One word slot. Owns its own kerning-settle so a phrase's words settle
 *  independently. Letters are keyed by identity; motion's `layout` FLIPs the
 *  survivors along the baseline while `AnimatePresence` iris-transitions the
 *  rest. Shared letters never touch opacity, so they stay fully legible. */
function WordMorph({
  text,
  duration,
  stagger,
}: {
  text: string;
  duration: number;
  stagger: number;
}) {
  const controls = useAnimationControls();
  const letters = React.useMemo(() => keyLetters(text), [text]);
  const isFirst = React.useRef(true);

  // Kerning settle: once the letters have slid home, the word tightens by a
  // hair into its final rest, like type seating in a form. Driven as a
  // scaleX overshoot on the whole slot — a transform, so it never fights the
  // letters' layout measurement. Skipped on the initial word.
  React.useEffect(() => {
    if (isFirst.current) {
      isFirst.current = false;
      return;
    }
    void controls.start(
      { scaleX: [1.03, 1] },
      { duration: duration * 0.8, delay: duration * 0.45, ease: [0.22, 1, 0.36, 1] }
    );
  }, [text, duration, controls]);

  const positionTransition: Transition = { type: "spring", duration, bounce: 0.16 };

  return (
    <motion.span
      animate={controls}
      className="relative inline-block whitespace-nowrap align-baseline will-change-transform"
      style={{ transformOrigin: "50% 60%" }}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        {letters.map(({ key, char }, i) => (
          <motion.span
            key={key}
            layout
            initial={{ opacity: 0, scale: 0.28 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.28 }}
            transition={{
              layout: positionTransition,
              opacity: { duration: duration * 0.5, delay: i * stagger, ease: [0.4, 0, 0.2, 1] },
              scale: { type: "spring", duration: duration * 0.7, bounce: 0.32, delay: i * stagger },
            }}
            className="inline-block whitespace-pre align-baseline will-change-[transform,opacity]"
          >
            {char}
          </motion.span>
        ))}
      </AnimatePresence>
    </motion.span>
  );
}

/**
 * Recast — a word that re-forms into a new one. When the text changes, letters
 * shared with the previous word slide along the baseline to their new home
 * while unique letters iris in and out, so the surviving letters stay legible
 * the whole way through (no blur, no scramble, no flash). The letters tighten a
 * hair into their final kerning once they arrive. Neutral monochrome — it
 * inherits the surrounding text color. The first word server-renders as plain
 * text; reduced motion swaps the text instantly.
 */
export function Recast({
  children = "",
  words,
  interval = 2600,
  loop = true,
  paused = false,
  duration = 0.6,
  stagger = 0.016,
  onIndexChange,
  className,
  ...props
}: RecastProps) {
  const reducedMotion = useReducedMotion();
  const cycling = Array.isArray(words) && words.length > 0;

  const [index, setIndex] = React.useState(0);
  const [mounted, setMounted] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  const [inView, setInView] = React.useState(true);
  const wrapperRef = React.useRef<HTMLSpanElement>(null);

  const safeIndex = cycling ? Math.max(0, Math.min(index, words!.length - 1)) : 0;
  const currentText = cycling ? words![safeIndex] ?? "" : children;

  React.useEffect(() => {
    setMounted(true);
  }, []);

  // Pause cycling on hidden tabs and offscreen — nothing runs at rest.
  React.useEffect(() => {
    if (!cycling) return;
    const onVisibility = () => setHidden(document.hidden);
    document.addEventListener("visibilitychange", onVisibility);
    return () => document.removeEventListener("visibilitychange", onVisibility);
  }, [cycling]);

  React.useEffect(() => {
    if (!cycling) return;
    const node = wrapperRef.current;
    if (!node || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(([entry]) => {
      setInView(entry?.isIntersecting ?? true);
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, [cycling]);

  React.useEffect(() => {
    if (!cycling || paused || hidden || !inView || words!.length < 2) return;
    if (!loop && safeIndex === words!.length - 1) return;
    const id = window.setTimeout(() => {
      setIndex((i) => (i + 1) % words!.length);
    }, interval);
    return () => window.clearTimeout(id);
    // `words.length`, not `words`: an inline array literal is a new identity on
    // every parent render and would otherwise restart the hold timer each time.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cycling, safeIndex, paused, hidden, inView, loop, interval, words?.length]);

  const onIndexChangeRef = React.useRef(onIndexChange);
  React.useEffect(() => {
    onIndexChangeRef.current = onIndexChange;
  });
  const isFirstIndex = React.useRef(true);
  React.useEffect(() => {
    if (isFirstIndex.current) {
      isFirstIndex.current = false;
      return;
    }
    onIndexChangeRef.current?.(safeIndex);
  }, [safeIndex]);

  // Before mount and under reduced motion: plain, static, selectable text —
  // matches SSR exactly (no hydration mismatch) and never animates the first word.
  const showMorph = mounted && !reducedMotion;

  const tokens = React.useMemo(() => (showMorph ? tokenize(currentText) : []), [showMorph, currentText]);
  let wordSlot = 0;

  return (
    <span
      ref={wrapperRef}
      className={cn("inline-block align-baseline", className)}
      {...props}
    >
      {/* Polite live region announces the current word on every change. */}
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {currentText}
      </span>

      {showMorph ? (
        <span aria-hidden>
          {tokens.map((token, i) =>
            token.isSpace ? (
              <span key={`s-${i}`} className="whitespace-pre">
                {token.text}
              </span>
            ) : (
              <WordMorph
                key={`w-${wordSlot++}`}
                text={token.text}
                duration={duration}
                stagger={stagger}
              />
            )
          )}
        </span>
      ) : (
        <span aria-hidden>{currentText}</span>
      )}
    </span>
  );
}

"use client";

import { AnimatePresence, motion, type HTMLMotionProps } from "motion/react";
import * as React from "react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cn } from "@/lib/utils";

export type RippleSize = "sm" | "md" | "lg";

export interface RippleProps extends React.ComponentPropsWithoutRef<"button"> {
  /** Ripple ink color. Any CSS color; drawn at low opacity so it tints, never covers. @default soft white */
  color?: string;
  /** Padding / font scale of the button. @default "md" */
  size?: RippleSize;
  /** Peak opacity of the expanding ink, 0–1. Lower reads more restrained. @default 0.35 */
  intensity?: number;
  /** Seconds an ink drop takes to expand across the face and fade. @default 0.6 */
  duration?: number;
  /** Corner radius in px. @default 10 */
  radius?: number;
  /**
   * Render the passed child as the root element instead of a `<button>`,
   * merging in the ripple layer, press feedback, className, style and refs.
   * The child must forward props to a real interactive element. @default false
   */
  asChild?: boolean;
  /**
   * Imperative handle — see {@link RippleHandle}. Note this is the handle, not
   * the DOM node (Ripple never forwarded its element ref).
   */
  ref?: React.Ref<RippleHandle>;
}

/** Imperative controls exposed through the `ref` prop. */
export interface RippleHandle {
  /**
   * Bloom an ink drop without clicking: purely visual, fires no click and
   * never moves focus. `x`/`y` are px within the button (default: center).
   * Stacks with any drops already in flight.
   */
  pulse(x?: number, y?: number): void;
}

/** Concurrent drops are capped; the oldest is retired when a new one lands. */
const MAX_DROPS = 8;

interface Drop {
  id: number;
  /** Origin x within the button, in px. */
  x: number;
  /** Origin y within the button, in px. */
  y: number;
  /** Diameter that covers the whole face from this origin, in px. */
  size: number;
}

const SIZE_CLASSES: Record<RippleSize, string> = {
  sm: "px-4 py-2 text-xs gap-1.5",
  md: "px-6 py-3 text-sm gap-2",
  lg: "px-8 py-4 text-base gap-2.5",
};

/** Merge any number of refs (callback or object) into one callback ref. */
function mergeRefs<T>(...refs: Array<React.Ref<T> | undefined>): React.RefCallback<T> {
  return (value) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(value);
      else if (ref) (ref as React.MutableRefObject<T | null>).current = value;
    }
  };
}

/** Compose two event handlers; the injected one runs first, then the child's own. */
function composeHandlers<E>(
  theirs: ((event: E) => void) | undefined,
  ours: (event: E) => void
): (event: E) => void {
  return (event) => {
    ours(event);
    theirs?.(event);
  };
}

/**
 * Ripple — a Material-style ink ripple. On press a soft circle blooms from the
 * exact point of contact and fades; several presses stack their own concurrent
 * ripples (capped at 8). The face dips on a spring while held and rebounds on release.
 * Keyboard activation (Enter/Space) blooms from the center. Neutral-elegant by
 * default with a single `color` accent; `size` and `intensity` are the knobs.
 * Under prefers-reduced-motion the expanding bloom is replaced by one quiet,
 * full-face opacity flash — motion-free, never blank.
 */
export function Ripple({
  color = "rgba(255,255,255,0.9)",
  size = "md",
  intensity = 0.35,
  duration = 0.6,
  radius = 10,
  asChild = false,
  className,
  style,
  disabled,
  children,
  onPointerDown,
  onPointerUp,
  onPointerLeave,
  onClick,
  ref,
  ...rest
}: RippleProps) {
  const reducedMotion = useReducedMotion();
  const rootRef = React.useRef<HTMLElement>(null);
  const [drops, setDrops] = React.useState<Drop[]>([]);
  const [pressed, setPressed] = React.useState(false);
  const nextId = React.useRef(0);

  const timers = React.useRef(new Set<number>());
  React.useEffect(() => {
    const set = timers.current;
    return () => {
      for (const t of set) window.clearTimeout(t);
      set.clear();
    };
  }, []);

  /** Add one drop at (x, y) in button-local px; null = center. */
  const bloom = React.useCallback(
    (lx: number | null, ly: number | null) => {
      const el = rootRef.current;
      if (!el) return;
      // Layout size, not the transformed rect — the face may be mid press-dip.
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      const x = lx ?? w / 2;
      const y = ly ?? h / 2;
      // Diameter that reaches the farthest corner, so the ink always fills.
      const dia = Math.hypot(Math.max(x, w - x), Math.max(y, h - y)) * 2;

      const id = nextId.current++;
      setDrops((prev) => {
        const next = [...prev, { id, x, y, size: dia }];
        return next.length > MAX_DROPS ? next.slice(next.length - MAX_DROPS) : next;
      });
      const t = window.setTimeout(
        () => {
          timers.current.delete(t);
          setDrops((prev) => prev.filter((d) => d.id !== id));
        },
        // Keep the node past its animation (1.1x) so the fade completes.
        (reducedMotion ? 0.36 : duration) * 1100
      );
      timers.current.add(t);
    },
    [duration, reducedMotion]
  );

  const spawn = React.useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      const el = rootRef.current;
      if (!el) return;
      // Keyboard-activated clicks report detail 0 and no real pointer position —
      // bloom from the exact center in that case.
      if (event.detail === 0) return bloom(null, null);
      const rect = el.getBoundingClientRect();
      // Map through any press-dip scale so the drop lands under the finger.
      const sx = rect.width / (el.offsetWidth || rect.width || 1);
      const sy = rect.height / (el.offsetHeight || rect.height || 1);
      bloom((event.clientX - rect.left) / sx, (event.clientY - rect.top) / sy);
    },
    [bloom]
  );

  React.useImperativeHandle(
    ref,
    () => ({
      pulse(x?: number, y?: number) {
        if (disabled) return;
        bloom(x ?? null, y ?? null);
      },
    }),
    [bloom, disabled]
  );

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    if (!disabled) spawn(event);
    onClick?.(event as React.MouseEvent<HTMLButtonElement>);
  };

  const handlePointerDown = (event: React.PointerEvent<HTMLElement>) => {
    if (!disabled) setPressed(true);
    onPointerDown?.(event as React.PointerEvent<HTMLButtonElement>);
  };
  const release = () => setPressed(false);
  const handlePointerUp = (event: React.PointerEvent<HTMLElement>) => {
    release();
    onPointerUp?.(event as React.PointerEvent<HTMLButtonElement>);
  };
  const handlePointerLeave = (event: React.PointerEvent<HTMLElement>) => {
    release();
    onPointerLeave?.(event as React.PointerEvent<HTMLButtonElement>);
  };

  const pressTransition = reducedMotion
    ? { duration: 0.12, ease: "easeOut" as const }
    : { type: "spring" as const, stiffness: 420, damping: 24 };

  const rootClassName = cn(
    "relative isolate inline-flex select-none items-center justify-center overflow-hidden rounded-[inherit]",
    "border border-neutral-800 bg-neutral-900 font-medium text-white",
    "transition-colors duration-200 hover:border-neutral-700 hover:bg-neutral-800",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
    "focus-visible:ring-[color:var(--ripple-color)]",
    "disabled:cursor-not-allowed disabled:opacity-50 aria-disabled:cursor-not-allowed aria-disabled:opacity-50",
    SIZE_CLASSES[size],
    className
  );

  const rootStyle = {
    borderRadius: radius,
    "--ripple-color": color,
    ...style,
  } as React.CSSProperties;

  // The ink layer + label, shared by both the <button> and asChild paths.
  const inkLayer = (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-0 overflow-hidden rounded-[inherit]"
    >
      <AnimatePresence>
        {drops.map((drop) =>
          reducedMotion ? (
            // Reduced motion: a single quiet full-face flash, pinned to an
            // explicit resting pose (opacity 0) so it never freezes visible.
            <motion.span
              key={drop.id}
              className="absolute inset-0 rounded-[inherit]"
              style={{ background: color }}
              initial={{ opacity: intensity * 0.55 }}
              animate={{ opacity: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.36, ease: "easeOut" }}
            />
          ) : (
            <motion.span
              key={drop.id}
              className="absolute rounded-full"
              style={{
                left: drop.x,
                top: drop.y,
                translateX: "-50%",
                translateY: "-50%",
                background: `radial-gradient(circle, ${color} 0%, ${color} 58%, transparent 72%)`,
              }}
              initial={{ width: 0, height: 0, opacity: intensity }}
              animate={{ width: drop.size, height: drop.size, opacity: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration, ease: [0.16, 0.6, 0.32, 1] }}
            />
          )
        )}
      </AnimatePresence>
    </span>
  );

  const scale = pressed && !disabled && !reducedMotion ? 0.96 : 1;

  if (asChild) {
    const child = React.Children.only(children) as React.ReactElement<
      React.HTMLAttributes<HTMLElement> & { ref?: React.Ref<HTMLElement> }
    >;
    const childProps = child.props;
    return React.cloneElement(
      child,
      {
        // Forward the rest of Ripple's own props (aria-*, data-*, handlers…);
        // the child's same-named props still win.
        ...Object.fromEntries(Object.entries(rest).filter(([key]) => !(key in childProps))),
        "aria-disabled": disabled || undefined,
        ref: mergeRefs(rootRef, (child as unknown as { ref?: React.Ref<HTMLElement> }).ref),
        className: cn(rootClassName, childProps.className),
        style: {
          ...rootStyle,
          ...childProps.style,
          transform: `scale(${scale})`,
          transition: reducedMotion
            ? "transform 0.12s ease-out"
            : "transform 0.42s cubic-bezier(0.34,1.56,0.64,1)",
        },
        onClick: composeHandlers(childProps.onClick, handleClick),
        onPointerDown: composeHandlers(childProps.onPointerDown, handlePointerDown),
        onPointerUp: composeHandlers(childProps.onPointerUp, handlePointerUp),
        onPointerLeave: composeHandlers(childProps.onPointerLeave, handlePointerLeave),
      } as React.HTMLAttributes<HTMLElement> & { ref: React.Ref<HTMLElement> },
      <>
        {inkLayer}
        <span className="relative z-10 inline-flex items-center justify-center gap-[inherit]">
          {childProps.children}
        </span>
      </>
    );
  }

  return (
    <motion.button
      ref={rootRef as React.Ref<HTMLButtonElement>}
      data-crucible="ripple"
      className={rootClassName}
      style={rootStyle}
      disabled={disabled}
      animate={{ scale }}
      transition={pressTransition}
      onClick={handleClick}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerLeave}
      {...(rest as unknown as HTMLMotionProps<"button">)}
    >
      {inkLayer}
      <span className="relative z-10 inline-flex items-center justify-center gap-[inherit]">
        {children}
      </span>
    </motion.button>
  );
}

"use client";

import { AnimatePresence, motion, useInView, type Transition } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { Ratchet } from "@/components/crucible/ratchet";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { Quorum } from "@/components/crucible/quorum";

/* ---------------------------------------------------------------- types */

/** A single stored setting value. Avatars store an image URL (or `null`). */
export type RiggingValue = string | boolean | null;

/** All settings values, keyed by field `name`. */
export type RiggingValues = Record<string, RiggingValue>;

/** One choice in a select, segmented control or radio-card group. */
export interface RiggingOption {
  /** Stored value. */
  value: string;
  /** Visible label. */
  label: string;
  /** Optional secondary line (radio cards only). */
  description?: string;
}

interface RiggingFieldBase {
  /** Key in the values object. Must be unique across all sections. */
  name: string;
  /** Visible label. */
  label: string;
  /** Helper copy under the label. */
  description?: string;
}

/** Single-line text or email input with inline validation. */
export interface RiggingTextField extends RiggingFieldBase {
  kind: "text" | "email";
  placeholder?: string;
  /** Empty value is an error. */
  required?: boolean;
  /** Static adornment inside the input, e.g. `"@"` or a URL base. */
  prefix?: string;
  autoComplete?: string;
  /** Return an error message (or nothing) for the current value. */
  validate?: (value: string, values: RiggingValues) => string | null | undefined;
}

/** Multi-line text with a live character counter. */
export interface RiggingTextareaField extends RiggingFieldBase {
  kind: "textarea";
  placeholder?: string;
  /** Hard cap; the counter warms up as it approaches. @default 200 */
  maxLength?: number;
  /** Visible rows. @default 3 */
  rows?: number;
  required?: boolean;
  validate?: (value: string, values: RiggingValues) => string | null | undefined;
}

/** Circular avatar with click / drop to upload and remove. Stores a data URL. */
export interface RiggingAvatarField extends RiggingFieldBase {
  kind: "avatar";
  /** Name of a text field whose value supplies the fallback initials. */
  initialsFrom?: string;
  /** Reject files larger than this. @default 2 */
  maxSizeMb?: number;
}

/** On/off switch with a spring knob. */
export interface RiggingSwitchField extends RiggingFieldBase {
  kind: "switch";
}

/** Large selectable cards; `preview` draws a mini theme tile. */
export interface RiggingRadioCardsField extends RiggingFieldBase {
  kind: "radio-cards";
  options: (RiggingOption & { preview?: "system" | "light" | "dark" })[];
}

/** Native select (best-in-class a11y and mobile pickers). */
export interface RiggingSelectField extends RiggingFieldBase {
  kind: "select";
  options: RiggingOption[];
}

/** Segmented control (composes Quorum). Best with 2–4 short options. */
export interface RiggingSegmentedField extends RiggingFieldBase {
  kind: "segmented";
  options: RiggingOption[];
}

/** A hold-to-confirm action (composes Ratchet). Not a value — fires `onAction`. */
export interface RiggingActionField extends RiggingFieldBase {
  kind: "action";
  /** Button label while idle. @default "Hold to confirm" */
  actionLabel?: string;
  /** Label after the hold completes. @default "Done" */
  confirmedLabel?: string;
  /** `danger` is rust, `neutral` is graphite. @default "danger" */
  tone?: "danger" | "neutral";
  /** Hold duration in ms. @default 1400 */
  holdMs?: number;
}

export type RiggingField =
  | RiggingTextField
  | RiggingTextareaField
  | RiggingAvatarField
  | RiggingSwitchField
  | RiggingRadioCardsField
  | RiggingSelectField
  | RiggingSegmentedField
  | RiggingActionField;

/** A group of fields; one nav entry. */
export interface RiggingSection {
  /** Unique id (also used for the DOM anchor). */
  id: string;
  /** Nav label and section heading. */
  title: string;
  /** Copy under the section heading. */
  description?: string;
  /** `danger` tints the nav item and frames the fields in red. @default "default" */
  tone?: "default" | "danger";
  /** Small glyph in the nav (16px, `currentColor`). */
  icon?: React.ReactNode;
  fields: RiggingField[];
}

/** Imperative verbs exposed through the `ref` prop. */
export interface RiggingHandle {
  /** Spring every field back to the last saved values and hide the save bar. */
  reset: () => void;
  /** Replay the intro cascade. */
  replay: () => void;
  /** Run the save flow (validation → `onSave`) as if Save was pressed. */
  save: () => Promise<void>;
  /** Current values snapshot. */
  getValues: () => RiggingValues;
}

export interface RiggingProps
  extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title" | "onChange" | "defaultValue"> {
  /**
   * The settings schema. Each section becomes a nav entry.
   * @default Profile, Account, Notifications, Appearance and Danger zone sample sections
   */
  sections?: RiggingSection[];
  /**
   * Initial (and "last saved") values. Missing keys fall back per field kind
   * (empty string, `false`, first option, `null`).
   * @default seeded sample values when `sections` is omitted
   */
  defaultValues?: RiggingValues;
  /** Controlled values. Omit for uncontrolled use. */
  values?: RiggingValues;
  /** Fires on every edit with the full next values and the field that changed. */
  onChange?: (values: RiggingValues, name: string) => void;
  /**
   * Called with all values when Save is pressed (or ⌘/Ctrl+S) and validation
   * passes. Return a Promise to show the pending state; resolve shows the
   * "Saved" chip and makes these the new baseline, reject shows its message
   * in the bar. Note: navigating away with unsaved changes is NOT blocked —
   * wire `beforeunload` / your router guard yourself if you need that.
   */
  onSave?: (values: RiggingValues) => void | Promise<unknown>;
  /** Fires when a danger-zone (`action`) field's hold completes. */
  onAction?: (name: string) => void;
  /**
   * `"tabs"` swaps one section at a time; `"stacked"` shows every section in
   * one scroll column with scroll-spy nav (give the block a bounded height,
   * e.g. `h-[640px]`, so the column scrolls inside it).
   * @default "tabs"
   */
  layout?: "tabs" | "stacked";
  /** Page heading. @default "Settings" */
  title?: React.ReactNode;
  /** Copy under the heading. */
  description?: React.ReactNode;
  /** Accent hex for the nav indicator, focus rings, switches and Save. @default "#93c5fd" */
  accentColor?: string;
  /** Imperative handle (`reset()`, `replay()`, `save()`, `getValues()`). React 19 ref-as-prop. */
  ref?: React.Ref<RiggingHandle>;
  /** Extra classes for the root. Set a height to make the content column scroll internally. */
  className?: string;
}

/* ---------------------------------------------------------------- constants */

const DEFAULT_ACCENT = "#93c5fd";
const EASE: [number, number, number, number] = [0.22, 1, 0.36, 1];
const SPRING: Transition = { type: "spring", stiffness: 420, damping: 36, mass: 0.8 };
const INSTANT: Transition = { duration: 0 };
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const SAVED_DWELL = 1900;

