/* ---------------------------------------------------------------- helpers */

/** Event-time clock (only called from handlers/effects). */
const nowMs = () => performance.now();

/** Black or white text, whichever reads against the accent fill. */
function readableOn(hex: string): string {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return "#0a0a0a";
  let s = m[1];
  if (s.length === 3) s = s.replace(/./g, (c) => c + c);
  const n = parseInt(s, 16);
  const lum = 0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255);
  return lum > 140 ? "#0a0a0a" : "#ffffff";
}

function fallbackValue(field: RiggingField): RiggingValue {
  switch (field.kind) {
    case "switch":
      return false;
    case "avatar":
      return null;
    case "select":
    case "segmented":
    case "radio-cards":
      return field.options[0]?.value ?? "";
    default:
      return "";
  }
}

function buildValues(sections: RiggingSection[], defaults: RiggingValues | undefined): RiggingValues {
  const out: RiggingValues = {};
  for (const section of sections) {
    for (const field of section.fields) {
      if (field.kind === "action") continue;
      out[field.name] = defaults && field.name in defaults ? defaults[field.name] : fallbackValue(field);
    }
  }
  return out;
}

function validateField(field: RiggingField, value: RiggingValue, values: RiggingValues): string | null {
  if (field.kind === "text" || field.kind === "email" || field.kind === "textarea") {
    const v = typeof value === "string" ? value : "";
    if (field.required && !v.trim()) return `${field.label} is required.`;
    if (field.kind === "email" && v.trim() && !EMAIL_RE.test(v.trim())) return "Enter a valid email address.";
    if (field.kind === "textarea" && v.length > (field.maxLength ?? 200)) return "Too long.";
    if (field.validate && v.trim()) return field.validate(v, values) ?? null;
  }
  return null;
}

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return ((parts[0][0] ?? "") + (parts.length > 1 ? (parts[parts.length - 1][0] ?? "") : "")).toUpperCase();
}

