/* ---------------------------------------------------------------- field controls */

interface ControlCtx {
  id: string;
  labelId: string;
  descId?: string;
  errId: string;
  error: string | null;
  showError: boolean;
  reduced: boolean;
  accent: string;
  ink: string;
  values: RiggingValues;
  setValue: (name: string, value: RiggingValue) => void;
  touch: (name: string) => void;
  onAction?: (name: string) => void;
  /** Report a non-value error (avatar file too large). */
  setLocalError: (name: string, msg: string | null) => void;
}

const inputBase = cn(
  "w-full rounded-lg border bg-white/[0.03] px-3 text-sm text-white placeholder:text-white/30",
  "transition-[border-color,box-shadow,background-color] duration-150 outline-none",
  "hover:bg-white/[0.045] focus:bg-white/[0.04]",
  "focus:border-[var(--rg-accent)] focus:shadow-[0_0_0_3px_color-mix(in_oklab,var(--rg-accent)_22%,transparent)]"
);

function TextControl({ field, ctx }: { field: RiggingTextField; ctx: ControlCtx }) {
  const value = String(ctx.values[field.name] ?? "");
  const invalid = ctx.showError && !!ctx.error;
  return (
    <div
      className={cn(
        inputBase,
        "flex h-9 items-center gap-0 px-0 focus-within:border-[var(--rg-accent)] focus-within:bg-white/[0.04]",
        "focus-within:shadow-[0_0_0_3px_color-mix(in_oklab,var(--rg-accent)_22%,transparent)]",
        invalid ? "border-red-400/60" : "border-white/10"
      )}
    >
      {field.prefix && (
        <span aria-hidden className="flex h-full items-center border-r border-white/[0.08] pl-3 pr-2.5 text-sm text-white/35">
          {field.prefix}
        </span>
      )}
      <input
        id={ctx.id}
        type={field.kind === "email" ? "email" : "text"}
        value={value}
        placeholder={field.placeholder}
        autoComplete={field.autoComplete}
        spellCheck={field.kind === "email" ? false : undefined}
        aria-required={field.required || undefined}
        aria-invalid={invalid || undefined}
        aria-describedby={cn(ctx.descId, invalid && ctx.errId) || undefined}
        onChange={(e) => ctx.setValue(field.name, e.target.value)}
        onBlur={() => ctx.touch(field.name)}
        className="h-full min-w-0 flex-1 bg-transparent px-3 text-sm text-white outline-none placeholder:text-white/30"
      />
    </div>
  );
}

function TextareaControl({ field, ctx }: { field: RiggingTextareaField; ctx: ControlCtx }) {
  const value = String(ctx.values[field.name] ?? "");
  const max = field.maxLength ?? 200;
  const ratio = value.length / max;
  const invalid = ctx.showError && !!ctx.error;
  const counterId = `${ctx.id}-count`;
  return (
    <div className="relative">
      <textarea
        id={ctx.id}
        value={value}
        rows={field.rows ?? 3}
        maxLength={max}
        placeholder={field.placeholder}
        aria-required={field.required || undefined}
        aria-invalid={invalid || undefined}
        aria-describedby={cn(ctx.descId, counterId, invalid && ctx.errId) || undefined}
        onChange={(e) => ctx.setValue(field.name, e.target.value)}
        onBlur={() => ctx.touch(field.name)}
        className={cn(inputBase, "block resize-none py-2 pb-6 leading-relaxed", invalid ? "border-red-400/60" : "border-white/10")}
      />
      <span
        id={counterId}
        aria-label={`${value.length} of ${max} characters`}
        className={cn(
          "pointer-events-none absolute bottom-1.5 right-2.5 text-[11px] tabular-nums transition-colors duration-200",
          ratio >= 1 ? "text-red-300" : ratio >= 0.85 ? "text-amber-200/90" : "text-white/30"
        )}
      >
        {value.length}
        <span className="text-white/20"> / {max}</span>
      </span>
    </div>
  );
}

function AvatarControl({ field, ctx }: { field: RiggingAvatarField; ctx: ControlCtx }) {
  const src = (ctx.values[field.name] as string | null) ?? null;
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = React.useState(false);
  const initials = initialsOf(String((field.initialsFrom && ctx.values[field.initialsFrom]) || ""));
  const maxMb = field.maxSizeMb ?? 2;

  const accept = (file: File | undefined) => {
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      ctx.setLocalError(field.name, "That file isn't an image.");
      return;
    }
    if (file.size > maxMb * 1024 * 1024) {
      ctx.setLocalError(field.name, `Images must be under ${maxMb} MB.`);
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      ctx.setLocalError(field.name, null);
      ctx.setValue(field.name, typeof reader.result === "string" ? reader.result : null);
    };
    reader.readAsDataURL(file);
  };

  const fade: Transition = ctx.reduced ? { duration: 0.15 } : { duration: 0.35, ease: EASE };

  return (
    <div className="flex items-center gap-4">
      <button
        type="button"
        id={ctx.id}
        aria-label={src ? "Change photo" : "Upload photo"}
        aria-describedby={cn(ctx.descId, ctx.error && ctx.errId) || undefined}
        onClick={() => inputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => {
          e.preventDefault();
          setDragging(false);
          accept(e.dataTransfer.files?.[0]);
        }}
        className={cn(
          "group/av relative size-16 shrink-0 overflow-hidden rounded-full border bg-neutral-900 outline-none",
          "focus-visible:ring-2 focus-visible:ring-[var(--rg-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
          dragging ? "border-[var(--rg-accent)]" : "border-white/10"
        )}
      >
        <AnimatePresence initial={false}>
          {src ? (
            <motion.img
              key={src.slice(-48)}
              src={src}
              alt=""
              initial={{ opacity: 0, scale: ctx.reduced ? 1 : 1.08 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0 }}
              transition={fade}
              className="absolute inset-0 size-full object-cover"
            />
          ) : (
            <motion.span
              key="initials"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={fade}
              className="absolute inset-0 flex items-center justify-center text-lg font-semibold tracking-wide"
              style={{
                color: "var(--rg-accent)",
                background:
                  "radial-gradient(120% 120% at 30% 20%, color-mix(in oklab, var(--rg-accent) 26%, #18181b), #121214 70%)",
              }}
            >
              {initials}
            </motion.span>
          )}
        </AnimatePresence>
        <span
          aria-hidden
          className="absolute inset-0 flex items-center justify-center bg-black/55 text-[11px] font-medium text-white opacity-0 transition-opacity duration-150 group-hover/av:opacity-100 group-focus-visible/av:opacity-100"
        >
          {src ? "Change" : "Upload"}
        </span>
      </button>
      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          className="h-8 rounded-lg border border-white/10 bg-white/[0.04] px-3 text-[13px] font-medium text-white/85 transition-colors hover:bg-white/[0.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--rg-accent)]"
        >
          {src ? "Replace" : "Upload"}
        </button>
        {src && (
          <button
            type="button"
            onClick={() => {
              ctx.setLocalError(field.name, null);
              ctx.setValue(field.name, null);
            }}
            className="h-8 rounded-lg px-3 text-[13px] font-medium text-white/50 transition-colors hover:text-white/85 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--rg-accent)]"
          >
            Remove
          </button>
        )}
      </div>
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        tabIndex={-1}
        aria-hidden
        className="sr-only"
        onChange={(e) => {
          accept(e.target.files?.[0]);
          e.target.value = "";
        }}
      />
    </div>
  );
}

