/* ================================================================ date helpers */

const pad = (n: number) => String(n).padStart(2, "0");
function dkey(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}
function fromKey(k: string): Date {
  const [y, m, d] = k.split("-").map(Number);
  return new Date(y, (m ?? 1) - 1, d ?? 1);
}
function addDays(k: string, n: number): string {
  const d = fromKey(k);
  d.setDate(d.getDate() + n);
  return dkey(d);
}
function addMonths(month: string, n: number): string {
  const [y, m] = month.split("-").map(Number);
  const d = new Date(y, m - 1 + n, 1);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}`;
}
/** Coerces a row value (Date, epoch ms, ISO string) to a local `YYYY-MM-DD` key. */
function toKey(v: unknown): string | null {
  if (v instanceof Date) return Number.isNaN(v.getTime()) ? null : dkey(v);
  if (typeof v === "number") return Number.isFinite(v) ? dkey(new Date(v)) : null;
  if (typeof v === "string") {
    if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
    const d = new Date(v);
    return Number.isNaN(d.getTime()) ? null : dkey(d);
  }
  return null;
}
function presetRange(p: SiftDatePreset, today: string): [string, string] {
  if (p === "today") return [today, today];
  if (p === "last-7") return [addDays(today, -6), today];
  if (p === "last-30") return [addDays(today, -29), today];
  const first = `${today.slice(0, 7)}-01`;
  return [first, addDays(`${addMonths(today.slice(0, 7), 1)}-01`, -1)];
}
function fmtDay(k: string): string {
  const d = fromKey(k);
  return `${MONTHS[d.getMonth()]} ${d.getDate()}`;
}

const subscribeNoop = () => () => {};
/** Local today as `YYYY-MM-DD`; null on the server / during hydration. */
function useTodayKey(override?: string | Date): string | null {
  const live = React.useSyncExternalStore(
    subscribeNoop,
    () => dkey(new Date()),
    () => null
  );
  if (override) return toKey(override);
  return live;
}

/* ================================================================ pure filtering */

function optionsOf(field: SiftField | undefined): Required<SiftOption>[] {
  return (field?.options ?? []).map((o) =>
    typeof o === "string"
      ? { value: o, label: o, color: "" }
      : { value: o.value, label: o.label ?? o.value, color: o.color ?? "" }
  );
}

function matches(row: Record<string, unknown>, f: SiftFilter, field: SiftField, today: string): boolean {
  const raw = row[field.key];
  switch (field.type) {
    case "text": {
      const hay = String(raw ?? "").toLowerCase();
      const needle = String(f.value ?? "").toLowerCase();
      if (!needle) return true;
      if (f.operator === "is") return hay === needle;
      if (f.operator === "is-not") return hay !== needle;
      if (f.operator === "starts-with") return hay.startsWith(needle);
      return hay.includes(needle);
    }
    case "select": {
      const sel = Array.isArray(f.value) ? f.value.map(String) : f.value == null ? [] : [String(f.value)];
      if (!sel.length) return true;
      const vals = Array.isArray(raw) ? raw.map(String) : raw == null ? [] : [String(raw)];
      const hit = vals.some((v) => sel.includes(v));
      return f.operator === "none-of" ? !hit : hit;
    }
    case "number": {
      const n = typeof raw === "number" ? raw : Number(raw);
      if (raw == null || Number.isNaN(n)) return false;
      if (f.operator === "between" && Array.isArray(f.value)) {
        const [a, b] = (f.value as number[]).map(Number);
        return n >= Math.min(a, b) && n <= Math.max(a, b);
      }
      const v = Number(f.value);
      if (f.operator === "neq") return n !== v;
      if (f.operator === "gt") return n > v;
      if (f.operator === "lt") return n < v;
      return n === v;
    }
    case "date": {
      const k = toKey(raw);
      if (!k) return false;
      if (f.preset) {
        const [a, b] = presetRange(f.preset, today);
        return k >= a && k <= b;
      }
      if (f.operator === "between" && Array.isArray(f.value)) {
        const [a, b] = (f.value as string[]).map(String).sort();
        return k >= a && k <= b;
      }
      const v = String(f.value ?? "");
      if (!v) return true;
      if (f.operator === "before") return k < v;
      if (f.operator === "after") return k > v;
      return k === v;
    }
    case "boolean":
      return Boolean(raw) === (f.operator === "is-true");
  }
}

/**
 * Pure helper: returns the rows that satisfy `filters` (AND by default, or OR),
 * reading `row[field.key]`. Filters for unknown fields are ignored. Date
 * values may be `Date`s, epoch ms or ISO strings; presets resolve against
 * `options.now` (default: the current date).
 */
export function applyFilters<T extends object>(
  rows: readonly T[],
  filters: readonly SiftFilter[],
  fields: readonly SiftField[] = defaultSiftFields,
  options: { conjunction?: SiftConjunction; now?: Date | string } = {}
): T[] {
  const active = filters
    .map((f) => ({ f, field: fields.find((x) => x.key === f.field) }))
    .filter((x): x is { f: SiftFilter; field: SiftField } => !!x.field);
  if (!active.length) return rows.slice();
  const today = toKey(options.now ?? new Date()) ?? dkey(new Date());
  const any = options.conjunction === "or";
  return rows.filter((row) => {
    const r = row as Record<string, unknown>;
    return any ? active.some((x) => matches(r, x.f, x.field, today)) : active.every((x) => matches(r, x.f, x.field, today));
  });
}

/* ================================================================ misc helpers */

function inkFor(hex: string): string {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return "#0a0a0a";
  const h = m[1].length === 3 ? [...m[1]].map((c) => c + c).join("") : m[1];
  const [r, g, b] = [0, 2, 4].map((i) => {
    const c = parseInt(h.slice(i, i + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  const L = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return L > 0.36 ? "#0a0a0a" : "#ffffff";
}

function sig(filters: readonly SiftFilter[], conj: SiftConjunction): string {
  return JSON.stringify([conj, filters.map((f) => [f.field, f.operator, f.value, f.preset ?? null])]);
}

function summarize(field: SiftField, f: SiftFilter): string {
  switch (field.type) {
    case "text":
      return `“${String(f.value ?? "")}”`;
    case "select": {
      const opts = optionsOf(field);
      const labels = (Array.isArray(f.value) ? f.value : []).map(
        (v) => opts.find((o) => o.value === v)?.label ?? String(v)
      );
      return labels.length > 2 ? `${labels.slice(0, 2).join(", ")} +${labels.length - 2}` : labels.join(", ");
    }
    case "number":
      return Array.isArray(f.value) ? `${f.value[0]} – ${f.value[1]}` : String(f.value ?? "");
    case "date":
      if (f.preset) return PRESET_LABEL[f.preset];
      if (Array.isArray(f.value)) {
        const [a, b] = (f.value as string[]).map(String).sort();
        return a === b ? fmtDay(a) : `${fmtDay(a)} – ${fmtDay(b)}`;
      }
      return f.value ? fmtDay(String(f.value)) : "";
    case "boolean":
      return "";
  }
}

function describe(field: SiftField, f: SiftFilter): string {
  const v = summarize(field, f);
  return `${field.label} ${opLabel(field.type, f.operator)}${v ? ` ${v}` : ""}`;
}

/* ================================================================ draft */

interface Draft {
  editingId: string | null;
  field: string | null;
  operator: SiftOperator | null;
  text: string;
  sel: string[];
  numA: string;
  numB: string;
  dateA: string | null;
  dateB: string | null;
  preset: SiftDatePreset | null;
}

const EMPTY_DRAFT: Draft = {
  editingId: null,
  field: null,
  operator: null,
  text: "",
  sel: [],
  numA: "",
  numB: "",
  dateA: null,
  dateB: null,
  preset: null,
};

function draftFrom(f: SiftFilter): Draft {
  const d: Draft = { ...EMPTY_DRAFT, editingId: f.id, field: f.field, operator: f.operator };
  const v = f.value;
  if (typeof v === "string") {
    d.text = v;
    d.dateA = /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null;
  }
  if (Array.isArray(v)) {
    if (typeof v[0] === "number") {
      d.numA = String(v[0]);
      d.numB = String(v[1] ?? "");
    } else if (f.operator === "between" && v.length === 2 && /^\d{4}-/.test(String(v[0]))) {
      d.dateA = String(v[0]);
      d.dateB = String(v[1]);
    } else d.sel = v.map(String);
  }
  if (typeof v === "number") d.numA = String(v);
  d.preset = f.preset ?? null;
  return d;
}

const isNum = (s: string) => s.trim() !== "" && Number.isFinite(Number(s));

function buildFilter(d: Draft, field: SiftField, id: string): SiftFilter | null {
  const op = d.operator;
  if (!op) return null;
  const base = { id, field: field.key, operator: op };
  switch (field.type) {
    case "text":
      return d.text.trim() ? { ...base, value: d.text.trim() } : null;
    case "select":
      return d.sel.length ? { ...base, value: d.sel } : null;
    case "number":
      if (op === "between")
        return isNum(d.numA) && isNum(d.numB)
          ? { ...base, value: [Number(d.numA), Number(d.numB)].sort((a, b) => a - b) as [number, number] }
          : null;
      return isNum(d.numA) ? { ...base, value: Number(d.numA) } : null;
    case "date":
      if (d.preset) return { ...base, operator: "is", value: null, preset: d.preset };
      if (!d.dateA) return null;
      if (op === "between") {
        const pair = [d.dateA, d.dateB ?? d.dateA].sort() as [string, string];
        return { ...base, value: pair };
      }
      return { ...base, value: d.dateA };
    case "boolean":
      return op === "is-true" || op === "is-false" ? { ...base, value: null } : null;
  }
}

/* ================================================================ small pieces */

type Step = "field" | "operator" | "value";
const STEP_INDEX: Record<Step, number> = { field: 0, operator: 1, value: 2 };

function Dot({ color }: { color: string }) {
  if (!color) return null;
  return <span aria-hidden className="size-2 shrink-0 rounded-full" style={{ background: color }} />;
}

const FOCUS =
  "outline-none focus-visible:ring-2 focus-visible:ring-[var(--sift-accent)] focus-visible:ring-offset-1 focus-visible:ring-offset-neutral-900";

/** Keyboard model shared by the listboxes: Up/Down/Home/End move, Enter picks. */
function listKeys(
  e: React.KeyboardEvent,
  count: number,
  active: number,
  setActive: (n: number) => void,
  pick: (n: number) => void
) {
  if (!count) return;
  if (e.key === "ArrowDown") {
    e.preventDefault();
    setActive((active + 1) % count);
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    setActive((active - 1 + count) % count);
  } else if (e.key === "Home") {
    e.preventDefault();
    setActive(0);
  } else if (e.key === "End") {
    e.preventDefault();
    setActive(count - 1);
  } else if (e.key === "Enter") {
    e.preventDefault();
    pick(active);
  }
}

function useFocusOnMount<T extends HTMLElement>() {
  const ref = React.useRef<T>(null);
  React.useEffect(() => {
    ref.current?.focus({ preventScroll: true });
  }, []);
  return ref;
}

/* ---------------------------------------------------------------- field step */

function FieldStep({
  uid,
  fields,
  selected,
  onPick,
}: {
  uid: string;
  fields: SiftField[];
  selected: string | null;
  onPick: (key: string) => void;
}) {
  const [q, setQ] = React.useState("");
  const [active, setActive] = React.useState(() => Math.max(0, fields.findIndex((f) => f.key === selected)));
  const input = useFocusOnMount<HTMLInputElement>();
  const shown = React.useMemo(() => {
    const s = q.trim().toLowerCase();
    return s ? fields.filter((f) => f.label.toLowerCase().includes(s)) : fields;
  }, [fields, q]);
  const act = Math.min(active, shown.length - 1);
  const listId = `${uid}-fields`;

  return (
    <div className="p-1.5">
      <label className="relative flex items-center">
        <span className="pointer-events-none absolute left-2.5 text-white/35">{Icon.search}</span>
        <input
          ref={input}
          value={q}
          onChange={(e) => {
            setQ(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => listKeys(e, shown.length, act, setActive, (i) => shown[i] && onPick(shown[i].key))}
          role="combobox"
          aria-expanded
          aria-controls={listId}
          aria-activedescendant={shown[act] ? `${listId}-${shown[act].key}` : undefined}
          aria-label="Filter by property"
          placeholder="Filter by…"
          className="h-9 w-full rounded-lg border border-white/[0.08] bg-white/[0.03] pl-8 pr-2.5 text-[13px] text-white placeholder:text-white/35 outline-none transition-colors focus:border-[color-mix(in_srgb,var(--sift-accent)_45%,transparent)]"
        />
      </label>
      <ul id={listId} role="listbox" aria-label="Properties" className="mt-1.5 max-h-64 overflow-y-auto">
        {shown.map((f, i) => (
          <li
            key={f.key}
            id={`${listId}-${f.key}`}
            role="option"
            aria-selected={i === act}
            onPointerMove={() => setActive(i)}
            onClick={() => onPick(f.key)}
            className={cn(
              "flex h-8 cursor-pointer items-center gap-2.5 rounded-md px-2.5 text-[13px] text-white/75",
              i === act && "bg-white/[0.06] text-white"
            )}
          >
            <span className="text-white/45">{f.icon ?? TYPE_ICON[f.type]}</span>
            <span className="flex-1 truncate">{f.label}</span>
            {f.key === selected && <span className="text-[var(--sift-accent)]">{Icon.check}</span>}
          </li>
        ))}
        {!shown.length && <li className="px-2.5 py-3 text-[12.5px] text-white/40">No matching properties</li>}
      </ul>
    </div>
  );
}

/* ---------------------------------------------------------------- operator step */

function OperatorStep({
  uid,
  type,
  selected,
  onPick,
}: {
  uid: string;
  type: SiftFieldType;
  selected: SiftOperator | null;
  onPick: (op: SiftOperator) => void;
}) {
  const ops = OPS[type];
  const [active, setActive] = React.useState(() => Math.max(0, ops.findIndex((o) => o.id === selected)));
  const list = useFocusOnMount<HTMLUListElement>();
  const listId = `${uid}-ops`;
  return (
    <div className="p-1.5">
      <ul
        ref={list}
        id={listId}
        role="listbox"
        tabIndex={0}
        aria-label="Operator"
        aria-activedescendant={`${listId}-${ops[active]?.id}`}
        onKeyDown={(e) => listKeys(e, ops.length, active, setActive, (i) => onPick(ops[i].id))}
        className="rounded-lg outline-none focus-visible:ring-1 focus-visible:ring-white/10"
      >
        {ops.map((o, i) => (
          <li
            key={o.id}
            id={`${listId}-${o.id}`}
            role="option"
            aria-selected={i === active}
            onPointerMove={() => setActive(i)}
            onClick={() => onPick(o.id)}
            className={cn(
              "flex h-8 cursor-pointer items-center gap-2.5 rounded-md px-2.5 text-[13px] text-white/75",
              i === active && "bg-white/[0.06] text-white"
            )}
          >
            <span className={cn("min-w-0 flex-1 truncate", o.label.length === 1 && "font-mono text-[13px]")}>
              {o.label}
              {o.hint && <span className="ml-2 font-sans text-[12px] text-white/35">{o.hint}</span>}
            </span>
            {o.id === selected && <span className="text-[var(--sift-accent)]">{Icon.check}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ---------------------------------------------------------------- value editors */

const INPUT =
  "h-9 w-full min-w-0 rounded-lg border border-white/[0.08] bg-white/[0.03] px-2.5 text-[13px] text-white tabular-nums placeholder:text-white/30 outline-none transition-colors focus:border-[color-mix(in_srgb,var(--sift-accent)_45%,transparent)]";

function TextEditor({ draft, set, submit }: { draft: Draft; set: (p: Partial<Draft>) => void; submit: () => void }) {
  const ref = useFocusOnMount<HTMLInputElement>();
  return (
    <div className="p-1.5">
      <input
        ref={ref}
        value={draft.text}
        onChange={(e) => set({ text: e.target.value })}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            submit();
          }
        }}
        aria-label="Value"
        placeholder="Type a value…"
        className={INPUT}
      />
    </div>
  );
}

function SelectEditor({
  uid,
  field,
  draft,
  set,
  submit,
}: {
  uid: string;
  field: SiftField;
  draft: Draft;
  set: (p: Partial<Draft>) => void;
  submit: () => void;
}) {
  const opts = React.useMemo(() => optionsOf(field), [field]);
  const [q, setQ] = React.useState("");
  const [active, setActive] = React.useState(0);
  const input = useFocusOnMount<HTMLInputElement>();
  const shown = React.useMemo(() => {
    const s = q.trim().toLowerCase();
    return s ? opts.filter((o) => o.label.toLowerCase().includes(s)) : opts;
  }, [opts, q]);
  const act = Math.min(active, shown.length - 1);
  const toggle = (v: string) =>
    set({ sel: draft.sel.includes(v) ? draft.sel.filter((x) => x !== v) : [...draft.sel, v] });
  const listId = `${uid}-opts`;
  return (
    <div className="p-1.5">
      <label className="relative flex items-center">
        <span className="pointer-events-none absolute left-2.5 text-white/35">{Icon.search}</span>
        <input
          ref={input}
          value={q}
          onChange={(e) => {
            setQ(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => {
            if (e.key === " " && !q) {
              e.preventDefault();
              if (shown[act]) toggle(shown[act].value);
              return;
            }
            if (e.key === "Enter") {
              e.preventDefault();
              // Enter toggles while searching an unselected option; otherwise applies.
              if (q && shown[act] && !draft.sel.includes(shown[act].value)) {
                toggle(shown[act].value);
                setQ("");
              } else submit();
              return;
            }
            listKeys(e, shown.length, act, setActive, () => {});
          }}
          role="combobox"
          aria-expanded
          aria-controls={listId}
          aria-activedescendant={shown[act] ? `${listId}-${act}` : undefined}
          aria-label={`Search ${field.label.toLowerCase()} (Space toggles, Enter applies)`}
          placeholder={`Search ${field.label.toLowerCase()}…`}
          className={cn(INPUT, "pl-8")}
        />
      </label>
      <ul
        id={listId}
        role="listbox"
        aria-multiselectable
        aria-label={field.label}
        className="mt-1.5 max-h-56 overflow-y-auto"
      >
        {shown.map((o, i) => {
          const on = draft.sel.includes(o.value);
          return (
            <li
              key={o.value}
              id={`${listId}-${i}`}
              role="option"
              aria-selected={on}
              onPointerMove={() => setActive(i)}
              onClick={() => toggle(o.value)}
              className={cn(
                "flex h-8 cursor-pointer items-center gap-2.5 rounded-md px-2.5 text-[13px] text-white/75",
                i === act && "bg-white/[0.06] text-white"
              )}
            >
              <span
                aria-hidden
                className={cn(
                  "grid size-4 shrink-0 place-items-center rounded-[5px] border transition-colors duration-150",
                  on ? "border-transparent" : "border-white/20 bg-white/[0.02]"
                )}
                style={on ? { background: "var(--sift-accent)", color: "var(--sift-ink)" } : undefined}
              >
                {on && (
                  <svg viewBox="0 0 16 16" className="size-3" fill="none" stroke="currentColor" strokeWidth="2.25" aria-hidden>
                    <path d="m3.5 8.5 3 3 6-7" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                )}
              </span>
              <Dot color={o.color} />
              <span className="flex-1 truncate">{o.label}</span>
            </li>
          );
        })}
        {!shown.length && <li className="px-2.5 py-3 text-[12.5px] text-white/40">No matches</li>}
      </ul>
    </div>
  );
}

function NumberEditor({ draft, set, submit }: { draft: Draft; set: (p: Partial<Draft>) => void; submit: () => void }) {
  const ref = useFocusOnMount<HTMLInputElement>();
  const between = draft.operator === "between";
  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      submit();
    }
  };
  const bad = (s: string) => s.trim() !== "" && !isNum(s);
  return (
    <div className="flex items-center gap-2 p-1.5">
      <input
        ref={ref}
        inputMode="decimal"
        value={draft.numA}
        onChange={(e) => set({ numA: e.target.value })}
        onKeyDown={onKey}
        aria-label={between ? "Minimum" : "Value"}
        aria-invalid={bad(draft.numA) || undefined}
        placeholder={between ? "Min" : "0"}
        className={cn(INPUT, bad(draft.numA) && "border-red-400/50")}
      />
      {between && (
        <>
          <span className="shrink-0 text-[12px] text-white/40">and</span>
          <input
            inputMode="decimal"
            value={draft.numB}
            onChange={(e) => set({ numB: e.target.value })}
            onKeyDown={onKey}
            aria-label="Maximum"
            aria-invalid={bad(draft.numB) || undefined}
            placeholder="Max"
            className={cn(INPUT, bad(draft.numB) && "border-red-400/50")}
          />
        </>
      )}
    </div>
  );
}

function monthGrid(month: string): string[] {
  const first = fromKey(`${month}-01`);
  const offset = (first.getDay() + 6) % 7;
  const start = addDays(`${month}-01`, -offset);
  return Array.from({ length: 42 }, (_, i) => addDays(start, i));
}

function Calendar({
  range,
  a,
  b,
  today,
  onSelect,
  submit,
}: {
  range: boolean;
  a: string | null;
  b: string | null;
  today: string;
  onSelect: (a: string, b: string | null) => void;
  submit: () => void;
}) {
  const init = a ?? today;
  const [month, setMonth] = React.useState(init.slice(0, 7));
  const [focusKey, setFocusKey] = React.useState(init);
  const [hover, setHover] = React.useState<string | null>(null);
  const [kbd, setKbd] = React.useState(0);
  const grid = React.useRef<HTMLDivElement>(null);
  const days = React.useMemo(() => monthGrid(month), [month]);
  const [y, m] = month.split("-").map(Number);

  React.useEffect(() => {
    if (!kbd) return;
    grid.current?.querySelector<HTMLButtonElement>(`[data-day="${focusKey}"]`)?.focus({ preventScroll: true });
  }, [kbd, focusKey]);

  const lo = a && range ? [a, b ?? hover ?? a].sort()[0] : a;
  const hi = a && range ? [a, b ?? hover ?? a].sort()[1] : a;

  const pick = (k: string) => {
    if (!range) return onSelect(k, null);
    if (!a || b) return onSelect(k, null);
    return onSelect(k < a ? k : a, k < a ? a : k);
  };

  const move = (n: number) => {
    const next = addDays(focusKey, n);
    setFocusKey(next);
    if (next.slice(0, 7) !== month) setMonth(next.slice(0, 7));
    setKbd((x) => x + 1);
  };

  return (
    <div className="px-2 pb-1 pt-0.5">
      <div className="flex items-center justify-between px-0.5 pb-1">
        <span className="text-[12.5px] font-medium text-white/85" aria-live="polite">
          {MONTHS_LONG[m - 1]} {y}
        </span>
        <div className="flex gap-0.5">
          {[
            { d: -1, icon: Icon.chevL, label: "Previous month" },
            { d: 1, icon: Icon.chevR, label: "Next month" },
          ].map((x) => (
            <button
              key={x.d}
              type="button"
              aria-label={x.label}
              onClick={() => {
                const nm = addMonths(month, x.d);
                setMonth(nm);
                setFocusKey(`${nm}-01`);
              }}
              className={cn("grid size-7 place-items-center rounded-md text-white/50 hover:bg-white/[0.06] hover:text-white", FOCUS)}
            >
              {x.icon}
            </button>
          ))}
        </div>
      </div>
      <div
        ref={grid}
        role="grid"
        aria-label={`${MONTHS_LONG[m - 1]} ${y}${range ? ", pick a start and end date" : ""}`}
        onPointerLeave={() => setHover(null)}
        onKeyDown={(e) => {
          const map: Record<string, number> = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 };
          if (map[e.key] !== undefined) {
            e.preventDefault();
            move(map[e.key]);
          } else if (e.key === "PageUp" || e.key === "PageDown") {
            e.preventDefault();
            move(e.key === "PageUp" ? -28 : 28);
          } else if (e.key === "Enter" && a && (!range || b) && focusKey === (range ? b : a)) {
            e.preventDefault();
            submit();
          }
        }}
      >
        <div role="row" className="grid grid-cols-7">
          {WEEKDAYS.map((w) => (
            <span key={w} role="columnheader" className="grid h-7 place-items-center text-[11px] text-white/35">
              {w}
            </span>
          ))}
        </div>
        {[0, 1, 2, 3, 4, 5].map((r) => (
          <div role="row" key={r} className="grid grid-cols-7">
            {days.slice(r * 7, r * 7 + 7).map((k) => {
              const out = k.slice(0, 7) !== month;
              const isEnd = k === lo || k === hi;
              const inside = !!lo && !!hi && k > lo && k < hi;
              const d = fromKey(k);
              return (
                <div role="gridcell" key={k} aria-selected={isEnd || inside} className="relative h-8 p-px">
                  {(inside || (isEnd && lo !== hi)) && (
                    <span
                      aria-hidden
                      className={cn(
                        "absolute inset-y-px bg-[color-mix(in_srgb,var(--sift-accent)_12%,transparent)]",
                        k === lo ? "left-1/2 right-0" : k === hi ? "left-0 right-1/2" : "inset-x-0"
                      )}
                    />
                  )}
                  <button
                    type="button"
                    data-day={k}
                    tabIndex={k === focusKey ? 0 : -1}
                    aria-label={`${MONTHS_LONG[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}${k === today ? " (today)" : ""}`}
                    onClick={() => {
                      setFocusKey(k);
                      pick(k);
                    }}
                    onPointerEnter={() => setHover(k)}
                    className={cn(
                      "relative grid h-full w-full place-items-center rounded-md text-[12.5px] tabular-nums transition-colors",
                      FOCUS,
                      out ? "text-white/25" : "text-white/75",
                      !isEnd && "hover:bg-white/[0.07] hover:text-white",
                      isEnd && "font-semibold"
                    )}
                    style={isEnd ? { background: "var(--sift-accent)", color: "var(--sift-ink)" } : undefined}
                  >
                    {d.getDate()}
                    {k === today && (
                      <span
                        aria-hidden
                        className="absolute bottom-1 left-1/2 size-[3px] -translate-x-1/2 rounded-full"
                        style={{ background: isEnd ? "var(--sift-ink)" : "var(--sift-accent)" }}
                      />
                    )}
                  </button>
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

function DateEditor({
  draft,
  set,
  today,
  submit,
}: {
  draft: Draft;
  set: (p: Partial<Draft>) => void;
  today: string;
  submit: () => void;
}) {
  const first = useFocusOnMount<HTMLDivElement>();
  return (
    <div>
      <div ref={first} tabIndex={-1} className="flex flex-wrap gap-1 px-2 pb-1.5 pt-1.5 outline-none" role="group" aria-label="Presets">
        {PRESETS.map((p) => {
          const on = draft.preset === p.id;
          return (
            <button
              key={p.id}
              type="button"
              aria-pressed={on}
              onClick={() => set({ preset: on ? null : p.id, dateA: null, dateB: null })}
              className={cn(
                "h-7 rounded-md border px-2 text-[12px] transition-colors",
                FOCUS,
                on
                  ? "border-[color-mix(in_srgb,var(--sift-accent)_45%,transparent)] bg-[color-mix(in_srgb,var(--sift-accent)_14%,transparent)] text-white"
                  : "border-white/[0.08] text-white/60 hover:border-white/15 hover:text-white"
              )}
            >
              {p.label}
            </button>
          );
        })}
      </div>
      <div className="mx-2 h-px bg-white/[0.06]" />
      <Calendar
        range={draft.operator === "between"}
        a={draft.preset ? null : draft.dateA}
        b={draft.preset ? null : draft.dateB}
        today={today}
        onSelect={(a, b) => set({ dateA: a, dateB: b, preset: null })}
        submit={submit}
      />
    </div>
  );
}

/* ================================================================ views menu */

function ViewsMenu({
  uid,
  views,
  activeId,
  edited,
  open,
  setOpen,
  onPick,
}: {
  uid: string;
  views: SiftView[];
  activeId: string | null;
  edited: boolean;
  open: boolean;
  setOpen: (o: boolean) => void;
  onPick: (v: SiftView) => void;
}) {
  const btn = React.useRef<HTMLButtonElement>(null);
  const menu = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const active = views.find((v) => v.id === activeId);
  const menuId = `${uid}-views`;

  React.useEffect(() => {
    if (!open) return;
    const idx = Math.max(0, views.findIndex((v) => v.id === activeId));
    const id = requestAnimationFrame(() =>
      menu.current?.querySelectorAll<HTMLElement>("[role=menuitemradio]")[idx]?.focus({ preventScroll: true })
    );
    const onDown = (e: PointerEvent) => {
      if (!menu.current?.contains(e.target as Node) && !btn.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => {
      cancelAnimationFrame(id);
      document.removeEventListener("pointerdown", onDown);
    };
  }, [open, views, activeId, setOpen]);

  const close = () => {
    setOpen(false);
    btn.current?.focus({ preventScroll: true });
  };

  return (
    <div className="relative min-w-0">
      <button
        ref={btn}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        onClick={() => setOpen(!open)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" && !open) {
            e.preventDefault();
            setOpen(true);
          }
        }}
        className={cn(
          "flex h-8 min-w-0 max-w-full items-center gap-2 rounded-lg px-2 text-[13px] font-medium text-white/90 transition-colors hover:bg-white/[0.05]",
          open && "bg-white/[0.05]",
          FOCUS
        )}
      >
        <span className="text-white/45">{Icon.views}</span>
        <span className="truncate">{active?.label ?? "Custom view"}</span>
        {edited && (
          <span className="shrink-0 rounded-[5px] border border-white/10 px-1 py-px text-[10.5px] font-normal leading-tight text-white/50">
            Edited
          </span>
        )}
        <span className={cn("text-white/40 transition-transform duration-200", open && "rotate-180")}>{Icon.chevron}</span>
      </button>
      <AnimatePresence>
        {open && (
          <motion.div
            ref={menu}
            id={menuId}
            role="menu"
            aria-label="Saved views"
            initial={reduced ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={reduced ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            transition={reduced ? FADE : { duration: 0.16, ease: EASE }}
            style={{ transformOrigin: "top left" }}
            onKeyDown={(e) => {
              const items = [...(menu.current?.querySelectorAll<HTMLElement>("[role=menuitemradio]") ?? [])];
              const i = items.indexOf(document.activeElement as HTMLElement);
              if (e.key === "ArrowDown" || e.key === "ArrowUp") {
                e.preventDefault();
                const n = (i + (e.key === "ArrowDown" ? 1 : -1) + items.length) % items.length;
                items[n]?.focus({ preventScroll: true });
              } else if (e.key === "Home" || e.key === "End") {
                e.preventDefault();
                items[e.key === "Home" ? 0 : items.length - 1]?.focus({ preventScroll: true });
              } else if (e.key === "Escape" || e.key === "Tab") {
                e.preventDefault();
                close();
              }
            }}
            className="absolute left-0 top-[calc(100%+6px)] z-40 w-60 max-w-[calc(100cqw-1rem)] rounded-xl border border-white/10 bg-[#141416] p-1 shadow-[0_24px_48px_-12px_rgba(0,0,0,0.75),0_0_0_1px_rgba(0,0,0,0.4)]"
          >
            <p className="px-2.5 pb-1 pt-1.5 text-[11px] font-medium uppercase tracking-[0.08em] text-white/35">Views</p>
            {views.map((v) => {
              const on = v.id === activeId;
              return (
                <div
                  key={v.id}
                  role="menuitemradio"
                  aria-checked={on}
                  tabIndex={-1}
                  onClick={() => {
                    onPick(v);
                    close();
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      onPick(v);
                      close();
                    }
                  }}
                  className="flex h-8 cursor-pointer items-center gap-2.5 rounded-md px-2.5 text-[13px] text-white/75 outline-none hover:bg-white/[0.06] hover:text-white focus-visible:bg-white/[0.06] focus-visible:text-white"
                >
                  <span className="grid w-3.5 place-items-center text-[var(--sift-accent)]">{on && Icon.check}</span>
                  <span className="flex-1 truncate">{v.label}</span>
                  <span className="text-[11.5px] tabular-nums text-white/30">{v.filters.length || "—"}</span>
                </div>
              );
            })}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ================================================================ main */

/**
 * Sift — a structured filter builder for any list or table. "+ Filter" opens
 * one popover that slides property → operator → value; applied filters become
 * editable chips joined by an and/or toggle; saved views swap chip sets with a
 * crossfade. Pair it with the exported `applyFilters(rows, filters, fields)`.
 */
export function Sift({
  fields: fieldsProp,
  value,
  defaultValue,
  onChange,
  conjunction: conjProp,
  defaultConjunction = "and",
  onConjunctionChange,
  views: viewsProp,
  defaultView,
  onViewChange,
  onSaveView,
  count,
  total,
  noun = { one: "result", other: "results" },
  today: todayProp,
  accentColor = DEFAULT_ACCENT,
  ref,
  className,
  style,
  onKeyDown,
  ...rest
}: SiftProps) {
  const reduced = useReducedMotion();
  const uid = React.useId().replace(/:/g, "");
  const sample = !fieldsProp;
  const fields = fieldsProp ?? defaultSiftFields;
  const baseViews = React.useMemo(() => viewsProp ?? (sample ? defaultSiftViews : []), [viewsProp, sample]);
  const initialViewId = defaultView ?? (sample && !viewsProp ? "active" : baseViews[0]?.id) ?? null;

  /* ----- state */
  const [innerFilters, setInnerFilters] = React.useState<SiftFilter[]>(
    () => defaultValue ?? (sample ? (baseViews.find((v) => v.id === initialViewId)?.filters ?? []) : [])
  );
  const filters = value ?? innerFilters;
  const [innerConj, setInnerConj] = React.useState<SiftConjunction>(defaultConjunction);
  const conj = conjProp ?? innerConj;
  const [saved, setSaved] = React.useState<SiftView[]>([]);
  const views = React.useMemo(() => [...baseViews, ...saved], [baseViews, saved]);
  const [activeViewId, setActiveViewId] = React.useState<string | null>(initialViewId);
  const activeView = views.find((v) => v.id === activeViewId);
  const edited = activeView
    ? sig(activeView.filters, activeView.conjunction ?? "and") !== sig(filters, conj)
    : filters.length > 0;
  const [epoch, setEpoch] = React.useState(0);
  const [announce, setAnnounce] = React.useState("");
  const idSeq = React.useRef(0);
  const freshId = (prefix: string, taken: string[]) => {
    let id = "";
    do id = `${prefix}-${uid}-${(idSeq.current++).toString(36)}`;
    while (taken.includes(id));
    return id;
  };
  const todayKey = useTodayKey(todayProp) ?? "2026-01-01";

  const [pop, setPop] = React.useState<{ anchor: string; step: Step; dir: 1 | -1 } | null>(null);
  const [popPos, setPopPos] = React.useState<{ left: number; top: number; width: number } | null>(null);
  const [draft, setDraft] = React.useState<Draft>(EMPTY_DRAFT);
  const [viewsOpen, setViewsOpen] = React.useState(false);

  const [saving, setSaving] = React.useState<null | { name: string; status: "idle" | "pending" | "error"; error?: string }>(
    null
  );

  const rootRef = React.useRef<HTMLDivElement>(null);
  const addRef = React.useRef<HTMLButtonElement>(null);
  const popRef = React.useRef<HTMLDivElement>(null);
  const anchorEl = React.useRef<HTMLElement | null>(null);
  const restoreEl = React.useRef<HTMLElement | null>(null);
  const saveInput = React.useRef<HTMLInputElement>(null);

  /* ----- intro (once in view; falls back on a timer so it never stays hidden) */
  const inView = useInView(rootRef, { once: true, amount: 0.2 });
  const [forced, setForced] = React.useState(false);
  const [introKey, setIntroKey] = React.useState(0);
  React.useEffect(() => {
    const t = window.setTimeout(() => setForced(true), 1200);
    return () => window.clearTimeout(t);
  }, []);
  const play = reduced || inView || forced;
  const [introDone, setIntroDone] = React.useState(false);
  React.useEffect(() => {
    if (!play || introDone) return;
    const t = window.setTimeout(() => setIntroDone(true), 900);
    return () => window.clearTimeout(t);
  }, [play, introDone, introKey]);

  /* ----- commits */
  const commit = React.useCallback(
    (next: SiftFilter[], msg?: string, keepView = true) => {
      if (value === undefined) setInnerFilters(next);
      onChange?.(next);
      if (msg) setAnnounce(msg);
      if (!keepView) setActiveViewId(null);
    },
    [value, onChange]
  );

  const setConj = (c: SiftConjunction) => {
    if (conjProp === undefined) setInnerConj(c);
    onConjunctionChange?.(c);
    setAnnounce(c === "and" ? "Matching all filters" : "Matching any filter");
  };

  const fieldOf = (key: string | null) => fields.find((f) => f.key === key);

  /* ----- popover */
  const place = React.useCallback(() => {
    const root = rootRef.current;
    const a = anchorEl.current;
    if (!root || !a) return;
    const r = root.getBoundingClientRect();
    const ar = a.getBoundingClientRect();
    const width = Math.min(POP_W, r.width - 12);
    const left = Math.max(6, Math.min(ar.left - r.left, r.width - width - 6));
    setPopPos({ left, top: ar.bottom - r.top + 6, width });
  }, []);

  const openAt = (anchor: string, el: HTMLElement | null, step: Step, d: Draft) => {
    setViewsOpen(false);
    setSaving(null);
    anchorEl.current = el;
    restoreEl.current = (document.activeElement as HTMLElement) ?? el;
    setDraft(d);
    setPop({ anchor, step, dir: 1 });
    place();
  };

  const openAdd = (fieldKey?: string) => {
    const f = fieldKey ? fieldOf(fieldKey) : undefined;
    openAt("add", addRef.current, f ? "operator" : "field", { ...EMPTY_DRAFT, field: f?.key ?? null });
  };

  const openEdit = (filter: SiftFilter, step: Step, el: HTMLElement | null) => {
    if (pop?.anchor === filter.id && pop.step === step) return closePop(true);
    openAt(filter.id, el, step, draftFrom(filter));
  };

  const closePop = (restore: boolean) => {
    setPop(null);
    if (restore) {
      const el = restoreEl.current;
      requestAnimationFrame(() => (el?.isConnected ? el : addRef.current)?.focus({ preventScroll: true }));
    }
  };

  const go = (step: Step) => setPop((p) => (p ? { ...p, step, dir: STEP_INDEX[step] >= STEP_INDEX[p.step] ? 1 : -1 } : p));

  const apply = (d: Draft = draft) => {
    const field = fieldOf(d.field);
    if (!field) return;
    const id = d.editingId ?? freshId("f", filters.map((x) => x.id));
    const f = buildFilter(d, field, id);
    if (!f) return;
    if (d.editingId) {
      commit(
        filters.map((x) => (x.id === d.editingId ? f : x)),
        `Filter updated: ${describe(field, f)}`
      );
    } else {
      commit([...filters, f], `Filter added: ${describe(field, f)}`);
      restoreEl.current = addRef.current;
    }
    closePop(true);
  };

  const pickField = (key: string) => {
    const nf = fieldOf(key);
    if (!nf) return;
    const prev = fieldOf(draft.field);
    const keep = prev && prev.type === nf.type && prev.key === nf.key;
    const sameType = prev && prev.type === nf.type;
    setDraft((d) => ({
      ...(keep ? d : sameType && nf.type !== "select" ? d : { ...EMPTY_DRAFT, editingId: d.editingId }),
      field: key,
    }));
    go("operator");
  };

  const pickOperator = (op: SiftOperator) => {
    const field = fieldOf(draft.field);
    if (!field) return;
    let d: Draft = { ...draft, operator: op };
    if (field.type === "date" && op !== "is") d = { ...d, preset: null };
    if (field.type === "date" && op !== "between") d = { ...d, dateB: null };
    if (field.type === "boolean") return apply(d);
    setDraft(d);
    // Editing in place: an operator swap that keeps a valid value applies at once.
    if (draft.editingId && buildFilter(d, field, draft.editingId) && pop?.step === "operator" && draft.operator) {
      const prevBetween = draft.operator === "between";
      if (prevBetween === (op === "between")) return apply(d);
    }
    go("value");
  };

  React.useEffect(() => {
    if (!pop) return;
    const root = rootRef.current;
    const ro = new ResizeObserver(() => place());
    if (root) ro.observe(root);
    const onDown = (e: PointerEvent) => {
      const t = e.target as Node;
      if (popRef.current?.contains(t) || anchorEl.current?.contains(t)) return;
      setPop(null);
    };
    document.addEventListener("pointerdown", onDown);
    return () => {
      ro.disconnect();
      document.removeEventListener("pointerdown", onDown);
    };
  }, [pop, place]);

  /* ----- chip ops */
  const removeChip = (id: string, focusAfter = false) => {
    const i = filters.findIndex((x) => x.id === id);
    if (i < 0) return;
    const f = filters[i];
    const field = fieldOf(f.field);
    const next = filters.filter((x) => x.id !== id);
    commit(next, field ? `Removed ${describe(field, f)}` : "Filter removed");
    if (pop?.anchor === id) setPop(null);
    if (focusAfter) {
      const target = next[Math.max(0, i - 1)]?.id;
      requestAnimationFrame(() => {
        const el = target
          ? rootRef.current?.querySelector<HTMLElement>(`[data-chip="${target}"] [data-part="field"]`)
          : addRef.current;
        el?.focus({ preventScroll: true });
      });
    }
  };

  const clearAll = () => {
    if (!filters.length) return;
    commit([], "All filters cleared");
    setPop(null);
    requestAnimationFrame(() => addRef.current?.focus({ preventScroll: true }));
  };

  const pickView = (v: SiftView) => {
    setActiveViewId(v.id);
    setEpoch((e) => e + 1);
    commit(v.filters, `View: ${v.label}, ${v.filters.length} filter${v.filters.length === 1 ? "" : "s"}`);
    const c = v.conjunction ?? "and";
    if (c !== conj) {
      if (conjProp === undefined) setInnerConj(c);
      onConjunctionChange?.(c);
    }
    setPop(null);
    onViewChange?.(v);
  };

  const startSave = () => {
    setPop(null);
    setViewsOpen(false);
    setSaving({ name: "", status: "idle" });
    requestAnimationFrame(() => saveInput.current?.focus({ preventScroll: true }));
  };

  const submitSave = async () => {
    if (!saving || saving.status === "pending") return;
    const name = saving.name.trim();
    if (!name) {
      setSaving({ ...saving, status: "error", error: "Name the view" });
      return;
    }
    const view: SiftView = {
      id: freshId("view", views.map((v) => v.id)),
      label: name,
      filters: filters.map((f) => ({ ...f })),
      conjunction: conj,
    };
    try {
      const r = onSaveView?.(view);
      if (r && typeof (r as Promise<unknown>).then === "function") {
        setSaving({ name, status: "pending" });
        await r;
      }
      setSaved((s) => [...s, view]);
      setActiveViewId(view.id);
      setSaving(null);
      setAnnounce(`View saved: ${name}`);
    } catch (err) {
      setSaving({ name, status: "error", error: err instanceof Error ? err.message : "Couldn't save view" });
      requestAnimationFrame(() => saveInput.current?.focus({ preventScroll: true }));
    }
  };

  /* ----- handle */
  React.useImperativeHandle(
    ref,
    () => ({
      open: (k?: string) => openAdd(k),
      close: () => {
        setPop(null);
        setViewsOpen(false);
      },
      clear: () => commit([], "All filters cleared"),
      replay: () => {
        setIntroDone(false);
        setIntroKey((k) => k + 1);
      },
    })
  );

  /* ----- keyboard */
  const onRootKey = (e: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    const t = e.target as HTMLElement;
    const typing = t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable;
    if (e.key === "Escape" && pop) {
      e.preventDefault();
      closePop(true);
      return;
    }
    if (pop && e.key === "Tab" && popRef.current?.contains(t)) {
      // Trap focus within the popover.
      const items = [
        ...popRef.current.querySelectorAll<HTMLElement>(
          'button:not([disabled]), input, [tabindex="0"]'
        ),
      ].filter((el) => el.offsetParent !== null);
      if (items.length) {
        const i = items.indexOf(t);
        const n = e.shiftKey ? (i <= 0 ? items.length - 1 : i - 1) : i === items.length - 1 ? 0 : i + 1;
        e.preventDefault();
        items[n].focus({ preventScroll: true });
      }
      return;
    }
    if (!typing && !pop && e.key.toLowerCase() === "f" && !e.metaKey && !e.ctrlKey && !e.altKey) {
      e.preventDefault();
      addRef.current?.focus({ preventScroll: true });
    }
  };

  const onChipKey = (e: React.KeyboardEvent, i: number, id: string) => {
    if (e.key === "Backspace" || e.key === "Delete") {
      e.preventDefault();
      e.stopPropagation();
      removeChip(id, true);
    } else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      const n = i + (e.key === "ArrowRight" ? 1 : -1);
      if (n < 0) return;
      const target = filters[n]?.id;
      const el = target
        ? rootRef.current?.querySelector<HTMLElement>(`[data-chip="${target}"] [data-part="field"]`)
        : addRef.current;
      el?.focus({ preventScroll: true });
    }
  };

  /* ----- derived render bits */
  const accentStyle = {
    "--sift-accent": accentColor,
    "--sift-ink": inkFor(accentColor),
    ...style,
  } as React.CSSProperties;
  const popField = fieldOf(draft.field);
  const popOp = draft.operator && popField ? opLabel(popField.type, draft.operator) : null;
  const canApply = !!(popField && buildFilter(draft, popField, "x"));
  const showViews = views.length > 0;
  const prevCount = usePrev(count);
  const layoutOn = !reduced;

  const chipTransition = (i: number): Transition =>
    reduced ? REDUCED_T : { ...SPRING, delay: introDone ? 0 : 0.14 + i * 0.05 };

  /* ----- step body */
  let body: React.ReactNode = null;
  if (pop) {
    if (pop.step === "field") body = <FieldStep uid={uid} fields={fields} selected={draft.field} onPick={pickField} />;
    else if (pop.step === "operator" && popField)
      body = <OperatorStep uid={uid} type={popField.type} selected={draft.operator} onPick={pickOperator} />;
    else if (pop.step === "value" && popField) {
      const set = (p: Partial<Draft>) => setDraft((d) => ({ ...d, ...p }));
      const submit = () => apply();
      body =
        popField.type === "text" ? (
          <TextEditor draft={draft} set={set} submit={submit} />
        ) : popField.type === "select" ? (
          <SelectEditor uid={uid} field={popField} draft={draft} set={set} submit={submit} />
        ) : popField.type === "number" ? (
          <NumberEditor draft={draft} set={set} submit={submit} />
        ) : popField.type === "date" ? (
          <DateEditor draft={draft} set={set} today={todayKey} submit={submit} />
        ) : null;
    }
  }

  return (
    <div
      ref={rootRef}
      data-crucible="sift"
      className={cn("@container relative w-full text-[13px] text-white", className)}
      style={accentStyle}
      onKeyDown={onRootKey}
      {...rest}
    >
      <motion.div
        key={introKey}
        initial={{ opacity: 0, y: 8 }}
        animate={play ? { opacity: 1, y: 0 } : undefined}
        transition={reduced ? { duration: 0.15, ease: "easeOut" } : { duration: 0.45, ease: EASE }}
        className="rounded-2xl border border-white/[0.08] bg-[#111113]/90 shadow-[inset_0_1px_0_rgba(255,255,255,0.04),0_24px_60px_-28px_rgba(0,0,0,0.8)] backdrop-blur-sm"
      >
        {/* header: views · count · save */}
        <div className="flex min-h-12 flex-wrap items-center gap-x-2 gap-y-1 border-b border-white/[0.06] px-2 py-1.5">
          {showViews ? (
            <ViewsMenu
              uid={uid}
              views={views}
              activeId={activeViewId}
              edited={edited}
              open={viewsOpen}
              setOpen={(o) => {
                if (o) setPop(null);
                setViewsOpen(o);
              }}
              onPick={pickView}
            />
          ) : (
            <span className="flex h-8 items-center gap-2 px-2 text-[13px] font-medium text-white/85">
              <span className="text-white/45">{Icon.funnel}</span>Filters
            </span>
          )}

          <div className="ml-auto flex min-w-0 items-center gap-2.5">
            {count !== undefined && (
              <span className="flex items-baseline gap-1 whitespace-nowrap px-1 text-[12.5px] text-white/45" aria-live="polite">
                {reduced ? (
                  <span className="font-medium tabular-nums text-white">{count}</span>
                ) : (
                  <Tally
                    key={count}
                    value={count}
                    start={prevCount ?? count}
                    duration={0.55}
                    stagger={0.03}
                    glow={false}
                    glint={false}
                    className="font-medium text-white"
                  />
                )}
                {total !== undefined && <span className="tabular-nums">of {total}</span>}
                <span>{count === 1 ? noun.one : noun.other}</span>
              </span>
            )}
            {onSaveView && (
              <AnimatePresence mode="popLayout" initial={false}>
                {saving ? (
                  <motion.form
                    key="save-form"
                    initial={reduced ? { opacity: 0 } : { opacity: 0, width: 96 }}
                    animate={{ opacity: 1, width: "auto" }}
                    exit={{ opacity: 0 }}
                    transition={reduced ? FADE : { duration: 0.22, ease: EASE }}
                    onSubmit={(e) => {
                      e.preventDefault();
                      void submitSave();
                    }}
                    className="flex items-center gap-1"
                  >
                    <motion.input
                      ref={saveInput}
                      value={saving.name}
                      disabled={saving.status === "pending"}
                      onChange={(e) => setSaving({ name: e.target.value, status: "idle" })}
                      onKeyDown={(e) => {
                        if (e.key === "Escape") {
                          e.preventDefault();
                          e.stopPropagation();
                          setSaving(null);
                        }
                      }}
                      onBlur={(e) => {
                        if (!saving.name.trim() && !e.currentTarget.form?.contains(e.relatedTarget as Node)) setSaving(null);
                      }}
                      animate={saving.status === "error" && !reduced ? { x: [0, -4, 4, -2, 0] } : { x: 0 }}
                      transition={{ duration: 0.3 }}
                      aria-label="View name"
                      aria-invalid={saving.status === "error" || undefined}
                      title={saving.error}
                      placeholder={saving.error ?? "View name"}
                      maxLength={40}
                      className={cn(
                        "h-8 w-[min(11rem,40cqw)] rounded-lg border bg-white/[0.04] px-2.5 text-[13px] text-white placeholder:text-white/35 outline-none transition-colors focus:border-[color-mix(in_srgb,var(--sift-accent)_50%,transparent)] disabled:opacity-60",
                        saving.status === "error" ? "border-red-400/50 placeholder:text-red-300/70" : "border-white/10"
                      )}
                    />
                    <button
                      type="submit"
                      aria-label="Save view"
                      disabled={saving.status === "pending"}
                      className={cn(
                        "grid size-8 shrink-0 place-items-center rounded-lg transition-[filter] hover:brightness-110 disabled:cursor-progress",
                        FOCUS
                      )}
                      style={{ background: "var(--sift-accent)", color: "var(--sift-ink)" }}
                    >
                      {saving.status === "pending" ? (
                        <motion.span
                          aria-hidden
                          className="block size-3.5 rounded-full border-2 border-current border-t-transparent"
                          animate={reduced ? undefined : { rotate: 360 }}
                          transition={{ duration: 0.8, repeat: Infinity, ease: "linear" }}
                        />
                      ) : (
                        Icon.check
                      )}
                    </button>
                  </motion.form>
                ) : (
                  <motion.button
                    key="save-btn"
                    type="button"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: !filters.length || !edited ? 0.35 : 1 }}
                    exit={{ opacity: 0 }}
                    transition={FADE}
                    onClick={startSave}
                    disabled={!filters.length || !edited}
                    className={cn(
                      "h-8 whitespace-nowrap rounded-lg border border-white/10 px-2.5 text-[12.5px] font-medium text-white/75 transition-colors hover:border-white/15 hover:bg-white/[0.04] hover:text-white disabled:pointer-events-none",
                      FOCUS
                    )}
                  >
                    Save view
                  </motion.button>
                )}
              </AnimatePresence>
            )}
          </div>
        </div>

        {/* chips row — views crossfade by stacking epochs in one grid cell */}
        <div className="grid p-2">
          <AnimatePresence initial={false}>
            <motion.div
              key={epoch}
              className="relative col-start-1 row-start-1"
              initial={{ opacity: 0, filter: reduced ? "blur(0px)" : "blur(3px)" }}
              animate={{ opacity: 1, filter: "blur(0px)" }}
              exit={{ opacity: 0, filter: reduced ? "blur(0px)" : "blur(3px)" }}
              transition={{ duration: reduced ? 0.15 : 0.24, ease: "easeOut" }}
            >
              <LayoutGroup id={`${uid}-${epoch}`}>
                <div role="group" aria-label="Applied filters" className="relative flex flex-wrap items-center gap-1.5">
                  <AnimatePresence mode="popLayout" initial={true}>
                    {filters.map((f, i) => {
                      const field = fieldOf(f.field);
                      if (!field) return null;
                      const val = summarize(field, f);
                      const on = pop?.anchor === f.id;
                      const opts = field.type === "select" ? optionsOf(field) : [];
                      const firstColor =
                        field.type === "select" && Array.isArray(f.value) && f.value.length === 1
                          ? (opts.find((o) => o.value === (f.value as string[])[0])?.color ?? "")
                          : "";
                      return (
                        <motion.div
                          key={f.id}
                          layout={layoutOn ? "position" : false}
                          className="flex items-center gap-1.5"
                          initial={{ opacity: 0, scale: 0.86, y: 3 }}
                          animate={play ? { opacity: 1, scale: 1, y: 0 } : undefined}
                          exit={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.86, filter: "blur(2px)" }}
                          transition={chipTransition(i)}
                        >
                          {i > 0 && (
                            <button
                              type="button"
                              onClick={() => setConj(conj === "and" ? "or" : "and")}
                              aria-label={`Combine filters with ${conj}. Switch to ${conj === "and" ? "or" : "and"}`}
                              className={cn(
                                "h-6 min-w-8 rounded-md px-1.5 text-[11.5px] font-medium uppercase tracking-[0.06em] text-white/40 transition-colors hover:bg-white/[0.05] hover:text-white/80",
                                FOCUS
                              )}
                            >
                              <AnimatePresence mode="popLayout" initial={false}>
                                <motion.span
                                  key={conj}
                                  className="inline-block"
                                  initial={reduced ? { opacity: 0 } : { opacity: 0, y: 6 }}
                                  animate={{ opacity: 1, y: 0 }}
                                  exit={reduced ? { opacity: 0 } : { opacity: 0, y: -6 }}
                                  transition={{ duration: 0.16, ease: EASE }}
                                >
                                  {conj}
                                </motion.span>
                              </AnimatePresence>
                            </button>
                          )}
                          <div
                            data-chip={f.id}
                            role="group"
                            aria-label={`Filter: ${describe(field, f)}. Backspace removes, arrow keys move between filters`}
                            onKeyDown={(e) => onChipKey(e, i, f.id)}
                            className={cn(
                              "flex h-8 max-w-full items-stretch overflow-hidden rounded-[9px] border bg-white/[0.035] transition-[border-color,box-shadow,background-color] duration-200",
                              on
                                ? "border-[color-mix(in_srgb,var(--sift-accent)_55%,transparent)] bg-[color-mix(in_srgb,var(--sift-accent)_7%,transparent)] shadow-[0_0_0_3px_color-mix(in_srgb,var(--sift-accent)_12%,transparent)]"
                                : "border-white/[0.09] hover:border-white/[0.14]"
                            )}
                          >
                            <ChipPart
                              part="field"
                              label={`Change property (${field.label})`}
                              onClick={(e) => openEdit(f, "field", e.currentTarget.closest("[data-chip]"))}
                              className="gap-1.5 pl-2.5 text-white/60"
                            >
                              <span className="text-white/40">{field.icon ?? TYPE_ICON[field.type]}</span>
                              <span className="hidden whitespace-nowrap @[18rem]:inline">{field.label}</span>
                            </ChipPart>
                            <ChipPart
                              part="op"
                              label={`Change operator (${opLabel(field.type, f.operator)})`}
                              onClick={(e) => openEdit(f, "operator", e.currentTarget.closest("[data-chip]"))}
                              className={cn("text-white/40", opLabel(field.type, f.operator).length === 1 && "font-mono")}
                            >
                              <span className="whitespace-nowrap">{opLabel(field.type, f.operator)}</span>
                            </ChipPart>
                            {val && (
                              <ChipPart
                                part="value"
                                label={`Change value (${val})`}
                                onClick={(e) => openEdit(f, "value", e.currentTarget.closest("[data-chip]"))}
                                className="min-w-0 gap-1.5 font-medium text-[var(--sift-accent)]"
                              >
                                <Dot color={firstColor} />
                                <span className="truncate tabular-nums">{val}</span>
                              </ChipPart>
                            )}
                            <button
                              type="button"
                              aria-label={`Remove filter ${describe(field, f)}`}
                              onClick={() => removeChip(f.id, true)}
                              className="grid w-7 shrink-0 place-items-center border-l border-white/[0.06] text-white/35 transition-colors hover:bg-white/[0.06] hover:text-white focus-visible:bg-white/[0.08] focus-visible:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[var(--sift-accent)]"
                            >
                              {Icon.x}
                            </button>
                          </div>
                        </motion.div>
                      );
                    })}
                    {/* Add + Clear all wrap together, so "Clear all" never lands alone on a row. */}
                    <motion.div
                      key="tail"
                      layout={layoutOn ? "position" : false}
                      className={cn(
                        "flex flex-1 items-center gap-1.5",
                        // nowrap → the pair's min-content is both buttons, so the row
                        // breaks before them rather than between them.
                        filters.length ? "flex-nowrap" : "min-w-0 flex-wrap"
                      )}
                    >
                      <motion.button
                        ref={addRef}
                        type="button"
                        aria-haspopup="dialog"
                        aria-expanded={pop?.anchor === "add"}
                        aria-keyshortcuts="F"
                        onClick={() => (pop?.anchor === "add" ? closePop(true) : openAdd())}
                        initial={{ opacity: 0, y: 3 }}
                        animate={play ? { opacity: 1, y: 0 } : undefined}
                        transition={reduced ? REDUCED_T : { ...SPRING, delay: introDone ? 0 : 0.14 + filters.length * 0.05 }}
                        className={cn(
                          "flex h-8 items-center gap-1.5 rounded-[9px] border border-dashed px-2.5 text-[12.5px] font-medium transition-colors",
                          pop?.anchor === "add"
                            ? "border-[color-mix(in_srgb,var(--sift-accent)_55%,transparent)] bg-white/[0.05] text-white"
                            : "border-white/15 text-white/60 hover:border-white/25 hover:bg-white/[0.03] hover:text-white",
                          FOCUS
                        )}
                      >
                        {Icon.plus}
                        Filter
                        <kbd className="ml-0.5 hidden rounded border border-white/10 px-1 font-sans text-[10px] leading-[14px] text-white/35 @[30rem]:inline">
                          F
                        </kbd>
                      </motion.button>
                      <AnimatePresence initial={false} mode="popLayout">
                        {!filters.length && (
                          <motion.span
                            key="empty"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            transition={FADE}
                            className="px-1 text-[12.5px] text-white/35"
                          >
                            No filters — showing everything
                          </motion.span>
                        )}
                        {filters.length > 0 && (
                          <motion.button
                            key="clear"
                            type="button"
                            onClick={clearAll}
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            transition={FADE}
                            className={cn(
                              "ml-auto h-8 whitespace-nowrap rounded-lg px-2 text-[12.5px] text-white/45 underline-offset-4 transition-colors hover:text-white hover:underline",
                              FOCUS
                            )}
                          >
                            Clear all
                          </motion.button>
                        )}
                      </AnimatePresence>
                    </motion.div>
                  </AnimatePresence>
                </div>
              </LayoutGroup>
            </motion.div>
          </AnimatePresence>
        </div>
      </motion.div>

      {/* popover */}
      <AnimatePresence>
        {pop && popPos && (
          <motion.div
            ref={popRef}
            role="dialog"
            aria-label={
              pop.step === "field"
                ? "Choose a property"
                : pop.step === "operator"
                  ? `${popField?.label ?? ""}: choose an operator`
                  : `${popField?.label ?? ""} ${popOp ?? ""}: choose a value`
            }
            initial={reduced ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={reduced ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            transition={reduced ? FADE : { duration: 0.18, ease: EASE }}
            style={{ left: popPos.left, top: popPos.top, width: popPos.width, transformOrigin: "top left" }}
            className="absolute z-50 overflow-hidden rounded-xl border border-white/10 bg-[#141416] shadow-[0_28px_60px_-16px_rgba(0,0,0,0.85),0_0_0_1px_rgba(0,0,0,0.45)]"
          >
            {/* step header */}
            <div className="flex h-10 items-center gap-1.5 border-b border-white/[0.06] px-1.5">
              {pop.step !== "field" ? (
                <button
                  type="button"
                  aria-label="Back"
                  onClick={() => go(pop.step === "value" ? "operator" : "field")}
                  className={cn("grid size-7 place-items-center rounded-md text-white/50 hover:bg-white/[0.06] hover:text-white", FOCUS)}
                >
                  {Icon.back}
                </button>
              ) : (
                <span className="grid size-7 place-items-center text-white/40">{Icon.funnel}</span>
              )}
              <div className="flex min-w-0 flex-1 items-center gap-1.5 text-[12.5px]">
                {pop.step === "field" ? (
                  <span className="font-medium text-white/80">{draft.editingId ? "Change property" : "Add filter"}</span>
                ) : (
                  <>
                    <span className="text-white/40">{popField?.icon ?? (popField && TYPE_ICON[popField.type])}</span>
                    <span className="truncate font-medium text-white/85">{popField?.label}</span>
                    {pop.step === "value" && popOp && (
                      <span className={cn("shrink-0 text-white/40", popOp?.length === 1 && "font-mono")}>{popOp}</span>
                    )}
                  </>
                )}
              </div>
              <StepDots step={pop.step} />
            </div>

            <PopBody stepKey={pop.step} dir={pop.dir} reduced={reduced}>
              {body}
            </PopBody>

            {pop.step === "value" && popField && popField.type !== "boolean" && (
              <div className="flex items-center gap-2 border-t border-white/[0.06] px-2 py-2">
                <span className="min-w-0 flex-1 truncate pl-1 text-[12px] text-white/40">
                  {popField.type === "select"
                    ? `${draft.sel.length} selected`
                    : popField.type === "date"
                      ? draft.preset
                        ? PRESET_LABEL[draft.preset]
                        : draft.dateA
                          ? draft.operator === "between"
                            ? `${fmtDay(draft.dateA)} – ${draft.dateB ? fmtDay(draft.dateB) : "…"}`
                            : fmtDay(draft.dateA)
                          : "Pick a date"
                      : "Enter to apply"}
                </span>
                <button
                  type="button"
                  onClick={() => apply()}
                  disabled={!canApply}
                  className={cn(
                    "h-8 rounded-lg px-3.5 text-[12.5px] font-semibold transition-[filter,opacity,transform] duration-150 hover:brightness-110 active:scale-[0.97] disabled:pointer-events-none disabled:opacity-35",
                    "outline-none focus-visible:ring-2 focus-visible:ring-white/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[#141416]"
                  )}
                  style={{ background: "var(--sift-accent)", color: "var(--sift-ink)" }}
                >
                  {draft.editingId ? "Update" : "Apply"}
                </button>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <span role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

/* ================================================================ internals */

function usePrev<T>(value: T): T | undefined {
  const [state, setState] = React.useState<{ current: T; previous: T | undefined }>({ current: value, previous: undefined });
  if (!Object.is(state.current, value)) setState({ current: value, previous: state.current });
  return state.previous;
}

function ChipPart({
  part,
  label,
  onClick,
  className,
  children,
}: {
  part: string;
  label: string;
  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      data-part={part}
      aria-label={label}
      onClick={onClick}
      className={cn(
        "flex min-w-0 items-center px-2 text-[12.5px] transition-colors hover:bg-white/[0.05] focus-visible:bg-white/[0.07] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[var(--sift-accent)]",
        part !== "field" && "border-l border-white/[0.06]",
        className
      )}
    >
      {children}
    </button>
  );
}

function StepDots({ step }: { step: Step }) {
  const n = STEP_INDEX[step];
  return (
    <span aria-hidden className="flex items-center gap-1 pr-1.5">
      {[0, 1, 2].map((i) => (
        <span
          key={i}
          className="h-1 rounded-full transition-all duration-300"
          style={{
            width: i === n ? 12 : 4,
            background: i <= n ? "var(--sift-accent)" : "rgba(255,255,255,0.15)",
            opacity: i === n ? 1 : i < n ? 0.5 : 1,
          }}
        />
      ))}
    </span>
  );
}

/** Slides step content horizontally and springs the popover height to fit. */
function PopBody({
  stepKey,
  dir,
  reduced,
  children,
}: {
  stepKey: string;
  dir: 1 | -1;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const inner = React.useRef<HTMLDivElement>(null);
  const [h, setH] = React.useState<number | "auto">("auto");
  React.useEffect(() => {
    const el = inner.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setH(el.offsetHeight));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return (
    <motion.div
      animate={{ height: h }}
      initial={false}
      transition={reduced ? { duration: 0 } : SLIDE}
      className="relative overflow-hidden"
    >
      <div ref={inner} className="relative">
        <AnimatePresence mode="popLayout" initial={false} custom={dir}>
          <motion.div
            key={stepKey}
            custom={dir}
            variants={{
              enter: (d: number) => (reduced ? { opacity: 0 } : { opacity: 0, x: d * 28 }),
              center: { opacity: 1, x: 0 },
              exit: (d: number) => (reduced ? { opacity: 0 } : { opacity: 0, x: d * -28 }),
            }}
            initial="enter"
            animate="center"
            exit="exit"
            transition={reduced ? FADE : { ...SLIDE, opacity: { duration: 0.16 } }}
            className="w-full"
          >
            {children}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface SonarProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Two tones `[phosphor, background]`. `phosphor` colors the sweep beam,
   * range rings, spokes and contact blips; `background` is the scope glass the
   * whole instrument sits on. Defaults to classic phosphor green on
   * near-black — pass amber (`["#fbbf24", "#140e04"]`) for a vintage CRT or
   * ice blue for a naval console.
   * @default ["#34d399", "#04140c"]
   */
  colors?: [string, string];
  /** Sweep-speed multiplier on top of `period`. `0` freezes the scope. 1 = default. @default 1 */
  speed?: number;
  /** Overall beam / blip / grid brightness, 0–2. @default 1 */
  intensity?: number;
  /** Seconds per full beam revolution (before `speed`). Clamped 2–60. @default 6 */
  period?: number;
  /** Number of labeled range rings inside the scope circle. Clamped 1–12. @default 4 */
  rings?: number;
  /** Number of seeded contacts on the scope. Clamped 0–24. @default 8 */
  contacts?: number;
  /**
   * Phosphor persistence, 0–1 — how far around the dial the sweep's afterglow
   * survives and how slowly contact blips decay between passes.
   * @default 0.55
   */
  persistence?: number;
  /** Full instrument look: center crosshair + range-ring labels. @default false */
  hud?: boolean;
  /** Seed for contact placement and drift — same seed, same scope picture. @default 0x50a44e1d */
  seed?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /** Freeze at the designed static frame (beam mid-sweep, two contacts lit). @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: [string, string] = ["#34d399", "#04140c"];
const TAU = Math.PI * 2;
const DEFAULT_SEED = 0x50a44e1d;
/** Static-frame beam heading (up-right) — used when reduced-motion / paused. */
const STATIC_ANGLE = -Math.PI / 3;
/** Azimuth spokes around the dial (every 30°). */
const SPOKES = 12;

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [52, 211, 153];
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

function mix(
  a: [number, number, number],
  b: [number, number, number],
  t: number
): [number, number, number] {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t),
  ];
}

function rgba(rgb: [number, number, number], a: number): string {
  return `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a})`;
}

/** Deterministic mulberry32 — seeded so the scope picture is identical SSR intent ↔ CSR. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Contact {
  /** Normalized position in the container (0–1) so resizes keep the picture. */
  nx: number;
  ny: number;
  /** Normalized drift velocity per second — zero for stationary contacts. */
  vx: number;
  vy: number;
  /** Blip size scalar, 0–1. */
  size: number;
  /** Excitement 0–1 — set to 1 when the beam crosses, decays until next pass. */
  e: number;
  /** Which beam lap last lit this contact (crossing detector). */
  lastPass: number;
  /** Seconds since last excitation, drives the wake-up ripple ring. */
  rippleAge: number;
  drifter: boolean;
  /** Past blip positions (px) for drifting contact tracks. */
  track: { x: number; y: number; t: number }[];
}

interface Internals {
  gridCtx: CanvasRenderingContext2D;
  fxCtx: CanvasRenderingContext2D;
  width: number;
  height: number;
  cx: number;
  cy: number;
  /** Full-bleed radius — the sweep reaches every corner. */
  rFull: number;
  /** Inscribed scope radius — labeled rings live inside this. */
  rIn: number;
  /** Cached radial mask that shapes the sweep (center dead-zone, rim falloff). */
  radialMask: CanvasGradient | null;
  contactList: Contact[];
  phosphor: [number, number, number];
  bg: [number, number, number];
  hot: [number, number, number];
  /** Sweep angular velocity, rad/s (period × speed applied). */
  omega: number;
  /** Fraction of the dial the afterglow spans. */
  trailFrac: number;
  /** Contact-blip decay time constant, seconds. */
  blipTau: number;
  intensity: number;
  rings: number;
  hud: boolean;
  /** Seeded per-instance start heading — multiple instances desynchronize. */
  angle0: number;
  lastElapsed: number;
  primed: boolean;
}

/** Paint the static instrument: glass, grain, range rings, spokes, HUD. */
function drawGrid(it: Internals) {
  const { gridCtx: ctx, width: w, height: h, cx, cy, rFull, rIn, phosphor, bg } = it;
  const gi = it.intensity;

  ctx.fillStyle = rgba(bg, 1);
  ctx.fillRect(0, 0, w, h);

  // Scope-glass glow — a whisper of phosphor lifting the center.
  const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, rIn * 1.15);
  glow.addColorStop(0, rgba(phosphor, 0.055 * gi));
  glow.addColorStop(0.55, rgba(phosphor, 0.02 * gi));
  glow.addColorStop(1, rgba(phosphor, 0));
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);

  // Seeded grain tile — breaks banding on the glass gradient.
  const tile = document.createElement("canvas");
  tile.width = 96;
  tile.height = 96;
  const tctx = tile.getContext("2d");
  if (tctx) {
    const img = tctx.createImageData(96, 96);
    const rand = mulberry32(0x9e3779b9);
    for (let p = 0; p < img.data.length; p += 4) {
      const v = rand();
      img.data[p] = phosphor[0];
      img.data[p + 1] = phosphor[1];
      img.data[p + 2] = phosphor[2];
      img.data[p + 3] = (v * 10) | 0; // ≤4% alpha speckle
    }
    tctx.putImageData(img, 0, 0);
    const pattern = ctx.createPattern(tile, "repeat");
    if (pattern) {
      ctx.fillStyle = pattern;
      ctx.fillRect(0, 0, w, h);
    }
  }

  // Azimuth spokes — every 30°, cardinal directions a touch brighter.
  ctx.lineWidth = 1;
  for (let s = 0; s < SPOKES; s++) {
    const a = (s / SPOKES) * TAU;
    const cardinal = s % 3 === 0;
    ctx.strokeStyle = rgba(phosphor, (cardinal ? 0.075 : 0.045) * gi);
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * rIn * 0.02, cy + Math.sin(a) * rIn * 0.02);
    ctx.lineTo(cx + Math.cos(a) * rFull, cy + Math.sin(a) * rFull);
    ctx.stroke();
  }

  // Range rings — labeled set inside the scope circle, fainter ones continue
  // outward so the instrument bleeds through the corners of the frame.
  const gap = rIn / it.rings;
  for (let k = 1; k * gap <= rFull + gap; k++) {
    const r = k * gap;
    const inside = k <= it.rings;
    const isBezel = k === it.rings;
    ctx.strokeStyle = rgba(phosphor, (isBezel ? 0.3 : inside ? 0.15 : 0.06) * gi);
    ctx.lineWidth = isBezel ? 1.5 : 1;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, TAU);
    ctx.stroke();
  }

  if (it.hud) {
    // Crosshair hairlines through the full frame.
    ctx.strokeStyle = rgba(phosphor, 0.13 * gi);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, cy + 0.5);
    ctx.lineTo(w, cy + 0.5);
    ctx.moveTo(cx + 0.5, 0);
    ctx.lineTo(cx + 0.5, h);
    ctx.stroke();

    // Range labels climbing the upper crosshair.
    ctx.font = "10px ui-monospace, SFMono-Regular, Menlo, monospace";
    ctx.textAlign = "left";
    ctx.textBaseline = "bottom";
    ctx.fillStyle = rgba(phosphor, 0.45 * gi);
    for (let k = 1; k <= it.rings; k++) {
      ctx.fillText(String(k * 100), cx + 5, cy - k * gap - 3);
    }
  }
}

/** The sweep: soft angular-gradient wedge trailing behind the beam heading. */
function drawSweep(it: Internals, beamAngle: number) {
  const { fxCtx: ctx, width: w, height: h, cx, cy, phosphor, trailFrac } = it;
  const peak = Math.min(0.5 * it.intensity, 0.85);

  if (typeof ctx.createConicGradient === "function") {
    // Conic runs clockwise from the beam heading; the sweep also rotates
    // clockwise, so the afterglow sits just behind — near t = 1.
    const conic = ctx.createConicGradient(beamAngle, cx, cy);
    conic.addColorStop(0, rgba(phosphor, peak));
    conic.addColorStop(0.004, rgba(phosphor, 0)); // razor falloff ahead of the beam
    conic.addColorStop(Math.max(0.005, 1 - trailFrac), rgba(phosphor, 0));
    // Exponential tail — tone-mapped decay, never a linear ramp.
    for (let s = 1; s <= 8; s++) {
      const u = 1 - s / 9; // 1 → oldest, 0 → freshest
      conic.addColorStop(1 - trailFrac * u, rgba(phosphor, peak * Math.exp(-4.2 * u)));
    }
    conic.addColorStop(1, rgba(phosphor, peak));
    ctx.fillStyle = conic;
    ctx.fillRect(0, 0, w, h);
  } else {
    // Ancient-browser fallback: one soft uniform wedge.
    ctx.fillStyle = rgba(phosphor, peak * 0.3);
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, it.rFull, beamAngle - trailFrac * TAU * 0.5, beamAngle);
    ctx.closePath();
    ctx.fill();
  }

  // Radial shaping: dead-zone at the hub, glass falloff toward the rim.
  if (it.radialMask) {
    ctx.globalCompositeOperation = "destination-in";
    ctx.fillStyle = it.radialMask;
    ctx.fillRect(0, 0, w, h);
    ctx.globalCompositeOperation = "source-over";
  }
}

/** Bright leading edge of the beam — the hot line the phosphor chases. */
function drawBeamEdge(it: Internals, beamAngle: number) {
  const { fxCtx: ctx, cx, cy, rFull, hot } = it;
  const ex = cx + Math.cos(beamAngle) * rFull;
  const ey = cy + Math.sin(beamAngle) * rFull;
  ctx.globalCompositeOperation = "lighter";
  ctx.lineCap = "round";
  ctx.strokeStyle = rgba(hot, Math.min(0.16 * it.intensity, 0.4));
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(beamAngle) * 6, cy + Math.sin(beamAngle) * 6);
  ctx.lineTo(ex, ey);
  ctx.stroke();
  ctx.strokeStyle = rgba(hot, Math.min(0.7 * it.intensity, 1));
  ctx.lineWidth = 1.25;
  ctx.stroke();
  ctx.globalCompositeOperation = "source-over";
}

/** Contact blips, wake-up ripples and drifting tracks. */
function drawContacts(it: Internals, elapsed: number) {
  const { fxCtx: ctx, width: w, height: h, phosphor, hot } = it;
  const trackTau = it.blipTau * 2.9;
  ctx.globalCompositeOperation = "lighter";

  for (const c of it.contactList) {
    const px = c.nx * w;
    const py = c.ny * h;

    // Faded breadcrumb track behind drifting contacts.
    for (const p of c.track) {
      const a = 0.3 * Math.exp(-(elapsed - p.t) / trackTau) * it.intensity;
      if (a < 0.015) continue;
      ctx.fillStyle = rgba(phosphor, Math.min(a, 0.35));
      ctx.beginPath();
      ctx.arc(p.x, p.y, 1.6, 0, TAU);
      ctx.fill();
    }

    const a = Math.pow(Math.max(c.e, 0), 1.35) * it.intensity;
    if (a < 0.012) continue;

    const r = 7 + c.size * 7;
    const bloom = ctx.createRadialGradient(px, py, 0, px, py, r);
    bloom.addColorStop(0, rgba(hot, Math.min(a, 1)));
    bloom.addColorStop(0.3, rgba(phosphor, Math.min(a * 0.55, 1)));
    bloom.addColorStop(1, rgba(phosphor, 0));
    ctx.fillStyle = bloom;
    ctx.beginPath();
    ctx.arc(px, py, r, 0, TAU);
    ctx.fill();

    // Wake-up ripple right after the beam finds it.
    if (c.rippleAge < 0.55) {
      const t = c.rippleAge / 0.55;
      ctx.strokeStyle = rgba(phosphor, (1 - t) * 0.45 * it.intensity);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(px, py, 4 + t * 26, 0, TAU);
      ctx.stroke();
    }
  }
  ctx.globalCompositeOperation = "source-over";
}

/** Advance drift + beam-crossing excitement for one frame. */
function updateContacts(it: Internals, beamAngle: number, dt: number, elapsed: number) {
  const { width: w, height: h, cx, cy } = it;
  const decay = Math.exp(-dt / it.blipTau);
  for (const c of it.contactList) {
    if (c.drifter) {
      c.nx += c.vx * dt;
      c.ny += c.vy * dt;
      if (c.nx < 0.06 || c.nx > 0.94) c.vx *= -1;
      if (c.ny < 0.08 || c.ny > 0.92) c.vy *= -1;
      c.nx = Math.min(Math.max(c.nx, 0.06), 0.94);
      c.ny = Math.min(Math.max(c.ny, 0.08), 0.92);
    }
    const theta = Math.atan2(c.ny * h - cy, c.nx * w - cx);
    const pass = Math.floor((beamAngle - theta) / TAU);
    if (pass > c.lastPass) {
      c.lastPass = pass;
      c.e = 1;
      c.rippleAge = 0;
      if (c.drifter) {
        c.track.push({ x: c.nx * w, y: c.ny * h, t: elapsed });
        if (c.track.length > 5) c.track.shift();
      }
    } else {
      c.e *= decay;
      c.rippleAge += dt;
    }
  }
}

/**
 * The designed still: beam frozen mid-sweep with its full afterglow, the two
 * contacts just behind the beam lit bright, the rest as faint embers.
 */
function poseStaticContacts(it: Internals, beamAngle: number) {
  const { width: w, height: h, cx, cy } = it;
  const behind = it.contactList.map(c => {
    const theta = Math.atan2(c.ny * h - cy, c.nx * w - cx);
    const d = (((beamAngle - theta) % TAU) + TAU) % TAU;
    return { c, d };
  });
  behind.sort((a, b) => a.d - b.d);
  behind.forEach(({ c, d }, i) => {
    c.e = i === 0 ? 0.95 : i === 1 ? 0.7 : Math.exp(-d * 1.6) * 0.35;
    c.rippleAge = 1; // no ripple in the still
  });
}

/** One frame. `useStatic` renders the frozen reduced-motion / paused pose. */
function draw(it: Internals, elapsed: number, useStatic: boolean) {
  const beamAngle = useStatic ? it.angle0 + STATIC_ANGLE : it.angle0 + it.omega * elapsed;

  if (useStatic) {
    poseStaticContacts(it, beamAngle);
  } else {
    if (!it.primed) {
      // Pre-excite as if the scope had been running — never a dark first frame.
      it.primed = true;
      const { width: w, height: h, cx, cy } = it;
      const safeOmega = Math.max(it.omega, 1e-3);
      for (const c of it.contactList) {
        const theta = Math.atan2(c.ny * h - cy, c.nx * w - cx);
        const d = (((beamAngle - theta) % TAU) + TAU) % TAU;
        c.e = Math.exp(-(d / safeOmega) / it.blipTau);
        c.rippleAge = 1;
        c.lastPass = Math.floor((beamAngle - theta) / TAU);
      }
    }
    const dt = Math.min(Math.max(elapsed - it.lastElapsed, 0), 0.1);
    updateContacts(it, beamAngle, dt, elapsed);
  }
  it.lastElapsed = elapsed;

  const ctx = it.fxCtx;
  ctx.clearRect(0, 0, it.width, it.height);
  drawSweep(it, beamAngle);
  drawBeamEdge(it, beamAngle);
  drawContacts(it, elapsed);
}

/**
 * Sonar — a phosphor radar scope. A rotating sweep beam drags a soft
 * angular-gradient afterglow over concentric range rings and faint azimuth
 * spokes; seeded contacts blip awake as the beam crosses them, bloom bright,
 * then decay until the next pass — drifting contacts leave breadcrumb tracks.
 * A `hud` knob adds the full instrument look (crosshair + range labels).
 * Canvas 2D: seeded and SSR-safe, paused offscreen and on hidden tabs,
 * DPR-clamped, reduced-motion-safe (beam frozen mid-sweep, two contacts lit).
 * Drop it inside any `relative` container.
 */
export function Sonar({
  colors = DEFAULT_COLORS,
  speed = 1,
  intensity = 1,
  period = 6,
  rings = 4,
  contacts = 8,
  persistence = 0.55,
  hud = false,
  seed = DEFAULT_SEED,
  dpr = 2,
  paused = false,
  className,
  style,
  ...props
}: SonarProps) {
  const gridRef = React.useRef<HTMLCanvasElement>(null);
  const fxRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();
  const staticFrame = paused || reducedMotion || speed <= 0;
  const staticFrameRef = React.useRef(staticFrame);
  staticFrameRef.current = staticFrame;

  const ringCount = Math.min(Math.max(Math.round(rings), 1), 12);
  const contactCount = Math.min(Math.max(Math.round(contacts), 0), 24);
  const clampedPeriod = Math.min(Math.max(period, 2), 60);
  const clampedPersistence = Math.min(Math.max(persistence, 0), 1);
  const clampedIntensity = Math.min(Math.max(intensity, 0), 2);
  const colorsKey = colors.join(",");

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it) return;
    draw(it, elapsed, staticFrameRef.current);
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: staticFrame });

  React.useEffect(() => {
    const gridCanvas = gridRef.current;
    const fxCanvas = fxRef.current;
    const container = containerRef.current;
    if (!gridCanvas || !fxCanvas || !container) return;

    const gridCtx = gridCanvas.getContext("2d", { alpha: false });
    const fxCtx = fxCanvas.getContext("2d");
    if (!gridCtx || !fxCtx) return;

    const effectiveDpr = Math.min(
      typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1,
      Math.min(Math.max(dpr, 1), 2)
    );

    const phosphor = hexToRgb(colors[0]);
    const bg = hexToRgb(colors[1]);
    const rand = mulberry32(seed >>> 0);
    const contactList: Contact[] = [];
    for (let i = 0; i < contactCount; i++) {
      const drifter = i % 3 === 2; // every third contact is underway
      const heading = rand() * TAU;
      const knots = 0.008 + rand() * 0.014; // normalized units / s — slow
      contactList.push({
        nx: 0.08 + rand() * 0.84,
        ny: 0.1 + rand() * 0.8,
        vx: drifter ? Math.cos(heading) * knots : 0,
        vy: drifter ? Math.sin(heading) * knots : 0,
        size: rand(),
        e: 0,
        lastPass: Number.NEGATIVE_INFINITY,
        rippleAge: 1,
        drifter,
        track: [],
      });
    }

    const speedMul = Math.max(speed, 0);
    const it: Internals = {
      gridCtx,
      fxCtx,
      width: 0,
      height: 0,
      cx: 0,
      cy: 0,
      rFull: 0,
      rIn: 0,
      radialMask: null,
      contactList,
      phosphor,
      bg,
      hot: mix(phosphor, [255, 255, 255], 0.55),
      omega: (TAU / clampedPeriod) * speedMul,
      trailFrac: 0.2 + clampedPersistence * 0.72,
      blipTau:
        (clampedPeriod / Math.max(speedMul, 0.05)) * (0.25 + 0.55 * clampedPersistence),
      intensity: clampedIntensity,
      rings: ringCount,
      hud,
      angle0: rand() * TAU,
      lastElapsed: 0,
      primed: false,
    };
    internalsRef.current = it;

    const resize = () => {
      const w = Math.max(container.clientWidth, 1);
      const h = Math.max(container.clientHeight, 1);
      for (const canvas of [gridCanvas, fxCanvas]) {
        canvas.width = Math.round(w * effectiveDpr);
        canvas.height = Math.round(h * effectiveDpr);
        canvas.style.width = "100%";
        canvas.style.height = "100%";
      }
      gridCtx.setTransform(effectiveDpr, 0, 0, effectiveDpr, 0, 0);
      fxCtx.setTransform(effectiveDpr, 0, 0, effectiveDpr, 0, 0);

      it.width = w;
      it.height = h;
      it.cx = w / 2;
      it.cy = h / 2;
      it.rFull = Math.hypot(w, h) / 2;
      it.rIn = (Math.min(w, h) / 2) * 0.92;

      const mask = fxCtx.createRadialGradient(it.cx, it.cy, 0, it.cx, it.cy, it.rFull);
      mask.addColorStop(0, "rgba(255,255,255,0)");
      mask.addColorStop(0.05, "rgba(255,255,255,0.9)");
      mask.addColorStop(0.35, "rgba(255,255,255,1)");
      mask.addColorStop(1, "rgba(255,255,255,0.12)");
      it.radialMask = mask;

      drawGrid(it);
      // Never flash empty — paint one sweep frame immediately.
      draw(it, it.lastElapsed, staticFrameRef.current);
    };

    const ro = new ResizeObserver(resize);
    ro.observe(container);
    resize();

    return () => {
      ro.disconnect();
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    dpr,
    colorsKey,
    speed,
    clampedIntensity,
    clampedPeriod,
    ringCount,
    contactCount,
    clampedPersistence,
    hud,
    seed,
  ]);

  // Re-pose the frozen frame in place when paused / reduced-motion toggles.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !staticFrame) return;
    draw(it, it.lastElapsed, true);
  }, [staticFrame]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="sonar"
      className={cn("absolute inset-0 -z-10 overflow-hidden", className)}
      style={{ backgroundColor: colors[1], ...style }}
      {...props}
    >
      <canvas ref={gridRef} className="absolute inset-0 block h-full w-full" />
      <canvas ref={fxRef} className="absolute inset-0 block h-full w-full" />
      {/* Soft vignette so the scope sinks into the frame edges. */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 120% at 50% 45%, transparent 60%, rgba(0,0,0,0.45) 100%)",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface StencilHandle {
  /** Wipe the paint, lay the plate back down and spray the headline again. */
  replay(): void;
}

export interface StencilProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children" | "color"
> {
  /** The headline (also rendered as a visually hidden heading for screen readers + SEO). @default "STENCIL" */
  text?: string;
  /** Element the visually hidden real text is rendered as, so it stays a heading. @default "h2" */
  as?: "h1" | "h2" | "h3" | "p";
  /** Spray paint color. @default "#f2f0eb" (off-white) */
  paint?: string;
  /** Stencil plate color — keep it a little lighter than the surface behind it. @default "#2a2b2f" (graphite) */
  plate?: string;
  /** Maximum glyph size in px; the headline scales down (and wraps to two lines) to fit. @default auto (~48% of the height) */
  fontSize?: number;
  /**
   * Canvas font stack. Any counters (the holes in O, A, B…) get stencil
   * bridges cut automatically, so plain bold fonts read as real stencils.
   * Web fonts are picked up once `document.fonts` is ready.
   * @default a bold condensed sans stack (Impact / Oswald / Arial Narrow…)
   */
  fontFamily?: string;
  /** Number of S-curve sweeps the can makes per line of text. 1–8. @default 3 */
  passes?: number;
  /** Paint runs that trickle 4–18px down from the letters' bottom edges during the intro. 0–16. @default 5 */
  drips?: number;
  /** Deterministic seed for the spray grain, sweep paths and drip spots. @default 7 */
  seed?: number;
  /** Imperative handle: `replay()`. */
  ref?: React.Ref<StencilHandle>;
}

const DEFAULT_FONT =
  '"Saira Stencil One", "Big Shoulders Stencil Display", Impact, Haettenschweiler, "Oswald", "Bebas Neue", "Arial Narrow Bold", "Arial Narrow", "Roboto Condensed", sans-serif';

const START = 0.3; // first sweep begins
const GAP = 0.07; // the can reverses between passes
const SETTLE = 0.4; // pause between the last pass and the plate lift
const LIFT_DUR = 1.05;
const OVERSPRAY = 0.22; // alpha of paint that creeps under the plate edge
const MAX_DRIPS = 40;

/** Deterministic mulberry32 PRNG. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));
const smooth = (a: number, b: number, v: number) => {
  const t = clamp((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
const easeOut = (u: number, p = 3) => 1 - Math.pow(1 - clamp(u, 0, 1), p);

interface Drip {
  x: number;
  y: number;
  len: number;
  w: number;
  start: number;
  dur: number;
  drawn: number;
}

interface Layout {
  w: number;
  h: number;
  dpr: number;
  fs: number;
  lines: number;
  /** CSS-px glyph mask (post-bridging). */
  mask: Uint8Array;
  /** Text block bounds (CSS px). */
  box: { x0: number; y0: number; x1: number; y1: number };
  /** Plate rect (CSS px). */
  plateRect: { x: number; y: number; w: number; h: number };
  /** Candidate drip origins — points on the letters' bottom edges. */
  edges: number[];
  maskC: HTMLCanvasElement;
  padSoftC: HTMLCanvasElement;
  padHardC: HTMLCanvasElement;
  plateC: HTMLCanvasElement;
  cutShadowC: HTMLCanvasElement;
  wordC: HTMLCanvasElement;
  platePaintC: HTMLCanvasElement;
  /** Fresh grain splats this frame. */
  freshC: HTMLCanvasElement;
  /** Fresh soft base coat this frame (kept out of the overspray so the halo stays speckled). */
  coatC: HTMLCanvasElement;
  dripFreshC: HTMLCanvasElement;
  tmpC: HTMLCanvasElement;
  blob: HTMLCanvasElement;
  /** Spray cone radius for the intro sweeps (CSS px). */
  R: number;
  passDur: number;
  passCount: number;
  sprayEnd: number;
  liftAt: number;
}

/**
 * Stencil — a headline spray-painted through a cut stencil plate. The glyphs
 * are rasterized into a mask (counters get stencil bridges cut automatically),
 * a graphite plate with those letters cut out sits over the surface, and an
 * off-screen can sweeps a few seeded S-curve passes, depositing thousands of
 * soft, grainy low-alpha splats: full strength inside the cutouts, a faint
 * overspray creeping under the plate edge, and the rest landing on the plate
 * itself. A few drips run down from the letters' bottom edges, then the plate
 * lifts away — shadow growing, fading out — revealing the crisp painted word.
 * Pointer drag sprays more paint locally (coats stack; lingering makes it
 * run). DPR-clamped, pauses offscreen/hidden; the real text ships as a
 * visually hidden heading; reduced motion shows the finished painted word.
 */
export function Stencil({
  text = "STENCIL",
  as = "h2",
  paint = "#f2f0eb",
  plate = "#2a2b2f",
  fontSize,
  fontFamily = DEFAULT_FONT,
  passes = 3,
  drips = 5,
  seed = 7,
  className,
  ref,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onKeyDown,
  ...props
}: StencilProps) {
  const Tag = as;
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const reducedMotion = useReducedMotion();
  const reducedRef = React.useRef(reducedMotion);
  React.useLayoutEffect(() => {
    reducedRef.current = reducedMotion;
  }, [reducedMotion]);

  const layoutRef = React.useRef<Layout | null>(null);
  const clockRef = React.useRef(0); // seconds since the intro (re)started
  const lastElapsedRef = React.useRef(0);
  const introDoneRef = React.useRef(false);
  const dripsRef = React.useRef<Drip[]>([]);
  const randRef = React.useRef(mulberry32(seed));
  const dirtyRef = React.useRef(true);
  const dragRef = React.useRef({
    active: false,
    id: -1,
    x: 0,
    y: 0,
    lx: 0,
    ly: 0,
    dwell: 0,
  });

  const passCount = clamp(Math.round(passes), 1, 8);
  const dripCount = clamp(Math.round(drips), 0, 16);

  // ---------------------------------------------------------------- painting
  /** Bind a context for drawing in CSS px. */
  const cssCtx = (c: HTMLCanvasElement, dpr: number) => {
    const ctx = c.getContext("2d")!;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return ctx;
  };

  /** Spray one burst of grainy splats + a soft base coat at (x, y) into the fresh layer. */
  const sprayAt = React.useCallback(
    (
      L: Layout,
      x: number,
      y: number,
      R: number,
      amount: number,
      rand: () => number,
    ) => {
      // Soft base coat — gives the coverage its smooth, misted body.
      const coat = cssCtx(L.coatC, L.dpr);
      // Jittered so repeated bursts on one spot never quantize into rings.
      coat.globalAlpha = 0.15 * Math.min(1, amount);
      const br = R * (0.85 + rand() * 0.3);
      const bx = x + (rand() - 0.5) * R * 0.35;
      const by = y + (rand() - 0.5) * R * 0.35;
      coat.drawImage(L.blob, bx - br, by - br, br * 2, br * 2);
      const ctx = cssCtx(L.freshC, L.dpr);
      // Grain — many tiny low-alpha dots in a gaussian cone.
      const n = Math.round(R * 0.75 * amount);
      const grain = clamp(L.fs / 110, 0.7, 1.6);
      ctx.fillStyle = paint;
      for (let i = 0; i < n; i++) {
        const r1 = Math.max(rand(), 1e-6);
        const mag = Math.sqrt(-2 * Math.log(r1)) * R * 0.42;
        const ang = rand() * Math.PI * 2;
        const px = x + Math.cos(ang) * mag;
        const py = y + Math.sin(ang) * mag;
        const s = grain * (0.45 + rand() * rand() * 1.9);
        ctx.globalAlpha = 0.14 + rand() * 0.42;
        if (s < 1.1) ctx.fillRect(px - s / 2, py - s / 2, s, s);
        else {
          ctx.beginPath();
          ctx.arc(px, py, s * 0.6, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
    },
    [paint],
  );

  /** Point on intro sweep `i` at progress u — alternating S-curves stacked down the text block. */
  const sweepPoint = (
    L: Layout,
    i: number,
    u: number,
    rand0: number,
  ): [number, number] => {
    const { x0, x1, y0, y1 } = L.box;
    const dir = i % 2 === 0 ? 1 : -1;
    const xa = x0 - L.R * 0.8;
    const xb = x1 + L.R * 0.8;
    const x = dir > 0 ? xa + (xb - xa) * u : xb - (xb - xa) * u;
    const band = (y1 - y0) / L.passCount;
    const yc = y0 + band * (i + 0.5);
    const amp = band * 0.5 + L.fs * 0.04;
    const y = yc + Math.sin(u * Math.PI * 2 + rand0 * 1.2 - 0.6) * amp * dir;
    return [x, y];
  };

  /** Spray the stretch of sweep `i` between progress u0 and u1. */
  const sprayAlong = React.useCallback(
    (L: Layout, i: number, u0: number, u1: number) => {
      if (u1 <= u0) return;
      const r0 = mulberry32(seed * 977 + i * 131)();
      const [ax, ay] = sweepPoint(L, i, u0, r0);
      const [bx, by] = sweepPoint(L, i, u1, r0);
      const steps = Math.max(1, Math.ceil(Math.hypot(bx - ax, by - ay) / 3));
      for (let s = 1; s <= steps; s++) {
        const u = u0 + ((u1 - u0) * s) / steps;
        const [x, y] = sweepPoint(L, i, u, r0);
        sprayAt(L, x, y, L.R, 1, randRef.current);
      }
    },
    [sprayAt, seed],
  );

  /** Extend every drip to its length at time t, drawing the new run into the drip layer. */
  const growDrips = React.useCallback(
    (L: Layout, t: number, instant: boolean) => {
      let any = false;
      const ctx = cssCtx(L.dripFreshC, L.dpr);
      ctx.fillStyle = paint;
      for (const d of dripsRef.current) {
        const p = instant ? 1 : easeOut((t - d.start) / d.dur, 2.4);
        const target = d.len * p;
        if (target <= d.drawn + 0.05) continue;
        any = true;
        for (let l = d.drawn; l <= target; l += 0.6) {
          const k = l / d.len;
          const r = d.w * (0.42 + 0.22 * k); // thickens toward the bead
          ctx.globalAlpha = 0.9;
          ctx.beginPath();
          ctx.arc(
            d.x + Math.sin(l * 0.35 + d.x) * 0.25,
            d.y + l,
            r,
            0,
            Math.PI * 2,
          );
          ctx.fill();
        }
        d.drawn = target;
        if (p >= 1) {
          ctx.beginPath();
          ctx.arc(d.x, d.y + d.len, d.w * 0.72, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
      return any;
    },
    [paint],
  );

  /** Route the fresh splats into the word (inside the cutouts + faint overspray) and onto the plate. */
  const flush = React.useCallback((L: Layout, overspray = OVERSPRAY) => {
    const tmp = L.tmpC.getContext("2d")!;
    const word = L.wordC.getContext("2d")!;
    const pp = L.platePaintC.getContext("2d")!;
    for (const c of [tmp, word, pp]) c.setTransform(1, 0, 0, 1, 0, 0);
    const pass = (
      src: HTMLCanvasElement,
      clip: HTMLCanvasElement,
      op: GlobalCompositeOperation,
    ) => {
      tmp.globalCompositeOperation = "copy";
      tmp.drawImage(src, 0, 0);
      tmp.globalCompositeOperation = op;
      tmp.drawImage(clip, 0, 0);
      tmp.globalCompositeOperation = "source-over";
    };
    // Overspray under the plate edge (soft padded mask, low alpha).
    pass(L.freshC, L.padSoftC, "destination-in");
    word.globalAlpha = overspray;
    word.drawImage(L.tmpC, 0, 0);
    word.globalAlpha = 1;
    // Full-strength paint through the cutouts.
    for (const src of [L.coatC, L.freshC]) {
      pass(src, L.maskC, "destination-in");
      word.drawImage(L.tmpC, 0, 0);
    }
    // Everything else lands on the plate.
    for (const src of [L.coatC, L.freshC]) {
      pass(src, L.plateC, "destination-in");
      pp.drawImage(L.tmpC, 0, 0);
    }
    // Drips may creep a few px past the cut edge.
    pass(L.dripFreshC, L.padHardC, "destination-in");
    word.drawImage(L.tmpC, 0, 0);
    for (const c of [L.freshC, L.coatC, L.dripFreshC]) {
      const ctx = c.getContext("2d")!;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, c.width, c.height);
    }
  }, []);

  /** Seed the intro drips on bottom edges of the letters. */
  const planDrips = React.useCallback(
    (L: Layout) => {
      const rand = mulberry32(seed * 313 + 17);
      const out: Drip[] = [];
      const minGap = L.fs * 0.3;
      const scale = clamp(L.fs / 120, 0.75, 1.5);
      let guard = 0;
      while (out.length < dripCount && L.edges.length && guard++ < 400) {
        const k = Math.floor(rand() * (L.edges.length / 2)) * 2;
        const x = L.edges[k];
        const y = L.edges[k + 1];
        if (out.some((d) => Math.abs(d.x - x) < minGap)) continue;
        const len = (4 + rand() * 14) * scale;
        out.push({
          x,
          y: y - L.fs * (0.02 + rand() * 0.05),
          len,
          w: (2 + rand() * 1.4) * scale,
          start: L.sprayEnd - 0.55 + out.length * 0.16 + rand() * 0.25,
          dur: 0.7 + (len / (18 * scale)) * 0.9,
          drawn: 0,
        });
      }
      dripsRef.current = out;
    },
    [seed, dripCount],
  );

  const clearPaint = (L: Layout) => {
    for (const c of [L.wordC, L.platePaintC, L.freshC, L.coatC, L.dripFreshC]) {
      const ctx = c.getContext("2d")!;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, c.width, c.height);
    }
  };

  /** Paint the finished word in one go (reduced motion, resize after the intro). */
  const paintInstant = React.useCallback(
    (L: Layout) => {
      clearPaint(L);
      randRef.current = mulberry32(seed);
      for (let i = 0; i < L.passCount; i++) sprayAlong(L, i, 0, 1);
      planDrips(L);
      growDrips(L, 0, true);
      flush(L);
    },
    [seed, sprayAlong, planDrips, growDrips, flush],
  );

  // ---------------------------------------------------------------- render
  const render = React.useCallback(() => {
    const canvas = canvasRef.current;
    const L = layoutRef.current;
    if (!canvas || !L) return;
    const ctx = canvas.getContext("2d")!;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(L.wordC, 0, 0);

    const t = clockRef.current;
    const lift =
      introDoneRef.current || reducedRef.current
        ? 1
        : clamp((t - L.liftAt) / LIFT_DUR, 0, 1);
    if (lift >= 1) return;
    // Unstick first (rise toward the viewer, shadow blooming), then pull away.
    const rise = smooth(0, 0.32, lift);
    const e = smooth(0.22, 1, lift);
    const alpha = 1 - smooth(0.35, 0.9, lift);

    // Plate thickness casts a hairline shadow into each cutout while it's down.
    ctx.globalAlpha = 1 - smooth(0, 0.25, lift);
    ctx.drawImage(L.cutShadowC, 0, 0);

    const { x, y, w, h } = L.plateRect;
    const cx = (x + w / 2) * L.dpr;
    const cy = (y + h / 2) * L.dpr;
    ctx.save();
    ctx.translate(cx + e * L.fs * 0.2, cy - e * (h * 0.6 + L.fs * 0.3));
    ctx.rotate(-0.05 * e);
    const sc = 1 + 0.025 * rise + 0.05 * e;
    ctx.scale(sc, sc);
    ctx.translate(-cx, -cy);
    ctx.globalAlpha = alpha;
    const lifted = Math.max(rise, e);
    ctx.shadowColor = `rgba(0,0,0,${0.6 * (1 - e * 0.5)})`;
    ctx.shadowBlur = (2 + 14 * rise + 22 * e) * L.dpr;
    ctx.shadowOffsetY = (1 + 8 * rise + 18 * e) * L.dpr;
    ctx.shadowOffsetX = -lifted * 6 * L.dpr;
    ctx.drawImage(L.plateC, 0, 0);
    ctx.shadowColor = "transparent";
    ctx.drawImage(L.platePaintC, 0, 0);
    ctx.restore();
    ctx.globalAlpha = 1;
  }, []);

  /** Pointer spray: interpolate along the stroke, and let paint build up (and run) where it lingers. */
  const sprayDrag = React.useCallback(
    (L: Layout, dt: number) => {
      const d = dragRef.current;
      const R = clamp(L.fs * 0.2, 14, 46);
      const dist = Math.hypot(d.x - d.lx, d.y - d.ly);
      const steps = Math.max(1, Math.ceil(dist / 4));
      const amount = clamp((dt * 60) / steps, 0.25, 1) * 0.55;
      for (let s = 1; s <= steps; s++) {
        const x = d.lx + ((d.x - d.lx) * s) / steps;
        const y = d.ly + ((d.y - d.ly) * s) / steps;
        sprayAt(L, x, y, R, amount, randRef.current);
      }
      d.lx = d.x;
      d.ly = d.y;
      if (reducedRef.current) return;
      // Lingering over a letter's bottom edge pools the paint into a fresh drip.
      d.dwell += dt * (dist < R * 0.5 ? 1 : 0.35);
      if (d.dwell > 0.75 && dripsRef.current.length < MAX_DRIPS) {
        d.dwell = 0;
        let best = -1;
        let bestD = R * 1.3;
        for (let k = 0; k < L.edges.length; k += 2) {
          const dd = Math.hypot(L.edges[k] - d.x, L.edges[k + 1] - d.y);
          if (
            dd < bestD &&
            !dripsRef.current.some((q) => Math.abs(q.x - L.edges[k]) < 4)
          ) {
            bestD = dd;
            best = k;
          }
        }
        if (best >= 0) {
          const rand = randRef.current;
          const scale = clamp(L.fs / 120, 0.75, 1.5);
          const len = (6 + rand() * 12) * scale;
          dripsRef.current.push({
            x: L.edges[best],
            y: L.edges[best + 1] - L.fs * 0.03,
            len,
            w: (1.4 + rand() * 1.2) * scale,
            start: clockRef.current,
            dur: 0.8 + (len / (18 * scale)) * 0.9,
            drawn: 0,
          });
        }
      }
    },
    [sprayAt],
  );

  // ---------------------------------------------------------------- loop
  const tick = React.useCallback(
    (elapsed: number) => {
      if (elapsed < lastElapsedRef.current) lastElapsedRef.current = elapsed;
      const dt = Math.min(elapsed - lastElapsedRef.current, 0.05);
      lastElapsedRef.current = elapsed;
      const L = layoutRef.current;
      if (!L || dt <= 0) return;

      const drag = dragRef.current;
      let changed = false;

      if (!introDoneRef.current) {
        const t0 = clockRef.current;
        const t1 = t0 + dt;
        clockRef.current = t1;
        // Intro sweeps overlapping (t0, t1].
        for (let i = 0; i < L.passCount; i++) {
          const ps = START + i * (L.passDur + GAP);
          const a = clamp((t0 - ps) / L.passDur, 0, 1);
          const b = clamp((t1 - ps) / L.passDur, 0, 1);
          if (b > a) {
            const ease = (v: number) => 0.5 - 0.5 * Math.cos(Math.PI * v);
            sprayAlong(L, i, ease(a), ease(b));
          }
        }
        if (
          t1 >= L.liftAt + LIFT_DUR &&
          dripsRef.current.every((d) => t1 >= d.start + d.dur)
        ) {
          introDoneRef.current = true;
        }
        changed = true;
      } else {
        clockRef.current += dt;
      }

      if (growDrips(L, clockRef.current, false)) changed = true;

      if (drag.active) {
        sprayDrag(L, dt);
        changed = true;
      }

      if (!changed && !dirtyRef.current) return;
      // With the plate gone, a hand-held can mists the surround more heavily.
      flush(L, drag.active && introDoneRef.current ? OVERSPRAY * 2 : OVERSPRAY);
      render();
      dirtyRef.current = false;
    },
    [sprayAlong, growDrips, sprayDrag, flush, render],
  );

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, {
    paused: reducedMotion,
  });

  // ---------------------------------------------------------------- layout
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;
    let cancelled = false;
    let lastW = 0;
    let lastH = 0;

    const build = (force: boolean) => {
      if (cancelled) return;
      const w = Math.max(container.clientWidth, 1);
      const h = Math.max(container.clientHeight, 1);
      if (!force && w === lastW && h === lastH) return;
      lastW = w;
      lastH = h;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const W = Math.round(w * dpr);
      const H = Math.round(h * dpr);
      canvas.width = W;
      canvas.height = H;

      const prev = layoutRef.current;
      const mk = (c?: HTMLCanvasElement) => {
        const el = c ?? document.createElement("canvas");
        el.width = W;
        el.height = H;
        return el;
      };
      const maskC = mk(prev?.maskC);
      const mctx = maskC.getContext("2d", { willReadFrequently: true });
      if (!mctx) return;

      // Fit: one line, or a balanced two-line wrap if that renders larger.
      const probe = 100;
      const font = (px: number) => `800 ${px}px ${fontFamily}`;
      const setSpacing = (px: number) => {
        if ("letterSpacing" in mctx) {
          (
            mctx as CanvasRenderingContext2D & { letterSpacing: string }
          ).letterSpacing = `${px}px`;
        }
      };
      mctx.setTransform(1, 0, 0, 1, 0, 0);
      mctx.clearRect(0, 0, W, H);
      mctx.font = font(probe);
      setSpacing(probe * 0.03);
      const target = fontSize ?? Math.min(h * 0.48, 200);
      const fit = (lines: string[]) => {
        const widest =
          Math.max(...lines.map((l) => mctx.measureText(l).width), 1) / probe;
        // Plate padding: 0.32em each side, 0.24em top/bottom.
        return Math.min(
          target,
          (w * 0.94) / (widest + 0.64),
          (h * 0.92) / (lines.length * 1.04 + 0.5),
        );
      };
      let lines = [text];
      let fs = fit(lines);
      const words = text.split(" ");
      if (words.length > 1) {
        let best: string[] | null = null;
        let bestDiff = Infinity;
        for (let i = 1; i < words.length; i++) {
          const a = words.slice(0, i).join(" ");
          const b = words.slice(i).join(" ");
          const diff = Math.abs(
            mctx.measureText(a).width - mctx.measureText(b).width,
          );
          if (diff < bestDiff) {
            bestDiff = diff;
            best = [a, b];
          }
        }
        if (best) {
          const fs2 = fit(best);
          if (fs2 > fs * 1.25) {
            lines = best;
            fs = fs2;
          }
        }
      }

      mctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      mctx.font = font(fs);
      setSpacing(fs * 0.03);
      mctx.textAlign = "center";
      mctx.textBaseline = "alphabetic";
      const m = mctx.measureText(lines.join(""));
      const ascent = m.actualBoundingBoxAscent || fs * 0.74;
      const descent = m.actualBoundingBoxDescent || fs * 0.04;
      const lh = fs * 1.04;
      const blockH = (lines.length - 1) * lh + ascent + descent;
      const top = (h - blockH) / 2;
      mctx.fillStyle = "#fff";
      let bx0 = w;
      let bx1 = 0;
      lines.forEach((line, i) => {
        // letterSpacing trails the last glyph — nudge back by half to stay centered.
        mctx.fillText(line, w / 2 + fs * 0.015, top + ascent + i * lh);
        const lw = mctx.measureText(line).width;
        bx0 = Math.min(bx0, w / 2 - lw / 2);
        bx1 = Math.max(bx1, w / 2 + lw / 2);
      });
      const box = { x0: bx0, y0: top, x1: bx1, y1: top + blockH };

      // CSS-px mask for bridging + drip spots.
      const readMask = () => {
        const data = mctx.getImageData(0, 0, W, H).data;
        const mask = new Uint8Array(w * h);
        for (let y = 0; y < h; y++) {
          const sy = Math.min(H - 1, Math.round((y + 0.5) * dpr - 0.5));
          for (let x = 0; x < w; x++) {
            const sx = Math.min(W - 1, Math.round((x + 0.5) * dpr - 0.5));
            mask[y * w + x] = data[(sy * W + sx) * 4 + 3] > 110 ? 1 : 0;
          }
        }
        return mask;
      };
      let mask = readMask();

      // Stencil bridges: any enclosed counter would fall out of a real plate,
      // so cut a tie above and below each one.
      {
        const N = w * h;
        const outside = new Uint8Array(N);
        const queue = new Int32Array(N);
        let qh = 0;
        let qt = 0;
        const push = (i: number) => {
          if (!mask[i] && !outside[i]) {
            outside[i] = 1;
            queue[qt++] = i;
          }
        };
        for (let x = 0; x < w; x++) {
          push(x);
          push((h - 1) * w + x);
        }
        for (let y = 0; y < h; y++) {
          push(y * w);
          push(y * w + w - 1);
        }
        while (qh < qt) {
          const i = queue[qh++];
          const x = i % w;
          if (x > 0) push(i - 1);
          if (x < w - 1) push(i + 1);
          if (i >= w) push(i - w);
          if (i < N - w) push(i + w);
        }
        const seen = new Uint8Array(N);
        const bw = Math.max(1.6, fs * 0.06);
        const minArea = Math.max(6, fs * fs * 0.0015);
        const strips: [number, number, number, number][] = [];
        for (let s = 0; s < N; s++) {
          if (mask[s] || outside[s] || seen[s]) continue;
          // Flood one counter.
          qh = 0;
          qt = 0;
          seen[s] = 1;
          queue[qt++] = s;
          let x0 = w;
          let x1 = 0;
          let y0 = h;
          let y1 = 0;
          let sumX = 0;
          while (qh < qt) {
            const i = queue[qh++];
            const x = i % w;
            const y = (i - x) / w;
            sumX += x;
            if (x < x0) x0 = x;
            if (x > x1) x1 = x;
            if (y < y0) y0 = y;
            if (y > y1) y1 = y;
            const nb = [
              x > 0 ? i - 1 : -1,
              x < w - 1 ? i + 1 : -1,
              i >= w ? i - w : -1,
              i < N - w ? i + w : -1,
            ];
            for (const j of nb) {
              if (j >= 0 && !mask[j] && !outside[j] && !seen[j]) {
                seen[j] = 1;
                queue[qt++] = j;
              }
            }
          }
          if (qt < minArea) continue;
          const cx = Math.round((sumX / qt + (x0 + x1) / 2) / 2);
          // Find the column's top-most counter pixel, then cut upward through ink.
          const colTop = (() => {
            for (let y = y0; y <= y1; y++)
              if (seen[y * w + cx] && !mask[y * w + cx]) return y;
            return y0;
          })();
          const colBot = (() => {
            for (let y = y1; y >= y0; y--)
              if (seen[y * w + cx] && !mask[y * w + cx]) return y;
            return y1;
          })();
          let y = colTop - 1;
          while (y > 0 && mask[y * w + cx]) y--;
          strips.push([cx - bw / 2, y, bw, colTop - y + 1]);
          y = colBot + 1;
          while (y < h - 1 && mask[y * w + cx]) y++;
          strips.push([cx - bw / 2, colBot, bw, y - colBot + 1]);
        }
        if (strips.length) {
          for (const [sx, sy, sw, sh] of strips) mctx.clearRect(sx, sy, sw, sh);
          mask = readMask();
        }
      }

      // Bottom-edge drip candidates.
      const edges: number[] = [];
      const stepX = Math.max(1, Math.round(fs * 0.02));
      for (
        let y = Math.max(1, Math.floor(box.y0));
        y < Math.min(h - 3, Math.ceil(box.y1) + 2);
        y++
      ) {
        for (let x = 1; x < w - 1; x += stepX) {
          const i = y * w + x;
          if (!(
            mask[i] &&
            mask[i - 1] &&
            mask[i + 1] &&
            !mask[i + w] &&
            !mask[i + 2 * w]
          ))
            continue;
          // Only the letters' true feet — no ink below in this column for half an em.
          let clear = true;
          for (let k = 2; k < fs * 0.9 && y + k < h; k++)
            if (mask[i + k * w]) clear = false;
          if (clear) edges.push(x, y);
        }
      }

      // Padded masks: hard (drips creep ~3px) and soft (overspray falloff).
      const stamp = (
        c: HTMLCanvasElement,
        radii: number[],
        alphas: number[],
      ) => {
        const ctx = c.getContext("2d")!;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, W, H);
        radii.forEach((r, ri) => {
          ctx.globalAlpha = alphas[ri];
          for (let a = 0; a < 12; a++) {
            const ang = (a / 12) * Math.PI * 2;
            ctx.drawImage(
              maskC,
              Math.cos(ang) * r * dpr,
              Math.sin(ang) * r * dpr,
            );
          }
        });
        ctx.globalAlpha = 1;
        ctx.drawImage(maskC, 0, 0);
      };
      const padHardC = mk(prev?.padHardC);
      stamp(padHardC, [1.5, 3], [1, 1]);
      const padSoftC = mk(prev?.padSoftC);
      const sr = clamp(fs * 0.055, 3, 10);
      stamp(padSoftC, [sr, sr * 0.66, sr * 0.33], [0.06, 0.1, 0.22]);

      // The plate: graphite with lighter edges, cut letters and two hanging holes.
      const padX = fs * 0.32;
      const padY = fs * 0.24;
      const plateRect = {
        x: box.x0 - padX,
        y: box.y0 - padY,
        w: box.x1 - box.x0 + padX * 2,
        h: box.y1 - box.y0 + padY * 2,
      };
      const plateC = mk(prev?.plateC);
      {
        const ctx = cssCtx(plateC, dpr);
        ctx.clearRect(0, 0, w, h);
        const { x, y, w: pw, h: ph } = plateRect;
        const rr = Math.min(8, fs * 0.06);
        const path = new Path2D();
        path.roundRect(x, y, pw, ph, rr);
        ctx.fillStyle = plate;
        ctx.fill(path);
        ctx.save();
        ctx.clip(path);
        const g = ctx.createLinearGradient(0, y, 0, y + ph);
        g.addColorStop(0, "rgba(255,255,255,0.07)");
        g.addColorStop(0.5, "rgba(255,255,255,0)");
        g.addColorStop(1, "rgba(0,0,0,0.18)");
        ctx.fillStyle = g;
        ctx.fillRect(x, y, pw, ph);
        // Milled-sheet speckle.
        const rand = mulberry32(seed * 53 + 3);
        const specks = Math.round((pw * ph) / 90);
        for (let i = 0; i < specks; i++) {
          ctx.fillStyle =
            rand() < 0.5 ? "rgba(255,255,255,0.035)" : "rgba(0,0,0,0.08)";
          ctx.fillRect(x + rand() * pw, y + rand() * ph, 1, 1);
        }
        // Lighter worn edges.
        ctx.lineWidth = 2;
        ctx.strokeStyle = "rgba(255,255,255,0.09)";
        ctx.stroke(path);
        ctx.restore();
        ctx.lineWidth = 1;
        ctx.strokeStyle = "rgba(255,255,255,0.14)";
        const inner = new Path2D();
        inner.roundRect(x + 0.5, y + 0.5, pw - 1, ph - 1, rr);
        ctx.stroke(inner);
        // Cut the letters (and two hanging holes) out of the sheet.
        ctx.globalCompositeOperation = "destination-out";
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.drawImage(maskC, 0, 0);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        const hr = clamp(fs * 0.035, 2, 6);
        for (const hx of [x + padX * 0.42, x + pw - padX * 0.42]) {
          ctx.beginPath();
          ctx.arc(hx, y + padY * 0.48, hr, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalCompositeOperation = "source-over";
      }
      // Cut-face rim: the plate's far edge of each cutout catches the light.
      const tmpC = mk(prev?.tmpC);
      {
        const t = tmpC.getContext("2d")!;
        t.setTransform(1, 0, 0, 1, 0, 0);
        t.globalCompositeOperation = "copy";
        t.drawImage(maskC, 1.2 * dpr, 1.2 * dpr);
        t.globalCompositeOperation = "destination-out";
        t.drawImage(maskC, 0, 0);
        t.globalCompositeOperation = "source-in";
        t.fillStyle = "rgba(255,255,255,0.2)";
        t.fillRect(0, 0, W, H);
        t.globalCompositeOperation = "source-over";
        const p = plateC.getContext("2d")!;
        p.setTransform(1, 0, 0, 1, 0, 0);
        p.globalCompositeOperation = "source-atop";
        p.drawImage(tmpC, 0, 0);
        p.globalCompositeOperation = "source-over";
      }
      // Plate thickness: hairline shadow inside each cutout's top-left edge.
      const cutShadowC = mk(prev?.cutShadowC);
      {
        const c = cutShadowC.getContext("2d")!;
        c.setTransform(1, 0, 0, 1, 0, 0);
        c.globalCompositeOperation = "copy";
        c.drawImage(maskC, 0, 0);
        c.globalCompositeOperation = "destination-out";
        c.drawImage(maskC, 2 * dpr, 2 * dpr);
        c.globalCompositeOperation = "source-in";
        c.fillStyle = "rgba(0,0,0,0.6)";
        c.fillRect(0, 0, W, H);
        c.globalCompositeOperation = "source-over";
      }

      // Soft spray sprite in the paint color.
      const blob = prev?.blob ?? document.createElement("canvas");
      blob.width = blob.height = 64;
      {
        const b = blob.getContext("2d")!;
        b.clearRect(0, 0, 64, 64);
        // Solid paint, alpha-shaped below — a color gradient to transparent
        // black would leave a dark fringe on every splat.
        b.fillStyle = paint;
        b.globalAlpha = 1;
        b.fillRect(0, 0, 64, 64);
        // Feather the core so the coat builds softly.
        b.globalCompositeOperation = "destination-in";
        const f = b.createRadialGradient(32, 32, 0, 32, 32, 32);
        f.addColorStop(0, "rgba(0,0,0,1)");
        f.addColorStop(0.5, "rgba(0,0,0,0.55)");
        f.addColorStop(1, "rgba(0,0,0,0)");
        b.fillStyle = f;
        b.fillRect(0, 0, 64, 64);
        b.globalCompositeOperation = "source-over";
      }

      const passTotal = passCount * lines.length;
      const R = Math.max(((box.y1 - box.y0) / passTotal) * 1.3, fs * 0.28);
      const passDur = clamp(0.5 + (box.x1 - box.x0) / 1500, 0.6, 1.05);
      const sprayEnd = START + passTotal * (passDur + GAP) - GAP;

      const L: Layout = {
        w,
        h,
        dpr,
        fs,
        lines: lines.length,
        mask,
        box,
        plateRect,
        edges,
        maskC,
        padSoftC,
        padHardC,
        plateC,
        cutShadowC,
        wordC: mk(prev?.wordC),
        platePaintC: mk(prev?.platePaintC),
        freshC: mk(prev?.freshC),
        coatC: mk(prev?.coatC),
        dripFreshC: mk(prev?.dripFreshC),
        tmpC,
        blob,
        R,
        passDur,
        passCount: passTotal,
        sprayEnd,
        liftAt: sprayEnd + SETTLE,
      };
      layoutRef.current = L;

      if (reducedRef.current || introDoneRef.current) {
        introDoneRef.current = true;
        paintInstant(L);
      } else {
        // (Re)start the intro against the new geometry.
        clearPaint(L);
        randRef.current = mulberry32(seed);
        clockRef.current = 0;
        planDrips(L);
      }
      dirtyRef.current = true;
      render();
    };

    const ro = new ResizeObserver(() => build(false));
    ro.observe(container);
    build(true);
    // Re-measure once web fonts land so the mask matches the final glyphs.
    document.fonts?.ready.then(() => build(true)).catch(() => {});

    return () => {
      cancelled = true;
      ro.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    text,
    fontSize,
    fontFamily,
    paint,
    plate,
    passCount,
    seed,
    paintInstant,
    planDrips,
    render,
  ]);

  // Reduced motion flipping on mid-intro: jump to the finished word.
  React.useEffect(() => {
    const L = layoutRef.current;
    if (!reducedMotion || !L || introDoneRef.current) return;
    introDoneRef.current = true;
    paintInstant(L);
    render();
  }, [reducedMotion, paintInstant, render]);

  const replay = React.useCallback(() => {
    const L = layoutRef.current;
    if (!L) return;
    if (reducedRef.current) {
      paintInstant(L);
      render();
      return;
    }
    clearPaint(L);
    randRef.current = mulberry32(seed);
    clockRef.current = 0;
    introDoneRef.current = false;
    planDrips(L);
    dirtyRef.current = true;
    render();
  }, [paintInstant, planDrips, render, seed]);

  React.useImperativeHandle(ref, () => ({ replay }), [replay]);

  // ---------------------------------------------------------------- input
  const local = (event: React.PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    return [event.clientX - rect.left, event.clientY - rect.top] as const;
  };

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event);
    if (event.defaultPrevented || event.button > 0) return;
    const [x, y] = local(event);
    event.currentTarget.setPointerCapture?.(event.pointerId);
    dragRef.current = {
      active: true,
      id: event.pointerId,
      x,
      y,
      lx: x,
      ly: y,
      dwell: 0,
    };
    if (reducedRef.current) {
      const L = layoutRef.current;
      if (!L) return;
      sprayDrag(L, 1 / 60);
      flush(L, OVERSPRAY * 2);
      render();
    }
  };

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    const d = dragRef.current;
    if (!d.active || d.id !== event.pointerId) return;
    const [x, y] = local(event);
    d.x = x;
    d.y = y;
    if (reducedRef.current) {
      const L = layoutRef.current;
      if (!L) return;
      sprayDrag(L, 1 / 60);
      flush(L, OVERSPRAY * 2);
      render();
    }
  };

  const endDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    if (dragRef.current.id === event.pointerId) dragRef.current.active = false;
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      replay();
    }
  };

  return (
    <div
      ref={containerRef}
      data-crucible="stencil"
      role="group"
      tabIndex={0}
      aria-roledescription="spray-painted headline"
      aria-label={`${text} — drag to add paint, press Enter to spray it again`}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(e) => {
        onPointerUp?.(e);
        endDrag(e);
      }}
      onPointerCancel={(e) => {
        onPointerCancel?.(e);
        endDrag(e);
      }}
      onKeyDown={handleKeyDown}
      className={cn(
        "relative block h-full min-h-40 w-full cursor-crosshair touch-none overflow-hidden rounded-md outline-none select-none focus-visible:ring-2 focus-visible:ring-white/40",
        className,
      )}
      {...props}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 h-full w-full"
      />
      {/* Real text for screen readers + SEO — the canvas is purely presentational. */}
      <Tag className="sr-only">{text}</Tag>
    </div>
  );
}

"use client";

import * as React from "react";
import { Mesh, Program, Renderer, Triangle } from "ogl";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";
import { clampDpr, useDprCap } from "@/hooks/use-dpr-cap";

export interface StrandProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Two tones: `[core, tail]`. `core` is the white-hot 1px filament center,
   * `tail` is the silver its glow cools into. Any hex string.
   * @default ["#fafafa", "#a3a3a3"]
   */
  colors?: [string, string];
  /**
   * Number of threads, clamped 2–64. A real uniform-driven prop — changing it
   * live-updates the shader without ever rebuilding the GL context.
   * @default 32
   */
  lineCount?: number;
  /**
   * How far the free middles bow and wander under noise. 1 = default drift,
   * 0 = perfectly taut threads. @default 1
   */
  amplitude?: number;
  /**
   * Vertical fan of the thread field as a fraction of the element height,
   * clamped 0–1.5. @default 1
   */
  spread?: number;
  /**
   * How strongly both ends of every thread pinch toward the two off-screen
   * loom anchors: 0 = parallel threads, 1 = full pinch. @default 0.6
   */
  convergence?: number;
  /** Drift speed multiplier. 1 = default. @default 1 */
  speed?: number;
  /** Overall glow brightness. 1 = default. @default 1 */
  intensity?: number;
  /**
   * Threads part around the cursor with a Gaussian bend that cascades from
   * near threads to far ones. @default true
   */
  interactive?: boolean;
  /** Radius of the cursor bend, as a fraction of the element height. @default 0.3 */
  bendRadius?: number;
  /** How far threads part around the cursor. 0 disables the bend. @default 1 */
  bendStrength?: number;
  /**
   * Idle autoplay: after ~1.5s with no real pointer over the field, a seeded
   * ghost cursor drifts through it on a slow Lissajous path, parting the
   * threads at a softer strength, so it never looks dead in thumbnails and
   * heroes. The real pointer takes over instantly. Only when `interactive`;
   * never under reduced motion. @default true
   */
  idle?: boolean;
  /** Freeze the animation, holding the current frame. @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: [string, string] = [
  "#fafafa", // white — hot filament core
  "#a3a3a3", // neutral-400 silver — glow tail
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.98, 0.98, 0.98];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Original converging-thread-field fragment shader. N filaments are evaluated
 * analytically per pixel: each thread's ends pin toward two off-screen loom
 * anchors (left and right) while its free middle bows and wanders under one
 * value-noise eval plus a cheap trig detail term riding on it — threads under
 * uneven tension. Rendering is a 1/|d| neon profile per thread (white-hot
 * ~1px core, long soft silver falloff — the glow doubles as free bloom),
 * accumulated and squashed through an exponential tone curve so crossings
 * bloom instead of clipping. The cursor parts the field with a Gaussian bend
 * gated by an eased 0→1 influence scalar, staggered per line so near threads
 * respond first and the release cascades back out. Grain dithering defeats
 * 8-bit banding in the glow. GLSL ES 1.00 (WebGL1/2 compatible).
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;     // eased pointer, 0..1, y-up
uniform float uSeed;       // per-instance time offset — desyncs multiple instances
uniform float uInfluence;  // eased 0..1 cursor-influence scalar

uniform vec3 uColorCore;   // white-hot filament center
uniform vec3 uColorTail;   // silver glow tail
uniform float uLineCount;
uniform float uAmplitude;
uniform float uSpread;
uniform float uConvergence;
uniform float uSpeed;
uniform float uIntensity;
uniform float uBendRadius;
uniform float uBendStrength;

const int MAX_LINES = 64;
const float PI = 3.14159265359;

float hash11(float n) {
  return fract(sin(n * 127.1 + 0.7) * 43758.5453123);
}

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = (uTime + uSeed) * uSpeed;
  float count = clamp(uLineCount, 2.0, float(MAX_LINES));

  // Loom anchors sit beyond both screen edges; tx is the position along the
  // extended span between them. pinch peaks mid-screen and shrinks toward the
  // anchors, so at convergence 1 the fan pinches fully just off-screen.
  float margin = 0.22;
  float tx = (uv.x + margin) / (1.0 + 2.0 * margin);
  float pinch = sin(PI * tx);
  float profile = mix(1.0, pinch, clamp(uConvergence, 0.0, 1.0));
  // Wander envelope: anchored ends, free middles — even at convergence 0 the
  // threads stay pinned at the loom and billow through the center.
  float freeMid = pow(pinch, 0.85);

  float bend2 = max(uBendRadius * uBendRadius, 1e-4);
  // Hot-core width in buffer pixels, gently tracking element size.
  float coreW = clamp(uResolution.y / 900.0, 0.75, 1.6);

  vec3 acc = vec3(0.0);
  for (int i = 0; i < MAX_LINES; i++) {
    if (float(i) >= count) break;
    float fi = float(i);
    float h1 = hash11(fi * 1.618 + 0.71);
    float h2 = hash11(fi * 2.317 + 4.30);
    float h3 = hash11(fi * 3.113 + 9.20);

    // Lane (evenly spaced, seeded jitter) and shuffled depth so near and far
    // threads interleave instead of sorting top-to-bottom.
    float lane = (fi + 0.5) / count - 0.5 + (h1 - 0.5) * (0.5 / count);
    float depth = h2; // 0 near .. 1 far

    // Per-line clock: each thread drifts at its own rate and phase.
    float lt = t * mix(0.7, 1.25, h3) + h1 * 43.0;

    // Wander: ONE noise eval per line, plus a cheap trig detail term whose
    // phase is modulated by the noise so it never reads as a comb.
    float n = vnoise(vec2(uv.x * aspect * 1.35 + h1 * 89.0, lt * 0.11)) - 0.5;
    float detail = sin(uv.x * aspect * 9.0 + h2 * 61.0 + lt * 0.35 + n * 5.0);
    float amp = uAmplitude * 0.16 * freeMid * mix(1.0, 0.5, depth) * mix(0.75, 1.2, h3);
    float yc = 0.5 + lane * clamp(uSpread, 0.0, 1.5) * 0.96 * profile
             + (n * 2.0 + detail * 0.22) * amp;

    // Cursor bend: Gaussian part, gated by the eased influence scalar with a
    // per-line stagger — threads nearer the cursor's lane engage first, and on
    // leave the release cascades back out through the field.
    float stagger = clamp(abs(yc - uPointer.y) * 1.5, 0.0, 0.7);
    float lineInf = smoothstep(stagger, stagger + 0.3, uInfluence);
    float dx = (uv.x - uPointer.x) * aspect;
    float dy = yc - uPointer.y;
    float gauss = exp(-(dx * dx + dy * dy) / bend2);
    yc += uBendStrength * lineInf * dy * gauss * 1.7;

    // 1/|d| neon glow: hot ~1px core with a long soft falloff — the falloff
    // IS the bloom, no extra passes.
    float dpx = abs(uv.y - yc) * uResolution.y;
    float w = mix(1.8, 1.0, depth) * coreW;
    float g = w / (dpx + w);

    // Depth-faded silver with a slow shimmer breathing along each thread, and
    // a gentle lift where the cursor holds the field open.
    float bright = mix(1.0, 0.15, depth);
    bright *= 0.82 + 0.18 * sin(lt * 0.9 + uv.x * aspect * 6.0 + h2 * 20.0);
    bright *= 1.0 + 0.6 * lineInf * gauss;

    acc += mix(uColorTail, uColorCore, pow(g, 3.0)) * (g * bright);
  }

  // Squash the accumulated glow — crossings bloom and roll off, never clip.
  vec3 threads = 1.0 - exp(-acc * 1.25 * uIntensity);

  // Near-black plate with a faint cool lift toward the base.
  vec3 col = mix(vec3(0.010, 0.011, 0.014), vec3(0.026, 0.028, 0.034),
                 pow(1.0 - uv.y, 1.5));
  col += threads;

  // Vignette sinks the frame edges; grain dither defeats 8-bit banding.
  vec2 vg = (uv - 0.5) * vec2(aspect, 1.0);
  col *= 1.0 - 0.30 * dot(vg, vg);
  float grain = hash21(gl_FragCoord.xy + fract(t) * 137.0) - 0.5;
  col += grain * (1.8 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

const VERTEX = /* glsl */ `
precision highp float;
attribute vec2 position;
attribute vec2 uv;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

interface Uniform<T> {
  value: T;
}

interface Internals {
  renderer: Renderer;
  mesh: Mesh;
  program: Program;
  uTime: Uniform<number>;
  uSeed: Uniform<number>;
  uInfluence: Uniform<number>;
  uResolution: Uniform<[number, number]>;
  uPointer: Uniform<[number, number]>;
  seed: number;
  loseContext: (() => void) | null;
}

/** OGL early-returns on a failed link without creating uniformLocations. */
function programLinked(program: Program): boolean {
  return (program as unknown as { uniformLocations?: unknown }).uniformLocations !== undefined;
}

const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi);

/** Longest edge of the drawing buffer — larger elements upscale imperceptibly. */
const MAX_RENDER_DIMENSION = 1920;

/** uTime for the reduced-motion still: threads gracefully bowed mid-drift. */
const REDUCED_TIME = 6.0;

/** Ghost takes over this long (ms) after the last real pointer activity. */
const GHOST_DELAY_MS = 1500;
/** Ghost bend strength relative to a real pointer. */
const GHOST_PRESENCE = 0.75;

/** Deterministic per-instance time offset so multiple instances desynchronize. */
let instanceCounter = 0;

/**
 * Strand — a converging thread field. Silver filaments strung between two
 * off-screen loom anchors: ends pinned, free middles bowing and wandering
 * under noise like threads held at uneven tension. Each thread renders as a
 * 1/|d| neon glow — white-hot 1px core, long soft silver falloff — depth-faded
 * so near threads burn bright over a dim far weave. The cursor parts the
 * field with a Gaussian bend that eases in and out (never pops) and cascades
 * from near threads to far ones.
 *
 * Original OGL fragment shader on a fullscreen triangle: mounted once with
 * every knob a live uniform, DPR ≤2 with a 1920px max-render-dimension cap,
 * offscreen- and hidden-tab-paused, reduced-motion-safe (a frozen mid-drift
 * still), full WebGL teardown on unmount, fails soft on lost context. Drop it
 * inside any `relative` container; it fills and sits behind content.
 */
export function Strand({
  colors = DEFAULT_COLORS,
  lineCount = 32,
  amplitude = 1,
  spread = 1,
  convergence = 0.6,
  speed = 1,
  intensity = 1,
  interactive = true,
  bendRadius = 0.3,
  bendStrength = 1,
  idle = true,
  paused = false,
  className,
  ...props
}: StrandProps) {
  const internalsRef = React.useRef<Internals | null>(null);
  const [ready, setReady] = React.useState(false);
  const [failed, setFailed] = React.useState(false);

  const reducedMotion = useReducedMotion();

  // Live mirrors read inside the RAF loop without re-subscribing it.
  const interactiveRef = React.useRef(interactive);
  interactiveRef.current = interactive;
  const idleRef = React.useRef(idle);
  idleRef.current = idle;
  // performance.now() of the last real pointer activity; -Infinity = never.
  const lastRealPointerRef = React.useRef(-Infinity);
  const insideRef = React.useRef(false);

  // Pointer + influence integration state.
  const pointerRef = React.useRef<[number, number]>([0.5, 0.5]);
  const pointerTargetRef = React.useRef<[number, number]>([0.5, 0.5]);
  const influenceRef = React.useRef(0);
  const influenceTargetRef = React.useRef(0);
  const lastElapsedRef = React.useRef(0);

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it || !programLinked(it.program)) return;

    // useVisibilityPause restarts `elapsed` at 0 whenever its `paused` option
    // flips; re-seat so the first frame after a resume steps by 0, not backwards.
    if (elapsed < lastElapsedRef.current) lastElapsedRef.current = elapsed;
    let dt = elapsed - lastElapsedRef.current;
    lastElapsedRef.current = elapsed;
    if (dt < 0) dt = 0;
    if (dt > 0.05) dt = 0.05; // clamp jumps after a pause/tab-switch

    // Idle ghost: a slow seeded Lissajous cursor while nobody is over the field.
    const pt = pointerTargetRef.current;
    if (
      interactiveRef.current &&
      idleRef.current &&
      !insideRef.current &&
      performance.now() - lastRealPointerRef.current > GHOST_DELAY_MS
    ) {
      const gt = elapsed + it.seed;
      pt[0] = 0.5 + 0.34 * Math.sin(gt * 0.27) * Math.cos(gt * 0.083);
      pt[1] = 0.5 + 0.22 * Math.sin(gt * 0.19 + 1.3);
      influenceTargetRef.current = GHOST_PRESENCE;
    }

    // Frame-rate-independent pointer damping (exponential time constant).
    const pc = pointerRef.current;
    const pe = 1 - Math.exp(-7 * dt);
    pc[0] += (pt[0] - pc[0]) * pe;
    pc[1] += (pt[1] - pc[1]) * pe;

    // Eased 0→1 influence scalar — quicker to engage than to let go, so the
    // bend fades in and out instead of popping.
    const target = interactiveRef.current ? influenceTargetRef.current : 0;
    const cur = influenceRef.current;
    const k = target > cur ? 5 : 2.4;
    influenceRef.current = cur + (target - cur) * (1 - Math.exp(-k * dt));

    it.uTime.value = elapsed;
    it.uInfluence.value = influenceRef.current;
    it.uPointer.value[0] = pc[0];
    it.uPointer.value[1] = pc[1];
    it.renderer.render({ scene: it.mesh });
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, {
    paused: paused || reducedMotion,
  });

  // Host-imposed DPR ceiling (galleries of thumbnails cap fill rate).
  const dprCap = useDprCap();

  // ---- setup / teardown (mount once; every knob is a live uniform) ----
  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Fresh canvas per mount: a canvas whose context was killed via
    // WEBGL_lose_context (our teardown) can only ever return that dead
    // context again — StrictMode's double-mount would come back black.
    const canvas = document.createElement("canvas");
    canvas.setAttribute("aria-hidden", "true");
    canvas.className = "absolute inset-0 block h-full w-full";
    container.appendChild(canvas);

    const baseDpr = clampDpr(dprCap, 2);

    let renderer: Renderer;
    let gl: Renderer["gl"];
    try {
      renderer = new Renderer({
        canvas,
        dpr: baseDpr,
        alpha: true,
        antialias: false, // fullscreen fragment pass — MSAA buys nothing
        premultipliedAlpha: false,
      });
      gl = renderer.gl;
      gl.clearColor(0, 0, 0, 0);
    } catch (err) {
      console.warn("[crucible] WebGL unavailable — rendering static fallback.", err);
      canvas.remove();
      setFailed(true);
      return;
    }

    const onContextLost = (e: Event) => {
      e.preventDefault();
      setFailed(true);
    };
    canvas.addEventListener("webglcontextlost", onContextLost);

    const seed = (instanceCounter++ % 64) * 5.3;

    const uTime: Uniform<number> = { value: 0 };
    const uSeed: Uniform<number> = { value: seed };
    const uInfluence: Uniform<number> = { value: 0 };
    const uResolution: Uniform<[number, number]> = {
      value: [gl.drawingBufferWidth || 1, gl.drawingBufferHeight || 1],
    };
    const uPointer: Uniform<[number, number]> = { value: [0.5, 0.5] };

    const program = new Program(gl, {
      vertex: VERTEX,
      fragment: FRAGMENT,
      uniforms: {
        uTime,
        uSeed,
        uInfluence,
        uResolution,
        uPointer,
        uColorCore: { value: hexToRgb(colors[0]) },
        uColorTail: { value: hexToRgb(colors[1]) },
        uLineCount: { value: clamp(Math.round(lineCount), 2, 64) },
        uAmplitude: { value: Math.max(amplitude, 0) },
        uSpread: { value: clamp(spread, 0, 1.5) },
        uConvergence: { value: clamp(convergence, 0, 1) },
        uSpeed: { value: Math.max(speed, 0) },
        uIntensity: { value: Math.max(intensity, 0) },
        uBendRadius: { value: clamp(bendRadius, 0.05, 1) },
        uBendStrength: { value: Math.max(bendStrength, 0) },
      },
    });

    const geometry = new Triangle(gl);
    const mesh = new Mesh(gl, { geometry, program });

    const loseExt = gl.getExtension("WEBGL_lose_context");

    const internals: Internals = {
      renderer,
      mesh,
      program,
      uTime,
      uSeed,
      uInfluence,
      uResolution,
      uPointer,
      seed,
      loseContext: loseExt ? () => loseExt.loseContext() : null,
    };
    internalsRef.current = internals;

    const resize = () => {
      const { clientWidth: w, clientHeight: h } = container;
      // DPR ≤2 plus a max-render-dimension cap: huge elements render at most
      // 1920px on their longest edge and upscale imperceptibly.
      const longest = Math.max(w, h, 1) * baseDpr;
      renderer.dpr =
        longest > MAX_RENDER_DIMENSION
          ? baseDpr * (MAX_RENDER_DIMENSION / longest)
          : baseDpr;
      renderer.setSize(Math.max(w, 1), Math.max(h, 1));
      uResolution.value[0] = gl.drawingBufferWidth;
      uResolution.value[1] = gl.drawingBufferHeight;
      // Keep the frame correct even while the loop is idle (paused/reduced).
      if (programLinked(program)) renderer.render({ scene: mesh });
    };

    const ro = new ResizeObserver(resize);
    ro.observe(container);
    resize();

    const onPointerMove = (e: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return;
      pointerTargetRef.current[0] = (e.clientX - rect.left) / rect.width;
      // Flip Y so "up" on screen is 1.
      pointerTargetRef.current[1] = 1 - (e.clientY - rect.top) / rect.height;
      influenceTargetRef.current = 1;
      insideRef.current = true;
      lastRealPointerRef.current = performance.now();
    };
    const onPointerLeave = () => {
      // Keep the last pointer position — the influence scalar fades the bend
      // out in place instead of dragging threads back through center.
      influenceTargetRef.current = 0;
      insideRef.current = false;
      // The ghost resumes after the usual delay rather than snapping in.
      lastRealPointerRef.current = performance.now();
    };

    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerleave", onPointerLeave);
    container.addEventListener("pointercancel", onPointerLeave);

    setReady(true);

    return () => {
      setReady(false);
      internalsRef.current = null;
      ro.disconnect();
      canvas.removeEventListener("webglcontextlost", onContextLost);
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
      container.removeEventListener("pointercancel", onPointerLeave);
      internals.loseContext?.();
      canvas.remove();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dprCap]);

  // ---- live-sync knob uniforms in place; re-render if the loop is idle ----
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !programLinked(it.program)) return;
    const u = it.program.uniforms;
    u.uColorCore.value = hexToRgb(colors[0]);
    u.uColorTail.value = hexToRgb(colors[1]);
    u.uLineCount.value = clamp(Math.round(lineCount), 2, 64);
    u.uAmplitude.value = Math.max(amplitude, 0);
    u.uSpread.value = clamp(spread, 0, 1.5);
    u.uConvergence.value = clamp(convergence, 0, 1);
    u.uSpeed.value = Math.max(speed, 0);
    u.uIntensity.value = Math.max(intensity, 0);
    u.uBendRadius.value = clamp(bendRadius, 0.05, 1);
    u.uBendStrength.value = Math.max(bendStrength, 0);
    if (paused || reducedMotion) it.renderer.render({ scene: it.mesh });
  });

  // ---- designed still under reduced motion; hold frame when paused ----
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !ready || !programLinked(it.program)) return;
    if (reducedMotion) {
      // A composed mid-drift frame: threads gracefully bowed, interaction off.
      // Seed zeroed so the still is the same designed frame on every instance.
      it.uTime.value = REDUCED_TIME;
      it.uSeed.value = 0;
      it.uInfluence.value = 0;
      it.uPointer.value[0] = 0.5;
      it.uPointer.value[1] = 0.5;
      influenceRef.current = 0;
      influenceTargetRef.current = 0;
      it.renderer.render({ scene: it.mesh });
    } else {
      it.uSeed.value = it.seed;
      if (paused) it.renderer.render({ scene: it.mesh });
    }
  }, [reducedMotion, paused, ready]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="strand"
      className={cn(
        "absolute inset-0 -z-10 block overflow-hidden bg-neutral-950",
        className
      )}
      {...props}
    >
      {failed && (
        <div
          aria-hidden
          className="absolute inset-0"
          style={{
            background:
              "linear-gradient(178deg, transparent 44%, rgba(250,250,250,0.10) 49%, transparent 50%, transparent 58%, rgba(163,163,163,0.08) 63%, transparent 64%)",
          }}
        />
      )}
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface StippleProps {
  /**
   * Duotone pair `[paper, ink]`: the dark paper tone and the light ink laid
   * over it. Any hex strings. Defaults to risograph sepia — warm cream ink
   * on near-black paper.
   */
  colors?: [string, string];
  /** Dither cell size in canvas pixels — bigger is chunkier. Clamped 2–16. Default 4. */
  pixelSize?: number;
  /** Quantization steps between the two inks. Clamped 2–8. Default 4. */
  levels?: number;
  /** Drift speed multiplier. 1 = default. */
  speed?: number;
  /** Contrast / ink coverage of the underlying field. 1 = default. */
  intensity?: number;
  /**
   * Idle autoplay: after ~1.5s with no real pointer, a seeded ghost pointer
   * bends the waves on a slow drift so it never looks dead in thumbnails and
   * heroes; the real pointer takes over instantly. Never runs under reduced
   * motion. @default true
   */
  idle?: boolean;
  /** Freeze the animation, holding the current frame. */
  paused?: boolean;
  /** Extra classes for the wrapper. Positioned `absolute inset-0 -z-10`. */
  className?: string;
}

const DEFAULT_COLORS: [string, string] = [
  "#181310", // near-black warm paper
  "#e0cba4", // sepia-cream ink
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.88, 0.8, 0.64];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Ordered-dither fragment shader. A drifting fbm field is sampled once per
 * dither cell, quantized to a small number of levels, and the banding is
 * broken by an 8x8 Bayer threshold matrix — the classic retro print
 * pipeline, with the dither itself as the aesthetic. A second quantize pass
 * drifts half a cell out of register on a very slow cycle, like a print
 * pass slipping. GLSL ES 1.00.
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive; // eased 0..1 pointer (or ghost) presence

uniform vec3 uPaper;
uniform vec3 uInk;
uniform float uPixelSize;
uniform float uLevels;
uniform float uSpeed;
uniform float uIntensity;

// --- compact value noise + fbm (original) ---
float hash21(vec2 p) {
  p = fract(p * vec2(217.13, 373.41));
  p += dot(p, p + 31.73);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  mat2 m = mat2(1.7, 1.1, -1.1, 1.7);
  for (int i = 0; i < 4; i++) {
    v += amp * vnoise(p);
    p = m * p;
    amp *= 0.5;
  }
  return v;
}

// 8x8 Bayer threshold, computed recursively rather than tabled -- GLSL ES
// 1.00 has no constant array initializers. Base 2x2 pattern: 0 2 / 3 1,
// with the least-significant cell bits carrying the largest weights.
float bayer8(vec2 cell) {
  vec2 q = floor(mod(cell, 8.0));
  float v = 0.0;
  float w = 16.0;
  for (int i = 0; i < 3; i++) {
    vec2 h = mod(q, 2.0);
    v += (2.0 * h.x + 3.0 * h.y - 4.0 * h.x * h.y) * w;
    q = floor(q * 0.5);
    w *= 0.25;
  }
  return (v + 0.5) / 64.0;
}

// The continuous field under the dither: two drifting fbm layers, a soft
// lift where the waves bend toward the pointer, a settling vignette, then
// contrast around the midtone.
float field(vec2 uv, float aspect, float t) {
  vec2 p = vec2(uv.x * aspect, uv.y) * 2.6;
  float f = fbm(p + vec2(t * 0.11, -t * 0.05));
  f += 0.4 * fbm(p * 2.3 + vec2(-t * 0.04, t * 0.08));
  f /= 1.4;

  // Pointer lift position scales with presence, settling home when nobody is there.
  vec2 ptr = mix(vec2(0.5), uPointer, uPointerActive);
  vec2 pd = vec2((uv.x - ptr.x) * aspect, uv.y - ptr.y);
  f += exp(-dot(pd, pd) * 9.0) * 0.2;

  vec2 vg = (uv - 0.5) * vec2(aspect, 1.0);
  f -= 0.22 * dot(vg, vg);

  return 0.5 + (f - 0.5) * (0.9 * uIntensity + 0.35);
}

float quantize(float f, float levels, float b) {
  return clamp(floor(f * (levels - 1.0) + b) / (levels - 1.0), 0.0, 1.0);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = uTime * uSpeed;
  float px = clamp(uPixelSize, 2.0, 16.0);

  // One field sample per dither cell keeps the pattern legibly crafted.
  vec2 cell = floor(gl_FragCoord.xy / px);
  vec2 cuv = (cell + 0.5) * px / uResolution;

  float levels = clamp(uLevels, 2.0, 8.0);
  float b = bayer8(cell);

  float q = quantize(field(cuv, aspect, t), levels, b);

  // Misregistered second pass: the light ink drifts half a cell out of
  // register on a very slow cycle, like a print pass slipping.
  vec2 reg = (px * 0.5 / uResolution) * vec2(sin(t * 0.07), cos(t * 0.057));
  float q2 = quantize(field(cuv + reg, aspect, t), levels, b);

  vec3 col = mix(uPaper, uInk, q);
  float hi = step(1.0 - 0.5 / (levels - 1.0), q2);
  col = mix(col, uInk, hi * 0.22);

  gl_FragColor = vec4(col, 1.0);
}
`;

/**
 * Stipple — an ordered-dither shader field. A slowly drifting noise field is
 * crushed to a handful of levels and rendered through an 8x8 Bayer matrix at
 * a chunky, controllable cell size: living newsprint in risograph sepia
 * duotone, with a light ink that slips a half-cell out of register on a slow
 * cycle. The waves bend toward the pointer. Built on the `ogl-canvas`
 * harness: GPU-light, offscreen-paused, reduced-motion-safe. Drop it inside
 * any `relative` container; it fills and sits behind content.
 */
export function Stipple({
  colors = DEFAULT_COLORS,
  pixelSize = 4,
  levels = 4,
  speed = 1,
  intensity = 1,
  paused = false,
  idle = true,
  className,
}: StippleProps) {
  const uniforms = React.useMemo(
    () => ({
      uPaper: { value: hexToRgb(colors[0]) },
      uInk: { value: hexToRgb(colors[1]) },
      uPixelSize: { value: pixelSize },
      uLevels: { value: levels },
      uSpeed: { value: speed },
      uIntensity: { value: intensity },
    }),
    [colors, pixelSize, levels, speed, intensity]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="stipple"
      // DPR locked to 1 so a dither cell is a true pixel block, with
      // image-rendering: pixelated keeping the upscale crisp on hidpi.
      className={cn(
        "absolute inset-0 -z-10 [&_canvas]:[image-rendering:pixelated]",
        className
      )}
      fragment={FRAGMENT}
      uniforms={uniforms}
      dpr={1}
      reducedMotionTime={6}
      paused={paused}
      ghost={idle}
    />
  );
}

"use client";

import { motion, type HTMLMotionProps, type TargetAndTransition, type Variants } from "motion/react";
import * as React from "react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cn } from "@/lib/utils";

export interface SurfaceProps
  extends Omit<HTMLMotionProps<"div">, "children" | "initial" | "whileInView" | "viewport" | "transition"> {
  /** Content to reveal. Each top-level child animates as its own staggered item. */
  children: React.ReactNode;
  /**
   * Named entrance treatment. `melt` is the Crucible signature: rise + blur +
   * a soft under-glow, like the element is surfacing out of the dark.
   * @default "melt"
   */
  preset?: "melt" | "fade" | "slide" | "scale" | "blur";
  /** Travel direction for `melt`/`slide`. @default "up" */
  direction?: "up" | "down" | "left" | "right";
  /** Travel distance in px for `melt`/`slide`. @default 12 */
  distance?: number;
  /** Starting blur radius in px for `melt`/`blur`. @default 8 */
  blur?: number;
  /** Starting scale for `scale`. @default 0.94 */
  scaleFrom?: number;
  /** Seconds each item takes to settle. @default 0.6 */
  duration?: number;
  /** Seconds between each top-level child's reveal. @default 0.08 */
  stagger?: number;
  /** Seconds before the first item starts. @default 0 */
  delay?: number;
  /** Re-trigger every time it scrolls into view instead of once. @default false */
  repeat?: boolean;
  /** Fraction of the element that must be visible to trigger. @default 0.4 */
  amount?: number;
  /** `viewport.margin`-style rootMargin, e.g. to trigger before entry. @default "0px 0px -10% 0px" */
  margin?: NonNullable<HTMLMotionProps<"div">["viewport"]>["margin"];
  /**
   * Scroll container to observe instead of the browser viewport. Pass a ref to
   * an `overflow`-scrolling ancestor so the reveal triggers as content scrolls
   * within THAT container (e.g. inside a boxed panel). @default the viewport
   */
  root?: React.RefObject<Element | null>;
  /** Show the under-glow (only rendered for `preset="melt"`). @default true */
  ember?: boolean;
  /** Glow color for the `melt` under-glow. @default "#ffffff" (soft white) */
  emberColor?: string;
}

function buildItemVariants(opts: {
  preset: SurfaceProps["preset"];
  direction: NonNullable<SurfaceProps["direction"]>;
  distance: number;
  blur: number;
  scaleFrom: number;
  duration: number;
  reducedMotion: boolean;
}): Variants {
  const { preset, direction, distance, blur, scaleFrom, duration, reducedMotion } = opts;

  if (reducedMotion) {
    // Reset the full superset of animatable props so the reveal lands on a clean
    // static frame even if an earlier (pre-hydration) render committed a melt/slide
    // hidden state carrying a blur or offset.
    return {
      hidden: { opacity: 0 },
      show: { opacity: 1, x: 0, y: 0, filter: "blur(0px)", scale: 1, transition: { duration: 0.3 } },
    };
  }

  const axis = direction === "left" || direction === "right" ? "x" : "y";
  const offset = axis === "y" ? (direction === "up" ? distance : -distance) : direction === "left" ? distance : -distance;

  const usesOffset = preset === "melt" || preset === "slide";
  const usesBlur = preset === "melt" || preset === "blur";
  const usesScale = preset === "scale";

  const hidden: TargetAndTransition = {
    opacity: 0,
    ...(usesOffset ? { [axis]: offset } : {}),
    ...(usesBlur ? { filter: `blur(${blur}px)` } : {}),
    ...(usesScale ? { scale: scaleFrom } : {}),
  };

  const show: TargetAndTransition = {
    opacity: 1,
    ...(usesOffset ? { [axis]: 0 } : {}),
    ...(usesBlur ? { filter: "blur(0px)" } : {}),
    ...(usesScale ? { scale: 1 } : {}),
    transition: { duration, ease: [0.25, 0.4, 0.25, 1] },
  };

  return { hidden, show };
}

/**
 * Surface — a composable in-view reveal wrapper. Wrap any content and it rises
 * into view as it crosses the viewport threshold; wrap multiple top-level
 * children and they stagger in sequence, each animating via shared variants.
 *
 * Default `melt` preset reads as surfacing out of the dark: children rise 12px
 * while a soft white under-glow brightens then fades beneath them, with a
 * starting blur that sharpens as they settle. Falls back to a plain opacity
 * fade when the user prefers reduced motion.
 */
export function Surface({
  children,
  preset = "melt",
  direction = "up",
  distance = 12,
  blur = 8,
  scaleFrom = 0.94,
  duration = 0.6,
  stagger = 0.08,
  delay = 0,
  repeat = false,
  amount = 0.4,
  margin = "0px 0px -10% 0px",
  root,
  ember = true,
  emberColor = "#ffffff",
  className,
  ...props
}: SurfaceProps) {
  const reducedMotion = useReducedMotion();
  const items = React.Children.toArray(children);

  const itemVariants = React.useMemo(
    () => buildItemVariants({ preset, direction, distance, blur, scaleFrom, duration, reducedMotion }),
    [preset, direction, distance, blur, scaleFrom, duration, reducedMotion]
  );

  const glowVariants: Variants = {
    hidden: { opacity: 0 },
    show: {
      opacity: [0, 0.55, 0],
      transition: { duration: duration * 1.4, times: [0, 0.45, 1], ease: "easeOut" },
    },
  };

  const showEmber = ember && preset === "melt" && !reducedMotion;

  return (
    <motion.div
      data-crucible="surface"
      className={cn("relative isolate", className)}
      initial="hidden"
      whileInView="show"
      viewport={{ once: !repeat, amount, margin, root }}
      transition={{ staggerChildren: reducedMotion ? 0 : stagger, delayChildren: delay }}
      {...props}
    >
      {showEmber && (
        <motion.span
          aria-hidden
          variants={glowVariants}
          className="pointer-events-none absolute inset-x-0 bottom-0 -z-10 h-1/2 blur-2xl"
          style={{ background: `radial-gradient(60% 100% at 50% 100%, ${emberColor}55, transparent 70%)` }}
        />
      )}
      {items.map((child, i) => (
        <motion.div
          key={i}
          variants={itemVariants}
          className="will-change-[transform,filter,opacity]"
        >
          {child}
        </motion.div>
      ))}
    </motion.div>
  );
}

"use client";

import * as React from "react";
import {
  motion,
  useScroll,
  useTransform,
  useMotionValueEvent,
  type TargetAndTransition,
} from "motion/react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/** A single dated entry on the timeline. */
export interface StratumEntry {
  /**
   * Small label rendered above the title — a date, version tag, or step marker.
   * Optional; omit for an undated milestone.
   */
  date?: React.ReactNode;
  /** Entry heading. Pins as a sticky title while its content scrolls past. */
  title: React.ReactNode;
  /** Body content that scrolls beneath the pinned title. */
  content: React.ReactNode;
  /** Stable identity for the list key. Falls back to the entry index. */
  id?: string;
}

export interface StratumProps
  extends Omit<React.ComponentPropsWithoutRef<"div">, "children"> {
  /**
   * The timeline entries, top to bottom. Beautiful with zero props — a sample
   * changelog renders when omitted.
   */
  entries?: StratumEntry[];
  /** Which edge the spine sits on. `center` alternates content side to side. @default "left" */
  rail?: "left" | "center" | "right";
  /** Live-beam + ignited-node color (the one cool accent). @default "#60a5fa" */
  accentColor?: string;
  /** Dim track + cold (un-ignited) node color. @default "#52525b" */
  railColor?: string;
  /** Beam / track stroke width in px. @default 2 */
  beamWidth?: number;
  /** Node marker shape. @default "dot" */
  marker?: "dot" | "ring" | "diamond" | "square";
  /** Node marker size in px. @default 14 */
  markerSize?: number;
  /** Sticky title offset from the top of the scroll container, in px. @default 16 */
  stickyOffset?: number;
  /**
   * Backdrop painted behind a pinned title so the entry body scrolling beneath
   * it never collides with the title text. Match it to your surface (any CSS
   * color); pass `"transparent"` to opt out. @default "rgb(10 10 10 / 0.88)"
   */
  stickyBackground?: string;
  /** Per-entry content reveal as it enters view. @default "slide" */
  reveal?: "slide" | "fade" | "none";
  /**
   * Scroll container to track instead of the window. Pass a ref to an
   * `overflow-y-auto` ancestor so the beam scrubs against THAT container
   * (e.g. inside a boxed panel). @default the viewport
   */
  root?: React.RefObject<HTMLElement | null>;
  /** Heading level rendered for each entry title (semantic outline). @default 3 */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
}

const DEFAULT_ACCENT = "#60a5fa";
const DEFAULT_RAIL = "#52525b";

const DEFAULT_ENTRIES: StratumEntry[] = [
  {
    date: "v2.4 — March",
    title: "Streaming search",
    content:
      "Results now surface as you type, with fuzzy matching across titles, tags, and body text. The index rebuilds incrementally in a worker, so typing never blocks.",
  },
  {
    date: "v2.5 — April",
    title: "Shared views",
    content:
      "Save a filtered view and share it with the whole workspace. Everyone sees the same board, live, with cursors and selection presence.",
  },
  {
    date: "v2.6 — May",
    title: "Offline drafts",
    content:
      "Edits queue locally and sync the moment you reconnect. Conflicts resolve field by field, so two people rarely clobber each other's work.",
  },
  {
    date: "v2.7 — June",
    title: "Granular roles",
    content:
      "The old admin toggle is gone. Grant access per project, per environment, or per key — and audit every grant from one place.",
  },
  {
    date: "v3.0 — July",
    title: "Audit stream",
    content:
      "Every change is recorded with who, what, and when. Export on demand, or stream the log straight to your SIEM of choice.",
  },
];

/** Reveal target/rest states per preset — used as inline transitions, not variants. */
function revealFrames(preset: NonNullable<StratumProps["reveal"]>): {
  hidden: TargetAndTransition;
  shown: TargetAndTransition;
} {
  switch (preset) {
    case "fade":
      return { hidden: { opacity: 0 }, shown: { opacity: 1 } };
    case "none":
      return { hidden: { opacity: 1 }, shown: { opacity: 1 } };
    case "slide":
    default:
      return { hidden: { opacity: 0, y: 14 }, shown: { opacity: 1, y: 0 } };
  }
}

interface NodeMarkerProps {
  lit: boolean;
  reduced: boolean;
  marker: NonNullable<StratumProps["marker"]>;
  size: number;
  accent: string;
  cold: string;
}

/**
 * A single rail node. Cold slate until the beam reaches it, then it seats with a
 * crisp escapement pop — the hot core springs in with a 2px overshoot and locks,
 * a halo flares once, and it stays lit thereafter.
 */
function NodeMarker({ lit, reduced, marker, size, accent, cold }: NodeMarkerProps) {
  const radius =
    marker === "diamond" || marker === "square" ? "18%" : "9999px";
  const hollow = marker === "ring";

  // Reduced motion: land lit and static, no springs, no flare.
  const coreTransition = reduced
    ? { duration: 0 }
    : { type: "spring" as const, stiffness: 720, damping: 15, mass: 0.5 };

  return (
    <span
      className="relative inline-flex items-center justify-center"
      style={{ width: size, height: size }}
    >
      {/* One-shot ignite flare. Mounted only once lit, keyed so it plays exactly
          once — unrelated re-renders (other nodes igniting) never replay it. */}
      {!reduced && lit && (
        <motion.span
          key="flare"
          aria-hidden
          className="pointer-events-none absolute inset-0"
          style={{ borderRadius: radius, background: accent }}
          initial={{ opacity: 0.55, scale: 0.6 }}
          animate={{ opacity: 0, scale: 2.4 }}
          transition={{ duration: 0.6, ease: [0.2, 0.7, 0.3, 1] }}
        />
      )}

      {/* Outer marker: outline that warms from slate to accent. */}
      <motion.span
        aria-hidden
        className={cn(
          "absolute inset-0 transition-none",
          marker === "diamond" && "rotate-45"
        )}
        style={{
          borderRadius: radius,
          borderStyle: "solid",
          borderWidth: Math.max(1.5, size * 0.14),
          background: hollow ? "transparent" : "#0a0a0a",
        }}
        initial={false}
        animate={{
          borderColor: lit ? accent : cold,
          boxShadow: lit
            ? `0 0 ${size * 0.9}px ${accent}, 0 0 ${size * 0.35}px ${accent}`
            : `0 0 0px ${accent}00`,
        }}
        transition={reduced ? { duration: 0 } : { duration: 0.45, ease: "easeOut" }}
      />

      {/* Hot core: springs in with overshoot when lit. Absent for the ring marker. */}
      {!hollow && (
        <motion.span
          aria-hidden
          className={cn("relative", marker === "diamond" && "rotate-45")}
          style={{
            width: "46%",
            height: "46%",
            borderRadius: marker === "diamond" || marker === "square" ? "12%" : "9999px",
            background: lit
              ? `radial-gradient(circle at 50% 40%, #ffffff, ${accent})`
              : cold,
          }}
          initial={false}
          animate={{ scale: lit ? 1 : 0 }}
          transition={coreTransition}
        />
      )}
    </span>
  );
}

/**
 * Stratum — a scroll-linked vertical timeline. Dated entries run down a rail
 * with sticky titles that pin while their content scrolls past. A progress beam
 * draws down the spine bound to scroll position (bright above the read point,
 * dim below), its leading edge carrying a faint white meniscus head. Node dots
 * ignite as the beam reaches them — cold slate seating into an accent glow with
 * an escapement pop — and stay lit.
 *
 * Semantic and accessible: renders an ordered list of entries with real
 * headings, so the timeline is navigable and reads correctly to assistive tech.
 * Under `prefers-reduced-motion` the beam is fully drawn, every node is lit, and
 * content sits in normal flow with no scrub or reveal.
 *
 * SSR-safe: no window access at module scope, deterministic markup, node
 * positions measured client-side. Perf: a single scroll-scrubbed transform
 * drives the beam and node ignition (no per-node scroll listeners), one
 * IntersectionObserver drives reveals, and both tear down on unmount.
 */
export function Stratum({
  entries = DEFAULT_ENTRIES,
  rail = "left",
  accentColor = DEFAULT_ACCENT,
  railColor = DEFAULT_RAIL,
  beamWidth = 2,
  marker = "dot",
  markerSize = 14,
  stickyOffset = 16,
  stickyBackground = "rgb(10 10 10 / 0.88)",
  reveal = "slide",
  root,
  headingLevel = 3,
  className,
  style,
  ...props
}: StratumProps) {
  const reduced = useReducedMotion();
  const innerRef = React.useRef<HTMLDivElement>(null);
  const nodeRefs = React.useRef<(HTMLElement | null)[]>([]);
  const contentRefs = React.useRef<(HTMLElement | null)[]>([]);

  // Fractional (0..1) rail position of each node center, measured client-side.
  const fractionsRef = React.useRef<number[]>([]);
  const peakLitRef = React.useRef(0);
  const peakRevealedRef = React.useRef<Set<number>>(new Set());
  const [litCount, setLitCount] = React.useState(0);
  const [revealed, setRevealed] = React.useState<Set<number>>(() => new Set());

  const Heading = `h${headingLevel}` as "h2";
  const laneWidth = Math.max(markerSize + 20, 40);
  const laneCenter = laneWidth / 2;
  const frames = revealFrames(reveal);

  const { scrollYProgress } = useScroll({
    container: root,
    target: innerRef,
    offset: ["start start", "end end"],
  });

  // Beam fill + meniscus head position, scrubbed straight off scroll progress.
  const beamHeight = useTransform(scrollYProgress, [0, 1], ["0%", "100%"]);
  const headTop = useTransform(scrollYProgress, [0, 1], ["0%", "100%"]);
  const headOpacity = useTransform(scrollYProgress, [0, 0.008, 0.985, 1], [0, 1, 1, 0]);

  const recomputeLit = React.useCallback(
    (p: number) => {
      const fracs = fractionsRef.current;
      let count = 0;
      for (let i = 0; i < fracs.length; i++) {
        if (p + 0.001 >= fracs[i]) count++;
        else break;
      }
      if (count > peakLitRef.current) {
        peakLitRef.current = count;
        setLitCount(count);
      }
    },
    []
  );

  // Measure node positions once mounted, and re-measure on resize. Nodes stay
  // lit once reached, so we only ever grow litCount from the scroll subscription.
  React.useEffect(() => {
    const inner = innerRef.current;
    if (!inner) return;

    const measure = () => {
      const total = inner.offsetHeight || 1;
      fractionsRef.current = nodeRefs.current.map((el) =>
        el ? (el.offsetTop + el.offsetHeight / 2) / total : 1
      );
      recomputeLit(scrollYProgress.get());
    };

    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(inner);
    return () => ro.disconnect();
  }, [entries, rail, recomputeLit, scrollYProgress]);

  // Single scroll subscription drives node ignition. Reduced motion lights all.
  useMotionValueEvent(scrollYProgress, "change", (p) => {
    if (reduced) return;
    recomputeLit(p);
  });

  React.useEffect(() => {
    if (reduced) {
      peakLitRef.current = entries.length;
      setLitCount(entries.length);
    }
  }, [reduced, entries.length]);

  // Single IntersectionObserver drives per-entry reveals.
  React.useEffect(() => {
    if (reduced || reveal === "none") {
      setRevealed(new Set(entries.map((_, i) => i)));
      return;
    }
    const els = contentRefs.current.filter(Boolean) as HTMLElement[];
    if (els.length === 0) return;

    const io = new IntersectionObserver(
      (obsEntries) => {
        let changed = false;
        const next = new Set(peakRevealedRef.current);
        for (const e of obsEntries) {
          if (e.isIntersecting) {
            const idx = Number((e.target as HTMLElement).dataset.stratumIndex);
            if (!Number.isNaN(idx) && !next.has(idx)) {
              next.add(idx);
              changed = true;
            }
          }
        }
        if (changed) {
          peakRevealedRef.current = next;
          setRevealed(next);
        }
      },
      { root: root?.current ?? null, threshold: 0.15, rootMargin: "0px 0px -10% 0px" }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, [reduced, reveal, entries, root]);

  // Lane geometry: the absolute spine and the node column share a center line.
  const laneStyle: React.CSSProperties =
    rail === "left"
      ? { left: laneCenter, transform: "translateX(-50%)" }
      : rail === "right"
        ? { right: laneCenter, transform: "translateX(50%)" }
        : { left: "50%", transform: "translateX(-50%)" };

  const gridTemplate =
    rail === "left"
      ? `${laneWidth}px minmax(0,1fr)`
      : rail === "right"
        ? `minmax(0,1fr) ${laneWidth}px`
        : `minmax(0,1fr) ${laneWidth}px minmax(0,1fr)`;

  const headSize = Math.max(beamWidth * 3, 7);

  return (
    <div
      ref={innerRef}
      data-crucible="stratum"
      className={cn("relative", className)}
      style={style}
      {...props}
    >
      {/* Spine: dim track + bright scrubbed beam + meniscus head. Decorative. */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-y-0 z-0"
        style={{ ...laneStyle, width: beamWidth }}
      >
        {/* Dim track (full height). */}
        <div
          className="absolute inset-y-0 left-0 w-full rounded-full"
          style={{ background: railColor, opacity: 0.5 }}
        />
        {/* Live beam: fades in from the top, brightest at the leading edge. */}
        <motion.div
          className="absolute left-0 top-0 w-full rounded-full"
          style={{
            height: reduced ? "100%" : beamHeight,
            background: `linear-gradient(to bottom, ${accentColor}00, ${accentColor})`,
            boxShadow: `0 0 ${beamWidth * 5}px ${accentColor}`,
            transformOrigin: "top",
          }}
        />
        {/* Meniscus head bead at the beam's leading edge. */}
        {!reduced && (
          <motion.div
            className="absolute left-1/2 rounded-full bg-white"
            style={{
              top: headTop,
              width: headSize,
              height: headSize,
              x: "-50%",
              y: "-50%",
              opacity: headOpacity,
              boxShadow: `0 0 ${headSize * 1.6}px #ffffff, 0 0 ${headSize * 0.7}px ${accentColor}`,
            }}
          />
        )}
      </div>

      <ol className="relative z-10 m-0 list-none p-0">
        {entries.map((entry, i) => {
          const key = entry.id ?? i;
          const isLit = i < litCount;
          const isRevealed = revealed.has(i);

          // Center rail alternates content side; left/right are fixed.
          const dotCol = rail === "center" ? 2 : rail === "left" ? 1 : 2;
          let contentCol: number;
          let contentAlign: "left" | "right";
          if (rail === "left") {
            contentCol = 2;
            contentAlign = "left";
          } else if (rail === "right") {
            contentCol = 1;
            contentAlign = "right";
          } else {
            const rightSide = i % 2 === 0;
            contentCol = rightSide ? 3 : 1;
            contentAlign = rightSide ? "left" : "right";
          }

          return (
            <li
              key={key}
              className="grid"
              style={{ gridTemplateColumns: gridTemplate, columnGap: 4 }}
            >
              {/* Node column — dot aligned to the entry's title line. */}
              <div
                className="flex justify-center"
                style={{ gridColumn: dotCol, paddingTop: stickyOffset }}
              >
                <span
                  ref={(el) => {
                    nodeRefs.current[i] = el;
                  }}
                  className="flex h-max items-start"
                >
                  <NodeMarker
                    lit={isLit}
                    reduced={reduced}
                    marker={marker}
                    size={markerSize}
                    accent={accentColor}
                    cold={railColor}
                  />
                </span>
              </div>

              {/* Content column. */}
              <div
                className="min-w-0 pb-16"
                style={{ gridColumn: contentCol, textAlign: contentAlign }}
              >
                <div
                  className="mb-4"
                  style={
                    reduced
                      ? { position: "static" }
                      : {
                          position: "sticky",
                          top: stickyOffset,
                          zIndex: 5,
                          // Opaque-ish backdrop (+ a little breathing room) so the
                          // body text sliding under the pinned title stays legible.
                          background: stickyBackground,
                          backdropFilter: stickyBackground === "transparent" ? undefined : "blur(6px)",
                          paddingBlock: 4,
                        }
                  }
                >
                  {entry.date != null && (
                    <div className="text-[11px] font-medium uppercase tracking-[0.18em] text-neutral-500">
                      {entry.date}
                    </div>
                  )}
                  <Heading className="mt-1 text-lg font-semibold tracking-tight text-white">
                    {entry.title}
                  </Heading>
                </div>

                <motion.div
                  ref={(el: HTMLDivElement | null) => {
                    contentRefs.current[i] = el;
                  }}
                  data-stratum-index={i}
                  className="text-sm leading-relaxed text-neutral-400"
                  initial={false}
                  animate={isRevealed ? frames.shown : frames.hidden}
                  transition={
                    reduced ? { duration: 0 } : { duration: 0.5, ease: [0.25, 0.4, 0.25, 1] }
                  }
                >
                  {entry.content}
                </motion.div>
              </div>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

/**
 * The default spring feel of the lattice, exported so you can reuse or riff on
 * it: `tension` is the Hooke pull-back stiffness (per s²), `friction` the
 * per-frame velocity retention at 60fps (applied frame-rate-independently),
 * `maxStretch` the CSS-px displacement the soft-clip saturates toward.
 */
export const DEFAULT_SPRING = {
  tension: 150,
  friction: 0.93,
  maxStretch: 48,
} as const;

export interface SwellProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * `"horizontal"` — rows of swell lines, depth rising toward the bottom of the
   * frame (an open-sea read). `"vertical"` — hanging curtains of line with
   * seeded depth layers. @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Lattice spacing in CSS px: `x` = horizontal spacing, `y` = vertical
   * spacing. For horizontal orientation `y` sets the row gap and `x` the
   * sample step along each row (vertical orientation swaps roles). Each axis
   * clamped 8–200. @default { x: 28, y: 26 }
   */
  gap?: { x: number; y: number };
  /** Idle wave amplitude in CSS px — how far points orbit their anchors. @default 16 */
  amplitude?: number;
  /** Animation-speed multiplier for drift and the swell front. 1 = default. @default 1 */
  speed?: number;
  /** Line brightness, 0–2. @default 1 */
  intensity?: number;
  /**
   * Spring stiffness pulling displaced points home (per s²). Higher = faster,
   * tighter snap-back. Clamped 1–600. @default 150
   */
  tension?: number;
  /**
   * Spring velocity retention per frame at 60fps, 0–0.999 (applied
   * frame-rate-independently). Lower = deader, higher = wobblier. @default 0.93
   */
  friction?: number;
  /**
   * CSS-px displacement the cursor can stretch a point toward. Rendered
   * through a tanh soft-clip, so stretch saturates smoothly — never a hard
   * stop. @default 48
   */
  maxStretch?: number;
  /**
   * Period in seconds of the autonomous swell front — a slow pressure wave
   * that rolls through the lattice so the field breathes with no cursor.
   * @default 8
   */
  swellInterval?: number;
  /**
   * Two tones `[far, near]` graded across row depth. Defaults to deep-sea
   * steel: dim slate far rows rising to cyan-tinged near rows. Pass warm tones
   * for a dune-wind look. @default ["#31404f", "#7dd3fc"]
   */
  colors?: [string, string];
  /**
   * When true, cursor swipes inject velocity impulses along the travel
   * direction, proportional to smoothed cursor speed, then spring back.
   * @default true
   */
  interactive?: boolean;
  /**
   * Idle autoplay: after ~1.5s with no real pointer, a seeded ghost cursor
   * sweeps slow figure-eights through the lattice (with an occasional faster
   * swipe) so thumbnails and heroes never sit still; the real pointer takes
   * over instantly. Requires `interactive`. Never runs under reduced motion.
   * @default true
   */
  idle?: boolean;
  /** Deterministic seed for depth layout and drift phases. @default 1 */
  seed?: number;
  /** devicePixelRatio ceiling. Clamped 1–2. @default 2 */
  dpr?: number;
  /** Freeze at a static frame with the swell front mid-roll (never flat). @default false */
  paused?: boolean;
}

const DEFAULT_COLORS: [string, string] = ["#31404f", "#7dd3fc"];
/** Deep-sea near-black bed — cool navy, never flat #000. */
const BG: [number, number, number] = [4, 9, 15];

const TAU = Math.PI * 2;
/** Spatial size of one noise feature in CSS px. */
const FEATURE_PX = 240;
/** How many full turns the noise value winds the orbital angle through. */
const ANGLE_TURNS = 1.6;
/** Swell-front contribution to the orbital angle (radians at crest). */
const SWELL_ANGLE = 1.05;
/** Swell-front amplitude boost at crest (fraction of base amplitude). */
const SWELL_AMP = 0.45;
/** Frozen noise time for the reduced-motion / paused frame. */
const NOISE_T_STATIC = 3.7;
/** Cursor influence radius, CSS px. */
const POINTER_RADIUS = 130;
/** Impulse gain: cursor speed → point velocity injection. */
const INJECT = 3.1;
/** Smoothed cursor speed cap, CSS px/s. */
const MAX_POINTER_SPEED = 2600;
/** Extra kick on the transverse axis — the component the eye reads on a polyline. */
const TRANSVERSE_BOOST = 1.35;
/** Exponential time constants (seconds): enter/leave ease, velocity smoothing, velocity decay. */
const EASE_TAU = 0.22;
const VEL_TAU = 0.05;
const VEL_DECAY_TAU = 0.12;
/** Hard cap on total lattice points; the along-line step grows past this. */
const MAX_POINTS = 4200;
/** Ghost cursor takes over this long after the last real pointer movement. */
const GHOST_DELAY_MS = 1500;
/** Ghost presence — a softer hand than a real swipe. */
const GHOST_PRESENCE = 0.85;

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [125, 211, 252];
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

/** Deterministic mulberry32 PRNG — same seed, same sea. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Integer hash → [0,1), stable across SSR intent and client. */
function hash3(ix: number, iy: number, iz: number, seed: number): number {
  let h = seed >>> 0;
  h = Math.imul(h ^ (ix | 0), 0x27d4eb2f);
  h = Math.imul(h ^ (iy | 0), 0x85ebca6b);
  h = Math.imul(h ^ (iz | 0), 0xc2b2ae35);
  h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}

function fade(t: number): number {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Trilinear value noise in 3D — smooth, seeded, morphs along z (time). */
function vnoise3(x: number, y: number, z: number, seed: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const iz = Math.floor(z);
  const ux = fade(x - ix);
  const uy = fade(y - iy);
  const uz = fade(z - iz);

  const c000 = hash3(ix, iy, iz, seed);
  const c100 = hash3(ix + 1, iy, iz, seed);
  const c010 = hash3(ix, iy + 1, iz, seed);
  const c110 = hash3(ix + 1, iy + 1, iz, seed);
  const c001 = hash3(ix, iy, iz + 1, seed);
  const c101 = hash3(ix + 1, iy, iz + 1, seed);
  const c011 = hash3(ix, iy + 1, iz + 1, seed);
  const c111 = hash3(ix + 1, iy + 1, iz + 1, seed);

  const x00 = lerp(c000, c100, ux);
  const x10 = lerp(c010, c110, ux);
  const x01 = lerp(c001, c101, ux);
  const x11 = lerp(c011, c111, ux);
  return lerp(lerp(x00, x10, uy), lerp(x01, x11, uy), uz);
}

/** Two-octave value noise, ~[0,1] — one main eval plus a cheap detail term. */
function fbm2(x: number, y: number, z: number, seed: number): number {
  return (
    vnoise3(x, y, z, seed) * 0.72 +
    vnoise3(x * 2.13, y * 2.13, z * 1.7 + 9.2, seed + 101) * 0.28
  );
}

interface Line {
  /** Index of the line's first point in the flat point arrays. */
  start: number;
  count: number;
  /** Depth 0 (far) → 1 (near): drives opacity, width, drift rate, amplitude. */
  z: number;
  rgb: [number, number, number];
  alphaBase: number;
  width: number;
  /** Per-row noise-drift rate — depth-graded so rows parallax. */
  tRate: number;
  tPhase: number;
}

interface Tuning {
  speed: number;
  intensity: number;
  amplitude: number;
  tension: number;
  friction: number;
  maxStretch: number;
  swellInterval: number;
  interactive: boolean;
  idle: boolean;
}

interface Internals {
  ctx: CanvasRenderingContext2D;
  w: number;
  h: number;
  horizontal: boolean;
  lines: Line[];
  /** Anchor positions, CSS px. */
  bx: Float32Array;
  by: Float32Array;
  /** Spring displacement + velocity per point. */
  sx: Float32Array;
  sy: Float32Array;
  vx: Float32Array;
  vy: Float32Array;
  /** Per-line scratch for displaced positions. */
  px: Float32Array;
  py: Float32Array;
  /** Swell-front wavelength (CSS px) and center projection for the static crest. */
  lambda: number;
  projC: number;
  /** Per-instance seeded time offset — multiple instances desync deterministically. */
  timeOffset: number;
  noiseSeed: number;
  springsIdle: boolean;
  // Pointer state, CSS px / px-per-second.
  pointerX: number;
  pointerY: number;
  prevX: number;
  prevY: number;
  velTX: number;
  velTY: number;
  velSX: number;
  velSY: number;
  ease: number;
  easeTarget: number;
  hasPointer: boolean;
  lastMoveT: number;
  lastElapsed: number;
  /** Ghost cursor is currently driving the pointer state. */
  ghostOn: boolean;
  /** Ghost path clock (s) — advances only while the ghost drives. */
  ghostT: number;
  /** Ghost wall clock (s) that paces the swipe surges. */
  ghostWall: number;
}

/**
 * Idle autoplay: when `want` (no real pointer for GHOST_DELAY_MS), a seeded
 * ghost drives the pointer state along a Lissajous figure-eight whose pace
 * surges every few seconds into a swipe, so the springs keep getting kicked.
 */
function driveGhost(it: Internals, tn: Tuning, dt: number, want: boolean) {
  if (!(want && tn.idle && tn.interactive)) {
    if (it.ghostOn) {
      it.ghostOn = false;
      it.hasPointer = false;
      it.easeTarget = 0;
    }
    return;
  }
  // Pace surges periodically: a lazy drift that every ~8s breaks into a swipe.
  it.ghostWall += dt;
  const surge = Math.pow(Math.max(Math.sin(it.ghostWall * 0.8 + it.timeOffset), 0), 4);
  it.ghostT += dt * (0.6 + 3.4 * surge) * Math.max(tn.speed, 0.2);
  const g = it.ghostT + it.timeOffset * 7;
  const x = it.w * (0.5 + 0.4 * Math.sin(g * 0.61) + 0.06 * Math.sin(g * 1.7));
  const y = it.h * (0.5 + 0.3 * Math.sin(g * 1.22 + 0.9));
  if (!it.ghostOn) {
    // Fade the ghost in from wherever its path is — never a streak from (0,0).
    it.ghostOn = true;
    it.prevX = it.pointerX = x;
    it.prevY = it.pointerY = y;
    it.velTX = it.velTY = 0;
    it.hasPointer = true;
    it.easeTarget = GHOST_PRESENCE;
    return;
  }
  const inv = 1 / Math.max(dt, 1e-3);
  it.velTX = it.velTX * 0.4 + (x - it.pointerX) * inv * 0.6;
  it.velTY = it.velTY * 0.4 + (y - it.pointerY) * inv * 0.6;
  it.pointerX = x;
  it.pointerY = y;
  it.hasPointer = true;
  it.easeTarget = GHOST_PRESENCE;
}

/** Advance pointer easing + springs by dt seconds (frame-rate independent). */
function physics(it: Internals, tn: Tuning, dt: number) {
  // Eased 0→1 influence scalar on enter/leave; exponential time-constant blends.
  it.ease += (it.easeTarget - it.ease) * (1 - Math.exp(-dt / EASE_TAU));
  const velK = 1 - Math.exp(-dt / VEL_TAU);
  it.velSX += (it.velTX - it.velSX) * velK;
  it.velSY += (it.velTY - it.velSY) * velK;
  // Target decays between move events so a parked cursor goes quiet.
  const decay = Math.exp(-dt / VEL_DECAY_TAU);
  it.velTX *= decay;
  it.velTY *= decay;

  const speedSm = Math.hypot(it.velSX, it.velSY);
  const drive = tn.interactive ? it.ease * Math.min(speedSm, MAX_POINTER_SPEED) : 0;
  const injecting = drive > 24 && it.hasPointer;

  const { bx, by, sx, sy, vx, vy } = it;
  const n = bx.length;

  if (injecting) {
    it.springsIdle = false;
    // Impulse along the travel direction, ∝ smoothed cursor speed, over dt.
    const invSpeed = 1 / (speedSm || 1);
    let impX = it.velSX * invSpeed * drive * INJECT * dt;
    let impY = it.velSY * invSpeed * drive * INJECT * dt;
    if (it.horizontal) impY *= TRANSVERSE_BOOST;
    else impX *= TRANSVERSE_BOOST;

    // Kick every point near the pointer's travel *segment* this frame, so a
    // fast swipe wakes the whole corridor it crossed — not just event samples.
    const ax = it.prevX;
    const ay = it.prevY;
    const abx = it.pointerX - ax;
    const aby = it.pointerY - ay;
    const ab2 = abx * abx + aby * aby || 1;
    const maxD2 = POINTER_RADIUS * POINTER_RADIUS * 2.9;
    const sigma = POINTER_RADIUS * 0.55;
    const invTwoSig2 = 1 / (2 * sigma * sigma);

    for (let i = 0; i < n; i++) {
      const pxp = bx[i] + sx[i];
      const pyp = by[i] + sy[i];
      let tSeg = ((pxp - ax) * abx + (pyp - ay) * aby) / ab2;
      tSeg = tSeg < 0 ? 0 : tSeg > 1 ? 1 : tSeg;
      const dx = pxp - (ax + abx * tSeg);
      const dy = pyp - (ay + aby * tSeg);
      const d2 = dx * dx + dy * dy;
      if (d2 > maxD2) continue;
      const wgt = Math.exp(-d2 * invTwoSig2);
      vx[i] += impX * wgt;
      vy[i] += impY * wgt;
    }
  }

  if (!it.springsIdle) {
    // Damped Hooke springs, semi-implicit Euler; friction is a per-frame
    // retention at 60fps raised to dt·60 so the feel survives any frame rate.
    const fr = Math.pow(Math.min(Math.max(tn.friction, 0), 0.999), dt * 60);
    const k = Math.min(Math.max(tn.tension, 1), 600);
    const cap = Math.max(tn.maxStretch, 1) * 2.5;
    const cap2 = cap * cap;
    let maxAbs = 0;
    for (let i = 0; i < n; i++) {
      let vxi = (vx[i] - sx[i] * k * dt) * fr;
      let vyi = (vy[i] - sy[i] * k * dt) * fr;
      let sxi = sx[i] + vxi * dt;
      let syi = sy[i] + vyi * dt;
      const r2 = sxi * sxi + syi * syi;
      if (r2 > cap2) {
        const s = cap / Math.sqrt(r2);
        sxi *= s;
        syi *= s;
        vxi *= 0.7;
        vyi *= 0.7;
      }
      vx[i] = vxi;
      vy[i] = vyi;
      sx[i] = sxi;
      sy[i] = syi;
      const a = Math.abs(sxi) + Math.abs(syi) + (Math.abs(vxi) + Math.abs(vyi)) * 0.05;
      if (a > maxAbs) maxAbs = a;
    }
    // All quiet → zero the field and skip this loop entirely until re-kicked.
    if (!injecting && maxAbs < 0.06) {
      it.springsIdle = true;
      sx.fill(0);
      sy.fill(0);
      vx.fill(0);
      vy.fill(0);
    }
  }

  it.prevX = it.pointerX;
  it.prevY = it.pointerY;
}

/** One frame. `staticFrame` parks the swell crest mid-frame — visible curvature. */
function draw(it: Internals, tn: Tuning, t: number, staticFrame: boolean) {
  const { ctx, w, h, horizontal, lines, bx, by, sx, sy, px, py, lambda } = it;
  ctx.fillStyle = `rgb(${BG[0]},${BG[1]},${BG[2]})`;
  ctx.fillRect(0, 0, w, h);
  ctx.lineJoin = "round";
  ctx.lineCap = "round";

  const baseT = t * Math.max(tn.speed, 0) + it.timeOffset;
  const swellT = baseT / Math.max(tn.swellInterval, 0.5);
  // Live: front travels with time. Static: phase chosen so the crest sits at
  // the frame center — the frozen lattice always shows a full rolling swell.
  const phase0 = staticFrame ? (TAU * it.projC) / lambda - Math.PI / 2 : TAU * swellT;
  const springs = !staticFrame && !it.springsIdle;
  const maxStretch = Math.max(tn.maxStretch, 1);
  const invF = 1 / FEATURE_PX;
  const amplitude = Math.max(tn.amplitude, 0);
  const intensity = Math.max(tn.intensity, 0);
  // Transverse-dominant orbits: lines sway across their own axis more than along it.
  const axX = horizontal ? 0.6 : 1;
  const axY = horizontal ? 1 : 0.6;

  for (const line of lines) {
    const alpha = Math.min(line.alphaBase * intensity, 1);
    if (alpha < 0.01) continue;
    const lt = staticFrame ? NOISE_T_STATIC + line.tPhase : baseT * line.tRate + line.tPhase;
    const ampBase = amplitude * (0.55 + 0.45 * line.z);
    const end = line.start + line.count;

    let j = 0;
    for (let i = line.start; i < end; i++, j++) {
      const x = bx[i];
      const y = by[i];
      // Slightly diagonal front direction so the swell reads organic, not axial.
      const proj = horizontal ? x + y * 0.28 : y + x * 0.28;
      // Near rows lead the front by a small phase — depth parallax in time too.
      const ph = (TAU * proj) / lambda - phase0 + line.z * 0.55;
      const swell = Math.sin(ph);
      // Noise sample used as an ANGLE through (cos, sin) — orbital, woven motion.
      const angle =
        fbm2(x * invF, y * invF, lt, it.noiseSeed) * TAU * ANGLE_TURNS + SWELL_ANGLE * swell;
      const amp = ampBase * (1 + SWELL_AMP * swell);
      let ox = Math.cos(angle) * amp * axX;
      let oy = Math.sin(angle) * amp * axY;
      if (springs) {
        const sxi = sx[i];
        const syi = sy[i];
        const r = Math.hypot(sxi, syi);
        if (r > 0.001) {
          // tanh soft-clip: stretch saturates toward maxStretch, never hard-stops.
          const soft = (maxStretch * Math.tanh(r / maxStretch)) / r;
          ox += sxi * soft;
          oy += syi * soft;
        }
      }
      px[j] = x + ox;
      py[j] = y + oy;
    }

    ctx.strokeStyle = `rgba(${line.rgb[0]},${line.rgb[1]},${line.rgb[2]},${alpha})`;
    ctx.lineWidth = line.width;
    ctx.beginPath();
    ctx.moveTo(px[0], py[0]);
    const cnt = line.count;
    for (let m = 1; m < cnt - 1; m++) {
      ctx.quadraticCurveTo(px[m], py[m], (px[m] + px[m + 1]) * 0.5, (py[m] + py[m + 1]) * 0.5);
    }
    ctx.lineTo(px[cnt - 1], py[cnt - 1]);
    ctx.stroke();
  }
}

/**
 * Swell — a sprung wave lattice. Rows of smooth lines ride an orbital noise
 * field (each point circles its anchor, so the mesh moves with woven, curtain-
 * like coherence) while a slow autonomous swell front rolls through every ~8s,
 * so the field breathes with no cursor. Swipe through it and points take
 * velocity impulses along your travel direction, proportional to cursor speed,
 * then spring home on damped Hooke springs — fast flicks send a wobble down
 * the lattice. Depth-graded rows (opacity, width, drift rate) give a parallax
 * curtain; deep-sea steel by default. Canvas 2D: seeded and SSR-safe, paused
 * offscreen and on hidden tabs, DPR-clamped with device-pixel-aligned strokes,
 * reduced-motion-safe (a static frame with the swell crest mid-roll). Left
 * untouched, a seeded ghost cursor takes over (`idle`). Drop it inside any
 * `relative` container.
 */
export function Swell({
  orientation = "horizontal",
  gap = { x: 28, y: 26 },
  amplitude = 16,
  speed = 1,
  intensity = 1,
  tension = DEFAULT_SPRING.tension,
  friction = DEFAULT_SPRING.friction,
  maxStretch = DEFAULT_SPRING.maxStretch,
  swellInterval = 8,
  colors = DEFAULT_COLORS,
  interactive = true,
  idle = true,
  seed = 1,
  dpr = 2,
  paused = false,
  className,
  style,
  ...props
}: SwellProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const internalsRef = React.useRef<Internals | null>(null);
  const reducedMotion = useReducedMotion();

  const frozen = paused || reducedMotion;
  const frozenRef = React.useRef(frozen);
  frozenRef.current = frozen;
  // performance.now() of the last real pointer move; -Infinity = never.
  const lastRealRef = React.useRef(-Infinity);

  // Tuning knobs mutate in place — no lattice rebuild on feel changes.
  const tuningRef = React.useRef<Tuning>({
    speed,
    intensity,
    amplitude,
    tension,
    friction,
    maxStretch,
    swellInterval,
    interactive,
    idle,
  });
  tuningRef.current = {
    speed,
    intensity,
    amplitude,
    tension,
    friction,
    maxStretch,
    swellInterval,
    interactive,
    idle,
  };

  const gapKey = `${gap.x},${gap.y}`;
  const colorsKey = colors.join(",");

  const tick = React.useCallback((elapsed: number) => {
    const it = internalsRef.current;
    if (!it) return;
    const tn = tuningRef.current;
    const dt = Math.min(Math.max(elapsed - it.lastElapsed, 1 / 240), 1 / 30);
    it.lastElapsed = elapsed;
    driveGhost(it, tn, dt, performance.now() - lastRealRef.current > GHOST_DELAY_MS);
    physics(it, tn, dt);
    draw(it, tn, elapsed, false);
  }, []);

  const containerRef = useVisibilityPause<HTMLDivElement>(tick, { paused: frozen });

  // Build the lattice; rebuild on size / orientation / spacing / palette / seed.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;

    const dprScale = Math.min(
      typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1,
      Math.min(Math.max(dpr, 1), 2)
    );
    const farRgb = hexToRgb(colors[0]);
    const nearRgb = hexToRgb(colors[1]);
    const horizontal = orientation !== "vertical";
    const gapX = Math.min(Math.max(gap.x, 8), 200);
    const gapY = Math.min(Math.max(gap.y, 8), 200);
    /** Half-pixel alignment in DEVICE px so idle 1px strokes sit crisp on any DPR. */
    const alignHalf = (v: number) => (Math.round(v * dprScale - 0.5) + 0.5) / dprScale;

    const onContextLost = (e: Event) => e.preventDefault();
    canvas.addEventListener("contextlost", onContextLost);

    const build = () => {
      const w = Math.max(container.clientWidth, 1);
      const h = Math.max(container.clientHeight, 1);
      canvas.width = Math.round(w * dprScale);
      canvas.height = Math.round(h * dprScale);
      canvas.style.width = "100%";
      canvas.style.height = "100%";
      ctx.setTransform(dprScale, 0, 0, dprScale, 0, 0);

      const rand = mulberry32((Math.round(seed || 1) * 0x9e3779b1) >>> 0 || 1);

      // Row decimation on short stages: skip every other row below 480px height.
      const dec = h < 480 ? 2 : 1;
      const lineGap = horizontal ? gapY * dec : gapX;
      let step = horizontal ? gapX : gapY * dec;
      const span = horizontal ? h : w; // across the lines
      const length = horizontal ? w : h; // along the lines
      const lineCount = Math.max(2, Math.floor(span / lineGap));
      let ptsPerLine = Math.max(4, Math.floor(length / step) + 3);
      while (lineCount * ptsPerLine > MAX_POINTS) {
        step *= 1.5;
        ptsPerLine = Math.max(4, Math.floor(length / step) + 3);
      }
      const n = lineCount * ptsPerLine;

      const bx = new Float32Array(n);
      const by = new Float32Array(n);
      const lines: Line[] = [];
      for (let li = 0; li < lineCount; li++) {
        const cross = alignHalf((li + 0.5) * lineGap);
        // Horizontal rows: depth rises toward the bottom (sea toward the viewer).
        // Vertical curtains: seeded random depth layers.
        const z = horizontal
          ? Math.min(1, Math.max(0, 0.78 * (cross / h) + 0.22 * rand()))
          : rand();
        const start = li * ptsPerLine;
        for (let j = 0; j < ptsPerLine; j++) {
          const along = (j - 1) * step; // one point of overhang each side
          bx[start + j] = horizontal ? along : cross;
          by[start + j] = horizontal ? cross : along;
        }
        const zz = Math.pow(z, 1.15);
        lines.push({
          start,
          count: ptsPerLine,
          z,
          rgb: [
            Math.round(farRgb[0] + (nearRgb[0] - farRgb[0]) * zz),
            Math.round(farRgb[1] + (nearRgb[1] - farRgb[1]) * zz),
            Math.round(farRgb[2] + (nearRgb[2] - farRgb[2]) * zz),
          ],
          alphaBase: 0.34 + 0.54 * zz,
          width: 0.75 + 0.9 * z,
          tRate: 0.55 + 0.6 * z,
          tPhase: rand() * 61,
        });
      }
      // Far rows first so near rows draw on top.
      lines.sort((a, b) => a.z - b.z);

      const it: Internals = {
        ctx,
        w,
        h,
        horizontal,
        lines,
        bx,
        by,
        sx: new Float32Array(n),
        sy: new Float32Array(n),
        vx: new Float32Array(n),
        vy: new Float32Array(n),
        px: new Float32Array(ptsPerLine),
        py: new Float32Array(ptsPerLine),
        lambda: Math.max(w, h) * 0.8,
        projC: horizontal ? w / 2 + h * 0.14 : h / 2 + w * 0.14,
        timeOffset: rand() * 100,
        noiseSeed: (Math.round(seed || 1) * 0x51ab7) >>> 0 || 1,
        springsIdle: true,
        pointerX: 0,
        pointerY: 0,
        prevX: 0,
        prevY: 0,
        velTX: 0,
        velTY: 0,
        velSX: 0,
        velSY: 0,
        ease: 0,
        easeTarget: 0,
        hasPointer: false,
        lastMoveT: 0,
        lastElapsed: 0,
        ghostOn: false,
        ghostT: 0,
        ghostWall: 0,
      };
      internalsRef.current = it;
      // Never flash empty — paint one frame immediately.
      draw(it, tuningRef.current, 0, frozenRef.current);
    };

    const onPointerMove = (e: PointerEvent) => {
      const it = internalsRef.current;
      if (!it || frozenRef.current || !tuningRef.current.interactive) return;
      const rect = container.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const now = performance.now();
      lastRealRef.current = now;
      if (it.ghostOn) {
        // Real pointer takes over instantly: drop the ghost's velocity so the
        // jump from its position to the cursor never registers as a swipe.
        it.ghostOn = false;
        it.hasPointer = false;
        it.velTX = it.velTY = 0;
      }
      if (it.hasPointer) {
        const dtE = Math.min(Math.max((now - it.lastMoveT) / 1000, 0.004), 0.05);
        // Blend event velocity into the target to tame event-timing jitter.
        it.velTX = it.velTX * 0.4 + ((x - it.pointerX) / dtE) * 0.6;
        it.velTY = it.velTY * 0.4 + ((y - it.pointerY) / dtE) * 0.6;
      } else {
        it.prevX = x;
        it.prevY = y;
      }
      it.pointerX = x;
      it.pointerY = y;
      it.lastMoveT = now;
      it.hasPointer = true;
      it.easeTarget = 1;
    };

    const onPointerLeave = () => {
      const it = internalsRef.current;
      if (!it) return;
      it.easeTarget = 0;
      it.hasPointer = false;
      // The ghost resumes after the usual delay rather than snapping in.
      lastRealRef.current = performance.now();
    };

    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerleave", onPointerLeave);
    container.addEventListener("pointercancel", onPointerLeave);

    const ro = new ResizeObserver(build);
    ro.observe(container);
    build();

    return () => {
      ro.disconnect();
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
      container.removeEventListener("pointercancel", onPointerLeave);
      canvas.removeEventListener("contextlost", onContextLost);
      internalsRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orientation, gapKey, colorsKey, seed, dpr]);

  // Render the designed static frame in place when paused / reduced-motion
  // toggles on; springs are zeroed so unfreezing never jumps.
  React.useEffect(() => {
    const it = internalsRef.current;
    if (!it || !frozen) return;
    it.springsIdle = true;
    it.sx.fill(0);
    it.sy.fill(0);
    it.vx.fill(0);
    it.vy.fill(0);
    it.ease = 0;
    it.easeTarget = 0;
    it.velTX = 0;
    it.velTY = 0;
    it.velSX = 0;
    it.velSY = 0;
    it.hasPointer = false;
    it.ghostOn = false;
    draw(it, tuningRef.current, 0, true);
    // Tuning deps: knob changes while frozen must repaint the still frame.
  }, [frozen, speed, intensity, amplitude, swellInterval]);

  return (
    <div
      ref={containerRef}
      aria-hidden
      data-crucible="swell"
      className={cn("absolute inset-0 -z-10 overflow-hidden", className)}
      style={style}
      {...props}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
      {/* Soft vignette so the lattice sinks into the frame edges. */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 120% at 50% 42%, transparent 55%, rgba(0,0,0,0.5) 100%)",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

/* ------------------------------------------------------------------ types */

/**
 * Coloring role for a run of terminal text. Everything defaults to a warm
 * off-white; the semantic tints are deliberately quiet so a session reads as
 * one calm block, not a rainbow.
 */
export type TelegraphTone =
  | "default"
  | "muted"
  | "accent"
  | "success"
  | "info"
  | "warn"
  | "error"
  | "string";

export interface TelegraphSegment {
  /** Literal text of this run. */
  text: string;
  /** Coloring role. @default "default" */
  tone?: TelegraphTone;
}

export interface TelegraphLine {
  /**
   * `"command"` lines type out character-by-character behind a prompt sigil;
   * `"output"` lines fade in whole, like a program's response.
   */
  kind: "command" | "output";
  /**
   * Prompt sigil shown before a command line (overrides the component
   * `prompt`). Ignored for output lines.
   */
  prompt?: string;
  /**
   * The line body. A plain string is treated as one default-toned run; pass an
   * array to color individual segments. An empty command line is a resting
   * prompt (the caret parks there when the session finishes).
   */
  content: string | TelegraphSegment[];
}

export interface TelegraphProps
  extends Omit<React.ComponentPropsWithoutRef<"figure">, "content" | "children"> {
  /** The scripted session, top to bottom. @default a short install/deploy session */
  lines?: TelegraphLine[];
  /** Window title shown in the title bar. @default "zsh — ~/my-app" */
  title?: string;
  /** Default prompt sigil for command lines. @default "$" */
  prompt?: string;
  /**
   * The single cool accent — used for the prompt sigil, the caret glow, and
   * the `accent`/`string` tones. Any CSS color. @default sky "#7dd3fc"
   */
  accent?: string;
  /** Typing-rate multiplier (and reveal cadence). @default 1 */
  speed?: number;
  /** Seconds to wait after scrolling into view before typing begins. @default 0.3 */
  startDelay?: number;
  /** Replay the session on a loop instead of resting at the end. @default false */
  loop?: boolean;
  /** Freeze at the fully rendered final transcript, no typing. @default false */
  paused?: boolean;
}

/* --------------------------------------------------------------- defaults */

/** Sky-300 — cool, calm, elegant on charcoal. Not the green every clone uses. */
const DEFAULT_ACCENT = "#7dd3fc";
const DEFAULT_TITLE = "zsh — ~/my-app";

const DEFAULT_LINES: TelegraphLine[] = [
  { kind: "command", content: [{ text: "npm create app@latest my-app" }] },
  {
    kind: "output",
    content: [
      { text: "✓", tone: "success" },
      { text: " scaffolded " },
      { text: "my-app", tone: "string" },
      { text: " (react + vite)", tone: "muted" },
    ],
  },
  { kind: "command", content: [{ text: "cd my-app && npm install" }] },
  {
    kind: "output",
    content: [{ text: "added 214 packages in 3.1s", tone: "muted" }],
  },
  { kind: "command", content: [{ text: "npm run deploy" }] },
  {
    kind: "output",
    content: [
      { text: "▸", tone: "info" },
      { text: " building production bundle…", tone: "muted" },
    ],
  },
  {
    kind: "output",
    content: [
      { text: "✓", tone: "success" },
      { text: " build complete " },
      { text: "— 1.24 MB gzipped", tone: "muted" },
    ],
  },
  {
    kind: "output",
    content: [
      { text: "✓", tone: "success" },
      { text: " live at " },
      { text: "https://my-app.example.com", tone: "string" },
    ],
  },
  { kind: "command", content: "" },
];

/* --------------------------------------------------------------- timing */

const BASE_CPS = 42; // characters per second at speed = 1
const COMMAND_HOLD = 0.42; // pause after a command finishes typing, before output
const OUTPUT_STEP = 0.16; // gap between successive line reveals
const END_HOLD = 1.8; // rest at the end before a loop restarts

/* --------------------------------------------------------------- helpers */

function toneColor(tone: TelegraphTone = "default"): string {
  switch (tone) {
    case "muted":
      return "rgba(245,243,237,0.42)";
    case "accent":
      return "var(--tg-accent)";
    case "success":
      return "#7ee0b0";
    case "info":
      return "#9ec5fb";
    case "warn":
      return "#f2c879";
    case "error":
      return "#f0a1a1";
    case "string":
      return "color-mix(in oklab, var(--tg-accent) 58%, white)";
    default:
      return "rgba(245,243,237,0.92)";
  }
}

function normalize(content: string | TelegraphSegment[]): TelegraphSegment[] {
  if (typeof content === "string") return content ? [{ text: content }] : [];
  return content;
}

function lineLength(segments: TelegraphSegment[]): number {
  return segments.reduce((n, s) => n + s.text.length, 0);
}

/** First `count` characters across the segments, preserving each segment's tone. */
function sliceSegments(segments: TelegraphSegment[], count: number): TelegraphSegment[] {
  const out: TelegraphSegment[] = [];
  let remaining = count;
  for (const seg of segments) {
    if (remaining <= 0) break;
    const take = Math.min(seg.text.length, remaining);
    out.push(take === seg.text.length ? seg : { ...seg, text: seg.text.slice(0, take) });
    remaining -= take;
  }
  return out;
}

interface Scheduled {
  segments: TelegraphSegment[];
  kind: "command" | "output";
  prompt: string;
  length: number;
  /** When this line begins, in seconds from session start. */
  start: number;
  /** Seconds to type this line's characters (0 for output). */
  typeDuration: number;
}

/* ------------------------------------------------------------- component */

/**
 * Telegraph — a self-contained terminal that types a scripted session on its
 * own. macOS-style window chrome frames a charcoal screen; command lines type
 * out character-by-character behind a cool prompt sigil with a blinking block
 * caret, and output lines fade in whole, auto-sequenced so each waits for the
 * one before it. Playback starts when the terminal scrolls into view and runs
 * a single rAF that only ticks the active line — it pauses offscreen and on
 * hidden tabs. Every glyph is real, selectable DOM text; a screen reader hears
 * the finished transcript once. Under reduced motion (or `paused`) the whole
 * session renders statically with no typing.
 */
export function Telegraph({
  lines = DEFAULT_LINES,
  title = DEFAULT_TITLE,
  prompt = "$",
  accent = DEFAULT_ACCENT,
  speed = 1,
  startDelay = 0.3,
  loop = false,
  paused = false,
  className,
  style,
  ...props
}: TelegraphProps) {
  const reducedMotion = useReducedMotion();
  const still = reducedMotion || paused;

  // Build the deterministic timeline once per lines/speed/prompt change.
  const { schedule, total } = React.useMemo(() => {
    const cps = BASE_CPS * Math.max(speed, 0.05);
    let cursor = 0;
    const out: Scheduled[] = lines.map((line) => {
      const segments = normalize(line.content);
      const length = lineLength(segments);
      const start = cursor;
      let typeDuration = 0;
      if (line.kind === "command") {
        typeDuration = length / cps;
        cursor = start + typeDuration + COMMAND_HOLD / Math.max(speed, 0.05);
      } else {
        cursor = start + OUTPUT_STEP / Math.max(speed, 0.05);
      }
      return {
        segments,
        kind: line.kind,
        prompt: line.prompt ?? prompt,
        length,
        start,
        typeDuration,
      };
    });
    return { schedule: out, total: cursor };
  }, [lines, speed, prompt]);

  const count = schedule.length;

  // Current frame: which line is active, how many of its chars are shown,
  // and whether the session has completed. Kept minimal so the rAF only
  // re-renders when the visible output actually changes.
  const [frame, setFrame] = React.useState({ visible: 0, chars: 0, done: false });
  const [finished, setFinished] = React.useState(false);
  const sigRef = React.useRef("");

  const tick = React.useCallback(
    (elapsed: number) => {
      let t = elapsed - startDelay;
      let done = false;
      if (loop) {
        t = ((t % (total + END_HOLD)) + total + END_HOLD) % (total + END_HOLD);
      }
      if (t < 0) t = 0;
      if (!loop && t >= total) done = true;

      // Last line whose start has passed.
      let visible = 0;
      for (let i = 0; i < count; i++) {
        if (schedule[i].start <= t) visible = i;
        else break;
      }

      const active = schedule[visible];
      let chars = active.length;
      if (active.kind === "command" && t < active.start + active.typeDuration) {
        chars = Math.max(0, Math.floor((t - active.start) * BASE_CPS * Math.max(speed, 0.05)));
      }

      const sig = `${visible}:${chars}:${done ? 1 : 0}`;
      if (sig !== sigRef.current) {
        sigRef.current = sig;
        setFrame({ visible, chars, done });
      }
      if (done && !loop && !finished) setFinished(true);
    },
    [schedule, total, count, startDelay, speed, loop, finished]
  );

  // Single rAF, view-gated + tab-gated by the hook. It stops entirely once the
  // (non-looping) session has finished — the resting caret blink is pure CSS.
  const containerRef = useVisibilityPause<HTMLElement>(tick, {
    paused: still || (finished && !loop),
  });

  // Reset when the source or speed changes so a new session replays cleanly.
  React.useEffect(() => {
    sigRef.current = "";
    setFrame({ visible: 0, chars: 0, done: false });
    setFinished(false);
  }, [schedule]);

  const transcript = React.useMemo(
    () =>
      schedule
        .map((l) => {
          const body = l.segments.map((s) => s.text).join("");
          return l.kind === "command" ? `${l.prompt} ${body}`.trimEnd() : body;
        })
        .join("\n"),
    [schedule]
  );

  const restIndex = lastCommandIndex(schedule);

  const renderLine = (
    line: Scheduled,
    segments: TelegraphSegment[],
    caret: boolean,
    fade: boolean,
    key: number
  ) => (
    <div key={key} className={cn("whitespace-pre", fade && !still && "tg-in")}>
      {line.kind === "command" && (
        <span className="tg-sigil" aria-hidden>
          {line.prompt}{" "}
        </span>
      )}
      {segments.map((seg, i) => (
        <span key={i} style={{ color: toneColor(seg.tone) }}>
          {seg.text}
        </span>
      ))}
      {caret && <span className="tg-caret" aria-hidden />}
    </div>
  );

  // The visible screen. Static (reduced motion / paused) renders the whole
  // transcript with the caret parked on the final command line.
  const body = still
    ? schedule.map((line, i) => {
        const lastCommand = line.kind === "command" && i === restIndex;
        return renderLine(line, line.segments, lastCommand, false, i);
      })
    : schedule.slice(0, frame.visible + 1).map((line, i) => {
        const isActive = i === frame.visible;
        const fullyTyped = !isActive || line.kind === "output" || frame.chars >= line.length;
        const shown =
          isActive && line.kind === "command" && !fullyTyped
            ? sliceSegments(line.segments, frame.chars)
            : line.segments;
        // Caret rides the active command line while typing/holding; when the
        // session is done it parks on the final command line.
        const caret =
          line.kind === "command" && (isActive || (frame.done && i === restIndex));
        const fade = line.kind === "output";
        return renderLine(line, shown, caret, fade, i);
      });

  const lineBoxHeight = `${count * 1.55 + 1.5}rem`;

  return (
    <figure
      ref={containerRef as React.RefObject<HTMLElement>}
      data-crucible="telegraph"
      aria-label={`Terminal session: ${title}`}
      className={cn(
        "not-prose w-full max-w-xl overflow-hidden rounded-xl border border-white/10",
        "bg-neutral-900/85 shadow-[0_28px_70px_-30px_rgba(0,0,0,0.85)] backdrop-blur-sm",
        className
      )}
      style={{ ["--tg-accent" as string]: accent, ...style }}
      {...props}
    >
      <style>{`
        [data-crucible="telegraph"] .tg-sigil {
          color: var(--tg-accent);
          text-shadow: 0 0 10px color-mix(in oklab, var(--tg-accent) 45%, transparent);
        }
        [data-crucible="telegraph"] .tg-caret {
          display: inline-block;
          width: 0.6em;
          height: 1.05em;
          margin-left: 0.06em;
          vertical-align: text-bottom;
          background: rgba(245,243,237,0.9);
          box-shadow: 0 0 8px 1px color-mix(in oklab, var(--tg-accent) 40%, transparent);
          animation: tg-blink 1.05s steps(1) infinite;
        }
        [data-crucible="telegraph"] .tg-in {
          animation: tg-in 0.32s ease-out both;
        }
        @keyframes tg-blink { 0%,52% { opacity: 1 } 53%,100% { opacity: 0 } }
        @keyframes tg-in { from { opacity: 0; transform: translateY(3px) } to { opacity: 1; transform: none } }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="telegraph"] .tg-caret { animation: none; opacity: 0.5 }
          [data-crucible="telegraph"] .tg-in { animation: none }
        }
      `}</style>

      {/* Title bar with macOS-style controls (neutral, brand-agnostic). */}
      <figcaption className="flex items-center gap-2 border-b border-white/8 bg-white/2 px-3.5 py-2.5">
        <span aria-hidden className="flex gap-1.5">
          <span className="h-3 w-3 rounded-full bg-white/15" />
          <span className="h-3 w-3 rounded-full bg-white/15" />
          <span className="h-3 w-3 rounded-full bg-white/15" />
        </span>
        <span className="mx-auto truncate px-2 font-mono text-xs text-white/40">{title}</span>
        <span aria-hidden className="h-3 w-3" />
      </figcaption>

      {/* Screen-reader transcript — read once; the animated screen is decorative. */}
      <span className="sr-only">{transcript}</span>

      <div
        aria-hidden
        className="overflow-x-auto px-4 py-3.5 font-mono text-[13px] leading-[1.55] sm:px-5 sm:py-4"
        style={{ minHeight: lineBoxHeight }}
      >
        {body}
      </div>
    </figure>
  );
}

/** Index of the last command line (where the resting caret parks), or -1. */
function lastCommandIndex(schedule: Scheduled[]): number {
  for (let i = schedule.length - 1; i >= 0; i--) {
    if (schedule[i].kind === "command") return i;
  }
  return -1;
}

"use client";

import {
  AnimatePresence,
  animate,
  motion,
  useInView,
  useMotionValue,
  useMotionValueEvent,
  useTransform,
  type AnimationPlaybackControls,
} from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/* -------------------------------------------------------------------------- */
/*                                   shared                                   */
/* -------------------------------------------------------------------------- */

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** Picks a legible ink (near-black or white) for text drawn on `hex`. */
function inkOn(color: string): string {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
  if (!m) return "#0a0a0a";
  let h = m[1];
  if (h.length === 3) h = h.replace(/./g, (c) => c + c);
  const lin = (i: number) => {
    const c = parseInt(h.slice(i, i + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  const L = 0.2126 * lin(0) + 0.7152 * lin(2) + 0.0722 * lin(4);
  // Contrast against black vs white — whichever wins.
  return (L + 0.05) / 0.05 >= 1.05 / (L + 0.05) ? "#0a0a0a" : "#ffffff";
}

const SPRING = { type: "spring", stiffness: 520, damping: 38, mass: 0.9 } as const;
const SOFT = { type: "spring", stiffness: 300, damping: 30 } as const;
const QUICK = { duration: 0.14, ease: "easeOut" } as const;

/* -------------------------------------------------------------------------- */
/*                                    Throw                                   */
/* -------------------------------------------------------------------------- */

/** Imperative handle for {@link Throw}. */
export interface ThrowHandle {
  /** Return the knob to the start and clear the committed state. */
  reset(): void;
  /** Move keyboard focus to the knob. */
  focus(): void;
}

export interface ThrowProps {
  /** Instruction text inside the track; also the slider's accessible name. @default "Slide to confirm" */
  label?: string;
  /** Text shown in the filled track once committed. @default "Done" */
  committedLabel?: string;
  /** Fires once when the knob is thrown past the threshold (or Enter is pressed at the end). */
  onCommit?: () => void;
  /** Fraction of the travel (0–1) the knob must pass on release to commit. @default 0.85 */
  threshold?: number;
  /** Fill colour behind the knob and of the committed track. Any CSS colour; hex gets auto-contrast ink. @default "#f5f5f5" */
  accentColor?: string;
  /** Disable dragging and keys. @default false */
  disabled?: boolean;
  /** Idle hint — the knob nudges forward every few seconds until first touched. @default true */
  hint?: boolean;
  /** Freeze the shimmer and idle hint. @default false */
  paused?: boolean;
  className?: string;
  /** Imperative handle — `{ reset(), focus() }`. */
  ref?: React.Ref<ThrowHandle>;
}

const KNOB = 48;
const PAD = 4;

/**
 * Throw — a slide-to-commit track. Drag the knob (or use the arrow keys) to the
 * end: past `threshold` on release it snaps home and commits, the track floods
 * with the accent, the knob turns into a check. Released early it springs back.
 * The instruction label shimmers and fades as the knob passes over it.
 *
 * Accessibility: the knob is a `role="slider"` (0–100, with valuetext);
 * Arrow/PageUp/PageDown/Home/End move it and Enter or Space commits once it sits
 * at 100%. Reduced motion drops the shimmer, springs and idle hint.
 */
export function Throw({
  label = "Slide to confirm",
  committedLabel = "Done",
  onCommit,
  threshold = 0.85,
  accentColor = "#f5f5f5",
  disabled = false,
  hint = true,
  paused = false,
  className,
  ref,
}: ThrowProps) {
  const reduced = useReducedMotion();
  const still = reduced || paused;
  const trackRef = React.useRef<HTMLDivElement>(null);
  const knobRef = React.useRef<HTMLDivElement>(null);
  const inView = useInView(trackRef, { amount: 0.4 });
  const descId = React.useId();

  const x = useMotionValue(0);
  const max = useMotionValue(0);
  const progress = useTransform([x, max], ([a, b]: number[]) => (b > 0 ? clamp(a / b, 0, 1) : 0));
  const fillW = useTransform(x, (v) => v + KNOB);
  const labelOpacity = useTransform(progress, [0, 0.55], [1, 0]);
  const labelShift = useTransform(progress, [0, 1], [0, 18]);

  const [committed, setCommitted] = React.useState(false);
  const [pct, setPct] = React.useState(0);
  const [dragging, setDragging] = React.useState(false);
  const [armed, setArmed] = React.useState(false);
  const [flash, setFlash] = React.useState(0);

  const anim = React.useRef<AnimationPlaybackControls | null>(null);
  const touched = React.useRef(false);
  const drag = React.useRef<{ id: number; sx: number; start: number } | null>(null);
  const committedRef = React.useRef(false);
  const onCommitRef = React.useRef(onCommit);
  React.useEffect(() => {
    onCommitRef.current = onCommit;
  });

  const run = React.useCallback(
    (to: number | number[], t: object) => {
      anim.current?.stop();
      anim.current = animate(x, to as number, t);
    },
    [x]
  );

  // Track width → travel. A committed knob stays pinned to the end on resize.
  React.useLayoutEffect(() => {
    const el = trackRef.current;
    if (!el) return;
    const measure = () => {
      const m = Math.max(0, el.clientWidth - KNOB - PAD * 2);
      max.set(m);
      if (committedRef.current) x.set(m);
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [max, x]);

  useMotionValueEvent(progress, "change", (p) => {
    if (drag.current) setArmed(p >= threshold);
  });

  const commit = React.useCallback(() => {
    if (committedRef.current) return;
    committedRef.current = true;
    touched.current = true;
    setCommitted(true);
    setArmed(false);
    setPct(100);
    setFlash((n) => n + 1);
    run(max.get(), still ? QUICK : SOFT);
    onCommitRef.current?.();
  }, [max, run, still]);

  const goTo = React.useCallback(
    (p: number) => {
      const next = clamp(p, 0, 1);
      setPct(Math.round(next * 100));
      run(next * max.get(), still ? QUICK : SPRING);
    },
    [max, run, still]
  );

  const reset = React.useCallback(() => {
    committedRef.current = false;
    setCommitted(false);
    setArmed(false);
    setPct(0);
    run(0, still ? QUICK : SOFT);
  }, [run, still]);

  React.useImperativeHandle(
    ref,
    () => ({ reset, focus: () => knobRef.current?.focus() }),
    [reset]
  );

  // Idle hint: a seeded-cadence nudge that teaches the gesture. Also serves as
  // the designed intro (first nudge lands shortly after the track enters view).
  React.useEffect(() => {
    if (!hint || still || disabled || committed || !inView) return;
    let timer = 0;
    const tease = () => {
      const el = knobRef.current;
      if (
        touched.current ||
        committedRef.current ||
        drag.current ||
        (el && document.activeElement === el)
      )
        return;
      const m = max.get();
      run([0, m * 0.24, 0], { duration: 1.15, times: [0, 0.38, 1], ease: ["easeOut", [0.5, 0, 0.2, 1]] });
      timer = window.setTimeout(tease, 4200);
    };
    timer = window.setTimeout(tease, 700);
    return () => window.clearTimeout(timer);
  }, [hint, still, disabled, committed, inView, max, run]);

  React.useEffect(() => () => anim.current?.stop(), []);

  /* ------------------------------- pointer -------------------------------- */

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled || committedRef.current || e.button !== 0) return;
    e.preventDefault();
    touched.current = true;
    anim.current?.stop();
    e.currentTarget.setPointerCapture(e.pointerId);
    e.currentTarget.focus({ preventScroll: true });
    drag.current = { id: e.pointerId, sx: e.clientX, start: x.get() };
    setDragging(true);
  };
  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    const m = max.get();
    const nx = clamp(d.start + e.clientX - d.sx, 0, m);
    x.set(nx);
    setPct(m > 0 ? Math.round((nx / m) * 100) : 0);
  };
  const endDrag = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    setDragging(false);
    setArmed(false);
    if (progress.get() >= threshold) commit();
    else goTo(0);
  };

  /* ------------------------------ keyboard -------------------------------- */

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    if (committedRef.current) return;
    const p = pct / 100;
    const big = e.shiftKey ? 0.25 : 0.1;
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = p + big;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = p - big;
        break;
      case "PageUp":
        next = p + 0.25;
        break;
      case "PageDown":
        next = p - 0.25;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = 1;
        break;
      case "Enter":
      case " ":
        e.preventDefault();
        if (pct >= 100) commit();
        return;
      default:
        return;
    }
    e.preventDefault();
    touched.current = true;
    goTo(next);
  };

  // A half-thrown knob left by the keyboard slides home when focus leaves.
  const onBlur = () => {
    if (!committedRef.current && !drag.current && pct > 0) goTo(0);
  };

  const valueText = committed
    ? committedLabel
    : pct >= 100
      ? "At the end — press Enter to commit"
      : `${pct}%`;

  const ink = inkOn(accentColor);
  const tint = (a: number) => `color-mix(in srgb, ${accentColor} ${a}%, transparent)`;

  return (
    <div
      ref={trackRef}
      data-crucible="throw"
      data-committed={committed || undefined}
      className={cn(
        "relative isolate h-14 w-full max-w-xs touch-pan-y select-none rounded-full",
        "border border-white/[0.07] bg-neutral-900",
        "shadow-[inset_0_2px_6px_rgba(0,0,0,0.55),inset_0_-1px_0_rgba(255,255,255,0.04),0_1px_0_rgba(255,255,255,0.03)]",
        disabled && "opacity-50",
        className
      )}
    >
      {/* Instruction label — shimmers, then fades and drifts as the knob passes. */}
      <motion.span
        aria-hidden
        className="pointer-events-none absolute inset-0 flex items-center justify-center pl-12 pr-4 text-sm font-medium tracking-wide"
        style={{ opacity: labelOpacity, x: labelShift }}
      >
        <motion.span
          className="truncate"
          style={
            still
              ? { color: "#a3a3a3" }
              : {
                  color: "transparent",
                  backgroundImage:
                    "linear-gradient(105deg, #6b6b6b 0%, #6b6b6b 38%, #fafafa 50%, #6b6b6b 62%, #6b6b6b 100%)",
                  backgroundSize: "260% 100%",
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                }
          }
          animate={still || !inView ? undefined : { backgroundPosition: ["100% 0%", "0% 0%"] }}
          transition={{ duration: 2.6, ease: "linear", repeat: Infinity, repeatDelay: 0.4 }}
        >
          {label}
        </motion.span>
      </motion.span>

      {/* Fill — trails the knob; floods solid on commit. */}
      <motion.span
        aria-hidden
        className="pointer-events-none absolute rounded-full"
        style={{
          top: PAD - 1,
          bottom: PAD - 1,
          left: PAD - 1,
          width: committed ? `calc(100% - ${(PAD - 1) * 2}px)` : fillW,
          background: committed
            ? accentColor
            : `linear-gradient(90deg, ${tint(6)}, ${tint(armed ? 42 : 26)})`,
          boxShadow: committed ? `0 0 24px -6px ${tint(70)}` : `inset 0 0 0 1px ${tint(14)}`,
          transition: still ? "none" : "background 240ms ease, box-shadow 240ms ease",
        }}
      />

      {/* Committed label, inked for contrast on the accent. */}
      <AnimatePresence>
        {committed && (
          <motion.span
            aria-hidden
            key="done"
            className="pointer-events-none absolute inset-0 flex items-center justify-center pr-12 text-sm font-semibold tracking-wide"
            style={{ color: ink }}
            initial={still ? { opacity: 0 } : { opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0 }}
            transition={still ? QUICK : { duration: 0.32, ease: "easeOut", delay: 0.08 }}
          >
            {committedLabel}
          </motion.span>
        )}
      </AnimatePresence>

      {/* One-shot ring flash on commit. */}
      {!still && flash > 0 && (
        <motion.span
          key={flash}
          aria-hidden
          className="pointer-events-none absolute -inset-px rounded-full"
          style={{ boxShadow: `0 0 0 1.5px ${accentColor}, 0 0 28px ${tint(55)}` }}
          initial={{ opacity: 0.9, scale: 1 }}
          animate={{ opacity: 0, scale: 1.06 }}
          transition={{ duration: 0.7, ease: "easeOut" }}
        />
      )}

      {/* Knob — the slider itself. */}
      <motion.div
        ref={knobRef}
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={label}
        aria-describedby={descId}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={pct}
        aria-valuetext={valueText}
        aria-disabled={disabled || undefined}
        aria-readonly={committed || undefined}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onKeyDown={onKeyDown}
        onBlur={onBlur}
        className={cn(
          "absolute flex items-center justify-center rounded-full outline-none",
          "focus-visible:ring-2 focus-visible:ring-white/70 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
          disabled ? "cursor-not-allowed" : committed ? "cursor-default" : dragging ? "cursor-grabbing" : "cursor-grab"
        )}
        style={{
          top: PAD,
          left: PAD,
          width: KNOB,
          height: KNOB,
          x,
          touchAction: "none",
          background: committed
            ? "#0a0a0a"
            : "linear-gradient(180deg, #ffffff 0%, #e7e7e7 100%)",
          color: committed ? accentColor : "#171717",
          boxShadow: committed
            ? "0 1px 2px rgba(0,0,0,0.4), inset 0 0 0 1px rgba(255,255,255,0.08)"
            : "0 4px 14px -2px rgba(0,0,0,0.65), 0 1px 2px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.9)",
        }}
        animate={{ scale: still ? 1 : dragging ? (armed ? 1.06 : 0.97) : 1 }}
        transition={still ? { duration: 0 } : SPRING}
      >
        <AnimatePresence initial={false} mode="popLayout">
          {committed ? (
            <motion.svg
              key="check"
              aria-hidden
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.4"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="h-5 w-5"
              initial={still ? { opacity: 0 } : { opacity: 0, scale: 0.4, rotate: -30 }}
              animate={{ opacity: 1, scale: 1, rotate: 0 }}
              exit={{ opacity: 0 }}
              transition={still ? QUICK : SPRING}
            >
              <motion.path
                d="M5 12.5l4.5 4.5L19 7.5"
                initial={still ? false : { pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={still ? { duration: 0 } : { duration: 0.34, ease: "easeOut", delay: 0.06 }}
              />
            </motion.svg>
          ) : (
            <motion.svg
              key="arrow"
              aria-hidden
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="h-5 w-5"
              initial={still ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.6 }}
              transition={still ? QUICK : SPRING}
            >
              <path d="M6 7l5 5-5 5" opacity={0.45} />
              <path d="M12 7l5 5-5 5" />
            </motion.svg>
          )}
        </AnimatePresence>
      </motion.div>

      <span id={descId} className="sr-only">
        Drag the handle to the end, or use the arrow keys to reach 100% and press Enter.
      </span>
      <span role="status" aria-live="polite" className="sr-only">
        {committed ? committedLabel : ""}
      </span>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*                                  ThrowRow                                  */
/* -------------------------------------------------------------------------- */

/** One swipe action. The first action on a side is that side's primary. */
export interface ThrowAction {
  /** Visible caption and accessible name. */
  label: string;
  /** Icon node (≈18px, uses `currentColor`). */
  icon?: React.ReactNode;
  /** Background colour of the action well. @default "#404040" (primary) / "#262626" */
  color?: string;
  /** Called when the action is chosen (after the row collapses, when it collapses). */
  onAction: () => void;
}

type Side = "leading" | "trailing";

/** Imperative handle for {@link ThrowRow}. */
export interface ThrowRowHandle {
  /** Slide a side's actions into view. */
  open(side: Side): void;
  /** Slide the row closed. */
  close(): void;
  /** Un-collapse a row whose action has fired and close it. */
  reset(): void;
}

export interface ThrowRowProps {
  /** Row content — the sliding foreground surface. */
  children: React.ReactNode;
  /** Actions revealed by swiping right (they sit on the left edge). */
  leading?: ThrowAction | ThrowAction[];
  /** Actions revealed by swiping left (they sit on the right edge). */
  trailing?: ThrowAction | ThrowAction[];
  /** A swipe past 60% of the row fires that side's primary action. @default true */
  fullSwipe?: boolean;
  /** Collapse the row (height spring) before firing an action. @default true */
  collapseOnAction?: boolean;
  /** Idle hint — the row briefly peeks its trailing (else leading) actions until touched. @default false */
  peek?: boolean;
  /** Accessible name for the row. Defaults to its text content. */
  label?: string;
  /** Class for the outer wrapper. */
  className?: string;
  /** Class for the sliding foreground surface. */
  contentClassName?: string;
  /** Imperative handle — `{ open(side), close(), reset() }`. */
  ref?: React.Ref<ThrowRowHandle>;
}

const ACTION_W = 76;
const FULL = 0.6;

const asList = (a?: ThrowAction | ThrowAction[]) => (a ? (Array.isArray(a) ? a : [a]) : []);

/** Exponential rubber band: grows quickly at first, saturates near `limit`. */
const rubber = (over: number, limit: number) => limit * (1 - Math.exp(-over / (limit * 1.6)));

/**
 * ThrowRow — a list row that slides to reveal actions. Swipe left for trailing
 * actions, right for leading ones; travel past the actions is rubber-banded,
 * the icons scale in as they're uncovered, and a full swipe past 60% fires the
 * side's primary action: the row flies out and collapses on a height spring.
 *
 * Keyboard: the row is focusable; ArrowLeft / ArrowRight reveal actions and
 * move focus into them (Enter activates), Escape or the opposite arrow closes.
 * Reduced motion: no rubber band or springs — short tweens only.
 */
export function ThrowRow({
  children,
  leading,
  trailing,
  fullSwipe = true,
  collapseOnAction = true,
  peek = false,
  label,
  className,
  contentClassName,
  ref,
}: ThrowRowProps) {
  const reduced = useReducedMotion();
  const lead = asList(leading);
  const trail = asList(trailing);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const rowRef = React.useRef<HTMLDivElement>(null);
  const leadRef = React.useRef<HTMLDivElement>(null);
  const trailRef = React.useRef<HTMLDivElement>(null);
  const inView = useInView(rootRef, { amount: 0.6 });
  const descId = React.useId();

  const x = useMotionValue(0);
  const leadW = useTransform(x, (v) => Math.max(0, v));
  const trailW = useTransform(x, (v) => Math.max(0, -v));
  const leadIcon = useTransform(leadW, [0, ACTION_W * 0.9], [0.35, 1], { clamp: true });
  const trailIcon = useTransform(trailW, [0, ACTION_W * 0.9], [0.35, 1], { clamp: true });
  const leadOp = useTransform(leadW, [8, ACTION_W * 0.7], [0, 1], { clamp: true });
  const trailOp = useTransform(trailW, [8, ACTION_W * 0.7], [0, 1], { clamp: true });
  // Captions wait until each action has room for them (no cramped half-words).
  const leadN = useMotionValue(lead.length);
  const trailN = useMotionValue(trail.length);
  React.useEffect(() => {
    leadN.set(lead.length);
    trailN.set(trail.length);
  }, [lead.length, trail.length, leadN, trailN]);
  const cap = ([w, n]: number[]) =>
    clamp((w / Math.max(1, n) - ACTION_W * 0.62) / (ACTION_W * 0.3), 0, 1);
  const leadCap = useTransform([leadW, leadN], cap);
  const trailCap = useTransform([trailW, trailN], cap);

  const [open, setOpen] = React.useState<Side | null>(null);
  const [armed, setArmed] = React.useState<Side | null>(null);
  const [firing, setFiring] = React.useState<{ side: Side; index: number } | null>(null);
  const [collapsed, setCollapsed] = React.useState(false);

  const anim = React.useRef<AnimationPlaybackControls | null>(null);
  const touched = React.useRef(false);
  const dragged = React.useRef(false);
  const focusInto = React.useRef<Side | null>(null);
  const pending = React.useRef<ThrowAction | null>(null);
  const drag = React.useRef<{
    id: number;
    sx: number;
    sy: number;
    start: number;
    decided: boolean;
    w: number;
    lx: number;
    lt: number;
    v: number;
  } | null>(null);

  const actionsFor = (s: Side) => (s === "leading" ? lead : trail);
  const sign = (s: Side) => (s === "leading" ? 1 : -1);

  const run = React.useCallback(
    (to: number | number[], t: object) => {
      anim.current?.stop();
      anim.current = animate(x, to as number, t);
    },
    [x]
  );

  const close = React.useCallback(() => {
    setOpen(null);
    setArmed(null);
    run(0, reduced ? QUICK : SPRING);
  }, [reduced, run]);

  const openSide = React.useCallback(
    (s: Side) => {
      const n = (s === "leading" ? lead : trail).length;
      if (!n) return;
      setOpen(s);
      setArmed(null);
      run(sign(s) * n * ACTION_W, reduced ? QUICK : SPRING);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [lead.length, trail.length, reduced, run]
  );

  const fire = (s: Side, index: number) => {
    const action = actionsFor(s)[index];
    if (!action || firing) return;
    touched.current = true;
    setFiring({ side: s, index });
    setArmed(null);
    if (!collapseOnAction) {
      action.onAction();
      window.setTimeout(() => {
        setFiring(null);
        close();
      }, reduced ? 60 : 220);
      return;
    }
    pending.current = action;
    const w = rowRef.current?.offsetWidth ?? 320;
    run(sign(s) * w, {
      ...(reduced ? QUICK : { duration: 0.24, ease: [0.4, 0, 0.6, 1] }),
      onComplete: () => setCollapsed(true),
    });
  };

  const reset = React.useCallback(() => {
    pending.current = null;
    setFiring(null);
    setCollapsed(false);
    setOpen(null);
    setArmed(null);
    anim.current?.stop();
    x.set(0);
  }, [x]);

  React.useImperativeHandle(ref, () => ({ open: openSide, close, reset }), [openSide, close, reset]);

  // Focus the revealed panel's first action after a keyboard reveal.
  React.useEffect(() => {
    const s = focusInto.current;
    if (!s || open !== s) return;
    focusInto.current = null;
    (s === "leading" ? leadRef : trailRef).current?.querySelector<HTMLButtonElement>("button")?.focus();
  }, [open]);

  // Tap / press outside closes an open row.
  React.useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) close();
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [open, close]);

  // Idle peek — teaches that the row swipes.
  const peekSide: Side | null = trail.length ? "trailing" : lead.length ? "leading" : null;
  React.useEffect(() => {
    if (!peek || reduced || !inView || !peekSide || collapsed) return;
    let timer = 0;
    const go = () => {
      if (touched.current || drag.current || open || firing) return;
      const d = sign(peekSide) * ACTION_W * 0.85;
      run([0, d, d, 0], { duration: 1.6, times: [0, 0.3, 0.55, 1], ease: ["easeOut", "linear", [0.5, 0, 0.2, 1]] });
      timer = window.setTimeout(go, 6000);
    };
    timer = window.setTimeout(go, 1200);
    return () => window.clearTimeout(timer);
  }, [peek, reduced, inView, peekSide, collapsed, open, firing, run]);

  React.useEffect(() => () => anim.current?.stop(), []);

  /* ------------------------------- pointer -------------------------------- */

  const shape = (raw: number, w: number) => {
    const s: Side = raw >= 0 ? "leading" : "trailing";
    const n = actionsFor(s).length;
    const a = Math.abs(raw);
    if (!n) return reduced ? 0 : sign(s) * rubber(a, 28);
    const reach = fullSwipe ? w * 0.82 : n * ACTION_W;
    if (reduced) return sign(s) * Math.min(a, reach);
    return sign(s) * (a <= reach ? a : reach + rubber(a - reach, 40));
  };

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (firing || e.button !== 0) return;
    anim.current?.stop();
    dragged.current = false;
    drag.current = {
      id: e.pointerId,
      sx: e.clientX,
      sy: e.clientY,
      start: x.get(),
      decided: false,
      w: rowRef.current?.offsetWidth ?? 320,
      lx: e.clientX,
      lt: e.timeStamp,
      v: 0,
    };
  };
  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    const dx = e.clientX - d.sx;
    const dy = e.clientY - d.sy;
    if (!d.decided) {
      if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
      if (Math.abs(dy) > Math.abs(dx)) {
        drag.current = null; // vertical — let the page scroll
        return;
      }
      d.decided = true;
      dragged.current = true;
      touched.current = true;
      e.currentTarget.setPointerCapture(e.pointerId);
    }
    const dt = Math.max(1, e.timeStamp - d.lt);
    d.v = d.v * 0.6 + ((e.clientX - d.lx) / dt) * 1000 * 0.4;
    d.lx = e.clientX;
    d.lt = e.timeStamp;
    const nx = shape(d.start + dx, d.w);
    x.set(nx);
    const s: Side = nx >= 0 ? "leading" : "trailing";
    const isArmed = fullSwipe && actionsFor(s).length > 0 && Math.abs(nx) > d.w * FULL;
    setArmed(isArmed ? s : null);
  };
  const onPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    if (!d.decided) return;
    const cur = x.get();
    const s: Side = cur >= 0 ? "leading" : "trailing";
    const n = actionsFor(s).length;
    const a = Math.abs(cur);
    const toward = Math.sign(d.v) === sign(s);
    if (n && fullSwipe && a > d.w * FULL) return fire(s, 0);
    if (n && ((a > (n * ACTION_W) / 2 && !(Math.abs(d.v) > 500 && !toward)) || (toward && Math.abs(d.v) > 500)))
      return openSide(s);
    close();
  };

  /* ------------------------------ keyboard -------------------------------- */

  const onRowKey = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.target !== e.currentTarget || firing) return;
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      touched.current = true;
      const s: Side = e.key === "ArrowLeft" ? "trailing" : "leading";
      if (open && open !== s) return close();
      if (!actionsFor(s).length) return;
      focusInto.current = s;
      if (open === s) {
        (s === "leading" ? leadRef : trailRef).current?.querySelector<HTMLButtonElement>("button")?.focus();
        focusInto.current = null;
      } else openSide(s);
    } else if (e.key === "Escape" && open) {
      e.preventDefault();
      close();
    }
  };

  const onActionKey = (s: Side) => (e: React.KeyboardEvent<HTMLButtonElement>) => {
    const closeKey = s === "trailing" ? "ArrowRight" : "ArrowLeft";
    const buttons = Array.from(
      (s === "leading" ? leadRef : trailRef).current?.querySelectorAll<HTMLButtonElement>("button") ?? []
    );
    const i = buttons.indexOf(e.currentTarget);
    if (e.key === "Escape") {
      e.preventDefault();
      close();
      rowRef.current?.focus();
    } else if (e.key === closeKey) {
      e.preventDefault();
      // Step back toward the content; past the first action, close.
      if (i > 0) buttons[i - 1].focus();
      else {
        close();
        rowRef.current?.focus();
      }
    } else if (e.key === (s === "trailing" ? "ArrowLeft" : "ArrowRight")) {
      e.preventDefault();
      buttons[i + 1]?.focus();
    }
  };

  /* -------------------------------- render -------------------------------- */

  const panel = (s: Side) => {
    const acts = actionsFor(s);
    if (!acts.length) return null;
    const isLead = s === "leading";
    const hot = firing?.side === s ? firing.index : armed === s ? 0 : -1;
    const visible = open === s;
    return (
      <motion.div
        ref={isLead ? leadRef : trailRef}
        inert={!visible}
        className={cn(
          "absolute inset-y-0 flex overflow-hidden",
          isLead ? "left-0 flex-row" : "right-0 flex-row-reverse"
        )}
        style={{
          width: isLead ? leadW : trailW,
          background: hot >= 0 ? (acts[hot].color ?? "#404040") : "#171717",
          transition: reduced ? "none" : "background 160ms ease",
        }}
      >
        {acts.map((a, i) => {
          const bg = a.color ?? (i === 0 ? "#404040" : "#262626");
          const grow = hot < 0 ? 1 : hot === i ? 1 : 0;
          return (
            <button
              key={a.label}
              type="button"
              tabIndex={visible ? 0 : -1}
              aria-label={a.label}
              onClick={() => fire(s, i)}
              onKeyDown={onActionKey(s)}
              className={cn(
                "relative flex min-w-0 basis-0 flex-col items-center justify-center gap-1 overflow-hidden px-1 text-[11px] font-medium outline-none",
                "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-white/80"
              )}
              style={{
                background: bg,
                color: inkOn(bg),
                flexGrow: grow,
                transition: reduced ? "none" : "flex-grow 240ms cubic-bezier(.3,.7,.2,1)",
              }}
            >
              <motion.span
                className="flex w-[68px] flex-col items-center justify-center gap-1"
                style={{
                  scale: isLead ? leadIcon : trailIcon,
                  opacity: isLead ? leadOp : trailOp,
                }}
              >
                {a.icon && (
                  <motion.span
                    aria-hidden
                    className="flex h-5 w-5 items-center justify-center [&>svg]:h-[18px] [&>svg]:w-[18px]"
                    animate={{ scale: !reduced && hot === i ? 1.18 : 1 }}
                    transition={reduced ? { duration: 0 } : SPRING}
                  >
                    {a.icon}
                  </motion.span>
                )}
                <motion.span
                  className="truncate"
                  style={{ opacity: hot === i ? 1 : isLead ? leadCap : trailCap }}
                >
                  {a.label}
                </motion.span>
              </motion.span>
            </button>
          );
        })}
      </motion.div>
    );
  };

  const hasActions = lead.length + trail.length > 0;
  const hintText = [
    trail.length ? `Left arrow: ${trail.map((a) => a.label).join(", ")}` : null,
    lead.length ? `Right arrow: ${lead.map((a) => a.label).join(", ")}` : null,
  ]
    .filter(Boolean)
    .join(". ");

  return (
    <motion.div
      ref={rootRef}
      data-crucible="throw-row"
      className={cn("relative overflow-hidden", className)}
      initial={false}
      animate={collapsed ? { height: 0, opacity: 0 } : { height: "auto", opacity: 1 }}
      transition={reduced ? { duration: 0.12 } : { height: SOFT, opacity: { duration: 0.2 } }}
      onAnimationComplete={() => {
        if (!collapsed || !pending.current) return;
        const a = pending.current;
        pending.current = null;
        a.onAction();
      }}
    >
      {panel("leading")}
      {panel("trailing")}
      <motion.div
        ref={rowRef}
        tabIndex={collapsed ? -1 : 0}
        role="group"
        aria-roledescription="swipeable row"
        aria-label={label}
        aria-describedby={hasActions ? descId : undefined}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onClickCapture={(e) => {
          if (dragged.current) {
            e.preventDefault();
            e.stopPropagation();
            dragged.current = false;
          } else if (open) {
            e.stopPropagation();
            close();
          }
        }}
        onKeyDown={onRowKey}
        className={cn(
          "relative z-10 touch-pan-y select-none bg-neutral-900 outline-none",
          "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-white/60",
          contentClassName
        )}
        style={{ x }}
      >
        {children}
      </motion.div>
      {hasActions && (
        <span id={descId} className="sr-only">
          {hintText}. Escape closes.
        </span>
      )}
    </motion.div>
  );
}

"use client";

import { animate, motion, useMotionValue } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

/* -------------------------------------------------------------------------- */
/*                                    Types                                   */
/* -------------------------------------------------------------------------- */

/** A list-mode option: a plain string, or an object for custom labels. */
export type TumblerOption =
  | string
  | {
      /** Unique, stable value reported through `onValueChange`. */
      value: string;
      /** Visible label. @default value */
      label?: React.ReactNode;
      /** Plain text used for type-ahead matching when `label` is not a string. @default value */
      textValue?: string;
      /** Skip this row — the drum never settles on it. */
      disabled?: boolean;
    };

/** Imperative handle — see `TumblerProps.ref`. */
export interface TumblerHandle {
  /** Spin to a value (an option value in list mode, a number in number mode). */
  spinTo: (value: string | number) => void;
  /** Spin by `delta` rows (positive = next row). */
  step: (delta: number) => void;
  /** Re-run the intro spin-in. */
  replay: () => void;
  /** Move keyboard focus onto the drum. */
  focus: () => void;
}

interface TumblerBaseProps
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    "onChange" | "defaultValue" | "role" | "children"
  > {
  /** Wrap around past the last row back to the first. @default false */
  loop?: boolean;
  /** Rows visible on the drum (odd numbers center best). @default 5 — inside a `TumblerGroup` the group's value wins. */
  visibleRows?: number;
  /** Height of one row in px. @default 40 — inside a `TumblerGroup` the group's value wins. */
  rowHeight?: number;
  /** Accessible name for the drum. Or pass `aria-labelledby`. @default "Choose a value" */
  label?: string;
  /** The single accent: rule lines around the lit band + focus ring. @default "#a5b4fc" (periwinkle) — inside a group the group's accent wins. */
  accentColor?: string;
  /** Disable the drum (no pointer, wheel or keyboard input). @default false */
  disabled?: boolean;
  /** Seconds to wait before the intro spin-in — stagger drums in a group. @default 0 */
  introDelay?: number;
  /** Submit the value with a form under this field name (renders a hidden input). */
  name?: string;
  /** Imperative handle: `spinTo`, `step`, `replay`, `focus`. */
  ref?: React.Ref<TumblerHandle>;
}

interface TumblerListModeProps {
  /** `"list"` = a listbox of `options`; `"number"` = a spinbutton over `min`–`max`. @default "list" when `options` is set, else "number" */
  mode?: "list";
  /** The rows, top to bottom. */
  options: readonly TumblerOption[];
  /** Controlled selected value. */
  value?: string;
  /** Initial value when uncontrolled. @default first enabled option */
  defaultValue?: string;
  /** Fires when the drum commits to a new row (on release, notch or key — not mid-drag). */
  onValueChange?: (value: string) => void;
  min?: never;
  max?: never;
  step?: never;
  formatValue?: never;
}

interface TumblerNumberModeProps {
  /** `"list"` = a listbox of `options`; `"number"` = a spinbutton over `min`–`max`. @default "list" when `options` is set, else "number" */
  mode?: "number";
  options?: never;
  /** Lowest value (top row). @default 0 */
  min?: number;
  /** Highest value (bottom row). @default 59 */
  max?: number;
  /** Increment between rows. @default 1 */
  step?: number;
  /** Row label formatter, e.g. `(n) => String(n).padStart(2, "0")`. @default String */
  formatValue?: (value: number) => string;
  /** Controlled value. */
  value?: number;
  /** Initial value when uncontrolled. @default min */
  defaultValue?: number;
  /** Fires when the drum commits to a new row (on release, notch or key — not mid-drag). */
  onValueChange?: (value: number) => void;
}

export type TumblerProps = TumblerBaseProps &
  (TumblerListModeProps | TumblerNumberModeProps);

export interface TumblerGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Accessible name for the whole picker, e.g. "Time". */
  label?: string;
  /** Rows visible on every drum. @default 5 */
  visibleRows?: number;
  /** Row height in px for every drum. @default 40 */
  rowHeight?: number;
  /** Accent for the shared band's rule lines and focus rings. @default "#a5b4fc" */
  accentColor?: string;
  /** Drums and any separators (e.g. a ":" span). */
  children?: React.ReactNode;
}

/* -------------------------------------------------------------------------- */
/*                                  Geometry                                  */
/* -------------------------------------------------------------------------- */

const DEFAULT_ACCENT = "#a5b4fc";
/** Angle of the drum surface at the outer edge of the visible window. */
const EDGE_ANGLE = 75;
/** Seconds of flick momentum projected forward on release. */
const FLICK_TAU = 0.2;
const DEG = Math.PI / 180;

interface Geometry {
  rowHeight: number;
  half: number;
  /** Degrees between neighbouring rows. */
  theta: number;
  /** Drum radius in px. */
  radius: number;
  height: number;
  perspective: number;
  /** Rows either side of center that get rendered. */
  reach: number;
}

function geometry(visibleRows: number, rowHeight: number, flat: boolean): Geometry {
  const rows = Math.max(1, Math.round(visibleRows));
  const half = (rows - 1) / 2;
  if (flat) {
    return {
      rowHeight,
      half,
      theta: 0,
      radius: 0,
      height: rows * rowHeight,
      perspective: 0,
      reach: Math.ceil(half) + 1,
    };
  }
  const theta = Math.min(60, EDGE_ANGLE / (half + 0.5));
  // Chord between neighbours ≈ rowHeight, so the centre row is true size.
  const radius = rowHeight / (2 * Math.tan((theta / 2) * DEG));
  const height = Math.ceil(2 * radius * Math.sin(Math.min(88, (half + 0.5) * theta) * DEG)) + 8;
  return {
    rowHeight,
    half,
    theta,
    radius,
    height,
    perspective: Math.max(260, radius * 3.2),
    reach: Math.min(Math.ceil(90 / theta), Math.ceil(half) + 3),
  };
}

function rowStyle(offset: number, g: Geometry, flat: boolean): React.CSSProperties {
  const dist = Math.abs(offset);
  if (flat) {
    return {
      transform: `translate3d(0, ${offset * g.rowHeight}px, 0)`,
      opacity: dist > g.half + 0.5 ? 0 : Math.max(0.25, 1 - dist * 0.22),
      visibility: dist > g.half + 1 ? "hidden" : "visible",
    };
  }
  const angle = -offset * g.theta;
  const facing = Math.cos(angle * DEG);
  const visible = Math.abs(angle) < 89;
  return {
    transform: `translateZ(${-g.radius}px) rotateX(${angle}deg) translateZ(${g.radius}px)`,
    opacity: visible ? Math.pow(Math.max(0, facing), 1.15) : 0,
    filter: dist > 0.6 ? `blur(${Math.min(1.2, (dist - 0.6) * 0.4).toFixed(2)}px)` : undefined,
    visibility: visible ? "visible" : "hidden",
  };
}

const mod = (k: number, n: number) => ((k % n) + n) % n;

/* -------------------------------------------------------------------------- */
/*                                Group context                               */
/* -------------------------------------------------------------------------- */

interface GroupContextValue {
  visibleRows: number;
  rowHeight: number;
  accentColor: string;
}

const TumblerGroupContext = React.createContext<GroupContextValue | null>(null);

/* -------------------------------------------------------------------------- */
/*                                   Tumbler                                  */
/* -------------------------------------------------------------------------- */

interface NormalizedRow {
  key: string;
  label: React.ReactNode;
  text: string;
  disabled: boolean;
  /** List value (string) or number-mode value. */
  value: string | number;
}

/**
 * Tumbler — a 3D drum picker. Rows ride a cylinder (each row rotated about X by
 * its distance from centre and pushed out by the drum radius, under
 * perspective), falling away with opacity and a whisper of blur. Flick to spin
 * with momentum that lands on a detent; the centred row is lit between two
 * accent rule lines. Mouse drag, touch, wheel (one notch per row), click a
 * row, and full keyboard: Arrow keys, PageUp/PageDown (±5), Home/End and
 * type-ahead.
 *
 * Accessibility: list mode is a `role="listbox"` with `aria-activedescendant`
 * pointing at the selected `role="option"`; number mode is a
 * `role="spinbutton"` with `aria-valuenow/min/max/text` (ArrowUp increases).
 * Reduced motion: no rotation or inertia — a flat list with the selected row
 * highlighted, and every change snaps.
 *
 * Use `TumblerGroup` to stand several drums side by side under one shared
 * highlight band (time, dates).
 */
export function Tumbler(props: TumblerProps) {
  const {
    mode: modeProp,
    options,
    min: minProp,
    max: maxProp,
    step: stepProp,
    formatValue,
    value,
    defaultValue,
    onValueChange,
    loop = false,
    visibleRows: visibleRowsProp = 5,
    rowHeight: rowHeightProp = 40,
    label = "Choose a value",
    accentColor: accentProp = DEFAULT_ACCENT,
    disabled = false,
    introDelay = 0,
    name,
    ref,
    className,
    style,
    "aria-labelledby": ariaLabelledby,
    ...rest
  } = props;

  const group = React.useContext(TumblerGroupContext);
  const visibleRows = group?.visibleRows ?? visibleRowsProp;
  const rowHeight = group?.rowHeight ?? rowHeightProp;
  const accentColor = group?.accentColor ?? accentProp;

  const reducedMotion = useReducedMotion();
  const flat = reducedMotion;
  const g = React.useMemo(
    () => geometry(visibleRows, rowHeight, flat),
    [visibleRows, rowHeight, flat]
  );

  const mode: "list" | "number" = modeProp ?? (options ? "list" : "number");
  const isNumber = mode === "number";
  const min = minProp ?? 0;
  const max = maxProp ?? 59;
  const step = stepProp && stepProp > 0 ? stepProp : 1;

  /* ------------------------------ rows / values ----------------------------- */

  const decimals = (String(step).split(".")[1] ?? "").length;
  const count = isNumber
    ? Math.max(1, Math.floor((max - min) / step + 1e-9) + 1)
    : Math.max(1, options?.length ?? 0);


  const listRows = React.useMemo<NormalizedRow[] | null>(() => {
    if (isNumber) return null;
    const list = options ?? [];
    if (list.length === 0) return [{ key: "", label: "", text: "", disabled: true, value: "" }];
    return list.map((o) =>
      typeof o === "string"
        ? { key: o, label: o, text: o, disabled: false, value: o }
        : {
            key: o.value,
            label: o.label ?? o.value,
            text: o.textValue ?? (typeof o.label === "string" ? o.label : o.value),
            disabled: !!o.disabled,
            value: o.value,
          }
    );
  }, [isNumber, options]);

  const rowAt = React.useCallback(
    (index: number): NormalizedRow => {
      if (listRows) return listRows[index] ?? listRows[0];
      const v = Number((min + index * step).toFixed(decimals));
      const text = formatValue ? formatValue(v) : String(v);
      return { key: String(v), label: text, text, disabled: false, value: v };
    },
    [listRows, min, step, decimals, formatValue]
  );

  const indexOf = React.useCallback(
    (v: string | number | undefined): number => {
      if (v === undefined) return -1;
      if (listRows) return listRows.findIndex((r) => r.value === v);
      const n = typeof v === "number" ? v : Number(v);
      if (!Number.isFinite(n)) return -1;
      return Math.min(count - 1, Math.max(0, Math.round((n - min) / step)));
    },
    [listRows, count, min, step]
  );

  const firstEnabled = listRows ? Math.max(0, listRows.findIndex((r) => !r.disabled)) : 0;

  /* ---------------------------------- state --------------------------------- */

  const isControlled = value !== undefined;
  const [internalIndex, setInternalIndex] = React.useState(() => {
    const i = indexOf(defaultValue);
    return i >= 0 ? i : firstEnabled;
  });
  const controlledIndex = isControlled ? indexOf(value) : -1;
  const selectedIndex = isControlled
    ? controlledIndex >= 0
      ? controlledIndex
      : firstEnabled
    : Math.min(internalIndex, count - 1);

  /** Continuous drum position in rows (unbounded when looping). */
  const pos = useMotionValue(selectedIndex);
  /** Virtual row the drum is heading to / resting on. */
  const targetKRef = React.useRef(selectedIndex);
  const [targetK, setTargetK] = React.useState(selectedIndex);
  const [centerK, setCenterK] = React.useState(selectedIndex);
  const intro = useMotionValue(1);
  const animRef = React.useRef<{ stop: () => void } | null>(null);
  const introRanRef = React.useRef(false);

  const rootRef = React.useRef<HTMLDivElement>(null);

  const latest = React.useRef({ g, flat, count, loop, selectedIndex, isControlled, onValueChange });
  React.useLayoutEffect(() => {
    latest.current = { g, flat, count, loop, selectedIndex, isControlled, onValueChange };
  });

  /* ------------------------------ DOM painting ------------------------------ */

  const paint = React.useCallback((p: number) => {
    const { g: geo, flat: isFlat } = latest.current;
    rootRef.current?.querySelectorAll<HTMLElement>("[data-tumbler-row]").forEach((el) => {
      const s = rowStyle(Number(el.dataset.tumblerRow) - p, geo, isFlat);
      el.style.transform = s.transform as string;
      el.style.opacity = String(s.opacity);
      el.style.filter = (s.filter as string) ?? "";
      el.style.visibility = s.visibility as string;
    });
  }, []);

  React.useEffect(() => {
    paint(pos.get());
    return pos.on("change", (p) => {
      paint(p);
      const c = Math.round(p);
      setCenterK((prev) => (prev === c ? prev : c));
    });
  }, [pos, paint]);

  // Geometry flips (reduced motion, row height) repaint immediately.
  React.useLayoutEffect(() => {
    paint(pos.get());
  }, [g, flat, paint, pos]);

  /* ------------------------------- navigation ------------------------------- */

  const resolveEnabled = React.useCallback(
    (k: number, dir: number): number => {
      if (!listRows) return k;
      const n = listRows.length;
      const d = dir >= 0 ? 1 : -1;
      for (let i = 0; i < n; i++) {
        for (const cand of i === 0 ? [k] : [k + d * i, k - d * i]) {
          if (!loop && (cand < 0 || cand > n - 1)) continue;
          if (!listRows[mod(cand, n)]?.disabled) return cand;
        }
      }
      return k;
    },
    [listRows, loop]
  );

  const runTo = React.useCallback(
    (k: number, velocity = 0) => {
      animRef.current?.stop();
      if (latest.current.flat) {
        pos.set(k);
        return;
      }
      animRef.current = animate(pos, k, {
        type: "spring",
        stiffness: 210,
        damping: 26,
        mass: 0.9,
        velocity,
        restDelta: 0.001,
      });
    },
    [pos]
  );

  /** Commit to virtual row `k` and spin there. */
  const goTo = React.useCallback(
    (rawK: number, opts: { velocity?: number; dir?: number } = {}) => {
      const { count: n, loop: isLoop } = latest.current;
      let k = Math.round(rawK);
      if (!isLoop) k = Math.min(n - 1, Math.max(0, k));
      k = resolveEnabled(k, opts.dir ?? Math.sign(rawK - targetKRef.current));
      targetKRef.current = k;
      setTargetK(k);
      const index = mod(k, n);
      if (index !== latest.current.selectedIndex) {
        if (!latest.current.isControlled) setInternalIndex(index);
        const cb = latest.current.onValueChange as ((v: string | number) => void) | undefined;
        cb?.(rowAt(index).value);
      }
      runTo(k, opts.velocity ?? 0);
    },
    [resolveEnabled, rowAt, runTo]
  );

  /** Nearest virtual row (to the current position) that shows `index`. */
  const nearestK = React.useCallback(
    (index: number) => {
      const { count: n, loop: isLoop } = latest.current;
      if (!isLoop) return index;
      const p = pos.get();
      return index + Math.round((p - index) / n) * n;
    },
    [pos]
  );

  // External value changes (controlled mode or option-set changes) spin in.
  React.useEffect(() => {
    if (mod(targetKRef.current, count) === selectedIndex) return;
    const k = nearestK(selectedIndex);
    targetKRef.current = k;
    setTargetK(k);
    runTo(k);
  }, [selectedIndex, count, nearestK, runTo]);

  /* ---------------------------------- intro --------------------------------- */

  const playIntro = React.useCallback(() => {
    if (latest.current.flat) return;
    const { count: n, loop: isLoop } = latest.current;
    const k = targetKRef.current;
    const span = Math.min(4, Math.max(2, n - 1));
    const from = isLoop || k - span >= 0 ? k - span : k + span;
    animRef.current?.stop();
    pos.set(from);
    intro.set(0);
    animate(intro, 1, { duration: 0.45, ease: "easeOut", delay: introDelay });
    animRef.current = animate(pos, k, {
      type: "spring",
      stiffness: 90,
      damping: 17,
      mass: 1,
      delay: introDelay,
    });
  }, [pos, intro, introDelay]);

  React.useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el || introRanRef.current) return;
    const fire = () => {
      if (introRanRef.current) return;
      introRanRef.current = true;
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      playIntro();
    };
    const r = el.getBoundingClientRect();
    if (r.bottom > 0 && r.top < window.innerHeight && r.width > 0) {
      fire();
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          io.disconnect();
          fire();
        }
      },
      { threshold: 0.3 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [playIntro]);

  // Reduced motion mid-flight: drop any spin and sit on the target.
  React.useEffect(() => {
    if (!flat) return;
    animRef.current?.stop();
    intro.set(1);
    pos.set(targetKRef.current);
  }, [flat, pos, intro]);

  React.useEffect(() => () => animRef.current?.stop(), []);

  /* --------------------------------- handle --------------------------------- */

  React.useImperativeHandle(
    ref,
    () => ({
      spinTo: (v) => {
        const i = indexOf(v);
        if (i >= 0) goTo(nearestK(i));
      },
      step: (delta) => goTo(targetKRef.current + delta, { dir: Math.sign(delta) }),
      replay: playIntro,
      focus: () => rootRef.current?.focus(),
    }),
    [indexOf, goTo, nearestK, playIntro]
  );

  /* --------------------------------- pointer -------------------------------- */

  const drag = React.useRef<{
    id: number;
    startY: number;
    startPos: number;
    moved: boolean;
    samples: { t: number; y: number }[];
  } | null>(null);

  const rubber = (p: number) => {
    const { count: n, loop: isLoop } = latest.current;
    if (isLoop) return p;
    const band = (x: number) => (1 - 1 / (x * 0.6 + 1)) * 1.2;
    if (p < 0) return -band(-p);
    if (p > n - 1) return n - 1 + band(p - (n - 1));
    return p;
  };

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled || (e.pointerType === "mouse" && e.button !== 0)) return;
    animRef.current?.stop();
    e.currentTarget.setPointerCapture(e.pointerId);
    drag.current = {
      id: e.pointerId,
      startY: e.clientY,
      startPos: pos.get(),
      moved: false,
      samples: [{ t: performance.now(), y: e.clientY }],
    };
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    const dy = e.clientY - d.startY;
    if (Math.abs(dy) > 4) d.moved = true;
    if (!d.moved) return;
    pos.set(rubber(d.startPos - dy / rowHeight));
    const now = performance.now();
    d.samples.push({ t: now, y: e.clientY });
    while (d.samples.length > 2 && now - d.samples[0].t > 100) d.samples.shift();
  };

  const endDrag = (e: React.PointerEvent<HTMLDivElement>, cancelled = false) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    if (!d.moved) {
      if (cancelled) return goTo(targetKRef.current);
      // Tap: spin the tapped row to centre.
      const rect = e.currentTarget.getBoundingClientRect();
      const y = e.clientY - (rect.top + rect.height / 2);
      const { g: geo, flat: isFlat } = latest.current;
      const rows = isFlat
        ? y / geo.rowHeight
        : Math.asin(Math.max(-1, Math.min(1, y / geo.radius))) / (geo.theta * DEG);
      const delta = Math.round(rows);
      rootRef.current?.focus({ preventScroll: true });
      if (delta !== 0) goTo(targetKRef.current + delta, { dir: Math.sign(delta) });
      return;
    }
    const first = d.samples[0];
    const last = d.samples[d.samples.length - 1];
    const dt = Math.max(1, last.t - first.t) / 1000;
    const recent = performance.now() - last.t < 80;
    let v = recent ? -((last.y - first.y) / dt) / rowHeight : 0;
    v = Math.max(-60, Math.min(60, v));
    if (latest.current.flat) v = 0;
    const p = pos.get();
    goTo(p + v * FLICK_TAU, { velocity: v, dir: Math.sign(v || p - d.startPos) });
  };

  /* ---------------------------------- wheel --------------------------------- */

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    let acc = 0;
    let lastT = 0;
    const onWheel = (e: WheelEvent) => {
      if (disabled || drag.current) return;
      const { count: n, loop: isLoop } = latest.current;
      const dir = Math.sign(e.deltaY);
      if (!dir) return;
      const k = targetKRef.current;
      // At a hard stop, let the page scroll instead.
      if (!isLoop && ((dir < 0 && k <= 0) || (dir > 0 && k >= n - 1))) return;
      e.preventDefault();
      const now = performance.now();
      if (now - lastT > 220 || Math.sign(acc) !== dir) acc = 0;
      lastT = now;
      // Line/page deltas (mouse notches) step once per event; pixel deltas
      // (trackpads) accumulate so a long swipe walks several rows.
      if (e.deltaMode !== 0) {
        goTo(k + dir, { dir });
        return;
      }
      acc += e.deltaY;
      if (Math.abs(acc) >= 34) {
        acc = 0;
        goTo(k + dir, { dir });
      }
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, [disabled, goTo]);

  /* -------------------------------- keyboard -------------------------------- */

  const typeahead = React.useRef({ buffer: "", t: 0 });

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    const k = targetKRef.current;
    const n = count;
    // Spinbutton semantics: ArrowUp increases (next row). Listbox: ArrowUp = previous option.
    const up = isNumber ? 1 : -1;
    let handled = true;
    switch (e.key) {
      case "ArrowUp":
        goTo(k + up, { dir: up });
        break;
      case "ArrowDown":
        goTo(k - up, { dir: -up });
        break;
      case "PageUp":
        goTo(k + up * 5, { dir: up });
        break;
      case "PageDown":
        goTo(k - up * 5, { dir: -up });
        break;
      case "Home":
        goTo(nearestK(resolveEnabled(0, 1)), { dir: 1 });
        break;
      case "End":
        goTo(nearestK(resolveEnabled(n - 1, -1)), { dir: -1 });
        break;
      default:
        handled = false;
    }
    if (!handled && e.key.length === 1 && !e.metaKey && !e.ctrlKey && !e.altKey && e.key !== " ") {
      const ta = typeahead.current;
      const now = performance.now();
      const ch = e.key.toLowerCase();
      ta.buffer = now - ta.t > 700 ? ch : ta.buffer + ch;
      ta.t = now;
      const current = mod(k, n);
      // Repeating one letter cycles through the rows that start with it.
      const cycling = ta.buffer.length > 1 && ta.buffer.split("").every((c) => c === ch);
      const needle = cycling ? ch : ta.buffer;
      const startAt = cycling || ta.buffer.length === 1 ? 1 : 0;
      for (let i = 0; i < n; i++) {
        const idx = mod(current + startAt + i, n);
        const row = rowAt(idx);
        if (!row.disabled && row.text.toLowerCase().startsWith(needle)) {
          goTo(nearestK(idx));
          break;
        }
      }
      handled = true;
    }
    if (handled) e.preventDefault();
  };

  /* --------------------------------- render --------------------------------- */

  const baseId = React.useId();
  const rowId = (k: number) => `${baseId}-row-${k}`;

  const ks: number[] = [];
  for (let k = centerK - g.reach; k <= centerK + g.reach; k++) {
    if (!loop && (k < 0 || k > count - 1)) continue;
    ks.push(k);
  }
  // The active descendant must always exist in the DOM, even mid-spin.
  if (!ks.includes(targetK)) ks.push(targetK);

  const p0 = pos.get();
  const bandTop = g.height / 2 - rowHeight / 2;
  const selectedRow = rowAt(selectedIndex);

  const renderRows = (lit: boolean) =>
    ks.map((k) => {
      const index = mod(k, count);
      const row = rowAt(index);
      // In loop mode the window can repeat options; only one copy of each is
      // exposed to assistive tech so the listbox never lists duplicates.
      const exposed =
        !lit &&
        !isNumber &&
        k >= targetK - Math.floor((count - 1) / 2) &&
        k <= targetK + Math.ceil((count - 1) / 2);
      return (
        <div
          key={k}
          data-tumbler-row={k}
          id={exposed ? rowId(k) : undefined}
          role={exposed ? "option" : undefined}
          aria-selected={exposed ? k === targetK : undefined}
          aria-disabled={exposed && row.disabled ? true : undefined}
          aria-setsize={exposed ? count : undefined}
          aria-posinset={exposed ? index + 1 : undefined}
          aria-hidden={exposed ? undefined : true}
          className={cn(
            "absolute inset-x-0 flex items-center justify-center whitespace-nowrap px-3 tabular-nums select-none",
            "[backface-visibility:hidden] will-change-transform",
            lit ? "font-medium text-white" : "text-neutral-500",
            row.disabled && "line-through opacity-40"
          )}
          style={{ top: bandTop, height: rowHeight, ...rowStyle(k - p0, g, flat) }}
        >
          {row.label}
        </div>
      );
    });

  // Width: every label stacked in one invisible grid cell (number mode only
  // needs the extremes; tabular digits keep the rest within them).
  const sizerLabels: React.ReactNode[] = listRows
    ? listRows.map((r) => r.label)
    : [rowAt(0).label, rowAt(count - 1).label];

  const bandMask = `linear-gradient(to bottom, #000 ${bandTop}px, transparent ${bandTop}px, transparent ${bandTop + rowHeight}px, #000 ${bandTop + rowHeight}px)`;
  const ariaName = ariaLabelledby ? undefined : label;

  const a11y = isNumber
    ? {
        role: "spinbutton" as const,
        "aria-valuenow": selectedRow.value as number,
        "aria-valuemin": min,
        "aria-valuemax": rowAt(count - 1).value as number,
        "aria-valuetext": selectedRow.text,
      }
    : {
        role: "listbox" as const,
        "aria-activedescendant": rowId(targetK),
      };

  return (
    <div
      ref={rootRef}
      data-crucible="tumbler"
      tabIndex={disabled ? -1 : 0}
      aria-label={ariaName}
      aria-labelledby={ariaLabelledby}
      aria-disabled={disabled || undefined}
      {...rest}
      {...a11y}
      onKeyDown={onKeyDown}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={(e) => endDrag(e)}
      onPointerCancel={(e) => endDrag(e, true)}
      className={cn(
        "group/tumbler relative inline-grid shrink-0 cursor-grab touch-none rounded-xl text-[17px] outline-none active:cursor-grabbing",
        "focus-visible:ring-2 focus-visible:ring-(--tumbler-accent)/70 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
        disabled && "pointer-events-none opacity-45",
        className
      )}
      style={{
        ["--tumbler-accent" as string]: accentColor,
        height: g.height,
        ...style,
      }}
    >
      {/* Invisible sizer sets the drum width to its widest label. */}
      <div aria-hidden className="invisible col-start-1 row-start-1 grid h-0 overflow-hidden font-medium tabular-nums">
        {sizerLabels.map((l, i) => (
          <span key={i} className="col-start-1 row-start-1 whitespace-nowrap px-3">
            {l}
          </span>
        ))}
      </div>

      {!group && (
        <div
          aria-hidden
          className="pointer-events-none absolute inset-x-0 rounded-lg bg-white/[0.045]"
          style={{ top: bandTop, height: rowHeight }}
        >
          <BandRules />
        </div>
      )}

      {/* Base drum: everything outside the lit band. Rows are direct children
          so they render under this layer's perspective. */}
      <motion.div
        className="pointer-events-none absolute inset-0"
        style={{
          opacity: intro,
          perspective: flat ? undefined : g.perspective,
          maskImage: bandMask,
          WebkitMaskImage: bandMask,
        }}
      >
        {renderRows(false)}
      </motion.div>
      <motion.div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          opacity: intro,
          perspective: flat ? undefined : g.perspective,
          clipPath: `inset(${bandTop}px 0 ${g.height - bandTop - rowHeight}px 0)`,
        }}
      >
        {renderRows(true)}
      </motion.div>

      {name !== undefined && <input type="hidden" name={name} value={String(selectedRow.value)} />}
    </div>
  );
}

/** Accent hairlines above and below the lit band, fading at the ends. */
function BandRules() {
  const line =
    "absolute inset-x-1 h-px bg-[linear-gradient(90deg,transparent,var(--tumbler-accent)_22%,var(--tumbler-accent)_78%,transparent)] opacity-60";
  return (
    <>
      <span className={cn(line, "top-0")} />
      <span className={cn(line, "bottom-0")} />
    </>
  );
}

/* -------------------------------------------------------------------------- */
/*                                TumblerGroup                                */
/* -------------------------------------------------------------------------- */

/**
 * TumblerGroup — lays several `Tumbler` drums side by side (HH:MM, dates)
 * sharing one highlight band. Every drum inherits the group's `visibleRows`,
 * `rowHeight` and `accentColor` so their rows line up exactly. Renders
 * `role="group"`; each drum keeps its own label and keyboard focus (Tab moves
 * between drums).
 */
export function TumblerGroup({
  label,
  visibleRows = 5,
  rowHeight = 40,
  accentColor = DEFAULT_ACCENT,
  className,
  style,
  children,
  ...props
}: TumblerGroupProps) {
  const ctx = React.useMemo(
    () => ({ visibleRows, rowHeight, accentColor }),
    [visibleRows, rowHeight, accentColor]
  );
  return (
    <div
      role="group"
      aria-label={props["aria-labelledby"] ? undefined : label}
      data-crucible="tumbler-group"
      className={cn("relative isolate inline-flex items-center gap-1 px-2", className)}
      style={{ ["--tumbler-accent" as string]: accentColor, ...style }}
      {...props}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute inset-x-0 top-1/2 -z-10 -translate-y-1/2 rounded-lg bg-white/[0.045]"
        style={{ height: rowHeight }}
      >
        <BandRules />
      </div>
      <TumblerGroupContext.Provider value={ctx}>{children}</TumblerGroupContext.Provider>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface VoltaicProps extends React.ComponentPropsWithoutRef<"div"> {
  /** Card content. */
  children: React.ReactNode;
  /** Arc color, any CSS color. The stroke core is auto-mixed toward white. @default electric violet */
  color?: string;
  /** Displacement strength — 0 is a calm line, higher is more violent arcing. @default 1 */
  intensity?: number;
  /** Temporal churn multiplier for the turbulence. @default 1 */
  speed?: number;
  /** Corner radius of the card and its arc, in px. @default 16 */
  borderRadius?: number;
  /** Freeze the arc at its current frame. @default false */
  paused?: boolean;
}

/** How far the SVG bleeds past the card so displaced kinks aren't clipped. */
const PAD = 12;

/** Deterministic PRNG so reseed/misfire schedules are identical every run (SSR-safe, no Math.random). */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rand = mulberry32(0x5eed);
const SEEDS = Array.from({ length: 32 }, () => Math.floor(rand() * 1000));
const MISFIRE_AT = Array.from({ length: 16 }, () => 0.25 + rand() * 0.55);

/**
 * Voltaic — an electric turbulence border. The card's perimeter is a live
 * arc: an SVG rounded-rect stroke continuously deformed by animated
 * procedural turbulence (feTurbulence noise drifting through feOffset, then
 * feDisplacementMap), so the line writhes and — on periodic reseeds —
 * crackles to a new configuration, under a soft violet corona. Every few
 * seconds the turbulence misfires to near-zero for a beat and snaps back,
 * like an arc re-striking. Hover ramps the displacement. Filter attributes
 * are driven by refs in a throttled rAF loop that pauses offscreen and on
 * hidden tabs; all randomness is seeded. Reduced motion: a static,
 * softly-glowing border with zero displacement.
 */
export function Voltaic({
  children,
  color = "#a78bfa",
  intensity = 1,
  speed = 1,
  borderRadius = 16,
  paused = false,
  className,
  style,
  ...props
}: VoltaicProps) {
  const reducedMotion = useReducedMotion();
  const rawId = React.useId();
  const id = React.useMemo(() => `voltaic-${rawId.replace(/[^a-zA-Z0-9-]/g, "")}`, [rawId]);

  const turbRefs = React.useRef<(SVGFETurbulenceElement | null)[]>([null, null]);
  const offsetRefs = React.useRef<(SVGFEOffsetElement | null)[]>([null, null]);
  const displaceRefs = React.useRef<(SVGFEDisplacementMapElement | null)[]>([null, null]);
  const hoverRef = React.useRef(false);
  const boostRef = React.useRef(0);
  const lastFrame = React.useRef(0);

  const nodeRef = useVisibilityPause<HTMLDivElement>(
    (elapsed) => {
      // SVG filters re-rasterize on every attribute write — 30fps is plenty.
      if (elapsed - lastFrame.current < 1 / 30) return;
      lastFrame.current = elapsed;
      const t = elapsed * speed;

      boostRef.current += ((hoverRef.current ? 1 : 0) - boostRef.current) * 0.14;

      // Misfire: every cycle the turbulence drops to near-zero for ~150ms at
      // a seeded point in the cycle, then snaps back — the arc re-striking.
      const CYCLE = 3.4;
      const cycleIndex = Math.floor(t / CYCLE);
      const phase = t / CYCLE - cycleIndex;
      const misfireAt = MISFIRE_AT[cycleIndex % MISFIRE_AT.length] ?? 0.5;
      const env = phase > misfireAt && phase < misfireAt + 0.045 ? 0.06 : 1;

      // Cap the displacement so high intensity + hover boost can't push stroke
      // samples far enough apart to fragment the arc into detached specks that
      // spill past the filter region (~24 is where the path starts breaking up).
      const scale = Math.min(13 * intensity * (1 + 0.65 * boostRef.current) * env, 22).toFixed(2);
      // Bounded scroll of the noise offset. A linear (t * 30) drift grows without
      // limit and eventually slides the turbulence entirely out of the filter
      // region — the arc fades away after a minute or two. A slow sine keeps the
      // pattern travelling seamlessly forever; the crackle comes from reseeding below.
      const dx = (Math.sin(t * 0.23) * 60).toFixed(2);
      const dy = (Math.sin(t * 0.8) * 10).toFixed(2);
      const seed = String(SEEDS[Math.floor(t / 0.55) % SEEDS.length]);

      for (const el of displaceRefs.current) el?.setAttribute("scale", scale);
      for (const el of offsetRefs.current) {
        el?.setAttribute("dx", dx);
        el?.setAttribute("dy", dy);
      }
      for (const el of turbRefs.current) {
        // Reseeding jumps the noise to a new configuration — the crackle.
        if (el && el.getAttribute("seed") !== seed) el.setAttribute("seed", seed);
      }
    },
    { paused: paused || reducedMotion }
  );

  // If reduced motion engages mid-session, settle the arc back to a calm line.
  React.useEffect(() => {
    if (!reducedMotion) return;
    for (const el of displaceRefs.current) el?.setAttribute("scale", "0");
    boostRef.current = 0;
  }, [reducedMotion]);

  const handlePointerEnter = React.useCallback(() => {
    hoverRef.current = true;
  }, []);
  const handlePointerLeave = React.useCallback(() => {
    hoverRef.current = false;
  }, []);

  const rectGeometry: React.CSSProperties = {
    ["x" as string]: `${PAD}px`,
    ["y" as string]: `${PAD}px`,
    ["width" as string]: `calc(100% - ${PAD * 2}px)`,
    ["height" as string]: `calc(100% - ${PAD * 2}px)`,
  };

  const turbulence = (index: number, result: string) => (
    <>
      <feTurbulence
        ref={(el) => {
          turbRefs.current[index] = el;
        }}
        type="turbulence"
        baseFrequency="0.02 0.06"
        numOctaves={2}
        seed={7}
        result={`${result}-noise`}
      />
      <feOffset
        ref={(el) => {
          offsetRefs.current[index] = el;
        }}
        in={`${result}-noise`}
        dx={0}
        dy={0}
        result={`${result}-drift`}
      />
      <feDisplacementMap
        ref={(el) => {
          displaceRefs.current[index] = el;
        }}
        in="SourceGraphic"
        in2={`${result}-drift`}
        scale={0}
        xChannelSelector="R"
        yChannelSelector="G"
        result={`${result}-arc`}
      />
    </>
  );

  return (
    <div
      ref={nodeRef}
      data-crucible="voltaic"
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      className={cn("relative border border-white/10 bg-neutral-900", className)}
      style={{
        borderRadius,
        boxShadow: `0 0 36px -10px color-mix(in oklab, ${color} 45%, transparent)`,
        ...style,
      }}
      {...props}
    >
      <div className="relative rounded-[inherit]">{children}</div>
      <svg
        aria-hidden
        className="pointer-events-none absolute overflow-visible"
        style={{
          left: -PAD,
          top: -PAD,
          width: `calc(100% + ${PAD * 2}px)`,
          height: `calc(100% + ${PAD * 2}px)`,
        }}
      >
        <defs>
          <filter id={`${id}-arc`} x="-25%" y="-25%" width="150%" height="150%">
            {turbulence(0, "a")}
          </filter>
          <filter id={`${id}-corona`} x="-25%" y="-25%" width="150%" height="150%">
            {turbulence(1, "b")}
            <feGaussianBlur in="b-arc" stdDeviation="3.5" />
          </filter>
        </defs>
        {/* Violet corona: the same displaced path, blurred wide. */}
        <rect
          fill="none"
          stroke={color}
          strokeWidth={2.5}
          opacity={0.85}
          rx={borderRadius}
          filter={`url(#${id}-corona)`}
          style={rectGeometry}
        />
        {/* Pale core: near-white filament riding the identical turbulence. */}
        <rect
          fill="none"
          strokeWidth={1.2}
          rx={borderRadius}
          filter={`url(#${id}-arc)`}
          style={{
            ...rectGeometry,
            stroke: `color-mix(in oklab, ${color} 30%, white)`,
          }}
        />
      </svg>
    </div>
  );
}

"use client";

import * as React from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

/**
 * Returns true when the user prefers reduced motion. SSR-safe: returns false
 * on the server and during hydration, then syncs to the real media query.
 *
 * Every animated Crucible component must consume this and either freeze at a
 * tasteful static frame or fall back to a simple fade.
 */
export function useReducedMotion(): boolean {
  return React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(QUERY).matches,
    () => false
  );
}

function subscribe(callback: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", callback);
  return () => mql.removeEventListener("change", callback);
}

import * as React from "react";

import { cn } from "@/lib/utils";

export interface WeldProps extends React.ComponentPropsWithoutRef<"button"> {
  /** Color of the blinding beam head. Any CSS color. @default white */
  headColor?: string;
  /** Color of the tail trailing the head. @default cool blue-white */
  tailColor?: string;
  /** Seconds for one full lap of the border. @default 3.2 */
  duration?: number;
  /** Border radius in px — the beam's path is corner-radius aware and matches this exactly. @default 10 */
  radius?: number;
  /** Travel counterclockwise instead of clockwise. @default false */
  reverse?: boolean;
  /** Seconds to wait before the first lap starts. @default 0 */
  delay?: number;
  /** Freeze the animation, holding the current frame. @default false */
  paused?: boolean;
}

/**
 * Weld — a light beam traveling the border in a continuous loop, like a
 * welding arc tracing the seam: a blinding white-hot head with a cool
 * blue-white tail, corner sparks, and a faint heat-discoloration on the rim
 * that fades before the next lap. Pure CSS, corner-radius aware via
 * `offset-path`. Honors prefers-reduced-motion by freezing the beam in place.
 */
export function Weld({
  headColor = "#ffffff",
  tailColor = "#93c5fd",
  duration = 3.2,
  radius = 10,
  reverse = false,
  delay = 0,
  paused = false,
  className,
  style,
  disabled,
  children,
  ...rest
}: WeldProps) {
  return (
    <button
      data-crucible="weld"
      className={cn(
        "relative isolate inline-flex items-center justify-center overflow-visible",
        "border border-neutral-800 bg-neutral-900 px-6 py-3 text-sm font-medium text-white",
        "select-none",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950",
        "focus-visible:ring-[color:var(--weld-head)]",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      style={
        {
          "--weld-head": headColor,
          "--weld-tail": tailColor,
          "--weld-duration": `${duration}s`,
          "--weld-delay": `${delay}s`,
          "--weld-direction": reverse ? "reverse" : "normal",
          "--weld-play": paused ? "paused" : "running",
          "--weld-radius": `${radius}px`,
          borderRadius: radius,
          ...style,
        } as React.CSSProperties
      }
      disabled={disabled}
      {...rest}
    >
      <style>{`
        @keyframes crucible-weld-travel {
          to { offset-distance: 100%; }
        }
        @keyframes crucible-weld-spark {
          0%, 92%, 100% { opacity: 0; transform: scale(0.4); }
          95% { opacity: 1; transform: scale(1); }
        }
        @keyframes crucible-weld-heat {
          0%   { opacity: 0; }
          6%   { opacity: 0.9; }
          30%  { opacity: 0; }
          100% { opacity: 0; }
        }
        [data-crucible="weld"] .weld-track {
          position: absolute;
          inset: 0;
          offset-path: inset(0 round var(--weld-radius));
          offset-distance: 0%;
          animation: crucible-weld-travel var(--weld-duration) linear infinite;
          animation-delay: var(--weld-delay);
          animation-direction: var(--weld-direction);
          animation-play-state: var(--weld-play);
        }
        /* The track box is exactly container-sized so its own perimeter IS the
           button's border; offset-distance rides that perimeter by moving the
           box's center anchor. Centering the head/tail on that anchor makes
           them ride the path while the (invisible) track box itself overflows. */
        [data-crucible="weld"] .weld-track { offset-rotate: auto; }
        [data-crucible="weld"] .weld-head,
        [data-crucible="weld"] .weld-trail-dot {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          border-radius: 999px;
        }
        [data-crucible="weld"] .weld-head {
          width: 7px;
          height: 7px;
          /* A tight white-hot core so the beam reads as a point riding the
             seam, not a loose orb hovering off the edge. */
          background: radial-gradient(circle, #fff 0%, var(--weld-head) 30%, var(--weld-tail) 62%, transparent 80%);
          filter: blur(0.3px);
          box-shadow: 0 0 5px 1px color-mix(in oklab, var(--weld-head) 85%, transparent),
            0 0 11px 2px color-mix(in oklab, var(--weld-tail) 45%, transparent);
        }
        /* The tail is drip dots on their own tracks, phase-lagged behind the
           head via negative animation-delays — they ride the same offset-path,
           so the trail bends around corners instead of flying off tangentially
           like a straight gradient bar would. */
        [data-crucible="weld"] .weld-trail-dot {
          background: var(--weld-tail);
          filter: blur(0.4px);
          box-shadow: 0 0 4px 1px color-mix(in oklab, var(--weld-tail) 55%, transparent);
        }
        [data-crucible="weld"] .weld-corner {
          position: absolute;
          width: 4px;
          height: 4px;
          border-radius: 999px;
          background: var(--weld-head);
          box-shadow: 0 0 5px 1px color-mix(in oklab, var(--weld-tail) 60%, transparent);
          animation: crucible-weld-spark var(--weld-duration) linear infinite;
          /* backwards: adopt the 0% keyframe (opacity 0) during the staggered
             start delay, so delayed corners stay dark on mount instead of
             flashing at their base opacity 1 until their animation begins. */
          animation-fill-mode: backwards;
          animation-play-state: var(--weld-play);
          transform: translate(-50%, -50%);
        }
        [data-crucible="weld"] .weld-heat {
          position: absolute;
          inset: 0;
          border-radius: inherit;
          box-shadow: inset 0 0 0 1.5px color-mix(in oklab, var(--weld-tail) 55%, transparent);
          animation: crucible-weld-heat var(--weld-duration) ease-out infinite;
          animation-delay: var(--weld-delay);
          /* backwards so a non-zero delay holds the rim at the 0% keyframe
             (opacity 0) rather than its base opacity 1 during the wait. */
          animation-fill-mode: backwards;
          animation-play-state: var(--weld-play);
        }
        [data-crucible="weld"]:disabled .weld-track,
        [data-crucible="weld"]:disabled .weld-corner,
        [data-crucible="weld"]:disabled .weld-heat {
          animation-play-state: paused;
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="weld"] .weld-track,
          [data-crucible="weld"] .weld-corner,
          [data-crucible="weld"] .weld-heat {
            animation: none;
          }
          [data-crucible="weld"] .weld-track { offset-distance: 0%; }
          [data-crucible="weld"] .weld-heat { opacity: 0.25; }
          [data-crucible="weld"] .weld-corner { opacity: 0; }
        }
      `}</style>

      {/* Faint heat discoloration that blooms after the beam passes and fades before the next lap. */}
      <span aria-hidden className="weld-heat pointer-events-none" />

      {/* Corner sparks, roughly phase-locked to the beam reaching each corner. */}
      {/* Counterclockwise laps reach the top-right / bottom-left corners in the
          opposite order, so their phases swap when reversed. */}
      <span aria-hidden className="weld-corner pointer-events-none" style={{ top: 0, left: 0, animationDelay: `calc(var(--weld-delay) + var(--weld-duration) * 0.0)` }} />
      <span aria-hidden className="weld-corner pointer-events-none" style={{ top: 0, right: 0, animationDelay: `calc(var(--weld-delay) + var(--weld-duration) * ${reverse ? 0.75 : 0.25})` }} />
      <span aria-hidden className="weld-corner pointer-events-none" style={{ bottom: 0, right: 0, animationDelay: `calc(var(--weld-delay) + var(--weld-duration) * 0.5)` }} />
      <span aria-hidden className="weld-corner pointer-events-none" style={{ bottom: 0, left: 0, animationDelay: `calc(var(--weld-delay) + var(--weld-duration) * ${reverse ? 0.25 : 0.75})` }} />

      {/* The beam itself: a bright head trailed by drip dots, all riding the
          border path. Negative delays put each dot mid-lap immediately (no
          start-corner pileup) at a phase just behind the head. */}
      {[
        { lag: 0.008, size: 5, opacity: 0.85 },
        { lag: 0.018, size: 4, opacity: 0.6 },
        { lag: 0.03, size: 3.5, opacity: 0.4 },
        { lag: 0.044, size: 3, opacity: 0.22 },
      ].map(({ lag, size, opacity }) => (
        <span
          key={lag}
          aria-hidden
          className="weld-track pointer-events-none"
          style={{ animationDelay: `calc(var(--weld-delay) - var(--weld-duration) * ${1 - lag})` }}
        >
          <span className="weld-trail-dot" style={{ width: size, height: size, opacity }} />
        </span>
      ))}
      <span aria-hidden className="weld-track pointer-events-none">
        <span className="weld-head" />
      </span>

      <span className="relative z-10">{children}</span>
    </button>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface WarpProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * Three tones: `[core, head, bloom]`. `core` is the streak body (kept near
   * white for the classic light-speed look), `head` the chromatic tint that
   * blooms at the leading edge of each streak, `bloom` the central glow at the
   * vanishing point. Defaults to a cool blue-white hyperspace palette. Pass a
   * warm set (e.g. `["#fff3e6", "#ff9a5c", "#ffcf99"]`) for a solar jump.
   */
  colors?: [string, string, string];
  /** Outward-travel speed multiplier. 1 = default, 2 = twice as fast. Default 1. */
  speed?: number;
  /**
   * Overall luminosity of the streaks, heads, and center bloom, 0–2. 1 =
   * default; lower is a calmer drift, higher blazes into full jump. Default 1.
   */
  intensity?: number;
  /**
   * Streak density, 0.3–2. Scales how many stars radiate from the vanishing
   * point. Lower is a sparse calm field, higher a dense warp tunnel. Default 1.
   */
  density?: number;
  /**
   * Idle autoplay: after ~1.5s with no real pointer, a seeded ghost pointer
   * steers the vanishing point on a slow seeded drift so it never looks dead in thumbnails and
   * heroes; the real pointer takes over instantly. Never runs under reduced
   * motion. @default true
   */
  idle?: boolean;
  /** Freeze the animation at its current frame. */
  paused?: boolean;
}

const DEFAULT_COLORS: [string, string, string] = [
  "#eaf1ff", // core — blue-white streak body
  "#5b8cff", // head — cool chromatic tint at the leading edge
  "#9db8ff", // bloom — soft periwinkle glow at the vanishing point
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.92, 0.95, 1.0];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(Math.max(v, lo), hi);
}

/**
 * Original hyperspace-warp fragment shader. Space is read in polar coordinates
 * around a vanishing point: several layers of star-streaks radiate outward,
 * each one a thin line whose LEADING EDGE accelerates toward the frame edge
 * (radius grows with the square of its phase, so stars ease out slowly then
 * blur to light-speed). Streak length breathes with a slow "warp surge" so the
 * field pulses between a gentle drift and a full jump. Every streak carries a
 * per-channel radial offset — a genuine chromatic aberration that fringes the
 * heads cyan/red — plus a colored head-bloom sampled from the palette. A tight
 * core bloom and wide halo sit at the vanishing point over a faint twinkling
 * backdrop. Line thickness is corrected by radius so streaks stay constant
 * width in screen space, not fat wedges. The pointer nudges the vanishing
 * point. Exponential tone curve + film-grain dither kill 8-bit banding.
 * GLSL ES 1.00 (WebGL1/2 compatible); no fract() on spatial coords (only in
 * the hash), so there are no wrap seams.
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive; // eased 0..1 pointer (or ghost) presence

uniform vec3 uCore;      // streak body
uniform vec3 uHead;      // chromatic head tint
uniform vec3 uBloom;     // center glow
uniform float uSpeed;
uniform float uIntensity;
uniform float uDensity;

const float TAU = 6.28318530718;
const float MAXR = 1.45;  // normalized radius a streak head travels to

// ---- compact value-noise hash (fract only inside) ----
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float sq(float x) { return x * x; }

// One layer's radial band for a single channel, bright at the head, fading to
// the tail behind it.
float band(float r, float head, float len) {
  return smoothstep(head - len, head, r) * (1.0 - smoothstep(head, head + 0.03, r));
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = uTime * uSpeed;

  // Vanishing point: pointer nudges it a little off-center.
  vec2 center = vec2(0.5) + (uPointer - vec2(0.5)) * 0.18 * uPointerActive;
  vec2 p = uv - center;
  p.x *= aspect;

  float r = length(p);
  float ang = atan(p.y, p.x) / TAU + 0.5; // 0..1

  // Steady hyperspace stream with a gentle breathing surge — a calm, constant
  // jump (Star Wars), not a dramatic drift↔lightspeed pulse. Two slow beats.
  float surge = 0.66 + 0.14 * sin(t * 0.22) + 0.06 * sin(t * 0.09 + 1.3);
  surge = clamp(surge, 0.0, 1.0);

  vec3 acc = vec3(0.0);

  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    // Whole columns only — a fractional count leaves a seam where the angle wraps.
    float cols = max(floor((12.0 + fi * 10.0) * clamp(uDensity, 0.3, 2.0) + 0.5), 1.0);
    float depth = 0.55 + 0.45 * fi / 2.0; // nearer layers brighter/faster

    float g = ang * cols;
    float col = floor(g);
    float fcol = fract(g);

    float h1 = hash21(vec2(col, fi * 5.7 + 1.3));
    float h2 = hash21(vec2(col, fi * 9.1 + 4.2));

    // Angular offset of this streak inside its column → screen-space arc.
    float ao = 0.2 + 0.6 * h2;
    float angDist = (fcol - ao) * (TAU / cols);
    float arc = angDist * max(r, 0.05);

    // Outward travel, accelerating: radius ~ phase^2.
    float spd = (0.24 + 0.5 * h1) * (0.55 + 0.45 * surge);
    float phase = fract(h1 * 7.31 + t * spd);
    float head = phase * phase * MAXR;
    float len = (0.14 + 0.6 * phase) * (0.5 + 0.7 * surge);

    // Chromatic aberration: subtle per-channel radial offset (kept restrained
    // so the streaks read as clean light, not a rainbow smear).
    float ca = 0.006 * (0.4 + surge) * (0.35 + phase);
    float bR = band(r * (1.0 + ca), head, len);
    float bG = band(r, head, len);
    float bB = band(r * (1.0 - ca), head, len);
    vec3 radial = vec3(bR, bG, bB);

    // Constant screen-space line width (thinner in far layers).
    float w = 0.0055 + 0.004 * (1.0 - depth);
    float thin = exp(-(arc * arc) / (2.0 * w * w));

    // Per-star brightness + twinkle.
    float bright = (0.3 + 0.7 * h2) * depth;
    float tw = 0.75 + 0.25 * sin(t * (1.4 + 3.0 * h1) + h2 * TAU);

    // Colored bloom at the leading edge.
    float headGlow = exp(-sq((r - head) / (len * 0.6 + 0.02)));

    vec3 streak = uCore * radial + uHead * headGlow * (0.35 + 0.4 * surge);
    acc += streak * thin * bright * tw;
  }

  // Center bloom: tight core + wide halo at the vanishing point (restrained).
  float coreGlow = exp(-r * r / (2.0 * 0.0045));
  float halo = exp(-r * r / (2.0 * 0.06));
  acc += uBloom * (coreGlow * 0.7 + halo * 0.18) * (0.6 + 0.4 * surge);

  // Whisper-faint twinkling backdrop so the gaps aren't dead black (sparse +
  // dim so it reads as distant stars, not blocky noise).
  vec2 sg = floor((p + 4.0) * 90.0);
  float sh = hash21(sg);
  float star = step(0.992, sh) * (0.4 + 0.6 * sin(t * 2.0 + sh * TAU));
  acc += uCore * star * 0.05 * smoothstep(0.02, 0.25, r);

  vec3 col = acc * uIntensity;

  // Exponential tone curve rolls the stacked bloom to white instead of clipping
  // (lower exposure keeps the field restrained rather than blown-out).
  col = vec3(1.0) - exp(-col * 1.3);

  // Vignette + film-grain dither.
  vec2 vg = (uv - 0.5) * vec2(aspect, 1.0);
  col *= 1.0 - 0.35 * dot(vg, vg);
  float grain = hash21(gl_FragCoord.xy + fract(t) * 137.0) - 0.5;
  col += grain * (1.6 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

/**
 * Warp — a jump-to-light-speed hyperspace background. Layered star-streaks
 * accelerate radially from a vanishing point, their length breathing with a
 * slow warp surge, their heads fringed by real chromatic aberration and lit by
 * a colored bloom, over a soft central glow and a faint twinkling starfield.
 * The pointer nudges the vanishing point. Built on the `ogl-canvas` harness:
 * DPR-clamped, offscreen-paused, reduced-motion-safe (freezes on a static
 * radial-streak starburst), full GL teardown. Drop it inside any `relative`
 * container; it fills and sits behind content.
 */
export function Warp({
  colors = DEFAULT_COLORS,
  speed = 1,
  intensity = 1,
  density = 1,
  paused = false,
  idle = true,
  className,
  ...props
}: WarpProps) {
  const uniforms = React.useMemo(
    () => ({
      uCore: { value: hexToRgb(colors[0]) },
      uHead: { value: hexToRgb(colors[1]) },
      uBloom: { value: hexToRgb(colors[2]) },
      uSpeed: { value: Math.max(speed, 0) },
      uIntensity: { value: clamp(intensity, 0, 2) },
      uDensity: { value: clamp(density, 0.3, 2) },
    }),
    [colors, speed, intensity, density]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="warp"
      className={cn("absolute inset-0 -z-10 bg-neutral-950", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      dpr={2}
      paused={paused}
      ghost={idle}
      reducedMotionTime={6}
      {...props}
    />
  );
}

"use client";

import * as React from "react";

/**
 * A subtree-wide devicePixelRatio ceiling, applied on top of each component's
 * own `dpr` knob. A host running many GPU components at once — a gallery of
 * thumbnails, a dashboard of small charts — wraps them in a provider to trade
 * sharpness for fill rate without touching each component:
 *
 * ```tsx
 * <DprCapContext.Provider value={1}>{thumbnails}</DprCapContext.Provider>
 * ```
 *
 * Defaults to no cap.
 */
export const DprCapContext = React.createContext<number>(Infinity);

/** The enclosing {@link DprCapContext} ceiling (Infinity when uncapped). */
export function useDprCap(): number {
  return React.useContext(DprCapContext);
}

/**
 * `min(window.devicePixelRatio, ...caps)`. Reads `window`, so call it inside
 * effects or handlers only — never during render.
 */
export function clampDpr(...caps: number[]): number {
  const device = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;
  return Math.min(device, ...caps);
}

"use client";

import * as React from "react";

/**
 * Drives a requestAnimationFrame loop that automatically pauses when the
 * element scrolls offscreen (IntersectionObserver) or the tab is hidden
 * (document.visibilitychange). Mandatory for every shader/canvas/R3F
 * component — offscreen WebGL must never burn GPU time.
 *
 * `tick` receives elapsed seconds since the loop started. Offscreen and
 * hidden-tab pauses are excluded (the clock resumes where it stopped), but
 * changing the `paused` option restarts the loop and the clock from 0 —
 * one-shot reveals rely on that to replay; continuous effects that must not
 * jump on un-pause should carry their own time offset across the toggle.
 * Returns a ref to attach to the observed element.
 */
export function useVisibilityPause<T extends HTMLElement>(
  tick: (elapsedSeconds: number) => void,
  { paused = false }: { paused?: boolean } = {}
): React.RefObject<T | null> {
  const ref = React.useRef<T>(null);
  const tickRef = React.useRef(tick);
  tickRef.current = tick;
  // Accumulated running time survives effect re-runs (e.g. toggling `paused`),
  // so un-pausing resumes the clock instead of snapping back to 0.
  const elapsedRef = React.useRef(0);

  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;

    let raf = 0;
    let running = false;
    let visible = false;
    let last = 0;

    const loop = (now: number) => {
      if (!running) return;
      // Clamp at 0: a rAF timestamp can predate the performance.now() that
      // armed the loop by a fraction of a frame.
      elapsedRef.current += Math.max(0, now - last) / 1000;
      last = now;
      tickRef.current(elapsedRef.current);
      raf = requestAnimationFrame(loop);
    };

    const sync = () => {
      const shouldRun = visible && !document.hidden && !paused;
      if (shouldRun && !running) {
        running = true;
        last = performance.now();
        raf = requestAnimationFrame(loop);
      } else if (!shouldRun && running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      sync();
    });
    io.observe(el);
    document.addEventListener("visibilitychange", sync);

    return () => {
      running = false;
      cancelAnimationFrame(raf);
      io.disconnect();
      document.removeEventListener("visibilitychange", sync);
    };
  }, [paused]);

  return ref;
}

