/* ------------------------------------------------------------------ types */

/** Every flow the card can show. */
export type WicketView = "sign-in" | "sign-up" | "magic-link" | "otp" | "forgot" | "reset";

/** A single-sign-on provider button. */
export interface WicketProvider {
  /** Stable id passed to `onProvider`. */
  id: string;
  /** Visible provider name — rendered as "Continue with {label}". */
  label: string;
  /** Optional glyph (16px). Defaults to a neutral generic mark. */
  icon?: React.ReactNode;
}

/** Values submitted from the sign-in view. */
export interface WicketSignInValues {
  email: string;
  password: string;
  remember: boolean;
}

/** Values submitted from the sign-up view. */
export interface WicketSignUpValues {
  name: string;
  email: string;
  password: string;
  acceptedTerms: boolean;
}

/** Per-view header copy override. */
export interface WicketCopy {
  title?: string;
  subtitle?: string;
}

/**
 * Async auth callbacks resolve to finish the flow, reject (throw) to show the
 * error banner with the error's message, or — for sign-in / sign-up / SSO —
 * resolve to another view (e.g. `"otp"`) to continue into a second step.
 */
type Outcome = void | WicketView;
type Async<T> = T | Promise<T>;

/** Imperative verbs exposed through the `ref` prop. */
export interface WicketHandle {
  /** Jump to a view (resets that view's pending/sent/done state). */
  setView: (view: WicketView) => void;
  /** Clear every field and state and return to `defaultView`. */
  reset: () => void;
  /** Replay the plate-in intro. */
  replay: () => void;
}

export interface WicketProps {
  /** Controlled view. Omit for internal navigation (see `defaultView`). */
  view?: WicketView;
  /** Initial view when uncontrolled. @default "sign-in" */
  defaultView?: WicketView;
  /** Fires whenever the card asks to move to another view (links, flow steps). */
  onViewChange?: (view: WicketView) => void;
  /** SSO buttons shown on sign-in and sign-up. Pass `[]` to hide the row. @default Google + GitHub with generic glyphs */
  providers?: WicketProvider[];
  /** Logo slot above the header. @default a neutral accent mark */
  logo?: React.ReactNode;
  /** Product name woven into the default copy ("Sign in to {title}"). @default "Halyard" */
  title?: string;
  /** Override the title/subtitle of any view. */
  copy?: Partial<Record<WicketView, WicketCopy>>;
  /** Sign in with email + password. Resolve to `"otp"` to require a second factor. */
  onSignIn?: (values: WicketSignInValues) => Async<Outcome>;
  /** Create an account. Resolve to a view to continue (e.g. `"otp"` to verify). */
  onSignUp?: (values: WicketSignUpValues) => Async<Outcome>;
  /** Send a magic sign-in link. Resolving shows the "Check your inbox" state. */
  onMagicLink?: (email: string) => Async<void>;
  /** Verify a one-time code (auto-submits once every cell is filled). Reject to shake + clear. */
  onVerifyOtp?: (code: string) => Async<void>;
  /** Send a password-reset email. Resolving shows the sent state. */
  onForgot?: (email: string) => Async<void>;
  /** Set a new password from a reset link. */
  onReset?: (values: { password: string }) => Async<void>;
  /** SSO button pressed. Resolve to finish, or to a view to continue. */
  onProvider?: (id: string) => Async<Outcome>;
  /** A "Resend" button was pressed (after its countdown). */
  onResend?: (view: "magic-link" | "otp" | "forgot", email: string) => Async<void>;
  /** Fires when a flow reaches its final success state. */
  onComplete?: (view: WicketView) => void;
  /** Prefill the email field. */
  defaultEmail?: string;
  /** Seconds before "Resend" re-enables. @default 30 */
  resendSeconds?: number;
  /** Number of OTP cells. @default 6 */
  otpLength?: number;
  /** The single signature accent — primary button, focus rings, links. @default violet #a78bfa */
  accentColor?: string;
  /** Imperative handle (`setView`, `reset`, `replay`). React 19 ref-as-prop. */
  ref?: React.Ref<WicketHandle>;
  className?: string;
}

