/* ---------------------------------------------------------------- helpers */

/** Black or white text, whichever reads against the accent fill. */
function readableOn(hex: string): string {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return "#0a0a0a";
  let s = m[1];
  if (s.length === 3) s = s.replace(/./g, (c) => c + c);
  const n = parseInt(s, 16);
  const lum = 0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255);
  return lum > 140 ? "#0a0a0a" : "#ffffff";
}

function strength(p: string): number {
  if (!p) return 0;
  const met = RULES.filter((r) => r.test(p)).length;
  // Short passwords can't be better than Weak no matter the mix.
  return p.length < 8 ? Math.min(met, 1) || 1 : Math.max(1, met);
}

function maskEmail(email: string): string {
  const [user, domain] = email.split("@");
  if (!user || !domain) return email;
  return `${user[0]}${"•".repeat(Math.min(4, Math.max(2, user.length - 1)))}@${domain}`;
}

const wait = (ms: number) => new Promise<void>((r) => window.setTimeout(r, ms));

function errorMessage(e: unknown, fallback: string): string {
  if (e instanceof Error && e.message) return e.message;
  if (typeof e === "string" && e) return e;
  return fallback;
}

/** Ticking countdown; timestamps only read in handlers/effects. */
function useCountdown() {
  const [left, setLeft] = React.useState(0);
  const endRef = React.useRef(0);
  const start = React.useCallback((seconds: number) => {
    endRef.current = performance.now() + seconds * 1000;
    setLeft(seconds);
  }, []);
  const clear = React.useCallback(() => {
    endRef.current = 0;
    setLeft(0);
  }, []);
  React.useEffect(() => {
    if (left <= 0) return;
    const t = window.setInterval(() => {
      const next = Math.max(0, Math.ceil((endRef.current - performance.now()) / 1000));
      setLeft(next);
    }, 250);
    return () => window.clearInterval(t);
  }, [left > 0]); // eslint-disable-line react-hooks/exhaustive-deps
  return { left, start, clear };
}

const fmtClock = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;

