const WicketCtx = React.createContext<Ctx>({ accent: "#a78bfa", ink: "#0a0a0a", reduced: false });

const inputBase =
  "h-10 w-full rounded-[10px] border bg-white/[0.03] px-3 text-sm text-white outline-none transition-[border-color,box-shadow,background-color] duration-150 placeholder:text-white/25 hover:bg-white/[0.045] focus:bg-white/[0.05] focus:border-[var(--wk-accent)] focus:shadow-[0_0_0_3px_var(--wk-ring)] disabled:opacity-60";

interface FieldProps extends Omit<React.ComponentPropsWithoutRef<"input">, "className"> {
  label: string;
  error?: string | null;
  hint?: React.ReactNode;
  aside?: React.ReactNode;
  trailing?: React.ReactNode;
  inputRef?: React.Ref<HTMLInputElement>;
}

function Field({ label, error, hint, aside, trailing, inputRef, id, ...input }: FieldProps) {
  const auto = React.useId();
  const fid = id ?? auto;
  const errId = `${fid}-err`;
  const hintId = `${fid}-hint`;
  const describedBy = [error ? errId : null, hint ? hintId : null].filter(Boolean).join(" ") || undefined;
  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-baseline justify-between gap-3">
        <label htmlFor={fid} className="text-[13px] font-medium text-white/75">
          {label}
        </label>
        {aside}
      </div>
      <div className="relative">
        <input
          ref={inputRef}
          id={fid}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          className={cn(
            inputBase,
            trailing && "pr-10",
            error ? "border-rose-400/55" : "border-white/[0.08]"
          )}
          {...input}
        />
        {trailing && <div className="absolute inset-y-0 right-0 flex items-center pr-1.5">{trailing}</div>}
      </div>
      <Collapse show={!!error}>
        <p id={errId} className="flex items-center gap-1.5 pt-0.5 text-[12.5px] text-rose-300">
          <svg viewBox="0 0 16 16" className="size-3.5 shrink-0" fill="currentColor" aria-hidden>
