          </svg>
          {error}
        </p>
      </Collapse>
      {hint && <div id={hintId}>{hint}</div>}
    </div>
  );
}

/** Height + opacity reveal for inline messages. */
function Collapse({ show, children }: { show: boolean; children: React.ReactNode }) {
  const { reduced } = React.useContext(WicketCtx);
  return (
    <AnimatePresence initial={false}>
      {show && (
        <motion.div
          initial={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }}
          animate={reduced ? { opacity: 1 } : { opacity: 1, height: "auto" }}
          exit={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }}
          transition={reduced ? { duration: 0.12 } : { duration: 0.2, ease: EASE }}
          className="overflow-hidden"
