/* --------------------------------------------------------------- component */

type Phase = "form" | "sent" | "done";
type FieldName = "name" | "email" | "password" | "confirm" | "terms";

interface Values {
  name: string;
  email: string;
  password: string;
  confirm: string;
  remember: boolean;
  terms: boolean;
}

function validate(view: WicketView, v: Values): Partial<Record<FieldName, string>> {
  const e: Partial<Record<FieldName, string>> = {};
  const needsEmail = view === "sign-in" || view === "sign-up" || view === "magic-link" || view === "forgot";
  if (needsEmail) {
    if (!v.email.trim()) e.email = "Enter your email address";
    else if (!EMAIL_RE.test(v.email.trim())) e.email = "That doesn't look like a valid email";
  }
  if (view === "sign-in" && !v.password) e.password = "Enter your password";
  if (view === "sign-up" || view === "reset") {
    const s = strength(v.password);
    if (!v.password) e.password = "Choose a password";
    else if (v.password.length < 8) e.password = "Use at least 8 characters";
    else if (s < 3) e.password = "Mix in a number, symbol or capital letter";
  }
  if (view === "sign-up") {
    if (!v.name.trim()) e.name = "Tell us your name";
    if (!v.terms) e.terms = "Please accept the terms to continue";
  }
  if (view === "reset") {
    if (!v.confirm) e.confirm = "Confirm your new password";
    else if (v.confirm !== v.password) e.confirm = "Passwords don't match";
  }
  return e;
}

const FIELD_ORDER: FieldName[] = ["name", "email", "password", "confirm", "terms"];

const EMPTY: Values = { name: "", email: "", password: "", confirm: "", remember: true, terms: false };

/**
 * Wicket — one auth card for every flow. Sign in, sign up (with a 4-segment
 * strength meter and live rule checklist), magic link (an envelope folds shut
 * on "Check your inbox" with a resend countdown), OTP/2FA (Passcode cells that
 * auto-submit and shake on a wrong code), and forgot/reset password. Views
 * morph with direction-aware slides inside a spring-animated height; async
 * callbacks drive pending spinners, a slide-in error banner and a drawn-check
 * success state. Real `<form>`s, autocomplete hints, labelled fields with
 * `aria-invalid`/`aria-describedby`, validation on blur and a shake on invalid
 * submit; focus lands on the first field whenever the view changes. Reduced
 * motion swaps every slide and shake for crossfades — never blank.
 */
export function Wicket({
  view: viewProp,
  defaultView = "sign-in",
  onViewChange,
  providers = DEFAULT_PROVIDERS,
  logo,
  title = "Halyard",
  copy,
  onSignIn,
  onSignUp,
  onMagicLink,
  onVerifyOtp,
  onForgot,
  onReset,
  onProvider,
  onResend,
  onComplete,
  defaultEmail = "",
  resendSeconds = 30,
  otpLength = 6,
  accentColor = "#a78bfa",
  ref,
  className,
}: WicketProps) {
  const reduced = useReducedMotion();
  const accent = accentColor;
  const ink = readableOn(accent);
  const ctx = React.useMemo<Ctx>(() => ({ accent, ink, reduced }), [accent, ink, reduced]);

  /* ----- view (controlled / uncontrolled) */
  const [innerView, setInnerView] = React.useState<WicketView>(defaultView);
  const view = viewProp ?? innerView;

  const [values, setValues] = React.useState<Values>(() => ({ ...EMPTY, email: defaultEmail }));
  const [touched, setTouched] = React.useState<Set<FieldName>>(() => new Set());
  const [submitted, setSubmitted] = React.useState(false);
  const [phase, setPhase] = React.useState<Phase>("form");
  const [pending, setPending] = React.useState(false);
  const [providerPending, setProviderPending] = React.useState<string | null>(null);
  const [error, setError] = React.useState<string | null>(null);
  const [otp, setOtp] = React.useState("");
  const [doneOf, setDoneOf] = React.useState<WicketView>("sign-in");
  const [announce, setAnnounce] = React.useState("");
  const [dir, setDir] = React.useState(1);
  const countdown = useCountdown();

  // Reset per-view state whenever the visible view changes (controlled or not).
  const [shownView, setShownView] = React.useState(view);
  if (shownView !== view) {
    const d = DEPTH[view] - DEPTH[shownView] || Math.sign(ORDER.indexOf(view) - ORDER.indexOf(shownView)) || 1;
    setShownView(view);
    setDir(d > 0 ? 1 : -1);
    setPhase("form");
    setPending(false);
    setProviderPending(null);
    setError(null);
    setSubmitted(false);
    setTouched(new Set());
    setOtp("");
    setValues((v) => ({ ...v, password: "", confirm: "" }));
  }

  // Focus management: after the user navigates, focus the next stage's first field.
  const navigatedRef = React.useRef(false);
  const stageRef = React.useRef<HTMLDivElement>(null);
  const shakeRef = React.useRef<HTMLDivElement>(null);
  const otpRef = React.useRef<HTMLDivElement>(null);

  const go = React.useCallback(
    (next: WicketView) => {
      navigatedRef.current = true;
      if (viewProp === undefined) setInnerView(next);
      onViewChange?.(next);
    },
    [viewProp, onViewChange]
  );

  // OTP code was just "sent" on entering the view — start its resend timer.
  React.useEffect(() => {
    if (view === "otp") countdown.start(resendSeconds);
    else countdown.clear();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view]);

  const focusStage = React.useCallback(() => {
    const root = stageRef.current;
    if (!root) return;
    const target =
      root.querySelector<HTMLElement>("[data-autofocus]") ??
      root.querySelector<HTMLElement>("input:not([type=hidden]):not([type=checkbox]):not(:disabled)");
    target?.focus({ preventScroll: true });
  }, []);

  /* ----- intro */
  const rootRef = React.useRef<HTMLDivElement>(null);
  const inView = useInView(rootRef, { once: true, amount: 0.2 });
  const [introKey, setIntroKey] = React.useState(0);
  const [fallback, setFallback] = React.useState(false);
  React.useEffect(() => {
    // Never stuck invisible if the in-view trigger never fires.
    const t = window.setTimeout(() => setFallback(true), 1400);
    return () => window.clearTimeout(t);
  }, []);
  const revealed = inView || fallback || reduced;

  /* ----- field helpers */
  const errors = React.useMemo(() => validate(view, values), [view, values]);
  const errFor = (f: FieldName) => (submitted || touched.has(f) ? (errors[f] ?? null) : null);
  const set = <K extends keyof Values>(k: K, v: Values[K]) => {
    setValues((s) => ({ ...s, [k]: v }));
    if (error) setError(null);
  };
  const touch = (f: FieldName) => setTouched((t) => (t.has(f) ? t : new Set(t).add(f)));

  const shake = React.useCallback(
    (el: HTMLElement | null) => {
      if (!el || reduced) return;
      animate(el, { x: [0, -9, 8, -6, 4, -2, 0] }, { duration: 0.42, ease: "easeOut" });
    },
    [reduced]
  );

  const finish = React.useCallback(
    (of: WicketView) => {
      setDoneOf(of);
      setDir(1);
      setPhase("done");
      setAnnounce(of === "reset" ? "Password updated" : of === "sign-up" ? "Account created — redirecting" : "Signed in — redirecting");
      navigatedRef.current = true;
      onComplete?.(of);
    },
    [onComplete]
  );

  /** Run an async callback with pending / error / outcome handling. */
  const run = async (fn: () => Promise<Outcome | void>, fallbackError: string, onOk: (out: Outcome | void) => void) => {
    setPending(true);
    setError(null);
    setAnnounce("Working…");
    try {
      const out = await fn();
      setPending(false);
      onOk(out);
    } catch (e) {
      setPending(false);
      const msg = errorMessage(e, fallbackError);
      setError(msg);
      setAnnounce("");
      // OTP failures shake just the cells (see the effect below).
      if (view !== "otp") shake(shakeRef.current);
    }
  };

  const guard = (): boolean => {
    setSubmitted(true);
    const first = FIELD_ORDER.find((f) => errors[f]);
    if (!first) return true;
    shake(shakeRef.current);
    const el = stageRef.current?.querySelector<HTMLElement>(`[data-field="${first}"] input`);
    el?.focus({ preventScroll: true });
    setAnnounce(errors[first] ?? "");
    return false;
  };

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (pending) return;
    if (!guard()) return;
    const email = values.email.trim();
    switch (view) {
      case "sign-in":
        void run(
          async () => (onSignIn ? onSignIn({ email, password: values.password, remember: values.remember }) : wait(900)),
          "We couldn't sign you in. Try again.",
          (out) => (out ? go(out) : finish("sign-in"))
        );
        break;
      case "sign-up":
        void run(
          async () => (onSignUp ? onSignUp({ name: values.name.trim(), email, password: values.password, acceptedTerms: values.terms }) : wait(1000)),
          "We couldn't create your account. Try again.",
          (out) => (out ? go(out) : finish("sign-up"))
        );
        break;
      case "magic-link":
      case "forgot":
        void run(
          async () => (view === "magic-link" ? (onMagicLink ? onMagicLink(email) : wait(900)) : onForgot ? onForgot(email) : wait(900)),
          "We couldn't send that email. Try again.",
          () => {
            navigatedRef.current = true;
            setDir(1);
            setPhase("sent");
            setAnnounce(`Email sent to ${email}`);
            countdown.start(resendSeconds);
          }
        );
        break;
      case "reset":
        void run(
          async () => (onReset ? onReset({ password: values.password }) : wait(900)),
          "We couldn't update your password. Try again.",
          () => finish("reset")
        );
        break;
      case "otp":
        submitOtp(otp);
        break;
    }
  };

  const submitOtp = (code: string) => {
    if (pending) return;
    if (code.length < otpLength) {
      setError(`Enter all ${otpLength} digits`);
      shake(otpRef.current);
      return;
    }
    void run(
      async () => (onVerifyOtp ? onVerifyOtp(code) : wait(900)),
      "That code didn't match. Try again.",
      () => finish("otp")
    );
  };

  // When a verify fails, clear the cells and refocus the first one.
  React.useEffect(() => {
    if (view !== "otp" || !error || pending) return;
    shake(otpRef.current);
    const t = window.setTimeout(() => {
      setOtp("");
      otpRef.current?.querySelector<HTMLInputElement>("input")?.focus({ preventScroll: true });
    }, reduced ? 0 : 420);
    return () => window.clearTimeout(t);
  }, [view, error, pending, shake, reduced]);

  const provider = (id: string) => {
    if (providerPending || pending) return;
    setProviderPending(id);
    setError(null);
    const p = providers.find((x) => x.id === id);
    setAnnounce(`Connecting to ${p?.label ?? id}…`);
    Promise.resolve(onProvider ? onProvider(id) : wait(1100))
      .then((out) => {
        setProviderPending(null);
        if (out) go(out);
        else finish(view);
      })
      .catch((e) => {
        setProviderPending(null);
        setError(errorMessage(e, `We couldn't connect to ${p?.label ?? id}.`));
        setAnnounce("");
      });
  };

  const resend = () => {
    if (countdown.left > 0) return;
    const v = view === "otp" ? "otp" : view === "forgot" ? "forgot" : "magic-link";
    countdown.start(resendSeconds);
    setAnnounce(v === "otp" ? "A new code is on its way" : `Sent again to ${values.email.trim()}`);
    void Promise.resolve(onResend?.(v, values.email.trim())).catch((e) => setError(errorMessage(e, "We couldn't resend. Try again.")));
  };

  const reset = React.useCallback(() => {
    navigatedRef.current = false;
    setValues({ ...EMPTY, email: defaultEmail });
    setTouched(new Set());
    setSubmitted(false);
    setPhase("form");
    setPending(false);
    setProviderPending(null);
    setError(null);
    setOtp("");
    setAnnounce("");
    countdown.clear();
    if (viewProp === undefined) setInnerView(defaultView);
    else onViewChange?.(defaultView);
  }, [defaultEmail, defaultView, viewProp, onViewChange, countdown]);

  React.useImperativeHandle(
    ref,
    () => ({
      setView: (v: WicketView) => {
        if (v === view) {
          navigatedRef.current = true;
          setDir(-1);
          setPhase("form");
          setError(null);
          setPending(false);
          setSubmitted(false);
          setTouched(new Set());
          setOtp("");
          return;
        }
        go(v);
      },
      reset,
      replay: () => setIntroKey((k) => k + 1),
    }),
    [view, go, reset]
  );

  /* ----- height animation */
  const measureRef = React.useRef<HTMLDivElement>(null);
  const [height, setHeight] = React.useState<number | "auto">("auto");
  React.useLayoutEffect(() => {
    const el = measureRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(() => setHeight(el.offsetHeight));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const stageKey = phase === "done" ? `done-${doneOf}` : `${view}-${phase}`;
  // A freshly mounted stage takes focus if the user navigated to it.
  const attachStage = React.useCallback(
    (el: HTMLDivElement | null) => {
      stageRef.current = el;
      if (el && navigatedRef.current) {
        navigatedRef.current = false;
        requestAnimationFrame(focusStage);
      }
    },
    [focusStage]
  );

  /* ----- copy */
  const email = values.email.trim();
  const defaults: Record<WicketView, Required<WicketCopy>> = {
    "sign-in": { title: "Welcome back", subtitle: `Sign in to your ${title} account` },
    "sign-up": { title: "Create your account", subtitle: `Start your 14-day ${title} trial — no card needed` },
    "magic-link": { title: "Sign in with email", subtitle: "We'll email you a one-tap sign-in link" },
    otp: { title: "Two-step verification", subtitle: `Enter the ${otpLength}-digit code from your authenticator or texts` },
    forgot: { title: "Reset your password", subtitle: "Enter your email and we'll send a reset link" },
    reset: { title: "Choose a new password", subtitle: "Make it at least 8 characters with a good mix" },
  };
  const head = { ...defaults[view], ...copy?.[view] };

  const variants: Variants = reduced
    ? { enter: { opacity: 0 }, center: { opacity: 1 }, exit: { opacity: 0 } }
    : {
        enter: (d: number) => ({ opacity: 0, x: d * 32 }),
        center: { opacity: 1, x: 0 },
        exit: (d: number) => ({ opacity: 0, x: d * -32 }),
      };
  const stageTransition: Transition = reduced
    ? { duration: 0.16 }
    : { x: { type: "spring", stiffness: 420, damping: 38 }, opacity: { duration: 0.18 } };

  const showProviders = (view === "sign-in" || view === "sign-up") && providers.length > 0;
  const busy = pending || !!providerPending;

  /* ----- stage bodies */
  const header = (t: string, s: React.ReactNode, center = true) => (
    <div className={cn("mb-6 flex flex-col gap-1.5", center && "items-center text-center")}>
      <h2 className="text-[19px] font-semibold tracking-[-0.01em] text-white outline-none" tabIndex={-1}>
        {t}
      </h2>
      <p className="max-w-[36ch] text-[13.5px] leading-5 text-white/50 text-balance">{s}</p>
    </div>
  );

  let body: React.ReactNode;
  if (phase === "done") {
    const msg: Record<WicketView, [string, string]> = {
      "sign-in": ["Signed in", "Signed in — redirecting…"],
      "sign-up": ["Account created", "Welcome aboard — redirecting…"],
      "magic-link": ["Signed in", "Signed in — redirecting…"],
      forgot: ["Signed in", "Signed in — redirecting…"],
      otp: ["Verified", "Signed in — redirecting…"],
      reset: ["Password updated", "You can now sign in with your new password."],
    };
    const [t, s] = msg[doneOf];
    body = (
      <div className="flex flex-col items-center py-4 text-center" role="status">
        <DrawnCheck />
        <h2 className="mt-5 text-[19px] font-semibold tracking-[-0.01em] text-white outline-none" tabIndex={-1} data-autofocus>
          {t}
        </h2>
        <p className="mt-1.5 text-[13.5px] text-white/50">{s}</p>
        {doneOf === "reset" ? (
          <div className="mt-6 w-full">
            <PrimaryButton type="button" onClick={() => go("sign-in")}>
              Continue to sign in
            </PrimaryButton>
          </div>
        ) : (
          <div className="mt-6 h-1 w-40 overflow-hidden rounded-full bg-white/[0.06]" aria-hidden>
            <motion.div
              className="h-full rounded-full"
              style={{ backgroundColor: accent, originX: 0 }}
              initial={reduced ? { scaleX: 1 } : { scaleX: 0 }}
              animate={{ scaleX: 1 }}
              transition={reduced ? INSTANT : { duration: 2.4, ease: [0.4, 0, 0.2, 1], delay: 0.4 }}
            />
          </div>
        )}
      </div>
    );
  } else if (phase === "sent") {
    body = (
      <div className="flex flex-col items-center text-center">
        <Envelope />
        <h2 className="mt-5 text-[19px] font-semibold tracking-[-0.01em] text-white outline-none" tabIndex={-1}>
          Check your inbox
        </h2>
        <p className="mt-1.5 max-w-[32ch] text-[13.5px] leading-5 text-white/50">
          {view === "forgot" ? "We sent a password reset link to" : "We sent a sign-in link to"}
          <br />
          <span className="font-medium text-white/85">{email}</span>
        </p>
        <p className="mt-1 text-[12.5px] text-white/35">The link expires in 15 minutes.</p>
        <div className="mt-6 flex w-full flex-col gap-2.5">
          <button
            type="button"
            data-autofocus
            onClick={resend}
            aria-disabled={countdown.left > 0}
            className={cn(
              "inline-flex h-10 w-full items-center justify-center gap-2 rounded-[10px] border border-white/[0.1] bg-white/[0.04] text-sm font-medium text-white/85 outline-none transition-colors focus-visible:border-[var(--wk-accent)] focus-visible:shadow-[0_0_0_3px_var(--wk-ring)]",
              countdown.left > 0 ? "cursor-default text-white/45" : "hover:bg-white/[0.07]"
            )}
          >
            {countdown.left > 0 ? (
              <>
                Resend in <span className="tabular-nums">{fmtClock(countdown.left)}</span>
              </>
            ) : (
              "Resend email"
            )}
          </button>
          <TextLink className="self-center" onClick={() => { navigatedRef.current = true; setDir(-1); setPhase("form"); countdown.clear(); }}>
            Use a different email
          </TextLink>
        </div>
      </div>
    );
  } else {
    const emailField = (
      <div data-field="email">
        <Field
          label="Email"
          name="email"
          type="email"
          inputMode="email"
          autoComplete="email"
          placeholder="you@company.com"
          value={values.email}
          onChange={(e) => set("email", e.target.value)}
          onBlur={() => values.email && touch("email")}
          error={errFor("email")}
          disabled={busy}
          spellCheck={false}
          autoCapitalize="none"
        />
      </div>
    );
    body = (
      <>
        {header(head.title, view === "otp" && email ? <>Enter the {otpLength}-digit code we sent to <span className="text-white/80">{maskEmail(email)}</span></> : head.subtitle)}
        <ErrorBanner message={error} onDismiss={() => setError(null)} />
        {showProviders && (
          <>
            <div className={cn("grid gap-2", providers.length === 1 ? "grid-cols-1" : providers.length === 2 ? "grid-cols-2" : "grid-cols-3")}>
              {providers.map((p) => {
                const isPending = providerPending === p.id;
                return (
                  <button
                    key={p.id}
                    type="button"
                    onClick={() => provider(p.id)}
                    disabled={busy && !isPending}
                    aria-busy={isPending || undefined}
                    aria-label={`Continue with ${p.label}`}
                    title={`Continue with ${p.label}`}
                    className="inline-flex h-10 min-w-0 items-center justify-center gap-2 rounded-[10px] border border-white/[0.1] bg-white/[0.03] px-3 text-[13px] font-medium text-white/85 outline-none transition-colors hover:border-white/[0.16] hover:bg-white/[0.06] focus-visible:border-[var(--wk-accent)] focus-visible:shadow-[0_0_0_3px_var(--wk-ring)] disabled:opacity-45"
                  >
                    <span className="grid size-4 shrink-0 place-items-center text-white/70">{isPending ? <Spinner /> : (p.icon ?? <GlobeGlyph />)}</span>
                    <span className="truncate">
                      {providers.length === 1 && "Continue with "}
                      {p.label}
                    </span>
                  </button>
                );
              })}
            </div>
            <div className="my-5">
              <Divider>or</Divider>
            </div>
          </>
        )}
        <form noValidate onSubmit={onSubmit} className="flex flex-col gap-4" aria-busy={pending || undefined}>
          {view === "sign-in" && (
            <>
              {emailField}
              <div data-field="password">
                <PasswordField
                  label="Password"
                  name="password"
                  autoComplete="current-password"
                  placeholder="••••••••"
                  value={values.password}
                  onChange={(v) => set("password", v)}
                  onBlur={() => values.password && touch("password")}
                  error={errFor("password")}
                  disabled={busy}
                  aside={<TextLink onClick={() => go("forgot")}>Forgot password?</TextLink>}
                />
              </div>
              <Checkbox checked={values.remember} onChange={(v) => set("remember", v)}>
                Keep me signed in for 30 days
              </Checkbox>
              <div className="flex flex-col gap-3 pt-1">
                <PrimaryButton type="submit" pending={pending} pendingLabel="Signing in…">
                  Sign in
                </PrimaryButton>
                <TextLink className="self-center" onClick={() => go("magic-link")}>
                  Email me a link instead
                </TextLink>
              </div>
            </>
          )}
          {view === "sign-up" && (
            <>
              <div data-field="name">
                <Field
                  label="Full name"
                  name="name"
                  autoComplete="name"
                  placeholder="Ada Lindqvist"
                  value={values.name}
                  onChange={(e) => set("name", e.target.value)}
                  onBlur={() => values.name && touch("name")}
                  error={errFor("name")}
                  disabled={busy}
                />
              </div>
              {emailField}
              <div data-field="password">
                <PasswordField
                  label="Password"
                  name="new-password"
                  autoComplete="new-password"
                  placeholder="At least 8 characters"
                  value={values.password}
                  onChange={(v) => set("password", v)}
                  onBlur={() => values.password && touch("password")}
                  error={errFor("password")}
                  disabled={busy}
                  meter
                />
              </div>
              <div data-field="terms">
                <Checkbox checked={values.terms} onChange={(v) => set("terms", v)} error={submitted ? (errors.terms ?? null) : null}>
                  I agree to the <span className="text-white/80 underline decoration-white/25 underline-offset-2">Terms</span> and{" "}
                  <span className="text-white/80 underline decoration-white/25 underline-offset-2">Privacy Policy</span>
                </Checkbox>
              </div>
              <div className="pt-1">
                <PrimaryButton type="submit" pending={pending} pendingLabel="Creating account…">
                  Create account
                </PrimaryButton>
              </div>
            </>
          )}
          {(view === "magic-link" || view === "forgot") && (
            <>
              {emailField}
              <div className="pt-1">
                <PrimaryButton type="submit" pending={pending} pendingLabel="Sending…">
                  {view === "forgot" ? "Send reset link" : "Send magic link"}
                </PrimaryButton>
              </div>
            </>
          )}
          {view === "otp" && (
            <>
              <div ref={otpRef} className="flex justify-center">
                <Passcode
                  length={otpLength}
                  value={otp}
                  onChange={(v) => {
                    setOtp(v);
                    if (error) setError(null);
                  }}
                  onComplete={submitOtp}
                  disabled={pending}
                  colors={[accent, SUCCESS]}
                  aria-label={`${otpLength}-digit verification code`}
                  size="sm"
                  name="code"
                />
              </div>
              <PrimaryButton type="submit" pending={pending} pendingLabel="Verifying…" disabled={!pending && otp.length < otpLength}>
                Verify
              </PrimaryButton>
              <p className="text-center text-[13px] text-white/45">
                Didn&apos;t get it?{" "}
                {countdown.left > 0 ? (
                  <span className="text-white/40">
                    Resend in <span className="tabular-nums text-white/60">{fmtClock(countdown.left)}</span>
                  </span>
                ) : (
                  <TextLink strong onClick={resend}>
                    Resend code
                  </TextLink>
                )}
              </p>
            </>
          )}
          {view === "reset" && (
            <>
              <input type="email" name="email" autoComplete="username" value={email} readOnly hidden />
              <div data-field="password">
                <PasswordField
                  label="New password"
                  name="new-password"
                  autoComplete="new-password"
                  placeholder="At least 8 characters"
                  value={values.password}
                  onChange={(v) => set("password", v)}
                  onBlur={() => values.password && touch("password")}
                  error={errFor("password")}
                  disabled={busy}
                  meter
                />
              </div>
              <div data-field="confirm">
                <PasswordField
                  label="Confirm password"
                  name="confirm-password"
                  autoComplete="new-password"
                  placeholder="Repeat it"
                  value={values.confirm}
                  onChange={(v) => set("confirm", v)}
                  onBlur={() => values.confirm && touch("confirm")}
                  error={errFor("confirm")}
                  disabled={busy}
                />
                <Collapse show={!!values.confirm && !errFor("confirm")}>
                  <p
                    className="flex items-center gap-1.5 pt-1.5 text-[12.5px]"
                    style={{ color: values.confirm === values.password ? SUCCESS : "rgba(255,255,255,0.4)" }}
                    aria-live="polite"
                  >
                    {values.confirm === values.password ? "✓ Passwords match" : "Keep typing — doesn't match yet"}
                  </p>
                </Collapse>
              </div>
              <div className="pt-1">
                <PrimaryButton type="submit" pending={pending} pendingLabel="Updating…">
                  Update password
                </PrimaryButton>
              </div>
            </>
          )}
        </form>
      </>
    );
  }

  /* ----- footer */
  let footer: React.ReactNode = null;
  if (phase !== "done") {
    if (view === "sign-in")
      footer = (
        <>
          New to {title}? <TextLink strong onClick={() => go("sign-up")}>Create an account</TextLink>
        </>
      );
    else if (view === "sign-up")
      footer = (
        <>
          Already have an account? <TextLink strong onClick={() => go("sign-in")}>Sign in</TextLink>
        </>
      );
    else
      footer = (
        <TextLink onClick={() => go("sign-in")} className="inline-flex items-center gap-1.5">
          <svg viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <path d="M10 3.5 5.5 8l4.5 4.5" />
          </svg>
          Back to sign in
        </TextLink>
      );
  }
  const footerKey = phase === "done" ? "none" : view === "sign-in" || view === "sign-up" ? view : "back";

  return (
    <WicketCtx.Provider value={ctx}>
      <div
        ref={rootRef}
        data-crucible="wicket"
        className={cn("@container relative w-full max-w-[400px]", className)}
        style={
          {
            "--wk-accent": accent,
            "--wk-ring": `color-mix(in srgb, ${accent} 26%, transparent)`,
          } as React.CSSProperties
        }
      >
        <motion.div
          key={introKey}
          initial={{ opacity: 0, y: 14, scale: 0.985 }}
          animate={revealed ? { opacity: 1, y: 0, scale: 1 } : { opacity: 0, y: 14, scale: 0.985 }}
          transition={reduced ? INSTANT : { duration: 0.6, ease: EASE }}
          className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-neutral-900/85 shadow-[0_1px_0_rgba(255,255,255,0.04)_inset,0_24px_60px_-20px_rgba(0,0,0,0.7)] backdrop-blur-xl"
        >
          {/* accent hairline + top glow */}
          <span aria-hidden className="pointer-events-none absolute inset-x-10 top-0 h-px" style={{ background: `linear-gradient(90deg, transparent, ${accent}, transparent)`, opacity: 0.55 }} />
          <span aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-32" style={{ background: `radial-gradient(60% 100% at 50% 0%, color-mix(in srgb, ${accent} 9%, transparent), transparent 70%)` }} />

          <div className="relative px-5 pb-6 pt-7 @min-[380px]:px-8 @min-[380px]:pb-7">
            <motion.div
              className="mb-5 flex justify-center"
              initial={{ opacity: 0, y: 6 }}
              animate={revealed ? { opacity: 1, y: 0 } : { opacity: 0, y: 6 }}
              transition={reduced ? INSTANT : { duration: 0.5, ease: EASE, delay: 0.12 }}
            >
              {logo ?? <DefaultLogo accent={accent} />}
            </motion.div>

            <motion.div
              initial={false}
              animate={{ height: reduced ? "auto" : height }}
              transition={reduced ? INSTANT : SPRING}
              className="-mx-2 -my-1 overflow-hidden"
            >
              <div ref={measureRef} className="px-2 py-1">
                <motion.div
                  ref={shakeRef}
                  initial={{ opacity: 0, y: 8 }}
                  animate={revealed ? { opacity: 1, y: 0 } : { opacity: 0, y: 8 }}
                  transition={reduced ? INSTANT : { duration: 0.55, ease: EASE, delay: 0.2 }}
                >
                  <AnimatePresence mode="wait" initial={false} custom={dir}>
                    <motion.div
                      key={stageKey}
                      ref={attachStage}
                      custom={dir}
                      variants={variants}
                      initial="enter"
                      animate="center"
                      exit="exit"
                      transition={stageTransition}
                    >
                      {body}
                    </motion.div>
                  </AnimatePresence>
                </motion.div>
              </div>
            </motion.div>
          </div>

          <AnimatePresence initial={false}>
            {footer && (
              <motion.div
                initial={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }}
                animate={reduced ? { opacity: 1 } : { opacity: 1, height: "auto" }}
                exit={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }}
                transition={reduced ? { duration: 0.15 } : { duration: 0.28, ease: EASE }}
                className="overflow-hidden"
              >
                <div className="border-t border-white/[0.06] bg-white/[0.015] px-5 py-4 text-center text-[13px] text-white/45">
                  <AnimatePresence mode="wait" initial={false}>
                    <motion.div
                      key={footerKey}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      transition={{ duration: reduced ? 0.12 : 0.16 }}
                    >
                      {footer}
                    </motion.div>
                  </AnimatePresence>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>
        <p className="sr-only" aria-live="polite" role="status">
          {announce}
        </p>
      </div>
    </WicketCtx.Provider>
  );
}

export default Wicket;

"use client";

import { motion, type HTMLMotionProps, type Variants } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface TallyProps
  extends Omit<HTMLMotionProps<"span">, "children" | "initial" | "whileInView" | "viewport" | "transition"> {
  /** The number counted up (or down) to. */
  value: number;
  /** Starting value each digit drum spins up (or down) from. @default 0 */
  start?: number;
  /** Decimal places to show. @default 0 */
  decimals?: number;
  /** BCP 47 locale passed to Intl.NumberFormat. @default "en-US" */
  locale?: string;
  /** Extra Intl.NumberFormat options, e.g. `{ style: "currency", currency: "USD" }`. */
  formatOptions?: Intl.NumberFormatOptions;
  /** Seconds each digit drum takes to settle. @default 1.4 */
  duration?: number;
  /** Seconds between each digit's settle, tail to head. @default 0.06 */
  stagger?: number;
  /** Seconds before the count-up starts. */
  delay?: number;
  /** Re-run every time the number re-enters the viewport (default: once). */
  repeat?: boolean;
  /** Color the digits settle to. @default "#ffffff" */
  color?: string;
  /** Hex hue of the entry cast, bloom, backlight and baseline glint. @default "#93c5fd" (cool white-blue) */
  tint?: string;
  /** Bloom on each drum plus the breathing backlight (and the static halo under reduced motion). Turn off for small, dense, or colored-chip readouts. @default true */
  glow?: boolean;
  /** The glint that sweeps the baseline as the value settles (a static rule under reduced motion). @default true */
  glint?: boolean;
  /** Cylinder shading over each drum face. Turn off on solid color fills (badges, chips), where it reads as a grey box. @default true */
  shade?: boolean;
}

const DIGIT_ROWS = "0123456789".split("");

/** Default palette: a cool white-blue cast (blue-200) over a blue-300 glow. */
const DEFAULT_CAST = "191,219,254";
const DEFAULT_GLOW = "147,197,253";

/** "r,g,b" for a #rgb / #rrggbb hex, or null if it can't be parsed. */
function rgbOf(hex: string | undefined): string | null {
  if (!hex) return null;
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return null;
  const h = m[1].length === 3 ? [...m[1]].map((c) => c + c).join("") : m[1];
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)).join(",");
}

/** Vertical cylinder shading painted over each drum face: dark at the top and
 *  bottom of the slot with a faint specular band above centre. Over the dark
 *  stage the dark stops vanish; over the bright digit they carve a curved,
 *  machined drum surface behind the slot. Slate-tinted so the shade stays cool. */
const DRUM_FACE =
  "linear-gradient(to bottom," +
  "rgba(2,6,23,0.55) 0%," +
  "rgba(2,6,23,0) 26%," +
  "rgba(255,255,255,0.05) 43%," +
  "rgba(2,6,23,0) 60%," +
  "rgba(2,6,23,0.6) 100%)";

/** Soft top/bottom fade so digits read as emerging from behind a slot lip
 *  (and incoming/outgoing digits dissolve at the slot edges as the drum turns). */
const SLOT_MASK = "linear-gradient(to bottom, transparent 0%, #000 11%, #000 89%, transparent 100%)";

function formatValue(
  value: number,
  decimals: number,
  locale: string | undefined,
  options?: Intl.NumberFormatOptions
): string {
  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
    ...options,
  }).format(value);
}

/**
 * Tally — a count-up number built from odometer-style digit drums. Each drum
 * enters carrying a cool white-blue cast and a soft bloom, then springs to its
 * seated digit and cools to white — the leading drum flaring brightest as it
 * seats. A vertical cylinder-shade and a slot fade give every drum physical
 * depth behind its window, a low backlight breathes under the readout, and a
 * glow sweep races along the baseline the instant the value settles. Falls back
 * to the correct static number (softly backlit, faint rest glow) under reduced
 * motion.
 */
export function Tally({
  value,
  start = 0,
  decimals = 0,
  locale = "en-US",
  formatOptions,
  duration = 1.4,
  stagger = 0.06,
  delay = 0,
  repeat = false,
  color = "#ffffff",
  tint,
  glow = true,
  glint = true,
  shade = true,
  className,
  ...props
}: TallyProps) {
  const reducedMotion = useReducedMotion();
  const tintRgb = rgbOf(tint);
  const castRgb = tintRgb ?? DEFAULT_CAST;
  const glowRgb = tintRgb ?? DEFAULT_GLOW;
  const CAST = `rgb(${castRgb})`;
  const cast = (a: number) => `rgba(${castRgb},${a})`;
  const halo = (a: number) => `rgba(${glowRgb},${a})`;
  const noBloom = "drop-shadow(0 0 0px rgba(0,0,0,0))";
  const targetStr = React.useMemo(
    () => formatValue(value, decimals, locale, formatOptions),
    [value, decimals, locale, formatOptions]
  );
  const chars = React.useMemo(() => [...targetStr], [targetStr]);
  const totalDigits = React.useMemo(() => (targetStr.match(/[0-9]/g) ?? []).length, [targetStr]);
  // Right-aligned so each drum starts on the matching digit of `start` (or "0" beyond its length).
  const startDigitsFromEnd = React.useMemo(() => {
    const startStr = formatValue(start, decimals, locale, formatOptions);
    return (startStr.match(/[0-9]/g) ?? []).reverse();
  }, [start, decimals, locale, formatOptions]);

  if (reducedMotion) {
    return (
      <motion.span
        data-crucible="tally"
        role="img"
        className={cn("relative isolate inline-flex items-baseline tabular-nums", className)}
        aria-label={targetStr}
        {...props}
      >
        {glow && (
          <span
            aria-hidden
            className="pointer-events-none absolute left-1/2 top-1/2 -z-10 h-[150%] w-[130%] -translate-x-1/2 -translate-y-1/2 rounded-full"
            style={{
              background: `radial-gradient(ellipse at center, ${halo(0.12)}, ${halo(0)} 70%)`,
              filter: "blur(6px)",
            }}
          />
        )}
        <span aria-hidden style={{ color, textShadow: glow ? `0 0 8px ${cast(0.14)}` : undefined }}>
          {targetStr}
        </span>
        {glint && (
          <span
            aria-hidden
            className="pointer-events-none absolute -bottom-1 left-0 h-[2px] w-full rounded-full"
            style={{
              background: `linear-gradient(90deg, transparent, ${cast(0.5)}, transparent)`,
              boxShadow: `0 0 8px ${halo(0.3)}`,
            }}
          />
        )}
      </motion.span>
    );
  }

  type DrumCustom = { digit: number; startDigit: number; isLead: boolean };

  // Bloom lives on a non-clipping wrapper so the drop-shadow escapes the slot
  // clip. Lead digit flares brightest right as it seats, then cools to a faint
  // resting halo; supporting digits swell more gently.
  const bloomVariants: Variants = glow
    ? {
        hidden: { filter: `drop-shadow(0 0 9px ${halo(0.5)})` },
        visible: (custom: DrumCustom) => ({
          filter: custom.isLead
            ? [`drop-shadow(0 0 9px ${halo(0.5)})`, `drop-shadow(0 0 20px ${cast(0.95)})`, `drop-shadow(0 0 6px ${cast(0.12)})`]
            : [`drop-shadow(0 0 9px ${halo(0.45)})`, `drop-shadow(0 0 11px ${cast(0.5)})`, `drop-shadow(0 0 5px ${cast(0.1)})`],
          transition: { duration, ease: "easeOut", times: custom.isLead ? [0, 0.85, 1] : [0, 0.55, 1] },
        }),
      }
    : { hidden: { filter: noBloom }, visible: { filter: noBloom } };

  const drumVariants: Variants = {
    hidden: (custom: DrumCustom) => ({ y: `-${custom.startDigit}em`, color: CAST }),
    visible: (custom: DrumCustom) => ({
      y: `-${custom.digit}em`,
      color,
      transition: {
        // Spring the reel so it overshoots a hair and settles — the drum's over-roll.
        y: { type: "spring", duration, bounce: 0.2 },
        color: { duration: duration * 0.75, ease: "easeOut" },
      },
    }),
  };

  const glyphVariants: Variants = {
    hidden: { opacity: 0, y: "0.25em", color: CAST },
    visible: {
      opacity: 1,
      y: "0em",
      color,
      transition: { duration: duration * 0.45, ease: "easeOut" },
    },
  };

  // A bright hotspot sweeping across a mostly-transparent bar: a glint racing
  // the baseline, not a flat line. Fades in as it enters, out as it leaves.
  const underlineVariants: Variants = {
    hidden: { opacity: 0, backgroundPositionX: "120%" },
    visible: {
      opacity: [0, 1, 1, 0],
      backgroundPositionX: ["120%", "-20%"],
      transition: {
        delay: duration * 0.82,
        duration: 0.8,
        ease: "easeOut",
        opacity: { delay: duration * 0.82, duration: 0.8, times: [0, 0.18, 0.6, 1] },
      },
    },
  };

  return (
    <motion.span
      data-crucible="tally"
      role="img"
      className={cn("relative isolate inline-flex items-baseline tabular-nums", className)}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: !repeat, amount: 0.6 }}
      transition={{ staggerChildren: stagger, delayChildren: delay }}
      aria-label={targetStr}
      {...props}
    >
      <style>{`
        @keyframes crucible-tally-breathe {
          0%, 100% { opacity: 0.32; transform: translate(-50%, -50%) scale(0.96); }
          50% { opacity: 0.68; transform: translate(-50%, -50%) scale(1.05); }
        }
        [data-crucible="tally"] .tally-backlight {
          animation: crucible-tally-breathe 6s ease-in-out infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          [data-crucible="tally"] .tally-backlight { animation: none; opacity: 0.4; }
        }
      `}</style>

      {/* Idle life: a low backlight that breathes under the readout. */}
      {glow && (
        <span
          aria-hidden
          className="tally-backlight pointer-events-none absolute left-1/2 top-1/2 -z-10 h-[150%] w-[130%] -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{
            background: `radial-gradient(ellipse at center, ${halo(0.16)}, ${halo(0)} 70%)`,
            filter: "blur(6px)",
          }}
        />
      )}

      {(() => {
        let digitsSeen = 0;
        return chars.map((char, i) => {
          const digit = Number(char);
          const isDigit = /[0-9]/.test(char) && !Number.isNaN(digit);
          if (!isDigit) {
            return (
              <motion.span key={i} aria-hidden variants={glyphVariants} className="inline-block">
                {char}
              </motion.span>
            );
          }
          const distanceFromEnd = totalDigits - digitsSeen - 1;
          const isLead = digitsSeen === 0;
          digitsSeen += 1;
          const startDigit = Number(startDigitsFromEnd[distanceFromEnd] ?? "0");
          const custom: DrumCustom = { digit, startDigit, isLead };
          return (
            // Outer wrapper carries the bloom: it has no clip/mask, so the
            // drop-shadow glow spreads freely past the slot.
            <motion.span
              key={i}
              aria-hidden
              custom={custom}
              variants={bloomVariants}
              className="inline-block align-baseline will-change-[filter]"
            >
              <span
                // clip-path (not overflow:hidden) clips the reel: overflow other
                // than visible re-baselines an inline-block to its bottom margin
                // edge, floating digits ~0.2em above sibling "$"/","/"." glyphs.
                // The invisible in-flow strut supplies the true text baseline
                // (and the digit's natural width), and lineHeight:1em sizes the
                // cell to exactly one reel row so neighbors never peek through.
                // The mask fades the slot lips for drum depth.
                className="relative inline-block align-baseline"
                style={{
                  lineHeight: "1em",
                  clipPath: "inset(0)",
                  maskImage: SLOT_MASK,
                  WebkitMaskImage: SLOT_MASK,
                }}
              >
                <span className="invisible">{char}</span>
                <motion.span
                  custom={custom}
                  variants={drumVariants}
                  className="absolute inset-x-0 top-0 flex flex-col items-center will-change-transform"
                >
                  {DIGIT_ROWS.map((d) => (
                    <span key={d} className="block text-center" style={{ height: "1em", lineHeight: "1em" }}>
                      {d}
                    </span>
                  ))}
                </motion.span>
                {/* Cylinder shade over the drum face: machined depth behind the slot. */}
                {shade && (
                  <span
                    aria-hidden
                    className="pointer-events-none absolute inset-0"
                    style={{ background: DRUM_FACE }}
                  />
                )}
              </span>
            </motion.span>
          );
        });
      })()}

      {glint && (
        <motion.span
          aria-hidden
          variants={underlineVariants}
          className="pointer-events-none absolute -bottom-1 left-0 h-[2px] w-full rounded-full"
          style={{
            background: `linear-gradient(90deg, transparent 0%, transparent 38%, ${cast(0.95)} 50%, transparent 62%, transparent 100%)`,
            backgroundSize: "250% 100%",
            boxShadow: `0 0 10px ${halo(0.5)}`,
          }}
        />
      )}
    </motion.span>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

export interface WinnowProps
  extends Omit<
    React.ComponentPropsWithoutRef<"input">,
    "value" | "defaultValue" | "onChange" | "onSubmit" | "color" | "size"
  > {
  /** Controlled value. Omit for uncontrolled use (see `defaultValue`). */
  value?: string;
  /** Initial value when uncontrolled. @default "" */
  defaultValue?: string;
  /** Fires on every keystroke with the current string value. */
  onChange?: (value: string) => void;
  /**
   * Fires on genuine submit (Enter or the submit button) with the field value
   * BEFORE it is cleared — the vanish is purely decorative over this call.
   */
  onSubmit?: (value: string) => void;
  /**
   * Rotating placeholder suggestions. Each slides up and out as the next
   * arrives while the field is empty. @default a few search prompts
   */
  placeholders?: string[];
  /** Milliseconds each placeholder is shown before cycling. @default 2800 */
  cycleInterval?: number;
  /** Base grain size in px (each grain jitters around it). @default 1.7 */
  particleSize?: number;
  /** Grain density multiplier — higher packs more, finer grains. @default 1 */
  density?: number;
  /** Base scatter speed in px/frame at 60fps. @default 3.4 */
  scatterVelocity?: number;
  /**
   * Scatter direction in degrees. 0 = straight right, negative = upward.
   * Grains blow off along this heading before gravity takes over. @default -14
   */
  scatterDirection?: number;
  /** Downward acceleration applied to freed grains per frame. @default 0.09 */
  gravity?: number;
  /** Seconds a single grain takes to scatter and fade. @default 0.9 */
  dissolveDuration?: number;
  /** Clear the field on submit (via the dissolve). @default true */
  submitClears?: boolean;
  /**
   * Grain palette, assigned per grain. Keep it a narrow near-white ramp —
   * the vanish should read as fine sand, not confetti. @default soft whites
   */
  colors?: string[];
  /** The single cool accent for the focus underline. @default sky */
  accent?: string;
  /** Error state — reddens the underline and sets aria-invalid. @default false */
  error?: boolean;
  /** Freeze the placeholder cycle and skip the dissolve (submit clears instantly). @default false */
  paused?: boolean;
  /** Deterministic seed for grain jitter. @default 7 */
  seed?: number;
  className?: string;
}

/** Fine near-white grains — a narrow neutral ramp, never multicolor. */
const DEFAULT_COLORS = ["#fafafa", "#e5e5e5", "#d4d4d4", "#a3a3a3"];
const DEFAULT_ACCENT = "#38bdf8";
const ERROR_COLOR = "#f87171";
const DEFAULT_PLACEHOLDERS = [
  "Search components…",
  "Try a background",
  "Find a loader",
  "What are you building?",
];

const MAX_PARTICLES = 6000;

/** Deterministic mulberry32 PRNG — same seed always casts the same grains. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Grains {
  count: number;
  x: Float32Array;
  y: Float32Array;
  hx: Float32Array; // home — where the grain rests as crisp glyph
  hy: Float32Array;
  vx: Float32Array;
  vy: Float32Array;
  size: Float32Array;
  release: Float32Array; // seconds before this grain is set free (the pour)
  released: Uint8Array;
  colorIndex: Uint8Array;
}

/**
 * Winnow — a search input whose empty placeholder cycles (each sliding up as
 * the next arrives), and whose typed characters, on submit, rasterize into
 * fine grains that pour off left-to-right and blow away under a slight gravity
 * bias, clearing the field. The submit is genuine: `onSubmit` fires with the
 * value BEFORE the dissolve. A hairline underline draws in from center like a
 * filled gauge and brightens to one cool accent on focus. The scatter canvas
 * mounts only during the brief dissolve and tears down after — no rAF at rest.
 * Reduced motion crossfades placeholders and clears the field instantly with
 * no particles.
 */
export function Winnow({
  value,
  defaultValue = "",
  onChange,
  onSubmit,
  placeholders = DEFAULT_PLACEHOLDERS,
  cycleInterval = 2800,
  particleSize = 1.7,
  density = 1,
  scatterVelocity = 3.4,
  scatterDirection = -14,
  gravity = 0.09,
  dissolveDuration = 0.9,
  submitClears = true,
  colors = DEFAULT_COLORS,
  accent = DEFAULT_ACCENT,
  error = false,
  paused = false,
  seed = 7,
  disabled,
  className,
  onFocus,
  onBlur,
  ...rest
}: WinnowProps) {
  const reducedMotion = useReducedMotion();

  const wrapperRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);

  const grainsRef = React.useRef<Grains | null>(null);
  const rafRef = React.useRef(0);
  const elapsedRef = React.useRef(0);
  const lastRef = React.useRef(0);

  const [index, setIndex] = React.useState(0);
  const [focused, setFocused] = React.useState(false);
  const [dissolving, setDissolving] = React.useState(false);
  const [internal, setInternal] = React.useState(defaultValue);

  const isControlled = value !== undefined;
  const currentValue = isControlled ? value : internal;

  const palette = React.useMemo(
    () => (colors.length ? colors : DEFAULT_COLORS),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [colors.join(",")]
  );
  const prompts = React.useMemo(
    () => (placeholders.length ? placeholders : DEFAULT_PLACEHOLDERS),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [placeholders.join("�")]
  );

  const setValue = React.useCallback(
    (next: string) => {
      if (!isControlled) setInternal(next);
      onChange?.(next);
    },
    [isControlled, onChange]
  );

  // Placeholder cycle — advances only while empty and not paused, and never
  // when the tab is hidden. Never runs at rest cost; a single interval.
  React.useEffect(() => {
    if (paused || disabled) return;
    if (currentValue !== "") return;
    if (prompts.length <= 1) return;
    const id = window.setInterval(() => {
      if (typeof document !== "undefined" && document.hidden) return;
      setIndex((i) => (i + 1) % prompts.length);
    }, Math.max(cycleInterval, 400));
    return () => window.clearInterval(id);
  }, [paused, disabled, currentValue, prompts, cycleInterval]);

  const teardown = React.useCallback(() => {
    cancelAnimationFrame(rafRef.current);
    rafRef.current = 0;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (canvas && ctx) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      canvas.style.opacity = "0";
    }
    grainsRef.current = null;
    setDissolving(false);
  }, []);

  // Cancel any in-flight dissolve on unmount — no dangling rAF.
  React.useEffect(() => teardown, [teardown]);

  const startDissolve = React.useCallback(
    (text: string): boolean => {
      const wrapper = wrapperRef.current;
      const input = inputRef.current;
      const canvas = canvasRef.current;
      if (!wrapper || !input || !canvas) return false;

      const W = wrapper.clientWidth;
      const H = wrapper.clientHeight;
      if (W < 2 || H < 2) return false;

      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (!ctx) return false;

      const cs = getComputedStyle(input);
      const font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
      const padL = parseFloat(cs.paddingLeft) || 0;
      // Account for horizontal scroll when the text overflows the field.
      const textX = input.offsetLeft + padL - input.scrollLeft;
      const textY = input.offsetTop + input.clientHeight / 2;

      const dpr = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, 2);
      canvas.width = Math.round(W * dpr);
      canvas.height = Math.round(H * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      // Rasterize the typed text at the input's exact glyph position.
      ctx.font = font;
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";
      ctx.fillStyle = "#fff";
      ctx.clearRect(0, 0, W, H);
      // Clip to the input's text box so overflowed glyphs don't spill out.
      ctx.save();
      ctx.beginPath();
      ctx.rect(
        input.offsetLeft + padL,
        input.offsetTop,
        Math.max(0, input.clientWidth - padL - (parseFloat(cs.paddingRight) || 0)),
        input.clientHeight
      );
      ctx.clip();
      ctx.fillText(text, textX, textY);
      ctx.restore();

      const img = ctx.getImageData(0, 0, Math.round(W * dpr), Math.round(H * dpr)).data;
      const iw = Math.round(W * dpr);
      const ih = Math.round(H * dpr);
      const step = Math.max(1, Math.round((2.6 / Math.max(density, 0.2)) * dpr));

      // Collect solid cells (in device px), tracking horizontal extent so the
      // pour can be staggered left-to-right.
      const cells: number[] = [];
      let minX = Infinity;
      let maxX = -Infinity;
      for (let py = 0; py < ih; py += step) {
        for (let px = 0; px < iw; px += step) {
          if (img[(py * iw + px) * 4 + 3] > 130) {
            cells.push(px, py);
            if (px < minX) minX = px;
            if (px > maxX) maxX = px;
          }
        }
      }
      let total = cells.length / 2;
      if (total === 0) return false;

      const stride = total > MAX_PARTICLES ? Math.ceil(total / MAX_PARTICLES) : 1;
      total = Math.floor(total / stride);
      if (total === 0) return false;

      const rand = mulberry32((seed >>> 0) + text.length * 97 + 1);
      const spanX = Math.max(maxX - minX, 1);
      const stagger = dissolveDuration * 0.55;
      const dir = (scatterDirection * Math.PI) / 180;

      const g: Grains = {
        count: total,
        x: new Float32Array(total),
        y: new Float32Array(total),
        hx: new Float32Array(total),
        hy: new Float32Array(total),
        vx: new Float32Array(total),
        vy: new Float32Array(total),
        size: new Float32Array(total),
        release: new Float32Array(total),
        released: new Uint8Array(total),
        colorIndex: new Uint8Array(total),
      };
      for (let i = 0; i < total; i++) {
        const src = i * stride * 2;
        const cx = cells[src] / dpr;
        const cy = cells[src + 1] / dpr;
        g.hx[i] = cx + ((rand() - 0.5) * step) / dpr;
        g.hy[i] = cy + ((rand() - 0.5) * step) / dpr;
        g.x[i] = g.hx[i];
        g.y[i] = g.hy[i];
        g.size[i] = Math.max(particleSize * (0.6 + rand() * 0.9), 0.5);
        g.colorIndex[i] = Math.floor(rand() * palette.length);
        const norm = (cells[src] - minX) / spanX; // 0 at left edge → 1 at right
        g.release[i] = norm * stagger + rand() * 0.06;
      }
      grainsRef.current = g;

      const dur = Math.max(dissolveDuration, 0.15);
      canvas.style.opacity = "1";
      elapsedRef.current = 0;
      lastRef.current = performance.now();

      const loop = (now: number) => {
        const grains = grainsRef.current;
        if (!grains) return;
        const dt = Math.min((now - lastRef.current) / 1000, 0.05);
        lastRef.current = now;
        elapsedRef.current += dt;
        const elapsed = elapsedRef.current;
        const f = dt * 60;
        const drag = Math.pow(0.985, f);

        ctx.clearRect(0, 0, W, H);
        let alive = false;
        let currentColor = -1;
        for (let i = 0; i < grains.count; i++) {
          const rel = grains.release[i];
          if (elapsed < rel) {
            // Not yet poured — still part of the crisp word.
            alive = true;
            const c = grains.colorIndex[i];
            if (c !== currentColor) {
              currentColor = c;
              ctx.fillStyle = palette[c] ?? palette[0];
            }
            ctx.globalAlpha = 1;
            const s = grains.size[i];
            ctx.fillRect(grains.hx[i] - s / 2, grains.hy[i] - s / 2, s, s);
            continue;
          }
          const local = elapsed - rel;
          const life = local / dur;
          if (life >= 1) continue; // gone
          alive = true;

          if (!grains.released[i]) {
            grains.released[i] = 1;
            // Deterministic per-grain angle + speed jitter around the heading
            // so the pour reads as loose sand, not a rigid sheet.
            const jitter = (((i * 2654435761) >>> 0) / 4294967296 - 0.5) * 0.9;
            const speed = scatterVelocity * (0.55 + (((i * 40503) >>> 0) % 1000) / 1000);
            grains.vx[i] = Math.cos(dir + jitter) * speed;
            grains.vy[i] = Math.sin(dir + jitter) * speed;
          }

          grains.vy[i] += gravity * f;
          grains.vx[i] *= drag;
          grains.vy[i] *= drag;
          grains.x[i] += grains.vx[i] * f;
          grains.y[i] += grains.vy[i] * f;

          const c = grains.colorIndex[i];
          if (c !== currentColor) {
            currentColor = c;
            ctx.fillStyle = palette[c] ?? palette[0];
          }
          ctx.globalAlpha = Math.max(0, 1 - life * life);
          const s = grains.size[i];
          ctx.fillRect(grains.x[i] - s / 2, grains.y[i] - s / 2, s, s);
        }
        ctx.globalAlpha = 1;

        if (!alive) {
          teardown();
          return;
        }
        rafRef.current = requestAnimationFrame(loop);
      };

      cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(loop);
      return true;
    },
    [density, dissolveDuration, gravity, palette, particleSize, scatterDirection, scatterVelocity, seed, teardown]
  );

  const handleSubmit = React.useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      if (disabled) return;
      const submitted = currentValue;
      onSubmit?.(submitted);

      if (!submitClears || submitted === "") return;

      if (reducedMotion || paused) {
        setValue("");
        return;
      }
      // Fire the dissolve on the captured text, then clear the field. The
      // canvas keeps painting the vanishing glyphs while the input goes empty.
      const started = startDissolve(submitted);
      if (started) setDissolving(true);
      setValue("");
    },
    [currentValue, disabled, onSubmit, paused, reducedMotion, setValue, startDissolve, submitClears]
  );

  const accentColor = error ? ERROR_COLOR : accent;
  const gaugeActive = focused || error;
  const showPlaceholder = currentValue === "" && !dissolving;

  return (
    <form
      role="search"
      onSubmit={handleSubmit}
      className={cn("w-full max-w-md", className)}
      data-crucible="winnow"
    >
      <div
        ref={wrapperRef}
        className={cn(
          "relative flex items-center",
          disabled && "opacity-50"
        )}
      >
        {/* The vanishing glyph canvas — mounted always but painted (and rAF-driven)
            only during the brief dissolve, then cleared. Purely decorative. */}
        <canvas
          ref={canvasRef}
          aria-hidden
          className="pointer-events-none absolute inset-0 h-full w-full opacity-0"
        />

        {/* Rotating placeholder overlay. Real placeholder text is transparent
            (kept for accessible name / autofill); this is the visible one. */}
        {showPlaceholder && (
          <div
            aria-hidden
            className="pointer-events-none absolute inset-y-0 left-1 right-10 flex items-center overflow-hidden"
          >
            <AnimatePresence initial={false} mode="popLayout">
              <motion.span
                key={index}
                className="block truncate text-base text-neutral-500"
                initial={reducedMotion ? { opacity: 0 } : { y: "0.9em", opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={reducedMotion ? { opacity: 0 } : { y: "-0.9em", opacity: 0 }}
                transition={
                  reducedMotion
                    ? { duration: 0.2 }
                    : { type: "spring", stiffness: 320, damping: 32 }
                }
              >
                {prompts[index % prompts.length]}
              </motion.span>
            </AnimatePresence>
          </div>
        )}

        <input
          ref={inputRef}
          type="text"
          value={currentValue}
          disabled={disabled}
          aria-invalid={error || undefined}
          onChange={(event) => setValue(event.target.value)}
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          className={cn(
            "w-full appearance-none bg-transparent px-1 py-3 pr-10 text-base text-neutral-100",
            "outline-none placeholder:text-transparent",
            "disabled:cursor-not-allowed"
          )}
          {...rest}
          placeholder={prompts[0]}
        />

        {/* Submit affordance for pointer users; Enter submits the form too. */}
        <button
          type="submit"
          disabled={disabled || currentValue === ""}
          aria-label="Submit"
          className={cn(
            "absolute right-0 top-1/2 -translate-y-1/2 flex h-8 w-8 items-center justify-center rounded-md",
            "text-neutral-500 transition-colors duration-200",
            "hover:text-neutral-200 disabled:pointer-events-none disabled:opacity-40",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-neutral-950"
          )}
          style={{ ["--tw-ring-color" as string]: accentColor }}
        >
          <svg
            aria-hidden
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
            className="h-4 w-4"
          >
            <path d="M5 12h14" />
            <path d="m13 6 6 6-6 6" />
          </svg>
        </button>

        {/* Hairline underline: a static dim base, plus an accent gauge that
            fills in from center on focus (or stays lit for the error state). */}
        <span
          aria-hidden
          className="pointer-events-none absolute inset-x-0 bottom-0 h-px bg-neutral-700"
        />
        <span
          aria-hidden
          className={cn(
            "pointer-events-none absolute inset-x-0 bottom-0 h-[1.5px] origin-center transition-transform ease-out",
            gaugeActive ? "scale-x-100" : "scale-x-0"
          )}
          style={{
            backgroundColor: accentColor,
            boxShadow: `0 0 8px ${accentColor}`,
            transitionDuration: reducedMotion ? "0ms" : "480ms",
          }}
        />
      </div>
    </form>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { useVisibilityPause } from "@/hooks/use-visibility-pause";

export interface WireItem {
  /** Small glyph rendered inside the accent chip (inline SVG works best). */
  icon?: React.ReactNode;
  /** Headline of the event — also used for the item's aria-label. */
  title: string;
  /** Secondary meta line under the title. */
  description?: string;
  /** Short timestamp string, e.g. "just now", "2m ago". */
  time?: string;
  /** Accent for this item's icon chip; falls back to the `colors` cycle. */
  accent?: string;
}

/** Imperative handle for live-push mode — see `WireProps.ref`. */
export interface WireHandle {
  /** Push a live item into the feed. Works alongside or instead of the loop. */
  push: (item: WireItem) => void;
}

export interface WireProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /**
   * Events the feed cycles through. The loop order is a seeded shuffle of this
   * array (deterministic per `seed`), so the cadence never reads scripted.
   * @default a built-in set of generic product events
   */
  items?: WireItem[];
  /** Mean seconds between inserts while looping. @default 2.4 */
  interval?: number;
  /**
   * Jitter applied to each gap as a fraction of `interval` (0 = metronomic,
   * 0.5 = gaps range ±50%). Seeded — the same rhythm every load. @default 0.35
   */
  jitter?: number;
  /** Where new entries land: "top" (news wire) or "bottom" (chat). @default "top" */
  direction?: "top" | "bottom";
  /** How many entries stay in the feed before the oldest retires. @default 4 */
  maxVisible?: number;
  /** Depth in px of the fade mask under which the oldest entry retires. @default 48 */
  fadeDepth?: number;
  /**
   * Spring for entry and the siblings' shuffle — one confident settle, no
   * bounce chain. @default { stiffness: 500, damping: 42 }
   */
  spring?: { stiffness?: number; damping?: number };
  /** Self-loop through `items`. Disable to drive the feed only via `ref.push()`. @default true */
  loop?: boolean;
  /** Pause the loop while the pointer is over the feed. @default true */
  hoverPause?: boolean;
  /**
   * Accent cycle for icon chips (per-item `accent` wins). Accents stay confined
   * to the chip — cards remain neutral. @default ["#fbbf24"]
   */
  colors?: string[];
  /** Seed for the shuffle order and interval jitter. @default 7 */
  seed?: number;
  /** Freeze the loop entirely. @default false */
  paused?: boolean;
  /** Imperative handle exposing `push(item)` for live-push mode. */
  ref?: React.Ref<WireHandle>;
}

/* ---------------------------------------------------------------- helpers */

/** Deterministic PRNG (mulberry32) — no Math.random anywhere. */
function mulberry32(seed: number): () => number {
  let t = seed >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) | 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/** Seeded Fisher–Yates over item indices — the loop's deterministic order. */
function seededOrder(length: number, seed: number): number[] {
  const rand = mulberry32(seed);
  const order = Array.from({ length }, (_, i) => i);
  for (let i = length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  return order;
}

function Glyph({ d }: { d: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      className="h-4 w-4"
      aria-hidden
    >
      <path d={d} />
    </svg>
  );
}

const DEFAULT_ITEMS: WireItem[] = [
  {
    icon: <Glyph d="M15 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M8.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M19 8v6M16 11h6" />,
    title: "New signup",
    description: "A new account just joined",
    time: "just now",
  },
  {
    icon: <Glyph d="M2 9h20M5.5 4.5h13a3 3 0 0 1 3 3v9a3 3 0 0 1-3 3h-13a3 3 0 0 1-3-3v-9a3 3 0 0 1 3-3ZM6 15.5h4" />,
    title: "Payment received",
    description: "Invoice #1042 was settled",
    time: "1m ago",
  },
  {
    icon: <Glyph d="M12 3v12M7 10l5 5 5-5M4 21h16" />,
    title: "Report exported",
    description: "Monthly summary is ready",
    time: "3m ago",
  },
  {
    icon: <Glyph d="M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM8.5 12.5l2.5 2.5 5-5.5" />,
    title: "Deploy complete",
    description: "Version 2.4.1 is live",
    time: "6m ago",
  },
  {
    icon: <Glyph d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z" />,
    title: "New comment",
    description: "Someone replied to a thread",
    time: "9m ago",
  },
  {
    icon: <Glyph d="M13 2 3 14h7l-1 8 10-12h-7l1-8Z" />,
    title: "Milestone reached",
    description: "10k events processed",
    time: "12m ago",
  },
];

const DEFAULT_COLORS = ["#fbbf24"];

/** Minimum seconds between polite screen-reader announcements. */
const ANNOUNCE_GAP_MS = 4000;

type Entry = { key: number; item: WireItem };

/**
 * Wire — a self-running "live activity" feed for marketing pages. New entries
 * land with one confident spring while siblings shuffle down via layout
 * animation and the oldest retires under an edge fade; each fresh entry's
 * leading edge flashes a hairline brightness that cools within 400ms — freshly
 * printed. Loops a provided items array on seeded, jittered intervals (never
 * metronomic, deterministic per seed), or accepts live items through an
 * imperative `push` ref. Hover pauses the feed; the interval also suspends
 * offscreen and on hidden tabs. Cards stay neutral with hairline borders — the
 * per-item accent lives only in the icon chip. Reduced motion renders a static
 * list of the most recent items, and live pushes appear without motion.
 *
 * **Boundary with `dispatch`:** wire is the *decorative* counterpart — a
 * declarative, self-looping showcase with seeded fake data, no dismissal and
 * no imperative toast() API, built to run unattended in a hero. For real app
 * notifications (imperative `toast()`, receding stack, swipe-dismiss, promise
 * morphs, `role="status"`), use `dispatch` instead.
 */
export function Wire({
  items = DEFAULT_ITEMS,
  interval = 2.4,
  jitter = 0.35,
  direction = "top",
  maxVisible = 4,
  fadeDepth = 48,
  spring,
  loop = true,
  hoverPause = true,
  colors = DEFAULT_COLORS,
  seed = 7,
  paused = false,
  ref,
  className,
  onPointerEnter,
  onPointerLeave,
  ...props
}: WireProps) {
  const reducedMotion = useReducedMotion();
  const stiffness = spring?.stiffness ?? 500;
  const damping = spring?.damping ?? 42;

  const order = React.useMemo(() => seededOrder(items.length, seed), [items, seed]);

  // Prefill so the feed reads alive from the first paint: the last `maxVisible`
  // loop pushes, newest first. Deterministic (seeded) — SSR-safe.
  const prefill = React.useMemo<Entry[]>(() => {
    const count = Math.min(maxVisible, items.length);
    return order
      .slice(0, count)
      .map((itemIndex, i) => ({ key: i, item: items[itemIndex] }))
      .reverse();
  }, [order, items, maxVisible]);

  const [entries, setEntries] = React.useState<Entry[]>(prefill);
  const [announcement, setAnnouncement] = React.useState("");

  const seqRef = React.useRef(prefill.length);
  const cursorRef = React.useRef(prefill.length);
  const hoveredRef = React.useRef(false);
  const lastAnnounceRef = React.useRef(0);
  const prevElapsedRef = React.useRef(0);
  const countdownRef = React.useRef(interval);

  // Persistent jitter PRNG, distinct stream from the shuffle. Lazy ref init
  // keeps it deterministic and stable across renders.
  const jitterRandRef = React.useRef<(() => number) | null>(null);
  if (jitterRandRef.current === null) jitterRandRef.current = mulberry32(seed * 7919 + 1);

  // If items/seed/maxVisible change, restart from the new deterministic prefill.
  // (On mount `entries === prefill`, so React bails out — no extra render.)
  React.useEffect(() => {
    setEntries(prefill);
    seqRef.current = prefill.length;
    cursorRef.current = prefill.length;
  }, [prefill]);

  // A new seed also restarts the jitter stream, so the rhythm is deterministic
  // per seed (not just the order).
  const seedRef = React.useRef(seed);
  React.useEffect(() => {
    if (seedRef.current === seed) return;
    seedRef.current = seed;
    jitterRandRef.current = mulberry32(seed * 7919 + 1);
  }, [seed]);

  const pushItem = React.useCallback(
    (item: WireItem) => {
      const key = seqRef.current++;
      setEntries((prev) => [{ key, item }, ...prev].slice(0, maxVisible));
      // Polite announcements, throttled to sanity.
      const now = performance.now();
      if (now - lastAnnounceRef.current >= ANNOUNCE_GAP_MS) {
        lastAnnounceRef.current = now;
        setAnnouncement(`New activity: ${item.title}`);
      }
    },
    [maxVisible]
  );

  React.useImperativeHandle(ref, () => ({ push: pushItem }), [pushItem]);

  const advanceRef = React.useRef(() => {});
  advanceRef.current = () => {
    if (items.length === 0) return;
    const itemIndex = order[cursorRef.current % order.length];
    cursorRef.current++;
    pushItem(items[itemIndex]);
  };

  const jitterProps = React.useRef({ interval, jitter, hoverPause });
  jitterProps.current = { interval, jitter, hoverPause };

  // rAF-driven countdown: suspends offscreen and on hidden tabs via the hook,
  // and skips while hovered. dt-based so hook restarts (elapsed resets) are safe.
  const loopSuspended = paused || !loop || (reducedMotion && loop);
  const containerRef = useVisibilityPause<HTMLDivElement>(
    (elapsed) => {
      const prev = prevElapsedRef.current;
      const dt = elapsed >= prev ? elapsed - prev : elapsed;
      prevElapsedRef.current = elapsed;
      if (jitterProps.current.hoverPause && hoveredRef.current) return;
      countdownRef.current -= dt;
      if (countdownRef.current <= 0) {
        advanceRef.current();
        const { interval: base, jitter: j } = jitterProps.current;
        const rand = jitterRandRef.current!;
        countdownRef.current = Math.max(0.35, base * (1 + j * (rand() * 2 - 1)));
      }
    },
    { paused: loopSuspended }
  );

  const rendered = direction === "top" ? entries : [...entries].reverse();

  // no-repeat + explicit size: content past the box is masked out, so the
  // oldest entry retires under the fade and the entering card slips in from
  // under a shallow leading-edge fade instead of overhanging the feed.
  const mask =
    direction === "top"
      ? `linear-gradient(to bottom, transparent 0, #000 12px, #000 calc(100% - ${fadeDepth}px), transparent 100%)`
      : `linear-gradient(to top, transparent 0, #000 12px, #000 calc(100% - ${fadeDepth}px), transparent 100%)`;

  const enterY = direction === "top" ? -18 : 18;
  const exitY = direction === "top" ? 14 : -14;

  return (
    <div
      ref={containerRef}
      data-crucible="wire"
      className={cn("relative w-full max-w-sm", className)}
      onPointerEnter={(event) => {
        hoveredRef.current = true;
        onPointerEnter?.(event);
      }}
      onPointerLeave={(event) => {
        hoveredRef.current = false;
        onPointerLeave?.(event);
      }}
      {...props}
    >
      <div
        role="feed"
        aria-label="Activity feed"
        aria-busy={false}
        className="flex w-full flex-col gap-2.5"
        style={{
          maskImage: mask,
          WebkitMaskImage: mask,
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
          maskSize: "100% 100%",
          WebkitMaskSize: "100% 100%",
        }}
      >
        <AnimatePresence initial={false} mode="popLayout">
          {rendered.map(({ key, item }, i) => {
            const accent = item.accent ?? colors[key % Math.max(1, colors.length)] ?? DEFAULT_COLORS[0];
            return (
              <motion.article
                key={key}
                aria-label={item.title}
                aria-posinset={i + 1}
                aria-setsize={rendered.length}
                layout={!reducedMotion}
                initial={reducedMotion ? false : { opacity: 0, y: enterY, scale: 0.98 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={
                  reducedMotion
                    ? { opacity: 0, transition: { duration: 0 } }
                    : { opacity: 0, y: exitY, transition: { duration: 0.3, ease: "easeOut" } }
                }
                transition={
                  reducedMotion
                    ? { duration: 0 }
                    : {
                        // One confident spring — entry and sibling shuffle alike.
                        type: "spring",
                        stiffness,
                        damping,
                        opacity: { duration: 0.28, ease: "easeOut" },
                      }
                }
                className="relative flex w-full items-center gap-3 rounded-lg border border-white/[0.08] bg-white/[0.03] px-3.5 py-3"
              >
                {/* Freshly printed: the leading edge flashes a hairline that
                    cools within 400ms. Skipped for prefilled entries because
                    AnimatePresence mounts them with initial={false}. */}
                {!reducedMotion && (
                  <motion.span
                    aria-hidden
                    className="pointer-events-none absolute inset-x-3 top-0 h-px"
                    style={{
                      background:
                        "linear-gradient(90deg, transparent, rgba(255,255,255,0.85), transparent)",
                      boxShadow: "0 0 10px rgba(255,255,255,0.35)",
                    }}
                    initial={{ opacity: 1 }}
                    animate={{ opacity: 0 }}
                    transition={{ duration: 0.4, ease: "easeOut" }}
                  />
                )}
                <span
                  aria-hidden
                  className="flex h-9 w-9 shrink-0 items-center justify-center rounded-md border"
                  style={{
                    color: accent,
                    borderColor: `color-mix(in srgb, ${accent} 28%, transparent)`,
                    background: `color-mix(in srgb, ${accent} 12%, transparent)`,
                  }}
                >
                  {item.icon ?? <span className="h-1.5 w-1.5 rounded-full bg-current" />}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium text-neutral-100">{item.title}</span>
                  {item.description && (
                    <span className="mt-0.5 block truncate text-xs text-neutral-400">{item.description}</span>
                  )}
                </span>
                {item.time && (
                  <span className="shrink-0 self-start text-[10px] font-medium tabular-nums text-neutral-500">
                    {item.time}
                  </span>
                )}
              </motion.article>
            );
          })}
        </AnimatePresence>
      </div>
      <span className="sr-only" role="status" aria-live="polite">
        {announcement}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { OglCanvas } from "@/lib/ogl-canvas";

export interface UmbraProps extends React.ComponentPropsWithoutRef<"div"> {
  /**
   * `[undertone, crestLight]`. The undertone is the deep hue that breathes in
   * the folds (default black-violet); crestLight is the pale tint the fold
   * crests catch. Both stay whisper-subtle under the luminance cap.
   */
  colors?: [string, string];
  /** Animation speed multiplier. 1 = default drift + ~0.1 Hz breathing. */
  speed?: number;
  /** Field scale. 1 = default; higher packs more, smaller folds. */
  scale?: number;
  /** Domain-warp strength. 0 = straight ridges, 1 = default drape, up to 3. */
  warp?: number;
  /**
   * Hard ceiling on output luminance (0–1). The veil soft-clips beneath this
   * so overlay text always wins. Default 0.3 — raise with care.
   */
  luminanceCap?: number;
  /** Freeze the animation at its current frame. */
  paused?: boolean;
}

const DEFAULT_COLORS: [string, string] = [
  "#1f1133", // deep violet undertone — breathes in the folds
  "#c9bfe4", // pale lavender-gray — what the crests catch
];

/** Hex → [r,g,b] in 0–1. Accepts #rgb / #rrggbb. */
function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const int = parseInt(h, 16);
  if (Number.isNaN(int) || h.length !== 6) return [0.12, 0.07, 0.2];
  return [((int >> 16) & 255) / 255, ((int >> 8) & 255) / 255, (int & 255) / 255];
}

/**
 * Original "dark veil" fragment shader: domain-warped ridged fbm rendered
 * near-threshold. The ridge transform folds value noise into sharp crests;
 * a low-frequency warp field drapes them into organic folds. Only the crests
 * catch light — everything else falls to true black — and a deep undertone
 * breathes through them at ~0.1 Hz. Output is soft-clipped under uCap so the
 * veil can never compete with overlay text, and time-varying hash dither
 * defeats the banding that would otherwise be fatal at these luminances.
 * GLSL ES 1.00 (WebGL1/2 compatible).
 */
const FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uPointer; // managed by the harness; unused — the veil ignores the cursor

uniform vec3 uUndertone; // deep violet — breathes in the folds
uniform vec3 uCrest;     // pale light the crests catch
uniform float uSpeed;
uniform float uScale;
uniform float uWarp;
uniform float uCap;  // luminance ceiling
uniform float uSeed; // per-instance offset — desynchronizes multiple veils

// --- compact value noise (original) ---
float hash21(vec2 p) {
  p = fract(p * vec2(127.1, 311.7));
  p += dot(p, p + 34.23);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Plain fbm drives the warp field (soft billows, no ridges needed there).
float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 3; i++) {
    v += amp * vnoise(p);
    p = m * p;
    amp *= 0.5;
  }
  return v;
}

// Ridge transform: folds noise so its midline becomes a sharp crest.
float ridge(float n) {
  return 1.0 - abs(2.0 * n - 1.0);
}

// Ridged multifractal: each octave's detail is gated by the crest below it,
// so fine wrinkles live ON the folds instead of filling the hollows.
float rfbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  float carry = 1.0;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 4; i++) {
    float r = ridge(vnoise(p));
    r *= r; // sharpen the fold line
    v += amp * r * (0.35 + 0.65 * carry);
    carry = r;
    p = m * p;
    amp *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);

  // Field clock: glacial by design — a drape settling, not a fluid churning.
  float t = uTime * uSpeed * 0.035 + uSeed;

  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * (2.4 * uScale)
    + vec2(uSeed * 3.1, uSeed * -1.7);

  // Low-frequency warp field: two decorrelated fbm channels on their own
  // clocks bend the ridge domain into hanging, overlapping folds.
  vec2 q = vec2(
    fbm(p * 0.55 + t * vec2(0.7, 0.45)),
    fbm(p * 0.55 + vec2(4.7, 2.3) - t * vec2(0.4, 0.65))
  );
  vec2 wp = p + uWarp * 3.4 * (q - 0.5);

  float f = rfbm(wp + t * vec2(0.12, -0.08));

  // ~0.1 Hz breath on the REAL clock (2*pi*0.1 = 0.6283), phase-split per
  // instance so multiple veils on a page never inhale together.
  float br = 0.5 + 0.5 * sin(uTime * uSpeed * 0.6283 + uSeed * 6.2832);

  // Near-threshold crest window: only the fold tops catch light. Squared so
  // the transition tail dies into true black instead of lingering as haze.
  float crest = smoothstep(0.42, 0.85, f);
  crest *= crest;

  // Crest color drifts between undertone-violet and pale light with the
  // breath — the undertone literally breathes IN the crests.
  vec3 crestCol = mix(uUndertone * 1.8, uCrest, 0.30 + 0.35 * crest + 0.18 * br);
  vec3 col = crestCol * crest * (0.72 + 0.35 * br);

  // Barely-there ambient drape so the crests read as tops of a volume, not
  // floating filaments. Sits a breath above true black, breathing too.
  float body = smoothstep(0.10, 0.55, f);
  col += uUndertone * body * (0.16 + 0.10 * br);

  // Hard promise of the component: soft-clip asymptotically under uCap so
  // no crest, at any knob setting, can climb above the luminance ceiling.
  float cap = max(uCap, 0.001);
  col = cap * (vec3(1.0) - exp(-col * 2.4 / cap));

  // Faint vignette seats the veil behind content.
  vec2 vg = (uv - 0.5) * vec2(aspect, 1.0);
  col *= 1.0 - 0.35 * dot(vg, vg);

  // Time-varying hash dither — mandatory. At these luminances, 8-bit banding
  // is fatal; re-hashing per frame turns it into a filmic shimmer instead.
  float grain = hash21(gl_FragCoord.xy + fract(uTime * 0.31 + uSeed) * 149.0) - 0.5;
  col += grain * (2.0 / 255.0);

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
`;

/**
 * Umbra — a dark veil. Black-on-black volumetric drape: domain-warped ridged
 * fbm folds where only the crests catch a whisper of light and a deep violet
 * undertone breathes at ~0.1 Hz; everything else falls to true black. Output
 * luminance is hard-capped so overlay text always wins — the restraint is the
 * signature. Built on the `ogl-canvas` harness: GPU-light, offscreen-paused,
 * reduced-motion-safe. Position it inside any `relative` container; it fills
 * and sits behind content.
 */
export function Umbra({
  colors = DEFAULT_COLORS,
  speed = 1,
  scale = 1,
  warp = 1,
  luminanceCap = 0.3,
  paused = false,
  className,
  ...props
}: UmbraProps) {
  // Deterministic per-instance seed (SSR-safe — useId is stable across
  // server and client) so multiple veils on one page desynchronize.
  const id = React.useId();
  const seed = React.useMemo(() => {
    let h = 0;
    for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
    return (h % 1024) / 1024;
  }, [id]);

  const uniforms = React.useMemo(
    () => ({
      uUndertone: { value: hexToRgb(colors[0]) },
      uCrest: { value: hexToRgb(colors[1]) },
      uSpeed: { value: Math.max(speed, 0) },
      uScale: { value: Math.min(Math.max(scale, 0.2), 4) },
      uWarp: { value: Math.min(Math.max(warp, 0), 3) },
      uCap: { value: Math.min(Math.max(luminanceCap, 0.02), 1) },
      uSeed: { value: seed * 37.0 },
    }),
    [colors, speed, scale, warp, luminanceCap, seed]
  );

  return (
    <OglCanvas
      aria-hidden
      data-crucible="umbra"
      {...props}
      className={cn("absolute inset-0 -z-10", className)}
      fragment={FRAGMENT}
      uniforms={uniforms}
      paused={paused}
      reducedMotionTime={11}
    />
  );
}

